{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockDatabase = {
  students: [
    { id: 1, name: "John Doe", email: "john@example.com", grade: "10th" },
    { id: 2, name: "Jane Smith", email: "jane@example.com", grade: "11th" }
  ],

  getAllStudents: (): Promise<any[]> => {
    return Promise.resolve(mockDatabase.students);
  },

  getStudentById: (id: number): Promise<any | null> => {
    const student = mockDatabase.students.find(s => s.id === id) || null;
    return Promise.resolve(student);
  },

  createStudent: (studentData: any): Promise<any> => {
    const newStudent = {
      id: mockDatabase.students.length + 1,
      ...studentData
    };
    mockDatabase.students.push(newStudent);
    return Promise.resolve(newStudent);
  },

  updateStudent: (id: number, studentData: any): Promise<any | null> => {
    const index = mockDatabase.students.findIndex(s => s.id === id);
    if (index === -1) return Promise.resolve(null);

    mockDatabase.students[index] = { ...mockDatabase.students[index], ...studentData };
    return Promise.resolve(mockDatabase.students[index]);
  },

  deleteStudent: (id: number): Promise<boolean> => {
    const initialLength = mockDatabase.students.length;
    mockDatabase.students = mockDatabase.students.filter(s => s.id !== id);
    return Promise.resolve(mockDatabase.students.length < initialLength);
  }
};

// GET /students - List all students
router.get("/students", async (req: Request, res: Response) => {
  try {
    const students = await mockDatabase.getAllStudents();
    res.json(students);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch students" });
  }
});

// GET /students/:id - Get a specific student by ID
router.get("/students/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid student ID" });
    }

    const student = await mockDatabase.getStudentById(id);
    if (!student) {
      return res.status(404).json({ error: "Student not found" });
    }

    res.json(student);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch student" });
  }
});

// POST /students - Create a new student
router.post("/students", async (req: Request, res: Response) => {
  try {
    const { name, email, grade } = req.body;

    if (!name || !email || !grade) {
      return res.status(400).json({ error: "Name, email, and grade are required" });
    }

    const newStudent = await mockDatabase.createStudent({ name, email, grade });
    res.status(201).json(newStudent);
  } catch (error) {
    res.status(500).json({ error: "Failed to create student" });
  }
});

// PUT /students/:id - Update an existing student
router.put("/students/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid student ID" });
    }

    const { name, email, grade } = req.body;

    if (!name || !email || !grade) {
      return res.status(400).json({ error: "Name, email, and grade are required" });
    }

    const updatedStudent = await mockDatabase.updateStudent(id, { name, email, grade });

    if (!updatedStudent) {
      return res.status(404).json({ error: "Student not found" });
    }

    res.json(updatedStudent);
  } catch (error) {
    res.status(500).json({ error: "Failed to update student" });
  }
});

// DELETE /students/:id - Delete a student
