{"code":"import type { Request, Response, NextFunction } from "express";
import { createHash, scrypt, randomBytes, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is designed to handle password hashing for user registration
  // It should only process POST requests to the /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  const password = req.body.password;

  // Generate salt
  const salt = randomBytes(16).toString("hex");

  // Hash password with salt
  scrypt(password, salt, 64, (err, derivedKey) => {
    if (err) {
      next(err);
      return;
    }

    // Store hashed password and salt in request body
    req.body.hashedPassword = derivedKey.toString("hex");
    req.body.salt = salt;

    next();
  });
}
"}

