{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("hotel-housekeeping.db");

interface Room {
  id: number;
  roomId: string;
  cleaningStatus: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS rooms (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    roomId TEXT NOT NULL UNIQUE,
    cleaningStatus TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllRooms(): Room[] {
  const stmt = db.prepare("SELECT * FROM rooms");
  return stmt.all() as unknown as Room[];
}

export function getRoomById(id: number): Room | undefined {
  const stmt = db.prepare("SELECT * FROM rooms WHERE id = ?");
  return stmt.get(id) as Room | undefined;
}

export function insertRoom(roomId: string, cleaningStatus: string): number {
  const stmt = db.prepare(
    "INSERT INTO rooms (roomId, cleaningStatus) VALUES (?, ?)"
  );
  const result = stmt.run(roomId, cleaningStatus);
  return Number(result.lastInsertRowid);
}

export function updateRoom(
  id: number,
  roomId: string,
  cleaningStatus: string
): void {
  const stmt = db.prepare(
    "UPDATE rooms SET roomId = ?, cleaningStatus = ? WHERE id = ?"
  );
  stmt.run(roomId, cleaningStatus, id);
}

export function deleteRoom(id: number): void {
  const stmt = db.prepare("DELETE FROM rooms WHERE id = ?");
  stmt.run(id);
}

// Seed data
if (getAllRooms().length === 0) {
  insertRoom("101", "Dirty");
  insertRoom("102", "Clean");
  insertRoom("103", "In Progress");
  insertRoom("104", "Dirty");
  insertRoom("105", "Clean");
}
"}

{"code":"import { useEffect, useState } from "react";

interface ScheduledPost {
  id: string;
  title: string;
  content: string;
  scheduledTime: string;
  status: "scheduled" | "published" | "failed";
}

export function PostList() {
  const [posts, setPosts] = useState<ScheduledPost[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [filterStatus, setFilterStatus] = useState<"all" | "scheduled" | "published" | "failed">("all");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    fetchPosts();
  }, []);

  const fetchPosts = async () => {
    try {
      setLoading(true);
      // In a real app, this would be an API call
      // const response = await fetch('/api/posts');
      // const data = await response.json();

      // Mock data for demonstration
      const mockData: ScheduledPost[] = [
        {
          id: "1",
          title: "My First Post",
          content: "This is the content of my first post.",
          scheduledTime: "2023-06-15T10:00:00Z",
          status: "scheduled"
        },
        {
          id: "2",
          title: "Another Post",
          content: "Content for another post.",
          scheduledTime: "2023-06-16T14:30:00Z",
          status: "published"
        },
        {
          id: "3",
          title: "Third Post",
          content: "Yet another post content.",
          scheduledTime: "2023-06-17T09:15:00Z",
          status: "failed"
        }
      ];

      setPosts(mockData);
      setError("");
    } catch (err) {
      setError("Failed to load posts");
    } finally {
      setLoading(false);
    }
  };

  const filteredPosts = posts.filter(post => {
    const matchesSearch = post.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          post.content.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesFilter = filterStatus === "all" || post.status === filterStatus;
    return matchesSearch && matchesFilter;
  });

  const handleDelete = async (id: string) => {
    try {
      // In a real app, this would be an API call
      // const response = await fetch(`/api/posts/${id}`, { method: 'DELETE' });

      // Mock delete operation
      setPosts(posts.filter(post => post.id !== id));
    } catch (err) {
      setError("Failed to delete post");
    }
  };

  const handlePublish = async (id: string) => {
    try {
      // In a real app, this would be an API call
      // const response = await fetch(`/api/posts/${id}/publish`, { method: 'POST' });

      // Mock publish operation
      setPosts(posts.map(post => 
        post.id === id ? { ...post, status: "published" } : post
      ));
    } catch (err) {
      setError("Failed to publish post");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Scheduled Posts</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search posts..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        />

        <select
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value as any)}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="all">All Statuses</option>
          <option value="scheduled">Scheduled</option>
          <option value="published">Published</option>
          <option value="failed">Failed</option>
        </select>
      </div>

      {filteredPosts.length === 0 ? (
        <div style={{ textAlign: "center", padding: "20px" }}>
          {searchTerm || filterStatus !== "all" ? 
