                                    post.status === "published" ? "#d4edda" : 
                                    "#f8d7da",
                      color: post.status === "scheduled" ? "#856404" : 
                           post.status === "published" ? "#155724" : 
                           "#721c24"
                    }}
                  >
                    {post.status.charAt(0).toUpperCase() + post.status.slice(1)}
                  </span>
                </div>
                <div style={{ display: "flex", gap: "5px", flexShrink: 0 }}>
                  {post.status === "scheduled" && (
                    <button 
                      onClick={() => handlePublish(post.id)}
                      style={{ 
                        padding: "4px 8px", 
                        backgroundColor: "#28a745", 
                        color: "white", 
                        border: "none", 
                        borderRadius: "4px", 
                        cursor: "pointer"
                      }}
                    >
                      Publish
                    </button>
                  )}
                  <button 
                    onClick={() => handleDelete(post.id)}
                    style={{ 
                      padding: "4px 8px", 
                      backgroundColor: "#dc3545", 
                      color: "white", 
                      border: "none", 
                      borderRadius: "4px", 
                      cursor: "pointer"
                    }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
