{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes
const ACTIVE_SESSIONS = new Map<string, { expires: number }>();

function getSessionIdFromRequest(req: Request): string | null {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return null;
  }

  const token = authHeader.substring(7);
  return token;
}

function verifyTokenSignature(token: string): boolean {
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return false;
  }

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) {
      return false;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /appointments
  if (req.method !== "POST" || !req.path.startsWith("/appointments")) {
    next();
    return;
  }

  const sessionId = getSessionIdFromRequest(req);
  if (!sessionId) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const session = ACTIVE_SESSIONS.get(sessionId);
  if (!session) {
    res.status(401).json({ error: "Invalid session" });
    return;
  }

  if (Date.now() > session.expires) {
    ACTIVE_SESSIONS.delete(sessionId);
    res.status(401).json({ error: "Session expired" });
    return;
  }

  // Verify token signature
  if (!verifyTokenSignature(sessionId)) {
    ACTIVE_SESSIONS.delete(sessionId);
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // Refresh session timeout
  session.expires = Date.now() + SESSION_TIMEOUT;

  next();
}
