    `INSERT INTO users (email, password_hash, full_name, hourly_rate, timezone, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?, datetime('now'), datetime('now'))`
  );
  const result = stmt.run(email, passwordHash, fullName, hourlyRate, timezone);
