{"code":"import { useEffect, useState } from "react";

export function BillingSystem() {
  const [sessions, setSessions] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchSessions();
  }, []);

  const fetchSessions = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/sessions');
      if (!response.ok) {
        throw new Error('Failed to fetch sessions');
      }
      const data = await response.json();
      setSessions(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const calculateTotal = (session: any) => {
    const baseRate = 10; // $10 per hour
    const hours = (new Date(session.endTime).getTime() - new Date(session.startTime).getTime()) / (1000 * 60 * 60);
    return baseRate * hours;
  };

  const processPayment = async (sessionId: string) => {
    try {
      const response = await fetch(`/api/sessions/${sessionId}/pay`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sessionId })
      });

      if (!response.ok) {
        throw new Error('Failed to process payment');
      }

      // Refresh sessions after payment
      await fetchSessions();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const generateInvoice = async (sessionId: string) => {
    try {
      const response = await fetch(`/api/sessions/${sessionId}/invoice`, {
        method: 'GET'
      });

      if (!response.ok) {
        throw new Error('Failed to generate invoice');
      }

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `invoice-${sessionId}.pdf`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (sessions.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No active sessions found.</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Billing System</h1>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        {sessions.map((session) => {
          const total = calculateTotal(session);
          return (
            <div key={session.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                <div>
                  <strong>Session ID:</strong> {session.id}
                </div>
                <div>
                  <strong>Total:</strong> ${total.toFixed(2)}
                </div>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                <div>
                  <strong>Start Time:</strong> {new Date(session.startTime).toLocaleString()}
                </div>
                <div>
                  <strong>End Time:</strong> {session.endTime ? new Date(session.endTime).toLocaleString() : 'Still active'}
                </div>
              </div>
              <div style={{ display: 'flex', gap: '10px', marginTop: '10px' }}>
                {!session.paid && (
                  <button 
                    onClick={() => processPayment(session.id)}
                    style={{ backgroundColor: '#4CAF50', color: 'white', border: 'none', padding: '8px 12px', borderRadius: '4px', cursor: 'pointer' }}
                  >
                    Process Payment
                  </button>
                )}
                <button 
                  onClick={() => generateInvoice(session.id)}
                  style={{ backgroundColor: '#2196F3', color: 'white', border: 'none', padding: '8px 12px', borderRadius: '4px', cursor: 'pointer' }}
                >
                  Generate Invoice
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

interface EquipmentItem {
  id: string;
  name: string;
  checkedOutBy: string | null;
  checkedOutAt: string | null;
}

export function CheckoutQueue() {
  const [equipment, setEquipment] = useState<EquipmentItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [artistName, setArtistName] = useState("");
  const [selectedToolId, setSelectedToolId] = useState<string | null>(null);

  useEffect(() => {
    fetchEquipment();
  }, []);

  const fetchEquipment = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/checkout-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setEquipment(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleCheckout = async (toolId: string) => {
    if (!artistName.trim()) {
      setError('Please enter your name');
      return;
    }

    try {
      const response = await fetch(`/api/checkout-api/${toolId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ checkedOutBy: artistName.trim() }),
      });

      if (!response.ok) {
        throw new Error(`Failed to checkout: ${response.status} ${response.statusText}`);
      }

      // Refresh the list after successful checkout
      await fetchEquipment();
      setArtistName("");
      setSelectedToolId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleReturn = async (toolId: string) => {
    try {
      const response = await fetch(`/api/checkout-api/${toolId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ checkedOutBy: null, checkedOutAt: null }),
      });

      if (!response.ok) {
        throw new Error(`Failed to return: ${response.status} ${response.statusText}`);
      }

      // Refresh the list after successful return
      await fetchEquipment();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDelete = async (toolId: string) => {
    try {
      const response = await fetch(`/api/checkout-api/${toolId}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        throw new Error(`Failed to delete: ${response.status} ${response.statusText}`);
      }

      // Refresh the list after successful deletion
      await fetchEquipment();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedToolId) {
      handleCheckout(selectedToolId);
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
