{"code":"import { useEffect, useState } from "react";

interface Order {
  id: string;
  customerName: string;
  items: string[];
  status: "pending" | "preparing" | "ready" | "completed" | "cancelled";
  timestamp: string;
}

export function OrderDashboard() {
  const [orders, setOrders] = useState<Order[]>([]);
  const [filteredOrders, setFilteredOrders] = useState<Order[]>([]);
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // Simulate fetching orders
    const fetchOrders = () => {
      // In a real app, this would be an API call
      // For demo purposes, we'll simulate with mock data
      const mockOrders: Order[] = [
        {
          id: "1",
          customerName: "John Doe",
          items: ["Pizza", "Salad"],
          status: "preparing",
          timestamp: "2023-05-15T10:30:00Z"
        },
        {
          id: "2",
          customerName: "Jane Smith",
          items: ["Burger", "Fries"],
          status: "ready",
          timestamp: "2023-05-15T11:15:00Z"
        },
        {
          id: "3",
          customerName: "Bob Johnson",
          items: ["Pasta", "Garlic Bread"],
          status: "completed",
          timestamp: "2023-05-15T09:45:00Z"
        }
      ];

      setOrders(mockOrders);
      setFilteredOrders(mockOrders);
      setLoading(false);
    };

    fetchOrders();

    // Simulate real-time updates
    const intervalId = setInterval(() => {
      // In a real app, this would be WebSocket or polling
      setOrders(prevOrders => {
        const updatedOrders = [...prevOrders];
        // Randomly update some orders
        if (updatedOrders.length > 0) {
          const randomIndex = Math.floor(Math.random() * updatedOrders.length);
          const statuses: Order["status"][] = ["pending", "preparing", "ready", "completed", "cancelled"];
          updatedOrders[randomIndex].status = statuses[Math.floor(Math.random() * statuses.length)];
        }
        return updatedOrders;
      });
    }, 10000);

    return () => clearInterval(intervalId);
  }, []);

  useEffect(() => {
    if (statusFilter === "all") {
      setFilteredOrders(orders);
    } else {
      setFilteredOrders(orders.filter(order => order.status === statusFilter));
    }
  }, [statusFilter, orders]);

  const handleStatusChange = (orderId: string, newStatus: Order["status"]) => {
    setOrders(prevOrders => 
      prevOrders.map(order => 
        order.id === orderId ? { ...order, status: newStatus } : order
      )
    );
  };

  const getStatusColor = (status: Order["status"]) => {
    switch (status) {
      case "pending": return "#FFD700";
      case "preparing": return "#1E90FF";
      case "ready": return "#32CD32";
      case "completed": return "#008000";
      case "cancelled": return "#808080";
      default: return "#000000";
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "1200px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center", marginBottom: "30px" }}>Cloud Kitchen Order Dashboard</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <label htmlFor="statusFilter" style={{ fontWeight: "bold" }}>Filter by Status:</label>
        <select
          id="statusFilter"
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          style={{ padding: "8px", borderRadius: "4px", border: "1px solid #ccc", fontSize: "16px" }}
        >
          <option value="all">All Orders</option>
          <option value="pending">Pending</option>
          <option value="preparing">Preparing</option>
          <option value="ready">Ready</option>
          <option value="completed">Completed</option>
          <option value="cancelled">Cancelled</option>
        </select>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(300px, 1fr))", gap: "20px" }}>
        {filteredOrders.length === 0 ? (
          <div style={{ textAlign: "center", gridColumn: "1 / -1", padding: "20px" }}>
            No orders found.
          </div>
        ) : (
          filteredOrders.map(order => (
            <div key={order.id} style={{ border: "1px solid #ddd", borderRadius: "8px", padding: "15px", backgroundColor: "#f9f9f9" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "10px" }}>
                <h3 style={{ margin: "0", fontSize: "18px" }}>Order #{order.id}</h3>
                <span style={{ backgroundColor: getStatusColor(order.status), padding: "4px 8px", borderRadius: "4px", color: "white", fontSize: "14px" }}>
                  {order.status.charAt(0).toUpperCase() + order.status.slice(1)}
                </span>
              </div>

              <p style={{ margin: "5px 0" }}><strong>Customer:</strong> {order.customerName}</p>
              <p style={{ margin: "5px 0" }}><strong>Items:</strong> {order.items.join(", ")}</p>
              <p style={{ margin: "5px 0" }}><strong>Time:</strong> {new Date(order.timestamp).toLocaleTimeString()}</p>

              <div style={{ marginTop: "10px", display: "flex", gap: "5px", flexWrap: "wrap" }}>
                <button 
                  onClick={() => handleStatusChange(order.id, "preparing")}
                  style={{ padding: "4px 8px", backgroundColor: "#1E90FF", color: "white", border: "none", borderRadius: "4px", cursor: "pointer", fontSize: "12px" }}
                >
                  Preparing
                </button>
                <button 
                  onClick={() => handleStatusChange(order.id, "ready")}
                  style={{ padding: "4px 8px", backgroundColor: "#32CD32", color: "white", border: "none", borderRadius: "4px", cursor: "pointer", fontSize: "12px" }}
                >
                  Ready
                </button>
                <button 
                  onClick={() => handleStatusChange(order.id, "completed")}
                  style={{ padding: "4px 8px", backgroundColor: "#008000", color: "white", border: "none", borderRadius: "4px", cursor: "pointer", fontSize: "12px" }}
                >
                  Completed
                </button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}
"}

