{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock student data storage
let students = [
  { id: 1, name: "Alice Johnson", email: "alice@example.com", age: 20 },
  { id: 2, name: "Bob Smith", email: "bob@example.com", age: 22 },
  { id: 3, name: "Charlie Brown", email: "charlie@example.com", age: 19 }
];

let nextId = 4;

// GET /students - List all students
router.get("/students", (req: Request, res: Response) => {
  res.json(students);
});

// GET /students/:id - Get a specific student by ID
router.get("/students/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid student ID" });
  }

  const student = students.find(s => s.id === id);

  if (!student) {
    return res.status(404).json({ error: "Student not found" });
  }

  res.json(student);
});

// POST /students - Create a new student
router.post("/students", (req: Request, res: Response) => {
  const { name, email, age } = req.body;

  if (!name || !email || !age) {
    return res.status(400).json({ error: "Name, email, and age are required" });
  }

  const newStudent = {
    id: nextId++,
    name,
    email,
    age: Number(age)
  };

  students.push(newStudent);

  res.status(201).json(newStudent);
});

// PUT /students/:id - Update a student
router.put("/students/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { name, email, age } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid student ID" });
  }

  const studentIndex = students.findIndex(s => s.id === id);

  if (studentIndex === -1) {
    return res.status(404).json({ error: "Student not found" });
  }

  if (!name || !email || !age) {
    return res.status(400).json({ error: "Name, email, and age are required" });
  }

  students[studentIndex] = {
    id,
    name,
    email,
    age: Number(age)
  };

  res.json(students[studentIndex]);
});

// DELETE /students/:id - Delete a student
router.delete("/students/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid student ID" });
  }

  const studentIndex = students.findIndex(s => s.id === id);

  if (studentIndex === -1) {
    return res.status(404).json({ error: "Student not found" });
  }

  students.splice(studentIndex, 1);

  res.json({ message: "Student deleted successfully" });
});
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function isValidToken(token: string): boolean {
  if (!JWT_SECRET) return false;

  const parts = token.split(".");
  if (parts.length !== 3) return false;

  const [header, payload, signature] = parts;

  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(signature, "base64url");

    return timingSafeEqual(expectedBuffer, actualBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST, PUT, DELETE requests to /inventory and /orders
  const isProtectedPath = req.path.startsWith("/inventory") || req.path.startsWith("/orders");
  const isProtectedMethod = req.method === "POST" || req.method === "PUT" || req.method === "DELETE";

  if (!isProtectedPath || !isProtectedMethod) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  if (!isValidToken(token)) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  // Token is valid, proceed to next middleware/route handler
  next();
}
"}

{"code":"import { useEffect, useState } from "react";

interface Project {
  id: string;
  name: string;
}

interface TimeEntry {
  id: string;
  projectId: string;
  startTime: string;
  endTime: string | null;
  duration: number | null;
}

export function TimeTrackingInterface() {
  const [isTimerRunning, setIsTimerRunning] = useState(false);
  const [elapsedTime, setElapsedTime] = useState(0);
  const [selectedProjectId, setSelectedProjectId] = useState<string>("");
  const [projects, setProjects] = useState<Project[]>([]);
  const [timeEntries, setTimeEntries] = useState<TimeEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Load projects and time entries
  useEffect(() => {
    const fetchData = async () => {
      try {
        const [projectsResponse, entriesResponse] = await Promise.all([
          fetch("/api/projects-api/"),
          fetch("/api/time-entries-api/")
        ]);

        if (!projectsResponse.ok || !entriesResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const [projectsData, entriesData] = await Promise.all([
          projectsResponse.json(),
          entriesResponse.json()
        ]);

        setProjects(projectsData);
        setTimeEntries(entriesData);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  // Timer effect
  useEffect(() => {
    let interval: NodeJS.Timeout | null = null;

    if (isTimerRunning) {
      interval = setInterval(() => {
        setElapsedTime(prev => prev + 1);
      }, 1000);
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isTimerRunning]);

  const formatTime = (seconds: number): string => {
    const hrs = Math.floor(seconds / 3600);
    const mins = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;

    return `${hrs.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const handleStartTimer = async () => {
    if (!selectedProjectId) {
      setError("Please select a project first");
      return;
    }

    try {
      const response = await fetch("/api/timer-service/start", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ projectId: selectedProjectId })
      });

      if (!response.ok) {
        throw new Error("Failed to start timer");
      }

      setIsTimerRunning(true);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleStopTimer = async () => {
    try {
      const response = await fetch("/api/timer-service/stop", {
        method: "POST",
        headers: { "Content-Type": "application/json" }
      });

      if (!response.ok) {
        throw new Error("Failed to stop timer");
      }

      setIsTimerRunning(false);
      setElapsedTime(0);
      setError(null);

      // Refresh time entries
      const entriesResponse = await fetch("/api/time-entries-api/");
      if (entriesResponse.ok) {
        const entriesData = await entriesResponse.json();
        setTimeEntries(entriesData);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleManualEntry = async () => {
    if (!selectedProjectId) {
      setError("Please select a project first");
      return;
    }

    try {
      const response = await fetch("/api/time-entries-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          projectId: selectedProjectId,
          duration: elapsedTime
        })
      });

      if (!response.ok) {
        throw new Error("Failed to create manual entry");
      }

      setElapsedTime(0);
      setSelectedProjectId("");
      setError(null);

      // Refresh time entries
      const entriesResponse = await fetch("/api/time-entries-api/");
      if (entriesResponse.ok) {
        const entriesData = await entriesResponse.json();
        setTimeEntries(entriesData);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Time Tracking</h1>

      <div style={{ marginBottom: "20px", padding: "15px", backgroundColor: "#f5f5f5", borderRadius: "8px" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "10px" }}>
          <span style={{ fontSize: "24px", fontWeight: "bold" }}>{formatTime(elapsedTime)}</span>
          <div style={{ display: "flex", gap: "10px" }}>
            {!isTimerRunning ? (
              <button 
                onClick={handleStartTimer}
                style={{ padding: "8px 16px", backgroundColor: "#4CAF50", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
              >
                Start Timer
              </button>
            ) : (
              <button 
                onClick={handleStopTimer}
                style={{ padding: "8px 16px", backgroundColor: "#f44336", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
              >
                Stop Timer
              </button>
            )}
          </div>
        </div>

        <div style={{ marginBottom: "10px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Select Project:</label>
          <select 
            value={selectedProjectId}
            onChange={(e) => setSelectedProjectId(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          >
            <option value="">-- Select Project --</option>
            {projects.map(project => (
              <option key={project.id} value={project.id}>{project.name}</option>
            ))}
          </select>
        </div>

        <button 
          onClick={handleManualEntry}
          style={{ width: "100%", padding: "10px", backgroundColor: "#2196F3", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
        >
          Save Manual Entry
        </button>
      </div>

      <h2>Recent Time Entries</h2>

      {timeEntries.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No time entries found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {timeEntries.map(entry => (
            <div 
              key={entry.id} 
              style={{ 
                padding: "10px", 
                border: "1px solid #ddd", 
                borderRadius: "4px",
                display: "flex",
                justifyContent: "space-between"
              }}
            >
              <div>
                <strong>{projects.find(p => p.id === entry.projectId)?.name || "Unknown Project"}</strong>
                <br />
                {entry.startTime} - {entry.endTime || "Ongoing"}
              </div>
              <div>
                {entry.duration ? `${Math.floor(entry.duration / 60)}m ${entry.duration % 60}s` : "N/A"}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to POST /orders and PUT /orders routes
  if (!(req.method === "POST" && req.path === "/orders") && !(req.method === "PUT" && req.path === "/orders")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT_SECRET not configured" });
    return;
  }

  // Split token into parts
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  const [header, payload, signature] = parts;

  // Verify signature
  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  const signatureBuffer = Buffer.from(signature, "base64url");
  const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

  try {
    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Unauthorized: Invalid token signature" });
    return;
  }

  // Decode payload
  const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());

  // Check role
  const { role } = decodedPayload;
  if (role !== "admin" && role !== "staff") {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  // Attach role to request for downstream middleware/routes
  (req as any).userRole = role;
  next();
}
"}

{"code":"import { useEffect, useState } from "react";

interface Reservation {
  id: string;
  date: string;
  time: string;
  guestName: string;
  guestEmail: string;
}

export function ReservationCalendar() {
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [bookingForm, setBookingForm] = useState({
    guestName: '',
    guestEmail: '',
  });
  const [selectedSlot, setSelectedSlot] = useState<string | null>(null);

  useEffect(() => {
    fetchReservations();
  }, [selectedDate]);

  const fetchReservations = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(`/api/reservations-api/?date=${selectedDate}`);
      if (!response.ok) {
        throw new Error(`Failed to fetch reservations: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setReservations(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleBookSlot = async (slotId: string) => {
    if (!bookingForm.guestName || !bookingForm.guestEmail) {
      alert('Please fill in your name and email');
      return;
    }

    try {
      const response = await fetch(`/api/reservations-api/`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          date: selectedDate,
          time: slotId,
          guestName: bookingForm.guestName,
          guestEmail: bookingForm.guestEmail,
        }),
      });

      if (!response.ok) {
        throw new Error(`Failed to book reservation: ${response.status} ${response.statusText}`);
      }

      // Reset form and refresh reservations
      setBookingForm({ guestName: '', guestEmail: '' });
      setSelectedSlot(null);
      await fetchReservations();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setBookingForm(prev => ({ ...prev, [name]: value }));
  };

  const getAvailableSlots = () => {
    const slots = [
      '09:00', '10:00', '11:00', '12:00',
      '13:00', '14:00', '15:00', '16:00'
    ];

    return slots.filter(slot => 
      !reservations.some(res => res.time === slot)
    );
  };

  const availableSlots = getAvailableSlots();

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Vineyard Tasting Room Reservations</h1>

      <div style={{ marginBottom: '20px' }}>
        <label htmlFor="datePicker" style={{ display: 'block', marginBottom: '5px' }}>
          Select Date:
        </label>
        <input
          type="date"
          id="datePicker"
          value={selectedDate}
          onChange={(e) => setSelectedDate(e.target.value)}
          style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
        />
      </div>

      <h2 style={{ textAlign: 'center' }}>Available Time Slots</h2>

      {availableSlots.length === 0 ? (
        <p style={{ textAlign: 'center', fontStyle: 'italic' }}>No available slots for this date.</p>
      ) : (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px', justifyContent: 'center' }}>
          {availableSlots.map(slot => (
            <button
              key={slot}
              onClick={() => handleBookSlot(slot)}
              style={{
                padding: '10px 15px',
                backgroundColor: '#4CAF50',
                color: 'white',
                border: 'none',
                borderRadius: '4px',
                cursor: 'pointer',
                fontSize: '16px',
                minWidth: '100px'
              }}
            >
              {slot}
            </button>
          ))}
        </div>
      )}

      <h2 style={{ textAlign: 'center', marginTop: '30px' }}>Book Your Slot</h2>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '10px', maxWidth: '400px', margin: '0 auto' }}>
        <input
          type="text"
          name="guestName"
          placeholder="Your Name"
          value={bookingForm.guestName}
          onChange={handleInputChange}
          style={{ padding: '10px', borderRadius: '4px', border: '1px solid #ccc', width: '100%' }}
        />
        <input
          type="email"
          name="guestEmail"
          placeholder="Your Email"
          value={bookingForm.guestEmail}
          onChange={handleInputChange}
          style={{ padding: '10px', borderRadius: '4px', border: '1px solid #ccc', width: '100%' }}
        />
        <button
          onClick={() => {
            if (selectedSlot) {
              handleBookSlot(selectedSlot);
            }
          }}
          disabled={!selectedSlot}
          style={{
            padding: '10px',
            backgroundColor: selectedSlot ? '#2196F3' : '#ccc',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: selectedSlot ? 'pointer' : 'default',
            fontSize: '16px'
          }}
        >
          Book Selected Slot
        </button>
      </div>

      <h2 style={{ textAlign: 'center', marginTop: '30px' }}>Current Reservations</h2>

      {reservations.length === 0 ? (
        <p style={{ textAlign: 'center', fontStyle: 'italic' }}>No reservations found for this date.</p>
      ) : (
        <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: '10px' }}>
          <thead>
            <tr style={{ borderBottom: '2px solid #ddd' }}>
              <th style={{ padding: '10px', textAlign: 'left' }}>Time</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Guest</th>
            </tr>
          </thead>
          <tbody>
            {reservations.map(res => (
              <tr key={res.id} style={{ borderBottom: '1px solid #eee' }}>
                <td style={{ padding: '10px' }}>{res.time}</td>
                <td style={{ padding: '10px' }}>{res.guestName}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

interface InventoryItem {
  id: number;
  name: string;
  category: string;
  stockLevel: number;
  lowStockThreshold: number;
}

export function InventoryDashboard() {
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchInventory();
  }, []);

  const fetchInventory = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/inventory');
      if (!response.ok) {
        throw new Error('Failed to fetch inventory');
      }
      const data = await response.json();
      setInventory(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const getLowStockItems = () => {
    return inventory.filter(item => item.stockLevel <= item.lowStockThreshold);
  };

  const getOutOfStockItems = () => {
    return inventory.filter(item => item.stockLevel === 0);
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  const lowStockItems = getLowStockItems();
  const outOfStockItems = getOutOfStockItems();

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Inventory Dashboard</h1>

      <div style={{ marginBottom: '30px' }}>
        <h2>Low Stock Alerts</h2>
        {lowStockItems.length > 0 ? (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
            {lowStockItems.map(item => (
              <div key={item.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '10px', flex: '1 1 200px' }}>
                <strong>{item.name}</strong>
                <p>Current: {item.stockLevel}</p>
                <p>Threshold: {item.lowStockThreshold}</p>
              </div>
            ))}
          </div>
        ) : (
          <p>No items below threshold</p>
        )}
      </div>

      <div style={{ marginBottom: '30px' }}>
        <h2>Out of Stock Items</h2>
        {outOfStockItems.length > 0 ? (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
            {outOfStockItems.map(item => (
              <div key={item.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '10px', flex: '1 1 200px' }}>
                <strong>{item.name}</strong>
                <p>Currently out of stock</p>
              </div>
            ))}
          </div>
        ) : (
          <p>All items in stock</p>
        )}
      </div>

      <div>
        <h2>Current Stock Levels</h2>
        {inventory.length > 0 ? (
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ borderBottom: '2px solid #ccc' }}>
                <th style={{ textAlign: 'left', padding: '10px' }}>Item</th>
                <th style={{ textAlign: 'left', padding: '10px' }}>Category</th>
                <th style={{ textAlign: 'left', padding: '10px' }}>Stock Level</th>
              </tr>
            </thead>
            <tbody>
              {inventory.map(item => (
                <tr key={item.id} style={{ borderBottom: '1px solid #eee' }}>
                  <td style={{ padding: '10px' }}>{item.name}</td>
                  <td style={{ padding: '10px' }}>{item.category}</td>
                  <td style={{ padding: '10px' }}>{item.stockLevel}</td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <p>No inventory data available</p>
        )}
      </div>

      <div style={{ marginTop: '30px', textAlign: 'center' }}>
        <button 
          onClick={fetchInventory}
          style={{ 
            backgroundColor: '#007bff', 
            color: 'white', 
            border: 'none', 
            borderRadius: '4px', 
            padding: '10px 20px', 
            cursor: 'pointer' 
          }}
        >
          Refresh Inventory
        </button>
      </div>
    </div>
  );
}
"}

