  { id: 1, make: "Toyota", model: "Camry", year: 2020, licensePlate: "ABC123" },
  { id: 2, make: "Honda", model: "Civic", year: 2019, licensePlate: "XYZ789" }
];

let nextId = 3;

// GET /vehicles - List all vehicles
router.get("/vehicles", (req: Request, res: Response) => {
  res.json(vehicles);
});

// GET /vehicles/:id - Get a specific vehicle by ID
router.get("/vehicles/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const vehicle = vehicles.find(v => v.id === id);

  if (!vehicle) {
    return res.status(404).json({ error: "Vehicle not found" });
  }

  res.json(vehicle);
});

// POST /vehicles - Create a new vehicle
router.post("/vehicles", (req: Request, res: Response) => {
  const { make, model, year, licensePlate } = req.body;

  // Basic validation
  if (!make || !model || !year || !licensePlate) {
    return res.status(400).json({ error: "Missing required fields: make, model, year, licensePlate" });
  }

  const newVehicle = {
    id: nextId++,
    make,
    model,
    year: Number(year),
    licensePlate
  };

  vehicles.push(newVehicle);
  res.status(201).json(newVehicle);
});

// PUT /vehicles/:id - Update a vehicle
router.put("/vehicles/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { make, model, year, licensePlate } = req.body;

  const vehicleIndex = vehicles.findIndex(v => v.id === id);

  if (vehicleIndex === -1) {
    return res.status(404).json({ error: "Vehicle not found" });
  }

  // Basic validation
  if (!make || !model || !year || !licensePlate) {
    return res.status(400).json({ error: "Missing required fields: make, model, year, licensePlate" });
  }

  vehicles[vehicleIndex] = {
    id,
    make,
    model,
    year: Number(year),
    licensePlate
  };

  res.json(vehicles[vehicleIndex]);
});

// DELETE /vehicles/:id - Delete a vehicle
router.delete("/vehicles/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const vehicleIndex = vehicles.findIndex(v => v.id === id);

  if (vehicleIndex === -1) {
    return res.status(404).json({ error: "Vehicle not found" });
  }

  vehicles.splice(vehicleIndex, 1);
  res.json({ message: "Vehicle deleted successfully" });
});
