export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply guard to DELETE requests to the shifts API
  if (req.method !== "DELETE" || !req.path.startsWith("/api/shifts")) {
    next();
    return;
  }

  // Check if user is supervisor
  // In a real implementation, this would check the request context
  // For now, we'll simulate supervisor check
  const isSupervisor = req.headers["x-user-role"] === "supervisor";

  if (!isSupervisor) {
    res.status(403).json({ error: "Forbidden: Supervisor access required to delete shifts" });
    return;
  }

  next();
}
