{"code":"import { useEffect, useState } from "react";

interface Pet {
  id: number;
  name: string;
  ownerName: string;
  contactInfo: string;
  notes: string;
  checkedIn: boolean;
}

export function CheckInOutForm() {
  const [pets, setPets] = useState<Pet[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    name: "",
    ownerName: "",
    contactInfo: "",
    notes: "",
  });

  const [editingId, setEditingId] = useState<number | null>(null);

  useEffect(() => {
    fetchPets();
  }, []);

  const fetchPets = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/pets-api/pets");
      if (!response.ok) throw new Error("Failed to fetch pets");
      const data = await response.json();
      setPets(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const url = editingId 
        ? `/api/pets-api/pets/${editingId}`
        : "/api/pets-api/pets";

      const method = editingId ? "PUT" : "POST";

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...formData,
          checkedIn: true,
        }),
      });

      if (!response.ok) throw new Error("Failed to save pet");

      fetchPets();
      resetForm();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const resetForm = () => {
    setFormData({ name: "", ownerName: "", contactInfo: "", notes: "" });
    setEditingId(null);
  };

  const handleEdit = (pet: Pet) => {
    setFormData({
      name: pet.name,
      ownerName: pet.ownerName,
      contactInfo: pet.contactInfo,
      notes: pet.notes,
    });
    setEditingId(pet.id);
  };

  const handleCheckOut = async (id: number) => {
    try {
      const response = await fetch(`/api/pets-api/pets/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ checkedIn: false }),
      });

      if (!response.ok) throw new Error("Failed to check out pet");

      fetchPets();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px", fontFamily: "system-ui, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Pet Check-In/Out Form</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="name" style={{ display: "block", marginBottom: "5px" }}>Pet Name:</label>
          <input
            type="text"
            id="name"
            name="name"
            value={formData.name}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="ownerName" style={{ display: "block", marginBottom: "5px" }}>Owner Name:</label>
          <input
            type="text"
            id="ownerName"
            name="ownerName"
            value={formData.ownerName}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="contactInfo" style={{ display: "block", marginBottom: "5px" }}>Contact Info:</label>
          <input
            type="text"
            id="contactInfo"
            name="contactInfo"
            value={formData.contactInfo}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="notes" style={{ display: "block", marginBottom: "5px" }}>Notes:</label>
          <textarea
            id="notes"
            name="notes"
            value={formData.notes}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd", minHeight: "80px" }}
          />
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: "#007bff", 
            color: "white", 
            padding: "10px 20px", 
            border: "none", 
            borderRadius: "4px", 
            cursor: "pointer" 
          }}
        >
          {editingId ? "Update Pet" : "Check In Pet"}
        </button>

        {editingId && (
          <button 
            type="button" 
            onClick={resetForm}
            style={{ 
              backgroundColor: "#6c757d", 
              color: "white", 
              padding: "10px 20px", 
              border: "none", 
              borderRadius: "4px", 
              cursor: "pointer", 
              marginLeft: "10px" 
            }}
          >
            Cancel Edit
          </button>
        )}
      </form>

      <h2 style={{ textAlign: "center" }}>Checked In Pets</h2>

      {pets.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>No pets currently checked in.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {pets
            .filter(pet => pet.checkedIn)
            .map(pet => (
              <div key={pet.id} style={{ 
                border: "1px solid #ccc", 
                borderRadius: "8px", 
                padding: "15px", 
                display: "flex", 
                justifyContent: "space-between", 
                alignItems: "center" 
              }}>
                <div>
                  <strong>{pet.name}</strong> - {pet.ownerName}
                  <br />
                  <small>{pet.contactInfo}</small>
                  <br />
                  <small>{pet.notes}</small>
                </div>
                <div>
                  <button 
                    onClick={() => handleCheckOut(pet.id)}
                    style={{ 
                      backgroundColor: "#dc3545", 
                      color: "white", 
                      padding: "5px 10px", 
                      border: "none", 
                      borderRadius: "4px", 
                      cursor: "pointer" 
                    }}
                  >
                    Check Out
                  </button>
                </div>
              </div>
            ))}
        </div>
      )}

      <h2 style={{ textAlign: "center", marginTop: "30px" }}>Checked Out Pets</h2>

      {pets.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>No pets checked out.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {pets
            .filter(pet => !pet.checkedIn)
            .map(pet => (
              <div key={pet.id} style={{ 
                border: "1px solid #ccc", 
                borderRadius: "8px", 
                padding: "15px", 
                display: "flex", 
                justifyContent: "space-between", 
                alignItems: "center" 
              }}>
                <div>
                  <strong>{pet.name}</strong> - {pet.ownerName}
                  <br />
                  <small>{pet.contactInfo}</small>
                  <br />
                  <small>{pet.notes}</small>
                </div>
                <div>
                  <button 
                    onClick={() => handleEdit(pet)}
                    style={{ 
                      backgroundColor: "#28a745", 
                      color: "white", 
                      padding: "5px 10px", 
                      border: "none", 
                      borderRadius: "4px", 
                      cursor: "pointer" 
                    }}
                  >
                    Check In
                  </button>
                </div>
              </div>
            ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import { getAllBookings } from "../db/bookings-table";

const router = Router();

router.get("/export", (req: Request, res: Response) => {
  // Check for owner token
  const ownerToken = req.headers["x-owner-token"];
  if (ownerToken !== "secret-owner-token") {
    return res.status(401).json({ error: "Unauthorized" });
  }

  // Get all bookings
  const bookings = getAllBookings();

  // Generate CSV content
  let csvContent = "id,guest_id,room_id,check_in_date,check_out_date\n";
  for (const booking of bookings) {
    csvContent += `${booking.id},${booking.guest_id},${booking.room_id},${booking.check_in_date},${booking.check_out_date}\n`;
  }

  // Send CSV response
  res.setHeader("Content-Type", "text/csv");
  res.setHeader("Content-Disposition", "attachment; filename=bookings.csv");
  res.status(200).send(csvContent);
});

export { router };
"}

