export const router = Router();

// Mock loan calculation service
const calculateEMI = (principal: number, rate: number, time: number): number => {
  const monthlyRate = rate / 12 / 100;
  const totalMonths = time * 12;

  if (monthlyRate === 0) {
    return principal / totalMonths;
  }

  return principal * monthlyRate * Math.pow(1 + monthlyRate, totalMonths) / (Math.pow(1 + monthlyRate, totalMonths) - 1);
};

// Mock EMI schedule generator
const generateEMISchedule = (principal: number, rate: number, time: number): { month: number; amount: number; principal: number; interest: number; balance: number }[] => {
  const schedule = [];
  const monthlyRate = rate / 12 / 100;
  const totalMonths = time * 12;
  let balance = principal;

  const emi = calculateEMI(principal, rate, time);

  for (let month = 1; month <= totalMonths; month++) {
    const interestPayment = balance * monthlyRate;
    const principalPayment = emi - interestPayment;
    balance -= principalPayment;

    schedule.push({
      month,
      amount: emi,
      principal: principalPayment,
      interest: interestPayment,
      balance
    });
  }

  return schedule;
};

