    return res.status(400).json({ error: "Principal, rate, and time must be numbers" });
  }

  if (principalNum <= 0 || rateNum <= 0 || timeNum <= 0) {
    return res.status(400).json({ error: "Principal, rate, and time must be positive numbers" });
  }

  const emi = calculateEMI(principalNum, rateNum, timeNum);
  const schedule = generateEMISchedule(principalNum, rateNum, timeNum);

  const newLoan = {
    id: Date.now(),
    principal: principalNum,
    rate: rateNum,
    time: timeNum,
