    sessionId INTEGER NOT NULL,
    status TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllRegistrations(): Registration[] {
  const stmt = db.prepare(
    "SELECT * FROM registrations ORDER BY id"
  );
  return stmt.all() as unknown as Registration[];
}

export function getRegistrationById(id: number): Registration | undefined {
  const stmt = db.prepare(
    "SELECT * FROM registrations WHERE id = ?"
  );
  return stmt.get(id) as unknown as Registration | undefined;
}

export function insertRegistration(
  camperId: number,
  sessionId: number,
  status: string
): number {
  const stmt = db.prepare(
    "INSERT INTO registrations (camperId, sessionId, status) VALUES (?, ?, ?)"
  );
  const result = stmt.run(camperId, sessionId, status);
  return Number(result.lastInsertRowid);
}

export function updateRegistration(
  id: number,
  camperId: number,
  sessionId: number,
  status: string
): void {
  const stmt = db.prepare(
    "UPDATE registrations SET camperId = ?, sessionId = ?, status = ? WHERE id = ?"
  );
  stmt.run(camperId, sessionId, status, id);
}

export function deleteRegistration(id: number): void {
  const stmt = db.prepare("DELETE FROM registrations WHERE id = ?");
  stmt.run(id);
}

// Seed data
if (getAllRegistrations().length === 0) {
  const sampleRegistrations = [
    { camperId: 1, sessionId: 1, status: "confirmed" },
    { camperId: 2, sessionId: 2, status: "pending" },
    { camperId: 3, sessionId: 1, status: "cancelled" },
    { camperId: 4, sessionId: 3, status: "confirmed" },
    { camperId: 5, sessionId: 2, status: "pending" }
  ];

  for (const reg of sampleRegistrations) {
    insertRegistration(reg.camperId, reg.sessionId, reg.status);
  }
}
"}

