{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  { id: 1, username: "admin", password: "admin123", role: "staff" },
  { id: 2, username: "customer1", password: "pass456", role: "customer" }
];

// User registration
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role } = req.body;

  if (!username || !password || !role) {
    return res.status(400).json({ error: "Username, password, and role are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    username,
    password,
    role
  };

  users.push(newUser);
  return res.status(201).json(newUser);
});

// User login
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Find user
  const user = users.find(u => u.username === username && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Return user info (excluding password)
  const { password: _, ...userWithoutPassword } = user;
  return res.json(userWithoutPassword);
});

// Role-based access control middleware
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: Function) => {
    const userRole = (req as any).user?.role;
    if (!userRole || !roles.includes(userRole)) {
      return res.status(403).json({ error: "Access denied" });
    }
    next();
  };
};

// Staff-only route example
router.get("/staff-dashboard", authorize(["staff"]), (req: Request, res: Response) => {
  return res.json({ message: "Welcome to the staff dashboard" });
});

// Customer-only route example
router.get("/customer-dashboard", authorize(["customer"]), (req: Request, res: Response) => {
  return res.json({ message: "Welcome to the customer dashboard" });
});
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock session storage - in a real app this would be a proper session store
const sessions: Record<string, { userId: string }> = {};

// Mock user database - in a real app this would be a proper database
const users = [
  { id: "1", email: "user@example.com", password: "password123" },
];

// Helper to generate a mock session ID
const generateSessionId = () => Math.random().toString(36).substring(2, 15);

/**
 * POST /login - Authenticate a user and create a session
 */
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  // Find user by email
  const user = users.find(u => u.email === email);

  if (!user || user.password !== password) {
    return res.status(401).json({ error: "Invalid email or password" });
  }

  // Create a session
  const sessionId = generateSessionId();
  sessions[sessionId] = { userId: user.id };

  // Set session cookie
  res.cookie("sessionId", sessionId, { httpOnly: true, secure: false });

  return res.status(200).json({ message: "Login successful" });
});

/**
 * GET /logout - End the current user session
 */
router.get("/logout", (req: Request, res: Response) => {
  const sessionId = req.cookies.sessionId;

  if (sessionId && sessions[sessionId]) {
    delete sessions[sessionId];
  }

  res.clearCookie("sessionId");
  return res.status(200).json({ message: "Logout successful" });
});

/**
 * GET /me - Get the currently authenticated user
 */
router.get("/me", (req: Request, res: Response) => {
  const sessionId = req.cookies.sessionId;

  if (!sessionId || !sessions[sessionId]) {
    return res.status(401).json({ error: "Not authenticated" });
  }

  const userId = sessions[sessionId].userId;
  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  return res.status(200).json({ id: user.id, email: user.email });
});
"}

