  const { event_type, user_id, timestamp, data } = req.body;
  if (typeof event_type !== "string" || typeof user_id !== "number" || typeof timestamp !== "number" || typeof data !== "string") {
    res.status(400).send("Invalid request body");
    return;
  }
  insertEvent(event_type, user_id, timestamp, data);
  res.status(201).send("Event inserted");
});

router.get("/events/:userId", (req: Request, res: Response) => {
  const userId = Number(req.params.userId);
  if (isNaN(userId)) {
    res.status(400).send("Invalid user ID");
    return;
  }
  const events = getEventsByUserId(userId);
  res.status(200).json(events);
});
