{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockDatabase = {
  customers: [
    { id: "1", name: "John Doe", service: "Haircut", status: "waiting", timestamp: new Date().toISOString() },
    { id: "2", name: "Jane Smith", service: "Beard Trim", status: "completed", timestamp: new Date().toISOString() }
  ],

  getAllCustomers: (): Promise<any[]> => {
    return Promise.resolve(mockDatabase.customers);
  },

  getCustomerById: (id: string): Promise<any | null> => {
    const customer = mockDatabase.customers.find(c => c.id === id);
    return Promise.resolve(customer || null);
  },

  createCustomer: (customerData: any): Promise<any> => {
    const newCustomer = {
      id: (mockDatabase.customers.length + 1).toString(),
      ...customerData,
      timestamp: new Date().toISOString()
    };
    mockDatabase.customers.push(newCustomer);
    return Promise.resolve(newCustomer);
  },

  updateCustomer: (id: string, updateData: any): Promise<any | null> => {
    const customerIndex = mockDatabase.customers.findIndex(c => c.id === id);
    if (customerIndex === -1) return Promise.resolve(null);

    const updatedCustomer = {
      ...mockDatabase.customers[customerIndex],
      ...updateData
    };

    mockDatabase.customers[customerIndex] = updatedCustomer;
    return Promise.resolve(updatedCustomer);
  },

  deleteCustomer: (id: string): Promise<boolean> => {
    const initialLength = mockDatabase.customers.length;
    mockDatabase.customers = mockDatabase.customers.filter(c => c.id !== id);
    return Promise.resolve(mockDatabase.customers.length < initialLength);
  }
};

// GET /queue - Get all customers in queue
router.get("/queue", async (req: Request, res: Response) => {
  try {
    const customers = await mockDatabase.getAllCustomers();
    res.json(customers);
  } catch (error) {
    res.status(500).json({ error: "Failed to retrieve queue" });
  }
});

// GET /queue/:id - Get a specific customer by ID
router.get("/queue/:id", async (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    const customer = await mockDatabase.getCustomerById(id);

    if (!customer) {
      return res.status(404).json({ error: "Customer not found" });
    }

    res.json(customer);
  } catch (error) {
    res.status(500).json({ error: "Failed to retrieve customer" });
  }
});

// POST /queue - Add a new customer to queue
router.post("/queue", async (req: Request, res: Response) => {
  try {
    const { name, service } = req.body;

    if (!name || !service) {
      return res.status(400).json({ error: "Name and service are required" });
    }

    const newCustomer = await mockDatabase.createCustomer({ name, service, status: "waiting" });
    res.status(201).json(newCustomer);
  } catch (error) {
    res.status(500).json({ error: "Failed to add customer to queue" });
  }
});

// PUT /queue/:id - Update customer status
router.put("/queue/:id", async (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    const { status } = req.body;

    if (!status) {
      return res.status(400).json({ error: "Status is required" });
    }

    const updatedCustomer = await mockDatabase.updateCustomer(id, { status });

    if (!updatedCustomer) {
      return res.status(404).json({ error: "Customer not found" });
    }

    res.json(updatedCustomer);
  } catch (error) {
    res.status(500).json({ error: "Failed to update customer" });
  }
});

// DELETE /queue/:id - Remove customer from queue
router.delete("/queue/:id", async (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    const deleted = await mockDatabase.deleteCustomer(id);

    if (!deleted) {
      return res.status(404).json({ error: "Customer not found" });
    }

    res.json({ message: "Customer removed from queue" });
  } catch (error) {
    res.status(500).json({ error: "Failed to remove customer from queue" });
  }
});
"}

