{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const ADMIN_PATHS = ["/admin", "/admin/"];
const ADMIN_METHODS = ["POST", "PUT", "DELETE"];

function isPathAdmin(path: string): boolean {
  return ADMIN_PATHS.some(adminPath => 
    path === adminPath || path.startsWith(adminPath + "/")
  );
}

function isAdminRequest(req: Request): boolean {
  return (
    ADMIN_METHODS.includes(req.method) &&
    isPathAdmin(req.path)
  );
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-admin requests
  if (!isAdminRequest(req)) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  // Simple token verification (in a real app, use proper JWT library)
  const [header, payload, signature] = token.split(".");

  if (!header || !payload || !signature) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  try {
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // Basic role check - in a real app, decode the payload to check roles
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());

    if (decodedPayload.role !== "admin") {
      res.status(403).json({ error: "Forbidden: Insufficient permissions" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./schedule.db");

interface Booking {
  id: number;
  event_type_id: number;
  user_name: string;
  user_email: string;
  start_time: string;
  end_time: string;
  status: "confirmed" | "pending" | "cancelled";
}

interface EventType {
  id: number;
  name: string;
  duration: number;
  description: string;
}

interface AvailabilityRule {
  id: number;
  event_type_id: number;
  day_of_week: number;
  start_time: string;
  end_time: string;
}

const initSql = `
  CREATE TABLE IF NOT EXISTS bookings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_type_id INTEGER NOT NULL,
    user_name TEXT NOT NULL,
    user_email TEXT NOT NULL,
    start_time TEXT NOT NULL,
    end_time TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending'
  );

  CREATE TABLE IF NOT EXISTS event_types (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    duration INTEGER NOT NULL,
    description TEXT
  );

  CREATE TABLE IF NOT EXISTS availability_rules (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    event_type_id INTEGER NOT NULL,
    day_of_week INTEGER NOT NULL,
    start_time TEXT NOT NULL,
    end_time TEXT NOT NULL
  );
`;

db.exec(initSql);

export function getAllBookings(): Booking[] {
  const stmt = db.prepare("SELECT * FROM bookings");
  return stmt.all() as unknown as Booking[];
}

export function getBookingById(id: number): Booking | undefined {
  const stmt = db.prepare("SELECT * FROM bookings WHERE id = ?");
  return stmt.get(id) as unknown as Booking | undefined;
}

export function createBooking(
  eventTypeId: number,
  userName: string,
  userEmail: string,
  startTime: string,
  endTime: string
): number {
  const stmt = db.prepare(
    "INSERT INTO bookings (event_type_id, user_name, user_email, start_time, end_time) VALUES (?, ?, ?, ?, ?)"
  );
  const result = stmt.run(eventTypeId, userName, userEmail, startTime, endTime);
  return Number(result.lastInsertRowid);
}

export function updateBookingStatus(id: number, status: "confirmed" | "pending" | "cancelled"): void {
  const stmt = db.prepare("UPDATE bookings SET status = ? WHERE id = ?");
  stmt.run(status, id);
}

export function deleteBooking(id: number): void {
  const stmt = db.prepare("DELETE FROM bookings WHERE id = ?");
  stmt.run(id);
}

// Sample data initialization
if (getAllBookings().length === 0) {
  const eventType1Id = createEventType("Team Meeting", 60, "Weekly team sync");
  const eventType2Id = createEventType("One-on-One", 30, "Individual catch-up");

  createBooking(eventType1Id, "John Doe", "john@example.com", "2023-05-15T10:00:00", "2023-05-15T11:00:00");
  createBooking(eventType2Id, "Jane Smith", "jane@example.com", "2023-05-16T14:00:00", "2023-05-16T14:30:00");
  createBooking(eventType1Id, "Bob Johnson", "bob@example.com", "2023-05-17T09:00:00", "2023-05-17T10:00:00");

  // Create some availability rules
  createAvailabilityRule(eventType1Id, 1, "09:00", "17:00");
  createAvailabilityRule(eventType2Id, 2, "10:00", "16:00");
}

function createEventType(name: string, duration: number, description: string): number {
  const stmt = db.prepare(
    "INSERT INTO event_types (name, duration, description) VALUES (?, ?, ?)"
  );
  const result = stmt.run(name, duration, description);
  return Number(result.lastInsertRowid);
}

function createAvailabilityRule(
  eventTypeId: number,
  dayOfWeek: number,
  startTime: string,
  endTime: string
): number {
  const stmt = db.prepare(
    "INSERT INTO availability_rules (event_type_id, day_of_week, start_time, end_time) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(eventTypeId, dayOfWeek, startTime, endTime);
  return Number(result.lastInsertRowid);
}
"}

