  title: string;
  description: string;
  location: string;
  audioContent: string;
}

export function ExhibitManagementPage() {
  const [exhibits, setExhibits] = useState<Exhibit[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [formData, setFormData] = useState<Omit<Exhibit, "id">>({ 
    title: "",
    description: "",
    location: "",
    audioContent: ""
  });
  const [editingId, setEditingId] = useState<number | null>(null);

  // Fetch exhibits
  useEffect(() => {
    const fetchExhibits = async () => {
      try {
        const response = await fetch('/api/exhibits');
        if (!response.ok) throw new Error('Failed to fetch exhibits');
        const data = await response.json();
        setExhibits(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
        setLoading(false);
      }
    };

    fetchExhibits();
  }, []);

  // Handle form input changes
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
  };

  // Handle form submission
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const url = editingId 
        ? `/api/exhibits/${editingId}`
        : '/api/exhibits';

      const method = editingId ? 'PUT' : 'POST';

      const response = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });

      if (!response.ok) throw new Error('Failed to save exhibit');

      // Refresh exhibits list
      const updatedResponse = await fetch('/api/exhibits');
      if (!updatedResponse.ok) throw new Error('Failed to refresh exhibits');
      const updatedData = await updatedResponse.json();
      setExhibits(updatedData);

      // Reset form
      setFormData({ title: '', description: '', location: '', audioContent: '' });
      setEditingId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  // Handle edit
