      title: exhibit.title,
      description: exhibit.description,
      location: exhibit.location,
      audioContent: exhibit.audioContent
    });
    setEditingId(exhibit.id);
  };

  // Handle delete
  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/exhibits/${id}`, { method: 'DELETE' });
      if (!response.ok) throw new Error('Failed to delete exhibit');

      // Refresh exhibits list
      const updatedResponse = await fetch('/api/exhibits');
      if (!updatedResponse.ok) throw new Error('Failed to refresh exhibits');
      const updatedData = await updatedResponse.json();
      setExhibits(updatedData);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  // Filter exhibits based on search term
  const filteredExhibits = exhibits.filter(exhibit => 
    exhibit.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
    exhibit.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
    exhibit.location.toLowerCase().includes(searchTerm.toLowerCase())
