{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  const protectedPaths = [
    "/records",
    "/records/:id",
    "/staff",
    "/staff/:id"
  ];

  const isProtectedPath = protectedPaths.some(path => {
    if (path.includes(":")) {
      const pathWithoutParams = path.replace(/:\w+/g, ".*");
      const regex = new RegExp(`^${pathWithoutParams}$`);
      return regex.test(req.path);
    }
    return req.path === path;
  });

  // Skip validation for non-protected paths
  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if request method is allowed for role-based access
  const allowedMethods = ["GET", "POST", "PUT", "DELETE"];
  if (!allowedMethods.includes(req.method)) {
    next();
    return;
  }

  // Extract role from request headers (assuming it's set by auth middleware)
  const userRole = req.headers["x-user-role"] as string | undefined;

  // Define role permissions
  const rolePermissions: Record<string, string[]> = {
    admin: ["GET", "POST", "PUT", "DELETE"],
    officer: ["GET", "POST", "PUT"],
    clerk: ["GET"]
  };

  // If no role is provided, deny access
  if (!userRole) {
    res.status(403).json({ error: "Access denied: Role not specified" });
    return;
  }

  // Check if the role exists in our permission map
  if (!rolePermissions[userRole]) {
    res.status(403).json({ error: "Access denied: Invalid role" });
    return;
  }

  // Check if the current method is allowed for this role
  if (!rolePermissions[userRole].includes(req.method)) {
    res.status(403).json({ error: "Access denied: Insufficient permissions" });
    return;
  }

  // If we reach here, the user has proper permissions
  next();
}
"}

