{"code":"import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to the export endpoint
  if (req.method !== "POST" || req.path !== "/export") {
    next();
    return;
  }

  // Check if the user is the owner
  // This is a placeholder implementation - in a real app,
  // you'd check the authenticated user against the owner
  const isOwner = req.headers["x-user-role"] === "owner";

  if (!isOwner) {
    res.status(403).json({ error: "Access denied. Only owners can export." });
    return;
  }

  next();
}
