import { FileMetadata, getFileMetadataById, insertFileMetadata, updateFileMetadataSyncState } from "../db/files-metadata-table";

export const router = Router();

router.post("/files", (req: Request, res: Response) => {
  const { ownerId, filePath, sharedWith, syncState } = req.body;
  if (typeof ownerId !== "number" || typeof filePath !== "string" || !Array.isArray(sharedWith) || typeof syncState !== "string") {
    res.status(400).send("Invalid request body");
    return;
  }
  insertFileMetadata(ownerId, filePath, sharedWith, syncState);
  res.status(201).send("File metadata inserted");
});

router.get("/files/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    res.status(400).send("Invalid file ID");
    return;
  }
  const fileMetadata = getFileMetadataById(id);
  if (!fileMetadata) {
    res.status(404).send("File metadata not found");
    return;
  }
  res.json(fileMetadata);
});

router.put("/files/:id/sync-state", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { syncState } = req.body;
  if (isNaN(id) || typeof syncState !== "string") {
    res.status(400).send("Invalid request");
    return;
  }
  updateFileMetadataSyncState(id, syncState);
  res.send("Sync state updated");
});
