];

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // In a real app, we would generate a JWT token here
  return res.json({
    message: "Login successful",
    user: {
      id: user.id,
      username: user.username,
      role: user.role
    }
  });
});

// Logout endpoint
router.post("/logout", (req: Request, res: Response) => {
  // In a real app, we would invalidate the JWT token or session
  return res.json({ message: "Logout successful" });
});

// Role-based access control middleware
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: Function) => {
    // In a real app, this would check the JWT token for user role
    // For now, we'll simulate it with a mock header
    const userRole = req.headers["x-user-role"] as string;

    if (!userRole || !roles.includes(userRole)) {
      return res.status(403).json({ error: "Access denied" });
    }

    next();
  };
};

// Protected route examples
router.get("/admin", authorize(["admin"]), (req: Request, res: Response) => {
  return res.json({ message: "Admin access granted" });
});

router.get("/doctor", authorize(["doctor", "admin"]), (req: Request, res: Response) => {
  return res.json({ message: "Doctor access granted" });
});

