  { id: 2, trainId: 1, seatNumber: "A2", status: "available" },
  { id: 3, trainId: 1, seatNumber: "B1", status: "booked" },
];

// Get all seats for a specific train
router.get("/trains/:trainId/seats", (req: Request, res: Response) => {
  const trainId = Number(req.params.trainId);

  if (isNaN(trainId)) {
    return res.status(400).json({ error: "Invalid train ID" });
  }

  const trainSeats = seats.filter(seat => seat.trainId === trainId);

  if (trainSeats.length === 0) {
    return res.status(404).json({ error: "No seats found for this train" });
  }

  return res.json(trainSeats);
});

// Get a specific seat by ID
router.get("/seats/:id", (req: Request, res: Response) => {
  const seatId = Number(req.params.id);

  if (isNaN(seatId)) {
    return res.status(400).json({ error: "Invalid seat ID" });
  }

  const seat = seats.find(s => s.id === seatId);

  if (!seat) {
    return res.status(404).json({ error: "Seat not found" });
  }

  return res.json(seat);
});

// Allocate a seat
router.post("/trains/:trainId/seats/allocate", (req: Request, res: Response) => {
  const trainId = Number(req.params.trainId);
  const { seatNumber } = req.body;

  if (isNaN(trainId)) {
    return res.status(400).json({ error: "Invalid train ID" });
  }

  if (!seatNumber) {
    return res.status(400).json({ error: "Seat number is required" });
  }

  const seat = seats.find(s => s.trainId === trainId && s.seatNumber === seatNumber);

  if (!seat) {
    return res.status(404).json({ error: "Seat not found" });
  }

  if (seat.status === "booked") {
    return res.status(400).json({ error: "Seat is already booked" });
  }

  // Update seat status to booked
  const updatedSeat = { ...seat, status: "booked" };

  return res.status(200).json(updatedSeat);
});

// Check seat availability
router.get("/trains/:trainId/seats/availability", (req: Request, res: Response) => {
  const trainId = Number(req.params.trainId);

  if (isNaN(trainId)) {
    return res.status(400).json({ error: "Invalid train ID" });
  }

  const trainSeats = seats.filter(seat => seat.trainId === trainId);

  if (trainSeats.length === 0) {
    return res.status(404).json({ error: "No seats found for this train" });
  }

  const availableSeats = trainSeats.filter(seat => seat.status === "available");

  return res.json({
    totalSeats: trainSeats.length,
    availableSeats: availableSeats.length,
    availableSeatNumbers: availableSeats.map(seat => seat.seatNumber)
  });
});
"}

