{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface UsageRecord {
  id: number;
  member_id: number;
  date: string;
  energy_amount: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS usage_records (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    member_id INTEGER NOT NULL,
    date TEXT NOT NULL,
    energy_amount REAL NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllUsageRecords(): UsageRecord[] {
  const stmt = db.prepare(`SELECT * FROM usage_records`);
  return stmt.all() as unknown as UsageRecord[];
}

export function getUsageRecordById(id: number): UsageRecord | undefined {
  const stmt = db.prepare(`SELECT * FROM usage_records WHERE id = ?`);
  return stmt.get(id) as unknown as UsageRecord | undefined;
}

export function insertUsageRecord(
  memberId: number,
  date: string,
  energyAmount: number
): number {
  const stmt = db.prepare(
    `INSERT INTO usage_records (member_id, date, energy_amount) VALUES (?, ?, ?)`
  );
  const result = stmt.run(memberId, date, energyAmount);
  return Number(result.lastInsertRowid);
}

export function updateUsageRecord(
  id: number,
  memberId: number,
  date: string,
  energyAmount: number
): void {
  const stmt = db.prepare(
    `UPDATE usage_records SET member_id = ?, date = ?, energy_amount = ? WHERE id = ?`
  );
  stmt.run(memberId, date, energyAmount, id);
}

export function deleteUsageRecord(id: number): void {
  const stmt = db.prepare(`DELETE FROM usage_records WHERE id = ?`);
  stmt.run(id);
}

// Insert sample data if table is empty
if (getAllUsageRecords().length === 0) {
