{"code":"import { useEffect, useState } from "react";

interface Machine {
  id: number;
  name: string;
  status: string;
}

interface Report {
  id: number;
  machineId: number;
  description: string;
  reportedAt: string;
}

export function BrokenMachineReportForm() {
  const [machines, setMachines] = useState<Machine[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedMachine, setSelectedMachine] = useState<number | null>(null);
  const [description, setDescription] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);

  useEffect(() => {
    fetchMachines();
  }, []);

  const fetchMachines = async () => {
    try {
      const response = await fetch("/api/machine-tracker-api/machines");
      if (!response.ok) {
        throw new Error(`Failed to fetch machines: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setMachines(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (submitting || selectedMachine === null) return;

    setSubmitting(true);
    setSubmitSuccess(false);

    try {
      const response = await fetch("/api/machine-tracker-api/reports", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          machineId: selectedMachine,
          description,
        }),
      });

      if (!response.ok) {
        throw new Error(`Failed to submit report: ${response.status} ${response.statusText}`);
      }

      setSubmitSuccess(true);
      setSelectedMachine(null);
      setDescription("");
      // Refresh the machines list after successful submission
      await fetchMachines();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div style={containerStyle}>
      <h1>Report Broken Machine</h1>

      {submitSuccess && (
        <div style={{
          backgroundColor: "#d4edda",
          color: "#155724",
          padding: "10px",
          borderRadius: "4px",
          marginBottom: "20px",
        }}>
          Report submitted successfully!
        </div>
      )}

      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        <div>
          <label htmlFor="machineSelect" style={{ display: "block", marginBottom: "5px" }}>
            Select Machine:
