export const db = new DatabaseSync("./data.db");

interface SessionRow {
  id: number;
  user_id: number;
  session_token: string;
  created_at: string;
  expires_at: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    session_token TEXT UNIQUE NOT NULL,
    created_at TEXT NOT NULL,
    expires_at TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function insertSession(
  userId: number,
  sessionToken: string,
  createdAt: string,
  expiresAt: string
): number {
  const sql = `INSERT INTO sessions (user_id, session_token, created_at, expires_at)
               VALUES (?, ?, ?, ?)`;
  const result = db.prepare(sql).run(userId, sessionToken, createdAt, expiresAt);
  return Number(result.lastInsertRowid);
}

export function getSessionById(id: number): SessionRow | undefined {
  const sql = `SELECT * FROM sessions WHERE id = ?`;
  const result = db.prepare(sql).get(id);
  return result as unknown as SessionRow | undefined;
}

export function getAllSessions(): SessionRow[] {
  const sql = `SELECT * FROM sessions`;
  const result = db.prepare(sql).all();
  return result as unknown as SessionRow[];
}

export function deleteSessionById(id: number): void {
  const sql = `DELETE FROM sessions WHERE id = ?`;
  db.prepare(sql).run(id);
}

