{"code":"import { Router, type Request, type Response } from "express";
import { db, deleteWalk, getAllWalks, getWalkById, insertWalk, updateWalk } from "../db/walks-table";

export const router = Router();

// Get all walks
router.get("/", (req: Request, res: Response) => {
  try {
    const walks = getAllWalks();
    res.json(walks);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch walks" });
  }
});

// Get a walk by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid walk ID" });
  }

  const walk = getWalkById(id);

  if (!walk) {
    return res.status(404).json({ error: "Walk not found" });
  }

  res.json(walk);
});

// Create a new walk
router.post("/", (req: Request, res: Response) => {
  const { ownerId, walkerId, date, status } = req.body;

  if (!ownerId || !walkerId || !date || !status) {
    return res.status(400).json({ error: "Missing required fields: ownerId, walkerId, date, status" });
  }

  try {
    const id = insertWalk(ownerId, walkerId, date, status);
    const newWalk = getWalkById(id);
    res.status(201).json(newWalk);
  } catch (error) {
    res.status(500).json({ error: "Failed to create walk" });
  }
});

// Update a walk
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { ownerId, walkerId, date, status } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid walk ID" });
  }

  if (!ownerId || !walkerId || !date || !status) {
    return res.status(400).json({ error: "Missing required fields: ownerId, walkerId, date, status" });
  }

  const existingWalk = getWalkById(id);

  if (!existingWalk) {
    return res.status(404).json({ error: "Walk not found" });
  }

  try {
    updateWalk(id, ownerId, walkerId, date, status);
    const updatedWalk = getWalkById(id);
    res.json(updatedWalk);
  } catch (error) {
    res.status(500).json({ error: "Failed to update walk" });
  }
});

// Delete a walk
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid walk ID" });
  }

  const existingWalk = getWalkById(id);

  if (!existingWalk) {
    return res.status(404).json({ error: "Walk not found" });
  }

  try {
    deleteWalk(id);
    res.json({ message: "Walk deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete walk" });
  }
});

// Accept a walk
router.put("/accept/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid walk ID" });
  }

  const existingWalk = getWalkById(id);

  if (!existingWalk) {
    return res.status(404).json({ error: "Walk not found" });
  }

  try {
    updateWalk(id, existingWalk.ownerId, existingWalk.walkerId, existingWalk.date, "accepted");
    const updatedWalk = getWalkById(id);
    res.json(updatedWalk);
  } catch (error) {
    res.status(500).json({ error: "Failed to accept walk" });
  }
});

// Decline a walk
