{"code":"import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process GET requests to /dns-query endpoint
  if (req.method !== "GET" || !req.path?.startsWith("/dns-query")) {
    next();
    return;
  }

  // Check if parental controls are enabled
  const parentalControlsEnabled = process.env.PARENTAL_CONTROLS_ENABLED === "true";
  if (!parentalControlsEnabled) {
    next();
    return;
  }

  // Get query parameters
  const query = req.query.q as string | undefined;
  const searchEngine = req.query.search_engine as string | undefined;

  // If no query or search engine specified, allow through
  if (!query || !searchEngine) {
    next();
    return;
  }

  // Check if query contains adult content indicators
  const adultContentIndicators = [
    "adult", "porn", "xxx", "sex", "nude", "nsa", "fetish"
  ];

  const normalizedQuery = query.toLowerCase();
  const hasAdultContent = adultContentIndicators.some(indicator => 
    normalizedQuery.includes(indicator)
  );

  // If adult content detected, block the request
  if (hasAdultContent) {
    res.status(403).json({
      error: "Parental controls blocked access to adult content",
      blocked: true
    });
    return;
  }

  // For supported search engines, enforce safe search
  const supportedSearchEngines = ["google", "bing", "duckduckgo"];
  if (supportedSearchEngines.includes(searchEngine.toLowerCase())) {
    // Add safe search parameter if not already present
    const safeSearchParam = req.query.safe || "active";

    // If safe search is not active, we might want to enforce it
    // But since this is a DNS-level blocking middleware,
    // we'll just pass through and let the DNS resolver handle it
  }

  // Allow the request to proceed
  next();
}
"}

