{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/tmp/team-chat-app.db"
);

export interface Message {
  id: number;
  text: string;
  channelId: number;
  authorId: number;
  timestamp: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS messages (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    text TEXT NOT NULL,
    channelId INTEGER NOT NULL,
    authorId INTEGER NOT NULL,
    timestamp INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function insertMessage(
  text: string,
  channelId: number,
  authorId: number,
  timestamp: number
): number {
  const sql =
    "INSERT INTO messages (text, channelId, authorId, timestamp) VALUES (?, ?, ?, ?)";
  const result = db.prepare(sql).run(text, channelId, authorId, timestamp);
  return Number(result.lastInsertRowid);
}

export function getMessageById(id: number): Message | undefined {
  const sql = "SELECT * FROM messages WHERE id = ?";
  const result = db.prepare(sql).get(id);
  return result as unknown as Message | undefined;
}

export function getAllMessages(): Message[] {
  const sql = "SELECT * FROM messages";
  const result = db.prepare(sql).all();
  return result as unknown as Message[];
}

export function getMessagesByChannelId(channelId: number): Message[] {
  const sql = "SELECT * FROM messages WHERE channelId = ?";
  const result = db.prepare(sql).all(channelId);
  return result as unknown as Message[];
}

export function updateMessage(
  id: number,
  text: string,
  channelId: number,
  authorId: number,
  timestamp: number
): void {
  const sql =
    "UPDATE messages SET text = ?, channelId = ?, authorId = ?, timestamp = ? WHERE id = ?";
  db.prepare(sql).run(text, channelId, authorId, timestamp, id);
}

export function deleteMessage(id: number): void {
  const sql = "DELETE FROM messages WHERE id = ?";
  db.prepare(sql).run(id);
}

// Seed data
if (getAllMessages().length === 0) {
  const sampleMessages = [
    {
      text: "Hey team, how's the project going?",
      channelId: 1,
      authorId: 101,
      timestamp: Date.now() - 3600000
    },
    {
      text: "I'm working on the UI components right now.",
      channelId: 1,
      authorId: 102,
      timestamp: Date.now() - 1800000
    },
    {
      text: "Great! Let me know when you're done so I can review it.",
      channelId: 1,
      authorId: 103,
      timestamp: Date.now() - 900000
    }
  ];

  sampleMessages.forEach((msg) => {
    insertMessage(
      msg.text,
      msg.channelId,
      msg.authorId,
      msg.timestamp
    );
  });
}
"}

