    id INTEGER PRIMARY KEY AUTOINCREMENT,
    tool_id INTEGER NOT NULL,
    member_id INTEGER NOT NULL,
    checkout_date TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllToolCheckouts(): ToolCheckout[] {
  const stmt = db.prepare(`SELECT * FROM tool_checkouts`);
  return stmt.all() as unknown as ToolCheckout[];
}

export function getToolCheckoutById(id: number): ToolCheckout | undefined {
  const stmt = db.prepare(`SELECT * FROM tool_checkouts WHERE id = ?`);
  return stmt.get(id) as unknown as ToolCheckout | undefined;
}

export function insertToolCheckout(
  toolId: number,
  memberId: number,
  checkoutDate: string
): number {
  const stmt = db.prepare(
    `INSERT INTO tool_checkouts (tool_id, member_id, checkout_date) VALUES (?, ?, ?)`
  );
  const result = stmt.run(toolId, memberId, checkoutDate);
  return Number(result.lastInsertRowid);
}

export function updateToolCheckout(
  id: number,
  toolId: number,
  memberId: number,
  checkoutDate: string
): number {
  const stmt = db.prepare(
    `UPDATE tool_checkouts SET tool_id = ?, member_id = ?, checkout_date = ? WHERE id = ?`
  );
  const result = stmt.run(toolId, memberId, checkoutDate, id);
  return Number(result.changes);
}

export function deleteToolCheckout(id: number): number {
