{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteToolCheckout,
  getAllToolCheckouts,
  getToolCheckoutById,
  insertToolCheckout,
  updateToolCheckout
} from "../db/tool-checkouts-table";

export const router = Router();

// Get all tool checkouts
router.get("/", (req: Request, res: Response) => {
  const checkouts = getAllToolCheckouts();
  res.json(checkouts);
});

// Get a specific tool checkout by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid ID" });
  }

  const checkout = getToolCheckoutById(id);

  if (!checkout) {
    return res.status(404).json({ error: "Tool checkout not found" });
  }

  res.json(checkout);
});

// Create a new tool checkout
router.post("/", (req: Request, res: Response) => {
  const { toolId, memberId, checkoutDate } = req.body;

  if (!toolId || !memberId || !checkoutDate) {
    return res.status(400).json({ error: "Missing required fields: toolId, memberId, checkoutDate" });
  }

  const newId = insertToolCheckout(toolId, memberId, checkoutDate);

  if (newId === -1) {
    return res.status(400).json({ error: "Failed to create tool checkout" });
  }

  const newCheckout = getToolCheckoutById(newId);

  if (!newCheckout) {
    return res.status(400).json({ error: "Failed to retrieve created tool checkout" });
  }

  res.status(201).json(newCheckout);
});

// Update a tool checkout
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { toolId, memberId, checkoutDate } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid ID" });
  }

  if (!toolId || !memberId || !checkoutDate) {
    return res.status(400).json({ error: "Missing required fields: toolId, memberId, checkoutDate" });
  }

  const updatedId = updateToolCheckout(id, toolId, memberId, checkoutDate);

  if (updatedId === -1) {
    return res.status(404).json({ error: "Tool checkout not found" });
  }

  const updatedCheckout = getToolCheckoutById(updatedId);

  if (!updatedCheckout) {
    return res.status(400).json({ error: "Failed to retrieve updated tool checkout" });
  }

  res.json(updatedCheckout);
});

// Delete a tool checkout
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid ID" });
  }

  const deletedId = deleteToolCheckout(id);

  if (deletedId === -1) {
    return res.status(404).json({ error: "Tool checkout not found" });
  }

  res.json({ message: "Tool checkout deleted successfully" });
});
"}

