const mockActivities = [
  { id: 1, name: "Planting Corn", date: "2023-05-15", cropType: "Corn", area: 10, status: "Completed" },
  { id: 2, name: "Fertilizing Wheat", date: "2023-06-20", cropType: "Wheat", area: 15, status: "In Progress" },
  { id: 3, name: "Harvesting Soybeans", date: "2023-07-10", cropType: "Soybeans", area: 8, status: "Pending" }
];

const findActivityById = (id: number) => {
  return mockActivities.find(activity => activity.id === id);
};

const createActivity = (activity: any) => {
  const newId = Math.max(0, ...mockActivities.map(a => a.id)) + 1;
  const newActivity = { ...activity, id: newId };
  mockActivities.push(newActivity);
  return newActivity;
};

const updateActivity = (id: number, updatedFields: any) => {
  const index = mockActivities.findIndex(activity => activity.id === id);
  if (index === -1) return null;
  mockActivities[index] = { ...mockActivities[index], ...updatedFields };
  return mockActivities[index];
};

const deleteActivity = (id: number) => {
  const index = mockActivities.findIndex(activity => activity.id === id);
  if (index === -1) return false;
  mockActivities.splice(index, 1);
  return true;
};

// GET /activities - List all activities
router.get("/activities", (req: Request, res: Response) => {
  res.json(mockActivities);
});

// GET /activities/:id - Get one activity by ID
router.get("/activities/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid activity ID" });
  }

  const activity = findActivityById(id);
  if (!activity) {
    return res.status(404).json({ error: "Activity not found" });
  }

  res.json(activity);
});

// POST /activities - Create a new activity
router.post("/activities", (req: Request, res: Response) => {
  const { name, date, cropType, area, status } = req.body;

  if (!name || !date || !cropType || area === undefined || !status) {
    return res.status(400).json({ error: "Missing required fields: name, date, cropType, area, status" });
  }

  const newActivity = createActivity({ name, date, cropType, area, status });
  res.status(201).json(newActivity);
});

// PUT /activities/:id - Update an existing activity
router.put("/activities/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid activity ID" });
  }

  const { name, date, cropType, area, status } = req.body;

  const updatedActivity = updateActivity(id, { name, date, cropType, area, status });

  if (!updatedActivity) {
    return res.status(404).json({ error: "Activity not found" });
  }

  res.json(updatedActivity);
});

// DELETE /activities/:id - Delete an activity
router.delete("/activities/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid activity ID" });
  }

  const deleted = deleteActivity(id);

  if (!deleted) {
    return res.status(404).json({ error: "Activity not found" });
  }

  res.json({ message: "Activity deleted successfully" });
});

