{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data structures to simulate database operations
const classes = [
  { id: "1", name: "Yoga", schedule: "Mon Wed Fri 6PM", maxEnrollment: 15 },
  { id: "2", name: "Spinning", schedule: "Tue Thu 7PM", maxEnrollment: 10 }
];

const enrollments = [
  { classId: "1", memberId: "101" },
  { classId: "1", memberId: "102" },
  { classId: "2", memberId: "103" }
];

const attendance = [
  { classId: "1", memberId: "101", date: "2023-04-01", attended: true },
  { classId: "1", memberId: "102", date: "2023-04-01", attended: false }
];

// Get all classes
router.get("/classes", (req: Request, res: Response) => {
  res.json(classes);
});

// Get a specific class by ID
router.get("/classes/:id", (req: Request, res: Response) => {
  const classId = req.params.id;
  const cls = classes.find(c => c.id === classId);

  if (!cls) {
    return res.status(404).json({ error: "Class not found" });
  }

  res.json(cls);
});

// Create a new class
router.post("/classes", (req: Request, res: Response) => {
  const { name, schedule, maxEnrollment } = req.body;

  if (!name || !schedule || !maxEnrollment) {
    return res.status(400).json({ error: "Name, schedule, and maxEnrollment are required" });
  }

  const newClass = {
    id: String(classes.length + 1),
    name,
    schedule,
    maxEnrollment: Number(maxEnrollment)
  };

  classes.push(newClass);
  res.status(201).json(newClass);
});

// Update a class
router.put("/classes/:id", (req: Request, res: Response) => {
  const classId = req.params.id;
  const { name, schedule, maxEnrollment } = req.body;

  const classIndex = classes.findIndex(c => c.id === classId);

  if (classIndex === -1) {
    return res.status(404).json({ error: "Class not found" });
  }

  if (!name || !schedule || !maxEnrollment) {
    return res.status(400).json({ error: "Name, schedule, and maxEnrollment are required" });
  }

  classes[classIndex] = {
    ...classes[classIndex],
    name,
    schedule,
    maxEnrollment: Number(maxEnrollment)
  };

  res.json(classes[classIndex]);
});

// Delete a class
router.delete("/classes/:id", (req: Request, res: Response) => {
  const classId = req.params.id;
  const classIndex = classes.findIndex(c => c.id === classId);

  if (classIndex === -1) {
    return res.status(404).json({ error: "Class not found" });
  }

  classes.splice(classIndex, 1);
  res.json({ message: "Class deleted successfully" });
});

// Enroll member in a class
router.post("/classes/:id/enroll", (req: Request, res: Response) => {
  const classId = req.params.id;
  const { memberId } = req.body;

  if (!memberId) {
    return res.status(400).json({ error: "Member ID is required" });
  }

  const cls = classes.find(c => c.id === classId);

  if (!cls) {
    return res.status(404).json({ error: "Class not found" });
  }

  // Check if class is full
  const currentEnrollments = enrollments.filter(e => e.classId === classId);

  if (currentEnrollments.length >= cls.maxEnrollment) {
    return res.status(400).json({ error: "Class is full" });
  }

  // Check if member is already enrolled
  const existingEnrollment = enrollments.find(e => e.classId === classId && e.memberId === memberId);

  if (existingEnrollment) {
    return res.status(400).json({ error: "Member already enrolled" });
  }

  const newEnrollment = { classId, memberId };
  enrollments.push(newEnrollment);

  res.status(201).json(newEnrollment);
});

// Track attendance
router.post("/classes/:id/attendance", (req: Request, res: Response) => {
  const classId = req.params.id;
  const { memberId, date, attended } = req.body;

  if (!memberId || !date || typeof attended !== "boolean") {
    return res.status(400).json({ error: "Member ID, date, and attended status are required" });
  }

  const newAttendance = { classId, memberId, date, attended };
  attendance.push(newAttendance);

  res.status(201).json(newAttendance);
});
"}

