{"code":"import { useEffect, useState } from "react";

interface Checkout {
  id: number;
  memberName: string;
  packetName: string;
  checkoutDate: string;
  dueDate: string;
}

export function CheckoutQueue() {
  const [checkouts, setCheckouts] = useState<Checkout[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newCheckout, setNewCheckout] = useState({
    memberName: "",
    packetName: ""
  });

  useEffect(() => {
    fetchCheckouts();
  }, []);

  const fetchCheckouts = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/checkouts-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setCheckouts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleCheckout = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/checkouts-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newCheckout)
      });
      if (!response.ok) {
        throw new Error(`Failed to checkout: ${response.status} ${response.statusText}`);
      }
      setNewCheckout({ memberName: "", packetName: "" });
      fetchCheckouts();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleReturn = async (id: number) => {
    try {
      const response = await fetch(`/api/checkouts-api/${id}`, {
        method: "PUT"
      });
      if (!response.ok) {
        throw new Error(`Failed to return: ${response.status} ${response.statusText}`);
      }
      fetchCheckouts();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/checkouts-api/${id}`, {
        method: "DELETE"
      });
      if (!response.ok) {
        throw new Error(`Failed to delete: ${response.status} ${response.statusText}`);
      }
      fetchCheckouts();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Checkout Queue</h1>

      <div style={{ marginBottom: "30px", padding: "15px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2 style={{ marginTop: "0" }}>Check Out a Packet</h2>
        <form onSubmit={handleCheckout}>
          <div style={{ marginBottom: "10px" }}>
            <label htmlFor="memberName" style={{ display: "block", marginBottom: "5px" }}>Member Name:</label>
            <input
              id="memberName"
              type="text"
              value={newCheckout.memberName}
              onChange={(e) => setNewCheckout({...newCheckout, memberName: e.target.value})}
              style={{ width: "100%", padding: "8px", boxSizing: "border-box" }}
              required
            />
          </div>
          <div style={{ marginBottom: "10px" }}>
            <label htmlFor="packetName" style={{ display: "block", marginBottom: "5px" }}>Packet Name:</label>
            <input
              id="packetName"
              type="text"
              value={newCheckout.packetName}
