{"code":"import { useEffect, useState } from "react";

interface Meal {
  id: string;
  name: string;
  description: string;
  price: number;
  available: boolean;
}

interface Order {
  id: string;
  mealId: string;
  quantity: number;
  status: 'pending' | 'confirmed' | 'preparing' | 'ready' | 'delivered';
  createdAt: string;
}

export function UserDashboard() {
  const [meals, setMeals] = useState<Meal[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedMealId, setSelectedMealId] = useState<string>('');
  const [quantity, setQuantity] = useState(1);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [mealsResponse, ordersResponse] = await Promise.all([
          fetch('/api/meal-management-service/meals'),
          fetch('/api/order-management-service/')
        ]);

        if (!mealsResponse.ok || !ordersResponse.ok) {
          throw new Error('Failed to fetch data');
        }

        const mealsData = await mealsResponse.json();
        const ordersData = await ordersResponse.json();

        setMeals(mealsData);
        setOrders(ordersData);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handlePlaceOrder = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedMealId) return;

    try {
      const response = await fetch('/api/order-management-service/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          mealId: selectedMealId,
          quantity
        })
      });

      if (!response.ok) {
        throw new Error('Failed to place order');
      }

      // Refresh data
      const ordersResponse = await fetch('/api/order-management-service/');
      const ordersData = await ordersResponse.json();
      setOrders(ordersData);

      // Reset form
      setSelectedMealId('');
      setQuantity(1);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>User Dashboard</h1>

      <section style={{ marginBottom: '30px' }}>
        <h2>Available Meals</h2>
        {meals.length === 0 ? (
          <p>No meals available.</p>
        ) : (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '15px' }}>
            {meals
              .filter(meal => meal.available)
              .map(meal => (
                <div key={meal.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px', width: '200px' }}>
                  <h3>{meal.name}</h3>
                  <p>{meal.description}</p>
                  <p><strong>${meal.price.toFixed(2)}</strong></p>
                </div>
              ))}
          </div>
        )}
      </section>

      <section style={{ marginBottom: '30px' }}>
        <h2>Place Order</h2>
        <form onSubmit={handlePlaceOrder} style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          <label>
            Select Meal:
            <select
              value={selectedMealId}
              onChange={(e) => setSelectedMealId(e.target.value)}
              style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
            >
              <option value="">Choose a meal</option>
              {meals
                .filter(meal => meal.available)
                .map(meal => (
                  <option key={meal.id} value={meal.id}>{meal.name}</option>
                ))}
            </select>
          </label>

          <label>
            Quantity:
            <input
              type="number"
              min="1"
              value={quantity}
              onChange={(e) => setQuantity(Number(e.target.value))}
              style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
            />
          </label>

          <button 
            type="submit" 
            style={{ 
              backgroundColor: '#007bff', 
              color: 'white', 
              border: 'none', 
              padding: '10px 15px', 
              borderRadius: '4px', 
              cursor: 'pointer' 
            }}
          >
            Place Order
          </button>
        </form>
      </section>

      <section>
        <h2>Your Orders</h2>
        {orders.length === 0 ? (
          <p>No orders placed yet.</p>
        ) : (
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ borderBottom: '1px solid #ccc' }}>
                <th style={{ textAlign: 'left', padding: '10px' }}>Meal</th>
                <th style={{ textAlign: 'left', padding: '10px' }}>Quantity</th>
                <th style={{ textAlign: 'left', padding: '10px' }}>Status</th>
                <th style={{ textAlign: 'left', padding: '10px' }}>Date</th>
              </tr>
            </thead>
            <tbody>
              {orders.map(order => {
                const meal = meals.find(m => m.id === order.mealId);
                return (
                  <tr key={order.id} style={{ borderBottom: '1px solid #eee' }}>
                    <td style={{ padding: '10px' }}>{meal?.name || 'Unknown Meal'}</td>
                    <td style={{ padding: '10px' }}>{order.quantity}</td>
                    <td style={{ padding: '10px' }}>{order.status}</td>
                    <td style={{ padding: '10px' }}>{new Date(order.createdAt).toLocaleDateString()}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </section>
    </div>
  );
}
"}

