  if (!memberId || !planType || !billingCycle || !renewalDate || !status) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const newMembership = {
    id: String(memberships.length + 1),
    memberId,
    planType,
    billingCycle,
    renewalDate,
    status
  };

  memberships.push(newMembership);
  res.status(201).json(newMembership);
});

// Update a membership
router.put("/:id", (req: Request, res: Response) => {
  const index = memberships.findIndex(m => m.id === req.params.id);
  if (index === -1) {
    return res.status(404).json({ error: "Membership not found" });
  }

  const { memberId, planType, billingCycle, renewalDate, status } = req.body;

  // Validate required fields
  if (!memberId || !planType || !billingCycle || !renewalDate || !status) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  memberships[index] = {
    id: req.params.id,
    memberId,
    planType,
    billingCycle,
    renewalDate,
    status
  };

  res.json(memberships[index]);
});

// Delete a membership
router.delete("/:id", (req: Request, res: Response) => {
  const index = memberships.findIndex(m => m.id === req.params.id);
  if (index === -1) {
    return res.status(404).json({ error: "Membership not found" });
  }

  memberships.splice(index, 1);
  res.json({ message: "Membership deleted successfully" });
});
