const users = [
  { id: 1, username: "admin", password: "admin123", role: "administrator" },
  { id: 2, username: "worker", password: "worker123", role: "staff" }
];

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // In a real app, we would generate a JWT token here
  res.json({
    user: {
      id: user.id,
      username: user.username,
      role: user.role
    },
    token: "mock-jwt-token"
  });
});

// Logout endpoint
router.post("/logout", (req: Request, res: Response) => {
  // In a real app, we would invalidate the JWT token or clear session
  res.json({ message: "Logged out successfully" });
});

// Middleware to check if user has required role
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    // In a real app, we would decode the JWT token and check the role
    const userRole = "administrator"; // Mock role for demo purposes

    if (userRole !== requiredRole) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }

    next();
  };
};

// Get all users (requires administrator role)
router.get("/users", requireRole("administrator"), (req: Request, res: Response) => {
  res.json(users);
});

// Get user by ID (requires administrator role)
router.get("/users/:id", requireRole("administrator"), (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const user = users.find(u => u.id === id);

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  res.json(user);
});

// Create new user (requires administrator role)
router.post("/users", requireRole("administrator"), (req: Request, res: Response) => {
  const { username, password, role } = req.body;

  if (!username || !password || !role) {
    return res.status(400).json({ error: "Username, password, and role are required" });
  }

  const newUser = {
    id: users.length + 1,
    username,
    password,
    role
  };

  users.push(newUser);
  res.status(201).json(newUser);
});

// Update user (requires administrator role)
router.put("/users/:id", requireRole("administrator"), (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const userIndex = users.findIndex(u => u.id === id);

  if (userIndex === -1) {
    return res.status(404).json({ error: "User not found" });
  }

  const { username, password, role } = req.body;

  if (!username || !password || !role) {
    return res.status(400).json({ error: "Username, password, and role are required" });
  }

  users[userIndex] = { id, username, password, role };
  res.json(users[userIndex]);
});

// Delete user (requires administrator role)
router.delete("/users/:id", requireRole("administrator"), (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const userIndex = users.findIndex(u => u.id === id);

  if (userIndex === -1) {
    return res.status(404).json({ error: "User not found" });
  }

  users.splice(userIndex, 1);
  res.json({ message: "User deleted successfully" });
});
"}

