{"code":"import { Router, type Request, type Response } from "express";
import { ShortUrlRow, insertShortUrl, getShortUrlByCode, updateVisitAnalytics } from "../db/short-urls-table";

export const router = Router();

router.post("/shorten", (req: Request, res: Response) => {
  const { shortCode, targetUrl } = req.body;
  if (typeof shortCode !== "string" || typeof targetUrl !== "string") {
    res.status(400).send("Invalid input");
    return;
  }
  insertShortUrl(shortCode, targetUrl);
  res.status(201).json({ shortCode, targetUrl });
});

router.get("/:shortCode", (req: Request, res: Response) => {
  const shortCode = req.params.shortCode;
  const shortUrl = getShortUrlByCode(shortCode);
  if (!shortUrl) {
    res.status(404).send("Short URL not found");
    return;
  }
  const visitorCountry = req.headers["cf-ipcountry"] as string || "Unknown";
  updateVisitAnalytics(shortCode, visitorCountry);
  res.redirect(shortUrl.targetUrl);
});
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data structures to simulate database operations
const rides = [] as Array<{ id: string; driverId: string; origin: string; destination: string; departureTime: string; availableSeats: number; passengers: string[] }>;
const users = [] as Array<{ id: string; name: string; role: string }>;

// Helper function to generate a unique ID
const generateId = () => Math.random().toString(36).substr(2, 9);

// Create a new ride
router.post("/rides", (req: Request, res: Response) => {
  const { driverId, origin, destination, departureTime, availableSeats } = req.body;

  if (!driverId || !origin || !destination || !departureTime || availableSeats === undefined) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const newRide = {
    id: generateId(),
    driverId,
    origin,
    destination,
    departureTime,
    availableSeats,
    passengers: []
  };

  rides.push(newRide);
  return res.status(201).json(newRide);
});

// Get all rides
router.get("/rides", (req: Request, res: Response) => {
  return res.json(rides);
});

// Get a specific ride by ID
router.get("/rides/:id", (req: Request, res: Response) => {
  const rideId = req.params.id;
  const ride = rides.find(r => r.id === rideId);

  if (!ride) {
    return res.status(404).json({ error: "Ride not found" });
  }

  return res.json(ride);
});

// Update a ride
router.put("/rides/:id", (req: Request, res: Response) => {
  const rideId = req.params.id;
  const rideIndex = rides.findIndex(r => r.id === rideId);

  if (rideIndex === -1) {
    return res.status(404).json({ error: "Ride not found" });
  }

  const { driverId, origin, destination, departureTime, availableSeats } = req.body;

  if (!driverId || !origin || !destination || !departureTime || availableSeats === undefined) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  rides[rideIndex] = {
    ...rides[rideIndex],
    driverId,
    origin,
    destination,
    departureTime,
    availableSeats
  };

  return res.json(rides[rideIndex]);
});

// Delete a ride
router.delete("/rides/:id", (req: Request, res: Response) => {
  const rideId = req.params.id;
  const rideIndex = rides.findIndex(r => r.id === rideId);

  if (rideIndex === -1) {
    return res.status(404).json({ error: "Ride not found" });
  }

  rides.splice(rideIndex, 1);
  return res.json({ message: "Ride deleted successfully" });
});

// Search for rides based on criteria
router.get("/rides/search", (req: Request, res: Response) => {
  const { origin, destination, departureTime } = req.query;

  let filteredRides = rides;

  if (origin) {
    filteredRides = filteredRides.filter(ride => ride.origin.toLowerCase() === origin.toString().toLowerCase());
  }

  if (destination) {
    filteredRides = filteredRides.filter(ride => ride.destination.toLowerCase() === destination.toString().toLowerCase());
  }

  if (departureTime) {
    filteredRides = filteredRides.filter(ride => ride.departureTime === departureTime.toString());
  }

  return res.json(filteredRides);
});

// Match passengers with available rides
router.post("/rides/:id/passengers", (req: Request, res: Response) => {
  const rideId = req.params.id;
  const { passengerId } = req.body;

  if (!passengerId) {
    return res.status(400).json({ error: "Passenger ID is required" });
  }

  const ride = rides.find(r => r.id === rideId);

  if (!ride) {
    return res.status(404).json({ error: "Ride not found" });
  }

  if (ride.availableSeats <= 0) {
    return res.status(400).json({ error: "No available seats on this ride" });
  }

  // Add passenger to the ride
  ride.passengers.push(passengerId);
  ride.availableSeats -= 1;

  return res.json(ride);
});
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./csa-box.db");

interface BoxCustomization {
  id: number;
  member_id: number;
  week_date: string;
  chosen_items: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS box_customizations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    member_id INTEGER NOT NULL,
    week_date TEXT NOT NULL,
    chosen_items TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllBoxCustomizations(): BoxCustomization[] {
  const stmt = db.prepare("SELECT * FROM box_customizations");
  return stmt.all() as unknown as BoxCustomization[];
}

export function getBoxCustomizationById(id: number): BoxCustomization | undefined {
  const stmt = db.prepare("SELECT * FROM box_customizations WHERE id = ?");
  return stmt.get(id) as unknown as BoxCustomization | undefined;
}

export function insertBoxCustomization(
  member_id: number,
  week_date: string,
  chosen_items: string
): number {
  const stmt = db.prepare(
    "INSERT INTO box_customizations (member_id, week_date, chosen_items) VALUES (?, ?, ?)"
  );
  const result = stmt.run(member_id, week_date, chosen_items);
  return Number(result.lastInsertRowid);
}

export function updateBoxCustomization(
  id: number,
  member_id: number,
  week_date: string,
  chosen_items: string
): void {
  const stmt = db.prepare(
    "UPDATE box_customizations SET member_id = ?, week_date = ?, chosen_items = ? WHERE id = ?"
  );
  stmt.run(member_id, week_date, chosen_items, id);
}

export function deleteBoxCustomization(id: number): void {
  const stmt = db.prepare("DELETE FROM box_customizations WHERE id = ?");
  stmt.run(id);
}

// Insert sample data if table is empty
if (getAllBoxCustomizations().length === 0) {
  insertBoxCustomization(1, "2023-06-01", "Apples, Carrots");
  insertBoxCustomization(2, "2023-06-08", "Broccoli, Spinach");
  insertBoxCustomization(3, "2023-06-15", "Tomatoes, Lettuce");
  insertBoxCustomization(4, "2023-06-22", "Cucumbers, Bell Peppers");
  insertBoxCustomization(5, "2023-06-29", "Potatoes, Onions");
}
"}

