      return res.status(400).json({ error: "Name, email, and phone are required" });
    }

    const newCustomer = mockDatabase.createCustomer({ name, email, phone });
    res.status(201).json(newCustomer);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// PUT /customers/:id - Update an existing customer
router.put("/customers/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid customer ID" });
    }

    const { name, email, phone } = req.body;

    const updatedCustomer = mockDatabase.updateCustomer(id, { name, email, phone });

    if (!updatedCustomer) {
      return res.status(404).json({ error: "Customer not found" });
    }

    res.json(updatedCustomer);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// DELETE /customers/:id - Delete a customer
router.delete("/customers/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid customer ID" });
    }

    const deleted = mockDatabase.deleteCustomer(id);

    if (!deleted) {
      return res.status(404).json({ error: "Customer not found" });
    }

    res.json({ message: "Customer deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});
"}

