{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/tmp/brewery-keg-inventory.db"
);

interface Keg {
  id: number;
  style: string;
  size: number;
  current_count: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS kegs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    style TEXT NOT NULL,
    size INTEGER NOT NULL,
    current_count INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllKegs(): Keg[] {
  const stmt = db.prepare(`SELECT * FROM kegs`);
  return stmt.all() as unknown as Keg[];
}

export function getKegById(id: number): Keg | undefined {
  const stmt = db.prepare(`SELECT * FROM kegs WHERE id = ?`);
  return stmt.get(id) as unknown as Keg | undefined;
}

export function insertKeg(style: string, size: number, current_count: number): number {
  const stmt = db.prepare(
    `INSERT INTO kegs (style, size, current_count) VALUES (?, ?, ?)`
  );
  const result = stmt.run(style, size, current_count);
  return Number(result.lastInsertRowid);
}

export function updateKeg(id: number, style: string, size: number, current_count: number): void {
  const stmt = db.prepare(
    `UPDATE kegs SET style = ?, size = ?, current_count = ? WHERE id = ?`
  );
  stmt.run(style, size, current_count, id);
}

export function deleteKeg(id: number): void {
  const stmt = db.prepare(`DELETE FROM kegs WHERE id = ?`);
  stmt.run(id);
}

