  doctorId: number,
  memberId: number,
  timeSlot: string
): number {
  const stmt = db.prepare(
    `INSERT INTO appointments (doctorId, memberId, timeSlot) VALUES (?, ?, ?)`
  );
  const result = stmt.run(doctorId, memberId, timeSlot);
  return Number(result.lastInsertRowid);
}

