{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real implementation these would connect to a database
const mockVisits = [
  { id: 1, customerId: 101, date: "2023-05-15", notes: "Initial meeting" },
  { id: 2, customerId: 102, date: "2023-05-16", notes: "Follow-up call" }
];

const findVisitById = (id: number) => {
  return mockVisits.find(visit => visit.id === id);
};

const createVisit = (visitData: Omit<Visit, 'id'>) => {
  const newVisit = {
    id: mockVisits.length > 0 ? Math.max(...mockVisits.map(v => v.id)) + 1 : 1,
    ...visitData
  };
  mockVisits.push(newVisit);
  return newVisit;
};

const updateVisit = (id: number, updateData: Partial<Visit>) => {
  const index = mockVisits.findIndex(visit => visit.id === id);
  if (index === -1) return null;

  mockVisits[index] = { ...mockVisits[index], ...updateData };
  return mockVisits[index];
};

const deleteVisit = (id: number) => {
  const index = mockVisits.findIndex(visit => visit.id === id);
  if (index === -1) return false;

  mockVisits.splice(index, 1);
  return true;
};

// Define the Visit interface
interface Visit {
  id: number;
  customerId: number;
  date: string;
  notes: string;
}

// GET /visits - List all visits
router.get("/visits", (req: Request, res: Response) => {
  res.json(mockVisits);
});

// GET /visits/:id - Get a specific visit by ID
router.get("/visits/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid visit ID" });
  }

  const visit = findVisitById(id);

  if (!visit) {
    return res.status(404).json({ error: "Visit not found" });
  }

  res.json(visit);
});

// POST /visits - Create a new visit
router.post("/visits", (req: Request, res: Response) => {
  const { customerId, date, notes } = req.body;

  if (!customerId || !date || !notes) {
    return res.status(400).json({ error: "customerId, date, and notes are required" });
  }

  const newVisit = createVisit({ customerId, date, notes });

  res.status(201).json(newVisit);
});

// PUT /visits/:id - Update an existing visit
router.put("/visits/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid visit ID" });
  }

  const { customerId, date, notes } = req.body;

  const updatedVisit = updateVisit(id, { customerId, date, notes });

  if (!updatedVisit) {
    return res.status(404).json({ error: "Visit not found" });
  }

  res.json(updatedVisit);
});

// DELETE /visits/:id - Delete a visit
router.delete("/visits/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid visit ID" });
  }

  const deleted = deleteVisit(id);

  if (!deleted) {
    return res.status(404).json({ error: "Visit not found" });
  }

  res.json({ message: "Visit deleted successfully" });
});
"}

