{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock tax rates for different categories
const taxRates = {
  electronics: 0.18,
  clothing: 0.05,
  food: 0.02,
  books: 0.0,
  services: 0.18
};

// Mock business rules
const businessRules = {
  // Minimum taxable amount
  minTaxableAmount: 100,
  // Maximum tax rate
  maxTaxRate: 0.28
};

/**
 * Calculates GST for a product or service
 */
router.post("/calculate-gst", (req: Request, res: Response) => {
  try {
    const { category, amount } = req.body;

    // Validate input
    if (!category || typeof amount !== 'number' || amount < 0) {
      return res.status(400).json({
        error: "Invalid input: category and positive amount required"
      });
    }

    // Get tax rate for category
    const taxRate = taxRates[category as keyof typeof taxRates];

    if (taxRate === undefined) {
      return res.status(400).json({
        error: "Invalid category: unknown product/service category"
      });
    }

    // Apply business rules
    const finalTaxRate = Math.min(taxRate, businessRules.maxTaxRate);

    // Calculate GST
    const gst = amount * finalTaxRate;

    // Ensure minimum taxable amount
    const taxableAmount = Math.max(amount, businessRules.minTaxableAmount);

    // Return result
    return res.json({
      category,
      amount,
      taxRate: finalTaxRate,
      gst,
      taxableAmount
    });
  } catch (error) {
    return res.status(500).json({
      error: "Internal server error"
    });
  }
});
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { router as auditionsRouter } from "../routes/auditions-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check casting notes access for requests to the auditions API
  if (!req.path.startsWith("/api/auditions")) {
    next();
    return;
  }

  // For casting note related routes, check role
  const castingNoteRoutes = ["/api/auditions/:id/casting-notes"];

  if (castingNoteRoutes.some(route => req.path.includes(route))) {
    // In a real implementation, this would check user roles from a token
    // For now, we'll simulate the role check
    const userRole = req.headers["x-user-role"] as string | undefined;

    if (userRole !== "director") {
      // Return empty array or null for non-directors
      res.status(200).json([]);
      return;
    }
  }

  next();
}
"}

