{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

// Define the role map with explicit types
const roleMap: Record<string, string[]> = {
  "/orders": ["admin", "staff"],
  "/menu": ["admin", "staff"],
  "/users": ["admin"]
};

// Helper to check if user has required role
function hasRequiredRole(userRoles: string[], requiredRoles: string[]): boolean {
  return userRoles.some(role => requiredRoles.includes(role));
}

// Middleware function
export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check routes that are defined in roleMap
  const matchedRoute = Object.keys(roleMap).find(route => 
    req.path.startsWith(route)
  );

  // If no matching route found, skip validation
  if (!matchedRoute) {
    next();
    return;
  }

  // Get required roles for this route
  const requiredRoles = roleMap[matchedRoute];

  // Check if user has required role
  const userRoles = req.headers["x-user-roles"] as string | string[] || [];
  const rolesArray = Array.isArray(userRoles) ? userRoles : [userRoles];

  if (hasRequiredRole(rolesArray, requiredRoles)) {
    next();
  } else {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
  }
}
"}

{"code":"import { useEffect, useState } from "react";

interface Reservation {
  id: string;
  spotNumber: string;
  startTime: string;
  endTime: string;
}

export function ReservationWidget() {
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newReservation, setNewReservation] = useState({
    spotNumber: "",
    startTime: "",
    endTime: ""
  });

  useEffect(() => {
    fetchReservations();
  }, []);

  const fetchReservations = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/reservations-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch reservations: ${response.status}`);
      }
      const data = await response.json();
      setReservations(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewReservation(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/reservations-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newReservation)
      });
      if (!response.ok) {
        throw new Error(`Failed to create reservation: ${response.status}`);
      }
      await fetchReservations();
      setNewReservation({ spotNumber: "", startTime: "", endTime: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/reservations-api/${id}`, {
        method: "DELETE"
      });
      if (!response.ok) {
        throw new Error(`Failed to delete reservation: ${response.status}`);
      }
      await fetchReservations();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Parking Reservation</h1>

      <h2 style={{ marginTop: "30px" }}>Your Reservations</h2>
      {reservations.length === 0 ? (
        <p style={{ textAlign: "center", color: "#666" }}>No reservations found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {reservations.map(res => (
            <div key={res.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <strong>Spot:</strong> {res.spotNumber}<br />
                <strong>From:</strong> {new Date(res.startTime).toLocaleString()}<br />
                <strong>To:</strong> {new Date(res.endTime).toLocaleString()}
              </div>
              <button 
                onClick={() => handleDelete(res.id)}
                style={{ backgroundColor: "#ff4d4d", color: "white", border: "none", borderRadius: "4px", padding: "8px 12px", cursor: "pointer" }}
              >
                Cancel
              </button>
            </div>
          ))}
        </div>
      )}

      <h2 style={{ marginTop: "30px" }}>Make a New Reservation</h2>
      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          name="spotNumber"
          placeholder="Spot Number"
          value={newReservation.spotNumber}
          onChange={handleInputChange}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        />
        <input
          type="datetime-local"
          name="startTime"
          value={newReservation.startTime}
          onChange={handleInputChange}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        />
        <input
          type="datetime-local"
          name="endTime"
          value={newReservation.endTime}
          onChange={handleInputChange}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        />
        <button 
          type="submit"
          style={{ backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px", padding: "10px", cursor: "pointer" }}
        >
          Reserve Spot
        </button>
      </form>
    </div>
  );
}
