export interface ExportRecord {
  id: number;
  requester_email: string;
  export_type: string;
  export_date: string;
  export_status: string;
}

export function getAllExportRecords(): ExportRecord[] {
  const stmt = db.prepare(
    "SELECT * FROM export_records ORDER BY export_date DESC"
  );
  return stmt.all() as unknown as ExportRecord[];
}

export function getExportRecordById(id: number): ExportRecord | undefined {
  const stmt = db.prepare(
    "SELECT * FROM export_records WHERE id = ?"
  );
  return stmt.get(id) as unknown as ExportRecord | undefined;
}

export function insertExportRecord(
  requester_email: string,
  export_type: string,
  export_date: string,
  export_status: string
): number {
  const stmt = db.prepare(
    "INSERT INTO export_records (requester_email, export_type, export_date, export_status) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(requester_email, export_type, export_date, export_status);
  return Number(result.lastInsertRowid);
}

export function updateExportRecord(
  id: number,
  requester_email: string,
  export_type: string,
  export_date: string,
  export_status: string
): number {
  const stmt = db.prepare(
    "UPDATE export_records SET requester_email = ?, export_type = ?, export_date = ?, export_status = ? WHERE id = ?"
  );
  const result = stmt.run(requester_email, export_type, export_date, export_status, id);
  return Number(result.changes);
}

