{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockDatabase = {
  products: [
    { id: 1, name: "Pencil", price: 1.5, stock: 100 },
    { id: 2, name: "Notebook", price: 3.0, stock: 50 },
    { id: 3, name: "Eraser", price: 0.5, stock: 200 }
  ],

  getAllProducts(): Promise<any[]> {
    return Promise.resolve(this.products);
  },

  getProductById(id: number): Promise<any> {
    const product = this.products.find(p => p.id === id);
    return Promise.resolve(product);
  },

  createProduct(productData: any): Promise<any> {
    const newProduct = {
      id: this.products.length + 1,
      ...productData
    };
    this.products.push(newProduct);
    return Promise.resolve(newProduct);
  },

  updateProduct(id: number, productData: any): Promise<any> {
    const index = this.products.findIndex(p => p.id === id);
    if (index === -1) return Promise.reject({ status: 404 });

    this.products[index] = { ...this.products[index], ...productData };
    return Promise.resolve(this.products[index]);
  },

  deleteProduct(id: number): Promise<void> {
    const index = this.products.findIndex(p => p.id === id);
    if (index === -1) return Promise.reject({ status: 404 });

    this.products.splice(index, 1);
    return Promise.resolve();
  }
};

// GET /inventory - List all products
router.get("/inventory", async (req: Request, res: Response) => {
  try {
    const products = await mockDatabase.getAllProducts();
    res.json(products);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch products" });
  }
});

// GET /inventory/:id - Get a specific product by ID
router.get("/inventory/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid product ID" });
    }

    const product = await mockDatabase.getProductById(id);
    if (!product) {
      return res.status(404).json({ error: "Product not found" });
    }

    res.json(product);
  } catch (error) {
    if ((error as any).status === 404) {
      res.status(404).json({ error: "Product not found" });
    } else {
      res.status(500).json({ error: "Failed to fetch product" });
    }
  }
});

// POST /inventory - Create a new product
router.post("/inventory", async (req: Request, res: Response) => {
  try {
    const { name, price, stock } = req.body;

    if (!name || price === undefined || stock === undefined) {
      return res.status(400).json({ error: "Name, price, and stock are required" });
    }

    const newProduct = await mockDatabase.createProduct({
      name,
      price: Number(price),
      stock: Number(stock)
    });

    res.status(201).json(newProduct);
  } catch (error) {
    res.status(500).json({ error: "Failed to create product" });
  }
});

// PUT /inventory/:id - Update an existing product
router.put("/inventory/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid product ID" });
    }

    const { name, price, stock } = req.body;

    if (!name && price === undefined && stock === undefined) {
      return res.status(400).json({ error: "At least one field (name, price, or stock) must be provided" });
    }

    const updatedProduct = await mockDatabase.updateProduct(id, {
      name,
      price: price !== undefined ? Number(price) : undefined,
      stock: stock !== undefined ? Number(stock) : undefined
    });

    if (!updatedProduct) {
      return res.status(404).json({ error: "Product not found" });
    }

    res.json(updatedProduct);
  } catch (error) {
    if ((error as any).status === 404) {
      res.status(404).json({ error: "Product not found" });
    } else {
      res.status(500).json({ error: "Failed to update product" });
    }
  }
});

// DELETE /inventory/:id - Delete a product
router.delete("/inventory/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid product ID" });
    }

    await mockDatabase.deleteProduct(id);
    res.json({ message: "Product deleted successfully" });
  } catch (error) {
    if ((error as any).status === 404) {
      res.status(404).json({ error: "Product not found" });
    } else {
      res.status(500).json({ error: "Failed to delete product" });
    }
  }
});
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only enforce role-based access control on POST, PUT, DELETE requests
  if (!['POST', 'PUT', 'DELETE'].includes(req.method)) {
    next();
    return;
  }

  // For demonstration purposes, we'll check a mock header
  // In a real implementation, this would be part of a JWT or similar token
  const userRole = req.header('X-User-Role') || 'worker';

  // Define role permissions
  const rolePermissions: Record<string, string[]> = {
    admin: ['POST', 'PUT', 'DELETE'],
    manager: ['PUT', 'DELETE'],
    worker: []
  };

  // Check if the user's role has permission for this request
  const allowedMethods = rolePermissions[userRole] || [];

  if (allowedMethods.includes(req.method)) {
    next();
  } else {
    res.status(403).json({ error: 'Insufficient permissions' });
  }
}
"}

{"code":"import { useEffect, useState } from "react";

interface Booking {
  id: string;
  event: string;
  date: string;
  time: string;
  tickets: number;
  status: "active" | "cancelled";
}

export function TicketManagement() {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchBookings();
  }, []);

  const fetchBookings = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/bookings");
      if (!response.ok) {
        throw new Error(`Failed to fetch bookings: ${response.status}`);
      }
      const data = await response.json();
      setBookings(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const cancelBooking = async (id: string) => {
    try {
      const response = await fetch(`/api/bookings/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`Failed to cancel booking: ${response.status}`);
      }
      // Refresh the list after cancellation
      await fetchBookings();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (bookings.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        You don't have any bookings yet.
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Your Bookings</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {bookings.map((booking) => (
          <div
            key={booking.id}
            style={{
              border: "1px solid #ddd",
              borderRadius: "8px",
              padding: "15px",
              backgroundColor: "#f9f9f9",
            }}
          >
            <div style={{ marginBottom: "10px" }}>
              <strong>Event:</strong> {booking.event}
            </div>
            <div style={{ marginBottom: "10px" }}>
              <strong>Date:</strong> {booking.date}
            </div>
            <div style={{ marginBottom: "10px" }}>
              <strong>Time:</strong> {booking.time}
            </div>
            <div style={{ marginBottom: "10px" }}>
              <strong>Tickets:</strong> {booking.tickets}
            </div>
            <div style={{ marginBottom: "10px" }}>
              <strong>Status:</strong> {booking.status}
            </div>
            <div style={{ textAlign: "right" }}>
              <button
                onClick={() => cancelBooking(booking.id)}
                disabled={booking.status === "cancelled"}
                style={{
                  backgroundColor: "#ff4d4d",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  padding: "8px 12px",
                  cursor: booking.status === "cancelled" ? "default" : "pointer",
                }}
              >
                {booking.status === "cancelled" ? "Cancelled" : "Cancel"}
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
"}

