{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface MobileOperator {
  id: number;
  name: string;
  commission_rate: number;
  service_details: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS mobile_operators (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    commission_rate REAL NOT NULL,
    service_details TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllMobileOperators(): MobileOperator[] {
  const stmt = db.prepare(`SELECT * FROM mobile_operators`);
  return stmt.all() as unknown as MobileOperator[];
}

export function getMobileOperatorById(id: number): MobileOperator | undefined {
  const stmt = db.prepare(`SELECT * FROM mobile_operators WHERE id = ?`);
  return stmt.get(id) as unknown as MobileOperator | undefined;
}

export function insertMobileOperator(operator: Omit<MobileOperator, "id">): number {
  const stmt = db.prepare(
    `INSERT INTO mobile_operators (name, commission_rate, service_details) VALUES (?, ?, ?)`
  );
  const result = stmt.run(operator.name, operator.commission_rate, operator.service_details);
  return Number(result.lastInsertRowid);
}

export function updateMobileOperator(
  id: number,
  operator: Partial<Omit<MobileOperator, "id">>
): boolean {
  const fields = [];
  const values = [];

  if (operator.name !== undefined) {
    fields.push("name = ?");
    values.push(operator.name);
  }

  if (operator.commission_rate !== undefined) {
    fields.push("commission_rate = ?");
    values.push(operator.commission_rate);
  }

  if (operator.service_details !== undefined) {
    fields.push("service_details = ?");
    values.push(operator.service_details);
  }

  if (fields.length === 0) return false;

  values.push(id);

  const sql = `UPDATE mobile_operators SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  const result = stmt.run(...values);
  return result.changes > 0;
}

export function deleteMobileOperator(id: number): boolean {
  const stmt = db.prepare(`DELETE FROM mobile_operators WHERE id = ?`);
  const result = stmt.run(id);
  return result.changes > 0;
}

// Seed data
if (getAllMobileOperators().length === 0) {
  insertMobileOperator({
    name: "Telecom Plus",
