{"code":"import { useEffect, useState } from "react";

interface Reservation {
  id: number;
  memberName: string;
  stallNumber: number;
  date: string;
  startTime: string;
  endTime: string;
}

export function MemberEntryView() {
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [memberName, setMemberName] = useState("");
  const [stallNumber, setStallNumber] = useState(0);
  const [date, setDate] = useState("");
  const [startTime, setStartTime] = useState("");
  const [endTime, setEndTime] = useState("");
  const [editingId, setEditingId] = useState<number | null>(null);

  useEffect(() => {
    fetchReservations();
  }, []);

  const fetchReservations = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/reservations-api/`);
      if (!response.ok) {
        throw new Error(`Failed to fetch reservations: ${response.status}`);
      }
      const data = await response.json();
      setReservations(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const newReservation = {
        memberName,
        stallNumber,
        date,
        startTime,
        endTime,
      };

      const response = await fetch(`/api/reservations-api/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newReservation),
      });

      if (!response.ok) {
        throw new Error(`Failed to create reservation: ${response.status}`);
      }

      // Reset form
      setMemberName("");
      setStallNumber(0);
      setDate("");
      setStartTime("");
      setEndTime("");

      // Refresh data
      await fetchReservations();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleUpdate = async (id: number) => {
    try {
      const updatedReservation = {
        memberName,
        stallNumber,
        date,
        startTime,
        endTime,
      };

      const response = await fetch(`/api/reservations-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(updatedReservation),
      });

      if (!response.ok) {
        throw new Error(`Failed to update reservation: ${response.status}`);
      }

      // Reset form
      setMemberName("");
      setStallNumber(0);
      setDate("");
      setStartTime("");
      setEndTime("");
      setEditingId(null);

      // Refresh data
      await fetchReservations();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/reservations-api/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        throw new Error(`Failed to delete reservation: ${response.status}`);
      }

      // Refresh data
      await fetchReservations();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleEdit = (reservation: Reservation) => {
    setMemberName(reservation.memberName);
    setStallNumber(reservation.stallNumber);
    setDate(reservation.date);
    setStartTime(reservation.startTime);
    setEndTime(reservation.endTime);
    setEditingId(reservation.id);
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1>My Reservation Entry</h1>

      <form onSubmit={editingId ? (e) => handleUpdate(editingId) : handleSubmit}>
        <div style={{ marginBottom: "10px" }}>
          <label>Member Name:</label>
          <input
            type="text"
            value={memberName}
            onChange={(e) => setMemberName(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <div style={{ marginBottom: "10px" }}>
          <label>Stall Number:</label>
          <input
            type="number"
            value={stallNumber}
            onChange={(e) => setStallNumber(Number(e.target.value))}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <div style={{ marginBottom: "10px" }}>
          <label>Date:</label>
          <input
            type="date"
            value={date}
            onChange={(e) => setDate(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <div style={{ marginBottom: "10px" }}>
          <label>Start Time:</label>
          <input
            type="time"
            value={startTime}
            onChange={(e) => setStartTime(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <div style={{ marginBottom: "10px" }}>
          <label>End Time:</label>
          <input
            type="time"
            value={endTime}
            onChange={(e) => setEndTime(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <button
          type="submit"
          style={{
            backgroundColor: "#007bff",
            color: "white",
            padding: "10px 20px",
            border: "none",
            borderRadius: "4px",
            cursor: "pointer",
          }}
        >
          {editingId ? "Update Reservation" : "Create Reservation"}
        </button>
      </form>

      <h2>My Reservations</h2>

      {reservations.length === 0 ? (
        <p>No reservations found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {reservations.map((reservation) => (
            <div
              key={reservation.id}
              style={{
                border: "1px solid #ccc",
                borderRadius: "4px",
                padding: "10px",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
              }}
            >
              <div>
                <strong>{reservation.memberName}</strong> - Stall #{reservation.stallNumber}
                <br />
                Date: {reservation.date}
                <br />
                Time: {reservation.startTime} - {reservation.endTime}
              </div>
              <div>
                <button
                  onClick={() => handleEdit(reservation)}
                  style={{
                    backgroundColor: "#ffc107",
                    color: "black",
                    padding: "5px 10px",
                    border: "none",
                    borderRadius: "4px",
                    marginRight: "5px",
                    cursor: "pointer",
                  }}
                >
                  Edit
                </button>
                <button
                  onClick={() => handleDelete(reservation.id)}
                  style={{
                    backgroundColor: "#dc3545",
                    color: "white",
                    padding: "5px 10px",
                    border: "none",
                    borderRadius: "4px",
                    cursor: "pointer",
                  }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only validate POST, PUT, PATCH requests to booking routes
  if (!['POST', 'PUT', 'PATCH'].includes(req.method) || !req.path.startsWith('/bookings')) {
    next();
    return;
  }

  // Validate booking data structure
  if (req.body) {
    // Check for potential injection patterns in string fields
    const fieldsToCheck = ['hallId', 'bookingDate', 'startTime', 'endTime', 'bookerName'];

    for (const field of fieldsToCheck) {
      if (typeof req.body[field] === 'string') {
        const value = req.body[field];
        // Check for common injection patterns
        if (value.includes('\\') || value.includes('\\\\') || value.includes('\\0')) {
          res.status(400).json({ error: `Invalid characters in ${field}` });
          return;
        }

        // Check for SQL injection patterns
        const sqlPatterns = [/ (union|select|insert|update|delete|drop|create) /i,
                            /\b(\d+\s*\+\s*\d+)\b/];
        for (const pattern of sqlPatterns) {
          if (pattern.test(value)) {
            res.status(400).json({ error: `Potential SQL injection detected in ${field}` });
            return;
          }
        }
      }
    }

    // Validate date format
    if (req.body.bookingDate) {
      const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
      if (!dateRegex.test(req.body.bookingDate)) {
        res.status(400).json({ error: 'Invalid date format. Expected YYYY-MM-DD' });
        return;
      }

      // Validate date is not in the past
      const inputDate = new Date(req.body.bookingDate);
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      if (inputDate < today) {
        res.status(400).json({ error: 'Booking date cannot be in the past' });
        return;
      }
    }

    // Validate time format
    if (req.body.startTime || req.body.endTime) {
      const timeRegex = /^\d{2}:\d{2}$/;
      if (req.body.startTime && !timeRegex.test(req.body.startTime)) {
        res.status(400).json({ error: 'Invalid start time format. Expected HH:MM' });
        return;
      }
      if (req.body.endTime && !timeRegex.test(req.body.endTime)) {
        res.status(400).json({ error: 'Invalid end time format. Expected HH:MM' });
        return;
      }

      // Validate time range
      if (req.body.startTime && req.body.endTime) {
        const [startHour, startMinute] = req.body.startTime.split(':').map(Number);
        const [endHour, endMinute] = req.body.endTime.split(':').map(Number);

        if (startHour > endHour || (startHour === endHour && startMinute >= endMinute)) {
          res.status(400).json({ error: 'End time must be after start time' });
          return;
        }
      }
    }

    // Validate hall capacity
    if (req.body.hallCapacity !== undefined) {
      if (typeof req.body.hallCapacity !== 'number' || req.body.hallCapacity <= 0) {
        res.status(400).json({ error: 'Hall capacity must be a positive number' });
        return;
      }
    }
  }

  next();
}
"}

