{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to POST, PUT, DELETE requests
  if (!['POST', 'PUT', 'DELETE'].includes(req.method)) {
    next();
    return;
  }

  // Define protected routes
  const protectedRoutes = [
    '/invoices',
    '/customers',
    '/products'
  ];

  // Check if current path is protected
  const isProtectedRoute = protectedRoutes.some(route => 
    req.path.startsWith(route)
  );

  if (!isProtectedRoute) {
    next();
    return;
  }

  // Get authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Unauthorized: Missing or invalid token' });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Verify JWT secret exists
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: 'Server configuration error: JWT_SECRET not set' });
    return;
  }

  try {
    // Simple JWT verification (in a real app, use a proper JWT library)
    const [header, payload, signature] = token.split('.');
    if (!header || !payload || !signature) {
      res.status(401).json({ error: 'Unauthorized: Invalid token format' });
      return;
    }

    // Create expected signature
    const expectedSignature = createHmac('sha256', jwtSecret)
      .update(`${header}.${payload}`)
      .digest('base64url');

    // Use timingSafeEqual to prevent timing attacks
    const expectedBuffer = Buffer.from(expectedSignature);
    const actualBuffer = Buffer.from(signature);

    if (expectedBuffer.length !== actualBuffer.length || 
        !timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: 'Unauthorized: Invalid token signature' });
      return;
    }

    // Decode payload to get role (simplified for this example)
    const decodedPayload = JSON.parse(
      Buffer.from(payload, 'base64').toString('utf-8')
    );

    const userRole = decodedPayload.role;
    if (!userRole) {
      res.status(401).json({ error: 'Unauthorized: Role not found in token' });
      return;
    }

    // Allow admin access to all protected routes
    if (userRole === 'admin') {
      next();
      return;
    }

    // Staff can only access specific routes
    const staffAllowedRoutes = ['/invoices'];
    const isStaffAllowed = staffAllowedRoutes.some(route => 
      req.path.startsWith(route)
    );

    if (userRole === 'staff' && isStaffAllowed) {
      next();
      return;
    }

    // Deny access for unauthorized roles
    res.status(403).json({ error: 'Forbidden: Insufficient permissions' });
  } catch (error) {
    res.status(401).json({ error: 'Unauthorized: Invalid token' });
  }
}
"}

