// Define role types
export type UserRole = "admin" | "editor" | "viewer";

// Define the structure of a decoded JWT payload
interface DecodedPayload {
  userId: string;
  roles: UserRole[];
}

// Helper to decode JWT without verification (for demonstration purposes)
// In a real implementation, this should be replaced with proper JWT decoding
function decodeJwt(payload: string): DecodedPayload {
  // This is a simplified version - in practice, use a proper JWT library
  const base64Url = payload.split(".")[1];
  const base64 = base64Url.replace(/-/g, "+").replace(/_/g, "/");
  const jsonPayload = Buffer.from(base64, "base64").toString();
  return JSON.parse(jsonPayload);
}

// Mock function to get user roles from database
async function getUserRoles(userId: string): Promise<UserRole[]> {
  // This would normally query a database
  // For demo purposes, we'll return mock data
  return ["viewer"];
}

// Middleware function
export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST, PUT, DELETE requests to /expenses
  if (!(req.method === "POST" || req.method === "PUT" || req.method === "DELETE") || !req.path.startsWith("/expenses")) {
    next();
    return;
  }

  // Get the token from headers
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);

  // Validate token signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  try {
    // Decode the token (simplified for example)
    const payload = decodeJwt(token);
    const userId = payload.userId;
    const userRoles = payload.roles;

    // Check if user has required role
    const requiredRole: UserRole = "editor"; // Example required role
    if (!userRoles.includes(requiredRole)) {
      res.status(403).json({ error: "Forbidden: Insufficient permissions" });
      return;
    }

    // If we reach here, user is authorized
    next();
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}
