      ride.destination.toLowerCase().includes(destinationFilter.toLowerCase());
    const matchesDate = dateFilter === "" || ride.date === dateFilter;
    const matchesTime = timeFilter === "" || ride.time === timeFilter;

    return matchesDestination && matchesDate && matchesTime;
  });

  const searchContainerStyle = {
    display: "flex",
    flexDirection: "column" as const,
    gap: "16px",
    marginBottom: "24px",
    padding: "16px",
    backgroundColor: "#f5f5f5",
    borderRadius: "8px"
  };

  const filterGroupStyle = {
    display: "flex",
    flexDirection: "row" as const,
    gap: "12px",
    flexWrap: "wrap" as const
  };

  const inputStyle = {
    padding: "8px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    fontSize: "16px",
    flex: "1",
    minWidth: "120px"
  };

  const rideCardStyle = {
