{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST, PUT, DELETE requests to /orders and /inventory
  const isProtectedPath = req.path.startsWith('/orders') || req.path.startsWith('/inventory');
  const isProtectedMethod = req.method === 'POST' || req.method === 'PUT' || req.method === 'DELETE';

  if (!isProtectedPath || !isProtectedMethod) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);

  if (!process.env.JWT_SECRET) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  const secret = process.env.JWT_SECRET;

  try {
    const [payload, signature] = token.split('.');

    if (!payload || !signature) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    const expectedSignature = createHmac('sha256', secret)
      .update(payload)
      .digest('base64url');

    const signatureBuffer = Buffer.from(signature, 'base64url');
    const expectedSignatureBuffer = Buffer.from(expectedSignature, 'base64url');

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // Decode payload (simplified for example)
    const decodedPayload = JSON.parse(Buffer.from(payload, 'base64url').toString());

    // Check role
    if (decodedPayload.role !== 'admin' && decodedPayload.role !== 'manager') {
      res.status(403).json({ error: "Insufficient permissions" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const DEFAULT_USERNAME = "admin";
const DEFAULT_PASSWORD = "password123";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const { username, password } = req.body;

  // Check if it's the default credentials
  if (username === DEFAULT_USERNAME && password === DEFAULT_PASSWORD) {
    // Set a flag in the response to indicate password change is required
    res.locals.passwordChangeRequired = true;
    next();
    return;
  }

  // For non-default credentials, proceed normally
  next();
}
"}

