router.post("/", (req: Request, res: Response) => {
  const { memberId, date, energyUsageKwh } = req.body;

  if (!memberId || !date || !energyUsageKwh) {
    return res.status(400).json({ error: "Missing required fields: memberId, date, energyUsageKwh" });
  }

  try {
    const newId = insertUsageRecord(memberId, date, energyUsageKwh);
    const newRecord = getUsageRecordById(newId);

    if (!newRecord) {
      return res.status(500).json({ error: "Failed to retrieve created record" });
    }

    return res.status(201).json(newRecord);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create usage record" });
  }
});

// Update an existing usage record
router.put("/:id", (req: Request, res: Response) => {
