  const { memberId, date, energyUsageKwh } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid record ID" });
  }

  if (!memberId || !date || !energyUsageKwh) {
    return res.status(400).json({ error: "Missing required fields: memberId, date, energyUsageKwh" });
  }

  const existingRecord = getUsageRecordById(id);

  if (!existingRecord) {
    return res.status(404).json({ error: "Usage record not found" });
  }

  try {
    updateUsageRecord(id, memberId, date, energyUsageKwh);
    const updatedRecord = getUsageRecordById(id);

    if (!updatedRecord) {
      return res.status(500).json({ error: "Failed to retrieve updated record" });
    }

    return res.json(updatedRecord);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update usage record" });
  }
});

// Delete a usage record
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid record ID" });
  }

  const existingRecord = getUsageRecordById(id);

