  content: string;
  authorId: number;
  status: "draft" | "published" | "archived";
  createdAt: string;
  updatedAt: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS stories (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    content TEXT NOT NULL,
    authorId INTEGER NOT NULL,
    status TEXT NOT NULL DEFAULT 'draft',
    createdAt TEXT NOT NULL,
    updatedAt TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export const getAllStories = (): StoryRow[] => {
  const stmt = db.prepare(`SELECT * FROM stories ORDER BY createdAt DESC`);
  return stmt.all() as unknown as StoryRow[];
};

export const getStoryById = (id: number): StoryRow | undefined => {
  const stmt = db.prepare(`SELECT * FROM stories WHERE id = ?`);
  return stmt.get(id) as unknown as StoryRow | undefined;
};

export const insertStory = (
  title: string,
  content: string,
  authorId: number,
  status: "draft" | "published" | "archived",
  createdAt: string,
  updatedAt: string
): number => {
  const stmt = db.prepare(
    `INSERT INTO stories (title, content, authorId, status, createdAt, updatedAt)
     VALUES (?, ?, ?, ?, ?, ?)`
  );
  const result = stmt.run(title, content, authorId, status, createdAt, updatedAt);
  return Number(result.lastInsertRowid);
};

export const updateStory = (
  id: number,
  title: string,
  content: string,
  authorId: number,
  status: "draft" | "published" | "archived",
  updatedAt: string
): void => {
  const stmt = db.prepare(
    `UPDATE stories SET title = ?, content = ?, authorId = ?, status = ?, updatedAt = ?
     WHERE id = ?`
  );
  stmt.run(title, content, authorId, status, updatedAt, id);
};

export const deleteStory = (id: number): void => {
  const stmt = db.prepare(`DELETE FROM stories WHERE id = ?`);
  stmt.run(id);
};

// Seed data
if (getAllStories().length === 0) {
