{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply to GET requests to routes starting with /api/routes/
  if (req.method !== "GET" || !req.path.startsWith("/api/routes/")) {
    next();
    return;
  }

  // Check if user is authenticated and has setter role
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify properly)
  try {
    // For this example, we'll assume the token contains user info in a simple format
    // In practice, you'd want proper JWT verification
    const payload = JSON.parse(atob(token.split('.')[1] || ''));

    // Check if user has setter role
    if (payload.role !== "setter") {
      res.status(403).json({ error: "Forbidden: Access denied" });
      return;
    }

    // Extract setter ID from token (assuming it's stored there)
    const tokenSetterId = payload.id;

    // Extract target setter ID from URL path
    // Assuming path format: /api/routes/setter/{setterId}
    const pathParts = req.path.split('/');
    const targetSetterId = pathParts[4]; // This assumes the structure

    // If target setter ID doesn't exist, allow access (this might be a general route)
    if (!targetSetterId) {
      next();
      return;
    }

    // If the requesting user is not the owner of the route data, deny access
    if (tokenSetterId !== targetSetterId) {
      res.status(403).json({ error: "Forbidden: Cannot access another setter's routes" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}
"}

