{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-feedback routes
  if (!req.path.startsWith("/feedback")) {
    next();
    return;
  }

  // Check if user is authenticated
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token verification (in a real app, use a proper JWT library)
  const [payload, signature] = token.split(".");
  if (!payload || !signature) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  // Verify signature
  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64url");

  try {
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // Decode payload (simplified for this example)
  const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());
  const userRole = decodedPayload.role;

  // Staff can access all feedback endpoints
  if (userRole === "staff") {
    next();
    return;
  }

  // Guest users can only submit feedback, not view or edit
  if (userRole === "guest" && req.method === "POST") {
    next();
    return;
  }

  // Reject unauthorized access
  res.status(403).json({ error: "Forbidden" });
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply to GET requests to album routes
  if (req.method !== "GET" || !req.path.startsWith("/album/")) {
    next();
    return;
  }

  const shareToken = req.headers["x-share-token"] as string | undefined;

  if (!shareToken) {
    res.status(401).json({ error: "Share token required" });
    return;
  }

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Basic token format validation
  const parts = shareToken.split(".");
  if (parts.length !== 2) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  const [tokenPayload, tokenSignature] = parts;

  // Verify signature
  const expectedSignature = createHmac("sha256", secret)
    .update(tokenPayload)
    .digest("hex");

  const expectedBuffer = Buffer.from(expectedSignature);
  const actualBuffer = Buffer.from(tokenSignature);

  if (actualBuffer.length !== expectedBuffer.length || 
      !timingSafeEqual(actualBuffer, expectedBuffer)) {
    res.status(401).json({ error: "Invalid token signature" });
    return;
  }

  // Token is valid, proceed
  next();
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteBatch,
  getAllBatches,
  getBatchById,
  insertBatch,
  updateBatch
} from "../db/aging-batches-table";

export const router = Router();

// Get all aging batches for the logged-in cheesemaker
router.get("/", (req: Request, res: Response) => {
  try {
    const batches = getAllBatches();
    return res.json(batches);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch batches" });
  }
});

// Get a specific aging batch by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid batch ID" });
    }

    const batch = getBatchById(id);
    if (!batch) {
      return res.status(404).json({ error: "Batch not found" });
    }

    return res.json(batch);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch batch" });
  }
});

// Create a new aging batch
router.post("/", (req: Request, res: Response) => {
  try {
    const { cheeseType, ageDays, ownerId } = req.body;

    if (!cheeseType || ageDays === undefined || ownerId === undefined) {
      return res.status(400).json({
        error: "Missing required fields: cheeseType, ageDays, ownerId"
      });
    }

    const id = insertBatch(cheeseType, ageDays, ownerId);
    const newBatch = getBatchById(id);

    if (!newBatch) {
      return res.status(500).json({ error: "Failed to create batch" });
    }

    return res.status(201).json(newBatch);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create batch" });
  }
});

// Update an existing aging batch
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { cheeseType, ageDays, ownerId } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid batch ID" });
    }

    if (!cheeseType || ageDays === undefined || ownerId === undefined) {
      return res.status(400).json({
        error: "Missing required fields: cheeseType, ageDays, ownerId"
      });
    }

    const existingBatch = getBatchById(id);
    if (!existingBatch) {
      return res.status(404).json({ error: "Batch not found" });
    }

    updateBatch(id, cheeseType, ageDays, ownerId);
    const updatedBatch = getBatchById(id);

    if (!updatedBatch) {
      return res.status(500).json({ error: "Failed to update batch" });
    }

    return res.json(updatedBatch);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update batch" });
  }
});

// Delete an aging batch
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid batch ID" });
    }

    const existingBatch = getBatchById(id);
    if (!existingBatch) {
      return res.status(404).json({ error: "Batch not found" });
    }

    deleteBatch(id);
    return res.json({ message: "Batch deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete batch" });
  }
});
