{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check override bookings, ignore all other requests
  if (!(req.method === "POST" && req.path === "/bookings/override")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify properly
  // For this exercise, we'll assume the token has a staff flag in payload
  try {
    // This is a simplified version - in practice, you'd decode the JWT properly
    // and verify the signature using HMAC-SHA256 with the secret
    const [payload] = token.split(".");
    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("hex");

    // In a real implementation, we'd verify the actual signature
    // For now, we'll just check if the token contains "staff"
    if (token.includes("staff")) {
      next();
    } else {
      res.status(403).json({ error: "Forbidden: Staff only" });
    }
  } catch (error) {
    res.status(401).json({ error: "Unauthorized" });
  }
}
"}

