import { db, deleteIncident, getAllIncidents, getIncidentById, insertIncident, updateIncident } from "../db/incidents-table";

export const router = Router();

// Get all incidents for the current resident
router.get("/", (req: Request, res: Response) => {
  try {
    const incidents = getAllIncidents();
    return res.json(incidents);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch incidents" });
  }
});

// Get a specific incident by ID for the current resident
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid incident ID" });
    }

    const incident = getIncidentById(id);
    if (!incident) {
      return res.status(404).json({ error: "Incident not found" });
    }

    return res.json(incident);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch incident" });
  }
});

// Create a new incident report for the current resident
router.post("/", (req: Request, res: Response) => {
  try {
    const { description } = req.body;

    if (!description || typeof description !== "string") {
      return res.status(400).json({ error: "Description is required and must be a string" });
    }

    // Assuming residentId is available in req.user or similar middleware
    // For now, we'll use a placeholder - in a real app, this should come from auth middleware
    const residentId = 1; // This should be extracted from authenticated user context

    const newId = insertIncident(residentId, description);
    const newIncident = getIncidentById(newId);

    if (!newIncident) {
      return res.status(500).json({ error: "Failed to create incident" });
    }

    return res.status(201).json(newIncident);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create incident" });
  }
});

// Update an existing incident report for the current resident
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid incident ID" });
    }

    const { description } = req.body;
    if (!description || typeof description !== "string") {
      return res.status(400).json({ error: "Description is required and must be a string" });
    }

    // Assuming residentId is available in req.user or similar middleware
    // For now, we'll use a placeholder - in a real app, this should come from auth middleware
    const residentId = 1; // This should be extracted from authenticated user context

    const existingIncident = getIncidentById(id);
    if (!existingIncident) {
      return res.status(404).json({ error: "Incident not found" });
    }

    updateIncident(id, description);
    const updatedIncident = getIncidentById(id);

    if (!updatedIncident) {
      return res.status(500).json({ error: "Failed to update incident" });
    }

    return res.json(updatedIncident);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update incident" });
  }
});

// Delete an incident report for the current resident
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid incident ID" });
    }

