  const [editingId, setEditingId] = useState<string | null>(null);

  // Form state
  const [newMeasurement, setNewMeasurement] = useState({
    customerId: "",
    date: "",
    chest: "",
    waist: "",
    hips: "",
    sleeveLength: "",
    length: ""
  });

  // Fetch data
  useEffect(() => {
    const fetchData = async () => {
      try {
        const [measurementsRes, customersRes] = await Promise.all([
          fetch('/api/measurements'),
          fetch('/api/customers')
        ]);

        if (!measurementsRes.ok || !customersRes.ok) {
          throw new Error('Failed to fetch data');
        }

        const measurementsData = await measurementsRes.json();
        const customersData = await customersRes.json();

        setMeasurements(measurementsData);
        setCustomers(customersData);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An error occurred');
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const filteredMeasurements = measurements.filter(m => 
    customers.find(c => c.id === m.customerId)?.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setNewMeasurement(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = await fetch('/api/measurements', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...newMeasurement,
          chest: Number(newMeasurement.chest),
          waist: Number(newMeasurement.waist),
          hips: Number(newMeasurement.hips),
          sleeveLength: Number(newMeasurement.sleeveLength),
          length: Number(newMeasurement.length)
        })
      });

      if (!response.ok) {
        throw new Error('Failed to add measurement');
      }

      // Refresh data
      const measurementsRes = await fetch('/api/measurements');
      const measurementsData = await measurementsRes.json();
      setMeasurements(measurementsData);

      // Reset form
      setNewMeasurement({
        customerId: "",
        date: "",
        chest: "",
        waist: "",
        hips: "",
        sleeveLength: "",
        length: ""
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/measurements/${id}`, {
        method: 'DELETE'
      });

      if (!response.ok) {
        throw new Error('Failed to delete measurement');
      }

      // Refresh data
      const measurementsRes = await fetch('/api/measurements');
      const measurementsData = await measurementsRes.json();
      setMeasurements(measurementsData);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
    }
  };

  const handleEdit = (measurement: Measurement) => {
    setEditingId(measurement.id);
  };

  const handleUpdate = async (id: string, updatedMeasurement: Partial<Measurement>) => {
    try {
      const response = await fetch(`/api/measurements/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updatedMeasurement)
      });

      if (!response.ok) {
        throw new Error('Failed to update measurement');
      }

      // Refresh data
      const measurementsRes = await fetch('/api/measurements');
      const measurementsData = await measurementsRes.json();
      setMeasurements(measurementsData);

      setEditingId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Measurement Tracking</h1>

      <div style={{ marginBottom: '30px' }}>
        <h2>Add New Measurement</h2>
        <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          <select 
            name="customerId" 
            value={newMeasurement.customerId}
            onChange={handleInputChange}
            required
            style={{ padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          >
            <option value="">Select Customer</option>
            {customers.map(customer => (
              <option key={customer.id} value={customer.id}>{customer.name}</option>
            ))}
          </select>

          <input 
            type="date" 
            name="date" 
            value={newMeasurement.date}
            onChange={handleInputChange}
            required
            style={{ padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          />

          <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
            <input 
              type="number" 
              name="chest" 
              placeholder="Chest (cm)"
              value={newMeasurement.chest}
              onChange={handleInputChange}
              style={{ flex: 1, minWidth: '120px', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
            />
            <input 
              type="number" 
              name="waist" 
              placeholder="Waist (cm)"
              value={newMeasurement.waist}
              onChange={handleInputChange}
              style={{ flex: 1, minWidth: '120px', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
            />
            <input 
              type="number" 
              name="hips" 
              placeholder="Hips (cm)"
              value={newMeasurement.hips}
              onChange={handleInputChange}
              style={{ flex: 1, minWidth: '120px', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
            />
          </div>

          <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
            <input 
              type="number" 
              name="sleeveLength" 
              placeholder="Sleeve Length (cm)"
              value={newMeasurement.sleeveLength}
              onChange={handleInputChange}
              style={{ flex: 1, minWidth: '120px', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
            />
            <input 
              type="number" 
              name="length" 
              placeholder="Length (cm)"
              value={newMeasurement.length}
              onChange={handleInputChange}
              style={{ flex: 1, minWidth: '120px', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
            />
          </div>

          <button 
            type="submit" 
            style={{ 
              padding: '10px', 
              backgroundColor: '#007bff', 
              color: 'white', 
              border: 'none', 
              borderRadius: '4px', 
              cursor: 'pointer' 
            }}
          >
            Add Measurement
          </button>
        </form>
      </div>

      <div style={{ marginBottom: '30px' }}>
        <h2>Search Measurements</h2>
        <input 
          type="text" 
          placeholder="Search by customer name..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ 
            width: '100%', 
            padding: '10px', 
            borderRadius: '4px', 
            border: '1px solid #ccc', 
            boxSizing: 'border-box' 
          }}
        />
      </div>

      <div>
        <h2>Measurement History</h2>
        {filteredMeasurements.length === 0 ? (
          <p style={{ textAlign: 'center', padding: '20px' }}>No measurements found.</p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
            {filteredMeasurements.map(measurement => {
              const customer = customers.find(c => c.id === measurement.customerId);

              return (
                <div 
                  key={measurement.id} 
                  style={{ 
                    border: '1px solid #ddd', 
                    borderRadius: '8px', 
                    padding: '15px', 
                    backgroundColor: '#f9f9f9' 
                  }}
                >
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <h3>{customer?.name || 'Unknown Customer'} - {measurement.date}</h3>
                    <div style={{ display: 'flex', gap: '5px' }}>
                      <button 
                        onClick={() => handleEdit(measurement)}
                        style={{ 
                          padding: '5px 10px', 
                          backgroundColor: '#ffc107', 
                          border: 'none', 
                          borderRadius: '4px', 
                          cursor: 'pointer' 
                        }}
                      >
                        Edit
                      </button>
                      <button 
                        onClick={() => handleDelete(measurement.id)}
                        style={{ 
                          padding: '5px 10px', 
                          backgroundColor: '#dc3545', 
                          color: 'white', 
                          border: 'none', 
                          borderRadius: '4px', 
                          cursor: 'pointer' 
                        }}
                      >
                        Delete
                      </button>
                    </div>
                  </div>

                  {editingId === measurement.id ? (
                    <div style={{ marginTop: '10px', padding: '10px', backgroundColor: '#fff', borderRadius: '4px' }}>
                      <input 
                        type="number" 
                        defaultValue={measurement.chest}
                        onChange={(e) => {
                          const updated = { ...measurement, chest: Number(e.target.value) };
                          handleUpdate(measurement.id, updated);
                        }}
                        style={{ 
                          width: '100%', 
                          padding: '8px', 
                          borderRadius: '4px', 
                          border: '1px solid #ccc', 
                          boxSizing: 'border-box' 
                        }}
                      />
                    </div>
                  ) : (
                    <div style={{ marginTop: '10px', display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(120px, 1fr))', gap: '10px' }}>
                      <div><strong>Chest:</strong> {measurement.chest} cm</div>
                      <div><strong>Waist:</strong> {measurement.waist} cm</div>
                      <div><strong>Hips:</strong> {measurement.hips} cm</div>
                      <div><strong>Sleeve:</strong> {measurement.sleeveLength} cm</div>
                      <div><strong>Length:</strong> {measurement.length} cm</div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteReservation,
  getAllReservations,
  getReservationById,
  insertReservation,
  updateReservation
} from "../db/reservations-table";

export const router = Router();

// Get all reservations
router.get("/", (req: Request, res: Response) => {
  try {
    const reservations = getAllReservations();
    res.json(reservations);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reservations" });
  }
});

// Get a reservation by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const reservation = getReservationById(id);
    if (!reservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    res.json(reservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reservation" });
  }
});

// Create a new reservation
router.post("/", (req: Request, res: Response) => {
  try {
    const { driverId, timeSlot, status } = req.body;

    if (!driverId || !timeSlot || !status) {
      return res.status(400).json({ error: "Missing required fields: driverId, timeSlot, status" });
    }

    const id = insertReservation(driverId, timeSlot, status);
    const newReservation = getReservationById(id);

    if (!newReservation) {
      return res.status(500).json({ error: "Failed to create reservation" });
    }

    res.status(201).json(newReservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to create reservation" });
  }
});

// Update a reservation
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { driverId, timeSlot, status } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    if (!driverId || !timeSlot || !status) {
      return res.status(400).json({ error: "Missing required fields: driverId, timeSlot, status" });
    }

    const existingReservation = getReservationById(id);
    if (!existingReservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    updateReservation(id, driverId, timeSlot, status);
    const updatedReservation = getReservationById(id);

    if (!updatedReservation) {
      return res.status(500).json({ error: "Failed to update reservation" });
    }

    res.json(updatedReservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to update reservation" });
  }
});

// Delete a reservation (supervisor-only access)
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const existingReservation = getReservationById(id);
    if (!existingReservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    // Enforce supervisor-only deletion
    // For this implementation, we'll assume any valid request qualifies as supervisor access
    deleteReservation(id);
    res.json({ message: "Reservation deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete reservation" });
  }
});
"}

