{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check authentication for POST /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT secret is set
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // For demonstration purposes, we'll just accept any valid-looking token
  // In a real implementation, this would verify the JWT signature
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Simple validation - in reality, this should verify the JWT signature
  try {
    // This is a simplified example - in practice, you'd decode and verify
    // the JWT using a library like jsonwebtoken
    const payload = JSON.parse(Buffer.from(token.split(".")[1], "base64").toString());

    // Verify the signature (simplified for this example)
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(`${token.split(".")[0]}.${token.split(".")[1]}`)
      .digest("hex");

    const actualSignature = token.split(".")[2];

    const isValid = timingSafeEqual(
      Buffer.from(expectedSignature),
      Buffer.from(actualSignature)
    );

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // If we get here, the token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}
"}

