import { db, deleteDocument, getAllDocuments, getDocumentById, insertDocument, updateDocument } from "../db/documents-table";

export const router = Router();

// GET /documents - Get all documents
router.get("/documents", (req: Request, res: Response) => {
  try {
    const documents = getAllDocuments();
    res.json(documents);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch documents" });
  }
});

// GET /documents/:id - Get a document by ID
router.get("/documents/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid document ID" });
    }

    const document = getDocumentById(id);
    if (!document) {
      return res.status(404).json({ error: "Document not found" });
    }

    res.json(document);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch document" });
  }
});

// POST /documents - Create a new document
router.post("/documents", (req: Request, res: Response) => {
  try {
    const { title, content, author } = req.body;

    if (!title || !content || !author) {
      return res.status(400).json({ error: "Title, content, and author are required" });
    }

    const id = insertDocument(title, content, author);
    const createdDocument = getDocumentById(id);

    if (!createdDocument) {
      return res.status(500).json({ error: "Failed to retrieve created document" });
    }

    res.status(201).json(createdDocument);
  } catch (error) {
    res.status(500).json({ error: "Failed to create document" });
  }
});

// PUT /documents/:id - Update a document
router.put("/documents/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid document ID" });
    }

    const { title, content, author } = req.body;

    if (!title || !content || !author) {
      return res.status(400).json({ error: "Title, content, and author are required" });
    }

    const existingDocument = getDocumentById(id);
    if (!existingDocument) {
      return res.status(404).json({ error: "Document not found" });
    }

    updateDocument(id, title, content, author);
    const updatedDocument = getDocumentById(id);

    if (!updatedDocument) {
      return res.status(500).json({ error: "Failed to retrieve updated document" });
    }

    res.json(updatedDocument);
  } catch (error) {
    res.status(500).json({ error: "Failed to update document" });
  }
});

// DELETE /documents/:id - Delete a document
router.delete("/documents/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid document ID" });
    }

    const existingDocument = getDocumentById(id);
    if (!existingDocument) {
      return res.status(404).json({ error: "Document not found" });
    }

    deleteDocument(id);
    res.json({ message: "Document deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete document" });
  }
});
