  // Validate required fields
  if (!variety || !grapes || !picker_id || !harvest_date) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const newId = insertHarvestEntry(variety, grapes, picker_id, harvest_date);
  const newEntry = getHarvestEntryById(newId);

  if (!newEntry) {
    return res.status(500).json({ error: "Failed to create harvest entry" });
  }

  res.status(201).json(newEntry);
});

// Update an existing harvest entry
router.put("/:id", (req: Request, res: Response) => {
