  const { variety, grapes, picker_id, harvest_date } = req.body;

  // Validate required fields
  if (!variety || !grapes || !picker_id || !harvest_date) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const existingEntry = getHarvestEntryById(id);

  if (!existingEntry) {
    return res.status(404).json({ error: "Harvest entry not found" });
  }

  updateHarvestEntry(id, variety, grapes, picker_id, harvest_date);
  const updatedEntry = getHarvestEntryById(id);

  if (!updatedEntry) {
    return res.status(500).json({ error: "Failed to update harvest entry" });
  }

  res.json(updatedEntry);
});

