  const id = Number(req.params.id);

  const existingEntry = getHarvestEntryById(id);

  if (!existingEntry) {
    return res.status(404).json({ error: "Harvest entry not found" });
  }

  deleteHarvestEntry(id);

  res.json({ message: "Harvest entry deleted successfully" });
});
