{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface CrmRecord {
  id: number;
  object_type: string;
  data: string;
  created_at: string;
  updated_at: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS crm_records (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    object_type TEXT NOT NULL,
    data TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllRecords(): CrmRecord[] {
  const stmt = db.prepare(`SELECT * FROM crm_records`);
  return stmt.all() as unknown as CrmRecord[];
}

export function getRecordById(id: number): CrmRecord | undefined {
  const stmt = db.prepare(`SELECT * FROM crm_records WHERE id = ?`);
  return stmt.get(id) as unknown as CrmRecord | undefined;
}

export function insertRecord(objectType: string, data: string): number {
  const stmt = db.prepare(
    `INSERT INTO crm_records (object_type, data, created_at, updated_at) VALUES (?, ?, ?, ?)`
  );
  const result = stmt.run(objectType, data, new Date().toISOString(), new Date().toISOString());
  return Number(result.lastInsertRowid);
}

export function updateRecord(id: number, objectType: string, data: string): number {
  const stmt = db.prepare(
    `UPDATE crm_records SET object_type = ?, data = ?, updated_at = ? WHERE id = ?`
  );
  const result = stmt.run(objectType, data, new Date().toISOString(), id);
  return Number(result.changes);
}

export function deleteRecord(id: number): number {
  const stmt = db.prepare(`DELETE FROM crm_records WHERE id = ?`);
  const result = stmt.run(id);
  return Number(result.changes);
}

// Sample data insertion
if (getAllRecords().length === 0) {
  insertRecord("contact", `{"name": "John Doe", "email": "john@example.com"}`);
  insertRecord("lead", `{"name": "Jane Smith", "company": "Acme Corp"}`);
  insertRecord("opportunity", `{"account": "Globex Inc", "amount": 50000}`);
  insertRecord("task", `{"title": "Follow up call", "assigned_to": "Bob Johnson"}`);
  insertRecord("note", `{"content": "Meeting notes for Q4 planning"}`);
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-feedback routes
  if (!req.path.startsWith("/feedback")) {
    next();
    return;
  }

  // Check if user is authenticated
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token verification (in a real app, use a proper JWT library)
  const [payload, signature] = token.split(".");
  if (!payload || !signature) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  // Verify signature
  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64url");

  try {
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // Decode payload (simplified for this example)
  const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());
  const userRole = decodedPayload.role;

  // Staff can access all feedback endpoints
  if (userRole === "staff") {
    next();
    return;
  }

  // Guest users can only submit feedback, not view or edit
  if (userRole === "guest" && req.method === "POST") {
    next();
    return;
  }

  // Reject unauthorized access
  res.status(403).json({ error: "Forbidden" });
}
"}

