  if (trainIndex === -1) {
    return res.status(404).json({ error: "Train not found" });
  }

  const { name, route, departureTime, arrivalTime, totalSeats, availableSeats } = req.body;

  trains[trainIndex] = {
    ...trains[trainIndex],
    name: name || trains[trainIndex].name,
    route: route || trains[trainIndex].route,
    departureTime: departureTime || trains[trainIndex].departureTime,
    arrivalTime: arrivalTime || trains[trainIndex].arrivalTime,
    totalSeats: totalSeats || trains[trainIndex].totalSeats,
    availableSeats: availableSeats !== undefined ? availableSeats : trains[trainIndex].availableSeats
  };

