{"code":"import { useEffect, useState } from "react";

interface Checkout {
  id: string;
  artistName: string;
  equipmentId: string;
  checkoutDate: string;
  returnDate?: string;
}

interface Equipment {
  id: string;
  name: string;
  description: string;
  status: "available" | "checkedOut" | "maintenance";
}

export function CheckoutQueue() {
  const [checkouts, setCheckouts] = useState<Checkout[]>([]);
  const [equipment, setEquipment] = useState<Equipment[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [artistName, setArtistName] = useState("");
  const [selectedEquipment, setSelectedEquipment] = useState("");

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [checkoutsResponse, equipmentResponse] = await Promise.all([
          fetch("/api/checkout-api/"),
          fetch("/api/equipment-inventory-service/equipment"),
        ]);

        if (!checkoutsResponse.ok || !equipmentResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const checkoutsData = await checkoutsResponse.json();
        const equipmentData = await equipmentResponse.json();

        setCheckouts(checkoutsData);
        setEquipment(equipmentData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleCheckout = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!artistName.trim() || !selectedEquipment) return;

    try {
      const response = await fetch("/api/checkout-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          artistName,
          equipmentId: selectedEquipment,
          checkoutDate: new Date().toISOString(),
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to create checkout");
      }

      // Refresh data
      const [checkoutsResponse, equipmentResponse] = await Promise.all([
        fetch("/api/checkout-api/"),
        fetch("/api/equipment-inventory-service/equipment"),
      ]);

      if (!checkoutsResponse.ok || !equipmentResponse.ok) {
        throw new Error("Failed to refresh data");
      }

      const checkoutsData = await checkoutsResponse.json();
      const equipmentData = await equipmentResponse.json();

      setCheckouts(checkoutsData);
      setEquipment(equipmentData);
      setArtistName("");
      setSelectedEquipment("");
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleReturn = async (id: string) => {
    try {
      const response = await fetch(`/api/checkout-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ returnDate: new Date().toISOString() }),
      });

      if (!response.ok) {
        throw new Error("Failed to update checkout");
      }

      // Refresh data
      const [checkoutsResponse, equipmentResponse] = await Promise.all([
        fetch("/api/checkout-api/"),
        fetch("/api/equipment-inventory-service/equipment"),
      ]);

      if (!checkoutsResponse.ok || !equipmentResponse.ok) {
        throw new Error("Failed to refresh data");
      }

      const checkoutsData = await checkoutsResponse.json();
      const equipmentData = await equipmentResponse.json();

      setCheckouts(checkoutsData);
      setEquipment(equipmentData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div
      style={{
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Checkout Queue</h1>

      <div style={{ marginBottom: "30px" }}>
        <h2>Request Checkout</h2>
        <form onSubmit={handleCheckout}>
          <div style={{ marginBottom: "10px" }}>
            <label htmlFor="artistName">Artist Name:</label>
            <input
              id="artistName"
              type="text"
              value={artistName}
              onChange={(e) => setArtistName(e.target.value)}
              style={{ width: "100%", padding: "8px", marginTop: "5px" }}
              required
            />
          </div>
          <div style={{ marginBottom: "10px" }}>
            <label htmlFor="equipment">Equipment:</label>
            <select
              id="equipment"
              value={selectedEquipment}
              onChange={(e) => setSelectedEquipment(e.target.value)}
              style={{ width: "100%", padding: "8px", marginTop: "5px" }}
              required
            >
              <option value="">Select Equipment</option>
              {equipment
                .filter((eq) => eq.status === "available")
                .map((eq) => (
                  <option key={eq.id} value={eq.id}>
                    {eq.name}
                  </option>
                ))}
            </select>
          </div>
          <button
            type="submit"
            style={{
              backgroundColor: "#007bff",
              color: "white",
              border: "none",
              padding: "10px 15px",
              borderRadius: "4px",
              cursor: "pointer",
            }}
          >
            Request Checkout
          </button>
        </form>
      </div>

      <div>
        <h2>Current Checkouts</h2>
        {checkouts.length === 0 ? (
          <p style={{ textAlign: "center", fontStyle: "italic" }}>
            No items currently checked out.
          </p>
        ) : (
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: "10px",
            }}
          >
            {checkouts.map((checkout) => {
              const equipmentItem = equipment.find(
                (eq) => eq.id === checkout.equipmentId
              );
              return (
                <div
                  key={checkout.id}
                  style={{
                    border: "1px solid #ccc",
                    borderRadius: "8px",
                    padding: "15px",
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                    flexWrap: "wrap",
                  }}
                >
                  <div>
                    <strong>{equipmentItem?.name}</strong>
                    <br />
                    Artist: {checkout.artistName}
                    <br />
                    Checked Out: {new Date(checkout.checkoutDate).toLocaleDateString()}
                    <br />
                    {checkout.returnDate && (
                      <span>Returned: {new Date(checkout.returnDate).toLocaleDateString()}</span>
                    )}
                  </div>
                  <div>
                    {!checkout.returnDate && (
                      <button
                        onClick={() => handleReturn(checkout.id)}
                        style={{
                          backgroundColor: "#28a745",
                          color: "white",
                          border: "none",
                          padding: "8px 12px",
                          borderRadius: "4px",
                          cursor: "pointer",
                        }}
                      >
                        Mark as Returned
                      </button>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}
"}

