{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface Meal {
  id: number;
  name: string;
  stock: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS meals (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    stock INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllMeals(): Meal[] {
  const stmt = db.prepare("SELECT * FROM meals");
  return stmt.all() as unknown as Meal[];
}

export function getMealById(id: number): Meal | undefined {
  const stmt = db.prepare("SELECT * FROM meals WHERE id = ?");
  return stmt.get(id) as unknown as Meal | undefined;
}

export function insertMeal(name: string, stock: number): number {
  const stmt = db.prepare("INSERT INTO meals (name, stock) VALUES (?, ?)");
  const result = stmt.run(name, stock);
  return Number(result.lastInsertRowid);
}

export function updateMealStock(id: number, stock: number): void {
  const stmt = db.prepare("UPDATE meals SET stock = ? WHERE id = ?");
  stmt.run(stock, id);
}

export function deleteMeal(id: number): void {
  const stmt = db.prepare("DELETE FROM meals WHERE id = ?");
  stmt.run(id);
}

// Seed data
if (getAllMeals().length === 0) {
  insertMeal("Chicken Burger", 50);
  insertMeal("Vegetable Salad", 30);
  insertMeal("Beef Pasta", 25);
  insertMeal("Fish Tacos", 40);
  insertMeal("Quinoa Bowl", 35);
}
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user data storage
const users = [
  { id: 1, username: "admin", password: "admin123", role: "admin" },
  { id: 2, username: "driver1", password: "driver123", role: "driver" },
  { id: 3, username: "user1", password: "user123", role: "user" }
];

// User registration
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role } = req.body;

  // Validate input
  if (!username || !password || !role) {
    return res.status(400).json({ error: "Username, password, and role are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    username,
    password,
    role
  };

  users.push(newUser);
  res.status(201).json(newUser);
});

// User login
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  // Validate input
  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Find user
  const user = users.find(u => u.username === username && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Return user info (in a real app, this would include a JWT token)
  res.json({
    id: user.id,
    username: user.username,
    role: user.role
  });
});

// Role-based access control middleware
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: Function) => {
    // In a real app, this would check the JWT token
    const userRole = req.headers.role as string;

    if (!userRole || !roles.includes(userRole)) {
      return res.status(403).json({ error: "Access denied" });
    }

    next();
  };
};

// Protected route example for admin only
router.get("/admin", authorize(["admin"]), (req: Request, res: Response) => {
  res.json({ message: "Admin access granted" });
});

// Protected route example for drivers and admins
router.get("/driver", authorize(["driver", "admin"]), (req: Request, res: Response) => {
  res.json({ message: "Driver or admin access granted" });
});

// Protected route example for users, drivers and admins
router.get("/user", authorize(["user", "driver", "admin"]), (req: Request, res: Response) => {
  res.json({ message: "User, driver or admin access granted" });
});
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply 2FA validation to POST requests to the /auth/2fa endpoint
  if (req.method !== "POST" || !req.path.startsWith("/auth/2fa")) {
    next();
    return;
  }

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  const token = req.headers["authorization"]?.split(" ")[1];

  if (!token) {
    res.status(401).json({ error: "Missing authorization token" });
    return;
  }

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    const [header, payload, signature] = parts;

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // If we get here, the token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Authentication failed" });
  }
}
"}

