{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data to simulate database operations
let orders = [
  { id: 1, customerName: "John Doe", frames: "Ray-Ban Aviator", lenses: "Progressive", status: "pending", createdAt: new Date().toISOString() },
  { id: 2, customerName: "Jane Smith", frames: "Oakley Flight Deck", lenses: "Single Vision", status: "shipped", createdAt: new Date().toISOString() }
];

let nextId = 3;

// GET /orders - List all orders
router.get("/orders", (req: Request, res: Response) => {
  res.json(orders);
});

// GET /orders/:id - Get one order by ID
router.get("/orders/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const order = orders.find(o => o.id === id);

  if (!order) {
    return res.status(404).json({ error: "Order not found" });
  }

  res.json(order);
});

// POST /orders - Create a new order
router.post("/orders", (req: Request, res: Response) => {
  const { customerName, frames, lenses, status } = req.body;

  if (!customerName || !frames || !lenses) {
    return res.status(400).json({ error: "Customer name, frames, and lenses are required" });
  }

  const newOrder = {
    id: nextId++,
    customerName,
    frames,
    lenses,
    status: status || "pending",
    createdAt: new Date().toISOString()
  };

  orders.push(newOrder);
  res.status(201).json(newOrder);
});

// PUT /orders/:id - Update an existing order
router.put("/orders/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const orderIndex = orders.findIndex(o => o.id === id);

  if (orderIndex === -1) {
    return res.status(404).json({ error: "Order not found" });
  }

  const { customerName, frames, lenses, status } = req.body;

  if (!customerName || !frames || !lenses) {
    return res.status(400).json({ error: "Customer name, frames, and lenses are required" });
  }

  orders[orderIndex] = {
    ...orders[orderIndex],
    customerName,
    frames,
    lenses,
    status: status || orders[orderIndex].status
  };

  res.json(orders[orderIndex]);
});

// DELETE /orders/:id - Delete an order
router.delete("/orders/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const orderIndex = orders.findIndex(o => o.id === id);

  if (orderIndex === -1) {
    return res.status(404).json({ error: "Order not found" });
  }

  orders.splice(orderIndex, 1);
  res.json({ message: "Order deleted successfully" });
});

// GET /orders/search?query= - Search orders by customer name or frames
router.get("/orders/search", (req: Request, res: Response) => {
  const query = req.query.query as string;

  if (!query) {
    return res.status(400).json({ error: "Query parameter is required" });
  }

  const results = orders.filter(order => 
    order.customerName.toLowerCase().includes(query.toLowerCase()) ||
    order.frames.toLowerCase().includes(query.toLowerCase())
  );

  res.json(results);
});

// PUT /orders/:id/status - Update order status
router.put("/orders/:id/status", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const orderIndex = orders.findIndex(o => o.id === id);

  if (orderIndex === -1) {
    return res.status(404).json({ error: "Order not found" });
  }

  const { status } = req.body;

  if (!status) {
    return res.status(400).json({ error: "Status is required" });
  }

  orders[orderIndex] = {
    ...orders[orderIndex],
    status
  };

  res.json(orders[orderIndex]);
});
"}

