{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply RBAC logic to protected routes
  const protectedPaths = ["/memberships", "/classes"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has proper role
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  try {
    // Simple token validation (in a real app, you'd decode and verify properly)
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // Decode payload to get user info
    const payloadStr = Buffer.from(payload, "base64url").toString();
    const payloadObj = JSON.parse(payloadStr);

    // Check if user is staff or member
    const userRole = payloadObj.role;
    const userId = payloadObj.userId;
    const pathUserId = req.params.userId;

    // Staff can access all resources
    if (userRole === "staff") {
      next();
      return;
    }

    // Members can only access their own data
    if (userRole === "member") {
      if (req.path.includes("/memberships") && pathUserId !== userId) {
        res.status(403).json({ error: "Forbidden" });
        return;
      }

      if (req.path.includes("/classes") && pathUserId !== userId) {
        res.status(403).json({ error: "Forbidden" });
        return;
      }

      next();
      return;
    }

    res.status(401).json({ error: "Unauthorized" });
  } catch (err) {
    res.status(401).json({ error: "Invalid token" });
  }
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("farmers-market.db");

interface Reservation {
  id: number;
  vendorId: number;
  stallNumber: number;
  weekendDate: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS reservations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    vendorId INTEGER NOT NULL,
    stallNumber INTEGER NOT NULL,
    weekendDate TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllReservations(): Reservation[] {
  const stmt = db.prepare("SELECT * FROM reservations");
  return stmt.all() as unknown as Reservation[];
}

export function getReservationById(id: number): Reservation | undefined {
  const stmt = db.prepare("SELECT * FROM reservations WHERE id = ?");
  return stmt.get(id) as unknown as Reservation | undefined;
}

export function insertReservation(
  vendorId: number,
  stallNumber: number,
  weekendDate: string
): number {
  const stmt = db.prepare(
    "INSERT INTO reservations (vendorId, stallNumber, weekendDate) VALUES (?, ?, ?)"
  );
  const result = stmt.run(vendorId, stallNumber, weekendDate);
  return Number(result.lastInsertRowid);
}

export function updateReservation(
  id: number,
  vendorId: number,
  stallNumber: number,
  weekendDate: string
): number {
  const stmt = db.prepare(
    "UPDATE reservations SET vendorId = ?, stallNumber = ?, weekendDate = ? WHERE id = ?"
  );
  const result = stmt.run(vendorId, stallNumber, weekendDate, id);
  return Number(result.changes);
}

export function deleteReservation(id: number): number {
  const stmt = db.prepare("DELETE FROM reservations WHERE id = ?");
  const result = stmt.run(id);
  return Number(result.changes);
}

