{"code":"import { useEffect, useState } from "react";

interface Reservation {
  id: string;
  date: string;
  time: string;
  guestName: string;
  guestEmail: string;
}

interface TimeSlot {
  time: string;
  available: boolean;
}

export function ReservationCalendar() {
  const [date, setDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [timeSlots, setTimeSlots] = useState<TimeSlot[]>([]);
  const [selectedTime, setSelectedTime] = useState<string>('');
  const [guestName, setGuestName] = useState<string>('');
  const [guestEmail, setGuestEmail] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<boolean>(false);

  useEffect(() => {
    fetchTimeSlots();
  }, [date]);

  const fetchTimeSlots = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(`/api/reservations-api/reservations?date=${date}`);
      if (!response.ok) {
        throw new Error(`Failed to fetch reservations: ${response.status} ${response.statusText}`);
      }
      const reservations: Reservation[] = await response.json();

      // Generate time slots (9am to 8pm)
      const slots: TimeSlot[] = [];
      for (let hour = 9; hour <= 20; hour++) {
        const time = `${hour}:00`;
        const isAvailable = !reservations.some(r => r.time === time);
        slots.push({ time, available: isAvailable });
      }

      setTimeSlots(slots);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleBookReservation = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedTime || !guestName || !guestEmail) return;

    try {
      const response = await fetch('/api/reservations-api/reservations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          date,
          time: selectedTime,
          guestName,
          guestEmail
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to book reservation: ${response.status} ${response.statusText}`);
      }

      setSuccess(true);
      setGuestName('');
      setGuestEmail('');
      setSelectedTime('');

      // Refresh the time slots
      await fetchTimeSlots();

      // Reset success message after 3 seconds
      setTimeout(() => setSuccess(false), 3000);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Book Your Reservation</h1>

      <div style={{ marginBottom: '20px' }}>
        <label htmlFor="date" style={{ display: 'block', marginBottom: '5px' }}>
          Select Date:
        </label>
        <input
          type="date"
          id="date"
          value={date}
          onChange={(e) => setDate(e.target.value)}
          style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
        />
      </div>

      <h2 style={{ textAlign: 'center' }}>Available Time Slots</h2>

      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px', justifyContent: 'center' }}>
        {timeSlots.length > 0 ? (
          timeSlots.map((slot) => (
            <button
              key={slot.time}
              onClick={() => setSelectedTime(slot.time)}
              disabled={!slot.available}
              style={{
                padding: '10px 15px',
                borderRadius: '8px',
                border: '1px solid #ccc',
                backgroundColor: slot.available ? '#4CAF50' : '#f0f0f0',
                color: slot.available ? 'white' : 'gray',
                cursor: slot.available ? 'pointer' : 'default',
                opacity: slot.available ? 1 : 0.6,
                minWidth: '100px'
              }}
            >
              {slot.time}
            </button>
          ))
        ) : (
          <p>No time slots available for this date.</p>
        )}
      </div>

      <form onSubmit={handleBookReservation} style={{ marginTop: '30px' }}>
        <h2 style={{ textAlign: 'center' }}>Book Now</h2>

        {success && (
          <div style={{ backgroundColor: '#d4edda', color: '#155724', padding: '10px', borderRadius: '4px', marginBottom: '10px' }}>
            Reservation booked successfully!
          </div>
        )}

        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="name" style={{ display: 'block', marginBottom: '5px' }}>
            Full Name:
          </label>
          <input
            type="text"
            id="name"
            value={guestName}
            onChange={(e) => setGuestName(e.target.value)}
            required
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="email" style={{ display: 'block', marginBottom: '5px' }}>
            Email Address:
          </label>
          <input
            type="email"
            id="email"
            value={guestEmail}
            onChange={(e) => setGuestEmail(e.target.value)}
            required
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          />
        </div>

        <button
          type="submit"
          disabled={!selectedTime || !guestName || !guestEmail}
          style={{
            width: '100%',
            padding: '12px',
            backgroundColor: selectedTime && guestName && guestEmail ? '#2196F3' : '#ccc',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: selectedTime && guestName && guestEmail ? 'pointer' : 'default'
          }}
        >
          Confirm Reservation
        </button>
      </form>
    </div>
  );
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check export-related requests
  if (!(req.method === "POST" && req.path === "/export/history")) {
    next();
    return;
  }

  const authHeader = req.headers["authorization"];
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Basic token structure validation
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  const [header, payload, signature] = parts;

  // Verify signature using HMAC-SHA256
  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  const actualSignature = signature;

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(actualSignature, "base64url");

    if (!timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Invalid token signature" });
    return;
  }

  // Decode payload to check ownership
  try {
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());

    // Assuming the payload contains an 'owner' field that must match a known owner ID
    // For this implementation, we'll assume owner ID is hardcoded or configurable
    const ownerId = process.env.OWNER_ID;

    if (!ownerId) {
      res.status(500).json({ error: "Server configuration error" });
      return;
    }

    if (decodedPayload.owner !== ownerId) {
      res.status(403).json({ error: "Forbidden: Export access restricted to owner" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Invalid token payload" });
    return;
  }

  next();
}
"}

