    const { date, machineId, description, status } = req.body;
    const updatedLog = await db.update(id, { date, machineId, description, status });
    if (!updatedLog) {
      return res.status(404).json({ error: "Maintenance log not found" });
    }
    res.json(updatedLog);
  } catch (error) {
    res.status(500).json({ error: "Failed to update log" });
  }
});

// DELETE /maintenance/:id - Delete a maintenance log
