export const db = new DatabaseSync("./short-story-platform.db");

interface MediaRow {
  id: number;
  filename: string;
  filepath: string;
  story_id: number;
  upload_date: string;
}

const createTableSQL = `
  CREATE TABLE IF NOT EXISTS media (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    filename TEXT NOT NULL,
    filepath TEXT NOT NULL,
    story_id INTEGER NOT NULL,
    upload_date TEXT NOT NULL,
    FOREIGN KEY (story_id) REFERENCES stories(id)
  )
`;

db.exec(createTableSQL);

export function insertMedia(
  filename: string,
  filepath: string,
  story_id: number,
  upload_date: string
): number {
  const sql = `INSERT INTO media (filename, filepath, story_id, upload_date) VALUES (?, ?, ?, ?)`;
  const result = db.prepare(sql).run(filename, filepath, story_id, upload_date);
  return Number(result.lastInsertRowid);
}

export function getMediaById(id: number): MediaRow | undefined {
  const sql = `SELECT * FROM media WHERE id = ?`;
  return db.prepare(sql).get(id) as unknown as MediaRow | undefined;
}

export function getAllMedia(): MediaRow[] {
  const sql = `SELECT * FROM media`;
  return db.prepare(sql).all() as unknown as MediaRow[];
}

export function updateMedia(
  id: number,
  filename: string,
  filepath: string,
  story_id: number,
  upload_date: string
): void {
  const sql = `UPDATE media SET filename = ?, filepath = ?, story_id = ?, upload_date = ? WHERE id = ?`;
  db.prepare(sql).run(filename, filepath, story_id, upload_date, id);
}

export function deleteMedia(id: number): void {
  const sql = `DELETE FROM media WHERE id = ?`;
  db.prepare(sql).run(id);
}

