{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes
const ACTIVE_SESSIONS = new Map<string, { expiresAt: number }>();

function verifyTokenSignature(token: string, secret: string): boolean {
  const [header, payload, signature] = token.split(".");
  if (!header || !payload || !signature) return false;

  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const actualSignature = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");
    return timingSafeEqual(actualSignature, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  if (!verifyTokenSignature(token, secret)) {
    res.status(401).json({ error: "Invalid token signature" });
    return;
  }

  // Parse token to extract session info
  const [header, payload, signature] = token.split(".");
  if (!header || !payload || !signature) {
    res.status(401).json({ error: "Malformed token" });
    return;
  }

  try {
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64").toString());
    const sessionId = decodedPayload.sessionId;
    const expiresAt = decodedPayload.expiresAt;

    if (!sessionId || !expiresAt) {
      res.status(401).json({ error: "Invalid token payload" });
      return;
    }

    const now = Date.now();
    if (now > expiresAt) {
      res.status(401).json({ error: "Session expired" });
      return;
    }

    // Check if session exists and is still valid
    const session = ACTIVE_SESSIONS.get(sessionId);
    if (!session || session.expiresAt < now) {
      res.status(401).json({ error: "Invalid session" });
      return;
    }

    // Update session expiration
    ACTIVE_SESSIONS.set(sessionId, { expiresAt: now + SESSION_TIMEOUT });

    next();
  } catch (err) {
    res.status(401).json({ error: "Invalid token format" });
  }
}
"}

