    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL,
    permissions TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllStaff(): StaffMember[] {
  const stmt = db.prepare("SELECT * FROM staff");
  return stmt.all() as unknown as StaffMember[];
}

export function getStaffById(id: number): StaffMember | undefined {
  const stmt = db.prepare("SELECT * FROM staff WHERE id = ?");
  return stmt.get(id) as unknown as StaffMember | undefined;
}

export function insertStaff(
  username: string,
  password_hash: string,
  role: string,
  permissions: string
): number {
  const stmt = db.prepare(
    "INSERT INTO staff (username, password_hash, role, permissions) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(username, password_hash, role, permissions);
  return Number(result.lastInsertRowid);
}

