{"code":"import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to POST /admin routes
  if (!(req.method === "POST" && req.path.startsWith("/admin"))) {
    next();
    return;
  }

  // Check if user has staff role
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (userRole !== "staff") {
    res.status(403).json({ error: "Access denied. Staff role required." });
    return;
  }

  next();
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./dog-park.db");

interface Checkin {
  id: number;
  dog_id: number;
  member_id: number;
  timestamp: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS checkins (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    dog_id INTEGER NOT NULL,
    member_id INTEGER NOT NULL,
    timestamp TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllCheckins(): Checkin[] {
  const stmt = db.prepare("SELECT * FROM checkins");
  return stmt.all() as unknown as Checkin[];
}

export function getCheckinById(id: number): Checkin | undefined {
  const stmt = db.prepare("SELECT * FROM checkins WHERE id = ?");
  return stmt.get(id) as unknown as Checkin | undefined;
}

export function insertCheckin(dogId: number, memberId: number, timestamp: string): number {
  const stmt = db.prepare(
    "INSERT INTO checkins (dog_id, member_id, timestamp) VALUES (?, ?, ?)"
  );
  const result = stmt.run(dogId, memberId, timestamp);
  return Number(result.lastInsertRowid);
}

export function updateCheckin(id: number, dogId: number, memberId: number, timestamp: string): void {
  const stmt = db.prepare(
    "UPDATE checkins SET dog_id = ?, member_id = ?, timestamp = ? WHERE id = ?"
  );
  stmt.run(dogId, memberId, timestamp, id);
}

export function deleteCheckin(id: number): void {
  const stmt = db.prepare("DELETE FROM checkins WHERE id = ?");
  stmt.run(id);
}

