{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock service data - in a real app this would come from a database
let services = [
  { id: 1, name: "Haircut", duration: 30, price: 25.0, description: "Basic haircut" },
  { id: 2, name: "Color", duration: 60, price: 50.0, description: "Full color service" }
];

let nextId = 3;

// Get all services
router.get("/", (req: Request, res: Response) => {
  res.json(services);
});

// Get service by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const service = services.find(s => s.id === id);

  if (!service) {
    return res.status(404).json({ error: "Service not found" });
  }

  res.json(service);
});

// Create new service
router.post("/", (req: Request, res: Response) => {
  const { name, duration, price, description } = req.body;

  // Validate required fields
  if (!name || !duration || !price) {
    return res.status(400).json({ error: "Name, duration, and price are required" });
  }

  // Validate types
  if (typeof duration !== "number" || typeof price !== "number") {
    return res.status(400).json({ error: "Duration and price must be numbers" });
  }

  const newService = {
    id: nextId++,
    name,
    duration,
    price,
    description: description || ""
  };

  services.push(newService);
  res.status(201).json(newService);
});

// Update service
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { name, duration, price, description } = req.body;

  const serviceIndex = services.findIndex(s => s.id === id);

  if (serviceIndex === -1) {
    return res.status(404).json({ error: "Service not found" });
  }

  // Validate required fields
  if (!name || !duration || !price) {
    return res.status(400).json({ error: "Name, duration, and price are required" });
  }

  // Validate types
  if (typeof duration !== "number" || typeof price !== "number") {
    return res.status(400).json({ error: "Duration and price must be numbers" });
  }

  services[serviceIndex] = {
    id,
    name,
    duration,
    price,
    description: description || ""
  };

  res.json(services[serviceIndex]);
});

// Delete service
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const serviceIndex = services.findIndex(s => s.id === id);

  if (serviceIndex === -1) {
    return res.status(404).json({ error: "Service not found" });
  }

  services.splice(serviceIndex, 1);
  res.json({ message: "Service deleted successfully" });
