export const db = new DatabaseSync(
  "/tmp/aquarium_feeding_schedule.db"
);

interface Feeding {
  id: number;
  animal_id: number;
  time: string;
  quantity: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS feedings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    animal_id INTEGER NOT NULL,
    time TEXT NOT NULL,
    quantity REAL NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllFeedings(): Feeding[] {
  const stmt = db.prepare(`SELECT * FROM feedings`);
  return stmt.all() as unknown as Feeding[];
}

export function getFeedingById(id: number): Feeding | undefined {
  const stmt = db.prepare(`SELECT * FROM feedings WHERE id = ?`);
  return stmt.get(id) as unknown as Feeding | undefined;
}

export function insertFeeding(
  animalId: number,
  time: string,
  quantity: number
): number {
  const stmt = db.prepare(
    `INSERT INTO feedings (animal_id, time, quantity) VALUES (?, ?, ?)`
  );
  const result = stmt.run(animalId, time, quantity);
  return Number(result.lastInsertRowid);
}

export function updateFeeding(
  id: number,
  animalId: number,
  time: string,
  quantity: number
): void {
  const stmt = db.prepare(
    `UPDATE feedings SET animal_id = ?, time = ?, quantity = ? WHERE id = ?`
  );
  stmt.run(animalId, time, quantity, id);
}

export function deleteFeeding(id: number): void {
  const stmt = db.prepare(`DELETE FROM feedings WHERE id = ?`);
  stmt.run(id);
}

