{"code":"import { Router, type Request, type Response, type NextFunction } from "express";
import { FeedItem, insertFeedItem, getFeedItemsByUserId, markFeedItemAsRead } from "../db/feed-items-table";
import { middleware } from "../middleware/multiple-login-methods";

export const router = Router();

router.use(middleware);

router.get("/items", (req: Request, res: Response) => {
  const userId = Number(req.query.userId);
  if (isNaN(userId)) {
    res.status(400).send("Invalid user ID");
    return;
  }
  const items = getFeedItemsByUserId(userId);
  res.json(items);
});

router.post("/items", (req: Request, res: Response) => {
  const { userId, title, link, content, tags } = req.body;
  if (typeof userId !== "number" || typeof title !== "string" || typeof link !== "string" || typeof content !== "string" || typeof tags !== "string") {
    res.status(400).send("Invalid input");
    return;
  }
  insertFeedItem(userId, title, link, content, tags);
  res.status(201).send("Feed item added");
});

router.put("/items/:itemId/mark-as-read", (req: Request, res: Response) => {
  const itemId = Number(req.params.itemId);
  if (isNaN(itemId)) {
    res.status(400).send("Invalid item ID");
    return;
  }
  markFeedItemAsRead(itemId);
  res.send("Feed item marked as read");
});
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  {
    id: 1,
    username: "admin",
    password: "admin123",
    role: "admin"
  },
  {
    id: 2,
    username: "customer",
    password: "customer123",
    role: "customer"
  }
];

// User registration
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    username,
    password,
    role: role || "customer"
  };

  users.push(newUser);
  res.status(201).json(newUser);
});

// User login
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // In a real app, we would generate a JWT token here
  res.json({
    message: "Login successful",
    user: {
      id: user.id,
      username: user.username,
      role: user.role
    }
  });
});

// Role-based access control middleware
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    // For simplicity, assuming user is attached to request
    // In a real app, this would come from a JWT token
    const user = req.body.user;

    if (!user || user.role !== requiredRole) {
      return res.status(403).json({ error: "Access denied" });
    }

    next();
  };
};

// Protected route example
router.get("/admin", requireRole("admin"), (req: Request, res: Response) => {
  res.json({ message: "Admin access granted" });
});
"}

