  try {
    const articles = getAllSavedArticles();
    return res.json(articles);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch articles" });
  }
});

router.get("/articles/:id", middleware, (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid article ID" });
    }

    const article = getSavedArticleById(id);
    if (!article) {
      return res.status(404).json({ error: "Article not found" });
    }

    return res.json(article);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch article" });
  }
});

router.post("/articles", middleware, (req: Request, res: Response) => {
  try {
    const { userId, title, url } = req.body;

    if (!userId || !title || !url) {
      return res.status(400).json({ error: "Missing required fields: userId, title, url" });
    }

    const content = extractContentFromUrl(url);
    const newId = insertSavedArticle(userId, title, url, content);

    return res.status(201).json({ id: newId, title, url, content });
  } catch (error) {
    return res.status(500).json({ error: "Failed to save article" });
  }
});

router.put("/articles/:id", middleware, (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid article ID" });
    }

    const { title, content } = req.body;

    if (!title || !content) {
      return res.status(400).json({ error: "Missing required fields: title, content" });
    }

    const updatedRows = updateSavedArticle(id, title, content);

    if (updatedRows === 0) {
      return res.status(404).json({ error: "Article not found" });
    }

    return res.json({ message: "Article updated successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to update article" });
  }
});

router.delete("/articles/:id", middleware, (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid article ID" });
    }

    const deletedRows = deleteSavedArticle(id);

    if (deletedRows === 0) {
      return res.status(404).json({ error: "Article not found" });
    }

    return res.json({ message: "Article deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete article" });
  }
});
