{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const TOKEN_HEADER = "x-auth-token";
const SESSION_TIMEOUT_MS = 30 * 60 * 1000; // 30 minutes

interface SessionData {
  userId: string;
  issuedAt: number;
}

function isValidToken(token: string): boolean {
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return false;
  }

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) {
      return false;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const actualSignature = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(actualSignature, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

function getSessionData(token: string): SessionData | null {
  try {
    const payload = token.split(".")[1];
    const decoded = Buffer.from(payload, "base64url").toString("utf8");
    return JSON.parse(decoded);
  } catch {
    return null;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle requests that require session validation
  if (req.method !== "POST" && req.method !== "PUT" && req.method !== "DELETE") {
    next();
    return;
  }

  const token = req.header(TOKEN_HEADER);

  if (!token) {
    res.status(401).json({ error: "Missing authentication token" });
    return;
  }

  if (!isValidToken(token)) {
    res.status(401).json({ error: "Invalid authentication token" });
    return;
  }

  const sessionData = getSessionData(token);
  if (!sessionData) {
    res.status(401).json({ error: "Invalid session data" });
    return;
  }

  // Check if session has timed out
  const now = Date.now();
  if (now - sessionData.issuedAt > SESSION_TIMEOUT_MS) {
    res.status(401).json({ error: "Session has expired" });
    return;
  }

  // Attach user ID to request for downstream middleware/route handlers
  (req as any).userId = sessionData.userId;
  next();
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteExpense,
  getAllExpenses,
  getExpenseById,
  insertExpense,
  updateExpense
} from "../db/expenses-table";

export const router = Router();

// Get all expenses
router.get("/", (req: Request, res: Response) => {
  try {
    const expenses = getAllExpenses();
    res.json(expenses);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch expenses" });
  }
});

// Get expense by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid expense ID" });
    }

    const expense = getExpenseById(id);
    if (!expense) {
      return res.status(404).json({ error: "Expense not found" });
    }

    res.json(expense);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch expense" });
  }
});

// Create new expense
router.post("/", (req: Request, res: Response) => {
  try {
    const { amount, date, category, account_id } = req.body;

    if (
      typeof amount !== "number" ||
      !date ||
      !category ||
      typeof account_id !== "number"
    ) {
      return res.status(400).json({
        error: "Amount, date, category, and account_id are required"
      });
    }

    const newId = insertExpense(amount, date, category, account_id);
    const newExpense = getExpenseById(newId);

    if (!newExpense) {
      return res.status(500).json({ error: "Failed to create expense" });
    }

    res.status(201).json(newExpense);
  } catch (error) {
    res.status(500).json({ error: "Failed to create expense" });
  }
});

// Update expense
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid expense ID" });
    }

    const { amount, date, category, account_id } = req.body;

    if (
      typeof amount !== "number" ||
      !date ||
      !category ||
      typeof account_id !== "number"
    ) {
      return res.status(400).json({
        error: "Amount, date, category, and account_id are required"
      });
    }

    const updatedId = updateExpense(id, amount, date, category, account_id);
    const updatedExpense = getExpenseById(updatedId);

    if (!updatedExpense) {
      return res.status(404).json({ error: "Expense not found" });
    }

    res.json(updatedExpense);
  } catch (error) {
    res.status(500).json({ error: "Failed to update expense" });
  }
});

// Delete expense
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid expense ID" });
    }

    const deletedId = deleteExpense(id);
    if (deletedId === 0) {
      return res.status(404).json({ error: "Expense not found" });
    }

    res.json({ message: "Expense deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete expense" });
  }
});
"}

