{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockDistributionRecords = [
  {
    id: "1",
    date: "2023-05-15",
    items: [
      { itemId: "1", quantity: 10 },
      { itemId: "2", quantity: 5 }
    ]
  },
  {
    id: "2",
    date: "2023-05-16",
    items: [
      { itemId: "1", quantity: 8 },
      { itemId: "3", quantity: 12 }
    ]
  }
];

const findRecordById = (id: string) => {
  return mockDistributionRecords.find(record => record.id === id);
};

const createRecord = (record: any) => {
  const newRecord = {
    id: String(mockDistributionRecords.length + 1),
    ...record
  };
  mockDistributionRecords.push(newRecord);
  return newRecord;
};

const updateRecord = (id: string, updatedRecord: any) => {
  const index = mockDistributionRecords.findIndex(record => record.id === id);
  if (index === -1) return null;
  mockDistributionRecords[index] = { ...mockDistributionRecords[index], ...updatedRecord };
  return mockDistributionRecords[index];
};

const deleteRecord = (id: string) => {
  const index = mockDistributionRecords.findIndex(record => record.id === id);
  if (index === -1) return false;
  mockDistributionRecords.splice(index, 1);
  return true;
};

// GET /distributions - List all distributions
router.get("/distributions", (req: Request, res: Response) => {
  res.json(mockDistributionRecords);
});

// GET /distributions/:id - Get a specific distribution by ID
router.get("/distributions/:id", (req: Request, res: Response) => {
  const record = findRecordById(req.params.id);
  if (!record) {
    return res.status(404).json({ error: "Distribution record not found" });
  }
  res.json(record);
});

// POST /distributions - Create a new distribution record
router.post("/distributions", (req: Request, res: Response) => {
  const { date, items } = req.body;

  if (!date || !items || !Array.isArray(items)) {
    return res.status(400).json({ error: "Date and items array are required" });
  }

  const newRecord = createRecord({ date, items });
  res.status(201).json(newRecord);
});

// PUT /distributions/:id - Update a distribution record
router.put("/distributions/:id", (req: Request, res: Response) => {
  const { date, items } = req.body;

  if (!date || !items || !Array.isArray(items)) {
    return res.status(400).json({ error: "Date and items array are required" });
  }

  const updatedRecord = updateRecord(req.params.id, { date, items });

  if (!updatedRecord) {
    return res.status(404).json({ error: "Distribution record not found" });
  }

  res.json(updatedRecord);
});

// DELETE /distributions/:id - Delete a distribution record
router.delete("/distributions/:id", (req: Request, res: Response) => {
  const deleted = deleteRecord(req.params.id);

  if (!deleted) {
    return res.status(404).json({ error: "Distribution record not found" });
  }

  res.json({ message: "Distribution record deleted successfully" });
});
