  content: string;
  ownerId: string;
}

export function PageEditor() {
  const [pages, setPages] = useState<Page[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [ownerId, setOwnerId] = useState("");

  useEffect(() => {
    fetchPages();
  }, []);

  const fetchPages = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/wiki-page-service/');
      if (!response.ok) {
        throw new Error(`Failed to fetch pages: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setPages(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim() || !content.trim()) return;

    try {
      const method = editingId ? 'PUT' : 'POST';
      const url = editingId 
        ? `/api/wiki-page-service/${editingId}`
        : '/api/wiki-page-service/';

      const response = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title, content, ownerId }),
      });

      if (!response.ok) {
        throw new Error(`Failed to save page: ${response.status} ${response.statusText}`);
      }

      // Reset form and reload pages
      setTitle("");
      setContent("");
      setEditingId(null);
      fetchPages();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleEdit = (page: Page) => {
    setTitle(page.title);
    setContent(page.content);
    setEditingId(page.id);
    setOwnerId(page.ownerId);
  };

