{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function verifyToken(token: string): boolean {
  if (!JWT_SECRET) return false;

  const [header, payload, signature] = token.split(".");
  if (!header || !payload || !signature) return false;

  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const expectedBytes = Buffer.from(expectedSignature, "base64url");
    const actualBytes = Buffer.from(signature, "base64url");
    return timingSafeEqual(expectedBytes, actualBytes);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  if (!req.body || !req.body.username || !req.body.password) {
    res.status(400).json({ error: "Username and password required" });
    return;
  }

  // In a real implementation, we would verify credentials here
  // For now, we'll just simulate a successful login
  // This is a placeholder for actual authentication logic

  // Simulate successful authentication
  const token = `header.payload.${createHmac("sha256", JWT_SECRET || "").update("header.payload").digest("base64url")}`;

  res.json({ token });
}
