{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database - in a real app this would be a proper database
const users = [
  {
    id: 1,
    username: "admin",
    password: "secure123",
    role: "administrator"
  },
  {
    id: 2,
    username: "staff1",
    password: "password123",
    role: "staff"
  }
];

// Session storage - in a real app this would be a proper session store
const sessions = new Map<string, { userId: number; role: string }>();

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate a simple session ID
  const sessionId = Math.random().toString(36).substring(2, 15);
  sessions.set(sessionId, { userId: user.id, role: user.role });

  return res.status(200).json({
    sessionId,
    role: user.role
  });
});

// Logout endpoint
router.post("/logout", (req: Request, res: Response) => {
  const sessionId = req.headers["x-session-id"] as string;

  if (!sessionId) {
    return res.status(400).json({ error: "Session ID is required" });
  }

  if (!sessions.has(sessionId)) {
    return res.status(401).json({ error: "Invalid session" });
  }

  sessions.delete(sessionId);
  return res.status(200).json({ message: "Logged out successfully" });
});

// Middleware to verify session
const authenticate = (req: Request, res: Response, next: Function) => {
  const sessionId = req.headers["x-session-id"] as string;

  if (!sessionId) {
    return res.status(401).json({ error: "Session ID is required" });
  }

  const session = sessions.get(sessionId);

  if (!session) {
    return res.status(401).json({ error: "Invalid session" });
  }

  (req as any).userId = session.userId;
  (req as any).role = session.role;
  next();
};

// Middleware to check role permissions
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    const userRole = (req as any).role;

    if (!userRole || userRole !== requiredRole) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }

    next();
  };
};

// Protected route example - requires staff role
router.get("/profile", authenticate, (req: Request, res: Response) => {
  return res.status(200).json({
    userId: (req as any).userId,
    role: (req as any).role
  });
});

// Admin-only route example
router.get("/admin", authenticate, requireRole("administrator"), (req: Request, res: Response) => {
  return res.status(200).json({ message: "Admin access granted" });
});
"}

