{"code":"import { useState, useEffect } from "react";

interface Client {
  id: number;
  name: string;
  email: string;
  address: string;
  phone: string;
}

export function ClientManagement() {
  const [clients, setClients] = useState<Client[]>([]);
  const [formData, setFormData] = useState<Omit<Client, "id">>({ 
    name: "", 
    email: "", 
    address: "", 
    phone: ""
  });
  const [editingId, setEditingId] = useState<number | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Load clients on component mount
  useEffect(() => {
    fetchClients();
  }, []);

  const fetchClients = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/clients");
      if (!response.ok) throw new Error("Failed to fetch clients");
      const data = await response.json();
      setClients(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const url = editingId 
        ? `/api/clients/${editingId}`
        : "/api/clients";

      const method = editingId ? "PUT" : "POST";

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData)
      });

      if (!response.ok) throw new Error("Failed to save client");

      await fetchClients();
      resetForm();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleEdit = (client: Client) => {
    setFormData({ 
      name: client.name, 
      email: client.email, 
      address: client.address, 
      phone: client.phone
    });
    setEditingId(client.id);
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/clients/${id}`, { method: "DELETE" });
      if (!response.ok) throw new Error("Failed to delete client");
      await fetchClients();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const resetForm = () => {
    setFormData({ name: "", email: "", address: "", phone: "" });
    setEditingId(null);
  };

  const formStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "12px",
    marginBottom: "24px",
    padding: "16px",
    border: "1px solid #ddd",
    borderRadius: "8px",
    backgroundColor: "#f9f9f9"
  };

  const inputStyle: React.CSSProperties = {
    padding: "8px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    fontSize: "16px",
    width: "100%"
  };

  const buttonStyle: React.CSSProperties = {
    padding: "8px 16px",
    borderRadius: "4px",
    border: "none",
    backgroundColor: "#007bff",
    color: "white",
    cursor: "pointer",
    fontSize: "16px"
  };

  const listContainerStyle: React.CSSProperties = {
    maxWidth: "800px",
    margin: "0 auto",
    fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
  };

  const clientCardStyle: React.CSSProperties = {
    padding: "16px",
    margin: "8px 0",
    border: "1px solid #ddd",
    borderRadius: "8px",
    backgroundColor: "#fff"
  };

  const buttonGroupStyle: React.CSSProperties = {
    display: "flex",
    gap: "8px",
    justifyContent: "flex-end"
  };

  if (loading) return <div style={listContainerStyle}>Loading...</div>;

  if (error) return <div style={listContainerStyle}>Error: {error}</div>;

  return (
    <div style={listContainerStyle}>
      <h1>Client Management</h1>

      <form onSubmit={handleSubmit} style={formStyle}>
        <h2>{editingId ? "Edit Client" : "Add New Client"}</h2>

        <input
          type="text"
          name="name"
          placeholder="Name"
          value={formData.name}
          onChange={handleChange}
          style={inputStyle}
        />

        <input
          type="email"
          name="email"
          placeholder="Email"
          value={formData.email}
          onChange={handleChange}
          style={inputStyle}
        />

        <textarea
          name="address"
          placeholder="Address"
          value={formData.address}
          onChange={handleChange}
          style={inputStyle}
        />

        <input
          type="tel"
          name="phone"
          placeholder="Phone"
          value={formData.phone}
          onChange={handleChange}
          style={inputStyle}
        />

        <button type="submit" style={buttonStyle}>
          {editingId ? "Update Client" : "Add Client"}
        </button>

        {editingId && (
          <button type="button" onClick={resetForm} style={{...buttonStyle, backgroundColor: "#6c757d"}}>
            Cancel
          </button>
        )}
      </form>

      <h2>Clients</h2>

      {clients.length === 0 ? (
        <p>No clients found.</p>
      ) : (
        <div>
          {clients.map(client => (
            <div key={client.id} style={clientCardStyle}>
              <h3>{client.name}</h3>
              <p><strong>Email:</strong> {client.email}</p>
              <p><strong>Address:</strong> {client.address}</p>
              <p><strong>Phone:</strong> {client.phone}</p>
              <div style={buttonGroupStyle}>
                <button 
                  onClick={() => handleEdit(client)}
                  style={{...buttonStyle, backgroundColor: "#17a2b8"}}
                >
                  Edit
                </button>
                <button 
                  onClick={() => handleDelete(client.id)}
                  style={{...buttonStyle, backgroundColor: "#dc3545"}}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (!(req.method === "POST" && req.path === "/login")) {
    next();
    return;
  }

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "JWT secret not configured" });
    return;
  }

  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    res.status(401).json({ error: "Authorization token required" });
    return;
  }

  try {
    // Simple verification of token format (base64url encoded)
    const [header, payload, signature] = token.split(".");

    if (!header || !payload || !signature) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(signature, "base64url"),
      Buffer.from(expectedSignature, "base64url")
    );

    if (!isValid) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // If we get here, token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}
"}

