{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database - in a real app this would be a proper database
const users = [
  { id: 1, username: "admin", password: "password123", role: "administrator" },
  { id: 2, username: "staff", password: "staffpass", role: "staff" }
];

// Mock session storage
const sessions = new Map<string, { userId: number; role: string }>();

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Find user
  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate session token
  const token = Math.random().toString(36).substring(2, 15);
  sessions.set(token, { userId: user.id, role: user.role });

  return res.json({ token, role: user.role });
});

// Logout endpoint
router.post("/logout", (req: Request, res: Response) => {
  const token = req.header("Authorization")?.replace("Bearer ", "");

  if (!token) {
    return res.status(400).json({ error: "No token provided" });
  }

  if (!sessions.has(token)) {
    return res.status(401).json({ error: "Invalid token" });
  }

  sessions.delete(token);
  return res.json({ message: "Logged out successfully" });
});

// Middleware to verify session
const authenticate = (req: Request, res: Response, next: () => void) => {
  const token = req.header("Authorization")?.replace("Bearer ", "");

  if (!token) {
    return res.status(401).json({ error: "No token provided" });
  }

  const session = sessions.get(token);

  if (!session) {
    return res.status(401).json({ error: "Invalid token" });
  }

  // Attach user info to request
  (req as any).user = session;
  next();
};

// Role-based authorization middleware
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: () => void) => {
    const userRole = (req as any).user?.role;

    if (!userRole || !roles.includes(userRole)) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }

    next();
  };
};

// Protected route example - can only be accessed by authenticated users
router.get("/profile", authenticate, (req: Request, res: Response) => {
  const user = (req as any).user;
  return res.json({ userId: user.userId, role: user.role });
});

// Admin-only route example
router.get("/admin", authenticate, authorize(["administrator"]), (req: Request, res: Response) => {
  return res.json({ message: "Admin access granted" });
});
"}

