export const router = Router();

// Mock data for demonstration purposes
const mockCalendarEvents = [
  { id: "1", date: "2023-10-15", startTime: "18:00", endTime: "20:00", tableNumber: 5 },
  { id: "2", date: "2023-10-16", startTime: "19:00", endTime: "21:00", tableNumber: 3 },
];

// Get all calendar events
router.get("/events", (req: Request, res: Response) => {
  res.json(mockCalendarEvents);
});

// Get a specific calendar event by ID
router.get("/events/:id", (req: Request, res: Response) => {
  const eventId = req.params.id;
  const event = mockCalendarEvents.find(e => e.id === eventId);

  if (!event) {
    return res.status(404).json({ message: "Event not found" });
  }

  res.json(event);
});

// Create a new calendar event
router.post("/events", (req: Request, res: Response) => {
  const { date, startTime, endTime, tableNumber } = req.body;

  // Basic validation
  if (!date || !startTime || !endTime || !tableNumber) {
    return res.status(400).json({ message: "Date, start time, end time, and table number are required" });
  }

  const newEvent = {
    id: String(mockCalendarEvents.length + 1),
    date,
    startTime,
    endTime,
    tableNumber
  };

  mockCalendarEvents.push(newEvent);

  res.status(201).json(newEvent);
});

// Update a calendar event
router.put("/events/:id", (req: Request, res: Response) => {
  const eventId = req.params.id;
  const { date, startTime, endTime, tableNumber } = req.body;

  const eventIndex = mockCalendarEvents.findIndex(e => e.id === eventId);

  if (eventIndex === -1) {
    return res.status(404).json({ message: "Event not found" });
  }

  // Basic validation
  if (!date || !startTime || !endTime || !tableNumber) {
    return res.status(400).json({ message: "Date, start time, end time, and table number are required" });
  }

  mockCalendarEvents[eventIndex] = {
    id: eventId,
    date,
    startTime,
    endTime,
    tableNumber
  };

  res.json(mockCalendarEvents[eventIndex]);
});

// Delete a calendar event
router.delete("/events/:id", (req: Request, res: Response) => {
  const eventId = req.params.id;
  const eventIndex = mockCalendarEvents.findIndex(e => e.id === eventId);

  if (eventIndex === -1) {
    return res.status(404).json({ message: "Event not found" });
  }

  mockCalendarEvents.splice(eventIndex, 1);

  res.json({ message: "Event deleted successfully" });
});
