{"code":"import { useEffect, useState } from "react";

interface StaffMember {
  id: number;
  name: string;
  email: string;
  role: string;
}

export function StaffManagement() {
  const [staff, setStaff] = useState<StaffMember[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    role: "",
  });
  const [editingId, setEditingId] = useState<number | null>(null);

  useEffect(() => {
    fetchStaff();
  }, []);

  const fetchStaff = async () => {
    try {
      const response = await fetch("/api/staff");
      if (!response.ok) throw new Error("Failed to fetch staff");
      const data = await response.json();
      setStaff(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId !== null) {
      // Update existing staff member
      const response = await fetch(`/api/staff/${editingId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });
      if (response.ok) {
        fetchStaff();
        setEditingId(null);
        setFormData({ name: "", email: "", role: "" });
      }
    } else {
      // Add new staff member
      const response = await fetch("/api/staff", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });
      if (response.ok) {
        fetchStaff();
        setFormData({ name: "", email: "", role: "" });
      }
    }
  };

  const handleEdit = (staffMember: StaffMember) => {
    setFormData({
      name: staffMember.name,
      email: staffMember.email,
      role: staffMember.role,
    });
    setEditingId(staffMember.id);
  };

  const handleDelete = async (id: number) => {
    const response = await fetch(`/api/staff/${id}`, {
      method: "DELETE",
    });
    if (response.ok) {
      fetchStaff();
    }
  };

  const handleCancel = () => {
    setEditingId(null);
    setFormData({ name: "", email: "", role: "" });
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  const formStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
    marginBottom: "20px",
    padding: "15px",
    border: "1px solid #ccc",
    borderRadius: "5px",
    backgroundColor: "#f9f9f9",
  };

  const inputStyle: React.CSSProperties = {
    padding: "8px",
    borderRadius: "4px",
    border: "1px solid #ddd",
    width: "100%",
    boxSizing: "border-box",
  };

  const buttonStyle: React.CSSProperties = {
    padding: "8px 12px",
    borderRadius: "4px",
    border: "none",
    backgroundColor: "#007bff",
    color: "white",
    cursor: "pointer",
    marginRight: "5px",
  };

  const listStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
  };

  const cardStyle: React.CSSProperties = {
    padding: "10px",
    border: "1px solid #ddd",
    borderRadius: "5px",
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
  };

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "Arial, sans-serif" }}>
      <h1>Staff Management</h1>

      <form onSubmit={handleSubmit} style={formStyle}>
        <input
          type="text"
          placeholder="Name"
          value={formData.name}
          onChange={(e) => setFormData({ ...formData, name: e.target.value })}
          style={inputStyle}
        />
        <input
          type="email"
          placeholder="Email"
          value={formData.email}
          onChange={(e) => setFormData({ ...formData, email: e.target.value })}
          style={inputStyle}
        />
        <select
          value={formData.role}
          onChange={(e) => setFormData({ ...formData, role: e.target.value })}
          style={inputStyle}
        >
          <option value="">Select Role</option>
          <option value="dentist">Dentist</option>
          <option value="hygienist">Hygienist</option>
          <option value="receptionist">Receptionist</option>
          <option value="admin">Admin</option>
        </select>
        <button type="submit" style={buttonStyle}>{editingId ? "Update" : "Add"} Staff</button>
        {editingId && (
          <button type="button" onClick={handleCancel} style={{ ...buttonStyle, backgroundColor: "#6c757d" }}>
            Cancel
          </button>
        )}
      </form>

      <h2>Staff List</h2>
      <div style={listStyle}>
        {staff.length === 0 ? (
          <p>No staff members found.</p>
        ) : (
          staff.map((member) => (
            <div key={member.id} style={cardStyle}>
              <div>
                <strong>{member.name}</strong> - {member.email} ({member.role})
              </div>
              <div>
                <button
                  onClick={() => handleEdit(member)}
                  style={{ ...buttonStyle, backgroundColor: "#17a2b8" }}
                >
                  Edit
                </button>
                <button
                  onClick={() => handleDelete(member.id)}
                  style={{ ...buttonStyle, backgroundColor: "#dc3545" }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./family-photo-album.db");

interface CommentRow {
  id: number;
  photo_id: number;
  author_id: number;
  comment_text: string;
  timestamp: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS comments (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    photo_id INTEGER NOT NULL,
    author_id INTEGER NOT NULL,
    comment_text TEXT NOT NULL,
    timestamp TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllComments(): CommentRow[] {
  const stmt = db.prepare("SELECT * FROM comments");
  return stmt.all() as unknown as CommentRow[];
}

export function getCommentById(id: number): CommentRow | undefined {
  const stmt = db.prepare("SELECT * FROM comments WHERE id = ?");
  return stmt.get(id) as unknown as CommentRow | undefined;
}

export function insertComment(
  photoId: number,
  authorId: number,
  commentText: string,
  timestamp: string
): number {
  const stmt = db.prepare(
    "INSERT INTO comments (photo_id, author_id, comment_text, timestamp) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(photoId, authorId, commentText, timestamp);
  return Number(result.lastInsertRowid);
}

export function updateComment(
  id: number,
  photoId: number,
  authorId: number,
  commentText: string,
  timestamp: string
): void {
  const stmt = db.prepare(
    "UPDATE comments SET photo_id = ?, author_id = ?, comment_text = ?, timestamp = ? WHERE id = ?"
  );
  stmt.run(photoId, authorId, commentText, timestamp, id);
}

export function deleteComment(id: number): void {
  const stmt = db.prepare("DELETE FROM comments WHERE id = ?");
  stmt.run(id);
}

// Sample data insertion
if (getAllComments().length === 0) {
