  }

  const newBooking = mockCreateBooking({ userId, service, date, time });
  return res.status(201).json(newBooking);
});

// Get a booking by ID
router.get('/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid booking ID' });
  }

  const booking = mockGetBookingById(id);

  if (!booking) {
    return res.status(404).json({ error: 'Booking not found' });
  }

  return res.json(booking);
});

// Update a booking
router.put('/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { service, date, time } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid booking ID' });
  }

  if (!service || !date || !time) {
    return res.status(400).json({ error: 'Missing required fields: service, date, time' });
  }

  const updatedBooking = mockUpdateBooking(id, { service, date, time });

  if (!updatedBooking) {
    return res.status(404).json({ error: 'Booking not found' });
  }

  return res.json(updatedBooking);
});

// Cancel a booking
router.delete('/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid booking ID' });
  }

