  return mockRequests.find(request => request.id === id);
};

const createRequest = (request: any) => {
  const newId = Math.max(0, ...mockRequests.map(r => r.id)) + 1;
  const newRequest = { ...request, id: newId };
  mockRequests.push(newRequest);
  return newRequest;
};

const updateRequest = (id: number, updates: any) => {
  const index = mockRequests.findIndex(request => request.id === id);
  if (index === -1) return null;
  mockRequests[index] = { ...mockRequests[index], ...updates };
  return mockRequests[index];
};

const deleteRequest = (id: number) => {
  const index = mockRequests.findIndex(request => request.id === id);
  if (index === -1) return false;
  mockRequests.splice(index, 1);
  return true;
};

// GET /requests - List all requests
router.get("/requests", (req: Request, res: Response) => {
  res.json(mockRequests);
});

// GET /requests/:id - Get a specific request by ID
router.get("/requests/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid request ID" });
  }

  const request = findRequestById(id);
  if (!request) {
    return res.status(404).json({ error: "Request not found" });
  }

  res.json(request);
});

// POST /requests - Create a new request
router.post("/requests", (req: Request, res: Response) => {
  const { item, quantity, status } = req.body;

  if (!item || !quantity || !status) {
    return res.status(400).json({ error: "Item, quantity, and status are required" });
  }

  const newRequest = createRequest({ item, quantity, status });
  res.status(201).json(newRequest);
});

// PUT /requests/:id - Update an existing request
router.put("/requests/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid request ID" });
  }

  const { item, quantity, status } = req.body;

  const updatedRequest = updateRequest(id, { item, quantity, status });

  if (!updatedRequest) {
    return res.status(404).json({ error: "Request not found" });
  }

  res.json(updatedRequest);
});

// DELETE /requests/:id - Delete a request
router.delete("/requests/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid request ID" });
  }

  const deleted = deleteRequest(id);

  if (!deleted) {
    return res.status(404).json({ error: "Request not found" });
  }

  res.json({ message: "Request deleted successfully" });
});
"}

