{"code":"import { useEffect, useState } from "react";

interface CertificateRequest {
  id: string;
  studentName: string;
  studentId: string;
  certificateType: string;
  status: "pending" | "approved" | "rejected";
  requestedAt: string;
}

export function ApprovalDashboard() {
  const [requests, setRequests] = useState<CertificateRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchPendingRequests();
  }, []);

  const fetchPendingRequests = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/certificate-requests/pending");
      if (!response.ok) {
        throw new Error(`Failed to fetch requests: ${response.status}`);
      }
      const data = await response.json();
      setRequests(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleApprove = async (id: string) => {
    try {
      const response = await fetch(`/api/certificate-requests/${id}/approve`, {
        method: "POST",
      });
      if (!response.ok) {
        throw new Error(`Failed to approve request: ${response.status}`);
      }
      // Refresh the list
      fetchPendingRequests();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleReject = async (id: string) => {
    try {
      const response = await fetch(`/api/certificate-requests/${id}/reject`, {
        method: "POST",
      });
      if (!response.ok) {
        throw new Error(`Failed to reject request: ${response.status}`);
      }
      // Refresh the list
      fetchPendingRequests();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (requests.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No pending certificate requests.
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Certificate Requests</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {requests.map((request) => (
          <div
            key={request.id}
            style={{
              border: "1px solid #ccc",
              borderRadius: "8px",
              padding: "15px",
              display: "flex",
              flexDirection: "column",
              gap: "10px",
            }}
          >
            <div style={{ display: "flex", justifyContent: "space-between" }}>
              <div>
                <strong>{request.studentName}</strong>
                <br />
                Student ID: {request.studentId}
                <br />
                Type: {request.certificateType}
              </div>
              <div style={{ fontSize: "0.9em", color: "#666" }}>
                Requested: {new Date(request.requestedAt).toLocaleDateString()}
              </div>
            </div>
            <div style={{ display: "flex", gap: "10px", justifyContent: "flex-end" }}>
              <button
                onClick={() => handleApprove(request.id)}
                style={{
                  backgroundColor: "#4CAF50",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  padding: "8px 12px",
                  cursor: "pointer",
                }}
              >
                Approve
              </button>
              <button
                onClick={() => handleReject(request.id)}
                style={{
                  backgroundColor: "#f44336",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  padding: "8px 12px",
                  cursor: "pointer",
                }}
              >
                Reject
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
"}

