{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockDatabase = {
  patients: [
    { id: "1", name: "John Doe", email: "john@example.com", phone: "123-456-7890", medicalHistory: "Allergic to penicillin" },
    { id: "2", name: "Jane Smith", email: "jane@example.com", phone: "098-765-4321", medicalHistory: "Diabetic" }
  ],

  findPatientById(id: string) {
    return this.patients.find(patient => patient.id === id);
  },

  findAllPatients() {
    return this.patients;
  },

  createPatient(patientData: any) {
    const newPatient = {
      id: (this.patients.length + 1).toString(),
      ...patientData
    };
    this.patients.push(newPatient);
    return newPatient;
  },

  updatePatient(id: string, updatedData: any) {
    const index = this.patients.findIndex(patient => patient.id === id);
    if (index !== -1) {
      this.patients[index] = { ...this.patients[index], ...updatedData };
      return this.patients[index];
    }
    return null;
  },

  deletePatient(id: string) {
    const index = this.patients.findIndex(patient => patient.id === id);
    if (index !== -1) {
      this.patients.splice(index, 1);
      return true;
    }
    return false;
  }
};

// GET /patients - List all patients
router.get("/patients", (req: Request, res: Response) => {
  try {
    const patients = mockDatabase.findAllPatients();
    res.json(patients);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// GET /patients/:id - Get a specific patient by ID
router.get("/patients/:id", (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    const patient = mockDatabase.findPatientById(id);

    if (!patient) {
      return res.status(404).json({ error: "Patient not found" });
    }

    res.json(patient);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// POST /patients - Create a new patient
router.post("/patients", (req: Request, res: Response) => {
  try {
    const { name, email, phone, medicalHistory } = req.body;

    // Validate required fields
    if (!name || !email || !phone) {
      return res.status(400).json({ error: "Name, email, and phone are required" });
    }

    const newPatient = mockDatabase.createPatient({ name, email, phone, medicalHistory });
    res.status(201).json(newPatient);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// PUT /patients/:id - Update a patient
router.put("/patients/:id", (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    const { name, email, phone, medicalHistory } = req.body;

    const updatedPatient = mockDatabase.updatePatient(id, { name, email, phone, medicalHistory });

    if (!updatedPatient) {
      return res.status(404).json({ error: "Patient not found" });
    }

    res.json(updatedPatient);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// DELETE /patients/:id - Delete a patient
router.delete("/patients/:id", (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    const deleted = mockDatabase.deletePatient(id);

    if (!deleted) {
      return res.status(404).json({ error: "Patient not found" });
    }

    res.json({ message: "Patient deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});
"}

