export const db = new DatabaseSync("./shop-register.db");

interface BillType {
  id: number;
  name: string;
  fee: number;
  processing_rules: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS bill_types (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    fee REAL NOT NULL,
    processing_rules TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllBillTypes(): BillType[] {
  const stmt = db.prepare("SELECT * FROM bill_types");
  return stmt.all() as unknown as BillType[];
}

export function getBillTypeById(id: number): BillType | undefined {
  const stmt = db.prepare("SELECT * FROM bill_types WHERE id = ?");
  return stmt.get(id) as unknown as BillType | undefined;
}

export function insertBillType(name: string, fee: number, processing_rules: string): number {
  const stmt = db.prepare(
    "INSERT INTO bill_types (name, fee, processing_rules) VALUES (?, ?, ?)"
  );
  const result = stmt.run(name, fee, processing_rules);
  return Number(result.lastInsertRowid);
}

export function updateBillType(id: number, name: string, fee: number, processing_rules: string): void {
  const stmt = db.prepare(
    "UPDATE bill_types SET name = ?, fee = ?, processing_rules = ? WHERE id = ?"
