{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./dog-park.db");

interface AuditTrailRow {
  id: number;
  member_id: number;
  event_type: "check-in" | "check-out";
  timestamp: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS audit_trail (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    member_id INTEGER NOT NULL,
    event_type TEXT NOT NULL CHECK(event_type IN ('check-in', 'check-out')),
    timestamp TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllAuditTrail(): AuditTrailRow[] {
  const stmt = db.prepare(`SELECT * FROM audit_trail ORDER BY timestamp DESC`);
  return stmt.all() as unknown as AuditTrailRow[];
}

export function getAuditTrailById(id: number): AuditTrailRow | undefined {
  const stmt = db.prepare(
    `SELECT * FROM audit_trail WHERE id = ? LIMIT 1`
  );
  return stmt.get(id) as unknown as AuditTrailRow | undefined;
}

export function insertAuditTrail(
  member_id: number,
  event_type: "check-in" | "check-out",
  timestamp: string
): number {
  const stmt = db.prepare(
    `INSERT INTO audit_trail (member_id, event_type, timestamp) VALUES (?, ?, ?)`
  );
  const result = stmt.run(member_id, event_type, timestamp);
  return Number(result.lastInsertRowid);
}

export function updateAuditTrail(
  id: number,
  member_id: number,
  event_type: "check-in" | "check-out",
  timestamp: string
): void {
  const stmt = db.prepare(
    `UPDATE audit_trail SET member_id = ?, event_type = ?, timestamp = ? WHERE id = ?`
  );
  stmt.run(member_id, event_type, timestamp, id);
}

export function deleteAuditTrail(id: number): void {
  const stmt = db.prepare(`DELETE FROM audit_trail WHERE id = ?`);
  stmt.run(id);
}

// Sample data insertion
if (getAllAuditTrail().length === 0) {
  insertAuditTrail(101, "check-in", "2023-05-15T08:30:00Z");
  insertAuditTrail(102, "check-in", "2023-05-15T09:15:00Z");
  insertAuditTrail(101, "check-out", "2023-05-15T17:45:00Z");
  insertAuditTrail(103, "check-in", "2023-05-15T10:00:00Z");
  insertAuditTrail(102, "check-out", "2023-05-15T18:00:00Z");
}
