{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockShowtimes = [
  { id: "1", date: "2023-10-15", time: "19:00", theater: "A", movieId: "1" },
  { id: "2", date: "2023-10-16", time: "20:30", theater: "B", movieId: "2" },
];

const findShowtimeById = (id: string) => {
  return mockShowtimes.find(showtime => showtime.id === id);
};

const createShowtime = (showtime: Omit<Showtime, "id">) => {
  const newShowtime = {
    ...showtime,
    id: String(mockShowtimes.length + 1),
  };
  mockShowtimes.push(newShowtime);
  return newShowtime;
};

const updateShowtime = (id: string, updatedShowtime: Partial<Showtime>) => {
  const index = mockShowtimes.findIndex(showtime => showtime.id === id);
  if (index === -1) return null;
  mockShowtimes[index] = { ...mockShowtimes[index], ...updatedShowtime };
  return mockShowtimes[index];
};

const deleteShowtime = (id: string) => {
  const index = mockShowtimes.findIndex(showtime => showtime.id === id);
  if (index === -1) return false;
  mockShowtimes.splice(index, 1);
  return true;
};

interface Showtime {
  id: string;
  date: string;
  time: string;
  theater: string;
  movieId: string;
}

// GET /showtimes - List all showtimes
router.get("/showtimes", (req: Request, res: Response) => {
  res.json(mockShowtimes);
});

// GET /showtimes/:id - Get a specific showtime by ID
router.get("/showtimes/:id", (req: Request, res: Response) => {
  const showtime = findShowtimeById(req.params.id);
  if (!showtime) {
    return res.status(404).json({ error: "Showtime not found" });
  }
  res.json(showtime);
});

// POST /showtimes - Create a new showtime
router.post("/showtimes", (req: Request, res: Response) => {
  const { date, time, theater, movieId } = req.body;

  if (!date || !time || !theater || !movieId) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const newShowtime = createShowtime({ date, time, theater, movieId });
  res.status(201).json(newShowtime);
});

// PUT /showtimes/:id - Update an existing showtime
router.put("/showtimes/:id", (req: Request, res: Response) => {
  const { date, time, theater, movieId } = req.body;

  const updatedShowtime = updateShowtime(req.params.id, { date, time, theater, movieId });

  if (!updatedShowtime) {
    return res.status(404).json({ error: "Showtime not found" });
  }

  res.json(updatedShowtime);
});

// DELETE /showtimes/:id - Delete a showtime
router.delete("/showtimes/:id", (req: Request, res: Response) => {
  const deleted = deleteShowtime(req.params.id);

  if (!deleted) {
    return res.status(404).json({ error: "Showtime not found" });
  }

  res.json({ message: "Showtime deleted successfully" });
});
"}

