  const [publisherFilter, setPublisherFilter] = useState("");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");

  // Fetch newspapers
  useEffect(() => {
    const fetchNewspapers = async () => {
      try {
        // In a real app, this would be an API call
        // For now, we'll simulate with mock data
        await new Promise(resolve => setTimeout(resolve, 500));

        const mockData: Newspaper[] = [
          { id: "1", title: "The Daily Herald", publisher: "Herald Publishing", publicationDate: "1923-05-15" },
          { id: "2", title: "Morning Times", publisher: "Times Group", publicationDate: "1924-08-22" },
          { id: "3", title: "Evening Star", publisher: "Star Media", publicationDate: "1922-12-01" },
          { id: "4", title: "City Journal", publisher: "Journal Corp", publicationDate: "1925-03-10" },
          { id: "5", title: "News Chronicle", publisher: "Chronicle Ltd", publicationDate: "1921-11-18" },
        ];

        setNewspapers(mockData);
        setLoading(false);
      } catch (err) {
        setError("Failed to load newspapers");
        setLoading(false);
      }
    };

    fetchNewspapers();
  }, []);

  // Apply filters
  const filteredNewspapers = newspapers.filter(newspaper => {
    const matchesTitle = titleFilter === "" || 
      newspaper.title.toLowerCase().includes(titleFilter.toLowerCase());

    const matchesPublisher = publisherFilter === "" || 
      newspaper.publisher.toLowerCase().includes(publisherFilter.toLowerCase());

    const matchesDate = (
      (startDate === "" || newspaper.publicationDate >= startDate) &&
      (endDate === "" || newspaper.publicationDate <= endDate)
    );

    return matchesTitle && matchesPublisher && matchesDate;
  });

  // Styles
  const containerStyle: React.CSSProperties = {
    maxWidth: "1200px",
    margin: "0 auto",
    padding: "20px",
    fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
