export const router = Router();

// Mock database functions - in a real app these would connect to a database
const matches = [
  {
    id: "1",
    team1: "Team A",
    team2: "Team B",
    score1: 150,
    score2: 120,
    status: "completed"
  },
  {
    id: "2",
    team1: "Team C",
    team2: "Team D",
    score1: 0,
    score2: 0,
    status: "scheduled"
  }
];

const findMatchById = (id: string) => {
  return matches.find(match => match.id === id);
};

const createMatch = (matchData: any) => {
  const newMatch = {
    id: (matches.length + 1).toString(),
    ...matchData
  };
  matches.push(newMatch);
  return newMatch;
};

const updateMatch = (id: string, updatedData: any) => {
  const index = matches.findIndex(match => match.id === id);
  if (index !== -1) {
    matches[index] = { ...matches[index], ...updatedData };
    return matches[index];
  }
  return null;
};

const deleteMatch = (id: string) => {
  const index = matches.findIndex(match => match.id === id);
  if (index !== -1) {
    matches.splice(index, 1);
    return true;
  }
  return false;
};

// GET /matches - List all matches
router.get("/matches", (req: Request, res: Response) => {
  res.json(matches);
});

// GET /matches/:id - Get a specific match by ID
router.get("/matches/:id", (req: Request, res: Response) => {
  const match = findMatchById(req.params.id);
  if (!match) {
    return res.status(404).json({ error: "Match not found" });
  }
  res.json(match);
});

// POST /matches - Create a new match
router.post("/matches", (req: Request, res: Response) => {
  const { team1, team2, score1, score2, status } = req.body;

  if (!team1 || !team2) {
    return res.status(400).json({ error: "Team names are required" });
  }

  const newMatch = createMatch({ team1, team2, score1, score2, status });
  res.status(201).json(newMatch);
});

// PUT /matches/:id - Update a match
router.put("/matches/:id", (req: Request, res: Response) => {
  const match = findMatchById(req.params.id);

  if (!match) {
    return res.status(404).json({ error: "Match not found" });
  }

  const { team1, team2, score1, score2, status } = req.body;

  const updatedMatch = updateMatch(req.params.id, { team1, team2, score1, score2, status });

  if (!updatedMatch) {
    return res.status(404).json({ error: "Match not found" });
  }

  res.json(updatedMatch);
});

// DELETE /matches/:id - Delete a match
router.delete("/matches/:id", (req: Request, res: Response) => {
  const deleted = deleteMatch(req.params.id);

  if (!deleted) {
    return res.status(404).json({ error: "Match not found" });
  }

  res.json({ message: "Match deleted successfully" });
});
