{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  { id: 1, username: "patient1", password: "pass123", role: "patient" },
  { id: 2, username: "staff1", password: "pass123", role: "staff" },
  { id: 3, username: "admin1", password: "pass123", role: "admin" }
];

// Registration endpoint
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role } = req.body;

  // Validate input
  if (!username || !password || !role) {
    return res.status(400).json({ error: "Username, password, and role are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    username,
    password,
    role
  };

  users.push(newUser);
  return res.status(201).json(newUser);
});

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  // Validate input
  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Find user
  const user = users.find(u => u.username === username && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Return user info (in a real app, this would be a JWT token)
  return res.json({
    username: user.username,
    role: user.role
  });
});

// Role-based access control middleware
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: Function) => {
    const { role } = req.body;
    if (!roles.includes(role)) {
      return res.status(403).json({ error: "Access denied" });
    }
    next();
  };
};

// Protected route examples
router.get("/patient", authorize(["patient", "staff", "admin"]), (req: Request, res: Response) => {
  return res.json({ message: "Patient dashboard accessible" });
});

router.get("/staff", authorize(["staff", "admin"]), (req: Request, res: Response) => {
  return res.json({ message: "Staff dashboard accessible" });
});

router.get("/admin", authorize(["admin"]), (req: Request, res: Response) => {
  return res.json({ message: "Admin dashboard accessible" });
});
"}

