{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes
const ACTIVE_SESSIONS = new Map<string, { expires: number }>();

function getCookieValue(cookieHeader: string | undefined, cookieName: string): string | null {
  if (!cookieHeader) return null;
  const cookies = cookieHeader.split(";").map(c => c.trim());
  for (const cookie of cookies) {
    const [name, value] = cookie.split("=");
    if (name === cookieName) {
      return value || null;
    }
  }
  return null;
}

function generateSessionId(): string {
  return Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);
}

function verifyToken(token: string): boolean {
  const secret = process.env.JWT_SECRET;
  if (!secret) return false;

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) return false;

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /logout
  if (req.method !== "POST" || req.path !== "/logout") {
    next();
    return;
  }

  const sessionId = getCookieValue(req.headers.cookie, "session_id");

  if (!sessionId) {
    res.status(401).json({ error: "No active session found" });
    return;
  }

  const session = ACTIVE_SESSIONS.get(sessionId);

  if (!session) {
    res.status(401).json({ error: "Invalid session ID" });
    return;
  }

  // Check if session has expired
  if (Date.now() > session.expires) {
    ACTIVE_SESSIONS.delete(sessionId);
    res.status(401).json({ error: "Session expired" });
    return;
  }

  // Verify token if present
  const token = getCookieValue(req.headers.cookie, "auth_token");
  if (token && !verifyToken(token)) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // Remove session on successful logout
  ACTIVE_SESSIONS.delete(sessionId);

  // Clear session cookie
  res.clearCookie("session_id");
  res.clearCookie("auth_token");

  res.json({ message: "Logged out successfully" });
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/tmp/choir-attendance.db"
);

interface AttendanceRecord {
  id: number;
  singer_id: number;
  date: string;
  status: "present" | "absent";
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS attendance (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    singer_id INTEGER NOT NULL,
    date TEXT NOT NULL,
    status TEXT NOT NULL CHECK(status IN ('present', 'absent'))
  )
`;

db.exec(createTableSql);

export function getAllAttendance(): AttendanceRecord[] {
  const stmt = db.prepare(`
    SELECT * FROM attendance
  `);
  return stmt.all() as unknown as AttendanceRecord[];
}

export function getAttendanceById(id: number): AttendanceRecord | undefined {
  const stmt = db.prepare(`
    SELECT * FROM attendance WHERE id = ?
  `);
  return stmt.get(id) as unknown as AttendanceRecord | undefined;
}

export function insertAttendance(
  singerId: number,
  date: string,
  status: "present" | "absent"
): number {
  const stmt = db.prepare(`
    INSERT INTO attendance (singer_id, date, status)
    VALUES (?, ?, ?)
  `);
  const result = stmt.run(singerId, date, status);
  return Number(result.lastInsertRowid);
}

export function updateAttendance(
  id: number,
  singerId: number,
  date: string,
  status: "present" | "absent"
): void {
  const stmt = db.prepare(`
    UPDATE attendance
    SET singer_id = ?, date = ?, status = ?
    WHERE id = ?
  `);
  stmt.run(singerId, date, status, id);
}

export function deleteAttendance(id: number): void {
  const stmt = db.prepare(`
    DELETE FROM attendance WHERE id = ?
  `);
  stmt.run(id);
}

// Seed data
if (getAllAttendance().length === 0) {
  insertAttendance(1, "2023-05-01", "present");
  insertAttendance(2, "2023-05-01", "absent");
  insertAttendance(3, "2023-05-02", "present");
  insertAttendance(4, "2023-05-02", "present");
  insertAttendance(5, "2023-05-03", "absent");
}
