}

export function AdminPanel() {
  const [requests, setRequests] = useState<Request[]>([]);
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchRequests();
    fetchInventory();
  }, []);

  const fetchRequests = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/requests");
      if (!response.ok) throw new Error("Failed to fetch requests");
      const data = await response.json();
      setRequests(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const fetchInventory = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/inventory");
      if (!response.ok) throw new Error("Failed to fetch inventory");
      const data = await response.json();
      setInventory(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleApprove = async (id: number) => {
    try {
      const response = await fetch(`/api/requests/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "approved" }),
      });
      if (!response.ok) throw new Error("Failed to approve request");
      await fetchRequests();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleReject = async (id: number) => {
    try {
      const response = await fetch(`/api/requests/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "rejected" }),
      });
      if (!response.ok) throw new Error("Failed to reject request");
      await fetchRequests();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "1200px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Admin Panel</h1>

      <section style={{ marginBottom: "40px" }}>
        <h2>Requests Management</h2>
        {requests.length === 0 ? (
          <p style={{ textAlign: "center", color: "#666" }}>No requests found.</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {requests.map(request => (
              <div key={request.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <strong>{request.userName}</strong> requested {request.quantity} x {request.item}
                  <br />
                  <small>Status: {request.status}</small>
                </div>
                <div>
                  {request.status === "pending" && (
                    <>
                      <button 
                        onClick={() => handleApprove(request.id)}
                        style={{ backgroundColor: "#4CAF50", color: "white", border: "none", padding: "8px 12px", marginRight: "10px", borderRadius: "4px", cursor: "pointer" }}
                      >
                        Approve
                      </button>
                      <button 
                        onClick={() => handleReject(request.id)}
                        style={{ backgroundColor: "#f44336", color: "white", border: "none", padding: "8px 12px", borderRadius: "4px", cursor: "pointer" }}
                      >
                        Reject
                      </button>
                    </>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </section>

      <section>
        <h2>Inventory Tracking</h2>
        {inventory.length === 0 ? (
          <p style={{ textAlign: "center", color: "#666" }}>No inventory items found.</p>
        ) : (
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(300px, 1fr))", gap: "20px" }}>
            {inventory.map(item => (
              <div key={item.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px" }}>
                <h3>{item.name}</h3>
                <p><strong>Stock:</strong> {item.stock}</p>
                <p><strong>Category:</strong> {item.category}</p>
              </div>
            ))}
          </div>
        )}
      </section>
    </div>
  );
}
