{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data to simulate database operations
let payments = [
  { id: "1", studentId: "101", amount: 150, date: "2023-06-15", status: "paid" },
  { id: "2", studentId: "102", amount: 200, date: "2023-06-16", status: "pending" }
];

let nextId = 3;

// GET /payments - List all payments
router.get("/payments", (req: Request, res: Response) => {
  res.json(payments);
});

// GET /payments/:id - Get a specific payment by ID
router.get("/payments/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const payment = payments.find(p => p.id === id);

  if (!payment) {
    return res.status(404).json({ error: "Payment not found" });
  }

  res.json(payment);
});

// POST /payments - Create a new payment
router.post("/payments", (req: Request, res: Response) => {
  const { studentId, amount, date, status } = req.body;

  // Basic validation
  if (!studentId || !amount || !date || !status) {
    return res.status(400).json({ error: "Missing required fields: studentId, amount, date, status" });
  }

  const newPayment = {
    id: String(nextId++),
    studentId,
    amount: Number(amount),
    date,
    status
  };

  payments.push(newPayment);
  res.status(201).json(newPayment);
});

// PUT /payments/:id - Update a payment
router.put("/payments/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const { studentId, amount, date, status } = req.body;

  const paymentIndex = payments.findIndex(p => p.id === id);

  if (paymentIndex === -1) {
    return res.status(404).json({ error: "Payment not found" });
  }

  // Basic validation
  if (!studentId || !amount || !date || !status) {
    return res.status(400).json({ error: "Missing required fields: studentId, amount, date, status" });
  }

  payments[paymentIndex] = {
    id,
    studentId,
    amount: Number(amount),
    date,
    status
  };

  res.json(payments[paymentIndex]);
});

// DELETE /payments/:id - Delete a payment
router.delete("/payments/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const paymentIndex = payments.findIndex(p => p.id === id);

  if (paymentIndex === -1) {
    return res.status(404).json({ error: "Payment not found" });
  }

  payments.splice(paymentIndex, 1);
  res.json({ message: "Payment deleted successfully" });
});
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/tmp/library-catalog.db"
);

interface Book {
  id: number;
  title: string;
  author: string;
  isbn: string;
  copyCount: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS books (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    author TEXT NOT NULL,
    isbn TEXT NOT NULL UNIQUE,
    copyCount INTEGER NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllBooks(): Book[] {
  const stmt = db.prepare(`SELECT * FROM books`);
  return stmt.all() as unknown as Book[];
}

export function getBookById(id: number): Book | undefined {
  const stmt = db.prepare(`SELECT * FROM books WHERE id = ?`);
  return stmt.get(id) as unknown as Book | undefined;
}

export function insertBook(
  title: string,
  author: string,
  isbn: string,
  copyCount: number
): number {
  const stmt = db.prepare(
    `INSERT INTO books (title, author, isbn, copyCount) VALUES (?, ?, ?, ?)`
  );
  const result = stmt.run(title, author, isbn, copyCount);
  return Number(result.lastInsertRowid);
}

export function updateBook(
  id: number,
  title: string,
  author: string,
  isbn: string,
  copyCount: number
): void {
  const stmt = db.prepare(
    `UPDATE books SET title = ?, author = ?, isbn = ?, copyCount = ? WHERE id = ?`
  );
  stmt.run(title, author, isbn, copyCount, id);
}

export function deleteBook(id: number): void {
  const stmt = db.prepare(`DELETE FROM books WHERE id = ?`);
  stmt.run(id);
}

