  getAllDropOffs: () => Promise.resolve([{ id: 1, weight: 50, category: "plastic", timestamp: "2023-01-01T00:00:00Z" }]),
  updateDropOff: (id: number, data: any) => Promise.resolve({ id, ...data }),
  deleteDropOff: (id: number) => Promise.resolve(true)
};

// GET /drop-offs - Get all drop-offs
router.get("/drop-offs", async (req: Request, res: Response) => {
  try {
    const dropOffs = await mockDatabase.getAllDropOffs();
    res.json(dropOffs);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch drop-offs" });
  }
});

// GET /drop-offs/:id - Get a specific drop-off by ID
router.get("/drop-offs/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const dropOff = await mockDatabase.getDropOffById(id);
    if (!dropOff) {
      return res.status(404).json({ error: "Drop-off not found" });
    }

    res.json(dropOff);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch drop-off" });
  }
});

// POST /drop-offs - Create a new drop-off
router.post("/drop-offs", async (req: Request, res: Response) => {
  try {
    const { weight, category } = req.body;

    if (!weight || !category) {
      return res.status(400).json({ error: "Weight and category are required" });
    }

    const newDropOff = await mockDatabase.createDropOff({ weight, category });
    res.status(201).json(newDropOff);
  } catch (error) {
    res.status(500).json({ error: "Failed to create drop-off" });
  }
});

// PUT /drop-offs/:id - Update an existing drop-off
router.put("/drop-offs/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const { weight, category } = req.body;

    if (!weight || !category) {
      return res.status(400).json({ error: "Weight and category are required" });
    }

    const updatedDropOff = await mockDatabase.updateDropOff(id, { weight, category });

    if (!updatedDropOff) {
      return res.status(404).json({ error: "Drop-off not found" });
    }

    res.json(updatedDropOff);
  } catch (error) {
    res.status(500).json({ error: "Failed to update drop-off" });
  }
});

// DELETE /drop-offs/:id - Delete a drop-off
router.delete("/drop-offs/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const deleted = await mockDatabase.deleteDropOff(id);

    if (!deleted) {
      return res.status(404).json({ error: "Drop-off not found" });
    }

    res.json({ message: "Drop-off deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete drop-off" });
  }
});
