{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check for DELETE requests to booking routes
  if (req.method !== "DELETE" || !req.path.startsWith("/bookings/")) {
    next();
    return;
  }

  // Check if user has supervisor role
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Internal server error: JWT_SECRET not configured" });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify properly)
  // For this example, we'll assume the token contains role info in a known format
  try {
    // This is a simplified check - in reality, you'd decode the JWT and verify its signature
    // using HMAC-SHA256 with the secret
    const expectedSignature = createHmac("sha256", secret)
      .update(token.split(".")[0] + "." + token.split(".")[1])
      .digest();

    const actualSignature = Buffer.from(token.split(".")[2], "base64");

    if (expectedSignature.length !== actualSignature.length || 
        !timingSafeEqual(expectedSignature, actualSignature)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // In a real implementation, you would decode the token to check the role
    // For now, we'll just simulate checking the role
    const decodedToken = JSON.parse(Buffer.from(token.split(".")[1], "base64").toString());

    if (decodedToken.role !== "supervisor") {
      res.status(403).json({ error: "Forbidden: Supervisor role required to delete bookings" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}
"}

