  const stmt = db.prepare(`SELECT * FROM inspections WHERE id = ?`);
  return stmt.get(id) as unknown as Inspection | undefined;
}

export function insertInspection(
  date: string,
  inspectorName: string,
  checklistItems: string,
  status: string,
  notes: string
): number {
  const stmt = db.prepare(
    `INSERT INTO inspections (date, inspectorName, checklistItems, status, notes) VALUES (?, ?, ?, ?, ?)`
  );
  const result = stmt.run(date, inspectorName, checklistItems, status, notes);
  return Number(result.lastInsertRowid);
}

