  if (req.method !== "POST" || req.path !== "/auth/callback") {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;

  // If JWT_SECRET is not set, reject all tokens
  if (!jwtSecret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  // In a real implementation, we would verify the JWT signature here
  // For now, we'll just simulate the verification process
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Simulate token verification - in reality, this would verify HMAC-SHA256 signature
