    res.status(400).send("Invalid input");
    return;
  }
  logHabit(userId, date, habit);
  res.status(201).send("Habit logged successfully");
});

router.get("/streak", (req: Request, res: Response) => {
  const { userId, date } = req.query;
  if (typeof userId !== "string" || typeof date !== "string") {
    res.status(400).send("Invalid query parameters");
    return;
  }
  const habits = getHabitsByUserAndDate(Number(userId), date);
  res.status(200).json(habits);
});
