{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./community-garden.db");

interface RoleRow {
  user_id: number;
  role: "member" | "owner";
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS roles (
    user_id INTEGER NOT NULL,
    role TEXT NOT NULL CHECK(role IN ('member', 'owner')),
    PRIMARY KEY (user_id)
  )
`;

db.exec(createTableSql);

export function getAllRoles(): RoleRow[] {
  const stmt = db.prepare("SELECT * FROM roles");
  return stmt.all() as unknown as RoleRow[];
}

export function getRoleByUserId(userId: number): RoleRow | undefined {
  const stmt = db.prepare("SELECT * FROM roles WHERE user_id = ?");
  return stmt.get(userId) as unknown as RoleRow | undefined;
}

export function insertRole(userId: number, role: "member" | "owner"): number {
  const stmt = db.prepare("INSERT INTO roles (user_id, role) VALUES (?, ?)");
  const result = stmt.run(userId, role);
  return Number(result.lastInsertRowid);
}

export function updateRole(userId: number, role: "member" | "owner"): number {
  const stmt = db.prepare("UPDATE roles SET role = ? WHERE user_id = ?");
  const result = stmt.run(role, userId);
  return Number(result.changes);
}

export function deleteRole(userId: number): number {
  const stmt = db.prepare("DELETE FROM roles WHERE user_id = ?");
  const result = stmt.run(userId);
  return Number(result.changes);
}

// Seed data
if (getAllRoles().length === 0) {
  insertRole(1, "owner");
  insertRole(2, "member");
  insertRole(3, "member");
  insertRole(4, "member");
  insertRole(5, "member");
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes

interface Session {
  userId: string;
  createdAt: number;
}

function isValidToken(token: string): boolean {
  if (!process.env.JWT_SECRET) {
    return false;
  }

  const parts = token.split(".");
  if (parts.length !== 3) {
    return false;
  }

  const [header, payload, signature] = parts;

  try {
    const expectedSignature = createHmac("sha256", process.env.JWT_SECRET)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(signature, "base64url");

    return timingSafeEqual(expectedBuffer, actualBuffer);
  } catch {
    return false;
  }
}

function parsePayload(payload: string): { userId: string; iat: number } | null {
  try {
    const decoded = Buffer.from(payload, "base64url").toString("utf-8");
    return JSON.parse(decoded);
  } catch {
    return null;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  if (!token) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  if (!isValidToken(token)) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  const payload = parsePayload(token.split(".")[1]);
  if (!payload) {
    res.status(401).json({ error: "Invalid token payload" });
    return;
  }

  if (!payload.userId) {
    res.status(401).json({ error: "Invalid token payload" });
    return;
  }

  // Simulate session storage lookup
  const session: Session = {
    userId: payload.userId,
    createdAt: payload.iat * 1000,
  };

  if (Date.now() - session.createdAt > SESSION_TIMEOUT) {
    res.status(401).json({ error: "Session expired" });
    return;
  }

  // Store session data in request object for downstream middleware/routes
  (req as any).session = session;
  next();
}
"}

