export function ClassScheduling() {
  const [classes, setClasses] = useState<ClassSchedule[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchClasses();
  }, []);

  const fetchClasses = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/classes');
      if (!response.ok) {
        throw new Error('Failed to fetch classes');
      }
      const data = await response.json();
      setClasses(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleRegister = async (classId: number) => {
    try {
      const response = await fetch(`/api/classes/${classId}/register`, {
        method: 'POST',
      });
      if (!response.ok) {
        throw new Error('Failed to register for class');
      }
      // Refresh the class list after registration
      fetchClasses();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
