{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database - in a real app this would be a proper database
const users = [
  { id: 1, username: "admin", password: "admin123", role: "administrator" },
  { id: 2, username: "teacher", password: "teacher123", role: "teacher" },
  { id: 3, username: "student", password: "student123", role: "student" }
];

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // In a real app, you would generate a JWT token here
  return res.json({
    user: {
      id: user.id,
      username: user.username,
      role: user.role
    },
    token: "mock-jwt-token"
  });
});

// Registration endpoint
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role } = req.body;

  if (!username || !password || !role) {
    return res.status(400).json({ error: "Username, password, and role are required" });
  }

  // Check if user already exists
  if (users.some(u => u.username === username)) {
    return res.status(409).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    username,
    password,
    role
  };

  users.push(newUser);

  return res.status(201).json({
    user: {
      id: newUser.id,
      username: newUser.username,
      role: newUser.role
    }
  });
});

// Role-based access control middleware
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    // In a real app, you would decode the JWT token here
    const mockUser = users[0]; // Mock user for demo purposes

    if (!mockUser || mockUser.role !== requiredRole) {
      return res.status(403).json({ error: "Access denied" });
    }

    next();
  };
};

// Protected route example - only administrators can access
router.get("/admin", requireRole("administrator"), (req: Request, res: Response) => {
  return res.json({ message: "Welcome, administrator!" });
});
"}

