    border: "none",
    padding: "12px 20px",
    borderRadius: "4px",
    cursor: "pointer",
    fontSize: "16px",
    width: "100%",
  };

  const successMessageStyle: React.CSSProperties = {
    color: "green",
    textAlign: "center",
    marginTop: "20px",
  };

  const errorMessageStyle: React.CSSProperties = {
    color: "red",
    textAlign: "center",
    marginTop: "20px",
