{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would interact with a database
const mockColumns = [
  { id: "1", title: "To Do", order: 0 },
  { id: "2", title: "In Progress", order: 1 },
  { id: "3", title: "Done", order: 2 }
];

const getColumnById = (id: string) => {
  return mockColumns.find(column => column.id === id);
};

const createColumn = (title: string, order: number) => {
  const newColumn = {
    id: `${mockColumns.length + 1}`,
    title,
    order
  };
  mockColumns.push(newColumn);
  return newColumn;
};

const updateColumnOrder = (id: string, order: number) => {
  const column = getColumnById(id);
  if (!column) return null;
  column.order = order;
  return column;
};

const deleteColumn = (id: string) => {
  const index = mockColumns.findIndex(column => column.id === id);
  if (index === -1) return false;
  mockColumns.splice(index, 1);
  return true;
};

// GET /columns - Get all columns
router.get("/columns", (req: Request, res: Response) => {
  res.json(mockColumns);
});

// POST /columns - Create a new column
router.post("/columns", (req: Request, res: Response) => {
  const { title, order } = req.body;

  if (!title || typeof order !== "number") {
    return res.status(400).json({ error: "Title and order are required" });
  }

  const newColumn = createColumn(title, order);
  res.status(201).json(newColumn);
});

// PUT /columns/:id - Update column order
router.put("/columns/:id", (req: Request, res: Response) => {
  const { id } = req.params;
  const { order } = req.body;

  if (typeof order !== "number") {
    return res.status(400).json({ error: "Order is required" });
  }

  const updatedColumn = updateColumnOrder(id, order);

  if (!updatedColumn) {
    return res.status(404).json({ error: "Column not found" });
  }

  res.json(updatedColumn);
});

// DELETE /columns/:id - Delete a column
router.delete("/columns/:id", (req: Request, res: Response) => {
  const { id } = req.params;

  const deleted = deleteColumn(id);

  if (!deleted) {
    return res.status(404).json({ error: "Column not found" });
  }

  res.json({ message: "Column deleted successfully" });
});
"}

