{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to the override path
  if (req.method !== "POST" || req.path !== "/override") {
    next();
    return;
  }

  // Check if the request has the required header
  const authHeader = req.headers["authorization"];
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation - in a real system, you'd decode and verify
  // the JWT signature properly. For this simplified example, we'll just
  // check if it matches a known valid token format.
  const expectedToken = createHmac("sha256", secret)
    .update("attendant_token")
    .digest("hex");

  const tokenBuffer = Buffer.from(token);
  const expectedBuffer = Buffer.from(expectedToken);

  try {
    // Use timingSafeEqual to prevent timing attacks
    if (timingSafeEqual(tokenBuffer, expectedBuffer)) {
      next();
    } else {
      res.status(401).json({ error: "Unauthorized" });
    }
  } catch {
    res.status(401).json({ error: "Unauthorized" });
  }
}
"}

