{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check authorization for POST /bookings and PUT /bookings routes
  if (!(req.method === "POST" && req.path === "/bookings") && !(req.method === "PUT" && req.path === "/bookings")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify the JWT signature
  // For this example, we'll just check if it has the right format
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  // In a real implementation, we would verify the HMAC signature here
  // This is a simplified version that just checks if the token exists
  // and has the expected structure
  try {
    // Verify the signature using HMAC-SHA256
    const [header, payload, signature] = parts;
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(signature, "base64url");

    if (!timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // If we get here, the token is valid
    // In a real app, we would decode the payload to check roles
    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Token verification failed" });
  }
}
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user data storage
const users = [
  { id: 1, username: "admin", password: "admin123", role: "admin" },
  { id: 2, username: "staff", password: "staff123", role: "staff" },
  { id: 3, username: "customer", password: "customer123", role: "customer" }
];

// Mock session storage
const sessions = new Map<string, { userId: number; role: string; expiresAt: Date }>();

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate session token
  const token = Math.random().toString(36).substring(2, 15);
  const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000); // 24 hours

  sessions.set(token, {
    userId: user.id,
    role: user.role,
    expiresAt
  });

  return res.status(200).json({
    token,
    user: {
      id: user.id,
      username: user.username,
      role: user.role
    }
  });
});

// Logout endpoint
router.post("/logout", (req: Request, res: Response) => {
  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    return res.status(400).json({ error: "Token is required" });
  }

  if (!sessions.has(token)) {
    return res.status(401).json({ error: "Invalid token" });
  }

  sessions.delete(token);
  return res.status(200).json({ message: "Logged out successfully" });
});

// Middleware to verify session
const authenticateSession = (req: Request, res: Response, next: Function) => {
  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "Authorization token is required" });
  }

  const session = sessions.get(token);

  if (!session) {
    return res.status(401).json({ error: "Invalid or expired token" });
  }

  // Check if session has expired
  if (new Date() > session.expiresAt) {
    sessions.delete(token);
    return res.status(401).json({ error: "Session expired" });
  }

  // Attach user info to request
  (req as any).user = {
    id: session.userId,
    role: session.role
  };

  next();
};

// Get current user info
router.get("/me", authenticateSession, (req: Request, res: Response) => {
  return res.status(200).json({
    id: (req as any).user.id,
    username: users.find(u => u.id === (req as any).user.id)?.username,
    role: (req as any).user.role
  });
});

// Role-based access control middleware
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    const userRole = (req as any).user?.role;

    if (!userRole || userRole !== requiredRole) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }

    next();
  };
};

// Admin-only route example
router.get("/admin", authenticateSession, requireRole("admin"), (req: Request, res: Response) => {
  return res.status(200).json({ message: "Admin access granted" });
});
"}

{"code":"import { useEffect, useState } from "react";

interface Task {
  id: string;
  title: string;
  date: string;
  description: string;
