    e.preventDefault();
    try {
      const response = await fetch("/api/calendar-api/tasks", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newTask)
      });
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
