{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function isValidToken(token: string): boolean {
  if (!JWT_SECRET) return false;

  const parts = token.split(".");
  if (parts.length !== 3) return false;

  const [header, payload, signature] = parts;

  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest();

  try {
    const actualSignature = Buffer.from(signature, "base64");
    return timingSafeEqual(expectedSignature, actualSignature);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only enforce authorization on POST, PUT, DELETE requests to protected routes
  const isProtectedRoute = req.path.startsWith("/clients") && 
                          (req.method === "POST" || 
                           req.method === "PUT" || 
                           req.method === "DELETE");

  if (!isProtectedRoute) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  if (!isValidToken(token)) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  // Token is valid, proceed to next middleware/route handler
  next();
}
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data for demonstration purposes
const bookings = [
  { id: 1, startDate: "2023-06-01", endDate: "2023-06-05", title: "Booking 1" },
  { id: 2, startDate: "2023-06-03", endDate: "2023-06-07", title: "Booking 2" },
  { id: 3, startDate: "2023-06-10", endDate: "2023-06-15", title: "Booking 3" }
];

// Helper function to check if dates overlap
const isDateOverlap = (start1: string, end1: string, start2: string, end2: string): boolean => {
  const date1Start = new Date(start1);
  const date1End = new Date(end1);
  const date2Start = new Date(start2);
  const date2End = new Date(end2);

  return date1Start <= date2End && date2Start <= date1End;
};

// Get all bookings
router.get("/bookings", (req: Request, res: Response) => {
  res.json(bookings);
});

// Get a specific booking by ID
router.get("/bookings/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const booking = bookings.find(b => b.id === id);

  if (!booking) {
    return res.status(404).json({ error: "Booking not found" });
  }

  res.json(booking);
});

// Create a new booking
router.post("/bookings", (req: Request, res: Response) => {
  const { startDate, endDate, title } = req.body;

  // Validate input
  if (!startDate || !endDate || !title) {
    return res.status(400).json({ error: "Start date, end date, and title are required" });
  }

  // Check for conflicts
  const hasConflict = bookings.some(booking => {
    return isDateOverlap(startDate, endDate, booking.startDate, booking.endDate);
  });

  if (hasConflict) {
    return res.status(400).json({ error: "Date conflict detected" });
  }

  // Create new booking
  const newBooking = {
    id: bookings.length + 1,
    startDate,
    endDate,
    title
  };

  bookings.push(newBooking);
  res.status(201).json(newBooking);
});

// Update a booking
router.put("/bookings/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { startDate, endDate, title } = req.body;

  // Validate input
  if (!startDate || !endDate || !title) {
    return res.status(400).json({ error: "Start date, end date, and title are required" });
  }

  const bookingIndex = bookings.findIndex(b => b.id === id);

  if (bookingIndex === -1) {
    return res.status(404).json({ error: "Booking not found" });
  }

  // Check for conflicts
  const hasConflict = bookings.some((booking, index) => {
    if (index === bookingIndex) return false;
    return isDateOverlap(startDate, endDate, booking.startDate, booking.endDate);
  });

  if (hasConflict) {
    return res.status(400).json({ error: "Date conflict detected" });
  }

  // Update booking
  const updatedBooking = {
    id,
    startDate,
    endDate,
    title
  };

  bookings[bookingIndex] = updatedBooking;
  res.json(updatedBooking);
});

// Delete a booking
router.delete("/bookings/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const bookingIndex = bookings.findIndex(b => b.id === id);

  if (bookingIndex === -1) {
    return res.status(404).json({ error: "Booking not found" });
  }

  bookings.splice(bookingIndex, 1);
  res.json({ message: "Booking deleted successfully" });
});
"}

