{"code":"import { Router, type Request, type Response } from "express";
import {
  getAllRecords,
  getRecordById,
  insertRecord,
  updateRecord,
  deleteRecord
} from "../db/commerce-records-table";

export const router = Router();

// GET /commerce-records - List all commerce records
router.get("/commerce-records", (req: Request, res: Response) => {
  try {
    const records = getAllRecords();
    return res.json(records);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch records" });
  }
});

// GET /commerce-records/:id - Get a specific record by ID
router.get("/commerce-records/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const record = getRecordById(id);
    if (!record) {
      return res.status(404).json({ error: "Record not found" });
    }

    return res.json(record);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch record" });
  }
});

// POST /commerce-records - Create a new record
router.post("/commerce-records", (req: Request, res: Response) => {
  try {
    const { type, data } = req.body;

    if (!type || !data) {
      return res.status(400).json({ error: "Type and data are required" });
    }

    const id = insertRecord(type, data);
    const newRecord = getRecordById(id);

    if (!newRecord) {
      return res.status(500).json({ error: "Failed to create record" });
    }

    return res.status(201).json(newRecord);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create record" });
  }
});

// PUT /commerce-records/:id - Update an existing record
router.put("/commerce-records/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const { type, data } = req.body;

    if (!type || !data) {
      return res.status(400).json({ error: "Type and data are required" });
    }

    const updated = updateRecord(id, type, data);

    if (!updated) {
      return res.status(404).json({ error: "Record not found" });
    }

    const updatedRecord = getRecordById(id);

    if (!updatedRecord) {
      return res.status(500).json({ error: "Failed to retrieve updated record" });
    }

    return res.json(updatedRecord);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update record" });
  }
});

// DELETE /commerce-records/:id - Delete a record
router.delete("/commerce-records/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const deleted = deleteRecord(id);

    if (!deleted) {
      return res.status(404).json({ error: "Record not found" });
    }

    return res.json({ message: "Record deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete record" });
  }
});
"}

