{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database - in a real app this would be a proper database
const users = [
  {
    id: 1,
    username: "admin",
    password: "password123",
    role: "administrator"
  },
  {
    id: 2,
    username: "staff1",
    password: "staffpass",
    role: "staff"
  }
];

let currentSessionId = 1;
const sessions = new Map<number, { userId: number; role: string }>();

// User registration
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role } = req.body;

  if (!username || !password || !role) {
    return res.status(400).json({ error: "Username, password, and role are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    username,
    password,
    role
  };

  users.push(newUser);
  return res.status(201).json(newUser);
});

// User login
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Create session
  const sessionId = currentSessionId++;
  sessions.set(sessionId, { userId: user.id, role: user.role });

  return res.json({ sessionId, role: user.role });
});

// Session validation middleware
const validateSession = (req: Request, res: Response, next: Function) => {
  const sessionId = Number(req.headers["x-session-id"]);

  if (!sessionId) {
    return res.status(401).json({ error: "No session ID provided" });
  }

  const session = sessions.get(sessionId);
  if (!session) {
    return res.status(401).json({ error: "Invalid session" });
  }

  (req as any).session = session;
  next();
};

// Role-based access control middleware
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    const session = (req as any).session;
    if (!session || session.role !== requiredRole) {
      return res.status(403).json({ error: "Access denied" });
    }
    next();
  };
};

// Get user profile (requires valid session)
router.get("/profile", validateSession, (req: Request, res: Response) => {
  const session = (req as any).session;
  const user = users.find(u => u.id === session.userId);

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  return res.json({
    id: user.id,
    username: user.username,
    role: user.role
  });
});

// Logout (invalidate session)
router.post("/logout", validateSession, (req: Request, res: Response) => {
  const sessionId = Number(req.headers["x-session-id"]);
  sessions.delete(sessionId);

  return res.json({ message: "Logged out successfully" });
});
"}

{"code":"import { useEffect, useState } from "react";

interface Thesis {
  id: string;
  title: string;
  studentName: string;
  supervisorId: string;
  status: string;
  startDate: string;
  endDate?: string;
}

interface Activity {
  id: string;
  thesisId: string;
  description: string;
  date: string;
  type: string;
}

export function ThesisDetailsPage({ thesisId }: { thesisId: string }) {
  const [thesis, setThesis] = useState<Thesis | null>(null);
  const [activities, setActivities] = useState<Activity[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [editMode, setEditMode] = useState(false);
  const [editedThesis, setEditedThesis] = useState<Partial<Thesis>>({});

  useEffect(() => {
    const fetchThesisAndActivities = async () => {
      try {
        const [thesisResponse, activitiesResponse] = await Promise.all([
          fetch(`/api/thesis-management-api/theses/${thesisId}`),
          fetch(`/api/activity-tracking-api/?thesisId=${thesisId}`)
        ]);

        if (!thesisResponse.ok || !activitiesResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const thesisData = await thesisResponse.json();
        const activitiesData = await activitiesResponse.json();

        setThesis(thesisData);
        setActivities(activitiesData);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchThesisAndActivities();
  }, [thesisId]);

  const handleEdit = () => {
    setEditedThesis({
      title: thesis?.title || "",
      studentName: thesis?.studentName || "",
      status: thesis?.status || ""
    });
    setEditMode(true);
  };

  const handleSave = async () => {
    if (!thesis) return;

    try {
      const response = await fetch(`/api/thesis-management-api/theses/${thesis.id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(editedThesis)
      });

      if (!response.ok) {
        throw new Error("Failed to update thesis");
      }

      const updatedThesis = await response.json();
      setThesis(updatedThesis);
      setEditMode(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setEditedThesis(prev => ({ ...prev, [name]: value }));
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (!thesis) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Thesis not found</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Thesis Details</h1>

      <div style={{ backgroundColor: "#f5f5f5", borderRadius: "8px", padding: "20px", marginBottom: "20px" }}>
        {editMode ? (
          <>
            <div style={{ marginBottom: "10px" }}>
              <label>Title:</label><br />
              <input
                type="text"
                name="title"
                value={editedThesis.title || ""}
                onChange={handleChange}
                style={{ width: "100%", padding: "8px", marginTop: "5px" }}
              />
            </div>
            <div style={{ marginBottom: "10px" }}>
              <label>Student Name:</label><br />
              <input
                type="text"
                name="studentName"
                value={editedThesis.studentName || ""}
                onChange={handleChange}
                style={{ width: "100%", padding: "8px", marginTop: "5px" }}
              />
            </div>
            <div style={{ marginBottom: "10px" }}>
              <label>Status:</label><br />
              <select
                name="status"
                value={editedThesis.status || ""}
                onChange={handleChange}
                style={{ width: "100%", padding: "8px", marginTop: "5px" }}
              >
                <option value="planning">Planning</option>
                <option value="in-progress">In Progress</option>
                <option value="completed">Completed</option>
                <option value="on-hold">On Hold</option>
              </select>
            </div>
            <button onClick={handleSave} style={{ backgroundColor: "#4CAF50", color: "white", border: "none", padding: "10px 15px", borderRadius: "4px", cursor: "pointer" }}>
              Save Changes
            </button>
            <button 
              onClick={() => setEditMode(false)}
              style={{ backgroundColor: "#f44336", color: "white", border: "none", padding: "10px 15px", borderRadius: "4px", cursor: "pointer", marginLeft: "10px" }}
            >
              Cancel
            </button>
          </>
        ) : (
          <>
            <h2>{thesis.title}</h2>
            <p><strong>Student:</strong> {thesis.studentName}</p>
            <p><strong>Status:</strong> {thesis.status}</p>
            <p><strong>Start Date:</strong> {new Date(thesis.startDate).toLocaleDateString()}</p>
            {thesis.endDate && (
              <p><strong>End Date:</strong> {new Date(thesis.endDate).toLocaleDateString()}</p>
            )}
            <button onClick={handleEdit} style={{ backgroundColor: "#2196F3", color: "white", border: "none", padding: "10px 15px", borderRadius: "4px", cursor: "pointer", marginTop: "10px" }}>
              Edit Thesis
