{"code":"import { useState, useRef } from 'react';

interface SharedFile {
  id: string;
  name: string;
  size: number;
  uploadedAt: string;
  url: string;
}

export function FileSharingInterface() {
  const [files, setFiles] = useState<SharedFile[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Mock data for demonstration
  const mockFiles: SharedFile[] = [
    {
      id: '1',
      name: 'project-design.pdf',
      size: 2048000,
      uploadedAt: '2023-05-15T10:30:00Z',
      url: '/files/project-design.pdf'
    },
    {
      id: '2',
      name: 'mockup.png',
      size: 1024000,
      uploadedAt: '2023-05-16T14:45:00Z',
      url: '/files/mockup.png'
    }
  ];

  // Simulate fetching files
  const fetchFiles = () => {
    setIsLoading(true);
    try {
      // In a real app, this would be an API call
      setTimeout(() => {
        setFiles(mockFiles);
        setIsLoading(false);
      }, 500);
    } catch (err) {
      setError('Failed to load files');
      setIsLoading(false);
    }
  };

  // Format file size
  const formatFileSize = (bytes: number): string => {
    if (bytes < 1024) return bytes + ' bytes';
    else if (bytes < 1048576) return (bytes / 1024).toFixed(1) + ' KB';
    else return (bytes / 1048576).toFixed(1) + ' MB';
  };

  // Format date
  const formatDate = (dateString: string): string => {
    const date = new Date(dateString);
    return date.toLocaleDateString();
  };

  // Handle file selection
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setSelectedFile(e.target.files[0]);
    }
  };

  // Handle file upload
  const handleUpload = () => {
    if (!selectedFile) return;

    // In a real app, this would be an API call
    console.log('Uploading file:', selectedFile.name);

    // Reset after upload
    setSelectedFile(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }

    // Refresh file list
    fetchFiles();
  };

  // Initial load
  useState(() => {
    fetchFiles();
  });

  const buttonHoverStyle = {
    backgroundColor: '#e0e0e0'
  };

  const fileCardHoverStyle = {
    boxShadow: '0 4px 8px rgba(0,0,0,0.1)'
  };

  return (
    <div style={{
      fontFamily: 'system-ui, sans-serif',
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px'
    }}>
      <h1 style={{ textAlign: 'center' }}>File Sharing</h1>
      <p style={{ textAlign: 'center', color: '#666' }}>Share and access project files</p>

      {/* Upload Section */}
      <div style={{
        border: '1px dashed #ccc',
        borderRadius: '8px',
        padding: '20px',
        marginBottom: '30px',
        textAlign: 'center'
      }}>
        <h2>Upload New File</h2>
        <input
          type="file"
          ref={fileInputRef}
          onChange={handleFileChange}
          style={{ display: 'none' }}
        />
        <button
          onClick={() => fileInputRef.current?.click()}
          style={{
            backgroundColor: '#007bff',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            padding: '10px 20px',
            cursor: 'pointer',
            transition: 'background-color 0.2s'
          }}
          onMouseEnter={(e) => {
            (e.currentTarget as HTMLElement).style.backgroundColor = buttonHoverStyle.backgroundColor!;
          }}
          onMouseLeave={(e) => {
            (e.currentTarget as HTMLElement).style.backgroundColor = '#007bff';
          }}
        >
          Select File
        </button>

        {selectedFile && (
          <div style={{ marginTop: '10px' }}>
            <p>{selectedFile.name}</p>
            <button
              onClick={handleUpload}
              style={{
                backgroundColor: '#28a745',
                color: 'white',
                border: 'none',
                borderRadius: '4px',
                padding: '10px 20px',
                cursor: 'pointer',
                marginLeft: '10px',
                transition: 'background-color 0.2s'
              }}
              onMouseEnter={(e) => {
                (e.currentTarget as HTMLElement).style.backgroundColor = buttonHoverStyle.backgroundColor!;
              }}
              onMouseLeave={(e) => {
                (e.currentTarget as HTMLElement).style.backgroundColor = '#28a745';
              }}
            >
              Upload File
            </button>
          </div>
        )}
      </div>

      {/* Files List */}
      <h2>Shared Files</h2>

      {isLoading ? (
        <p>Loading files...</p>
      ) : error ? (
        <p>Error: {error}</p>
      ) : files.length === 0 ? (
        <p>No files shared yet.</p>
      ) : (
        <div style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '15px'
        }}>
          {files.map((file) => (
            <div
              key={file.id}
              style={{
                border: '1px solid #ddd',
                borderRadius: '8px',
                padding: '15px',
                transition: 'box-shadow 0.2s',
                backgroundColor: 'white'
              }}
              onMouseEnter={(e) => {
                (e.currentTarget as HTMLElement).style.boxShadow = fileCardHoverStyle.boxShadow!;
              }}
              onMouseLeave={(e) => {
                (e.currentTarget as HTMLElement).style.boxShadow = 'none';
              }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                  <h3 style={{ margin: '0 0 5px 0' }}>{file.name}</h3>
                  <p style={{ margin: '0', fontSize: '0.9em', color: '#666' }}>
                    Size: {formatFileSize(file.size)} | Uploaded: {formatDate(file.uploadedAt)}
                  </p>
                </div>
                <a
                  href={file.url}
                  download={file.name}
                  style={{
                    backgroundColor: '#007bff',
                    color: 'white',
                    textDecoration: 'none',
                    borderRadius: '4px',
                    padding: '8px 12px',
                    cursor: 'pointer',
                    transition: 'background-color 0.2s'
                  }}
                  onMouseEnter={(e) => {
                    (e.currentTarget as HTMLElement).style.backgroundColor = buttonHoverStyle.backgroundColor!;
                  }}
                  onMouseLeave={(e) => {
                    (e.currentTarget as HTMLElement).style.backgroundColor = '#007bff';
                  }}
                >
                  Download
                </a>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

