  const { petId, bookingDateTime, serviceType, groomer, notes } = req.body;

  // Validate required fields
  if (!petId || !bookingDateTime || !serviceType || !groomer) {
    return res.status(400).json({ error: "Missing required fields: petId, bookingDateTime, serviceType, groomer" });
  }

  const newBooking = createBooking({
    petId,
    bookingDateTime,
    serviceType,
    groomer,
    notes: notes || ""
  });

  res.status(201).json(newBooking);
});

// PUT /bookings/:id - Update a booking
router.put("/bookings/:id", (req: Request, res: Response) => {
  const { petId, bookingDateTime, serviceType, groomer, notes } = req.body;

  const existingBooking = findBookingById(req.params.id);
  if (!existingBooking) {
    return res.status(404).json({ error: "Booking not found" });
  }

  const updatedBooking = updateBooking(req.params.id, {
    petId,
    bookingDateTime,
    serviceType,
    groomer,
    notes: notes || ""
  });

  if (!updatedBooking) {
    return res.status(404).json({ error: "Booking not found" });
  }

  res.json(updatedBooking);
});

// DELETE /bookings/:id - Delete a booking
router.delete("/bookings/:id", (req: Request, res: Response) => {
  const deleted = deleteBooking(req.params.id);
  if (!deleted) {
    return res.status(404).json({ error: "Booking not found" });
