  title: string;
  description: string;
  due_date: string;
  status: string;
  plan_id: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    description TEXT,
    due_date TEXT NOT NULL,
    status TEXT NOT NULL,
    plan_id INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllTasks(): Task[] {
  const stmt = db.prepare(`SELECT * FROM tasks`);
  return stmt.all() as unknown as Task[];
}

export function getTaskById(id: number): Task | undefined {
  const stmt = db.prepare(`SELECT * FROM tasks WHERE id = ?`);
  return stmt.get(id) as unknown as Task | undefined;
}

export function insertTask(task: Omit<Task, "id">): number {
  const stmt = db.prepare(
    `INSERT INTO tasks (title, description, due_date, status, plan_id) VALUES (?, ?, ?, ?, ?)`
  );
  const result = stmt.run(
    task.title,
    task.description,
    task.due_date,
    task.status,
    task.plan_id
  );
  return Number(result.lastInsertRowid);
}

export function updateTask(id: number, task: Partial<Omit<Task, "id">>): boolean {
  const fields = [];
  const values = [];

  if (task.title !== undefined) {
    fields.push("title = ?");
    values.push(task.title);
  }
  if (task.description !== undefined) {
    fields.push("description = ?");
    values.push(task.description);
  }
  if (task.due_date !== undefined) {
    fields.push("due_date = ?");
    values.push(task.due_date);
  }
  if (task.status !== undefined) {
    fields.push("status = ?");
    values.push(task.status);
  }
  if (task.plan_id !== undefined) {
    fields.push("plan_id = ?");
    values.push(task.plan_id);
  }

  if (fields.length === 0) return false;

  values.push(id);

  const sql = `UPDATE tasks SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);
  return true;
}

export function deleteTask(id: number): boolean {
  const stmt = db.prepare(`DELETE FROM tasks WHERE id = ?`);
  const result = stmt.run(id);
  return result.changes > 0;
}

