{"code":"import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST, PUT, PATCH requests with a body
  if (!req.body || (req.method !== 'POST' && req.method !== 'PUT' && req.method !== 'PATCH')) {
    next();
    return;
  }

  // Sanitize input fields
  const sanitizeInput = (input: any): any => {
    if (typeof input === 'string') {
      // Remove potentially dangerous HTML tags
      let sanitized = input
        .replace(/<form[^<]*(?:(?!<\/form>)<[^<]*)*<\/form>/gi, '')
        .replace(/<meta[^<]*(?:(?!<\/meta>)<[^<]*)*<\/meta>/gi, '')
        .replace(/<link[^<]*(?:(?!<\/link>)<[^<]*)*<\/link>/gi, '')
        .replace(/<base[^<]*(?:(?!<\/base>)<[^<]*)*<\/base>/gi, '')
        .replace(/<style[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '')
        .replace(/<script[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
        .replace(/on\w+\s*=\s*["'][^"']*?["']/gi, '');

      // Additional sanitization for common XSS patterns
      sanitized = sanitized
        .replace(/<script[^>]*>.*?<\/script>/gi, '')
        .replace(/<iframe[^>]*>.*?<\/iframe>/gi, '')
        .replace(/<object[^>]*>.*?<\/object>/gi, '')
        .replace(/<embed[^>]*>.*?<\/embed>/gi, '')
        .replace(/<applet[^>]*>.*?<\/applet>/gi, '');

      return sanitized;
    } else if (Array.isArray(input)) {
      return input.map(sanitizeInput);
    } else if (typeof input === 'object' && input !== null) {
      const sanitizedObj: any = {};
      for (const key in input) {
        if (Object.prototype.hasOwnProperty.call(input, key)) {
          sanitizedObj[key] = sanitizeInput(input[key]);
        }
      }
      return sanitizedObj;
    }

    return input;
  };

  // Apply sanitization to request body
  req.body = sanitizeInput(req.body);

  next();
}
"}

