export const router = Router();

// Mock database functions - in a real app these would be actual database calls
const mockPets = [
  { id: 1, name: "Buddy", species: "Dog", breed: "Golden Retriever", age: 3 },
  { id: 2, name: "Whiskers", species: "Cat", breed: "Siamese", age: 2 }
];

const findPetById = (id: number) => {
  return mockPets.find(pet => pet.id === id);
};

const createPet = (petData: Omit<typeof mockPets[0], "id">) => {
  const newId = Math.max(...mockPets.map(p => p.id)) + 1;
  const newPet = { ...petData, id: newId };
  mockPets.push(newPet);
  return newPet;
};

const updatePet = (id: number, petData: Partial<Omit<typeof mockPets[0], "id">>) => {
  const index = mockPets.findIndex(pet => pet.id === id);
  if (index === -1) return null;
  mockPets[index] = { ...mockPets[index], ...petData };
  return mockPets[index];
};

const deletePet = (id: number) => {
  const index = mockPets.findIndex(pet => pet.id === id);
  if (index === -1) return false;
  mockPets.splice(index, 1);
  return true;
};

// GET /pets - List all pets
router.get("/pets", (req: Request, res: Response) => {
  res.json(mockPets);
});

// GET /pets/:id - Get a specific pet by ID
