  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid pet ID" });
  }

  const pet = findPetById(id);

  if (!pet) {
    return res.status(404).json({ error: "Pet not found" });
  }

  res.json(pet);
});

