  const { name, species, breed, age } = req.body;

  if (!name || !species || !breed || !age) {
    return res.status(400).json({ error: "Name, species, breed, and age are required" });
  }

  const newPet = createPet({ name, species, breed, age });

  res.status(201).json(newPet);
});

// PUT /pets/:id - Update an existing pet
router.put("/pets/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { name, species, breed, age } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid pet ID" });
  }

  const pet = findPetById(id);

  if (!pet) {
    return res.status(404).json({ error: "Pet not found" });
  }

  const updatedPet = updatePet(id, { name, species, breed, age });

  if (!updatedPet) {
