{"code":"import { useEffect, useState } from "react";

interface CartItem {
  id: number;
  name: string;
  price: number;
  quantity: number;
  imageUrl: string;
}

export function ShoppingCartPage() {
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // Simulate fetching cart items
    const fetchCartItems = async () => {
      try {
        // In a real app, this would be an API call
        // const response = await fetch('/api/cart');
        // const items = await response.json();

        // Mock data for demonstration
        const mockItems: CartItem[] = [
          { id: 1, name: "Cotton T-Shirt", price: 29.99, quantity: 2, imageUrl: "/images/tshirt.jpg" },
          { id: 2, name: "Jeans", price: 59.99, quantity: 1, imageUrl: "/images/jeans.jpg" },
          { id: 3, name: "Sneakers", price: 89.99, quantity: 1, imageUrl: "/images/sneakers.jpg" },
        ];

        setCartItems(mockItems);
        setLoading(false);
      } catch (err) {
        setError("Failed to load cart items");
        setLoading(false);
      }
    };

    fetchCartItems();
  }, []);

  const updateQuantity = (id: number, newQuantity: number) => {
    if (newQuantity <= 0) {
      removeItem(id);
      return;
    }

    setCartItems(items => 
      items.map(item => 
        item.id === id ? { ...item, quantity: newQuantity } : item
      )
    );
  };

  const removeItem = (id: number) => {
    setCartItems(items => items.filter(item => item.id !== id));
  };

  const totalAmount = cartItems.reduce(
    (total, item) => total + (item.price * item.quantity),
    0
  );

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (cartItems.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        Your cart is empty.
      </div>
    );
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Your Shopping Cart</h1>

      <div style={{ marginBottom: "20px" }}>
        {cartItems.map(item => (
          <div 
            key={item.id} 
            style={{ 
              display: "flex", 
              alignItems: "center", 
              marginBottom: "15px", 
              padding: "10px", 
              border: "1px solid #ddd", 
              borderRadius: "8px",
              backgroundColor: "#f9f9f9"
            }}
          >
            <img 
              src={item.imageUrl} 
              alt={item.name} 
              style={{ 
                width: "80px", 
                height: "80px", 
                objectFit: "cover", 
                marginRight: "15px",
                borderRadius: "4px"
              }} 
            />

            <div style={{ flex: 1 }}>
              <h3 style={{ margin: "0 0 5px 0" }}>{item.name}</h3>
              <p style={{ margin: "0 0 5px 0", color: "#666" }}>
                ${item.price.toFixed(2)}
              </p>
              <div style={{ display: "flex", alignItems: "center" }}>
                <span style={{ marginRight: "10px" }}>Qty:</span>
                <input 
                  type="number" 
                  min="1" 
                  value={item.quantity}
                  onChange={(e) => updateQuantity(item.id, parseInt(e.target.value) || 1)}
                  style={{ 
                    width: "60px", 
                    padding: "5px", 
                    marginRight: "10px",
                    border: "1px solid #ccc",
                    borderRadius: "4px"
                  }}
                />
                <button 
                  onClick={() => removeItem(item.id)}
                  style={{ 
                    padding: "5px 10px", 
                    backgroundColor: "#ff4d4d", 
                    color: "white", 
                    border: "none", 
                    borderRadius: "4px",
                    cursor: "pointer"
                  }}
                >
                  Remove
                </button>
              </div>
            </div>

            <div style={{ 
              textAlign: "right", 
              fontWeight: "bold", 
              minWidth: "100px"
            }}>
              ${(item.price * item.quantity).toFixed(2)}
            </div>
          </div>
        ))}
      </div>

      <div style={{ 
        borderTop: "2px solid #eee", 
        paddingTop: "20px", 
        marginTop: "20px"
      }}>
        <div style={{ 
          display: "flex", 
          justifyContent: "space-between", 
          fontSize: "18px", 
          fontWeight: "bold"
        }}>
          <span>Total:</span>
          <span>${totalAmount.toFixed(2)}</span>
        </div>

        <div style={{ 
          marginTop: "20px", 
          textAlign: "center"
        }}>
          <button 
            style={{ 
              padding: "12px 24px", 
              backgroundColor: "#007bff", 
              color: "white", 
              border: "none", 
              borderRadius: "4px", 
              fontSize: "16px", 
              cursor: "pointer",
              width: "100%",
              maxWidth: "200px"
            }}
          >
            Proceed to Checkout
          </button>
        </div>
      </div>
    </div>
  );
}
"}

