{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "./backend/src/db/freelance-contracts.db"
);

interface ContractRow {
  id: number;
  text: string;
  owner_id: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS contracts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    text TEXT NOT NULL,
    owner_id INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllContracts(): ContractRow[] {
  const stmt = db.prepare("SELECT * FROM contracts");
  return stmt.all() as unknown as ContractRow[];
}

export function getContractById(id: number): ContractRow | undefined {
  const stmt = db.prepare("SELECT * FROM contracts WHERE id = ?");
  return stmt.get(id) as unknown as ContractRow | undefined;
}

export function insertContract(text: string, owner_id: number): number {
  const stmt = db.prepare(
    "INSERT INTO contracts (text, owner_id) VALUES (?, ?)"
  );
  const result = stmt.run(text, owner_id);
  return Number(result.lastInsertRowid);
}

export function updateContract(
  id: number,
  text: string,
  owner_id: number
): void {
  const stmt = db.prepare(
    "UPDATE contracts SET text = ?, owner_id = ? WHERE id = ?"
  );
  stmt.run(text, owner_id, id);
}

export function deleteContract(id: number): void {
  const stmt = db.prepare("DELETE FROM contracts WHERE id = ?");
  stmt.run(id);
}

