{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  {
    id: 1,
    username: "admin",
    password: "admin123",
    role: "admin"
  },
  {
    id: 2,
    username: "user",
    password: "user123",
    role: "user"
  }
];

// Mock session storage
const sessions = new Map<string, { userId: number; role: string }>();

// Registration endpoint
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role = "user" } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    username,
    password,
    role
  };

  users.push(newUser);
  return res.status(201).json({ message: "User registered successfully" });
});

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Find user
  const user = users.find(u => u.username === username && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate session token
  const token = Math.random().toString(36).substring(2, 15);
  sessions.set(token, { userId: user.id, role: user.role });

  return res.json({ token, role: user.role });
});

// Logout endpoint
router.post("/logout", (req: Request, res: Response) => {
  const token = req.header("Authorization")?.replace("Bearer ", "");

  if (!token) {
    return res.status(400).json({ error: "No token provided" });
  }

  if (!sessions.has(token)) {
    return res.status(401).json({ error: "Invalid token" });
  }

  sessions.delete(token);
  return res.json({ message: "Logged out successfully" });
});

// Middleware to verify session
const authenticate = (req: Request, res: Response, next: Function) => {
  const token = req.header("Authorization")?.replace("Bearer ", "");

  if (!token) {
    return res.status(401).json({ error: "No token provided" });
  }

  const session = sessions.get(token);
  if (!session) {
    return res.status(401).json({ error: "Invalid token" });
  }

  (req as any).userId = session.userId;
  (req as any).role = session.role;
  next();
};

// Role-based access control middleware
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: Function) => {
    const userRole = (req as any).role;
    if (!roles.includes(userRole)) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }
    next();
  };
};

// Protected route example - get user info
router.get("/me", authenticate, (req: Request, res: Response) => {
  const userId = (req as any).userId;
  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  return res.json({
    id: user.id,
    username: user.username,
    role: user.role
  });
});

// Admin-only route example
router.get("/admin", authenticate, authorize(["admin"]), (req: Request, res: Response) => {
  return res.json({ message: "Admin access granted" });
});
"}

{"code":"import { useEffect, useState } from "react";

interface TimeSlot {
  id: string;
  startTime: string;
  endTime: string;
  isBooked: boolean;
}

export function SlotBookingPage() {
  const [timeSlots, setTimeSlots] = useState<TimeSlot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchTimeSlots();
  }, []);

  const fetchTimeSlots = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/slots');
      if (!response.ok) {
        throw new Error('Failed to fetch time slots');
      }
      const slots = await response.json();
      setTimeSlots(slots);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleBookSlot = async (slotId: string) => {
    try {
      const response = await fetch(`/api/slots/${slotId}/book`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error('Failed to book slot');
      }

      // Refresh the slot list after booking
      await fetchTimeSlots();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: 'system-ui, sans-serif',
    }}>
      <h1 style={{ textAlign: 'center' }}>Available Time Slots</h1>

      {timeSlots.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No available time slots.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {timeSlots.map((slot) => (
            <div 
              key={slot.id} 
              style={{
                border: '1px solid #ccc',
                borderRadius: '8px',
                padding: '15px',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                backgroundColor: slot.isBooked ? '#f0f0f0' : '#fff',
              }}
            >
              <div>
                <strong>{slot.startTime} - {slot.endTime}</strong>
                {!slot.isBooked && (
                  <span style={{ color: 'green', marginLeft: '10px' }}>
                    Available
                  </span>
                )}
              </div>

              {!slot.isBooked && (
                <button 
                  onClick={() => handleBookSlot(slot.id)}
                  style={{
                    backgroundColor: '#007bff',
                    color: 'white',
                    border: 'none',
                    borderRadius: '4px',
                    padding: '8px 16px',
                    cursor: 'pointer',
                  }}
                >
                  Book Slot
                </button>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
