  ],

  findAll(): Promise<any[]> {
    return Promise.resolve(this.patients);
  },

  findById(id: string): Promise<any | null> {
    const patient = this.patients.find(p => p.id === id);
    return Promise.resolve(patient || null);
  },

  create(patientData: any): Promise<any> {
    const newPatient = {
      id: String(this.patients.length + 1),
      ...patientData
    };
    this.patients.push(newPatient);
    return Promise.resolve(newPatient);
  },

  update(id: string, patientData: any): Promise<any | null> {
    const index = this.patients.findIndex(p => p.id === id);
    if (index === -1) return Promise.resolve(null);

    this.patients[index] = { ...this.patients[index], ...patientData };
    return Promise.resolve(this.patients[index]);
  },

  delete(id: string): Promise<boolean> {
    const initialLength = this.patients.length;
    this.patients = this.patients.filter(p => p.id !== id);
    return Promise.resolve(this.patients.length < initialLength);
  }
};

