    password: "hashed_password_2",
    role: "ngo",
    name: "Example NGO"
  }
];

// Mock hash function
const hashPassword = (password: string): string => {
  return `hashed_${password}`;
};

// Mock verify function
const verifyPassword = (password: string, hashed: string): boolean => {
  return `hashed_${password}` === hashed;
};

// Registration endpoint
router.post("/register", (req: Request, res: Response) => {
  const { email, password, role, name } = req.body;

  // Validate input
  if (!email || !password || !role || !name) {
    return res.status(400).json({ message: "Email, password, role, and name are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.email === email);
  if (existingUser) {
    return res.status(400).json({ message: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: `${users.length + 1}`,
    email,
    password: hashPassword(password),
    role,
    name
  };

  users.push(newUser);

  return res.status(201).json({
    id: newUser.id,
    email: newUser.email,
    role: newUser.role,
    name: newUser.name
  });
});

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  // Validate input
  if (!email || !password) {
    return res.status(400).json({ message: "Email and password are required" });
  }

  // Find user
  const user = users.find(u => u.email === email);
  if (!user) {
    return res.status(401).json({ message: "Invalid credentials" });
  }

  // Verify password
  const isValid = verifyPassword(password, user.password);
  if (!isValid) {
    return res.status(401).json({ message: "Invalid credentials" });
  }

  // Return user info
  return res.json({
    id: user.id,
    email: user.email,
    role: user.role,
    name: user.name
  });
});

// Role-based access control middleware
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    // In a real app, this would check JWT token
    // For now, we'll simulate with a mock header
    const userRole = req.headers["x-user-role"] as string;

    if (userRole !== requiredRole) {
      return res.status(403).json({ message: "Access denied" });
    }

    next();
  };
};

