export const db = new DatabaseSync("./shop-pos.db");

interface UserRow {
  id: number;
  username: string;
  password_hash: string;
  role: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllUsers(): UserRow[] {
  const stmt = db.prepare("SELECT * FROM users");
  return stmt.all() as unknown as UserRow[];
}

export function getUserById(id: number): UserRow | undefined {
  const stmt = db.prepare("SELECT * FROM users WHERE id = ?");
  return stmt.get(id) as unknown as UserRow | undefined;
}

export function insertUser(username: string, password_hash: string, role: string): number {
  const stmt = db.prepare("INSERT INTO users (username, password_hash, role) VALUES (?, ?, ?)");
  const result = stmt.run(username, password_hash, role);
  return Number(result.lastInsertRowid);
}

export function updateUser(id: number, username: string, password_hash: string, role: string): number {
  const stmt = db.prepare("UPDATE users SET username = ?, password_hash = ?, role = ? WHERE id = ?");
  const result = stmt.run(username, password_hash, role, id);
  return Number(result.changes);
}

export function deleteUser(id: number): number {
  const stmt = db.prepare("DELETE FROM users WHERE id = ?");
  const result = stmt.run(id);
  return Number(result.changes);
}

