{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockTalks = [
  { id: 1, title: "Introduction to TypeScript", speaker: "John Doe", startTime: "09:00", endTime: "10:00", roomId: "A101" },
  { id: 2, title: "Advanced React Patterns", speaker: "Jane Smith", startTime: "10:30", endTime: "11:30", roomId: "B202" }
];

const findTalkById = (id: number) => {
  return mockTalks.find(talk => talk.id === id);
};

const createTalk = (talk: Omit<Talk, 'id'>) => {
  const newId = Math.max(0, ...mockTalks.map(t => t.id)) + 1;
  const newTalk = { ...talk, id: newId };
  mockTalks.push(newTalk);
  return newTalk;
};

const updateTalk = (id: number, updatedTalk: Partial<Talk>) => {
  const index = mockTalks.findIndex(talk => talk.id === id);
  if (index === -1) return null;
  mockTalks[index] = { ...mockTalks[index], ...updatedTalk };
  return mockTalks[index];
};

const deleteTalk = (id: number) => {
  const index = mockTalks.findIndex(talk => talk.id === id);
  if (index === -1) return false;
  mockTalks.splice(index, 1);
  return true;
};

// Define Talk interface
interface Talk {
  id: number;
  title: string;
  speaker: string;
  startTime: string;
  endTime: string;
  roomId: string;
}

// GET /talks - List all talks
router.get("/talks", (req: Request, res: Response) => {
  res.json(mockTalks);
});

// GET /talks/:id - Get a specific talk by ID
router.get("/talks/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid talk ID" });
  }

  const talk = findTalkById(id);
  if (!talk) {
    return res.status(404).json({ error: "Talk not found" });
  }

  res.json(talk);
});

// POST /talks - Create a new talk
router.post("/talks", (req: Request, res: Response) => {
  const { title, speaker, startTime, endTime, roomId } = req.body;

  if (!title || !speaker || !startTime || !endTime || !roomId) {
    return res.status(400).json({ error: "Missing required fields: title, speaker, startTime, endTime, roomId" });
  }

  const newTalk = createTalk({ title, speaker, startTime, endTime, roomId });
  res.status(201).json(newTalk);
});

// PUT /talks/:id - Update an existing talk
router.put("/talks/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid talk ID" });
  }

  const { title, speaker, startTime, endTime, roomId } = req.body;

  const updatedTalk = updateTalk(id, { title, speaker, startTime, endTime, roomId });

  if (!updatedTalk) {
    return res.status(404).json({ error: "Talk not found" });
  }

  res.json(updatedTalk);
});

// DELETE /talks/:id - Delete a talk
router.delete("/talks/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid talk ID" });
  }

  const deleted = deleteTalk(id);

  if (!deleted) {
    return res.status(404).json({ error: "Talk not found" });
  }

  res.json({ message: "Talk deleted successfully" });
});
"}

