{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const API_KEY = process.env.API_KEY;

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check API key for specific endpoints
  const isRegistrationsEndpoint = req.path.startsWith('/registrations');
  const isMedicalNotesEndpoint = req.path.startsWith('/medical-notes');

  if (!isRegistrationsEndpoint && !isMedicalNotesEndpoint) {
    next();
    return;
  }

  // Check if API key is provided in headers
  const apiKey = req.header('X-API-Key');

  if (!apiKey || !API_KEY) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  // Create HMAC of the provided key
  const expectedKey = createHmac('sha256', API_KEY)
    .update(apiKey)
    .digest();

  // Compare with expected key using timingSafeEqual for security
  const expected = createHmac('sha256', API_KEY)
    .update(API_KEY)
    .digest();

  if (timingSafeEqual(expectedKey, expected)) {
    next();
  } else {
    res.status(401).json({ error: 'Unauthorized' });
  }
}
"}

