// Define role types and their numeric values
const roles = {
  member: 1,
  researcher: 2,
  admin: 3,
} as const;

type Role = keyof typeof roles;

function getRoleFromToken(token: string): Role | null {
  // Simple mock implementation - in reality this would decode and verify a JWT
  // For this example, we'll assume a fixed role for demonstration
  // In practice, you'd extract the role from the token payload

  // This is a placeholder - actual JWT verification would go here
  // Example: const payload = jwt.verify(token, process.env.JWT_SECRET);

  // Mocking a valid role extraction
  if (token === "valid-member-token") return "member";
  if (token === "valid-researcher-token") return "researcher";
  if (token === "valid-admin-token") return "admin";

  return null;
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const protectedPaths = ["/api/papers", "/api/researchers"];
  const isProtectedPath = protectedPaths.some(path => req.path.startsWith(path));

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  // Verify token (mocked for now)
  const userRole = getRoleFromToken(token);

  if (!userRole) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  // Define required role for this endpoint
  let requiredRole: Role = "member"; // Default role requirement

  // Adjust required role based on path and method
  if (req.path.startsWith("/api/researchers") && req.method === "POST") {
    requiredRole = "admin"; // Only admins can create researchers
  } else if (req.path.startsWith("/api/papers") && req.method === "POST") {
    requiredRole = "researcher"; // Researchers can create papers
  } else if (req.path.startsWith("/api/papers") && req.method === "DELETE") {
    requiredRole = "admin"; // Only admins can delete papers
  }

  // Check if user has sufficient role
  if (roles[userRole] < roles[requiredRole]) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  // User has sufficient permissions, proceed
  next();
}
