{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteTimesheet,
  getAllTimesheets,
  getTimesheetById,
  insertTimesheet,
  updateTimesheet
} from "../db/timesheets-table";

export const router = Router();

// Get all timesheets for the logged-in user
router.get("/", (req: Request, res: Response) => {
  const userId = Number(req.query.userId);

  if (isNaN(userId)) {
    return res.status(400).json({ error: "Invalid user ID" });
  }

  const timesheets = getAllTimesheets().filter(ts => ts.user_id === userId);

  res.json(timesheets);
});

// Get a specific timesheet by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid timesheet ID" });
  }

  const timesheet = getTimesheetById(id);

  if (!timesheet) {
    return res.status(404).json({ error: "Timesheet not found" });
  }

  res.json(timesheet);
});

// Create a new timesheet entry
router.post("/", (req: Request, res: Response) => {
  const { userId, date, client, task, hours } = req.body;

  if (!userId || !date || !client || !task || hours === undefined) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const newId = insertTimesheet(userId, date, client, task, hours);

  res.status(201).json({ id: newId });
});

// Update an existing timesheet entry
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { userId, date, client, task, hours } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid timesheet ID" });
  }

  if (!userId || !date || !client || !task || hours === undefined) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const existingTimesheet = getTimesheetById(id);

  if (!existingTimesheet) {
    return res.status(404).json({ error: "Timesheet not found" });
  }

  updateTimesheet(id, userId, date, client, task, hours);

  res.json({ message: "Timesheet updated successfully" });
});

// Delete a timesheet entry
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid timesheet ID" });
  }

  const existingTimesheet = getTimesheetById(id);

  if (!existingTimesheet) {
    return res.status(404).json({ error: "Timesheet not found" });
  }

  // Check if the user is a supervisor (this is a placeholder)
  // In a real implementation, we'd check the user's role here
  const isSupervisor = false; // Placeholder logic

  if (!isSupervisor) {
    return res.status(403).json({ error: "Insufficient permissions to delete timesheet" });
  }

  deleteTimesheet(id);

  res.json({ message: "Timesheet deleted successfully" });
});
"}

{"code":"import { useEffect, useState } from "react";

export function Profile() {
  const [userData, setUserData] = useState<{
    name: string;
    email: string;
    sleepGoal: number;
  } | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    sleepGoal: 0,
  });

  useEffect(() => {
    const fetchProfile = async () => {
      try {
        const response = await fetch("/api/user/profile", {
          method: "GET",
          headers: {
            "Content-Type": "application/json",
          },
        });

        if (!response.ok) {
          throw new Error(`Failed to fetch profile: ${response.status}`);
        }

        const data = await response.json();
        setUserData(data);
        setFormData({
          name: data.name,
          email: data.email,
          sleepGoal: data.sleepGoal,
        });
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchProfile();
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: name === "sleepGoal" ? Number(value) : value,
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/user/profile", {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(formData),
      });

      if (!response.ok) {
        throw new Error(`Failed to update profile: ${response.status}`);
      }

      const updatedData = await response.json();
      setUserData(updatedData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (!userData) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        No profile data available.
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "600px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Profile Settings</h1>
      <form onSubmit={handleSubmit}>
        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="name" style={{ display: "block", marginBottom: "5px" }}>
            Name:
          </label>
          <input
            type="text"
            id="name"
            name="name"
            value={formData.name}
            onChange={handleChange}
            style={{
              width: "100%",
              padding: "8px",
              borderRadius: "4px",
              border: "1px solid #ccc",
            }}
          />
        </div>
        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="email" style={{ display: "block", marginBottom: "5px" }}>
            Email:
          </label>
          <input
            type="email"
            id="email"
            name="email"
            value={formData.email}
            onChange={handleChange}
            style={{
              width: "100%",
              padding: "8px",
              borderRadius: "4px",
              border: "1px solid #ccc",
            }}
          />
        </div>
        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="sleepGoal" style={{ display: "block", marginBottom: "5px" }}>
            Sleep Goal (hours):
          </label>
          <input
            type="number"
            id="sleepGoal"
            name="sleepGoal"
