  const stmt = db.prepare(
    "INSERT INTO checkouts (memberId, bookIds, checkoutDate) VALUES (?, ?, ?)"
  );
  const result = stmt.run(memberId, bookIds, checkoutDate);
  return Number(result.lastInsertRowid);
}

