  title: string;
  instructor: string;
  date: string;
  time: string;
  duration: number;
  capacity: number;
  bookedSpots: number;
}

export function BookingForm() {
  const [classes, setClasses] = useState<Class[]>([]);
  const [selectedClassId, setSelectedClassId] = useState<number | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchClasses();
  }, []);

  const fetchClasses = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/classes');
      if (!response.ok) {
        throw new Error('Failed to fetch classes');
      }
      const data = await response.json();
      setClasses(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleBookClass = async (classId: number) => {
    try {
      const response = await fetch(`/api/classes/${classId}/book`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ classId }),
      });

      if (!response.ok) {
        throw new Error('Failed to book class');
      }

      // Refresh the class list after booking
      await fetchClasses();
      setSelectedClassId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const availableClasses = classes.filter(cls => 
    cls.bookedSpots < cls.capacity
  );

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (availableClasses.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No available classes to book.</div>;
  }

  return (
    <div style={{
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <h1 style={{ textAlign: 'center' }}>Book a Yoga Class</h1>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        {availableClasses.map(cls => (
          <div 
            key={cls.id} 
            style={{
              border: '1px solid #ccc',
              borderRadius: '8px',
              padding: '15px',
              backgroundColor: '#f9f9f9'
            }}
          >
            <div style={{ marginBottom: '10px' }}>
              <strong>{cls.title}</strong> with {cls.instructor}
            </div>
            <div style={{ marginBottom: '10px' }}>
              {new Date(cls.date).toLocaleDateString()} at {cls.time} ({cls.duration} min)
            </div>
            <div style={{ marginBottom: '10px' }}>
              Spots available: {cls.capacity - cls.bookedSpots}/{cls.capacity}
            </div>
            <button 
              onClick={() => handleBookClass(cls.id)}
              disabled={selectedClassId === cls.id}
              style={{
                backgroundColor: '#4CAF50',
                color: 'white',
                border: 'none',
                borderRadius: '4px',
                padding: '8px 16px',
                cursor: 'pointer',
                fontSize: '14px'
              }}
            >
              Book Class
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}
