{"code":"import { useEffect, useState } from "react";

interface Product {
  id: number;
  name: string;
  price: number;
}

interface InvoiceItem {
  productId: number;
  quantity: number;
}

interface Invoice {
  id: number;
  customerId: number;
  items: InvoiceItem[];
  total: number;
  status: "pending" | "paid";
}

export function BillingSystem() {
  const [products, setProducts] = useState<Product[]>([]);
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState<number>(1);
  const [invoiceItems, setInvoiceItems] = useState<InvoiceItem[]>([
    { productId: 1, quantity: 1 },
  ]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // Simulate fetching products
    const fetchProducts = async () => {
      try {
        // In a real app, this would be an API call
        const mockProducts: Product[] = [
          { id: 1, name: "Pencil", price: 0.5 },
          { id: 2, name: "Notebook", price: 2.0 },
          { id: 3, name: "Eraser", price: 0.3 },
        ];
        setProducts(mockProducts);
        setLoading(false);
      } catch (err) {
        setError("Failed to load products");
        setLoading(false);
      }
    };

    // Simulate fetching invoices
    const fetchInvoices = async () => {
      try {
        // In a real app, this would be an API call
        const mockInvoices: Invoice[] = [
          { id: 1, customerId: 1, items: [{ productId: 1, quantity: 2 }], total: 1.0, status: "paid" },
          { id: 2, customerId: 1, items: [{ productId: 2, quantity: 1 }], total: 2.0, status: "pending" },
        ];
        setInvoices(mockInvoices);
        setLoading(false);
      } catch (err) {
        setError("Failed to load invoices");
        setLoading(false);
      }
    };

    fetchProducts();
    fetchInvoices();
  }, []);

  const handleAddItem = () => {
    setInvoiceItems([...invoiceItems, { productId: 1, quantity: 1 }]);
  };

  const handleRemoveItem = (index: number) => {
    const newItems = [...invoiceItems];
    newItems.splice(index, 1);
    setInvoiceItems(newItems);
  };

  const handleQuantityChange = (index: number, value: string) => {
    const newItems = [...invoiceItems];
    newItems[index].quantity = Number(value);
    setInvoiceItems(newItems);
  };

  const handleProductChange = (index: number, value: string) => {
    const newItems = [...invoiceItems];
    newItems[index].productId = Number(value);
    setInvoiceItems(newItems);
  };

  const calculateTotal = (): number => {
    return invoiceItems.reduce((total, item) => {
      const product = products.find(p => p.id === item.productId);
      return total + (product ? product.price * item.quantity : 0);
    }, 0);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      // In a real app, this would be an API call
      const newInvoice: Invoice = {
        id: invoices.length + 1,
        customerId: selectedCustomerId,
        items: invoiceItems,
        total: calculateTotal(),
        status: "pending",
      };

      // Simulate successful creation
      setInvoices([...invoices, newInvoice]);

      // Reset form
      setInvoiceItems([{ productId: 1, quantity: 1 }]);
    } catch (err) {
      setError("Failed to create invoice");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Billing System</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <div style={{ marginBottom: "15px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Customer ID:</label>
          <input
            type="number"
            value={selectedCustomerId}
            onChange={(e) => setSelectedCustomerId(Number(e.target.value))}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
        </div>

        <h2>Invoice Items</h2>
        {invoiceItems.map((item, index) => (
          <div key={index} style={{ display: "flex", gap: "10px", marginBottom: "10px", alignItems: "flex-end" }}>
            <div style={{ flex: 1 }}>
              <label style={{ display: "block", marginBottom: "5px" }}>Product:</label>
              <select
                value={item.productId}
                onChange={(e) => handleProductChange(index, e.target.value)}
                style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
              >
                {products.map(product => (
                  <option key={product.id} value={product.id}>{product.name}</option>
                ))}
              </select>
            </div>

            <div style={{ flex: 1 }}>
              <label style={{ display: "block", marginBottom: "5px" }}>Quantity:</label>
              <input
                type="number"
                min="1"
                value={item.quantity}
                onChange={(e) => handleQuantityChange(index, e.target.value)}
                style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
              />
            </div>

            <button
              type="button"
              onClick={() => handleRemoveItem(index)}
              style={{ padding: "8px 12px", backgroundColor: "#ff4d4d", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
            >
              Remove
            </button>
          </div>
        ))}

        <button
          type="button"
          onClick={handleAddItem}
          style={{ padding: "8px 12px", backgroundColor: "#1890ff", color: "white", border: "none", borderRadius: "4px", cursor: "pointer", marginBottom: "15px" }}
        >
          Add Item
        </button>

        <div style={{ marginBottom: "15px", fontWeight: "bold" }}>
          Total: ${calculateTotal().toFixed(2)}
        </div>

        <button
          type="submit"
          style={{ padding: "10px 20px", backgroundColor: "#52c41a", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
        >
          Process Payment
        </button>
      </form>

      <h2>Recent Invoices</h2>
      {invoices.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No invoices found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {invoices.map(invoice => (
            <div key={invoice.id} style={{ padding: "15px", border: "1px solid #ccc", borderRadius: "8px" }}>
              <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "5px" }}>
                <span>Invoice #{invoice.id}</span>
                <span style={{ fontWeight: "bold" }}>${invoice.total.toFixed(2)}</span>
              </div>
              <div style={{ marginBottom: "5px" }}>
                Status: <span style={{ color: invoice.status === "paid" ? "green" : "orange" }}>{invoice.status}</span>
              </div>
              <div>
                Items: {invoice.items.map(item => {
                  const product = products.find(p => p.id === item.productId);
                  return product ? `${product.name} x${item.quantity}` : "";
                }).join(", ")}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

