{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data structures to simulate database operations
const invoices = [] as { id: number; items: string[]; total: number; status: string }[];
const payments = [] as { id: number; invoiceId: number; amount: number; method: string; timestamp: Date }[];
const transactions = [] as { id: number; invoiceId: number; amount: number; status: string; timestamp: Date }[];

// Helper function to generate next ID
const getNextId = (array: any[]) => array.length > 0 ? Math.max(...array.map(item => item.id)) + 1 : 1;

// Create Invoice
router.post('/invoices', (req: Request, res: Response) => {
  const { items, total } = req.body;

  if (!items || !Array.isArray(items) || !total || typeof total !== 'number') {
    return res.status(400).json({ error: 'Invalid invoice data' });
  }

  const newInvoice = {
    id: getNextId(invoices),
    items,
    total,
    status: 'pending'
  };

  invoices.push(newInvoice);
  return res.status(201).json(newInvoice);
});

// Get Invoice by ID
router.get('/invoices/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const invoice = invoices.find(i => i.id === id);

  if (!invoice) {
    return res.status(404).json({ error: 'Invoice not found' });
  }

  return res.json(invoice);
});

// Update Invoice Status
router.put('/invoices/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { status } = req.body;

  if (!status) {
    return res.status(400).json({ error: 'Status is required' });
  }

  const invoiceIndex = invoices.findIndex(i => i.id === id);

  if (invoiceIndex === -1) {
    return res.status(404).json({ error: 'Invoice not found' });
  }

  invoices[invoiceIndex].status = status;
  return res.json(invoices[invoiceIndex]);
});

// Delete Invoice
router.delete('/invoices/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const invoiceIndex = invoices.findIndex(i => i.id === id);

  if (invoiceIndex === -1) {
    return res.status(404).json({ error: 'Invoice not found' });
  }

  invoices.splice(invoiceIndex, 1);
  return res.json({ message: 'Invoice deleted successfully' });
});

// Process Payment
router.post('/payments', (req: Request, res: Response) => {
  const { invoiceId, amount, method } = req.body;

  if (!invoiceId || !amount || !method) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  const invoice = invoices.find(i => i.id === invoiceId);

  if (!invoice) {
    return res.status(404).json({ error: 'Invoice not found' });
  }

  const newPayment = {
    id: getNextId(payments),
    invoiceId,
    amount,
    method,
    timestamp: new Date()
  };

  payments.push(newPayment);

  // Log transaction
  const newTransaction = {
    id: getNextId(transactions),
    invoiceId,
    amount,
    status: 'completed',
    timestamp: new Date()
  };

  transactions.push(newTransaction);

  // Update invoice status
  invoice.status = 'paid';

  return res.status(201).json(newPayment);
});

// Get All Transactions
router.get('/transactions', (req: Request, res: Response) => {
  return res.json(transactions);
});
"}

