{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data for demonstration purposes
const slots = [
  { id: "1", startTime: "09:00", endTime: "10:00", available: true },
  { id: "2", startTime: "10:00", endTime: "11:00", available: true },
  { id: "3", startTime: "11:00", endTime: "12:00", available: false }
];

// Get all slots
router.get("/", (req: Request, res: Response) => {
  res.json(slots);
});

// Get a specific slot by ID
router.get("/:id", (req: Request, res: Response) => {
  const slotId = req.params.id;
  const slot = slots.find(s => s.id === slotId);

  if (!slot) {
    return res.status(404).json({ message: "Slot not found" });
  }

  res.json(slot);
});

// Create a new slot
router.post("/", (req: Request, res: Response) => {
  const { startTime, endTime } = req.body;

  if (!startTime || !endTime) {
    return res.status(400).json({ message: "Start time and end time are required" });
  }

  const newSlot = {
    id: String(slots.length + 1),
    startTime,
    endTime,
    available: true
  };

  slots.push(newSlot);
  res.status(201).json(newSlot);
});

// Update a slot
router.put("/:id", (req: Request, res: Response) => {
  const slotId = req.params.id;
  const { startTime, endTime, available } = req.body;

  const slotIndex = slots.findIndex(s => s.id === slotId);

  if (slotIndex === -1) {
    return res.status(404).json({ message: "Slot not found" });
  }

  if (startTime) slots[slotIndex].startTime = startTime;
  if (endTime) slots[slotIndex].endTime = endTime;
  if (available !== undefined) slots[slotIndex].available = available;

  res.json(slots[slotIndex]);
});

// Delete a slot
router.delete("/:id", (req: Request, res: Response) => {
  const slotId = req.params.id;
  const slotIndex = slots.findIndex(s => s.id === slotId);

  if (slotIndex === -1) {
    return res.status(404).json({ message: "Slot not found" });
  }

  slots.splice(slotIndex, 1);
  res.json({ message: "Slot deleted successfully" });
