{"code":"import { useEffect, useState } from "react";

interface RepairRecord {
  id: number;
  bikeId: string;
  description: string;
  status: string;
  date: string;
}

export function MechanicRepairEntryForm() {
  const [repairs, setRepairs] = useState<RepairRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    bikeId: "",
    description: "",
    status: "pending"
  });

  useEffect(() => {
    fetchRepairs();
  }, []);

  const fetchRepairs = async () => {
    try {
      const response = await fetch("/api/repairs-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch repairs: ${response.status}`);
      }
      const data = await response.json();
      setRepairs(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
      setLoading(false);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/repairs-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData)
      });
      if (!response.ok) {
        throw new Error(`Failed to create repair: ${response.status}`);
      }
      await fetchRepairs();
      setFormData({ bikeId: "", description: "", status: "pending" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Bike Repair Entry Form</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="bikeId" style={{ display: "block", marginBottom: "5px" }}>Bike ID:</label>
          <input
            type="text"
            id="bikeId"
            name="bikeId"
            value={formData.bikeId}
            onChange={handleChange}
            required
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="description" style={{ display: "block", marginBottom: "5px" }}>Description:</label>
          <textarea
            id="description"
            name="description"
            value={formData.description}
            onChange={handleChange}
            required
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc", minHeight: "60px" }}
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="status" style={{ display: "block", marginBottom: "5px" }}>Status:</label>
          <select
            id="status"
            name="status"
            value={formData.status}
            onChange={handleChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          >
            <option value="pending">Pending</option>
            <option value="in-progress">In Progress</option>
            <option value="completed">Completed</option>
          </select>
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: "#007bff", 
            color: "white", 
            border: "none", 
            padding: "10px 20px", 
            borderRadius: "4px", 
            cursor: "pointer" 
          }}
        >
          Add Repair Record
        </button>
      </form>

      <h2 style={{ textAlign: "center" }}>Current Repairs</h2>
      {repairs.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>No repair records found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {repairs.map(repair => (
            <div 
              key={repair.id} 
              style={{ 
                border: "1px solid #ccc", 
                borderRadius: "8px", 
                padding: "15px", 
                display: "flex", 
                justifyContent: "space-between", 
                alignItems: "center" 
              }}
            >
              <div>
                <strong>Bike ID:</strong> {repair.bikeId}<br />
                <strong>Description:</strong> {repair.description}<br />
                <strong>Status:</strong> {repair.status}<br />
                <strong>Date:</strong> {repair.date}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

