{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data for demonstration purposes
const mockReports = [
  { id: 1, title: "Monthly Spending Report", period: "2023-01", totalSpent: 1250.75, categoryBreakdown: { food: 300.50, transport: 200.00, entertainment: 150.00 } },
  { id: 2, title: "Quarterly Budget Analysis", period: "2023-Q1", totalSpent: 3500.00, categoryBreakdown: { food: 800.00, transport: 500.00, entertainment: 400.00 } }
];

// GET /reports - Get all reports
