export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockDatabase = {
  findClassById: (id: string) => {
    // Simulate finding a class by ID
    return id === "1" ? { id: "1", name: "Yoga Flow", capacity: 10, booked: 3 } : null;
  },

  bookClass: (classId: string, userId: string) => {
    // Simulate booking a class
    return { classId, userId, status: "booked" };
  },

  cancelBooking: (classId: string, userId: string) => {
    // Simulate cancelling a booking
    return { classId, userId, status: "cancelled" };
  },

  updateClassAvailability: (classId: string, newCapacity: number) => {
    // Simulate updating class capacity
    return { classId, newCapacity };
  }
};

// Get class availability
router.get("/classes/:id/availability", (req: Request, res: Response) => {
  const classId = req.params.id;

  if (!classId) {
    return res.status(400).json({ error: "Class ID is required" });
  }

  const classData = mockDatabase.findClassById(classId);

  if (!classData) {
    return res.status(404).json({ error: "Class not found" });
  }

  return res.json({
    classId,
    name: classData.name,
    capacity: classData.capacity,
    availableSpots: classData.capacity - classData.booked
  });
});

// Book a class
router.post("/classes/:id/book", (req: Request, res: Response) => {
  const classId = req.params.id;
  const { userId } = req.body;

  if (!classId || !userId) {
    return res.status(400).json({ error: "Class ID and User ID are required" });
  }

  const classData = mockDatabase.findClassById(classId);

  if (!classData) {
    return res.status(404).json({ error: "Class not found" });
  }

  if (classData.booked >= classData.capacity) {
    return res.status(400).json({ error: "No available spots" });
  }

  const booking = mockDatabase.bookClass(classId, userId);

  return res.status(201).json(booking);
});

// Cancel a booking
router.delete("/classes/:id/bookings/:userId", (req: Request, res: Response) => {
  const classId = req.params.id;
  const userId = req.params.userId;

  if (!classId || !userId) {
    return res.status(400).json({ error: "Class ID and User ID are required" });
  }

  const classData = mockDatabase.findClassById(classId);

  if (!classData) {
    return res.status(404).json({ error: "Class not found" });
  }

  const cancellation = mockDatabase.cancelBooking(classId, userId);

  return res.json(cancellation);
});

// Update class availability
router.put("/classes/:id/availability", (req: Request, res: Response) => {
  const classId = req.params.id;
  const { capacity } = req.body;

  if (!classId || capacity === undefined) {
    return res.status(400).json({ error: "Class ID and Capacity are required" });
  }

  const classData = mockDatabase.findClassById(classId);

  if (!classData) {
    return res.status(404).json({ error: "Class not found" });
  }

  const updatedClass = mockDatabase.updateClassAvailability(classId, capacity);

  return res.json(updatedClass);
});
