{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data to simulate database operations
let orders = [
  { id: 1, customerName: "John Doe", items: ["Pizza", "Salad"], status: "preparing", total: 25.5 },
  { id: 2, customerName: "Jane Smith", items: ["Burger", "Fries"], status: "ready", total: 18.75 },
];

let nextId = 3;

// GET /orders - List all orders
router.get("/orders", (req: Request, res: Response) => {
  res.json(orders);
});

// GET /orders/:id - Get one order by ID
router.get("/orders/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const order = orders.find(o => o.id === id);

  if (!order) {
    return res.status(404).json({ error: "Order not found" });
  }

  res.json(order);
});

// POST /orders - Create a new order
router.post("/orders", (req: Request, res: Response) => {
  const { customerName, items, total } = req.body;

  if (!customerName || !items || !total) {
    return res.status(400).json({ error: "Missing required fields: customerName, items, total" });
  }

  const newOrder = {
    id: nextId++,
    customerName,
    items,
    status: "preparing",
    total,
  };

  orders.push(newOrder);
  res.status(201).json(newOrder);
});

// PUT /orders/:id - Update an existing order
router.put("/orders/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const orderIndex = orders.findIndex(o => o.id === id);

  if (orderIndex === -1) {
    return res.status(404).json({ error: "Order not found" });
  }

  const { customerName, items, status, total } = req.body;

  if (!customerName || !items || !status || !total) {
    return res.status(400).json({ error: "Missing required fields: customerName, items, status, total" });
  }

  orders[orderIndex] = {
    id,
    customerName,
    items,
    status,
    total,
  };

  res.json(orders[orderIndex]);
});

// DELETE /orders/:id - Delete an order
router.delete("/orders/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const orderIndex = orders.findIndex(o => o.id === id);

  if (orderIndex === -1) {
    return res.status(404).json({ error: "Order not found" });
  }

  orders.splice(orderIndex, 1);
  res.json({ message: "Order deleted successfully" });
});

// GET /orders/search?customerName=... - Search orders by customer name
router.get("/orders/search", (req: Request, res: Response) => {
  const { customerName } = req.query;

  if (!customerName) {
    return res.status(400).json({ error: "Query parameter 'customerName' is required" });
  }

  const filteredOrders = orders.filter(order => 
    order.customerName.toLowerCase().includes(customerName.toString().toLowerCase())
  );

  res.json(filteredOrders);
});

// PUT /orders/:id/status - Update order status
router.put("/orders/:id/status", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const orderIndex = orders.findIndex(o => o.id === id);

  if (orderIndex === -1) {
    return res.status(404).json({ error: "Order not found" });
  }

  const { status } = req.body;

  if (!status) {
    return res.status(400).json({ error: "Status is required" });
  }

  orders[orderIndex].status = status;
  res.json(orders[orderIndex]);
});
