{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockOrders = [
  {
    id: 1,
    customerId: 1,
    orderDate: "2023-05-15",
    status: "completed",
    items: [
      { plantId: 1, quantity: 2 },
      { plantId: 2, quantity: 1 }
    ]
  },
  {
    id: 2,
    customerId: 2,
    orderDate: "2023-06-20",
    status: "pending",
    items: [
      { plantId: 3, quantity: 3 }
    ]
  }
];

const findOrderById = (id: number) => {
  return mockOrders.find(order => order.id === id);
};

const createOrder = (orderData: any) => {
  const newOrder = {
    id: mockOrders.length + 1,
    ...orderData
  };
  mockOrders.push(newOrder);
  return newOrder;
};

const updateOrder = (id: number, updatedData: any) => {
  const index = mockOrders.findIndex(order => order.id === id);
  if (index !== -1) {
    mockOrders[index] = { ...mockOrders[index], ...updatedData };
    return mockOrders[index];
  }
  return null;
};

const deleteOrder = (id: number) => {
  const index = mockOrders.findIndex(order => order.id === id);
  if (index !== -1) {
    mockOrders.splice(index, 1);
    return true;
  }
  return false;
};

// GET /orders - List all orders
router.get("/", (req: Request, res: Response) => {
  res.json(mockOrders);
});

// GET /orders/:id - Get a specific order by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const order = findOrderById(id);

  if (!order) {
    return res.status(404).json({ error: "Order not found" });
  }

  res.json(order);
});

// POST /orders - Create a new order
router.post("/", (req: Request, res: Response) => {
  const { customerId, orderDate, status, items } = req.body;

  // Validate required fields
  if (!customerId || !orderDate || !status || !items) {
    return res.status(400).json({ error: "Missing required fields: customerId, orderDate, status, items" });
  }

  // Validate items array
  if (!Array.isArray(items)) {
    return res.status(400).json({ error: "Items must be an array" });
  }

  // Validate each item
  for (const item of items) {
    if (!item.plantId || !item.quantity) {
      return res.status(400).json({ error: "Each item must have plantId and quantity" });
    }
  }

  const newOrder = createOrder({ customerId, orderDate, status, items });
  res.status(201).json(newOrder);
});

// PUT /orders/:id - Update an existing order
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { customerId, orderDate, status, items } = req.body;

  // Validate required fields
  if (!customerId || !orderDate || !status || !items) {
    return res.status(400).json({ error: "Missing required fields: customerId, orderDate, status, items" });
  }

  // Validate items array
  if (!Array.isArray(items)) {
    return res.status(400).json({ error: "Items must be an array" });
  }

  // Validate each item
  for (const item of items) {
    if (!item.plantId || !item.quantity) {
      return res.status(400).json({ error: "Each item must have plantId and quantity" });
    }
  }

  const updatedOrder = updateOrder(id, { customerId, orderDate, status, items });

  if (!updatedOrder) {
    return res.status(404).json({ error: "Order not found" });
  }

  res.json(updatedOrder);
});

// DELETE /orders/:id - Delete an order
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const deleted = deleteOrder(id);

  if (!deleted) {
    return res.status(404).json({ error: "Order not found" });
  }

  res.json({ message: "Order deleted successfully" });
});
"}

