{"code":"import { useEffect, useState } from "react";

interface Room {
  id: string;
  name: string;
  capacity: number;
  amenities: string[];
}

interface Booking {
  id: string;
  roomId: string;
  memberId: string;
  startTime: string;
  endTime: string;
}

export function RoomBookingView() {
  const [rooms, setRooms] = useState<Room[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedRoomId, setSelectedRoomId] = useState<string | null>(null);
  const [startTime, setStartTime] = useState("");
  const [endTime, setEndTime] = useState("");

  useEffect(() => {
    async function fetchRoomsAndBookings() {
      try {
        setLoading(true);
        const [roomsResponse, bookingsResponse] = await Promise.all([
          fetch("/api/room-availability-service/rooms"),
          fetch("/api/bookings-api/"),
        ]);

        if (!roomsResponse.ok || !bookingsResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const roomsData = await roomsResponse.json();
        const bookingsData = await bookingsResponse.json();

        setRooms(roomsData);
        setBookings(bookingsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchRoomsAndBookings();
  }, []);

  const handleBookRoom = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedRoomId || !startTime || !endTime) return;

    try {
      const response = await fetch("/api/bookings-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          roomId: selectedRoomId,
          memberId: "member-123", // In a real app, this would come from auth context
          startTime,
          endTime,
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to book room");
      }

      // Refresh data after booking
      const [roomsResponse, bookingsResponse] = await Promise.all([
        fetch("/api/room-availability-service/rooms"),
        fetch("/api/bookings-api/"),
      ]);

      if (roomsResponse.ok && bookingsResponse.ok) {
        const roomsData = await roomsResponse.json();
        const bookingsData = await bookingsResponse.json();
        setRooms(roomsData);
        setBookings(bookingsData);
        setSelectedRoomId(null);
        setStartTime("");
        setEndTime("");
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Room Booking</h1>

      <div style={{ marginBottom: "30px" }}>
        <h2>Available Rooms</h2>
        {rooms.length === 0 ? (
          <p>No rooms available.</p>
        ) : (
          <div
            style={{
              display: "flex",
              flexWrap: "wrap",
              gap: "15px",
            }}
          >
            {rooms.map((room) => (
              <div
                key={room.id}
                style={{
                  border: "1px solid #ccc",
                  borderRadius: "8px",
                  padding: "15px",
                  width: "200px",
                  boxSizing: "border-box",
                }}
              >
                <h3>{room.name}</h3>
                <p>Capacity: {room.capacity}</p>
                <p>Amenities: {room.amenities.join(", ")}</p>
              </div>
            ))}
          </div>
        )}
      </div>

      <div style={{ marginBottom: "30px" }}>
        <h2>Book a Room</h2>
        <form onSubmit={handleBookRoom}>
          <div style={{ marginBottom: "10px" }}>
            <label htmlFor="roomId">Select Room:</label>
            <select
              id="roomId"
              value={selectedRoomId || ""}
              onChange={(e) => setSelectedRoomId(e.target.value)}
              style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            >
              <option value="">Choose a room</option>
              {rooms.map((room) => (
                <option key={room.id} value={room.id}>
                  {room.name}
                </option>
              ))}
            </select>
          </div>

          <div style={{ marginBottom: "10px" }}>
            <label htmlFor="startTime">Start Time:</label>
            <input
              type="datetime-local"
              id="startTime"
              value={startTime}
              onChange={(e) => setStartTime(e.target.value)}
              style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            />
          </div>

          <div style={{ marginBottom: "10px" }}>
            <label htmlFor="endTime">End Time:</label>
            <input
              type="datetime-local"
              id="endTime"
              value={endTime}
              onChange={(e) => setEndTime(e.target.value)}
              style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            />
          </div>

          <button
            type="submit"
            style={{
              backgroundColor: "#007bff",
              color: "white",
              border: "none",
              borderRadius: "4px",
              padding: "10px 15px",
              cursor: "pointer",
            }}
          >
            Book Room
          </button>
        </form>
      </div>

      <div>
        <h2>Your Bookings</h2>
        {bookings.length === 0 ? (
          <p>You have no upcoming bookings.</p>
        ) : (
          <table
            style={{
              width: "100%",
              borderCollapse: "collapse",
              marginBottom: "20px",
            }}
          >
            <thead>
              <tr>
                <th style={{ border: "1px solid #ddd", padding: "8px" }}>Room</th>
                <th style={{ border: "1px solid #ddd", padding: "8px" }}>Start</th>
                <th style={{ border: "1px solid #ddd", padding: "8px" }}>End</th>
                <th style={{ border: "1px solid #ddd", padding: "8px" }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {bookings.map((booking) => {
                const room = rooms.find((r) => r.id === booking.roomId);
                return (
                  <tr key={booking.id}>
                    <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                      {room?.name || "Unknown Room"}
                    </td>
                    <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                      {new Date(booking.startTime).toLocaleString()}
                    </td>
                    <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                      {new Date(booking.endTime).toLocaleString()}
                    </td>
                    <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                      <button
                        onClick={async () => {
                          const response = await fetch(
                            `/api/bookings-api/${booking.id}`,
                            { method: "DELETE" }
                          );
                          if (response.ok) {
                            // Refresh data after deletion
                            const [roomsResponse, bookingsResponse] =
                              await Promise.all([
                                fetch("/api/room-availability-service/rooms"),
                                fetch("/api/bookings-api/"),
                              ]);
                            if (roomsResponse.ok && bookingsResponse.ok) {
                              const roomsData = await roomsResponse.json();
                              const bookingsData = await bookingsResponse.json();
                              setRooms(roomsData);
                              setBookings(bookingsData);
                            }
                          }
                        }}
                        style={{
                          backgroundColor: "#dc3545",
                          color: "white",
                          border: "none",
                          borderRadius: "4px",
                          padding: "5px 10px",
                          cursor: "pointer",
                        }}
                      >
                        Cancel
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}
"}

