{"code":"import { useEffect, useState } from "react";

interface Subscription {
  id: number;
  name: string;
  category: string;
  amount: number;
  billingCycle: string;
  nextBillingDate: string;
}

export function SubscriptionsPage() {
  const [subscriptions, setSubscriptions] = useState<Subscription[]>([]);
  const [filteredSubscriptions, setFilteredSubscriptions] = useState<Subscription[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [categoryFilter, setCategoryFilter] = useState("all");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchSubscriptions();
  }, []);

  const fetchSubscriptions = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/subscriptions");
      if (!response.ok) {
        throw new Error(`Failed to fetch subscriptions: ${response.status}`);
      }
      const data = await response.json();
      setSubscriptions(data);
      setFilteredSubscriptions(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    let result = subscriptions;

    if (searchTerm) {
      const term = searchTerm.toLowerCase();
      result = result.filter(sub => 
        sub.name.toLowerCase().includes(term) ||
        sub.category.toLowerCase().includes(term)
      );
    }

    if (categoryFilter !== "all") {
      result = result.filter(sub => sub.category === categoryFilter);
    }

    setFilteredSubscriptions(result);
  }, [searchTerm, categoryFilter, subscriptions]);

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/subscriptions/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`Failed to delete subscription: ${response.status}`);
      }
      // Refresh the list after deletion
      fetchSubscriptions();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const categories = Array.from(new Set(subscriptions.map(sub => sub.category)));

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>My Subscriptions</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search subscriptions..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        />

        <select
          value={categoryFilter}
          onChange={(e) => setCategoryFilter(e.target.value)}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="all">All Categories</option>
          {categories.map(category => (
            <option key={category} value={category}>{category}</option>
          ))}
        </select>
      </div>

      {filteredSubscriptions.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No subscriptions found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {filteredSubscriptions.map(sub => (
            <div 
              key={sub.id} 
              style={{ 
                border: "1px solid #ddd", 
                borderRadius: "8px", 
                padding: "15px", 
                display: "flex", 
                justifyContent: "space-between", 
                alignItems: "center",
                flexWrap: "wrap"
              }}
            >
              <div style={{ flex: 1, minWidth: "200px" }}>
                <h3 style={{ margin: "0 0 5px 0" }}>{sub.name}</h3>
                <p style={{ margin: "0 0 5px 0", color: "#666" }}>
                  {sub.category} • ${sub.amount.toFixed(2)} • {sub.billingCycle}
                </p>
                <p style={{ margin: "0", color: "#666" }}>
                  Next billing: {new Date(sub.nextBillingDate).toLocaleDateString()}
                </p>
              </div>
              <button 
                onClick={() => handleDelete(sub.id)}
                style={{ 
                  backgroundColor: "#ff4d4d", 
                  color: "white", 
                  border: "none", 
                  borderRadius: "4px", 
                  padding: "8px 12px", 
                  cursor: "pointer",
                  marginLeft: "10px"
                }}
              >
                Cancel
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data to simulate inventory management
let inventoryItems = [
  { id: 1, name: "Burger", stock: 50, price: 8.99 },
  { id: 2, name: "Fries", stock: 100, price: 3.99 },
  { id: 3, name: "Soda", stock: 75, price: 1.99 }
];

// Get all inventory items
router.get("/", (req: Request, res: Response) => {
  res.json(inventoryItems);
});

// Get a specific inventory item by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const item = inventoryItems.find(i => i.id === id);

  if (!item) {
    return res.status(404).json({ error: "Item not found" });
  }

  res.json(item);
});

// Create a new inventory item
router.post("/", (req: Request, res: Response) => {
  const { name, stock, price } = req.body;

  if (!name || stock === undefined || price === undefined) {
    return res.status(400).json({ error: "Name, stock, and price are required" });
  }

  const newItem = {
    id: inventoryItems.length > 0 ? Math.max(...inventoryItems.map(i => i.id)) + 1 : 1,
    name,
    stock: Number(stock),
    price: Number(price)
  };

  inventoryItems.push(newItem);
  res.status(201).json(newItem);
});

// Update an existing inventory item
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { name, stock, price } = req.body;

  const itemIndex = inventoryItems.findIndex(i => i.id === id);

  if (itemIndex === -1) {
    return res.status(404).json({ error: "Item not found" });
  }

  if (!name || stock === undefined || price === undefined) {
    return res.status(400).json({ error: "Name, stock, and price are required" });
  }

  inventoryItems[itemIndex] = {
    id,
    name,
    stock: Number(stock),
    price: Number(price)
  };

  res.json(inventoryItems[itemIndex]);
});

// Delete an inventory item
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const itemIndex = inventoryItems.findIndex(i => i.id === id);

  if (itemIndex === -1) {
    return res.status(404).json({ error: "Item not found" });
  }

  inventoryItems.splice(itemIndex, 1);
  res.json({ message: "Item deleted successfully" });
});
"}

