{"code":"import { useEffect, useState } from "react";

interface AttendanceRecord {
  id: string;
  singerName: string;
  date: string;
  status: "present" | "absent";
}

export function AttendanceMarkingPanel() {
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newRecord, setNewRecord] = useState({
    singerName: "",
    date: "",
    status: "present" as "present" | "absent"
  });

  useEffect(() => {
    fetchAttendanceRecords();
  }, []);

  const fetchAttendanceRecords = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/attendance-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setRecords(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setNewRecord(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/attendance-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newRecord)
      });
      if (!response.ok) {
        throw new Error(`Failed to create record: ${response.status} ${response.statusText}`);
      }
      // Reset form
      setNewRecord({
        singerName: "",
        date: "",
        status: "present"
      });
      // Refresh data
      await fetchAttendanceRecords();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const updateStatus = async (id: string, status: "present" | "absent") => {
    try {
      const response = await fetch(`/api/attendance-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status })
      });
      if (!response.ok) {
        throw new Error(`Failed to update record: ${response.status} ${response.statusText}`);
      }
      await fetchAttendanceRecords();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const deleteRecord = async (id: string) => {
    try {
      const response = await fetch(`/api/attendance-api/${id}`, {
        method: "DELETE"
      });
      if (!response.ok) {
        throw new Error(`Failed to delete record: ${response.status} ${response.statusText}`);
      }
      await fetchAttendanceRecords();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Attendance Marking Panel</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "15px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2>Add New Record</h2>
        <div style={{ marginBottom: "10px" }}>
          <label>Singer Name: </label>
          <input
            type="text"
            name="singerName"
            value={newRecord.singerName}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            required
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label>Date: </label>
          <input
            type="date"
            name="date"
            value={newRecord.date}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            required
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label>Status: </label>
          <select
            name="status"
            value={newRecord.status}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", marginTop: "5px" }}
          >
            <option value="present">Present</option>
            <option value="absent">Absent</option>
          </select>
        </div>
        <button type="submit" style={{ backgroundColor: "#007bff", color: "white", padding: "10px 15px", border: "none", borderRadius: "4px", cursor: "pointer" }}>
          Add Record
        </button>
      </form>

      <h2>Attendance Records</h2>
      {records.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>No records found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {records.map(record => (
            <div key={record.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <strong>{record.singerName}</strong> - {record.date}
                <br />
                Status: <span style={{ fontWeight: "bold" }}>{record.status}</span>
              </div>
              <div style={{ display: "flex", gap: "5px" }}>
                <button 
                  onClick={() => updateStatus(record.id, "present")}
                  style={{ backgroundColor: record.status === "present" ? "green" : "#28a745", color: "white", padding: "5px 10px", border: "none", borderRadius: "4px", cursor: "pointer" }}
                >
                  Present
                </button>
                <button 
                  onClick={() => updateStatus(record.id, "absent")}
                  style={{ backgroundColor: record.status === "absent" ? "red" : "#dc3545", color: "white", padding: "5px 10px", border: "none", borderRadius: "4px", cursor: "pointer" }}
                >
                  Absent
                </button>
                <button 
                  onClick={() => deleteRecord(record.id)}
                  style={{ backgroundColor: "#6c757d", color: "white", padding: "5px 10px", border: "none", borderRadius: "4px", cursor: "pointer" }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

