export const db = new DatabaseSync(
  "/tmp/manuscript-submission-tracker.db"
);

interface Submission {
  id: number;
  manuscript_text: string;
  category_id: number;
  author_id: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS submissions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    manuscript_text TEXT NOT NULL,
    category_id INTEGER NOT NULL,
    author_id INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllSubmissions(): Submission[] {
  const stmt = db.prepare(`SELECT * FROM submissions`);
  return stmt.all() as unknown as Submission[];
}

export function getSubmissionById(id: number): Submission | undefined {
  const stmt = db.prepare(
    `SELECT * FROM submissions WHERE id = ?`
  );
  return stmt.get(id) as unknown as Submission | undefined;
}

export function insertSubmission(
  manuscriptText: string,
  categoryId: number,
  authorId: number
): number {
  const stmt = db.prepare(
    `INSERT INTO submissions (manuscript_text, category_id, author_id) VALUES (?, ?, ?)`
  );
  const result = stmt.run(manuscriptText, categoryId, authorId);
  return Number(result.lastInsertRowid);
}

export function updateSubmission(
  id: number,
  manuscriptText: string,
  categoryId: number,
  authorId: number
): number {
  const stmt = db.prepare(
    `UPDATE submissions SET manuscript_text = ?, category_id = ?, author_id = ? WHERE id = ?`
  );
  const result = stmt.run(manuscriptText, categoryId, authorId, id);
  return Number(result.changes);
}

export function deleteSubmission(id: number): number {
  const stmt = db.prepare(`DELETE FROM submissions WHERE id = ?`);
