{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/tmp/booking.db"
);

interface Room {
  id: number;
  capacity: number;
  location: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS rooms (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    capacity INTEGER NOT NULL,
    location TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllRooms(): Room[] {
  const stmt = db.prepare(`SELECT * FROM rooms`);
  return stmt.all() as unknown as Room[];
}

export function getRoomById(id: number): Room | undefined {
  const stmt = db.prepare(`SELECT * FROM rooms WHERE id = ?`);
  return stmt.get(id) as Room | undefined;
}

export function insertRoom(capacity: number, location: string): number {
  const stmt = db.prepare(
    `INSERT INTO rooms (capacity, location) VALUES (?, ?)`
  );
  const result = stmt.run(capacity, location);
  return Number(result.lastInsertRowid);
}

export function updateRoom(
  id: number,
  capacity: number,
  location: string
): void {
  const stmt = db.prepare(
    `UPDATE rooms SET capacity = ?, location = ? WHERE id = ?`
  );
  stmt.run(capacity, location, id);
}

export function deleteRoom(id: number): void {
  const stmt = db.prepare(`DELETE FROM rooms WHERE id = ?`);
  stmt.run(id);
}

// Seed data
if (getAllRooms().length === 0) {
  insertRoom(10, "Main Hall");
  insertRoom(25, "Conference Room A");
  insertRoom(15, "Meeting Room B");
  insertRoom(30, "Auditorium");
  insertRoom(8, "Quiet Room");
}
"}

