  const id = Number(req.params.id);
  const { name } = req.body;

  if (!name || typeof name !== "string") {
    return res.status(400).json({ error: "Name is required and must be a string" });
  }

  const tagIndex = mockTags.findIndex(t => t.id === id);

  if (tagIndex === -1) {
