  }

  mockTags[tagIndex].name = name;
  res.json(mockTags[tagIndex]);
});

// Delete a tag by ID
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const tagIndex = mockTags.findIndex(t => t.id === id);

  if (tagIndex === -1) {
    return res.status(404).json({ error: "Tag not found" });
  }

  mockTags.splice(tagIndex, 1);
  res.json({ message: "Tag deleted successfully" });
});

// Associate a tag with a note
router.post("/:tagId/notes/:noteId", (req: Request, res: Response) => {
  const tagId = Number(req.params.tagId);
  const noteId = Number(req.params.noteId);

