  ],

  findAll(): Promise<any[]> {
    return Promise.resolve(this.classes);
  },

  findById(id: string): Promise<any | null> {
    const found = this.classes.find(cls => cls.id === id);
    return Promise.resolve(found || null);
  },

  create(newClass: any): Promise<any> {
    const created = { ...newClass, id: String(this.classes.length + 1) };
    this.classes.push(created);
    return Promise.resolve(created);
  },

  update(id: string, updatedClass: any): Promise<any | null> {
    const index = this.classes.findIndex(cls => cls.id === id);
    if (index === -1) return Promise.resolve(null);
    this.classes[index] = { ...this.classes[index], ...updatedClass };
    return Promise.resolve(this.classes[index]);
  },

  delete(id: string): Promise<boolean> {
