{"code":"import type { Request, Response, NextFunction } from "express";
import { createHash, scryptSync, randomBytes, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // This middleware is designed to handle password hashing for user registration
  // It should only process POST requests to the /register endpoint
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  // Check if password exists in request body
  if (!req.body || typeof req.body.password !== "string") {
    next();
    return;
  }

  // Hash the password using scrypt
  const salt = randomBytes(16).toString("hex");
  const key = scryptSync(req.body.password, salt, 32);
  const hashedPassword = key.toString("hex");

  // Replace the password with the hashed version
  req.body.password = hashedPassword;
  req.body.salt = salt;

  next();
}
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database - in a real app this would be a proper database
const users: { id: number; username: string; password: string }[] = [];
let nextId = 1;

// Mock JWT implementation - in a real app this would use a proper JWT library
const generateToken = (userId: number): string => {
  return `token_${userId}_${Date.now()}`;
};

const verifyToken = (token: string): number | null => {
  const match = token.match(/^token_(\d+)_\d+$/);
  if (match) {
    return parseInt(match[1], 10);
  }
  return null;
};

// Registration endpoint
router.post("/register", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: nextId++,
    username,
    password
  };

  users.push(newUser);

  // Generate token
  const token = generateToken(newUser.id);

  res.status(201).json({
    id: newUser.id,
    username: newUser.username,
    token
  });
});

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Find user
  const user = users.find(u => u.username === username && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate token
  const token = generateToken(user.id);

  res.json({
    id: user.id,
    username: user.username,
    token
  });
});

// Middleware to verify JWT token
const authenticate = (req: Request, res: Response, next: Function) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Authorization header missing or invalid" });
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix
  const userId = verifyToken(token);

  if (!userId) {
    return res.status(401).json({ error: "Invalid or expired token" });
  }

  // Attach user ID to request for downstream middleware/handlers
  (req as any).userId = userId;
  next();
};

// Session endpoint - returns user info if valid session
router.get("/session", authenticate, (req: Request, res: Response) => {
  const userId = (req as any).userId;

  const user = users.find(u => u.id === userId);
  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  res.json({
    id: user.id,
    username: user.username
  });
});
"}

