      </button>

      {/* Form for creating/editing */}
      {showForm && (
        <div style={{ 
          border: '1px solid #ccc', 
          padding: '20px', 
          borderRadius: '4px', 
          marginBottom: '20px' 
        }}>
          <h2>{editingBatch ? 'Edit Batch' : 'Create New Batch'}</h2>
          <form onSubmit={editingBatch ? handleUpdate : handleCreate}>
            <div style={{ marginBottom: '10px' }}>
              <label>Name:</label><br />
              <input
                type="text"
                value={formData.name}
                onChange={(e) => setFormData({...formData, name: e.target.value})}
