                    style={{ padding: "5px 10px", backgroundColor: "#f0f0f0", border: "none", borderRadius: "4px" }}
                  >
                    -
                  </button>
                  <span style={{ minWidth: "30px", textAlign: "center" }}>{item.quantity}</span>
                  <button 
                    onClick={() => handleQuantityChange(item.cake.id, item.quantity + 1)}
                    style={{ padding: "5px 10px", backgroundColor: "#f0f0f0", border: "none", borderRadius: "4px" }}
                  >
                    +
                  </button>
                </div>
                <p style={{ marginTop: "10px", fontWeight: "bold" }}>
                  ${(item.cake.basePrice + item.cake.customizationOptions.decorations.length * 5) * item.quantity}
