  try {
    const newsletters = await mockDatabase.findAll();
    res.json(newsletters);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch newsletters" });
  }
});

// Get a single newsletter by ID
router.get("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }
    const newsletter = await mockDatabase.findById(id);
    if (!newsletter) {
      return res.status(404).json({ error: "Newsletter not found" });
    }
    res.json(newsletter);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch newsletter" });
  }
});

// Create a new newsletter
router.post("/", async (req: Request, res: Response) => {
  try {
    const { title, description } = req.body;
    if (!title || !description) {
      return res.status(400).json({ error: "Title and description are required" });
    }
    const newNewsletter = await mockDatabase.create({ title, description });
    res.status(201).json(newNewsletter);
  } catch (error) {
    res.status(500).json({ error: "Failed to create newsletter" });
  }
});

// Update a newsletter
router.put("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }
    const { title, description } = req.body;
    const updatedNewsletter = await mockDatabase.update(id, { title, description });
    if (!updatedNewsletter) {
      return res.status(404).json({ error: "Newsletter not found" });
    }
    res.json(updatedNewsletter);
  } catch (error) {
    res.status(500).json({ error: "Failed to update newsletter" });
  }
});

// Delete a newsletter
router.delete("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }
