                  <button 
                    onClick={() => updateRideStatus(ride.id, "accepted")}
                    style={{
                      padding: "8px 12px",
                      backgroundColor: "#007bff",
                      color: "white",
                      border: "none",
                      borderRadius: "4px",
                      cursor: "pointer"
                    }}
                  >
                    Accept Ride
                  </button>
                )}

                {ride.status === "accepted" && (
                  <button 
                    onClick={() => updateRideStatus(ride.id, "completed")}
                    style={{
                      padding: "8px 12px",
                      backgroundColor: "#28a745",
                      color: "white",
                      border: "none",
                      borderRadius: "4px",
                      cursor: "pointer"
                    }}
                  >
                    Mark as Completed
                  </button>
                )}

                {(ride.status === "pending" || ride.status === "accepted") && (
                  <button 
                    onClick={() => updateRideStatus(ride.id, "cancelled")}
                    style={{
                      padding: "8px 12px",
                      backgroundColor: "#dc3545",
                      color: "white",
                      border: "none",
                      borderRadius: "4px",
                      cursor: "pointer"
                    }}
