                    Cancel Ride
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function getRideStatusColor(status: Ride["status"]) {
  switch (status) {
    case "pending": return "#ffc107";
    case "accepted": return "#17a2b8";
    case "completed": return "#28a745";
    case "cancelled": return "#dc3545";
    default: return "#000";
  }
}
"}

