{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to POST requests to /register
  if (req.method !== "POST" || req.path !== "/register") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify properly)
  const [payload, signature] = token.split(".");
  if (!payload || !signature) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  // Create expected signature
  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64url");

  // Use timingSafeEqual to prevent timing attacks
  const expectedBuffer = Buffer.from(expectedSignature);
  const actualBuffer = Buffer.from(signature);

  if (expectedBuffer.length !== actualBuffer.length || 
      !timingSafeEqual(expectedBuffer, actualBuffer)) {
    res.status(401).json({ error: "Unauthorized: Invalid token signature" });
    return;
  }

  // In a real implementation, we would decode the payload here
  // For now, we'll just check if the role is present in the payload
  // This is a simplified version - in practice, you'd parse the JWT properly
  try {
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());
    const userRole = decodedPayload.role;

    if (!userRole) {
      res.status(403).json({ error: "Forbidden: Role not specified in token" });
      return;
    }

    // Allow only staff to register students
    if (userRole === "staff") {
      next();
    } else if (userRole === "student") {
      res.status(403).json({ error: "Forbidden: Students cannot register other students" });
    } else {
      res.status(403).json({ error: "Forbidden: Unknown role" });
    }
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Invalid token payload" });
  }
}
"}

{"code":"import { useEffect, useState } from "react";

interface Page {
  id: string;
  title: string;
  content: string;
  ownerId: string;
}

export function PageEditor() {
  const [pages, setPages] = useState<Page[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [ownerId, setOwnerId] = useState("");

  useEffect(() => {
    fetchPages();
  }, []);

  const fetchPages = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/wiki-page-service/');
      if (!response.ok) {
        throw new Error(`Failed to fetch pages: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setPages(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim() || !content.trim()) return;

    try {
      const method = editingId ? 'PUT' : 'POST';
      const url = editingId 
        ? `/api/wiki-page-service/${editingId}`
        : '/api/wiki-page-service/';

      const response = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title, content, ownerId }),
      });

      if (!response.ok) {
        throw new Error(`Failed to save page: ${response.status} ${response.statusText}`);
      }

      // Reset form and reload pages
      setTitle("");
      setContent("");
      setEditingId(null);
      fetchPages();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleEdit = (page: Page) => {
    setTitle(page.title);
    setContent(page.content);
    setEditingId(page.id);
    setOwnerId(page.ownerId);
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/wiki-page-service/${id}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        throw new Error(`Failed to delete page: ${response.status} ${response.statusText}`);
      }

      fetchPages();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const pageListStyle = {
    display: "flex",
    flexDirection: "column" as const,
    gap: "16px",
  };

  const cardStyle = {
    border: "1px solid #ccc",
    borderRadius: "8px",
    padding: "16px",
    maxWidth: "600px",
    margin: "0 auto",
  };

  const inputStyle = {
    width: "100%",
    padding: "8px",
    marginBottom: "12px",
    borderRadius: "4px",
    border: "1px solid #ddd",
  };

  const buttonStyle = {
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    borderRadius: "4px",
    padding: "8px 16px",
    cursor: "pointer",
    marginRight: "8px",
  };

  const deleteButtonStyle = {
    backgroundColor: "#dc3545",
    color: "white",
    border: "none",
    borderRadius: "4px",
    padding: "8px 16px",
    cursor: "pointer",
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1>Wiki Page Editor</h1>

      <form onSubmit={handleSubmit} style={cardStyle}>
        <input
          type="text"
          placeholder="Title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          style={inputStyle}
        />
        <textarea
          placeholder="Content"
          value={content}
          onChange={(e) => setContent(e.target.value)}
          style={{ ...inputStyle, height: "120px" }}
        />
        <input
          type="text"
          placeholder="Owner ID"
          value={ownerId}
          onChange={(e) => setOwnerId(e.target.value)}
          style={inputStyle}
        />
        <button type="submit" style={buttonStyle}>{editingId ? "Update Page" : "Create Page"}</button>
      </form>

      <div style={pageListStyle}>
        <h2>Existing Pages</h2>
        {pages.length === 0 ? (
          <p>No pages found.</p>
        ) : (
          pages.map((page) => (
            <div key={page.id} style={cardStyle}>
              <h3>{page.title}</h3>
              <p>{page.content}</p>
              <p><strong>Owner ID:</strong> {page.ownerId}</p>
              <div>
                <button onClick={() => handleEdit(page)} style={buttonStyle}>Edit</button>
                <button onClick={() => handleDelete(page.id)} style={deleteButtonStyle}>Delete</button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface Plot {
  id: number;
  status: "available" | "reserved";
  current_reservation: string | null;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS plots (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    status TEXT NOT NULL,
    current_reservation TEXT
  )
`;

db.exec(createTableSql);

export function getAllPlots(): Plot[] {
  const stmt = db.prepare(`SELECT * FROM plots`);
  return stmt.all() as unknown as Plot[];
}

export function getPlotById(id: number): Plot | undefined {
  const stmt = db.prepare(`SELECT * FROM plots WHERE id = ?`);
  return stmt.get(id) as unknown as Plot | undefined;
}

export function insertPlot(plot: Omit<Plot, "id">): number {
  const stmt = db.prepare(
    `INSERT INTO plots (status, current_reservation) VALUES (?, ?)`
  );
  const result = stmt.run(plot.status, plot.current_reservation);
  return Number(result.lastInsertRowid);
}

export function updatePlot(id: number, plot: Partial<Plot>): boolean {
  const stmt = db.prepare(
    `UPDATE plots SET status = ?, current_reservation = ? WHERE id = ?`
  );
  const result = stmt.run(
    plot.status ?? "",
    plot.current_reservation ?? null,
    id
  );
  return result.changes > 0;
}

export function deletePlot(id: number): boolean {
  const stmt = db.prepare(`DELETE FROM plots WHERE id = ?`);
  const result = stmt.run(id);
  return result.changes > 0;
}

// Sample data initialization
if (getAllPlots().length === 0) {
  insertPlot({
    status: "available",
    current_reservation: null
  });
  insertPlot({
