{"code":"import { Router, type Request, type Response } from "express";
import {
  deleteGrantRequest,
  getAllGrantRequests,
  getGrantRequestById,
  insertGrantRequest,
  updateGrantRequest
} from "../db/grant-requests-table";

export const router = Router();

// Get all grant requests
router.get("/", (req: Request, res: Response) => {
  const grantRequests = getAllGrantRequests();
  res.json(grantRequests);
});

// Get a specific grant request by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid ID" });
  }

  const grantRequest = getGrantRequestById(id);

  if (!grantRequest) {
    return res.status(404).json({ error: "Grant request not found" });
  }

  res.json(grantRequest);
});

// Create a new grant request
router.post("/", (req: Request, res: Response) => {
  const { applicantId, amount, status } = req.body;

  if (!applicantId || !amount || !status) {
    return res.status(400).json({ error: "Missing required fields: applicantId, amount, status" });
  }

  const id = insertGrantRequest(applicantId, amount, status);

  res.status(201).json({ id, applicantId, amount, status });
});

// Update an existing grant request
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { applicantId, amount, status } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid ID" });
  }

  if (!applicantId || !amount || !status) {
    return res.status(400).json({ error: "Missing required fields: applicantId, amount, status" });
  }

  const existingGrantRequest = getGrantRequestById(id);

  if (!existingGrantRequest) {
    return res.status(404).json({ error: "Grant request not found" });
  }

  updateGrantRequest(id, applicantId, amount, status);

  res.json({ id, applicantId, amount, status });
});

// Delete a grant request
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid ID" });
  }

  const existingGrantRequest = getGrantRequestById(id);

  if (!existingGrantRequest) {
    return res.status(404).json({ error: "Grant request not found" });
  }

  deleteGrantRequest(id);

  res.json({ message: "Grant request deleted successfully" });
});
"}

{"code":"import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply guard to excuse-related requests
  if (!(req.method === "POST" && req.path === "/excuses") &&
      !(req.method === "PUT" && req.path.startsWith("/excuses/")) &&
      !(req.method === "DELETE" && req.path.startsWith("/excuses/"))) {
    next();
    return;
  }

  // Check if user is director - this is a placeholder implementation
  // In a real system, this would check the authenticated user's role
  const isDirector = req.headers["x-user-role"] === "director";

  if (!isDirector) {
    res.status(403).json({ error: "Forbidden: Director access required" });
    return;
  }

  next();
}
