export const router = Router();

// Get all usage events for a specific member
router.get("/member/:memberId", (req: Request, res: Response) => {
  const memberId = Number(req.params.memberId);

  if (isNaN(memberId)) {
    return res.status(400).json({ error: "Invalid member ID" });
  }

  const events = getAllUsageEvents().filter(event => event.memberId === memberId);

  return res.json(events);
});

// Get a specific usage event by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid event ID" });
  }

  const event = getUsageEventById(id);

  if (!event) {
    return res.status(404).json({ error: "Usage event not found" });
  }

  return res.json(event);
});

// Create a new usage event
router.post("/", (req: Request, res: Response) => {
  const { memberId, kwhUsed, date } = req.body;

  if (!memberId || !kwhUsed || !date) {
    return res.status(400).json({ error: "Member ID, kWh used, and date are required" });
  }

  const newId = insertUsageEvent(memberId, kwhUsed, date);

  return res.status(201).json({ id: newId, memberId, kwhUsed, date });
});

// Update an existing usage event
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { memberId, kwhUsed, date } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid event ID" });
  }

  if (!memberId || !kwhUsed || !date) {
    return res.status(400).json({ error: "Member ID, kWh used, and date are required" });
  }

  const existingEvent = getUsageEventById(id);

  if (!existingEvent) {
    return res.status(404).json({ error: "Usage event not found" });
  }

  updateUsageEvent(id, memberId, kwhUsed, date);

  return res.json({ id, memberId, kwhUsed, date });
});

// Delete a usage event
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid event ID" });
  }

  const existingEvent = getUsageEventById(id);

  if (!existingEvent) {
    return res.status(404).json({ error: "Usage event not found" });
  }

  deleteUsageEvent(id);

  return res.json({ message: "Usage event deleted successfully" });
