{"code":"import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to complaint management routes
  const isComplaintRoute = req.path.startsWith('/complaints') && 
                          (req.method === 'POST' || 
                           req.method === 'PUT' || 
                           req.method === 'DELETE');

  if (!isComplaintRoute) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers['x-user-role'] as string | undefined;

  if (!userRole) {
    res.status(401).json({ error: 'Unauthorized: Missing role header' });
    return;
  }

  // Allow only admin and staff roles to access complaint management
  if (userRole !== 'admin' && userRole !== 'staff') {
    res.status(403).json({ error: 'Forbidden: Insufficient permissions' });
    return;
  }

  next();
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT secret is set
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // For demonstration purposes, we'll simulate token verification
  // In a real implementation, you would decode and verify the JWT signature
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);

  // Simulate token verification using HMAC-SHA256
  const expectedSignature = createHmac("sha256", jwtSecret)
    .update(token.split(".")[0] + "." + token.split(".")[1])
    .digest();

  const actualSignature = Buffer.from(token.split(".")[2], "base64");

  try {
    const isValid = timingSafeEqual(expectedSignature, actualSignature);
    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // If token is valid, proceed to next middleware
    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized" });
  }
}
"}

