  password_hash: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    email TEXT UNIQUE NOT NULL,
    role TEXT NOT NULL,
    password_hash TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllUsers(): User[] {
  const stmt = db.prepare("SELECT * FROM users");
  return stmt.all() as unknown as User[];
}

export function getUserById(id: number): User | undefined {
  const stmt = db.prepare("SELECT * FROM users WHERE id = ?");
  return stmt.get(id) as unknown as User | undefined;
}

export function insertUser(user: Omit<User, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO users (name, email, role, password_hash) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(user.name, user.email, user.role, user.password_hash);
  return Number(result.lastInsertRowid);
}

export function updateUser(id: number, user: Partial<Omit<User, "id">>): boolean {
  const fields = [];
  const values = [];

  if (user.name !== undefined) {
    fields.push("name = ?");
    values.push(user.name);
  }

  if (user.email !== undefined) {
    fields.push("email = ?");
    values.push(user.email);
  }

  if (user.role !== undefined) {
    fields.push("role = ?");
    values.push(user.role);
  }

  if (user.password_hash !== undefined) {
    fields.push("password_hash = ?");
    values.push(user.password_hash);
  }

  if (fields.length === 0) return false;

  values.push(id);

  const sql = `UPDATE users SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);

  return true;
}

export function deleteUser(id: number): boolean {
  const stmt = db.prepare("DELETE FROM users WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
