  const [bookedSlots, setBookedSlots] = useState<ParkingSlot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchSlots = async () => {
      try {
        // Simulate API call
        await new Promise(resolve => setTimeout(resolve, 500));

        // Mock data
        const mockSlots: ParkingSlot[] = [
          { id: "1", location: "A1", price: 10, isBooked: false },
          { id: "2", location: "A2", price: 15, isBooked: true },
          { id: "3", location: "B1", price: 8, isBooked: false },
          { id: "4", location: "B2", price: 12, isBooked: false },
          { id: "5", location: "C1", price: 20, isBooked: true },
        ];

        setAvailableSlots(mockSlots.filter(slot => !slot.isBooked));
        setBookedSlots(mockSlots.filter(slot => slot.isBooked));
      } catch (err) {
        setError("Failed to load parking slots");
      } finally {
        setLoading(false);
      }
    };

    fetchSlots();
  }, []);

  const handleBookSlot = (slotId: string) => {
    // In a real app, this would make a POST request
    console.log(`Booking slot ${slotId}`);

    // Update UI immediately
    const updatedSlots = availableSlots.map(slot => 
      slot.id === slotId ? {...slot, isBooked: true} : slot
    );

    setAvailableSlots(updatedSlots);
    setBookedSlots(prev => [...prev, updatedSlots.find(s => s.id === slotId)!]);
  };

  const handleCancelBooking = (slotId: string) => {
    // In a real app, this would make a DELETE request
    console.log(`Cancelling booking for slot ${slotId}`);

    // Update UI immediately
    const updatedSlots = bookedSlots.map(slot => 
      slot.id === slotId ? {...slot, isBooked: false} : slot
    );

    setBookedSlots(updatedSlots);
