{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would come from a database module
const mockProblems = [
  { id: 1, title: "Two Sum", description: "Given an array of integers, return indices of the two numbers such that they add up to a specific target.", difficulty: "Easy" },
  { id: 2, title: "Reverse Linked List", description: "Given the head of a singly linked list, reverse the list, and return the reversed list.", difficulty: "Easy" }
];

const findProblemById = (id: number) => {
  return mockProblems.find(problem => problem.id === id);
};

const createProblem = (title: string, description: string, difficulty: string) => {
  const newId = Math.max(0, ...mockProblems.map(p => p.id)) + 1;
  const newProblem = { id: newId, title, description, difficulty };
  mockProblems.push(newProblem);
  return newProblem;
};

const updateProblem = (id: number, title: string, description: string, difficulty: string) => {
  const index = mockProblems.findIndex(problem => problem.id === id);
  if (index === -1) return null;

  mockProblems[index] = { id, title, description, difficulty };
  return mockProblems[index];
};

const deleteProblem = (id: number) => {
  const index = mockProblems.findIndex(problem => problem.id === id);
  if (index === -1) return false;

  mockProblems.splice(index, 1);
  return true;
};

// GET /problems - List all problems
router.get("/problems", (req: Request, res: Response) => {
  res.json(mockProblems);
});

// GET /problems/:id - Get a specific problem by ID
router.get("/problems/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid problem ID" });
  }

  const problem = findProblemById(id);

  if (!problem) {
    return res.status(404).json({ error: "Problem not found" });
  }

  res.json(problem);
});

// POST /problems - Create a new problem
router.post("/problems", (req: Request, res: Response) => {
  const { title, description, difficulty } = req.body;

  if (!title || !description || !difficulty) {
    return res.status(400).json({ error: "Title, description, and difficulty are required" });
  }

  const newProblem = createProblem(title, description, difficulty);

  res.status(201).json(newProblem);
});

// PUT /problems/:id - Update a problem
router.put("/problems/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { title, description, difficulty } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid problem ID" });
  }

  if (!title || !description || !difficulty) {
    return res.status(400).json({ error: "Title, description, and difficulty are required" });
  }

  const updatedProblem = updateProblem(id, title, description, difficulty);

  if (!updatedProblem) {
    return res.status(404).json({ error: "Problem not found" });
  }

  res.json(updatedProblem);
});

// DELETE /problems/:id - Delete a problem
router.delete("/problems/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid problem ID" });
  }

  const deleted = deleteProblem(id);

  if (!deleted) {
    return res.status(404).json({ error: "Problem not found" });
  }

  res.json({ message: "Problem deleted successfully" });
});
"}

