  res.json(staffMembers[staffIndex]);
});

// Delete a staff member
router.delete("/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const staffIndex = staffMembers.findIndex(s => s.id === id);

  if (staffIndex === -1) {
    return res.status(404).json({ error: "Staff member not found" });
  }

  staffMembers.splice(staffIndex, 1);

  res.json({ message: "Staff member deleted successfully" });
});
"}

{"code":"import { useEffect, useState } from "react";

interface FeedingRecord {
  id: number;
  animal: string;
  food: string;
  amount: number;
  date: string;
}

export function FeedingLogForm() {
  const [feedings, setFeedings] = useState<FeedingRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    animal: "",
    food: "",
    amount: "",
    date: ""
  });

  useEffect(() => {
    fetchFeedings();
  }, []);

  const fetchFeedings = async () => {
    try {
      const response = await fetch("/api/feedings-api/");
      if (!response.ok) throw new Error("Failed to fetch feedings");
      const data = await response.json();
      setFeedings(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
      setLoading(false);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/feedings-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...formData,
          amount: Number(formData.amount)
        })
      });
      if (!response.ok) throw new Error("Failed to add feeding");
      await fetchFeedings();
      setFormData({ animal: "", food: "", amount: "", date: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Feeding Log</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <div style={{ marginBottom: "15px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Animal:</label>
          <input
            type="text"
            name="animal"
            value={formData.animal}
            onChange={handleChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Food:</label>
          <input
            type="text"
            name="food"
            value={formData.food}
            onChange={handleChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Amount (grams):</label>
          <input
            type="number"
            name="amount"
            value={formData.amount}
            onChange={handleChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Date:</label>
          <input
            type="date"
            name="date"
            value={formData.date}
            onChange={handleChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <button
          type="submit"
          style={{
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            padding: "10px 20px",
            borderRadius: "4px",
            cursor: "pointer",
            width: "100%"
          }}
        >
          Add Feeding Record
        </button>
      </form>

      <h2 style={{ textAlign: "center" }}>Feeding Records</h2>

      {feedings.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>No feeding records found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {feedings.map(feeding => (
            <div key={feeding.id} style={{
              border: "1px solid #ccc",
              borderRadius: "8px",
              padding: "15px",
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center"
            }}>
              <div>
                <strong>{feeding.animal}</strong> - {feeding.food} ({feeding.amount}g) on {feeding.date}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import {
  getAllShifts,
  getShiftById,
  insertShift,
  updateShift,
  deleteShift,
} from "../db/shifts-table";
import {
  getAllShiftDeletes,
  getShiftDeleteById,
  insertShiftDelete,
} from "../db/shift-deletes-table";

export const router = Router();

// Get all shifts
router.get("/", (req: Request, res: Response) => {
  try {
    const shifts = getAllShifts();
    res.json(shifts);
  } catch (err) {
    res.status(500).json({ error: "Failed to fetch shifts" });
  }
});

// Get a shift by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid shift ID" });
  }

  const shift = getShiftById(id);
  if (!shift) {
    return res.status(404).json({ error: "Shift not found" });
  }

  res.json(shift);
});

// Create a new shift
router.post("/", (req: Request, res: Response) => {
  const { parentId, shiftDate, role } = req.body;

  if (!parentId || !shiftDate || !role) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  try {
    const newId = insertShift(parentId, shiftDate, role);
    const newShift = getShiftById(newId);
    res.status(201).json(newShift);
  } catch (err) {
    res.status(500).json({ error: "Failed to create shift" });
  }
});

// Update a shift
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { parentId, shiftDate, role } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid shift ID" });
  }

  if (!parentId || !shiftDate || !role) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const existingShift = getShiftById(id);
  if (!existingShift) {
    return res.status(404).json({ error: "Shift not found" });
  }

  try {
    updateShift(id, parentId, shiftDate, role);
    const updatedShift = getShiftById(id);
    res.json(updatedShift);
  } catch (err) {
    res.status(500).json({ error: "Failed to update shift" });
  }
});

// Delete a shift (supervisor-only)
router.delete("/:id", (req: Request, res: Response) => {
  const shiftId = Number(req.params.id);
  const supervisorId = Number(req.body.supervisorId); // Assuming supervisorId is passed in body

  if (isNaN(shiftId) || isNaN(supervisorId)) {
    return res.status(400).json({ error: "Invalid shift ID or supervisor ID" });
  }

  const shift = getShiftById(shiftId);
  if (!shift) {
    return res.status(404).json({ error: "Shift not found" });
  }

  // Check if this supervisor has already deleted this shift
  const existingDelete = getShiftDeleteById(supervisorId, shiftId);
  if (existingDelete) {
    return res.status(400).json({ error: "Shift already deleted by this supervisor" });
  }

  try {
    // Record the deletion
    insertShiftDelete(supervisorId, shiftId);
    // Actually delete the shift
    deleteShift(shiftId);
    res.json({ message: "Shift deleted successfully" });
  } catch (err) {
    res.status(500).json({ error: "Failed to delete shift" });
  }
});
"}

