export const db = new DatabaseSync("./aquarium.db");

interface Feeding {
  id: number;
  aquarium_id: number;
  animal_id: number;
  time: string;
  quantity: number;
  feeder_id: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS feedings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    aquarium_id INTEGER NOT NULL,
    animal_id INTEGER NOT NULL,
    time TEXT NOT NULL,
    quantity REAL NOT NULL,
    feeder_id INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllFeedings(): Feeding[] {
  const stmt = db.prepare("SELECT * FROM feedings");
  return stmt.all() as unknown as Feeding[];
}

export function getFeedingById(id: number): Feeding | undefined {
  const stmt = db.prepare("SELECT * FROM feedings WHERE id = ?");
  return stmt.get(id) as unknown as Feeding | undefined;
}

export function insertFeeding(
  aquariumId: number,
  animalId: number,
  time: string,
  quantity: number,
  feederId: number
): number {
  const stmt = db.prepare(
    "INSERT INTO feedings (aquarium_id, animal_id, time, quantity, feeder_id) VALUES (?, ?, ?, ?, ?)"
  );
  const result = stmt.run(aquariumId, animalId, time, quantity, feederId);
  return Number(result.lastInsertRowid);
}

export function updateFeeding(
  id: number,
  aquariumId: number,
  animalId: number,
  time: string,
  quantity: number,
  feederId: number
): void {
  const stmt = db.prepare(
    "UPDATE feedings SET aquarium_id = ?, animal_id = ?, time = ?, quantity = ?, feeder_id = ? WHERE id = ?"
  );
  stmt.run(aquariumId, animalId, time, quantity, feederId, id);
}

export function deleteFeeding(id: number): void {
  const stmt = db.prepare("DELETE FROM feedings WHERE id = ?");
  stmt.run(id);
}

