{"code":"import { useEffect, useState } from "react";

interface Plot {
  id: number;
  location: string;
  size: string;
  status: string;
}

interface Reservation {
  id: number;
  plotId: number;
  reservedBy: string;
  startDate: string;
  endDate: string;
}

export function CoordinatorReassignmentPanel() {
  const [plots, setPlots] = useState<Plot[]>([]);
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedReservation, setSelectedReservation] = useState<number | null>(null);
  const [newPlotId, setNewPlotId] = useState<number | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [plotsResponse, reservationsResponse] = await Promise.all([
          fetch("/api/garden-api/plots"),
          fetch("/api/garden-api/reservations")
        ]);

        if (!plotsResponse.ok || !reservationsResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const plotsData = await plotsResponse.json();
        const reservationsData = await reservationsResponse.json();

        setPlots(plotsData);
        setReservations(reservationsData);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleReassign = async (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedReservation === null || newPlotId === null) return;

    try {
      const response = await fetch(`/api/garden-api/reservations/${selectedReservation}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ plotId: newPlotId })
      });

      if (!response.ok) {
        throw new Error("Failed to reassign plot");
      }

      // Refresh data after successful reassignment
      const [plotsResponse, reservationsResponse] = await Promise.all([
        fetch("/api/garden-api/plots"),
        fetch("/api/garden-api/reservations")
      ]);

      if (!plotsResponse.ok || !reservationsResponse.ok) {
        throw new Error("Failed to refresh data");
      }

      const plotsData = await plotsResponse.json();
      const reservationsData = await reservationsResponse.json();

      setPlots(plotsData);
      setReservations(reservationsData);
      setSelectedReservation(null);
      setNewPlotId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  const availablePlots = plots.filter(plot => plot.status !== "reserved");

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Coordinator Reassignment Panel</h1>

      <div style={{ marginBottom: "20px" }}>
        <h2>Current Reservations</h2>
        {reservations.length === 0 ? (
          <p>No reservations found.</p>
        ) : (
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ borderBottom: "1px solid #ccc" }}>
                <th style={{ textAlign: "left", padding: "8px" }}>Reserved By</th>
                <th style={{ textAlign: "left", padding: "8px" }}>Plot Location</th>
                <th style={{ textAlign: "left", padding: "8px" }}>Start Date</th>
                <th style={{ textAlign: "left", padding: "8px" }}>End Date</th>
              </tr>
            </thead>
            <tbody>
              {reservations.map(reservation => {
                const plot = plots.find(p => p.id === reservation.plotId);
                return (
                  <tr key={reservation.id} style={{ borderBottom: "1px solid #eee" }}>
                    <td style={{ padding: "8px" }}>{reservation.reservedBy}</td>
                    <td style={{ padding: "8px" }}>{plot?.location || "Unknown"}</td>
                    <td style={{ padding: "8px" }}>{reservation.startDate}</td>
                    <td style={{ padding: "8px" }}>{reservation.endDate}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>

      <div style={{ marginTop: "30px" }}>
        <h2>Reassign Plot</h2>
        <form onSubmit={handleReassign}>
          <div style={{ marginBottom: "15px" }}>
            <label htmlFor="reservationSelect" style={{ display: "block", marginBottom: "5px" }}>
              Select Reservation:
            </label>
            <select
              id="reservationSelect"
              value={selectedReservation ?? ""}
              onChange={(e) => setSelectedReservation(Number(e.target.value))}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            >
              <option value="">-- Choose a reservation --</option>
              {reservations.map(reservation => (
                <option key={reservation.id} value={reservation.id}>
                  {reservation.reservedBy} - {reservation.startDate} to {reservation.endDate}
                </option>
              ))}
            </select>
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label htmlFor="plotSelect" style={{ display: "block", marginBottom: "5px" }}>
              Assign New Plot:
            </label>
            <select
              id="plotSelect"
              value={newPlotId ?? ""}
              onChange={(e) => setNewPlotId(Number(e.target.value))}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            >
              <option value="">-- Choose a plot --</option>
              {availablePlots.map(plot => (
                <option key={plot.id} value={plot.id}>
                  {plot.location} ({plot.size})
                </option>
              ))}
            </select>
          </div>

          <button
            type="submit"
            disabled={!selectedReservation || !newPlotId}
            style={{
              backgroundColor: "#007bff",
              color: "white",
              border: "none",
              padding: "10px 15px",
              borderRadius: "4px",
              cursor: "pointer",
              fontSize: "16px"
            }}
          >
            Reassign Plot
          </button>
        </form>
      </div>
    </div>
  );
}
"}

