{"code":"import { useEffect, useState } from "react";

interface Audition {
  id: number;
  showId: number;
  actorId: number;
  actorName: string;
  showTitle: string;
}

interface Show {
  id: number;
  title: string;
}

export function AuditionSignupForm() {
  const [shows, setShows] = useState<Show[]>([]);
  const [auditions, setAuditions] = useState<Audition[]>([]);
  const [selectedShowId, setSelectedShowId] = useState<number | null>(null);
  const [actorName, setActorName] = useState<string>("");
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchShows = async () => {
      try {
        const response = await fetch('/api/auditions-api/auditions');
        if (!response.ok) throw new Error('Failed to fetch shows');
        const data = await response.json();
        setShows(data);
      } catch (err) {
        setError('Error loading shows');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    const fetchAuditions = async () => {
      try {
        const response = await fetch('/api/auditions-api/auditions');
        if (!response.ok) throw new Error('Failed to fetch auditions');
        const data = await response.json();
        setAuditions(data);
      } catch (err) {
        setError('Error loading auditions');
        console.error(err);
      }
    };

    fetchShows();
    fetchAuditions();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedShowId || !actorName) return;

    try {
      const response = await fetch('/api/auditions-api/auditions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          showId: selectedShowId,
          actorName
        })
      });

      if (!response.ok) throw new Error('Failed to sign up');

      // Refresh data
      const showsResponse = await fetch('/api/auditions-api/auditions');
      const showsData = await showsResponse.json();
      setShows(showsData);

      const auditionsResponse = await fetch('/api/auditions-api/auditions');
      const auditionsData = await auditionsResponse.json();
      setAuditions(auditionsData);

      // Reset form
      setSelectedShowId(null);
      setActorName("");
    } catch (err) {
      setError('Error signing up');
      console.error(err);
    }
  };

  const handleDelete = async (actorId: number, showId: number) => {
    try {
      const response = await fetch(`/api/auditions-api/auditions/${actorId}/${showId}`, {
        method: 'DELETE'
      });

      if (!response.ok) throw new Error('Failed to delete audition');

      // Refresh data
      const auditionsResponse = await fetch('/api/auditions-api/auditions');
      const auditionsData = await auditionsResponse.json();
      setAuditions(auditionsData);
    } catch (err) {
      setError('Error deleting audition');
      console.error(err);
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  const containerStyle: React.CSSProperties = {
    maxWidth: '600px',
    margin: '0 auto',
    padding: '20px',
    fontFamily: 'system-ui, sans-serif'
  };

  const formStyle: React.CSSProperties = {
    marginBottom: '30px',
    padding: '20px',
    border: '1px solid #ccc',
    borderRadius: '8px'
  };

  const inputStyle: React.CSSProperties = {
    width: '100%',
    padding: '10px',
    borderRadius: '4px',
    border: '1px solid #ccc',
    boxSizing: 'border-box',
    marginBottom: '10px'
  };

  const buttonStyle: React.CSSProperties = {
    backgroundColor: '#007bff',
    color: 'white',
    border: 'none',
    padding: '10px 15px',
    borderRadius: '4px',
    cursor: 'pointer',
    marginRight: '10px'
  };

  const listStyle: React.CSSProperties = {
    display: 'flex',
    flexDirection: 'column',
    gap: '10px'
  };

  const itemStyle: React.CSSProperties = {
    padding: '15px',
    border: '1px solid #ddd',
    borderRadius: '4px',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center'
  };

  const deleteButtonStyle: React.CSSProperties = {
    backgroundColor: '#dc3545',
    color: 'white',
    border: 'none',
    padding: '5px 10px',
    borderRadius: '4px',
    cursor: 'pointer'
  };

  return (
    <div style={containerStyle}>
      <h1>Audition Signup</h1>

      {error && <p style={{ color: 'red' }}>{error}</p>}

      <form onSubmit={handleSubmit} style={formStyle}>
        <h2>Sign Up for Audition</h2>
        <input
          type="text"
          placeholder="Your Name"
          value={actorName}
          onChange={(e) => setActorName(e.target.value)}
          style={inputStyle}
        />
        <select
          value={selectedShowId ?? ''}
          onChange={(e) => setSelectedShowId(Number(e.target.value))}
          style={inputStyle}
        >
          <option value="">Select a Show</option>
          {shows.map(show => (
            <option key={show.id} value={show.id}>{show.title}</option>
          ))}
        </select>
        <button type="submit" style={buttonStyle}>Sign Up</button>
      </form>

      <h2>Current Signups</h2>
      <div style={listStyle}>
        {auditions.length === 0 ? (
          <p>No auditions signed up yet.</p>
        ) : (
          auditions.map(audition => (
            <div key={`${audition.actorId}-${audition.showId}`} style={itemStyle}>
              <div>
                <strong>{audition.actorName}</strong> - {audition.showTitle}
              </div>
              <button 
                onClick={() => handleDelete(audition.actorId, audition.showId)}
                style={deleteButtonStyle}
              >
                Remove
              </button>
            </div>
          ))
        )}
      </div>
    </div>
  );
}
"}

