    if (!team1 || !team2 || !overs) {
      return res.status(400).json({ error: "Missing required fields: team1, team2, overs" });
    }

    const newMatch = await mockDatabase.createMatch({ team1, team2, overs });
    return res.status(201).json(newMatch);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

