router.put("/matches/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { team1, team2, score1, score2, overs } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid match ID" });
    }

    if (!team1 || !team2 || !score1 || !score2 || !overs) {
      return res.status(400).json({ error: "Missing required fields: team1, team2, score1, score2, overs" });
    }

    const updatedMatch = await mockDatabase.updateMatch(id, { team1, team2, score1, score2, overs });

    if (!updatedMatch) {
      return res.status(404).json({ error: "Match not found" });
    }

    return res.json(updatedMatch);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

// DELETE /scoring/matches/:id - Delete a match by ID
router.delete("/matches/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid match ID" });
    }

    const deleted = await mockDatabase.deleteMatch(id);

    if (!deleted) {
      return res.status(404).json({ error: "Match not found" });
    }

    return res.json({ message: "Match deleted successfully" });
  } catch (error) {
