{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteAppointment,
  getAllAppointments,
  getAppointmentById,
  insertAppointment,
  updateAppointment
} from "../db/appointments-table";

export const router = Router();

// Get all appointments for the logged-in member
router.get("/", (req: Request, res: Response) => {
  try {
    const appointments = getAllAppointments();
    return res.json(appointments);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch appointments" });
  }
});

// Get a specific appointment by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid appointment ID" });
  }

  const appointment = getAppointmentById(id);

  if (!appointment) {
    return res.status(404).json({ error: "Appointment not found" });
  }

  return res.json(appointment);
});

// Create a new appointment
router.post("/", (req: Request, res: Response) => {
  const { doctorId, memberId, timeSlot } = req.body;

  if (!doctorId || !memberId || !timeSlot) {
    return res.status(400).json({ error: "Missing required fields: doctorId, memberId, timeSlot" });
  }

  try {
    const newId = insertAppointment(doctorId, memberId, timeSlot);
    const newAppointment = getAppointmentById(newId);

    if (!newAppointment) {
      return res.status(500).json({ error: "Failed to create appointment" });
    }

    return res.status(201).json(newAppointment);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create appointment" });
  }
});

// Update an existing appointment
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { doctorId, memberId, timeSlot } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid appointment ID" });
  }

  if (!doctorId || !memberId || !timeSlot) {
    return res.status(400).json({ error: "Missing required fields: doctorId, memberId, timeSlot" });
  }

  const existingAppointment = getAppointmentById(id);

  if (!existingAppointment) {
    return res.status(404).json({ error: "Appointment not found" });
  }

  try {
    updateAppointment(id, doctorId, memberId, timeSlot);
    const updatedAppointment = getAppointmentById(id);

    if (!updatedAppointment) {
      return res.status(500).json({ error: "Failed to update appointment" });
    }

    return res.json(updatedAppointment);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update appointment" });
  }
});

// Delete an appointment
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid appointment ID" });
  }

  const existingAppointment = getAppointmentById(id);

  if (!existingAppointment) {
    return res.status(404).json({ error: "Appointment not found" });
  }

  try {
    deleteAppointment(id);
    return res.json({ message: "Appointment deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete appointment" });
  }
});
"}

