{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const MAX_REQUESTS = 100;
const TIME_WINDOW_MS = 15 * 60 * 1000; // 15 minutes
const RATE_LIMITED_PATHS = ["/renewal/remind", "/renewal/notify"];

interface RateLimitStore {
  [key: string]: {
    count: number;
    resetTime: number;
  };
}

const store: RateLimitStore = {};

function getRateLimitKey(req: Request): string {
  const ip = req.ip || req.connection.remoteAddress || "unknown";
  const userAgent = req.get("User-Agent") || "unknown";
  return `${ip}:${userAgent}`;
}

function isRateLimited(key: string): boolean {
  const now = Date.now();
  const entry = store[key];

  if (!entry) {
    return false;
  }

  if (now > entry.resetTime) {
    delete store[key];
    return false;
  }

  return entry.count >= MAX_REQUESTS;
}

function incrementCounter(key: string): void {
  const now = Date.now();
  const entry = store[key] || { count: 0, resetTime: now + TIME_WINDOW_MS };

  entry.count += 1;
  store[key] = entry;
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply rate limiting to specific paths
  if (!RATE_LIMITED_PATHS.includes(req.path)) {
    next();
    return;
  }

  const key = getRateLimitKey(req);

  if (isRateLimited(key)) {
    res.status(429).json({
      error: "Too many requests",
      message: "You have exceeded the rate limit. Please try again later."
    });
    return;
  }

  incrementCounter(key);
  next();
}
"}

