    return res.status(500).json({ error: "Failed to update subscriber" });
  }
});

// Delete a subscriber
router.delete("/subscribers/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid subscriber ID" });
    }

    const deletedCount = deleteSubscriber(id);
    if (deletedCount === 0) {
      return res.status(404).json({ error: "Subscriber not found" });
    }

    return res.json({ message: "Subscriber deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete subscriber" });
  }
});
"}

