{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./coop-grocery.db");

interface BoardOwnership {
  board_id: number;
  owner_account_id: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS board_ownership (
    board_id INTEGER PRIMARY KEY,
    owner_account_id INTEGER NOT NULL
  );
`;

db.exec(createTableSql);

export function insertBoardOwnership(boardId: number, ownerId: number): number {
  const sql = `INSERT OR REPLACE INTO board_ownership (board_id, owner_account_id) VALUES (?, ?)`;
  const result = db.prepare(sql).run(boardId, ownerId);
  return Number(result.changes);
}

export function getBoardOwnership(boardId: number): BoardOwnership | undefined {
  const sql = `SELECT * FROM board_ownership WHERE board_id = ?`;
  const result = db.prepare(sql).get(boardId) as unknown as BoardOwnership | undefined;
  return result;
}

export function getAllBoardOwnerships(): BoardOwnership[] {
  const sql = `SELECT * FROM board_ownership`;
  const result = db.prepare(sql).all() as unknown as BoardOwnership[];
  return result;
}

export function deleteBoardOwnership(boardId: number): number {
  const sql = `DELETE FROM board_ownership WHERE board_id = ?`;
  const result = db.prepare(sql).run(boardId);
  return Number(result.changes);
}

// Sample data initialization
