{"code":"import { useEffect, useState } from "react";

interface Booking {
  id: string;
  roomId: string;
  roomName: string;
  startTime: string;
  endTime: string;
  memberName: string;
}

interface Room {
  id: string;
  name: string;
  capacity: number;
}

export function RoomBookingCalendar() {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [rooms, setRooms] = useState<Room[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newBooking, setNewBooking] = useState({
    roomId: "",
    startTime: "",
    endTime: "",
  });

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [bookingsRes, roomsRes] = await Promise.all([
          fetch("/api/bookings-api/"),
          fetch("/api/bookings-api/available-rooms"),
        ]);

        if (!bookingsRes.ok || !roomsRes.ok) {
          throw new Error("Failed to fetch data");
        }

        const bookingsData = await bookingsRes.json();
        const roomsData = await roomsRes.json();

        setBookings(bookingsData);
        setRooms(roomsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setNewBooking({
      ...newBooking,
      [name]: value,
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/bookings-api/", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(newBooking),
      });

      if (!response.ok) {
        throw new Error("Failed to create booking");
      }

      // Refresh data
      const [bookingsRes, roomsRes] = await Promise.all([
        fetch("/api/bookings-api/"),
        fetch("/api/bookings-api/available-rooms"),
      ]);

      if (!bookingsRes.ok || !roomsRes.ok) {
        throw new Error("Failed to refresh data");
      }

      const bookingsData = await bookingsRes.json();
      const roomsData = await roomsRes.json();

      setBookings(bookingsData);
      setRooms(roomsData);

      // Reset form
      setNewBooking({
        roomId: "",
        startTime: "",
        endTime: "",
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
