          <thead>
            <tr style={{ borderBottom: "1px solid #ccc" }}>
              <th style={{ padding: "8px", textAlign: "left" }}>Room</th>
              <th style={{ padding: "8px", textAlign: "left" }}>Start Time</th>
              <th style={{ padding: "8px", textAlign: "left" }}>End Time</th>
