{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data structures to simulate database operations
const feedbackEntries: any[] = [];
const categories = ["complaint", "suggestion", "praise"];

// Helper function to categorize feedback
const categorizeFeedback = (text: string): string => {
  const lowerText = text.toLowerCase();
  if (lowerText.includes("bad") || lowerText.includes("terrible") || lowerText.includes("worst")) {
    return "complaint";
  }
  if (lowerText.includes("good") || lowerText.includes("excellent") || lowerText.includes("love")) {
    return "praise";
  }
  if (lowerText.includes("idea") || lowerText.includes("improve") || lowerText.includes("better")) {
    return "suggestion";
  }
  return "general";
};

// Helper function to generate summary report
const generateSummaryReport = (): any => {
  const report: any = {};
  categories.forEach(category => {
    report[category] = feedbackEntries.filter(entry => entry.category === category).length;
  });
  return report;
};

// POST /feedback - Process feedback submission
router.post("/feedback", (req: Request, res: Response) => {
  const { text, guestId } = req.body;

  if (!text || !guestId) {
    return res.status(400).json({ error: "Text and guestId are required" });
  }

  const category = categorizeFeedback(text);
  const newEntry = {
    id: feedbackEntries.length + 1,
    text,
    guestId,
    category,
    timestamp: new Date().toISOString()
  };

  feedbackEntries.push(newEntry);

  return res.status(201).json(newEntry);
});

// GET /feedback/report - Generate summary report
router.get("/feedback/report", (req: Request, res: Response) => {
  const report = generateSummaryReport();
  return res.json(report);
});
"}

{"code":"import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply authentication to POST requests to the login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if credentials are provided
  if (!req.body || !req.body.username || !req.body.password) {
    res.status(401).json({ error: "Username and password required" });
    return;
  }

  // In a real system, we would check the credentials against a database
  // For this basic implementation, we'll just accept any non-empty credentials
  const { username, password } = req.body;

  if (username.trim() === "" || password.trim() === "") {
    res.status(401).json({ error: "Invalid credentials" });
    return;
  }

  // If we get here, credentials are valid
  next();
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle GET requests to /bookings/:id
  if (req.method !== "GET" || !req.path.startsWith("/bookings/")) {
    next();
    return;
  }

  // Check if user is a regular member
  const userRole = req.headers["x-user-role"];
  if (userRole !== "regular-member") {
    next();
    return;
  }

  // Extract the booking ID from the path
  const pathParts = req.path.split("/");
  const requestedBookingId = pathParts[3];

  // If no booking ID, allow access
  if (!requestedBookingId) {
    next();
    return;
  }

  // Get the user ID from headers
  const userId = req.headers["x-user-id"];

  // If no user ID, deny access
  if (!userId) {
    res.status(403).json({ error: "Access denied" });
    return;
  }

  // Check if the requested booking ID matches the user ID
  // In a real implementation, we would check the actual booking data
  // For now, we'll assume the booking ID contains the user ID
  if (requestedBookingId.includes(userId as string)) {
    next();
  } else {
    res.status(403).json({ error: "Access denied" });
  }
}
"}

