    return res.status(400).json({ error: "Email and password are required" });
  }

  // Find user
  const user = users.find(u => u.email === email && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  const token = generateToken();
  return res.json({ token, user: { id: user.id, email, role: user.role } });
});

// Middleware to verify token (mock implementation)
const authenticate = (req: Request, res: Response, next: Function) => {
  // In a real app, verify JWT token here
  const token = req.headers.authorization?.split(" ")[1];
  if (!token) {
    return res.status(401).json({ error: "No token provided" });
  }

  // Mock user ID assignment
  (req as any).userId = "1"; // Mock user ID
  next();
};

// Middleware to check role (mock implementation)
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: Function) => {
    const user = users.find(u => u.id === (req as any).userId);
    if (!user || !roles.includes(user.role)) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }
    next();
  };
};

// Get user profile endpoint
router.get("/profile", authenticate, (req: Request, res: Response) => {
  const userId = (req as any).userId;
  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  return res.json({ id: user.id, email: user.email, role: user.role });
});

// Update user profile endpoint
router.put("/profile", authenticate, (req: Request, res: Response) => {
  const userId = (req as any).userId;
  const { email, password } = req.body;

  const userIndex = users.findIndex(u => u.id === userId);
  if (userIndex === -1) {
    return res.status(404).json({ error: "User not found" });
  }

  if (email) users[userIndex].email = email;
  if (password) users[userIndex].password = password;

  return res.json({ id: users[userIndex].id, email: users[userIndex].email, role: users[userIndex].role });
});

// Admin-only endpoint example
router.delete("/user/:id", authenticate, authorize(["admin"]), (req: Request, res: Response) => {
  const userId = req.params.id;
  const userIndex = users.findIndex(u => u.id === userId);

  if (userIndex === -1) {
    return res.status(404).json({ error: "User not found" });
  }

  users.splice(userIndex, 1);
  return res.json({ message: "User deleted successfully" });
});
"}

{"code":"import { useEffect, useState } from "react";

interface Patient {
  id: number;
  name: string;
  phone: string;
  email: string;
}

export function PatientManagement() {
  const [patients, setPatients] = useState<Patient[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Form state
  const [formData, setFormData] = useState({
    name: "",
    phone: "",
    email: ""
  });

  const [editingId, setEditingId] = useState<number | null>(null);
  const [searchTerm, setSearchTerm] = useState("");

  // Fetch patients
  useEffect(() => {
    const fetchPatients = async () => {
      try {
        const response = await fetch('/api/patients');
        if (!response.ok) throw new Error('Failed to fetch patients');
        const data = await response.json();
        setPatients(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
        setLoading(false);
      }
    };

    fetchPatients();
  }, []);

  // Handle form input changes
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  // Handle form submission
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = await fetch('/api/patients', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });

      if (!response.ok) throw new Error('Failed to add patient');

      const newPatient = await response.json();
      setPatients(prev => [...prev, newPatient]);
      setFormData({ name: '', phone: '', email: '' });
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  // Handle update
  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId === null) return;

    try {
      const response = await fetch(`/api/patients/${editingId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });

      if (!response.ok) throw new Error('Failed to update patient');

      const updatedPatient = await response.json();
      setPatients(prev => 
        prev.map(p => p.id === editingId ? updatedPatient : p)
      );
      setEditingId(null);
      setFormData({ name: '', phone: '', email: '' });
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  // Handle delete
  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/patients/${id}`, {
        method: 'DELETE'
      });

      if (!response.ok) throw new Error('Failed to delete patient');

      setPatients(prev => prev.filter(p => p.id !== id));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  // Start editing
  const startEditing = (patient: Patient) => {
    setFormData({ name: patient.name, phone: patient.phone, email: patient.email });
    setEditingId(patient.id);
  };

  // Filter patients based on search term
  const filteredPatients = patients.filter(patient => 
    patient.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    patient.phone.includes(searchTerm)
  );

  // Styles
  const containerStyle: React.CSSProperties = {
    maxWidth: '800px',
    margin: '0 auto',
    padding: '20px',
    fontFamily: 'system-ui, sans-serif'
  };

  const formStyle: React.CSSProperties = {
    display: 'flex',
    flexDirection: 'column',
    gap: '10px',
    marginBottom: '20px',
    padding: '15px',
    border: '1px solid #ccc',
    borderRadius: '5px'
  };

  const inputStyle: React.CSSProperties = {
    padding: '8px',
    borderRadius: '4px',
    border: '1px solid #ddd',
    width: '100%',
    boxSizing: 'border-box'
  };

  const buttonStyle: React.CSSProperties = {
    padding: '8px 12px',
    backgroundColor: '#007bff',
    color: 'white',
    border: 'none',
    borderRadius: '4px',
    cursor: 'pointer'
  };

  const listStyle: React.CSSProperties = {
    display: 'flex',
    flexWrap: 'wrap',
    gap: '10px'
  };

  const cardStyle: React.CSSProperties = {
    border: '1px solid #ddd',
    borderRadius: '5px',
    padding: '15px',
    width: '100%',
    maxWidth: '300px'
  };

  const buttonGroupStyle: React.CSSProperties = {
    display: 'flex',
    gap: '5px',
    marginTop: '10px'
  };

  if (loading) return <div style={containerStyle}>Loading...</div>;
  if (error) return <div style={containerStyle}>Error: {error}</div>;

  return (
    <div style={containerStyle}>
      <h1>Patient Management</h1>

      <form onSubmit={editingId ? handleUpdate : handleSubmit} style={formStyle}>
        <input
          type="text"
          name="name"
          placeholder="Name"
          value={formData.name}
          onChange={handleInputChange}
          style={inputStyle}
        />
        <input
          type="text"
          name="phone"
          placeholder="Phone"
          value={formData.phone}
          onChange={handleInputChange}
          style={inputStyle}
        />
        <input
          type="email"
          name="email"
          placeholder="Email"
          value={formData.email}
          onChange={handleInputChange}
          style={inputStyle}
        />
        <button type="submit" style={buttonStyle}>
          {editingId ? 'Update Patient' : 'Add Patient'}
        </button>
      </form>

      <input
        type="text"
        placeholder="Search by name or phone"
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
        style={inputStyle}
      />

      <div style={listStyle}>
        {filteredPatients.length === 0 ? (
          <p>No patients found.</p>
        ) : (
          filteredPatients.map(patient => (
            <div key={patient.id} style={cardStyle}>
              <h3>{patient.name}</h3>
              <p>Phone: {patient.phone}</p>
              <p>Email: {patient.email}</p>
              <div style={buttonGroupStyle}>
                <button onClick={() => startEditing(patient)} style={buttonStyle}>Edit</button>
                <button onClick={() => handleDelete(patient.id)} style={{...buttonStyle, backgroundColor: '#dc3545'}}>Delete</button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply authorization checks to protected routes
  if (!(req.method === "POST" || req.method === "PUT" || req.method === "DELETE") &&
      !req.path.startsWith("/api/bills") &&
      !req.path.startsWith("/api/usage")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT secret not configured" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify JWT properly
  const expectedToken = createHmac("sha256", secret)
    .update(req.method + req.path + Date.now())
    .digest("hex");

  const expectedBuffer = Buffer.from(expectedToken);
  const providedBuffer = Buffer.from(token);

  try {
    if (timingSafeEqual(expectedBuffer, providedBuffer)) {
      next();
    } else {
      res.status(401).json({ error: "Unauthorized: Invalid token" });
    }
  } catch {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}
"}

