{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  const token = req.body.token;
  if (!token) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Basic token structure validation
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const [header, payload, signature] = parts;

  // Verify signature
  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  const signatureBuffer = Buffer.from(signature, "base64url");
  const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

  try {
    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Decode payload (basic base64url decoding)
  const decodedPayload = Buffer.from(payload, "base64url").toString("utf8");
  let payloadObj;
  try {
    payloadObj = JSON.parse(decodedPayload);
  } catch {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Assign role based on payload
  if (payloadObj.role === "admin") {
    (req as any).role = "admin";
  } else if (payloadObj.role === "client") {
    (req as any).role = "client";
  } else {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  next();
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "./laundromat.db"
);

interface MachineReport {
  id: number;
  member_id: number;
  machine_id: number;
  report_text: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS machine_reports (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    member_id INTEGER NOT NULL,
    machine_id INTEGER NOT NULL,
    report_text TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllMachineReports(): MachineReport[] {
  const stmt = db.prepare(
    "SELECT * FROM machine_reports ORDER BY id"
  );
  return stmt.all() as unknown as MachineReport[];
}

export function getMachineReportById(id: number): MachineReport | undefined {
  const stmt = db.prepare(
    "SELECT * FROM machine_reports WHERE id = ?"
  );
  return stmt.get(id) as unknown as MachineReport | undefined;
}

export function insertMachineReport(
  member_id: number,
  machine_id: number,
  report_text: string
): number {
  const stmt = db.prepare(
    "INSERT INTO machine_reports (member_id, machine_id, report_text) VALUES (?, ?, ?)"
  );
  const result = stmt.run(member_id, machine_id, report_text);
  return Number(result.lastInsertRowid);
}

export function updateMachineReport(
  id: number,
  member_id: number,
  machine_id: number,
  report_text: string
): number {
  const stmt = db.prepare(
    "UPDATE machine_reports SET member_id = ?, machine_id = ?, report_text = ? WHERE id = ?"
  );
  const result = stmt.run(member_id, machine_id, report_text, id);
  return Number(result.changes);
}

export function deleteMachineReport(id: number): number {
  const stmt = db.prepare(
    "DELETE FROM machine_reports WHERE id = ?"
  );
  const result = stmt.run(id);
  return Number(result.changes);
}

