{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to the export endpoint
  if (req.method !== "POST" || req.path !== "/export") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify properly
  const expectedToken = createHmac("sha256", secret).update("owner-export-token").digest("hex");

  try {
    const tokenBuffer = Buffer.from(token, "hex");
    const expectedBuffer = Buffer.from(expectedToken, "hex");

    if (tokenBuffer.length !== expectedBuffer.length || !timingSafeEqual(tokenBuffer, expectedBuffer)) {
      res.status(403).json({ error: "Forbidden" });
      return;
    }
  } catch (err) {
    res.status(403).json({ error: "Forbidden" });
    return;
  }

  next();
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("hotel-housekeeping.db");

interface ReassignmentRow {
  id: number;
  supervisor_id: number;
  source_housekeeper_id: number;
  target_housekeeper_id: number;
  room_id: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS reassignments (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    supervisor_id INTEGER NOT NULL,
    source_housekeeper_id INTEGER NOT NULL,
    target_housekeeper_id INTEGER NOT NULL,
    room_id INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllReassignments(): ReassignmentRow[] {
  const stmt = db.prepare("SELECT * FROM reassignments");
  return stmt.all() as unknown as ReassignmentRow[];
}

export function getReassignmentById(id: number): ReassignmentRow | undefined {
  const stmt = db.prepare("SELECT * FROM reassignments WHERE id = ?");
  return stmt.get(id) as unknown as ReassignmentRow | undefined;
}

export function insertReassignment(
  supervisorId: number,
  sourceHousekeeperId: number,
  targetHousekeeperId: number,
  roomId: number
): number {
  const stmt = db.prepare(
    "INSERT INTO reassignments (supervisor_id, source_housekeeper_id, target_housekeeper_id, room_id) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(supervisorId, sourceHousekeeperId, targetHousekeeperId, roomId);
  return Number(result.lastInsertRowid);
}

export function updateReassignment(
  id: number,
  supervisorId: number,
  sourceHousekeeperId: number,
  targetHousekeeperId: number,
  roomId: number
): void {
  const stmt = db.prepare(
    "UPDATE reassignments SET supervisor_id = ?, source_housekeeper_id = ?, target_housekeeper_id = ?, room_id = ? WHERE id = ?"
  );
  stmt.run(supervisorId, sourceHousekeeperId, targetHousekeeperId, roomId, id);
}

export function deleteReassignment(id: number): void {
  const stmt = db.prepare("DELETE FROM reassignments WHERE id = ?");
  stmt.run(id);
}

// Sample data insertion
if (getAllReassignments().length === 0) {
  insertReassignment(1, 101, 102, 201);
  insertReassignment(1, 103, 104, 202);
  insertReassignment(2, 105, 106, 203);
  insertReassignment(2, 107, 108, 204);
  insertReassignment(1, 109, 110, 205);
}
"}

