{"code":"import { Router, type Request, type Response } from "express";
import { getAllComplaints, getComplaintById, updateAuditLog } from "../db/complaints-table";

export const router = Router();

router.get("/", (req: Request, res: Response) => {
  const complaints = getAllComplaints().map(complaint => ({
    id: complaint.id,
    metadata: complaint.metadata
  }));
  res.json(complaints);
});

router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const complaint = getComplaintById(id);
  if (complaint) {
    res.json({
      id: complaint.id,
      metadata: complaint.metadata
    });
  } else {
    res.status(404).send("Complaint not found");
  }
});

router.post("/:id/audit", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const auditLogEntry = req.body.auditLog;
  if (typeof auditLogEntry === "string") {
    updateAuditLog(id, auditLogEntry);
    res.status(200).send("Audit log updated");
  } else {
    res.status(400).send("Invalid audit log entry");
  }
});
"}

{"code":"import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check DELETE requests
  if (req.method !== "DELETE") {
    next();
    return;
  }

  // Check if the request is for a channel deletion endpoint
  // Assuming the path pattern is /channels/:channelId/messages/:messageId
  const pathParts = req.path.split("/");
  const isChannelDeletion = pathParts.length >= 5 && pathParts[1] === "channels" && pathParts[3] === "messages";

  if (!isChannelDeletion) {
    next();
    return;
  }

  // For demonstration purposes, we assume admin status is passed via a custom property
  // In a real implementation, this would involve actual authentication and role checking
  const isAdmin = (req as any).user?.isAdmin ?? false;

  if (!isAdmin) {
    res.status(403).json({ error: "Admin access required to delete messages" });
    return;
  }

  next();
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface ExportRecord {
  id: number;
  userId: number;
  exportDate: string;
  fileName: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS export_records (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    userId INTEGER NOT NULL,
    exportDate TEXT NOT NULL,
    fileName TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllExportRecords(): ExportRecord[] {
  const stmt = db.prepare(`
    SELECT id, userId, exportDate, fileName 
    FROM export_records 
    ORDER BY exportDate DESC
  `);
  return stmt.all() as unknown as ExportRecord[];
}

export function getExportRecordById(id: number): ExportRecord | undefined {
  const stmt = db.prepare(`
    SELECT id, userId, exportDate, fileName 
    FROM export_records 
    WHERE id = ?
  `);
  return stmt.get(id) as unknown as ExportRecord | undefined;
}

export function insertExportRecord(
  userId: number,
  exportDate: string,
  fileName: string
): number {
  const stmt = db.prepare(`
    INSERT INTO export_records (userId, exportDate, fileName)
    VALUES (?, ?, ?)
  `);
  const result = stmt.run(userId, exportDate, fileName);
  return Number(result.lastInsertRowid);
}

export function updateExportRecord(
  id: number,
  userId: number,
  exportDate: string,
  fileName: string
): number {
  const stmt = db.prepare(`
    UPDATE export_records 
    SET userId = ?, exportDate = ?, fileName = ?
    WHERE id = ?
  `);
  const result = stmt.run(userId, exportDate, fileName, id);
  return Number(result.changes);
}

export function deleteExportRecord(id: number): number {
  const stmt = db.prepare(`
    DELETE FROM export_records 
    WHERE id = ?
  `);
  const result = stmt.run(id);
  return Number(result.changes);
}

// Insert sample data if table is empty
if (getAllExportRecords().length === 0) {
  insertExportRecord(1, "2023-05-15", "inventory_export_20230515.csv");
  insertExportRecord(2, "2023-05-16", "inventory_export_20230516.csv");
  insertExportRecord(1, "2023-05-17", "inventory_export_20230517.csv");
  insertExportRecord(3, "2023-05-18", "inventory_export_20230518.csv");
  insertExportRecord(2, "2023-05-19", "inventory_export_20230519.csv");
}
"}

