export const db = new DatabaseSync("./hostel.db");

interface BookingRow {
  id: number;
  guest_id: number;
  room_id: number;
  check_in_date: string;
  check_out_date: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS bookings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    guest_id INTEGER NOT NULL,
    room_id INTEGER NOT NULL,
    check_in_date TEXT NOT NULL,
    check_out_date TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllBookings(): BookingRow[] {
  const stmt = db.prepare("SELECT * FROM bookings");
  return stmt.all() as unknown as BookingRow[];
}

export function getBookingById(id: number): BookingRow | undefined {
  const stmt = db.prepare("SELECT * FROM bookings WHERE id = ?");
  return stmt.get(id) as unknown as BookingRow | undefined;
}

export function insertBooking(
  guestId: number,
  roomId: number,
  checkInDate: string,
  checkOutDate: string
): number {
  const stmt = db.prepare(
    "INSERT INTO bookings (guest_id, room_id, check_in_date, check_out_date) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(guestId, roomId, checkInDate, checkOutDate);
  return Number(result.lastInsertRowid);
}

export function updateBooking(
  id: number,
  guestId: number,
  roomId: number,
  checkInDate: string,
  checkOutDate: string
): void {
  const stmt = db.prepare(
    "UPDATE bookings SET guest_id = ?, room_id = ?, check_in_date = ?, check_out_date = ? WHERE id = ?"
  );
  stmt.run(guestId, roomId, checkInDate, checkOutDate, id);
}

export function deleteBooking(id: number): void {
  const stmt = db.prepare("DELETE FROM bookings WHERE id = ?");
  stmt.run(id);
}

