{"code":"import { useEffect, useState } from "react";

interface Booking {
  id: string;
  date: string;
  time: string;
  groundName: string;
  status: "confirmed" | "cancelled";
}

export function BookingDashboard() {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchBookings();
  }, []);

  const fetchBookings = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/bookings/upcoming");
      if (!response.ok) {
        throw new Error(`Failed to fetch bookings: ${response.status}`);
      }
      const data = await response.json();
      setBookings(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = async (id: string) => {
    try {
      const response = await fetch(`/api/bookings/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`Failed to cancel booking: ${response.status}`);
      }
      // Refresh the list after cancellation
      fetchBookings();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (bookings.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        You have no upcoming bookings.
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Your Upcoming Bookings</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {bookings.map((booking) => (
          <div
            key={booking.id}
            style={{
              border: "1px solid #ddd",
              borderRadius: "8px",
              padding: "15px",
              backgroundColor: "#f9f9f9",
            }}
          >
            <div style={{ display: "flex", justifyContent: "space-between" }}>
              <div>
                <h3>{booking.groundName}</h3>
                <p>Date: {booking.date}</p>
                <p>Time: {booking.time}</p>
                <p>Status: {booking.status}</p>
              </div>
              <button
                onClick={() => handleCancel(booking.id)}
                style={{
                  backgroundColor: "#ff4d4d",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  padding: "8px 12px",
                  cursor: "pointer",
                }}
              >
                Cancel
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import { db, deleteContract, getAllContracts, getContractById, insertContract, updateContract } from "../db/contracts-table";

export const router = Router();

// Get all contracts
router.get("/", (req: Request, res: Response) => {
  const contracts = getAllContracts();
  res.json(contracts);
});

// Get contract by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid contract ID" });
  }

  const contract = getContractById(id);

  if (!contract) {
    return res.status(404).json({ error: "Contract not found" });
  }

  res.json(contract);
});

// Create new contract
router.post("/", (req: Request, res: Response) => {
  const { text, freelancerId, signingDate } = req.body;

  if (!text || !freelancerId || !signingDate) {
    return res.status(400).json({ error: "Missing required fields: text, freelancerId, signingDate" });
  }

  const id = insertContract(text, freelancerId, signingDate);

  // Fetch the created contract to send back
  const contract = getContractById(id);

  if (!contract) {
    return res.status(500).json({ error: "Failed to retrieve created contract" });
  }

  res.status(201).json(contract);
});

// Update existing contract
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { text, freelancerId, signingDate } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid contract ID" });
  }

  if (!text || !freelancerId || !signingDate) {
    return res.status(400).json({ error: "Missing required fields: text, freelancerId, signingDate" });
  }

  const existingContract = getContractById(id);

  if (!existingContract) {
    return res.status(404).json({ error: "Contract not found" });
  }

  updateContract(id, text, freelancerId, signingDate);

  // Fetch the updated contract to send back
  const updatedContract = getContractById(id);

  if (!updatedContract) {
    return res.status(500).json({ error: "Failed to retrieve updated contract" });
  }

  res.json(updatedContract);
});

// Delete contract
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid contract ID" });
  }

  const existingContract = getContractById(id);

  if (!existingContract) {
    return res.status(404).json({ error: "Contract not found" });
  }

  deleteContract(id);

  res.json({ message: "Contract deleted successfully" });
});
"}

