export const db = new DatabaseSync(
  "/tmp/dog-park-membership.db"
);

interface Checkin {
  id: number;
  memberId: number;
  dogName: string;
  checkInTimestamp: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS checkins (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    memberId INTEGER NOT NULL,
    dogName TEXT NOT NULL,
    checkInTimestamp TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllCheckins(): Checkin[] {
  const stmt = db.prepare(`SELECT * FROM checkins`);
  return stmt.all() as unknown as Checkin[];
}

export function getCheckinById(id: number): Checkin | undefined {
  const stmt = db.prepare(
    `SELECT * FROM checkins WHERE id = ?`
  );
  return stmt.get(id) as unknown as Checkin | undefined;
}

export function insertCheckin(
  memberId: number,
  dogName: string,
  checkInTimestamp: string
): number {
  const stmt = db.prepare(
    `INSERT INTO checkins (memberId, dogName, checkInTimestamp) VALUES (?, ?, ?)`
  );
  const result = stmt.run(memberId, dogName, checkInTimestamp);
  return Number(result.lastInsertRowid);
}

export function updateCheckin(
  id: number,
  memberId: number,
  dogName: string,
  checkInTimestamp: string
): void {
  const stmt = db.prepare(
    `UPDATE checkins SET memberId = ?, dogName = ?, checkInTimestamp = ? WHERE id = ?`
  );
  stmt.run(memberId, dogName, checkInTimestamp, id);
}

export function deleteCheckin(id: number): void {
  const stmt = db.prepare(`DELETE FROM checkins WHERE id = ?`);
  stmt.run(id);
}

