{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data structures to simulate database operations
const attendanceRecords = [
  { id: 1, studentId: 101, date: "2023-05-01", status: "present" },
  { id: 2, studentId: 102, date: "2023-05-01", status: "absent" },
  { id: 3, studentId: 103, date: "2023-05-02", status: "late" }
];

let nextId = 4;

// GET /api/attendance - Get all attendance records
router.get("/", (req: Request, res: Response) => {
  res.json(attendanceRecords);
});

// GET /api/attendance/:id - Get a specific attendance record by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const record = attendanceRecords.find(r => r.id === id);

  if (!record) {
    return res.status(404).json({ error: "Attendance record not found" });
  }

  res.json(record);
});

// POST /api/attendance - Create a new attendance record
router.post("/", (req: Request, res: Response) => {
  const { studentId, date, status } = req.body;

  if (!studentId || !date || !status) {
    return res.status(400).json({ error: "Student ID, date, and status are required" });
  }

  const newRecord = {
    id: nextId++,
    studentId,
    date,
    status
  };

  attendanceRecords.push(newRecord);
  res.status(201).json(newRecord);
});

// PUT /api/attendance/:id - Update an existing attendance record
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const recordIndex = attendanceRecords.findIndex(r => r.id === id);

  if (recordIndex === -1) {
    return res.status(404).json({ error: "Attendance record not found" });
  }

  const { studentId, date, status } = req.body;

  // Build updates object with only provided fields
  const updates: Partial<{ studentId: number; date: string; status: string }> = {};

  if (studentId !== undefined) updates.studentId = studentId;
  if (date !== undefined) updates.date = date;
  if (status !== undefined) updates.status = status;

  // Apply updates to the record
  Object.assign(attendanceRecords[recordIndex], updates);

  res.json(attendanceRecords[recordIndex]);
});

// DELETE /api/attendance/:id - Delete an attendance record
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const recordIndex = attendanceRecords.findIndex(r => r.id === id);

  if (recordIndex === -1) {
    return res.status(404).json({ error: "Attendance record not found" });
  }

  attendanceRecords.splice(recordIndex, 1);
  res.json({ message: "Attendance record deleted successfully" });
});

// GET /api/attendance/report - Generate attendance report
router.get("/report", (req: Request, res: Response) => {
  // Simple report generation - count by status
  const report = attendanceRecords.reduce((acc, record) => {
    acc[record.status] = (acc[record.status] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  res.json(report);
});
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // In a real implementation, we would verify JWT signature here
  // For now, we'll just check if the request has proper headers
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Simulate token verification - in reality this would verify HMAC-SHA256 signature
  try {
    // This is a simplified mock - in practice, you'd decode and verify the JWT
    const expectedToken = createHmac("sha256", secret)
      .update("mocked-user-token")
      .digest("hex");

    // Mock timing-safe comparison
    const tokenBuffer = Buffer.from(token);
    const expectedBuffer = Buffer.from(expectedToken);

    if (tokenBuffer.length !== expectedBuffer.length) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    // This is a simplified check - in real implementation:
    // const isEqual = timingSafeEqual(tokenBuffer, expectedBuffer);
    // if (!isEqual) { ... }

    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized" });
  }
}
"}

{"code":"import { useEffect, useState } from "react";

interface Shift {
  id: string;
  title: string;
  description: string;
  startTime: string;
  endTime: string;
  claimedBy?: string;
}

interface BoardOwnership {
  id: string;
  shiftId: string;
  memberId: string;
}

export function ShiftClaimBoard() {
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [memberId, setMemberId] = useState("");

  useEffect(() => {
    fetchShifts();
  }, []);

  const fetchShifts = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/shifts-api/shifts');
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setShifts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleClaimShift = async (shiftId: string) => {
    if (!memberId.trim()) {
      setError("Please enter your member ID to claim a shift.");
      return;
    }

    try {
      const response = await fetch(`/api/shifts-api/shifts/${shiftId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ claimedBy: memberId }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      // Refresh the shifts list after claiming
      await fetchShifts();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  if (error) {
    return <div>Error: {error}</div>;
  }

  const gridStyle: React.CSSProperties = {
    display: 'flex',
    flexWrap: 'wrap',
    gap: '1rem',
    justifyContent: 'center',
  };

  const cardStyle: React.CSSProperties = {
    border: '1px solid #ccc',
    borderRadius: '8px',
    padding: '1rem',
    width: '300px',
    boxSizing: 'border-box',
    backgroundColor: '#f9f9f9',
  };

  const buttonStyle: React.CSSProperties = {
    backgroundColor: '#4CAF50',
    color: 'white',
    border: 'none',
    padding: '0.5rem 1rem',
    borderRadius: '4px',
    cursor: 'pointer',
    marginTop: '0.5rem',
  };

  const inputStyle: React.CSSProperties = {
    width: '100%',
    padding: '0.5rem',
    marginBottom: '1rem',
    boxSizing: 'border-box',
  };

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', fontFamily: 'system-ui, sans-serif', padding: '1rem' }}>
      <h1>Shift Claim Board</h1>
      <p>Claim an open shift below:</p>

      <input
        type="text"
        placeholder="Enter your Member ID"
        value={memberId}
        onChange={(e) => setMemberId(e.target.value)}
        style={inputStyle}
      />

      {shifts.length === 0 ? (
        <p>No open shifts available.</p>
      ) : (
        <div style={gridStyle}>
          {shifts
            .filter(shift => !shift.claimedBy)
            .map(shift => (
              <div key={shift.id} style={cardStyle}>
                <h3>{shift.title}</h3>
                <p>{shift.description}</p>
                <p><strong>Start:</strong> {new Date(shift.startTime).toLocaleString()}</p>
                <p><strong>End:</strong> {new Date(shift.endTime).toLocaleString()}</p>
                <button onClick={() => handleClaimShift(shift.id)} style={buttonStyle}>Claim Shift</button>
              </div>
            ))}
        </div>
      )}
    </div>
  );
}
"}

