{"code":"import { useEffect, useState } from "react";

interface Lead {
  id: number;
  name: string;
  email: string;
  phone: string;
  status: "new" | "contacted" | "qualified" | "lost";
  createdAt: string;
}

export function LeadsPage() {
  const [leads, setLeads] = useState<Lead[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState<Lead["status"] | "all">("all");

  useEffect(() => {
    fetchLeads();
  }, []);

  const fetchLeads = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/leads`);
      if (!response.ok) {
        throw new Error(`Failed to fetch leads: ${response.status}`);
      }
      const data = await response.json();
      setLeads(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const filteredLeads = leads.filter(lead => {
    const matchesSearch = 
      lead.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      lead.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
      lead.phone.includes(searchTerm);

    const matchesStatus = statusFilter === "all" || lead.status === statusFilter;

    return matchesSearch && matchesStatus;
  });

  const handleStatusChange = async (id: number, newStatus: Lead["status"]) => {
    try {
      const response = await fetch(`/api/leads/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: newStatus }),
      });

      if (!response.ok) {
        throw new Error(`Failed to update lead: ${response.status}`);
      }

      // Refresh the leads list
      await fetchLeads();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const getStatusColor = (status: Lead["status"]) => {
    switch (status) {
      case "new": return "#3b82f6"; // blue-500
      case "contacted": return "#10b981"; // emerald-500
      case "qualified": return "#8b5cf6"; // violet-500
      case "lost": return "#ef4444"; // red-500
      default: return "#6b7280"; // gray-500
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "1200px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center", marginBottom: "30px" }}>Solar Panel Installation Leads</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search by name, email, or phone..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        />

        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value as Lead["status"] | "all")}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="all">All Statuses</option>
          <option value="new">New</option>
          <option value="contacted">Contacted</option>
          <option value="qualified">Qualified</option>
          <option value="lost">Lost</option>
        </select>
      </div>

      {filteredLeads.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No leads found.</p>
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(300px, 1fr))", gap: "20px" }}>
          {filteredLeads.map(lead => (
            <div key={lead.id} style={{ border: "1px solid #ddd", borderRadius: "8px", padding: "15px", backgroundColor: "#f9fafb" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "start" }}>
                <div>
                  <h3 style={{ margin: "0 0 5px 0", fontSize: "1.1em" }}>{lead.name}</h3>
                  <p style={{ margin: "0 0 5px 0", color: "#6b7280" }}>{lead.email}</p>
                  <p style={{ margin: "0 0 5px 0", color: "#6b7280" }}>{lead.phone}</p>
                </div>
                <span style={{ backgroundColor: getStatusColor(lead.status), color: "white", padding: "4px 8px", borderRadius: "4px", fontSize: "0.8em" }}>
                  {lead.status.charAt(0).toUpperCase() + lead.status.slice(1)}
                </span>
              </div>

              <div style={{ marginTop: "10px", display: "flex", flexWrap: "wrap", gap: "5px" }}>
                <button
                  onClick={() => handleStatusChange(lead.id, "contacted")}
                  disabled={lead.status === "contacted"}
                  style={{ 
                    backgroundColor: lead.status === "contacted" ? "#9ca3af" : "#3b82f6", 
                    color: "white", 
                    border: "none", 
                    padding: "5px 10px", 
                    borderRadius: "4px", 
                    cursor: "pointer", 
                    fontSize: "0.8em",
                    opacity: lead.status === "contacted" ? 0.6 : 1
                  }}
                >
                  Contacted
                </button>

                <button
                  onClick={() => handleStatusChange(lead.id, "qualified")}
                  disabled={lead.status === "qualified"}
                  style={{ 
                    backgroundColor: lead.status === "qualified" ? "#9ca3af" : "#10b981", 
                    color: "white", 
                    border: "none", 
                    padding: "5px 10px", 
                    borderRadius: "4px", 
                    cursor: "pointer", 
                    fontSize: "0.8em",
                    opacity: lead.status === "qualified" ? 0.6 : 1
                  }}
                >
                  Qualified
                </button>

                <button
                  onClick={() => handleStatusChange(lead.id, "lost")}
                  disabled={lead.status === "lost"}
                  style={{ 
                    backgroundColor: lead.status === "lost" ? "#9ca3af" : "#ef4444", 
                    color: "white", 
                    border: "none", 
                    padding: "5px 10px", 
                    borderRadius: "4px", 
                    cursor: "pointer", 
                    fontSize: "0.8em",
                    opacity: lead.status === "lost" ? 0.6 : 1
                  }}
                >
                  Lost
                </button>
              </div>

              <p style={{ marginTop: "10px", fontSize: "0.8em", color: "#6b7280" }}>
                Created: {new Date(lead.createdAt).toLocaleDateString()}
              </p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

