export const router = Router();

// Mock in-memory storage for paper statuses
let paperStatuses: { id: string; status: string }[] = [];
let nextId = 1;

// GET /status - List all paper statuses
router.get("/", (req: Request, res: Response) => {
  res.json(paperStatuses);
});

// GET /status/:id - Get a specific paper status by ID
router.get("/status/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const paperStatus = paperStatuses.find((ps) => ps.id === id);

  if (!paperStatus) {
    return res.status(404).json({ error: "Paper status not found" });
  }

  res.json(paperStatus);
});

// POST /status - Create a new paper status
router.post("/status", (req: Request, res: Response) => {
  const { status } = req.body;

  if (!status) {
    return res.status(400).json({ error: "Status is required" });
  }

  const newPaperStatus = {
    id: nextId.toString(),
    status
  };

  paperStatuses.push(newPaperStatus);
  nextId++;

  res.status(201).json(newPaperStatus);
});

// PUT /status/:id - Update a paper status by ID
router.put("/status/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const { status } = req.body;

  const paperStatusIndex = paperStatuses.findIndex((ps) => ps.id === id);

  if (paperStatusIndex === -1) {
    return res.status(404).json({ error: "Paper status not found" });
  }

  if (!status) {
    return res.status(400).json({ error: "Status is required" });
  }

  paperStatuses[paperStatusIndex].status = status;

  res.json(paperStatuses[paperStatusIndex]);
});

// DELETE /status/:id - Delete a paper status by ID
router.delete("/status/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const paperStatusIndex = paperStatuses.findIndex((ps) => ps.id === id);

  if (paperStatusIndex === -1) {
    return res.status(404).json({ error: "Paper status not found" });
  }

  paperStatuses.splice(paperStatusIndex, 1);

  res.json({ message: "Paper status deleted successfully" });
});
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to work order related routes
  if (!req.path.startsWith('/work-orders')) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers['x-user-role'] as string | undefined;

  // For demonstration purposes, we'll assume these roles exist:
  // 'admin', 'manager', 'technician', 'viewer'

  // Define role requirements per endpoint
  const roleRequirements: Record<string, string[]> = {
    '/work-orders': ['admin', 'manager'],
    '/work-orders/:id': ['admin', 'manager', 'technician'],
    '/work-orders/:id/status': ['admin', 'manager', 'technician'],
    '/work-orders/:id/assign': ['admin', 'manager'],
  };

  // Get the specific endpoint path
  let endpointPath = req.path;

  // Handle dynamic paths by normalizing them
  if (req.params.id) {
    endpointPath = req.path.replace(/\/[^\/]+$/, '/:id');
  }

  const requiredRoles = roleRequirements[endpointPath] || [];

  // If no roles are required, allow access
  if (requiredRoles.length === 0) {
    next();
    return;
  }

  // If no role provided, deny access
  if (!userRole) {
    res.status(403).json({ error: 'Access denied: role required' });
    return;
  }

  // Check if user has sufficient role
  if (!requiredRoles.includes(userRole)) {
    res.status(403).json({ error: 'Access denied: insufficient permissions' });
    return;
  }

  // User has proper role, proceed
  next();
}
"}

