{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("help-requests.db");

interface HelpRequest {
  id: number;
  title: string;
  description: string;
  category: string;
  location: string;
  urgency: string;
  status: string;
  created_at: string;
  updated_at: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS help_requests (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    description TEXT NOT NULL,
    category TEXT NOT NULL,
    location TEXT NOT NULL,
    urgency TEXT NOT NULL,
    status TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllHelpRequests(): HelpRequest[] {
  const stmt = db.prepare(`SELECT * FROM help_requests`);
  return stmt.all() as unknown as HelpRequest[];
}

export function getHelpRequestById(id: number): HelpRequest | undefined {
  const stmt = db.prepare(`SELECT * FROM help_requests WHERE id = ?`);
  return stmt.get(id) as unknown as HelpRequest | undefined;
}

export function createHelpRequest(
  title: string,
  description: string,
  category: string,
  location: string,
  urgency: string,
  status: string,
  created_at: string,
  updated_at: string
): number {
  const stmt = db.prepare(
    `INSERT INTO help_requests (title, description, category, location, urgency, status, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
  );
  const result = stmt.run(title, description, category, location, urgency, status, created_at, updated_at);
  return Number(result.lastInsertRowid);
