{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteReservation,
  getAllReservations,
  getReservationById,
  insertReservation,
  updateReservation
} from "../db/reservations-table";

export const router = Router();

// Get all reservations
router.get("/", (req: Request, res: Response) => {
  try {
    const reservations = getAllReservations();
    res.json(reservations);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reservations" });
  }
});

// Get a reservation by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const reservation = getReservationById(id);
    if (!reservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    res.json(reservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reservation" });
  }
});

// Create a new reservation
router.post("/", (req: Request, res: Response) => {
  try {
    const { vendorId, stallNumber, reservedWeekendDate } = req.body;

    if (!vendorId || !stallNumber || !reservedWeekendDate) {
      return res.status(400).json({
        error: "Missing required fields: vendorId, stallNumber, reservedWeekendDate"
      });
    }

    const newId = insertReservation(
      Number(vendorId),
      Number(stallNumber),
      reservedWeekendDate
    );

    const newReservation = getReservationById(newId);
    res.status(201).json(newReservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to create reservation" });
  }
});

// Update a reservation
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const { vendorId, stallNumber, reservedWeekendDate } = req.body;

    if (!vendorId || !stallNumber || !reservedWeekendDate) {
      return res.status(400).json({
        error: "Missing required fields: vendorId, stallNumber, reservedWeekendDate"
      });
    }

    const existingReservation = getReservationById(id);
    if (!existingReservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    updateReservation(
      id,
      Number(vendorId),
      Number(stallNumber),
      reservedWeekendDate
    );

    const updatedReservation = getReservationById(id);
    res.json(updatedReservation);
  } catch (error) {
    res.status(500).json({ error: "Failed to update reservation" });
  }
});

// Delete a reservation
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reservation ID" });
    }

    const existingReservation = getReservationById(id);
    if (!existingReservation) {
      return res.status(404).json({ error: "Reservation not found" });
    }

    deleteReservation(id);
    res.json({ message: "Reservation deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete reservation" });
  }
});
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("helpdesk.db");

interface Ticket {
  id: number;
  title: string;
  description: string;
  channel: string;
  status: string;
  created_at: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS tickets (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    description TEXT NOT NULL,
    channel TEXT NOT NULL,
    status TEXT NOT NULL,
    created_at TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllTickets(): Ticket[] {
  const stmt = db.prepare("SELECT * FROM tickets");
  return stmt.all() as unknown as Ticket[];
}

export function getTicketById(id: number): Ticket | undefined {
  const stmt = db.prepare("SELECT * FROM tickets WHERE id = ?");
  return stmt.get(id) as unknown as Ticket | undefined;
}

export function createTicket(ticket: Omit<Ticket, "id" | "created_at">): number {
  const stmt = db.prepare(
    "INSERT INTO tickets (title, description, channel, status, created_at) VALUES (?, ?, ?, ?, ?)"
  );
  const result = stmt.run(
    ticket.title,
    ticket.description,
    ticket.channel,
    ticket.status,
    new Date().toISOString()
  );
  return Number(result.lastInsertRowid);
}

export function updateTicket(id: number, ticket: Partial<Omit<Ticket, "id" | "created_at">>): boolean {
  const fields = [];
  const values = [];

  if (ticket.title !== undefined) {
    fields.push("title = ?");
    values.push(ticket.title);
  }

  if (ticket.description !== undefined) {
    fields.push("description = ?");
    values.push(ticket.description);
  }

  if (ticket.channel !== undefined) {
    fields.push("channel = ?");
    values.push(ticket.channel);
  }

  if (ticket.status !== undefined) {
    fields.push("status = ?");
    values.push(ticket.status);
  }

  if (fields.length === 0) {
    return false;
  }

  values.push(id);

  const stmt = db.prepare(`UPDATE tickets SET ${fields.join(", ")} WHERE id = ?`);
  const result = stmt.run(...values);

  return result.changes > 0;
}

export function deleteTicket(id: number): boolean {
  const stmt = db.prepare("DELETE FROM tickets WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

// Seed data
if (getAllTickets().length === 0) {
  createTicket({
    title: "Login Issue",
    description: "User unable to login to the system",
    channel: "email",
    status: "open"
  });

  createTicket({
    title: "Payment Failure",
    description: "Credit card payment not processing",
    channel: "phone",
    status: "in_progress"
  });

  createTicket({
    title: "Feature Request",
    description: "Request for new dashboard feature",
    channel: "web_form",
    status: "closed"
  });

  createTicket({
    title: "Account Lockout",
    description: "Multiple failed login attempts",
    channel: "chat",
    status: "open"
  });

  createTicket({
    title: "Data Export Error",
    description: "Exporting reports fails with timeout",
    channel: "email",
    status: "in_progress"
  });
}
