router.get("/recipes", (req: Request, res: Response) => {
  try {
    const recipes = getAllRecipes();
    res.json(recipes);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch recipes" });
  }
});

// Get one recipe by ID
router.get("/recipes/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid recipe ID" });
    }

    const recipe = getRecipeById(id);
    if (!recipe) {
      return res.status(404).json({ error: "Recipe not found" });
    }

    res.json(recipe);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch recipe" });
  }
});

// Create a new recipe
router.post("/recipes", (req: Request, res: Response) => {
  try {
    const { title, description, prep_time, cook_time } = req.body;

    if (!title || !description || prep_time === undefined || cook_time === undefined) {
      return res.status(400).json({ error: "Missing required fields: title, description, prep_time, cook_time" });
    }

    const id = insertRecipe(title, description, prep_time, cook_time);
    const newRecipe = getRecipeById(id);

    if (!newRecipe) {
      return res.status(500).json({ error: "Failed to create recipe" });
    }

    res.status(201).json(newRecipe);
  } catch (error) {
    res.status(500).json({ error: "Failed to create recipe" });
  }
});

