  const id = Number(req.params.id);
  const registration = campRegistrations.find(r => r.id === id);

  if (!registration) {
    return res.status(404).json({ error: "Camp registration not found" });
  }

  res.json(registration);
});

// POST /api/camp-registrations - Create a new camp registration
