  const { name, email, bloodType, donationDate } = req.body;

  // Basic validation
  if (!name || !email || !bloodType || !donationDate) {
    return res.status(400).json({ error: "Name, email, blood type, and donation date are required" });
  }

  const newRegistration = {
    id: nextId++,
    name,
    email,
    bloodType,
    donationDate
  };

  campRegistrations.push(newRegistration);

  res.status(201).json(newRegistration);
});

// PUT /api/camp-registrations/:id - Update a camp registration
router.put("/camp-registrations/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const index = campRegistrations.findIndex(r => r.id === id);

  if (index === -1) {
    return res.status(404).json({ error: "Camp registration not found" });
  }

  const { name, email, bloodType, donationDate } = req.body;

  // Basic validation
  if (!name || !email || !bloodType || !donationDate) {
    return res.status(400).json({ error: "Name, email, blood type, and donation date are required" });
  }

  campRegistrations[index] = {
    id,
    name,
    email,
    bloodType,
    donationDate
  };

  res.json(campRegistrations[index]);
