{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/tmp/freelance-contract-tracker.db"
);

interface ContractRow {
  id: number;
  text: string;
  freelancer_id: number;
  signing_date: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS contracts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    text TEXT NOT NULL,
    freelancer_id INTEGER NOT NULL,
    signing_date TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllContracts(): ContractRow[] {
  const stmt = db.prepare(`SELECT * FROM contracts`);
  return stmt.all() as unknown as ContractRow[];
}

export function getContractById(id: number): ContractRow | undefined {
  const stmt = db.prepare(
    `SELECT * FROM contracts WHERE id = ?`
  );
  return stmt.get(id) as unknown as ContractRow | undefined;
}

export function insertContract(
  text: string,
  freelancerId: number,
  signingDate: string
): number {
  const stmt = db.prepare(
    `INSERT INTO contracts (text, freelancer_id, signing_date) VALUES (?, ?, ?)`
  );
  const result = stmt.run(text, freelancerId, signingDate);
  return Number(result.lastInsertRowid);
}

export function updateContract(
  id: number,
  text: string,
  freelancerId: number,
  signingDate: string
): void {
  const stmt = db.prepare(
    `UPDATE contracts SET text = ?, freelancer_id = ?, signing_date = ? WHERE id = ?`
  );
  stmt.run(text, freelancerId, signingDate, id);
}

export function deleteContract(id: number): void {
  const stmt = db.prepare(`DELETE FROM contracts WHERE id = ?`);
  stmt.run(id);
}

