  const { username, password, email } = req.body;

  if (!username || !password || !email) {
    return res.status(400).json({ error: "Username, password, and email are required" });
  }

  // Check if user already exists
  if (users.some(u => u.username === username)) {
    return res.status(409).json({ error: "User already exists" });
  }

  // Create new user (in a real app, hash the password)
  const newUser = {
    id: users.length + 1,
    username,
    password,
    email
  };

  users.push(newUser);

  // In a real app, we would generate a JWT token here
  res.status(201).json({ message: "User registered successfully", user: { id: newUser.id, username: newUser.username, email: newUser.email } });
});
