  // Only apply role-based access control to protected routes
  const protectedPaths = ["/billing", "/staff", "/patients"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has proper role access
  const userRole = req.headers["x-user-role"] as string | undefined;
  const requiredRoles = getRequiredRoles(req.method, req.path);

  if (!userRole || !requiredRoles.includes(userRole)) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  next();
}

function getRequiredRoles(method: string, path: string): string[] {
  // Define role requirements based on path and method
  if (path.startsWith("/billing")) {
    if (method === "GET") {
      return ["admin", "billing specialist"];
    } else if (method === "POST" || method === "PUT" || method === "DELETE") {
      return ["admin", "billing specialist"];
    }
  }

  if (path.startsWith("/staff")) {
    if (method === "GET") {
      return ["admin", "receptionist"];
    } else if (method === "POST" || method === "PUT" || method === "DELETE") {
      return ["admin"];
    }
  }

  if (path.startsWith("/patients")) {
    if (method === "GET") {
      return ["admin", "receptionist"];
    } else if (method === "POST" || method === "PUT" || method === "DELETE") {
      return ["admin", "receptionist"];
    }
  }

  // Default to admin only for unknown paths
  return ["admin"];
}
"}

{"code":"import { useEffect, useState } from "react";

