{"code":"import { Router, type Request, type Response } from "express";
import { getAllReservations } from "../db/reservations-table";
import { getRoleByUserId } from "../db/role-table";

export const router = Router();

router.get("/export", (req: Request, res: Response) => {
  // Check if user has owner role
  const userId = Number(req.query.userId);

  if (isNaN(userId)) {
    return res.status(400).json({ error: "Invalid user ID" });
  }

  const userRole = getRoleByUserId(userId);

  if (!userRole || userRole.role !== "owner") {
    return res.status(403).json({ error: "Access denied. Owner role required." });
  }

  // Get all reservations
  const reservations = getAllReservations();

  // Generate CSV content
  let csvContent = "Member ID,Plot ID,Reservation Date\n";

  reservations.forEach(reservation => {
    csvContent += `${reservation.memberId},${reservation.plotId},${reservation.reservationDate}\n`;
  });

  // Send CSV response
  res.setHeader("Content-Type", "text/csv");
  res.setHeader("Content-Disposition", "attachment; filename=\"reservations.csv\"");
  res.status(200).send(csvContent);
});
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("library.db");

interface Checkout {
  id: number;
  studentId: number;
  bookIsbn: string;
  date: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS checkouts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    studentId INTEGER NOT NULL,
    bookIsbn TEXT NOT NULL,
    date TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllCheckouts(): Checkout[] {
  const stmt = db.prepare("SELECT * FROM checkouts");
  return stmt.all() as unknown as Checkout[];
}

export function getCheckoutById(id: number): Checkout | undefined {
  const stmt = db.prepare("SELECT * FROM checkouts WHERE id = ?");
  return stmt.get(id) as unknown as Checkout | undefined;
}

export function insertCheckout(studentId: number, bookIsbn: string, date: string): number {
  const stmt = db.prepare(
    "INSERT INTO checkouts (studentId, bookIsbn, date) VALUES (?, ?, ?)"
  );
  const result = stmt.run(studentId, bookIsbn, date);
  return Number(result.lastInsertRowid);
}

export function updateCheckout(id: number, studentId: number, bookIsbn: string, date: string): void {
  const stmt = db.prepare(
    "UPDATE checkouts SET studentId = ?, bookIsbn = ?, date = ? WHERE id = ?"
  );
  stmt.run(studentId, bookIsbn, date, id);
}

export function deleteCheckout(id: number): void {
  const stmt = db.prepare("DELETE FROM checkouts WHERE id = ?");
  stmt.run(id);
}

// Insert sample data if table is empty
if (getAllCheckouts().length === 0) {
