{"code":"import { useEffect, useState } from "react";

interface PlacementRecord {
  id: number;
  studentName: string;
  company: string;
  position: string;
  salary: number;
  date: string;
}

export function PlacementRecords() {
  const [placements, setPlacements] = useState<PlacementRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Form state
  const [formData, setFormData] = useState<Omit<PlacementRecord, 'id'>>({ 
    studentName: '',
    company: '',
    position: '',
    salary: 0,
    date: ''
  });

  const [editingId, setEditingId] = useState<number | null>(null);

  // Fetch placement records
  useEffect(() => {
    const fetchPlacements = async () => {
      try {
        const response = await fetch('/api/placements');
        if (!response.ok) {
          throw new Error('Failed to fetch placements');
        }
        const data = await response.json();
        setPlacements(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchPlacements();
  }, []);

  // Handle form input changes
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: name === 'salary' ? Number(value) : value
    });
  };

  // Submit new placement record
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = await fetch('/api/placements', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });

      if (!response.ok) {
        throw new Error('Failed to add placement');
      }

      // Refresh the list
      const newResponse = await fetch('/api/placements');
      const newData = await newResponse.json();
      setPlacements(newData);

      // Reset form
      setFormData({ 
        studentName: '',
        company: '',
        position: '',
        salary: 0,
        date: ''
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  // Delete a placement record
  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/placements/${id}`, {
        method: 'DELETE'
      });

      if (!response.ok) {
        throw new Error('Failed to delete placement');
      }

      // Refresh the list
      const newResponse = await fetch('/api/placements');
      const newData = await newResponse.json();
      setPlacements(newData);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  // Start editing a record
  const startEditing = (placement: PlacementRecord) => {
    setEditingId(placement.id);
    setFormData({
      studentName: placement.studentName,
      company: placement.company,
      position: placement.position,
      salary: placement.salary,
      date: placement.date
    });
  };

  // Save edited record
  const saveEdit = async () => {
    if (editingId === null) return;

    try {
      const response = await fetch(`/api/placements/${editingId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });

      if (!response.ok) {
        throw new Error('Failed to update placement');
      }

      // Refresh the list
      const newResponse = await fetch('/api/placements');
      const newData = await newResponse.json();
      setPlacements(newData);

      // Reset editing
      setEditingId(null);
      setFormData({ 
        studentName: '',
        company: '',
        position: '',
        salary: 0,
        date: ''
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  // Cancel editing
  const cancelEdit = () => {
    setEditingId(null);
    setFormData({ 
      studentName: '',
      company: '',
      position: '',
      salary: 0,
      date: ''
    });
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Placement Records</h1>

      {/* Add New Placement Form */}
      <div style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <h2>{editingId ? 'Edit Placement' : 'Add New Placement'}</h2>
        <form onSubmit={editingId ? saveEdit : handleSubmit}>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              name="studentName"
              placeholder="Student Name"
              value={formData.studentName}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
              required
            />
          </div>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              name="company"
              placeholder="Company"
              value={formData.company}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
              required
            />
          </div>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              name="position"
              placeholder="Position"
              value={formData.position}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
              required
            />
          </div>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="number"
              name="salary"
              placeholder="Salary"
              value={formData.salary}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
              required
            />
          </div>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="date"
              name="date"
              value={formData.date}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
              required
            />
          </div>
          <div>
            {editingId ? (
              <>
                <button type="submit" style={{ backgroundColor: '#4CAF50', color: 'white', padding: '10px 15px', border: 'none', borderRadius: '4px', cursor: 'pointer', marginRight: '10px' }}>
                  Save Changes
                </button>
                <button type="button" onClick={cancelEdit} style={{ backgroundColor: '#f44336', color: 'white', padding: '10px 15px', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>
                  Cancel
                </button>
              </>
            ) : (
              <button type="submit" style={{ backgroundColor: '#2196F3', color: 'white', padding: '10px 15px', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>
                Add Placement
              </button>
            )}
          </div>
        </form>
      </div>

      {/* Placement Records List */}
      <h2>Placement Records</h2>
      {placements.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No placement records found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {placements.map((placement) => (
            <div key={placement.id} style={{ 
              border: '1px solid #ccc', 
              borderRadius: '8px', 
              padding: '15px', 
              display: 'flex', 
              flexDirection: 'column', 
              gap: '10px'
            }}>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <div>
                  <strong>Student:</strong> {placement.studentName}<br />
                  <strong>Company:</strong> {placement.company}<br />
                  <strong>Position:</strong> {placement.position}<br />
                  <strong>Salary:</strong> ${placement.salary.toLocaleString()}<br />
                  <strong>Date:</strong> {placement.date}
                </div>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '5px' }}>
                  <button 
                    onClick={() => startEditing(placement)}
                    style={{ backgroundColor: '#FF9800', color: 'white', padding: '5px 10px', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
                  >
                    Edit
                  </button>
                  <button 
                    onClick={() => handleDelete(placement.id)}
                    style={{ backgroundColor: '#f44336', color: 'white', padding: '5px 10px', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

