{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply to checkout-related routes
  if (!req.path.startsWith("/checkouts") || req.method !== "GET") {
    next();
    return;
  }

  // Check if user is authenticated
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  try {
    // Simple token validation - in a real system, you'd decode and verify properly
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    // In a real implementation, we would decode the payload to get the member ID
    // For now, we'll assume the token contains a member ID in a known format
    // This is a simplified version - in practice, proper JWT decoding and validation
    // would be needed

    // Extract member ID from token (simplified)
    const decodedPayload = Buffer.from(payload, "base64").toString();
    const payloadObj = JSON.parse(decodedPayload);
    const memberIdFromToken = payloadObj.memberId;

    if (!memberIdFromToken) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    // Store member ID in request for later use in controllers
    (req as any).memberId = memberIdFromToken;
    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized" });
  }
}
"}

