      const [plotsResponse, reservationsResponse] = await Promise.all([
        fetch("/api/garden-api/plots"),
        fetch("/api/garden-api/reservations"),
      ]);

      if (plotsResponse.ok && reservationsResponse.ok) {
        const plotsData = await plotsResponse.json();
        const reservationsData = await reservationsResponse.json();

        setPlots(plotsData);
        setReservations(reservationsData);
        setSelectedPlotId(null);
