  try {
    const { title, content, status } = req.body;

    if (!title || !content || !status) {
      return res.status(400).json({ error: "Title, content, and status are required" });
    }

    const newPostId = insertPost({
      title,
      content,
      status
    });

    const createdPost = getPostById(newPostId);
    if (!createdPost) {
      return res.status(500).json({ error: "Failed to create post" });
    }

    res.status(201).json(createdPost);
  } catch (error) {
    res.status(500).json({ error: "Failed to create post" });
  }
});

// Update a post
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid post ID" });
    }

    const { title, content, status } = req.body;

    const postExists = getPostById(id);
    if (!postExists) {
      return res.status(404).json({ error: "Post not found" });
    }

    const updated = updatePost(id, { title, content, status });

    if (!updated) {
      return res.status(500).json({ error: "Failed to update post" });
    }

    const updatedPost = getPostById(id);
    if (!updatedPost) {
      return res.status(500).json({ error: "Failed to retrieve updated post" });
    }

    res.json(updatedPost);
  } catch (error) {
    res.status(500).json({ error: "Failed to update post" });
  }
});

// Delete a post
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid post ID" });
    }

    const postExists = getPostById(id);
    if (!postExists) {
      return res.status(404).json({ error: "Post not found" });
    }

    const deleted = deletePost(id);

    if (!deleted) {
      return res.status(500).json({ error: "Failed to delete post" });
    }

    res.json({ message: "Post deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete post" });
  }
});
"}

{"code":"import { useEffect, useState } from "react";

interface Ticket {
  id: number;
  title: string;
  description: string;
  status: "open" | "in-progress" | "resolved" | "closed";
  assignee: string | null;
  createdAt: string;
  updatedAt: string;
}

interface Comment {
  id: number;
  ticketId: number;
  content: string;
  author: string;
  createdAt: string;
}

interface HistoryItem {
  id: number;
  ticketId: number;
  action: string;
  oldValue: string | null;
  newValue: string | null;
  author: string;
  createdAt: string;
}

export function TicketDetailView({ ticketId }: { ticketId: string }) {
  const [ticket, setTicket] = useState<Ticket | null>(null);
  const [comments, setComments] = useState<Comment[]>([]);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newComment, setNewComment] = useState("");
  const [assignee, setAssignee] = useState("");
  const [status, setStatus] = useState<"open" | "in-progress" | "resolved" | "closed">("open");

  useEffect(() => {
    const fetchTicketData = async () => {
      try {
        const response = await fetch(`/api/tickets/${ticketId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch ticket: ${response.status}`);
        }
        const ticketData: Ticket = await response.json();
        setTicket(ticketData);

        const commentsResponse = await fetch(`/api/tickets/${ticketId}/comments`);
        if (!commentsResponse.ok) {
          throw new Error(`Failed to fetch comments: ${commentsResponse.status}`);
        }
        const commentsData: Comment[] = await commentsResponse.json();
        setComments(commentsData);

        const historyResponse = await fetch(`/api/tickets/${ticketId}/history`);
        if (!historyResponse.ok) {
          throw new Error(`Failed to fetch history: ${historyResponse.status}`);
        }
        const historyData: HistoryItem[] = await historyResponse.json();
        setHistory(historyData);

        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchTicketData();
  }, [ticketId]);

  const handleUpdateStatus = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!ticket) return;

    try {
      const response = await fetch(`/api/tickets/${ticket.id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status, assignee }),
      });

      if (!response.ok) {
        throw new Error(`Failed to update ticket: ${response.status}`);
      }

      // Refresh data after update
      const updatedResponse = await fetch(`/api/tickets/${ticket.id}`);
      const updatedTicket: Ticket = await updatedResponse.json();
      setTicket(updatedTicket);

      // Reset form
      setStatus("open");
      setAssignee("");
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleAddComment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!ticket || !newComment.trim()) return;

    try {
      const response = await fetch(`/api/tickets/${ticket.id}/comments`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ content: newComment }),
      });

      if (!response.ok) {
        throw new Error(`Failed to add comment: ${response.status}`);
      }

      // Refresh comments after adding
      const commentsResponse = await fetch(`/api/tickets/${ticket.id}/comments`);
      const commentsData: Comment[] = await commentsResponse.json();
      setComments(commentsData);

      // Reset comment input
      setNewComment("");
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;
  }

  if (!ticket) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Ticket not found</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Ticket Details</h1>

      <div style={{ backgroundColor: "#f5f5f5", borderRadius: "8px", padding: "16px", marginBottom: "20px" }}>
        <h2>{ticket.title}</h2>
        <p><strong>Description:</strong> {ticket.description}</p>
        <p><strong>Status:</strong> {ticket.status}</p>
        <p><strong>Assignee:</strong> {ticket.assignee || "Unassigned"}</p>
        <p><strong>Created:</strong> {new Date(ticket.createdAt).toLocaleString()}</p>
        <p><strong>Last Updated:</strong> {new Date(ticket.updatedAt).toLocaleString()}</p>
      </div>

      <div style={{ marginBottom: "20px" }}>
        <h3>Add Comment</h3>
        <form onSubmit={handleAddComment}>
          <textarea
            value={newComment}
            onChange={(e) => setNewComment(e.target.value)}
            placeholder="Enter your comment..."
            style={{ width: "100%", padding: "8px", marginBottom: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
            rows={3}
          />
          <button type="submit" style={{ backgroundColor: "#007bff", color: "white", padding: "8px 16px", border: "none", borderRadius: "4px", cursor: "pointer" }}>
            Add Comment
          </button>
        </form>
      </div>

      <div style={{ marginBottom: "20px" }}>
        <h3>Comments</h3>
        {comments.length === 0 ? (
          <p>No comments yet.</p>
        ) : (
          <div>
            {comments.map((comment) => (
              <div key={comment.id} style={{ backgroundColor: "#fff", border: "1px solid #ddd", borderRadius: "4px", padding: "10px", marginBottom: "10px" }}>
                <p><strong>{comment.author}</strong> - {new Date(comment.createdAt).toLocaleString()}</p>
                <p>{comment.content}</p>
              </div>
            ))}
          </div>
        )}
      </div>

      <div style={{ marginBottom: "20px" }}>
        <h3>History</h3>
        {history.length === 0 ? (
          <p>No history available.</p>
        ) : (
          <div>
            {history.map((item) => (
              <div key={item.id} style={{ backgroundColor: "#fff", border: "1px solid #ddd", borderRadius: "4px", padding: "10px", marginBottom: "10px" }}>
                <p><strong>{item.author}</strong> - {new Date(item.createdAt).toLocaleString()}</p>
                <p>{item.action}</p>
                {item.oldValue && item.newValue && (
                  <p>
                    Changed from <strong>{item.oldValue}</strong> to <strong>{item.newValue}</strong>
                  </p>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      <div>
        <h3>Update Status</h3>
        <form onSubmit={handleUpdateStatus}>
          <div style={{ marginBottom: "10px" }}>
            <label htmlFor="status" style={{ display: "block", marginBottom: "5px" }}>
              Status:
            </label>
            <select
              id="status"
              value={status}
              onChange={(e) => setStatus(e.target.value as any)}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            >
              <option value="open">Open</option>
              <option value="in-progress">In Progress</option>
              <option value="resolved">Resolved</option>
              <option value="closed">Closed</option>
            </select>
          </div>

          <div style={{ marginBottom: "10px" }}>
            <label htmlFor="assignee" style={{ display: "block", marginBottom: "5px" }}>
              Assignee:
            </label>
            <input
              type="text"
              id="assignee"
              value={assignee}
              onChange={(e) => setAssignee(e.target.value)}
              placeholder="Enter assignee name"
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            />
          </div>

          <button type="submit" style={{ backgroundColor: "#28a745", color: "white", padding: "8px 16px", border: "none", borderRadius: "4px", cursor: "pointer" }}>
            Update Ticket
          </button>
        </form>
      </div>
    </div>
  );
}
"}

