{"code":"import { useEffect, useState } from "react";

interface DiaryEntry {
  id: number;
  title: string;
  content: string;
  date: string;
}

export function DiaryEntryDetail({
  entryId,
  onEdit,
  onDelete
}: {
  entryId: string;
  onEdit: () => void;
  onDelete: () => void;
}) {
  const [entry, setEntry] = useState<DiaryEntry | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchEntry() {
      try {
        const response = await fetch(`/api/diary-entries/${entryId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch entry: ${response.status}`);
        }
        const data = await response.json();
        setEntry(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchEntry();
  }, [entryId]);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (!entry) {
    return <div style={{ textAlign: "center", padding: "20px" }}>No entry found</div>;
  }

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center", marginBottom: "20px" }}>{entry.title}</h1>
      <p style={{ fontSize: "14px", color: "#666", marginBottom: "20px" }}>Date: {entry.date}</p>
      <div style={{ border: "1px solid #ddd", borderRadius: "8px", padding: "20px", marginBottom: "20px" }}>
        <p>{entry.content}</p>
      </div>
      <div style={{ display: "flex", gap: "10px", justifyContent: "center" }}>
        <button 
          onClick={onEdit}
          style={{ 
            backgroundColor: "#007bff", 
            color: "white", 
            border: "none", 
            borderRadius: "4px", 
            padding: "10px 20px", 
            cursor: "pointer" 
          }}
        >
          Edit
        </button>
        <button 
          onClick={onDelete}
          style={{ 
            backgroundColor: "#dc3545", 
            color: "white", 
            border: "none", 
            borderRadius: "4px", 
            padding: "10px 20px", 
            cursor: "pointer" 
          }}
        >
          Delete
        </button>
      </div>
    </div>
  );
}
"}

