{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const machines = [
  { id: 1, model: "Espresso Pro", location: "Lobby", lastService: "2023-05-15", status: "active" },
  { id: 2, model: "Cappuccino Master", location: "Conference Room", lastService: "2023-06-20", status: "maintenance" }
];

const findMachineIndex = (id: number) => machines.findIndex(machine => machine.id === id);

// Get all machines
router.get("/", (req: Request, res: Response) => {
  res.json(machines);
});

// Get one machine by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid machine ID" });
  }

  const machine = machines.find(m => m.id === id);

  if (!machine) {
    return res.status(404).json({ error: "Machine not found" });
  }

  res.json(machine);
});

// Create a new machine
router.post("/", (req: Request, res: Response) => {
  const { model, location, lastService, status } = req.body;

  if (!model || !location || !lastService || !status) {
    return res.status(400).json({ error: "Missing required fields: model, location, lastService, status" });
  }

  const newId = machines.length > 0 ? Math.max(...machines.map(m => m.id)) + 1 : 1;

  const newMachine = {
    id: newId,
    model,
    location,
    lastService,
    status
  };

  machines.push(newMachine);

  res.status(201).json(newMachine);
});

// Update a machine
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid machine ID" });
  }

  const machineIndex = findMachineIndex(id);

  if (machineIndex === -1) {
    return res.status(404).json({ error: "Machine not found" });
  }

  const { model, location, lastService, status } = req.body;

  if (!model || !location || !lastService || !status) {
    return res.status(400).json({ error: "Missing required fields: model, location, lastService, status" });
  }

  machines[machineIndex] = {
    id,
    model,
    location,
    lastService,
    status
  };

  res.json(machines[machineIndex]);
});

// Delete a machine
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid machine ID" });
  }

  const machineIndex = findMachineIndex(id);

  if (machineIndex === -1) {
    return res.status(404).json({ error: "Machine not found" });
  }

  machines.splice(machineIndex, 1);

  res.json({ message: "Machine deleted successfully" });
});
"}

