{"code":"import { useEffect, useState } from "react";

interface Member {
  id: string;
  name: string;
  email: string;
  dogName: string;
  checkedIn: boolean;
}

export function CheckInWidget() {
  const [members, setMembers] = useState<Member[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newMember, setNewMember] = useState({
    name: "",
    email: "",
    dogName: ""
  });

  useEffect(() => {
    fetchMembers();
  }, []);

  const fetchMembers = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/membership-api/members");
      if (!response.ok) {
        throw new Error(`Failed to fetch members: ${response.status}`);
      }
      const data = await response.json();
      setMembers(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleCheckIn = async (id: string) => {
    try {
      const response = await fetch(`/api/membership-api/checkin`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id })
      });
      if (!response.ok) {
        throw new Error(`Failed to check in: ${response.status}`);
      }
      await fetchMembers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleRevoke = async (id: string) => {
    try {
      const response = await fetch(`/api/membership-api/revoke/${id}`, {
        method: "PUT"
      });
      if (!response.ok) {
        throw new Error(`Failed to revoke: ${response.status}`);
      }
      await fetchMembers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleAddMember = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch(`/api/membership-api/members`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newMember)
      });
      if (!response.ok) {
        throw new Error(`Failed to add member: ${response.status}`);
      }
      setNewMember({ name: "", email: "", dogName: "" });
      await fetchMembers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Dog Park Membership Check-In</h1>

      <div style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2>Add New Member</h2>
        <form onSubmit={handleAddMember}>
          <div style={{ marginBottom: "10px" }}>
            <input
              type="text"
              placeholder="Member Name"
              value={newMember.name}
              onChange={(e) => setNewMember({...newMember, name: e.target.value})}
              style={{ width: "100%", padding: "8px", boxSizing: "border-box" }}
            />
          </div>
          <div style={{ marginBottom: "10px" }}>
            <input
              type="email"
              placeholder="Email"
              value={newMember.email}
              onChange={(e) => setNewMember({...newMember, email: e.target.value})}
              style={{ width: "100%", padding: "8px", boxSizing: "border-box" }}
            />
          </div>
          <div style={{ marginBottom: "10px" }}>
            <input
              type="text"
              placeholder="Dog Name"
              value={newMember.dogName}
              onChange={(e) => setNewMember({...newMember, dogName: e.target.value})}
              style={{ width: "100%", padding: "8px", boxSizing: "border-box" }}
            />
          </div>
          <button type="submit" style={{ backgroundColor: "#007bff", color: "white", border: "none", padding: "10px 20px", borderRadius: "4px", cursor: "pointer" }}>
            Add Member
          </button>
        </form>
      </div>

      <h2>Current Members</h2>
      {members.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No members found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {members.map(member => (
            <div key={member.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <strong>{member.name}</strong> - {member.dogName}
                <br />
                <small>{member.email}</small>
                <br />
                <small>{member.checkedIn ? "Checked In" : "Not Checked In"}</small>
              </div>
              <div style={{ display: "flex", gap: "10px" }}>
                {!member.checkedIn && (
                  <button 
                    onClick={() => handleCheckIn(member.id)}
                    style={{ backgroundColor: "#28a745", color: "white", border: "none", padding: "5px 10px", borderRadius: "4px", cursor: "pointer" }}
                  >
                    Check In
                  </button>
                )}
                {member.checkedIn && (
                  <button 
                    onClick={() => handleRevoke(member.id)}
                    style={{ backgroundColor: "#dc3545", color: "white", border: "none", padding: "5px 10px", borderRadius: "4px", cursor: "pointer" }}
                  >
                    Revoke
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import { db as photosDb, getAllPhotos, getPhotoById, insertPhoto, updatePhoto, deletePhoto } from "../db/photos-table";
import { db as commentsDb, getAllComments, getCommentById, insertComment, updateComment, deleteComment } from "../db/comments-table";
import { middleware as albumAccessGuard } from "../middleware/album-access-guard";
import { middleware as ownerOnlyDeleteGuard } from "../middleware/owner-only-delete-guard";

export const router = Router();

// GET /albums - Get all photos
router.get("/albums", albumAccessGuard, (req: Request, res: Response) => {
  try {
    const photos = getAllPhotos();
    res.json(photos);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch photos" });
  }
});

// GET /albums/:id - Get a specific photo by ID
router.get("/albums/:id", albumAccessGuard, (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid photo ID" });
    }

    const photo = getPhotoById(id);
    if (!photo) {
      return res.status(404).json({ error: "Photo not found" });
    }

    res.json(photo);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch photo" });
  }
});

// POST /albums - Create a new photo
router.post("/albums", albumAccessGuard, (req: Request, res: Response) => {
  try {
    const { filename, owner_id } = req.body;

    if (!filename || !owner_id) {
      return res.status(400).json({ error: "Filename and owner_id are required" });
    }

    const newId = insertPhoto(filename, owner_id);
    const newPhoto = getPhotoById(newId);

    if (!newPhoto) {
      return res.status(500).json({ error: "Failed to retrieve created photo" });
    }

    res.status(201).json(newPhoto);
  } catch (error) {
    res.status(500).json({ error: "Failed to create photo" });
  }
});

// PUT /albums/:id - Update a photo
router.put("/albums/:id", albumAccessGuard, (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { filename, owner_id } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid photo ID" });
    }

    if (!filename || !owner_id) {
      return res.status(400).json({ error: "Filename and owner_id are required" });
    }

    const existingPhoto = getPhotoById(id);
    if (!existingPhoto) {
      return res.status(404).json({ error: "Photo not found" });
    }

    updatePhoto(id, filename, owner_id);
    const updatedPhoto = getPhotoById(id);

    if (!updatedPhoto) {
      return res.status(500).json({ error: "Failed to retrieve updated photo" });
    }

    res.json(updatedPhoto);
  } catch (error) {
    res.status(500).json({ error: "Failed to update photo" });
  }
});

// DELETE /albums/:id - Delete a photo
router.delete("/albums/:id", [albumAccessGuard, ownerOnlyDeleteGuard], (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid photo ID" });
    }

    const existingPhoto = getPhotoById(id);
    if (!existingPhoto) {
      return res.status(404).json({ error: "Photo not found" });
    }

    deletePhoto(id);
    res.json({ message: "Photo deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete photo" });
  }
});

// GET /albums/:id/comments - Get all comments for a specific photo
router.get("/albums/:id/comments", albumAccessGuard, (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid photo ID" });
    }

    const comments = getAllComments().filter((comment: any) => comment.photo_id === id);
    res.json(comments);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch comments" });
  }
});
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./food-bank.db");

interface Supervisor {
  id: number;
  name: string;
  email: string;
  role: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS supervisors (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    email TEXT UNIQUE NOT NULL,
    role TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllSupervisors(): Supervisor[] {
  const stmt = db.prepare("SELECT * FROM supervisors");
  return stmt.all() as unknown as Supervisor[];
}

export function getSupervisorById(id: number): Supervisor | undefined {
  const stmt = db.prepare("SELECT * FROM supervisors WHERE id = ?");
  return stmt.get(id) as unknown as Supervisor | undefined;
}

export function insertSupervisor(supervisor: Omit<Supervisor, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO supervisors (name, email, role) VALUES (?, ?, ?)"
  );
  const result = stmt.run(supervisor.name, supervisor.email, supervisor.role);
  return Number(result.lastInsertRowid);
}

export function updateSupervisor(
  id: number,
  supervisor: Partial<Omit<Supervisor, "id">>
): boolean {
  const fields = [];
  const values = [];

  if (supervisor.name !== undefined) {
    fields.push("name = ?");
    values.push(supervisor.name);
  }

  if (supervisor.email !== undefined) {
    fields.push("email = ?");
    values.push(supervisor.email);
  }

  if (supervisor.role !== undefined) {
    fields.push("role = ?");
    values.push(supervisor.role);
  }

  if (fields.length === 0) return false;

  values.push(id);

  const sql = `UPDATE supervisors SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);
  return true;
}

export function deleteSupervisor(id: number): boolean {
  const stmt = db.prepare("DELETE FROM supervisors WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

// Insert sample data if table is empty
if (getAllSupervisors().length === 0) {
  insertSupervisor({
    name: "Alice Johnson",
    email: "alice@foodbank.org",
    role: "Manager"
  });
