    name: "Carol Davis",
    email: "carol@foodbank.org",
    role: "Supervisor"
  });
  insertSupervisor({
    name: "David Wilson",
    email: "david@foodbank.org",
    role: "Assistant Manager"
  });
  insertSupervisor({
    name: "Eva Brown",
    email: "eva@foodbank.org",
    role: "Staff"
  });
}
