{"code":"import { useEffect, useState } from "react";

interface UsageRecord {
  id: string;
  date: string;
  kwh: number;
  cost: number;
}

export function UsageDashboard() {
  const [records, setRecords] = useState<UsageRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newRecord, setNewRecord] = useState({
    date: "",
    kwh: "",
    cost: ""
  });

  useEffect(() => {
    fetchUsageRecords();
  }, []);

  const fetchUsageRecords = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/usage-records-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status}`);
      }
      const data = await response.json();
      setRecords(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewRecord({
      ...newRecord,
      [name]: value
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/usage-records-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          date: newRecord.date,
          kwh: parseFloat(newRecord.kwh),
          cost: parseFloat(newRecord.cost)
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to create record: ${response.status}`);
      }

      // Reset form and reload records
      setNewRecord({ date: "", kwh: "", cost: "" });
      fetchUsageRecords();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/usage-records-api/${id}`, {
        method: "DELETE"
      });

      if (!response.ok) {
        throw new Error(`Failed to delete record: ${response.status}`);
      }

      fetchUsageRecords();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
