{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function isValidMethod(method: string): boolean {
  return ["GET", "POST", "PUT", "DELETE"].includes(method);
}

function isProtectedPath(path: string): boolean {
  return path.startsWith("/dispense") || 
         path.startsWith("/patient-data") ||
         path.startsWith("/medication") ||
         path.startsWith("/pharmacy-staff");
}

function verifyTokenSignature(token: string): boolean {
  if (!JWT_SECRET) return false;

  const [header, payload, signature] = token.split(".");
  if (!header || !payload || !signature) return false;

  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(signature, "base64url");
    return timingSafeEqual(expectedBuffer, actualBuffer);
  } catch {
    return false;
  }
}

function extractRoleFromToken(token: string): string | null {
  try {
    const payload = token.split(".")[1];
    const decodedPayload = Buffer.from(payload, "base64").toString();
    const parsed = JSON.parse(decodedPayload);
    return parsed.role || null;
  } catch {
    return null;
  }
}

function hasValidRole(role: string | null): boolean {
  return role === "pharmacist" || role === "pharmacy-tech" || role === "admin";
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-protected methods or paths
  if (!isValidMethod(req.method) || !isProtectedPath(req.path)) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  if (!verifyTokenSignature(token)) {
    res.status(401).json({ error: "Unauthorized: Invalid token signature" });
    return;
  }

  const role = extractRoleFromToken(token);
  if (!hasValidRole(role)) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  // Attach role to request for downstream middleware/route handlers
  (req as any).role = role;
  next();
}
"}

