  if (!parcel) {
    return res.status(404).json({ error: "Parcel not found" });
  }

  res.json(parcel);
});

// POST /parcels - Create a new parcel
router.post("/parcels", (req: Request, res: Response) => {
  const { sender, recipient, weight, dimensions, status } = req.body;

  // Basic validation
  if (!sender || !recipient || !weight || !dimensions) {
    return res.status(400).json({ error: "Missing required fields: sender, recipient, weight, dimensions" });
  }

  const newParcel = {
    id: nextId++,
    sender,
    recipient,
    weight,
    dimensions,
    status: status || "pending",
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };

  parcels.push(newParcel);
  res.status(201).json(newParcel);
});

// PUT /parcels/:id - Update a parcel
router.put("/parcels/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const parcelIndex = parcels.findIndex(p => p.id === id);

  if (parcelIndex === -1) {
    return res.status(404).json({ error: "Parcel not found" });
  }

  const { sender, recipient, weight, dimensions, status } = req.body;

  // Basic validation
  if (!sender || !recipient || !weight || !dimensions) {
    return res.status(400).json({ error: "Missing required fields: sender, recipient, weight, dimensions" });
  }

  const updatedParcel = {
    ...parcels[parcelIndex],
    sender,
    recipient,
    weight,
    dimensions,
    status,
    updatedAt: new Date().toISOString()
  };

  parcels[parcelIndex] = updatedParcel;
  res.json(updatedParcel);
});

// DELETE /parcels/:id - Delete a parcel
router.delete("/parcels/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const parcelIndex = parcels.findIndex(p => p.id === id);

  if (parcelIndex === -1) {
    return res.status(404).json({ error: "Parcel not found" });
  }

  parcels.splice(parcelIndex, 1);
  res.json({ message: "Parcel deleted successfully" });
});
"}

