export const router = Router();

// Mock database functions - in a real app these would come from a database module
const mockWeddingDatabase = {
  create: (wedding: any) => Promise.resolve({ id: 1, ...wedding }),
  findById: (id: number) => Promise.resolve({ id: 1, name: "Sample Wedding", date: "2023-12-01", vendorIds: [] }),
  findAll: () => Promise.resolve([{ id: 1, name: "Sample Wedding", date: "2023-12-01", vendorIds: [] }]),
  update: (id: number, wedding: any) => Promise.resolve({ id, ...wedding }),
  delete: (id: number) => Promise.resolve(true)
};

// Validation helper
const validateWedding = (wedding: any): boolean => {
  return wedding && 
         typeof wedding.name === 'string' && 
         wedding.name.trim().length > 0 &&
         typeof wedding.date === 'string' && 
         wedding.date.length > 0;
};

// GET /weddings - List all weddings
router.get("/weddings", async (req: Request, res: Response) => {
  try {
    const weddings = await mockWeddingDatabase.findAll();
    res.json(weddings);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch weddings" });
  }
});

// GET /weddings/:id - Get a specific wedding by ID
router.get("/weddings/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid wedding ID" });
    }

    const wedding = await mockWeddingDatabase.findById(id);
    if (!wedding) {
      return res.status(404).json({ error: "Wedding not found" });
    }

    res.json(wedding);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch wedding" });
  }
});

// POST /weddings - Create a new wedding
router.post("/weddings", async (req: Request, res: Response) => {
  try {
    const { name, date, vendorIds } = req.body;

    // Validate input
    if (!validateWedding({ name, date })) {
      return res.status(400).json({ error: "Invalid wedding data" });
    }

    const newWedding = await mockWeddingDatabase.create({ name, date, vendorIds });
    res.status(201).json(newWedding);
  } catch (error) {
    res.status(500).json({ error: "Failed to create wedding" });
  }
});

// PUT /weddings/:id - Update a wedding
router.put("/weddings/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid wedding ID" });
    }

    const { name, date, vendorIds } = req.body;

    // Validate input
    if (!validateWedding({ name, date })) {
      return res.status(400).json({ error: "Invalid wedding data" });
    }

    const updatedWedding = await mockWeddingDatabase.update(id, { name, date, vendorIds });

    if (!updatedWedding) {
      return res.status(404).json({ error: "Wedding not found" });
    }

    res.json(updatedWedding);
  } catch (error) {
    res.status(500).json({ error: "Failed to update wedding" });
  }
});

// DELETE /weddings/:id - Delete a wedding
router.delete("/weddings/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid wedding ID" });
    }

    const deleted = await mockWeddingDatabase.delete(id);

    if (!deleted) {
      return res.status(404).json({ error: "Wedding not found" });
    }

    res.json({ message: "Wedding deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete wedding" });
  }
});
