{"code":"import { useEffect, useState } from "react";

interface MaintenanceRequest {
  id: number;
  title: string;
  description: string;
  status: "pending" | "in-progress" | "completed";
  createdAt: string;
}

export function MaintenanceRequests() {
  const [requests, setRequests] = useState<MaintenanceRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");

  useEffect(() => {
    fetchRequests();
  }, []);

  const fetchRequests = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/maintenance-requests");
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status}`);
      }
      const data = await response.json();
      setRequests(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/maintenance-requests", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ title, description }),
      });
      if (!response.ok) {
        throw new Error(`Failed to create: ${response.status}`);
      }
      setTitle("");
      setDescription("");
      await fetchRequests();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Maintenance Requests</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2>Create New Request</h2>
        <div style={{ marginBottom: "15px" }}>
          <input
            type="text"
            placeholder="Title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ddd" }}
            required
          />
        </div>
        <div style={{ marginBottom: "15px" }}>
          <textarea
            placeholder="Description"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ddd", height: "100px" }}
            required
          />
        </div>
        <button type="submit" style={{ backgroundColor: "#007bff", color: "white", padding: "10px 20px", border: "none", borderRadius: "4px", cursor: "pointer" }}>
          Submit Request
        </button>
      </form>

      <h2>Current Requests</h2>
      {requests.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No maintenance requests found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {requests.map((request) => (
            <div key={request.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <h3 style={{ margin: "0" }}>{request.title}</h3>
                <span style={{ backgroundColor: getStatusColor(request.status), color: "white", padding: "4px 8px", borderRadius: "4px" }}>
                  {request.status}
                </span>
              </div>
              <p style={{ margin: "10px 0" }}>{request.description}</p>
              <p style={{ fontSize: "0.9em", color: "#666" }}>
                Created: {new Date(request.createdAt).toLocaleDateString()}
              </p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function getStatusColor(status: string) {
  switch (status) {
    case "pending":
      return "#ffc107";
    case "in-progress":
      return "#17a2b8";
    case "completed":
      return "#28a745";
    default:
      return "#6c757d";
  }
}
"}

{"code":"import { useEffect, useState } from "react";

