  id: number;
  bookTitle: string;
  borrowerName: string;
  dueDate: string;
  fineAmount: number;
}

interface WaiverRequest {
  checkoutId: number;
  reason: string;
}

export function OverdueFeeWaiverForm() {
  const [checkouts, setCheckouts] = useState<Checkout[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedCheckoutId, setSelectedCheckoutId] = useState<number | null>(null);
  const [reason, setReason] = useState("");

  useEffect(() => {
    fetchCheckouts();
  }, []);

  const fetchCheckouts = async () => {
    try {
      const response = await fetch("/api/checkouts-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch checkouts: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setCheckouts(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
      setLoading(false);
    }
  };

  const handleWaiveFee = async (checkoutId: number, reason: string) => {
    try {
      const waiverRequest: WaiverRequest = { checkoutId, reason };
      const response = await fetch("/api/waivers-api/waivers", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(waiverRequest),
      });

      if (!response.ok) {
        throw new Error(`Failed to waive fee: ${response.status} ${response.statusText}`);
      }

      // Refresh the list after successful waiver
      await fetchCheckouts();
      setSelectedCheckoutId(null);
      setReason("");
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

