      {checkouts.length === 0 ? (
        <p style={{ textAlign: "center" }}>No overdue books found.</p>
      ) : (
        <div>
          <table style={{ width: "100%", borderCollapse: "collapse", marginBottom: "20px" }}>
            <thead>
              <tr style={{ borderBottom: "1px solid #ccc" }}>
                <th style={{ textAlign: "left", padding: "10px" }}>Book Title</th>
                <th style={{ textAlign: "left", padding: "10px" }}>Borrower</th>
                <th style={{ textAlign: "left", padding: "10px" }}>Due Date</th>
                <th style={{ textAlign: "left", padding: "10px" }}>Fine Amount</th>
                <th style={{ textAlign: "left", padding: "10px" }}>Action</th>
              </tr>
            </thead>
            <tbody>
              {checkouts.map((checkout) => (
                <tr key={checkout.id} style={{ borderBottom: "1px solid #eee" }}>
                  <td style={{ padding: "10px" }}>{checkout.bookTitle}</td>
                  <td style={{ padding: "10px" }}>{checkout.borrowerName}</td>
