                      style={{
                        backgroundColor: "#007bff",
                        color: "white",
                        border: "none",
                        borderRadius: "4px",
                        padding: "5px 10px",
                        cursor: "pointer",
                      }}
                    >
                      Waive Fee
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {selectedCheckoutId !== null && (
        <div style={{ marginTop: "20px", padding: "20px", border: "1px solid #ccc", borderRadius: "4px" }}>
          <h2>Waive Fee for Selected Book</h2>
          <div style={{ marginBottom: "10px" }}>
            <label htmlFor="reason" style={{ display: "block", marginBottom: "5px" }}>
              Reason for Waiver:
            </label>
            <input
              id="reason"
              type="text"
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              style={{ width: "100%", padding: "8px", boxSizing: "border-box" }}
