              style={{
                backgroundColor: "#28a745",
                color: "white",
                border: "none",
                borderRadius: "4px",
                padding: "10px 20px",
                cursor: "pointer",
                marginRight: "10px",
              }}
            >
              Submit Waiver
            </button>
            <button
              onClick={() => {
