                  {column.title} ({columnTasks.length})
                </h2>

                <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
                  {columnTasks.length > 0 ? (
                    columnTasks.map(task => (
                      <div 
                        key={task.id} 
                        style={{
                          backgroundColor: "white",
                          border: "1px solid #ddd",
                          borderRadius: "6px",
                          padding: "12px",
                          boxShadow: "0 1px 3px rgba(0,0,0,0.1)"
                        }}
                      >
