                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function getTaskStatusColor(status: "todo" | "in-progress" | "done") {
  switch (status) {
    case "todo": return "#3b82f6"; // blue-500
    case "in-progress": return "#f59e0b"; // amber-500
    case "done": return "#10b981"; // emerald-500
    default: return "#6b7280"; // gray-500
  }
}
