{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply RBAC to protected routes
  if (!req.path.startsWith('/api/')) {
    next();
    return;
  }

  // Check if user is authenticated
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: 'Server configuration error' });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify properly)
  try {
    const [payload, signature] = token.split('.');
    if (!payload || !signature) {
      res.status(401).json({ error: 'Invalid token format' });
      return;
    }

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac('sha256', secret)
      .update(payload)
      .digest('base64url');

    const signatureBuffer = Buffer.from(signature, 'base64url');
    const expectedSignatureBuffer = Buffer.from(expectedSignature, 'base64url');

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: 'Invalid token signature' });
      return;
    }

    // Decode payload to get role and user info
    const payloadBytes = Buffer.from(payload, 'base64url');
    const payloadStr = payloadBytes.toString('utf8');
    const { role, userId } = JSON.parse(payloadStr);

    // Store user info in request for later use
    (req as any).userRole = role;
    (req as any).userId = userId;

    // Apply role-based access control
    if (role === 'admin') {
      // Admins have full access
      next();
      return;
    }

    // For regular members, check if they're accessing their own data
    if (role === 'member') {
      // Allow member to access their own bookings
      if (req.path.includes(`/members/${userId}/bookings`)) {
        next();
        return;
      }

      // Deny access to other members' data
      if (req.path.includes('/members/') && !req.path.includes(`/members/${userId}/`)) {
        res.status(403).json({ error: 'Forbidden: Access to other members data denied' });
        return;
      }

      // Allow member to access their own profile
      if (req.path.includes(`/members/${userId}`)) {
        next();
        return;
      }

      // Deny access to admin-only endpoints
      if (req.path.includes('/admin/')) {
        res.status(403).json({ error: 'Forbidden: Admin access required' });
        return;
      }

      // Allow read-only access to public resources
      if (req.method === 'GET') {
        next();
        return;
      }

      // Deny write access for non-admins unless it's their own data
      res.status(403).json({ error: 'Forbidden: Insufficient permissions' });
      return;
    }

    // Unknown role
    res.status(401).json({ error: 'Unauthorized' });
  } catch (error) {
    res.status(401).json({ error: 'Invalid token' });
  }
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  const protectedPaths = [
    "/api/appointments",
    "/api/staff",
    "/api/customers",
    "/api/services"
  ];

  const isProtectedPath = protectedPaths.some(path => 
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Verify token signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  try {
    // Simple token verification (in a real app, use a proper JWT library)
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    // Recalculate signature
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(signature, "base64url"),
      Buffer.from(expectedSignature, "base64url")
    );

    if (!isValid) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // Decode payload (simplified - in reality, parse base64url)
    const decodedPayload = JSON.parse(
      Buffer.from(payload, "base64url").toString("utf-8")
    );

    // Extract user role from token
    const userRole = decodedPayload.role;
    if (!userRole) {
      res.status(401).json({ error: "Unauthorized: Role not found in token" });
      return;
    }

    // Define role requirements for different paths
    const roleRequirements: Record<string, string[]> = {
      "/api/appointments": ["customer", "staff", "admin"],
      "/api/staff": ["admin"],
      "/api/customers": ["admin"],
      "/api/services": ["admin"]
    };

    // Check if user has required role
    const requiredRoles = roleRequirements[req.path] || [];
    if (requiredRoles.length > 0 && !requiredRoles.includes(userRole)) {
      res.status(403).json({ error: "Forbidden: Insufficient permissions" });
      return;
    }

    // Attach user info to request for downstream middleware/routes
    (req as any).user = {
      id: decodedPayload.id,
      role: userRole
    };

    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}
"}

{"code":"import { useEffect, useState } from "react";

interface Order {
  id: number;
  customerName: string;
  items: string[];
  status: "pending" | "shipped" | "delivered";
  orderDate: string;
}

export function OrdersPage() {
  const [orders, setOrders] = useState<Order[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchOrders();
  }, []);

  const fetchOrders = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/orders`);
      if (!response.ok) {
        throw new Error(`Failed to fetch orders: ${response.status}`);
      }
      const data = await response.json();
      setOrders(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const filteredOrders = orders.filter(order =>
    order.customerName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    order.items.some(item => item.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "system-ui, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Customer Orders</h1>

      <div style={{ marginBottom: "20px" }}>
        <input
          type="text"
          placeholder="Search orders..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        />
      </div>

      {filteredOrders.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No orders found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {filteredOrders.map(order => (
            <div key={order.id} style={{ border: "1px solid #ddd", borderRadius: "8px", padding: "15px", backgroundColor: "#f9f9f9" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <h3>{order.customerName}</h3>
                  <p><strong>Items:</strong> {order.items.join(", ")}</p>
                  <p><strong>Status:</strong> {order.status}</p>
                  <p><strong>Date:</strong> {new Date(order.orderDate).toLocaleDateString()}</p>
                </div>
                <div style={{ display: "flex", gap: "10px" }}>
                  <button
                    onClick={() => {
                      // Edit functionality would go here
                      alert(`Edit order ${order.id}`);
                    }}
                    style={{ padding: "5px 10px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
                  >
                    Edit
                  </button>
                  <button
                    onClick={async () => {
                      const confirmed = window.confirm("Are you sure you want to delete this order?");
                      if (confirmed) {
                        try {
                          const response = await fetch(`/api/orders/${order.id}`, { method: "DELETE" });
                          if (!response.ok) {
                            throw new Error(`Failed to delete order: ${response.status}`);
                          }
                          fetchOrders();
                        } catch (err) {
                          setError(err instanceof Error ? err.message : "An unknown error occurred");
                        }
                      }
                    }}
                    style={{ padding: "5px 10px", backgroundColor: "#dc3545", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      <div style={{ marginTop: "20px", textAlign: "center" }}>
        <button
