{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const isAdminRoute = req.path.startsWith('/admin') && (req.method === 'POST' || req.method === 'PUT' || req.method === 'DELETE');
  const isBookingRoute = req.path.startsWith('/bookings') && req.method === 'POST';

  // If not an admin or booking route, skip validation
  if (!isAdminRoute && !isBookingRoute) {
    next();
    return;
  }

  // Check for authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Unauthorized: Missing or invalid token' });
    return;
  }

  const token = authHeader.substring(7);

  // Verify JWT signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: 'Server configuration error: JWT_SECRET not set' });
    return;
  }

  // Simple verification - in a real app, use a proper JWT library
  const [header, payload, signature] = token.split('.');
  if (!header || !payload || !signature) {
    res.status(401).json({ error: 'Unauthorized: Invalid token format' });
    return;
  }

  // Create expected signature
  const expectedSignature = createHmac('sha256', secret)
    .update(`${header}.${payload}`)
    .digest('base64url');

  // Use timingSafeEqual to prevent timing attacks
  const expectedBuffer = Buffer.from(expectedSignature, 'base64url');
  const actualBuffer = Buffer.from(signature, 'base64url');

  if (!timingSafeEqual(expectedBuffer, actualBuffer)) {
    res.status(401).json({ error: 'Unauthorized: Invalid token signature' });
    return;
  }

  // Decode payload to check role
  try {
    const decodedPayload = JSON.parse(Buffer.from(payload, 'base64url').toString());
    const userRole = decodedPayload.role;

    if (isAdminRoute && userRole !== 'admin') {
      res.status(403).json({ error: 'Forbidden: Admin access required' });
      return;
    }

    if (isBookingRoute && userRole !== 'member') {
      res.status(403).json({ error: 'Forbidden: Member access required' });
      return;
    }

    next();
  } catch (err) {
    res.status(401).json({ error: 'Unauthorized: Invalid token payload' });
  }
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to the export endpoint
  if (req.method !== "POST" || req.path !== "/export") {
    next();
    return;
  }

  // Check if the user is authenticated and is the owner
  // This is a simplified check - in a real application, you'd verify a JWT token
  const userRole = req.headers["x-user-role"];

  if (userRole !== "owner") {
    res.status(403).json({ error: "Access denied. Owner only." });
    return;
  }

  next();
}
