export const db = new DatabaseSync("./maintenance-log.db");

interface ServiceEventRow {
  id: number;
  appliance_id: number;
  service_date: string;
  notes: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS service_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    appliance_id INTEGER NOT NULL,
    service_date TEXT NOT NULL,
    notes TEXT
  );
`;

db.exec(createTableSql);

export function getAllServiceEvents(): ServiceEventRow[] {
  const stmt = db.prepare(`SELECT * FROM service_events`);
  return stmt.all() as unknown as ServiceEventRow[];
}

export function getServiceEventById(id: number): ServiceEventRow | undefined {
  const stmt = db.prepare(`SELECT * FROM service_events WHERE id = ?`);
  return stmt.get(id) as unknown as ServiceEventRow | undefined;
}

export function insertServiceEvent(
  applianceId: number,
  serviceDate: string,
  notes: string
): number {
  const stmt = db.prepare(
    `INSERT INTO service_events (appliance_id, service_date, notes) VALUES (?, ?, ?)`
  );
  const result = stmt.run(applianceId, serviceDate, notes);
  return Number(result.lastInsertRowid);
}

export function updateServiceEvent(
  id: number,
  applianceId: number,
  serviceDate: string,
  notes: string
): void {
  const stmt = db.prepare(
    `UPDATE service_events SET appliance_id = ?, service_date = ?, notes = ? WHERE id = ?`
  );
  stmt.run(applianceId, serviceDate, notes, id);
}

export function deleteServiceEvent(id: number): void {
  const stmt = db.prepare(`DELETE FROM service_events WHERE id = ?`);
  stmt.run(id);
}

