{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would come from a database module
const mockPrescriptions = [
  { id: "1", patientId: "123", medication: "Ibuprofen", dosage: "200mg", frequency: "twice daily", status: "active" },
  { id: "2", patientId: "456", medication: "Amoxicillin", dosage: "500mg", frequency: "every 8 hours", status: "completed" }
];

const findPrescriptionById = (id: string) => {
  return mockPrescriptions.find(prescription => prescription.id === id);
};

const createPrescription = (prescription: any) => {
  const newPrescription = { ...prescription, id: String(mockPrescriptions.length + 1) };
  mockPrescriptions.push(newPrescription);
  return newPrescription;
};

const updatePrescription = (id: string, updates: any) => {
  const index = mockPrescriptions.findIndex(prescription => prescription.id === id);
  if (index !== -1) {
    mockPrescriptions[index] = { ...mockPrescriptions[index], ...updates };
    return mockPrescriptions[index];
  }
  return null;
};

const deletePrescription = (id: string) => {
  const index = mockPrescriptions.findIndex(prescription => prescription.id === id);
  if (index !== -1) {
    mockPrescriptions.splice(index, 1);
    return true;
  }
  return false;
};

// GET /prescriptions - List all prescriptions
router.get("/prescriptions", (req: Request, res: Response) => {
  res.json(mockPrescriptions);
});

// GET /prescriptions/:id - Get a specific prescription by ID
router.get("/prescriptions/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const prescription = findPrescriptionById(id);

  if (!prescription) {
    return res.status(404).json({ error: "Prescription not found" });
  }

  res.json(prescription);
});

// POST /prescriptions - Create a new prescription
router.post("/prescriptions", (req: Request, res: Response) => {
  const { patientId, medication, dosage, frequency, status } = req.body;

  // Basic validation
  if (!patientId || !medication || !dosage || !frequency) {
    return res.status(400).json({ error: "Missing required fields: patientId, medication, dosage, frequency" });
  }

  const newPrescription = createPrescription({ patientId, medication, dosage, frequency, status });

  res.status(201).json(newPrescription);
});

// PUT /prescriptions/:id - Update an existing prescription
router.put("/prescriptions/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const { patientId, medication, dosage, frequency, status } = req.body;

  const existingPrescription = findPrescriptionById(id);

  if (!existingPrescription) {
    return res.status(404).json({ error: "Prescription not found" });
  }

  const updatedPrescription = updatePrescription(id, { patientId, medication, dosage, frequency, status });

  if (!updatedPrescription) {
    return res.status(404).json({ error: "Prescription not found" });
  }

  res.json(updatedPrescription);
});

// DELETE /prescriptions/:id - Delete a prescription
router.delete("/prescriptions/:id", (req: Request, res: Response) => {
  const id = req.params.id;

  const deleted = deletePrescription(id);

  if (!deleted) {
    return res.status(404).json({ error: "Prescription not found" });
  }

  res.json({ message: "Prescription deleted successfully" });
});
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface ShiftSignup {
  id: number;
  volunteerId: number;
  shiftId: number;
  signupTimestamp: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS shift_signups (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    volunteerId INTEGER NOT NULL,
    shiftId INTEGER NOT NULL,
    signupTimestamp TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllShiftSignups(): ShiftSignup[] {
  const stmt = db.prepare(`SELECT * FROM shift_signups;`);
  return stmt.all() as unknown as ShiftSignup[];
}

export function getShiftSignupById(id: number): ShiftSignup | undefined {
  const stmt = db.prepare(`SELECT * FROM shift_signups WHERE id = ?;`);
  return stmt.get(id) as unknown as ShiftSignup | undefined;
}

export function insertShiftSignup(
  volunteerId: number,
  shiftId: number,
  signupTimestamp: string
): number {
  const stmt = db.prepare(
    `INSERT INTO shift_signups (volunteerId, shiftId, signupTimestamp) VALUES (?, ?, ?);`
  );
  const result = stmt.run(volunteerId, shiftId, signupTimestamp);
  return Number(result.lastInsertRowid);
}

export function updateShiftSignup(
  id: number,
  volunteerId: number,
  shiftId: number,
  signupTimestamp: string
): void {
  const stmt = db.prepare(
    `UPDATE shift_signups SET volunteerId = ?, shiftId = ?, signupTimestamp = ? WHERE id = ?;`
  );
  stmt.run(volunteerId, shiftId, signupTimestamp, id);
}

export function deleteShiftSignup(id: number): void {
  const stmt = db.prepare(`DELETE FROM shift_signups WHERE id = ?;`);
  stmt.run(id);
}

// Insert sample data if table is empty
