{"code":"import { useEffect, useState } from "react";

interface AttendanceRecord {
  id: string;
  singerId: string;
  date: string;
  status: "present" | "absent" | "late";
}

export function AttendanceMarkPanel() {
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [singerId, setSingerId] = useState("1"); // Default singer ID

  useEffect(() => {
    fetchAttendanceRecords();
  }, []);

  const fetchAttendanceRecords = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/attendance-api/`);
      if (!response.ok) {
        throw new Error(`Failed to fetch records: ${response.status}`);
      }
      const data = await response.json();
      setRecords(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleMarkAttendance = async (status: "present" | "absent" | "late") => {
    try {
      const today = new Date().toISOString().split('T')[0];
      const response = await fetch(`/api/attendance-api/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          singerId,
          date: today,
          status
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to mark attendance: ${response.status}`);
      }

      await fetchAttendanceRecords();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div style={{
      maxWidth: "600px",
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
    }}>
      <h1 style={{ textAlign: "center" }}>Attendance Mark Panel</h1>

      <div style={{ marginBottom: "20px" }}>
        <label htmlFor="singerId" style={{ display: "block", marginBottom: "5px" }}>
          Singer ID:
        </label>
        <input
          id="singerId"
          type="text"
          value={singerId}
          onChange={(e) => setSingerId(e.target.value)}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        />
      </div>

      <div style={{ display: "flex", gap: "10px", justifyContent: "center", marginBottom: "20px" }}>
        <button
          onClick={() => handleMarkAttendance("present")}
          style={{
            padding: "10px 20px",
            backgroundColor: "#4CAF50",
            color: "white",
            border: "none",
            borderRadius: "4px",
            cursor: "pointer"
          }}
        >
          Mark Present
        </button>
        <button
          onClick={() => handleMarkAttendance("absent")}
          style={{
            padding: "10px 20px",
            backgroundColor: "#f44336",
            color: "white",
            border: "none",
            borderRadius: "4px",
            cursor: "pointer"
          }}
        >
          Mark Absent
        </button>
        <button
          onClick={() => handleMarkAttendance("late")}
          style={{
            padding: "10px 20px",
            backgroundColor: "#ff9800",
            color: "white",
            border: "none",
            borderRadius: "4px",
            cursor: "pointer"
          }}
        >
          Mark Late
        </button>
      </div>

      <h2 style={{ textAlign: "center" }}>Your Records</h2>
      {records.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>No attendance records found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {records.map((record) => (
            <div
              key={record.id}
              style={{
                border: "1px solid #ccc",
                borderRadius: "4px",
                padding: "10px",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center"
              }}
            >
              <div>
                <strong>Date:</strong> {record.date} | 
                <strong>Status:</strong> {record.status}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

interface MilkCollection {
  id: number;
  date: string;
  quantity: number;
  farmerId: number;
}

export function CollectionListPage() {
  const [collections, setCollections] = useState<MilkCollection[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);

  const itemsPerPage = 10;

  useEffect(() => {
    fetchCollections();
  }, [currentPage, searchTerm]);

  const fetchCollections = async () => {
    try {
      setLoading(true);
      // In a real app, this would be an API call
      // For demo purposes, we'll simulate data
      await new Promise(resolve => setTimeout(resolve, 500));

      // Mock data
      const mockCollections: MilkCollection[] = [
        { id: 1, date: "2023-06-01", quantity: 120, farmerId: 101 },
        { id: 2, date: "2023-06-02", quantity: 150, farmerId: 102 },
        { id: 3, date: "2023-06-03", quantity: 90, farmerId: 103 },
        { id: 4, date: "2023-06-04", quantity: 200, farmerId: 104 },
        { id: 5, date: "2023-06-05", quantity: 180, farmerId: 105 },
        { id: 6, date: "2023-06-06", quantity: 110, farmerId: 106 },
        { id: 7, date: "2023-06-07", quantity: 160, farmerId: 107 },
        { id: 8, date: "2023-06-08", quantity: 130, farmerId: 108 },
        { id: 9, date: "2023-06-09", quantity: 140, farmerId: 109 },
        { id: 10, date: "2023-06-10", quantity: 170, farmerId: 110 },
        { id: 11, date: "2023-06-11", quantity: 190, farmerId: 111 },
        { id: 12, date: "2023-06-12", quantity: 100, farmerId: 112 },
      ];

      // Filter based on search term
      const filtered = mockCollections.filter(collection => 
        collection.date.includes(searchTerm) || 
        collection.farmerId.toString().includes(searchTerm)
      );

      const startIndex = (currentPage - 1) * itemsPerPage;
      const paginated = filtered.slice(startIndex, startIndex + itemsPerPage);

      setCollections(paginated);
      setTotalPages(Math.ceil(filtered.length / itemsPerPage));
      setError(null);
    } catch (err) {
      setError("Failed to load collections");
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
    setCurrentPage(1); // Reset to first page when searching
  };

  const handlePageChange = (page: number) => {
    setCurrentPage(page);
  };

  const renderPagination = () => {
    const pages = [];
    for (let i = 1; i <= totalPages; i++) {
      pages.push(
        <button
          key={i}
