{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/tmp/manuscript-submission-tracker.db"
);

interface SubmissionRow {
  id: number;
  content: string;
  author_id: number;
  category: string;
  review_status: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS submissions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    content TEXT NOT NULL,
    author_id INTEGER NOT NULL,
    category TEXT NOT NULL,
    review_status TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllSubmissions(): SubmissionRow[] {
  const stmt = db.prepare(`
    SELECT * FROM submissions
  `);
  return stmt.all() as unknown as SubmissionRow[];
}

export function getSubmissionById(id: number): SubmissionRow | undefined {
  const stmt = db.prepare(`
    SELECT * FROM submissions WHERE id = ?
  `);
  return stmt.get(id) as unknown as SubmissionRow | undefined;
}

export function insertSubmission(
  content: string,
  authorId: number,
  category: string,
  reviewStatus: string
): number {
  const stmt = db.prepare(`
    INSERT INTO submissions (content, author_id, category, review_status)
    VALUES (?, ?, ?, ?)
  `);
  const result = stmt.run(content, authorId, category, reviewStatus);
  return Number(result.lastInsertRowid);
}

export function updateSubmission(
  id: number,
  content: string,
  authorId: number,
  category: string,
  reviewStatus: string
): void {
  const stmt = db.prepare(`
    UPDATE submissions
    SET content = ?, author_id = ?, category = ?, review_status = ?
    WHERE id = ?
  `);
  stmt.run(content, authorId, category, reviewStatus, id);
}

export function deleteSubmission(id: number): void {
  const stmt = db.prepare(`
    DELETE FROM submissions WHERE id = ?
  `);
  stmt.run(id);
}

// Seed data
if (getAllSubmissions().length === 0) {
  insertSubmission(
    "The Impact of Climate Change on Marine Ecosystems",
