    "Sustainable Agriculture Practices in Urban Environments",
    4,
    "Environmental Science",
    "Pending"
  );
  insertSubmission(
    "The Role of Artificial Intelligence in Modern Healthcare",
    5,
    "Medicine",
    "In Progress"
  );
}
