{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockCreateBooking = (bookingData: any) => {
  return {
    id: Math.floor(Math.random() * 1000),
    ...bookingData,
    createdAt: new Date().toISOString()
  };
};

const mockGetBookingById = (id: string) => {
  // Simulate finding a booking or returning null
  return Math.random() > 0.5 ? {
    id,
    carId: "car123",
    startDate: "2023-06-15",
    endDate: "2023-06-17",
    status: "confirmed"
  } : null;
};

const mockUpdateBooking = (id: string, updates: any) => {
  // Simulate updating a booking
  return {
    id,
    ...updates,
    updatedAt: new Date().toISOString()
  };
};

const mockCancelBooking = (id: string) => {
  // Simulate canceling a booking
  return true;
};

// Helper to validate date format (YYYY-MM-DD)
const isValidDate = (dateString: string): boolean => {
  const regex = /^\d{4}-\d{2}-\d{2}$/;
  return regex.test(dateString);
};

// Helper to validate date range
const isValidDateRange = (startDate: string, endDate: string): boolean => {
  const start = new Date(startDate);
  const end = new Date(endDate);
  return start <= end;
};

// GET /bookings/:id
router.get("/bookings/:id", (req: Request, res: Response) => {
  const { id } = req.params;

  const booking = mockGetBookingById(id);

  if (!booking) {
    return res.status(404).json({ error: "Booking not found" });
  }

  return res.json(booking);
});

// POST /bookings
router.post("/bookings", (req: Request, res: Response) => {
  const { carId, startDate, endDate } = req.body;

  // Validate required fields
  if (!carId || !startDate || !endDate) {
    return res.status(400).json({ error: "Missing required fields: carId, startDate, endDate" });
  }

  // Validate date formats
  if (!isValidDate(startDate) || !isValidDate(endDate)) {
    return res.status(400).json({ error: "Invalid date format. Expected YYYY-MM-DD" });
  }

  // Validate date range
  if (!isValidDateRange(startDate, endDate)) {
    return res.status(400).json({ error: "End date must be after or equal to start date" });
  }

  // Create booking
  const newBooking = mockCreateBooking({ carId, startDate, endDate });

  return res.status(201).json(newBooking);
});

// PUT /bookings/:id
router.put("/bookings/:id", (req: Request, res: Response) => {
  const { id } = req.params;
  const { startDate, endDate } = req.body;

  // Validate date formats
  if (startDate && !isValidDate(startDate)) {
    return res.status(400).json({ error: "Invalid date format. Expected YYYY-MM-DD" });
  }

  if (endDate && !isValidDate(endDate)) {
    return res.status(400).json({ error: "Invalid date format. Expected YYYY-MM-DD" });
  }

  // Validate date range
  if (startDate && endDate && !isValidDateRange(startDate, endDate)) {
    return res.status(400).json({ error: "End date must be after or equal to start date" });
  }

  // Update booking
  const updatedBooking = mockUpdateBooking(id, { startDate, endDate });

  return res.json(updatedBooking);
});

// DELETE /bookings/:id
router.delete("/bookings/:id", (req: Request, res: Response) => {
  const { id } = req.params;

  const result = mockCancelBooking(id);

  if (!result) {
    return res.status(404).json({ error: "Booking not found" });
  }

  return res.json({ message: "Booking cancelled successfully" });
});
"}

