{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteAttendanceRecord,
  getAllAttendanceRecords,
  getAttendanceRecordById,
  insertAttendanceRecord,
  updateAttendanceRecord
} from "../db/attendance-records-table";

export const router = Router();

// Get all attendance records
router.get("/", (req: Request, res: Response) => {
  const records = getAllAttendanceRecords();
  res.json(records);
});

// Get a specific attendance record by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const record = getAttendanceRecordById(id);

  if (!record) {
    return res.status(404).json({ error: "Attendance record not found" });
  }

  res.json(record);
});

// Create a new attendance record
router.post("/", (req: Request, res: Response) => {
  const { member_id, date, presence_status } = req.body;

  // Validate required fields
  if (!member_id || !date || !presence_status) {
    return res.status(400).json({ error: "Missing required fields: member_id, date, presence_status" });
  }

  // Validate presence_status
  const validStatuses = ["present", "absent", "late"];
  if (!validStatuses.includes(presence_status)) {
    return res.status(400).json({ error: "Invalid presence_status. Must be 'present', 'absent', or 'late'" });
  }

  try {
    const newId = insertAttendanceRecord(member_id, date, presence_status);
    const newRecord = getAttendanceRecordById(newId);

    if (!newRecord) {
      return res.status(500).json({ error: "Failed to retrieve created record" });
    }

    res.status(201).json(newRecord);
  } catch (error) {
    res.status(500).json({ error: "Failed to create attendance record" });
  }
});

// Update an existing attendance record
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { member_id, date, presence_status } = req.body;

  // Validate required fields
  if (!member_id || !date || !presence_status) {
    return res.status(400).json({ error: "Missing required fields: member_id, date, presence_status" });
  }

  // Validate presence_status
  const validStatuses = ["present", "absent", "late"];
  if (!validStatuses.includes(presence_status)) {
    return res.status(400).json({ error: "Invalid presence_status. Must be 'present', 'absent', or 'late'" });
  }

  const existingRecord = getAttendanceRecordById(id);

  if (!existingRecord) {
    return res.status(404).json({ error: "Attendance record not found" });
  }

  try {
    updateAttendanceRecord(id, member_id, date, presence_status);
    const updatedRecord = getAttendanceRecordById(id);

    if (!updatedRecord) {
      return res.status(500).json({ error: "Failed to retrieve updated record" });
    }

    res.json(updatedRecord);
  } catch (error) {
    res.status(500).json({ error: "Failed to update attendance record" });
  }
});

// Delete an attendance record (supervisor-only access)
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  const existingRecord = getAttendanceRecordById(id);

  if (!existingRecord) {
    return res.status(404).json({ error: "Attendance record not found" });
  }

  try {
    deleteAttendanceRecord(id);
    res.json({ message: "Attendance record deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete attendance record" });
  }
});
"}

