export const router = Router();

// In-memory storage for carts (in a real app, this would be a database)
const carts: Map<string, any[]> = new Map();

// Helper to get or create a cart for a user
const getUserCart = (userId: string): any[] => {
  if (!carts.has(userId)) {
    carts.set(userId, []);
  }
  return carts.get(userId)!;
};

// Add item to cart
router.post("/cart/:userId/items", (req: Request, res: Response) => {
  const { userId } = req.params;
  const { itemId, quantity } = req.body;

  if (!itemId || quantity === undefined || quantity <= 0) {
    return res.status(400).json({ error: "Item ID and valid quantity required" });
  }

  const userCart = getUserCart(userId);
  const existingItemIndex = userCart.findIndex(item => item.itemId === itemId);

  if (existingItemIndex >= 0) {
    userCart[existingItemIndex].quantity += quantity;
  } else {
    userCart.push({ itemId, quantity });
  }

  return res.status(201).json({ message: "Item added to cart", cart: userCart });
});

// Remove item from cart
router.delete("/cart/:userId/items/:itemId", (req: Request, res: Response) => {
  const { userId, itemId } = req.params;

  const userCart = getUserCart(userId);
  const itemIndex = userCart.findIndex(item => item.itemId === itemId);

  if (itemIndex < 0) {
    return res.status(404).json({ error: "Item not found in cart" });
  }

  userCart.splice(itemIndex, 1);
  return res.json({ message: "Item removed from cart", cart: userCart });
});

// Get cart items
router.get("/cart/:userId", (req: Request, res: Response) => {
  const { userId } = req.params;
  const userCart = getUserCart(userId);
  return res.json({ items: userCart });
});

// Clear cart
router.delete("/cart/:userId", (req: Request, res: Response) => {
  const { userId } = req.params;
  carts.set(userId, []);
  return res.json({ message: "Cart cleared" });
});
"}

