{"code":"import { Router, type Request, type Response } from "express";
import { db, deleteAudition, getAllAuditions, getAuditionById, insertAudition, updateAudition } from "../db/auditions-table";

export const router = Router();

// Get all auditions
router.get("/", (req: Request, res: Response) => {
  try {
    const auditions = getAllAuditions();
    res.json(auditions);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch auditions" });
  }
});

// Get a specific audition by ID
router.get("/:actorId/:showId/:slotId", (req: Request, res: Response) => {
  try {
    const { actorId, showId, slotId } = req.params;
    const audition = getAuditionById(
      Number(actorId),
      Number(showId),
      Number(slotId)
    );

    if (!audition) {
      return res.status(404).json({ error: "Audition not found" });
    }

    res.json(audition);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch audition" });
  }
});

// Create a new audition
router.post("/", (req: Request, res: Response) => {
  try {
    const { actor_id, show_id, slot_id, casting_note } = req.body;

    if (typeof actor_id !== "number" || typeof show_id !== "number" || typeof slot_id !== "number") {
      return res.status(400).json({ error: "Invalid input data" });
    }

    const newAuditionId = insertAudition({
      actor_id,
      show_id,
      slot_id,
      casting_note
    });

    res.status(201).json({ id: newAuditionId });
  } catch (error) {
    res.status(500).json({ error: "Failed to create audition" });
  }
});

// Update an audition
router.put("/:actorId/:showId/:slotId", (req: Request, res: Response) => {
  try {
    const { actorId, showId, slotId } = req.params;
    const { casting_note } = req.body;

    if (typeof casting_note !== "string") {
      return res.status(400).json({ error: "Invalid input data" });
    }

    const updatedRows = updateAudition(
      Number(actorId),
      Number(showId),
      Number(slotId),
      casting_note
    );

    if (updatedRows === 0) {
      return res.status(404).json({ error: "Audition not found" });
    }

    res.json({ message: "Audition updated successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to update audition" });
  }
});

// Delete an audition
router.delete("/:actorId/:showId/:slotId", (req: Request, res: Response) => {
  try {
    const { actorId, showId, slotId } = req.params;

    const deletedRows = deleteAudition(
      Number(actorId),
      Number(showId),
      Number(slotId)
    );

    if (deletedRows === 0) {
      return res.status(404).json({ error: "Audition not found" });
    }

    res.json({ message: "Audition deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete audition" });
  }
});
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;

  if (!jwtSecret) {
    res.status(500).json({ error: "JWT secret not configured" });
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    const [header, payload, signature] = parts;

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // If we get here, token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Authentication failed" });
  }
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteTimesheetEntry,
  getAllTimesheetEntries,
  getTimesheetEntryById,
  insertTimesheetEntry,
  updateTimesheetEntry
} from "../db/timesheets-table";

export const router = Router();

// Get all timesheet entries for the logged-in user
router.get("/", (req: Request, res: Response) => {
  try {
    const entries = getAllTimesheetEntries();
    return res.json(entries);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch timesheet entries" });
  }
});

// Get a specific timesheet entry by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid ID format" });
  }

  const entry = getTimesheetEntryById(id);

  if (!entry) {
    return res.status(404).json({ error: "Timesheet entry not found" });
  }

  return res.json(entry);
});

// Create a new timesheet entry
router.post("/", (req: Request, res: Response) => {
  const { associateId, date, rate, description } = req.body;

  // Validate required fields
  if (!associateId || !date || !rate || !description) {
    return res.status(400).json({ error: "Missing required fields: associateId, date, rate, description" });
  }

  try {
    const newId = insertTimesheetEntry(associateId, date, rate, description);
    const newEntry = getTimesheetEntryById(newId);

    if (!newEntry) {
      return res.status(500).json({ error: "Failed to retrieve created entry" });
    }

    return res.status(201).json(newEntry);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create timesheet entry" });
  }
});

// Update an existing timesheet entry
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { associateId, date, rate, description } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid ID format" });
  }

  // Validate required fields
  if (!associateId || !date || !rate || !description) {
    return res.status(400).json({ error: "Missing required fields: associateId, date, rate, description" });
  }

  const existingEntry = getTimesheetEntryById(id);

  if (!existingEntry) {
    return res.status(404).json({ error: "Timesheet entry not found" });
  }

  try {
    updateTimesheetEntry(id, associateId, date, rate, description);
    const updatedEntry = getTimesheetEntryById(id);

    if (!updatedEntry) {
      return res.status(500).json({ error: "Failed to retrieve updated entry" });
    }

    return res.json(updatedEntry);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update timesheet entry" });
  }
});

// Delete a timesheet entry
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid ID format" });
  }

  const existingEntry = getTimesheetEntryById(id);

  if (!existingEntry) {
    return res.status(404).json({ error: "Timesheet entry not found" });
  }

  try {
    deleteTimesheetEntry(id);
    return res.json({ message: "Timesheet entry deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete timesheet entry" });
  }
});
"}

