{"code":"import { useEffect, useState } from "react";

interface Challenge {
  id: number;
  name: string;
  description: string;
  startDate: string;
  endDate: string;
  targetSteps: number;
}

export function ChallengeManagementPage() {
  const [challenges, setChallenges] = useState<Challenge[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Form state
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [targetSteps, setTargetSteps] = useState(0);
  const [editingId, setEditingId] = useState<number | null>(null);

  useEffect(() => {
    fetchChallenges();
  }, []);

  const fetchChallenges = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/challenges');
      if (!response.ok) {
        throw new Error('Failed to fetch challenges');
      }
      const data = await response.json();
      setChallenges(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const challengeData = {
      name,
      description,
      startDate,
      endDate,
      targetSteps
    };

    try {
      const response = editingId 
        ? await fetch(`/api/challenges/${editingId}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(challengeData)
          })
        : await fetch('/api/challenges', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(challengeData)
          });

      if (!response.ok) {
        throw new Error('Failed to save challenge');
      }

      // Reset form
      setName("");
      setDescription("");
      setStartDate("");
      setEndDate("");
      setTargetSteps(0);
      setEditingId(null);

      // Refresh data
      await fetchChallenges();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleEdit = (challenge: Challenge) => {
    setName(challenge.name);
    setDescription(challenge.description);
    setStartDate(challenge.startDate);
    setEndDate(challenge.endDate);
    setTargetSteps(challenge.targetSteps);
    setEditingId(challenge.id);
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/challenges/${id}`, {
        method: 'DELETE'
      });

      if (!response.ok) {
        throw new Error('Failed to delete challenge');
      }

      // Refresh data
      await fetchChallenges();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleCancel = () => {
    setName("");
    setDescription("");
    setStartDate("");
    setEndDate("");
    setTargetSteps(0);
    setEditingId(null);
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Challenge Management</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px' }}>Name:</label>
          <input
            type="text"
            value={name}
            onChange={(e) => setName(e.target.value)}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ddd' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px' }}>Description:</label>
          <textarea
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ddd', minHeight: '60px' }}
            required
          />
        </div>

        <div style={{ display: 'flex', gap: '15px', marginBottom: '15px' }}>
          <div style={{ flex: 1 }}>
            <label style={{ display: 'block', marginBottom: '5px' }}>Start Date:</label>
            <input
              type="date"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
              style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ddd' }}
              required
            />
          </div>
          <div style={{ flex: 1 }}>
            <label style={{ display: 'block', marginBottom: '5px' }}>End Date:</label>
            <input
              type="date"
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
              style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ddd' }}
              required
            />
          </div>
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px' }}>Target Steps:</label>
          <input
            type="number"
            value={targetSteps}
            onChange={(e) => setTargetSteps(Number(e.target.value))}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ddd' }}
            min="0"
            required
          />
        </div>

        <div style={{ display: 'flex', gap: '10px' }}>
          <button 
            type="submit" 
            style={{ 
              backgroundColor: '#007bff', 
              color: 'white', 
              border: 'none', 
              padding: '10px 20px', 
              borderRadius: '4px', 
              cursor: 'pointer' 
            }}
          >
            {editingId ? 'Update Challenge' : 'Create Challenge'}
          </button>

          {editingId && (
            <button 
              type="button" 
              onClick={handleCancel}
              style={{ 
                backgroundColor: '#6c757d', 
                color: 'white', 
                border: 'none', 
                padding: '10px 20px', 
                borderRadius: '4px', 
                cursor: 'pointer' 
              }}
            >
              Cancel
            </button>
          )}
        </div>
      </form>

      <h2>Current Challenges</h2>

      {challenges.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No challenges found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {challenges.map((challenge) => (
            <div 
              key={challenge.id} 
              style={{ 
                border: '1px solid #ccc', 
                borderRadius: '8px', 
                padding: '15px', 
                display: 'flex', 
                flexDirection: 'column', 
                gap: '10px' 
              }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <h3>{challenge.name}</h3>
                <div style={{ display: 'flex', gap: '5px' }}>
                  <button 
                    onClick={() => handleEdit(challenge)}
                    style={{ 
                      backgroundColor: '#28a745', 
                      color: 'white', 
                      border: 'none', 
                      padding: '5px 10px', 
                      borderRadius: '4px', 
                      cursor: 'pointer' 
                    }}
                  >
                    Edit
                  </button>
                  <button 
                    onClick={() => handleDelete(challenge.id)}
                    style={{ 
                      backgroundColor: '#dc3545', 
                      color: 'white', 
                      border: 'none', 
                      padding: '5px 10px', 
                      borderRadius: '4px', 
                      cursor: 'pointer' 
                    }}
                  >
                    Delete
                  </button>
                </div>
              </div>
              <p>{challenge.description}</p>
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.9em', color: '#666' }}>
                <span>Start: {new Date(challenge.startDate).toLocaleDateString()}</span>
                <span>End: {new Date(challenge.endDate).toLocaleDateString()}</span>
                <span>Target: {challenge.targetSteps.toLocaleString()} steps</span>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

interface Parcel {
  id: string;
  trackingNumber: string;
  status: string;
  destination: string;
  weight: number;
  createdAt: string;
}

interface Statistics {
  totalParcels: number;
  pendingParcels: number;
  deliveredParcels: number;
}

export function AdminDashboard() {
  const [parcels, setParcels] = useState<Parcel[]>([]);
  const [stats, setStats] = useState<Statistics | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchDashboardData() {
      try {
        const [parcelsResponse, statsResponse] = await Promise.all([
          fetch('/api/parcels'),
          fetch('/api/statistics')
        ]);

        if (!parcelsResponse.ok || !statsResponse.ok) {
          throw new Error('Failed to fetch dashboard data');
        }

        const parcelsData = await parcelsResponse.json();
        const statsData = await statsResponse.json();

        setParcels(parcelsData);
        setStats(statsData);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
        setLoading(false);
      }
    }

    fetchDashboardData();
  }, []);

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Admin Dashboard</h1>

      {stats && (
        <div style={{ display: 'flex', justifyContent: 'space-around', flexWrap: 'wrap', marginBottom: '30px' }}>
          <div style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px', margin: '10px', minWidth: '200px' }}>
            <h2>Total Parcels</h2>
            <p style={{ fontSize: '24px', fontWeight: 'bold' }}>{stats.totalParcels}</p>
          </div>
          <div style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px', margin: '10px', minWidth: '200px' }}>
            <h2>Pending Parcels</h2>
