const mockOrders = [
  { id: "1", customerId: "123", items: ["burger", "fries"], status: "preparing", pickupTime: "2023-05-15T14:30:00Z" },
  { id: "2", customerId: "456", items: ["pizza", "soda"], status: "ready", pickupTime: "2023-05-15T15:00:00Z" }
];

const findOrderById = (id: string) => {
  return mockOrders.find(order => order.id === id);
};

const createOrder = (orderData: any) => {
  const newOrder = {
    id: String(mockOrders.length + 1),
    customerId: orderData.customerId,
    items: orderData.items,
    status: "preparing",
    pickupTime: new Date().toISOString()
  };
  mockOrders.push(newOrder);
  return newOrder;
};

const updateOrderStatus = (id: string, status: string) => {
  const orderIndex = mockOrders.findIndex(order => order.id === id);
  if (orderIndex !== -1) {
    mockOrders[orderIndex].status = status;
    return mockOrders[orderIndex];
  }
  return null;
};

// List all orders
router.get("/orders", (req: Request, res: Response) => {
  res.json(mockOrders);
});

// Get one order by ID
router.get("/orders/:id", (req: Request, res: Response) => {
  const order = findOrderById(req.params.id);
  if (!order) {
    return res.status(404).json({ error: "Order not found" });
  }
  res.json(order);
});

// Create a new order
router.post("/orders", (req: Request, res: Response) => {
  const { customerId, items } = req.body;

  if (!customerId || !items || !Array.isArray(items)) {
    return res.status(400).json({ error: "Invalid order data" });
  }

  const newOrder = createOrder({ customerId, items });
  res.status(201).json(newOrder);
});

// Update order status
router.put("/orders/:id/status", (req: Request, res: Response) => {
  const { id } = req.params;
  const { status } = req.body;

  if (!status) {
    return res.status(400).json({ error: "Status is required" });
  }

  const updatedOrder = updateOrderStatus(id, status);

  if (!updatedOrder) {
    return res.status(404).json({ error: "Order not found" });
  }

  res.json(updatedOrder);
});

// Delete an order
router.delete("/orders/:id", (req: Request, res: Response) => {
  const orderId = req.params.id;
  const orderIndex = mockOrders.findIndex(order => order.id === orderId);

  if (orderIndex === -1) {
    return res.status(404).json({ error: "Order not found" });
  }

