export const db = new DatabaseSync("./incidents.db");

interface IncidentRow {
  id: number;
  resident_id: number;
  description: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS incidents (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    resident_id INTEGER NOT NULL,
    description TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllIncidents(): IncidentRow[] {
  const stmt = db.prepare("SELECT * FROM incidents");
  return stmt.all() as unknown as IncidentRow[];
}

export function getIncidentById(id: number): IncidentRow | undefined {
  const stmt = db.prepare("SELECT * FROM incidents WHERE id = ?");
  return stmt.get(id) as unknown as IncidentRow | undefined;
}

export function insertIncident(residentId: number, description: string): number {
  const stmt = db.prepare(
    "INSERT INTO incidents (resident_id, description) VALUES (?, ?)"
  );
  const result = stmt.run(residentId, description);
  return Number(result.lastInsertRowid);
}

export function updateIncident(id: number, description: string): void {
  const stmt = db.prepare(
    "UPDATE incidents SET description = ? WHERE id = ?"
  );
  stmt.run(description, id);
}

export function deleteIncident(id: number): void {
  const stmt = db.prepare("DELETE FROM incidents WHERE id = ?");
  stmt.run(id);
}

