{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "file:./aquarium_feeding_schedule.db?mode=rwc&cache=shared"
);

interface Keeper {
  id: number;
  role: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS keepers (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    role TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllKeepers(): Keeper[] {
  const stmt = db.prepare(`SELECT * FROM keepers`);
  return stmt.all() as unknown as Keeper[];
}

export function getKeeperById(id: number): Keeper | undefined {
  const stmt = db.prepare(`SELECT * FROM keepers WHERE id = ?`);
  return stmt.get(id) as unknown as Keeper | undefined;
}

export function insertKeeper(role: string): number {
  const stmt = db.prepare(`INSERT INTO keepers (role) VALUES (?)`);
  const result = stmt.run(role);
  return Number(result.lastInsertRowid);
}

export function updateKeeper(id: number, role: string): void {
  const stmt = db.prepare(`UPDATE keepers SET role = ? WHERE id = ?`);
  stmt.run(role, id);
}

export function deleteKeeper(id: number): void {
  const stmt = db.prepare(`DELETE FROM keepers WHERE id = ?`);
  stmt.run(id);
}

// Insert sample data if table is empty
if (getAllKeepers().length === 0) {
  insertKeeper("Aquatic Specialist");
  insertKeeper("Marine Biologist");
  insertKeeper("Aquarium Technician");
  insertKeeper("Zookeeper");
  insertKeeper("Animal Care Assistant");
}
"}

