{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockDatabase = {
  findAll: () => Promise.resolve([
    { id: 1, name: "Apples", quantity: 50, price: 1.2 },
    { id: 2, name: "Bananas", quantity: 30, price: 0.8 }
  ]),
  findById: (id: number) => Promise.resolve(
    [{ id: 1, name: "Apples", quantity: 50, price: 1.2 },
     { id: 2, name: "Bananas", quantity: 30, price: 0.8 }]
      .find(item => item.id === id)
  ),
  create: (item: any) => Promise.resolve({
    id: Date.now(),
    ...item
  }),
  update: (id: number, updates: any) => Promise.resolve({
    id,
    ...updates
  }),
  delete: (id: number) => Promise.resolve(true)
};

// List all inventory items
router.get("/", async (req: Request, res: Response) => {
  try {
    const items = await mockDatabase.findAll();
    res.json(items);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch items" });
  }
});

// Get one inventory item by ID
router.get("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const item = await mockDatabase.findById(id);
    if (!item) {
      return res.status(404).json({ error: "Item not found" });
    }

    res.json(item);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch item" });
  }
});

// Create a new inventory item
router.post("/", async (req: Request, res: Response) => {
  try {
    const { name, quantity, price } = req.body;

    if (!name || quantity === undefined || price === undefined) {
      return res.status(400).json({ error: "Name, quantity, and price are required" });
    }

    const newItem = await mockDatabase.create({
      name,
      quantity,
      price
    });

    res.status(201).json(newItem);
  } catch (error) {
    res.status(500).json({ error: "Failed to create item" });
  }
});

// Update an existing inventory item
router.put("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const { name, quantity, price } = req.body;

    if (quantity === undefined || price === undefined) {
      return res.status(400).json({ error: "Quantity and price are required" });
    }

    const updatedItem = await mockDatabase.update(id, { name, quantity, price });

    if (!updatedItem) {
      return res.status(404).json({ error: "Item not found" });
    }

    res.json(updatedItem);
  } catch (error) {
    res.status(500).json({ error: "Failed to update item" });
  }
});

// Delete an inventory item
router.delete("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const deleted = await mockDatabase.delete(id);

    if (!deleted) {
      return res.status(404).json({ error: "Item not found" });
    }

    res.json({ message: "Item deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete item" });
  }
});
"}

