{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to the lock endpoint
  if (req.method !== "POST" || req.path !== "/lock") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Basic token structure validation
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  const [header, payload, signature] = parts;

  // Verify signature using HMAC-SHA256
  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  const actualSignature = signature;

  // Use timingSafeEqual to prevent timing attacks
  const isValid = timingSafeEqual(
    Buffer.from(expectedSignature, "base64url"),
    Buffer.from(actualSignature, "base64url")
  );

  if (!isValid) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // Decode payload to check role
  try {
    const decodedPayload = JSON.parse(
      Buffer.from(payload, "base64url").toString()
    );

    if (decodedPayload.role !== "staff") {
      res.status(403).json({ error: "Access denied: staff only" });
      return;
    }

    next();
  } catch (err) {
    res.status(401).json({ error: "Invalid token payload" });
  }
}
"}

{"code":"import { useEffect, useState } from "react";

interface FormData {
  childName: string;
  sessionDate: string;
  parentEmail: string;
  parentPhone: string;
}

interface Registration {
  id: string;
  childName: string;
  sessionDate: string;
  parentEmail: string;
  parentPhone: string;
}

export function RegistrationForm() {
  const [formData, setFormData] = useState<FormData>({
    childName: "",
    sessionDate: "",
    parentEmail: "",
    parentPhone: "",
  });

  const [registrations, setRegistrations] = useState<Registration[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchRegistrations();
  }, []);

  const fetchRegistrations = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/registrations-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch registrations: ${response.status}`);
      }
      const data = await response.json();
      setRegistrations(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/registrations-api/", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(formData),
      });

      if (!response.ok) {
        throw new Error(`Failed to submit registration: ${response.status}`);
      }

      // Reset form after successful submission
      setFormData({
        childName: "",
        sessionDate: "",
        parentEmail: "",
        parentPhone: "",
      });

      // Refresh the list
      await fetchRegistrations();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
