{"code":"import { Router, type Request, type Response } from "express";
import {
  getAllCheckouts,
  getCheckoutById,
  insertCheckout,
  updateCheckout,
  deleteCheckout
} from "../db/equipment-checkouts-table";

export const router = Router();

// GET /api/checkout - Get all checkouts
router.get("/", (req: Request, res: Response) => {
  const checkouts = getAllCheckouts();
  res.json(checkouts);
});

// GET /api/checkout/:id - Get a specific checkout by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid checkout ID" });
  }

  const checkout = getCheckoutById(id);

  if (!checkout) {
    return res.status(404).json({ error: "Checkout not found" });
  }

  res.json(checkout);
});

// POST /api/checkout - Create a new checkout
router.post("/", (req: Request, res: Response) => {
  const { equipmentId, userId, checkoutDate, returnDate } = req.body;

  if (!equipmentId || !userId || !checkoutDate) {
    return res.status(400).json({ error: "Missing required fields: equipmentId, userId, checkoutDate" });
  }

  const id = insertCheckout(
    Number(equipmentId),
    Number(userId),
    checkoutDate,
    returnDate || null
  );

  res.status(201).json({ id });
});

// PUT /api/checkout/:id - Update an existing checkout
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { equipmentId, userId, checkoutDate, returnDate } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid checkout ID" });
  }

  if (!equipmentId || !userId || !checkoutDate) {
    return res.status(400).json({ error: "Missing required fields: equipmentId, userId, checkoutDate" });
  }

  const existingCheckout = getCheckoutById(id);

  if (!existingCheckout) {
    return res.status(404).json({ error: "Checkout not found" });
  }

  updateCheckout(
    id,
    Number(equipmentId),
    Number(userId),
    checkoutDate,
    returnDate || null
  );

  res.json({ message: "Checkout updated successfully" });
});

// DELETE /api/checkout/:id - Delete a checkout
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid checkout ID" });
  }

  const existingCheckout = getCheckoutById(id);

  if (!existingCheckout) {
    return res.status(404).json({ error: "Checkout not found" });
  }

  deleteCheckout(id);

  res.json({ message: "Checkout deleted successfully" });
});
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check visibility for GET requests to donation routes
  if (req.method !== "GET" || !req.path.startsWith("/donations/")) {
    next();
    return;
  }

  // Check if user is authenticated
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation (in a real app, you'd want proper JWT verification)
  try {
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    // Create expected signature
    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const expectedBuffer = Buffer.from(expectedSignature);
    const actualBuffer = Buffer.from(signature);

    if (timingSafeEqual(expectedBuffer, actualBuffer)) {
      // Token is valid, proceed
      next();
    } else {
      res.status(401).json({ error: "Invalid token" });
    }
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const farmers = [
  { id: "1", name: "John Doe", email: "john@example.com", phone: "123-456-7890", address: "123 Farm Rd" },
  { id: "2", name: "Jane Smith", email: "jane@example.com", phone: "098-765-4321", address: "456 Ranch Ln" }
];

const findFarmerById = (id: string) => {
  return farmers.find(farmer => farmer.id === id);
};

const createFarmer = (farmerData: Omit<typeof farmers[0], "id">) => {
  const newFarmer = {
    id: String(farmers.length + 1),
    ...farmerData
  };
  farmers.push(newFarmer);
  return newFarmer;
};

const updateFarmer = (id: string, updatedData: Partial<typeof farmers[0]>) => {
  const index = farmers.findIndex(farmer => farmer.id === id);
  if (index === -1) return null;
  farmers[index] = { ...farmers[index], ...updatedData };
  return farmers[index];
};

const deleteFarmer = (id: string) => {
  const index = farmers.findIndex(farmer => farmer.id === id);
  if (index === -1) return false;
  farmers.splice(index, 1);
  return true;
};

// List all farmers
router.get("/", (req: Request, res: Response) => {
  res.json(farmers);
});

// Get a specific farmer by ID
router.get("/:id", (req: Request, res: Response) => {
  const farmer = findFarmerById(req.params.id);
  if (!farmer) {
    return res.status(404).json({ error: "Farmer not found" });
  }
  res.json(farmer);
});

// Create a new farmer
router.post("/", (req: Request, res: Response) => {
  const { name, email, phone, address } = req.body;

  if (!name || !email || !phone || !address) {
    return res.status(400).json({ error: "Name, email, phone, and address are required" });
  }

  const newFarmer = createFarmer({ name, email, phone, address });
  res.status(201).json(newFarmer);
});

// Update a farmer
router.put("/:id", (req: Request, res: Response) => {
  const { name, email, phone, address } = req.body;

  const farmer = findFarmerById(req.params.id);
  if (!farmer) {
    return res.status(404).json({ error: "Farmer not found" });
  }

  const updatedFarmer = updateFarmer(req.params.id, { name, email, phone, address });
  if (!updatedFarmer) {
    return res.status(404).json({ error: "Farmer not found" });
  }

  res.json(updatedFarmer);
});

// Delete a farmer
router.delete("/:id", (req: Request, res: Response) => {
  const deleted = deleteFarmer(req.params.id);
  if (!deleted) {
    return res.status(404).json({ error: "Farmer not found" });
  }
  res.json({ message: "Farmer deleted successfully" });
});
"}

