{"code":"import { useEffect, useState } from "react";

interface Cryptocurrency {
  id: string;
  name: string;
  symbol: string;
  current_price: number;
  price_change_percentage_24h: number;
}

interface WatchlistItem {
  id: string;
  cryptocurrency_id: string;
  user_id: string;
  created_at: string;
}

export function WatchlistManagement() {
  const [watchlistItems, setWatchlistItems] = useState<WatchlistItem[]>([]);
  const [cryptocurrencies, setCryptocurrencies] = useState<Cryptocurrency[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newCryptoId, setNewCryptoId] = useState("");

  useEffect(() => {
    fetchWatchlist();
    fetchCryptocurrencies();
  }, []);

  const fetchWatchlist = async () => {
    try {
      const response = await fetch("/api/watchlist");
      if (!response.ok) {
        throw new Error("Failed to fetch watchlist");
      }
      const data = await response.json();
      setWatchlistItems(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const fetchCryptocurrencies = async () => {
    try {
      const response = await fetch("/api/cryptocurrencies");
      if (!response.ok) {
        throw new Error("Failed to fetch cryptocurrencies");
      }
      const data = await response.json();
      setCryptocurrencies(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleAddToWatchlist = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCryptoId.trim()) return;

    try {
      const response = await fetch("/api/watchlist", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ cryptocurrency_id: newCryptoId }),
      });

      if (!response.ok) {
        throw new Error("Failed to add cryptocurrency to watchlist");
      }

      setNewCryptoId("");
      await fetchWatchlist();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDeleteFromWatchlist = async (id: string) => {
    try {
      const response = await fetch(`/api/watchlist/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        throw new Error("Failed to remove cryptocurrency from watchlist");
      }

      await fetchWatchlist();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  const getCurrencyById = (id: string) => {
    return cryptocurrencies.find(crypto => crypto.id === id);
  };

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>My Watchlist</h1>

      <form onSubmit={handleAddToWatchlist} style={{ marginBottom: "20px", display: "flex", gap: "10px" }}>
        <select
          value={newCryptoId}
          onChange={(e) => setNewCryptoId(e.target.value)}
          style={{ flex: 1, padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="">Select a cryptocurrency</option>
          {cryptocurrencies.map((crypto) => (
            <option key={crypto.id} value={crypto.id}>
              {crypto.name} ({crypto.symbol})
            </option>
          ))}
        </select>
        <button
          type="submit"
          style={{ padding: "10px 20px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
        >
          Add to Watchlist
        </button>
      </form>

      {watchlistItems.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>Your watchlist is empty.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {watchlistItems.map((item) => {
            const crypto = getCurrencyById(item.cryptocurrency_id);
            return crypto ? (
              <div 
                key={item.id} 
                style={{ 
                  border: "1px solid #ddd", 
                  borderRadius: "8px", 
                  padding: "15px", 
                  display: "flex", 
                  justifyContent: "space-between", 
                  alignItems: "center", 
                  flexWrap: "wrap"
                }}
              >
                <div>
                  <h3>{crypto.name} ({crypto.symbol})</h3>
                  <p>${crypto.current_price.toFixed(2)}</p>
                  <p style={{ color: crypto.price_change_percentage_24h >= 0 ? "green" : "red" }}>
                    {crypto.price_change_percentage_24h >= 0 ? "↑" : "↓"} {Math.abs(crypto.price_change_percentage_24h).toFixed(2)}%
                  </p>
                </div>
                <button
                  onClick={() => handleDeleteFromWatchlist(item.id)}
                  style={{ 
                    padding: "8px 16px", 
                    backgroundColor: "#dc3545", 
                    color: "white", 
                    border: "none", 
                    borderRadius: "4px", 
                    cursor: "pointer" 
                  }}
                >
                  Remove
                </button>
              </div>
            ) : null;
          })}
        </div>
      )}
    </div>
  );
}
"}

