{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SECRET = process.env.JWT_SECRET;

function isValidToken(token: string): boolean {
  if (!SECRET) return false;

  const parts = token.split(".");
  if (parts.length !== 3) return false;

  const [header, payload, signature] = parts;

  const expectedSignature = createHmac("sha256", SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const expectedBytes = Buffer.from(expectedSignature, "base64url");
    const actualBytes = Buffer.from(signature, "base64url");
    return timingSafeEqual(expectedBytes, actualBytes);
  } catch {
    return false;
  }
}

function getRoleFromToken(token: string): string | null {
  if (!isValidToken(token)) return null;

  try {
    const payload = token.split(".")[1];
    const decoded = Buffer.from(payload, "base64url").toString("utf-8");
    const parsed = JSON.parse(decoded);
    return parsed.role || null;
  } catch {
    return null;
  }
}

function hasPermission(role: string | null, requiredRoles: string[]): boolean {
  if (!role) return false;
  return requiredRoles.includes(role);
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to POST, PUT, DELETE requests
  if (!(req.method === "POST" || req.method === "PUT" || req.method === "DELETE")) {
    next();
    return;
  }

  // For now, we'll assume all routes requiring role-based access are protected
  // In a real implementation, you might want to check specific paths
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '
  const role = getRoleFromToken(token);

  if (!role) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  // Define required roles for different operations
  const requiredRoles = {
    "POST": ["admin", "staff"],
    "PUT": ["admin", "staff"],
    "DELETE": ["admin"]
  };

  const requiredRoleList = requiredRoles[req.method as keyof typeof requiredRoles] || [];

  if (!hasPermission(role, requiredRoleList)) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  next();
}
"}

