    const fetchData = async () => {
      try {
        // In a real app, these would be API calls
        // For now, we'll simulate with mock data
        const mockTournaments: Tournament[] = [
          { id: 1, name: "Weekly Championship" },
          { id: 2, name: "Beginner's League" },
        ];

