        fileName,
        duration,
        format,
        status: "uploaded"
      };

      setAudioFiles([...audioFiles, newFile]);

      // Reset form
      setFileName("");
      setDuration("");
      setFormat("mp3");

      // Show success message
      alert("Audio file uploaded successfully!");
    } catch (err) {
      setError("Failed to upload audio file");
    }
  };

  const getStatusColor = (status: AudioFile["status"]) => {
    switch (status) {
      case "ready": return "#4caf50";
      case "processing": return "#ff9800";
      case "uploaded": return "#2196f3";
      case "error": return "#f44336";
      default: return "#9e9e9e";
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center", marginBottom: "30px" }}>Audio File Management</h1>

      {/* Upload Form */}
      <div style={{ backgroundColor: "#f5f5f5", borderRadius: "8px", padding: "20px", marginBottom: "30px" }}>
        <h2 style={{ marginTop: "0", marginBottom: "15px" }}>Upload New Audio File</h2>
        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: "15px" }}>
            <label style={{ display: "block", marginBottom: "5px" }}>File Name</label>
            <input
              type="text"
              value={fileName}
              onChange={(e) => setFileName(e.target.value)}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
              required
            />
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label style={{ display: "block", marginBottom: "5px" }}>Duration</label>
            <input
              type="text"
              value={duration}
              onChange={(e) => setDuration(e.target.value)}
              placeholder="e.g., 3:45"
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
              required
            />
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label style={{ display: "block", marginBottom: "5px" }}>Format</label>
            <select
              value={format}
              onChange={(e) => setFormat(e.target.value)}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
            >
              <option value="mp3">MP3</option>
              <option value="wav">WAV</option>
              <option value="flac">FLAC</option>
              <option value="aac">AAC</option>
            </select>
          </div>

          <button 
            type="submit" 
            style={{ 
              backgroundColor: "#2196f3", 
              color: "white", 
              border: "none", 
              padding: "10px 20px", 
              borderRadius: "4px", 
              cursor: "pointer", 
              fontWeight: "bold" 
            }}
          >
            Upload Audio File
          </button>
        </form>
      </div>

      {/* Audio Files List */}
      <h2 style={{ marginBottom: "15px" }}>Uploaded Audio Files</h2>

      {error && (
        <div style={{ color: "#f44336", padding: "10px", backgroundColor: "#ffebee", borderRadius: "4px", marginBottom: "20px" }}>
          {error}
        </div>
      )}

      {audioFiles.length === 0 ? (
        <div style={{ textAlign: "center", padding: "20px", color: "#666" }}>
          No audio files found. Upload your first file above.
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {audioFiles.map((file) => (
            <div 
              key={file.id} 
              style={{ 
                display: "flex", 
                justifyContent: "space-between", 
                alignItems: "center", 
                padding: "15px", 
                border: "1px solid #ddd", 
                borderRadius: "8px",
                backgroundColor: "white"
              }}
            >
              <div>
                <div style={{ fontWeight: "bold", fontSize: "16px" }}>{file.fileName}</div>
                <div style={{ fontSize: "14px", color: "#666" }}>
                  Duration: {file.duration} | Format: {file.format}
                </div>
              </div>
              <div style={{ display: "flex", alignItems: "center" }}>
                <span 
                  style={{ 
                    display: "inline-block", 
                    width: "12px", 
                    height: "12px", 
                    borderRadius: "50%", 
                    backgroundColor: getStatusColor(file.status), 
                    marginRight: "10px" 
                  }}
                />
                <span style={{ textTransform: "capitalize" }}>{file.status}</span>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

