{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./library.db");

interface Checkout {
  studentId: number;
  isbn: string;
  dueDate: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS checkouts (
    studentId INTEGER NOT NULL,
    isbn TEXT NOT NULL,
    dueDate TEXT NOT NULL,
    PRIMARY KEY (studentId, isbn)
  )
`;

db.exec(createTableSql);

export function getAllCheckouts(): Checkout[] {
  const stmt = db.prepare(`SELECT * FROM checkouts`);
  return stmt.all() as unknown as Checkout[];
}

export function getCheckoutById(studentId: number, isbn: string): Checkout | undefined {
  const stmt = db.prepare(`SELECT * FROM checkouts WHERE studentId = ? AND isbn = ?`);
  return stmt.get(studentId, isbn) as unknown as Checkout | undefined;
}

export function insertCheckout(studentId: number, isbn: string, dueDate: string): number {
  const stmt = db.prepare(
    `INSERT INTO checkouts (studentId, isbn, dueDate) VALUES (?, ?, ?)`
  );
  const result = stmt.run(studentId, isbn, dueDate);
  return Number(result.lastInsertRowid);
}

export function updateCheckout(studentId: number, isbn: string, dueDate: string): number {
  const stmt = db.prepare(
    `UPDATE checkouts SET dueDate = ? WHERE studentId = ? AND isbn = ?`
  );
  const result = stmt.run(dueDate, studentId, isbn);
  return Number(result.changes);
}

export function deleteCheckout(studentId: number, isbn: string): number {
  const stmt = db.prepare(`DELETE FROM checkouts WHERE studentId = ? AND isbn = ?`);
  const result = stmt.run(studentId, isbn);
  return Number(result.changes);
}

