{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const protectedPaths = ["/admin", "/coach", "/player"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (!userRole) {
    res.status(401).json({ error: "Unauthorized: Missing role header" });
    return;
  }

  // Define role hierarchy
  const roleHierarchy = {
    admin: 3,
    coach: 2,
    player: 1
  };

  // Get required role from path
  let requiredRole: string;
  if (req.path.startsWith("/admin")) {
    requiredRole = "admin";
  } else if (req.path.startsWith("/coach")) {
    requiredRole = "coach";
  } else if (req.path.startsWith("/player")) {
    requiredRole = "player";
  } else {
    next();
    return;
  }

  // Validate role permissions
  const userLevel = roleHierarchy[userRole as keyof typeof roleHierarchy];
  const requiredLevel = roleHierarchy[requiredRole as keyof typeof roleHierarchy];

  if (!userLevel || !requiredLevel || userLevel < requiredLevel) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  next();
}
"}

{"code":"import { useEffect, useState } from "react";

interface Bike {
  id: number;
  type: string;
  brand: string;
  model: string;
  size: string;
  color: string;
  dailyRate: number;
  isAvailable: boolean;
}

export function BikeManagementPage() {
  const [bikes, setBikes] = useState<Bike[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [filter, setFilter] = useState("all");

  // Form state
  const [newBike, setNewBike] = useState({
    type: "",
    brand: "",
    model: "",
    size: "",
    color: "",
    dailyRate: 0,
    isAvailable: true
  });

  // Fetch bikes
  useEffect(() => {
    const fetchBikes = async () => {
      try {
        const response = await fetch('/api/bikes');
        if (!response.ok) {
          throw new Error('Failed to fetch bikes');
        }
        const data = await response.json();
        setBikes(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
        setLoading(false);
      }
    };

    fetchBikes();
  }, []);

  // Handle form input changes
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target as HTMLInputElement | HTMLSelectElement;
    const checked = (e.target as HTMLInputElement).checked;

    setNewBike(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  // Add new bike
  const handleAddBike = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = await fetch('/api/bikes', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(newBike)
      });

      if (!response.ok) {
        throw new Error('Failed to add bike');
      }

      // Refresh the list
      const updatedResponse = await fetch('/api/bikes');
      const updatedData = await updatedResponse.json();
      setBikes(updatedData);

      // Reset form
      setNewBike({
        type: "",
        brand: "",
        model: "",
        size: "",
        color: "",
        dailyRate: 0,
        isAvailable: true
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  // Delete bike
  const handleDeleteBike = async (id: number) => {
    try {
      const response = await fetch(`/api/bikes/${id}`, {
        method: 'DELETE'
      });

      if (!response.ok) {
        throw new Error('Failed to delete bike');
      }

      // Refresh the list
      const updatedResponse = await fetch('/api/bikes');
      const updatedData = await updatedResponse.json();
      setBikes(updatedData);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  // Filter bikes based on search term and filter
  const filteredBikes = bikes.filter(bike => {
    const matchesSearch = bike.type.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          bike.brand.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          bike.model.toLowerCase().includes(searchTerm.toLowerCase());

    if (filter === 'available') return bike.isAvailable && matchesSearch;
    if (filter === 'unavailable') return !bike.isAvailable && matchesSearch;
    return matchesSearch;
  });

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Bike Management</h1>

      {/* Add New Bike Form */}
      <div style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <h2>Add New Bike</h2>
        <form onSubmit={handleAddBike}>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              name="type"
              placeholder="Type (e.g., Mountain, Road)"
              value={newBike.type}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px' }}
              required
            />
          </div>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              name="brand"
              placeholder="Brand"
              value={newBike.brand}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px' }}
              required
            />
          </div>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              name="model"
              placeholder="Model"
              value={newBike.model}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px' }}
              required
            />
          </div>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              name="size"
              placeholder="Size"
              value={newBike.size}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px' }}
              required
            />
          </div>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              name="color"
              placeholder="Color"
              value={newBike.color}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px' }}
              required
            />
          </div>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="number"
              name="dailyRate"
              placeholder="Daily Rate"
              value={newBike.dailyRate}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px' }}
              required
            />
          </div>
          <div style={{ marginBottom: '10px' }}>
            <label>
              <input
                type="checkbox"
                name="isAvailable"
                checked={newBike.isAvailable}
                onChange={handleInputChange}
              /> Available
            </label>
          </div>
          <button type="submit" style={{ backgroundColor: '#4CAF50', color: 'white', padding: '10px 15px', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>
            Add Bike
          </button>
        </form>
      </div>

      {/* Search and Filter */}
      <div style={{ marginBottom: '20px', display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
        <input
          type="text"
          placeholder="Search by type, brand, or model"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ flex: '1', minWidth: '200px', padding: '8px' }}
        />
        <select
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          style={{ padding: '8px' }}
        >
          <option value="all">All Bikes</option>
          <option value="available">Available</option>
          <option value="unavailable">Unavailable</option>
        </select>
      </div>

      {/* Bike List */}
      <div>
        {filteredBikes.length === 0 ? (
          <p style={{ textAlign: 'center', padding: '20px' }}>No bikes found.</p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
            {filteredBikes.map(bike => (
              <div key={bike.id} style={{
                border: '1px solid #ddd',
                borderRadius: '8px',
                padding: '15px',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                flexWrap: 'wrap'
              }}>
                <div style={{ flex: '1', minWidth: '200px' }}>
                  <h3>{bike.brand} {bike.model}</h3>
                  <p>Type: {bike.type}</p>
                  <p>Size: {bike.size}</p>
                  <p>Color: {bike.color}</p>
                  <p>Daily Rate: ${bike.dailyRate}</p>
                  <p>Status: {bike.isAvailable ? 'Available' : 'Not Available'}</p>
                </div>
                <div style={{ display: 'flex', gap: '10px' }}>
                  <button 
                    onClick={() => handleDeleteBike(bike.id)}
                    style={{ backgroundColor: '#f44336', color: 'white', padding: '8px 12px', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
"}

