{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  { id: 1, username: "admin", password: "admin123", role: "administrator" },
  { id: 2, username: "user1", password: "pass456", role: "member" },
  { id: 3, username: "user2", password: "pass789", role: "guest" }
];

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // In a real app, we would generate a JWT token here
  res.json({
    user: {
      id: user.id,
      username: user.username,
      role: user.role
    },
    token: "mock-jwt-token"
  });
});

// Register endpoint
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role = "guest" } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const existingUser = users.find(u => u.username === username);

  if (existingUser) {
    return res.status(409).json({ error: "Username already exists" });
  }

  const newUser = {
    id: users.length + 1,
    username,
    password,
    role
  };

  users.push(newUser);

  res.status(201).json({
    user: {
      id: newUser.id,
      username: newUser.username,
      role: newUser.role
    },
    token: "mock-jwt-token"
  });
});

// Get user profile endpoint
router.get("/profile/:id", (req: Request, res: Response) => {
  const userId = Number(req.params.id);

  if (isNaN(userId)) {
    return res.status(400).json({ error: "Invalid user ID" });
  }

  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  res.json({
    id: user.id,
    username: user.username,
    role: user.role
  });
});

// Update user role endpoint
router.put("/role/:id", (req: Request, res: Response) => {
  const userId = Number(req.params.id);
  const { role } = req.body;

  if (isNaN(userId)) {
    return res.status(400).json({ error: "Invalid user ID" });
  }

  if (!role) {
    return res.status(400).json({ error: "Role is required" });
  }

  const userIndex = users.findIndex(u => u.id === userId);

  if (userIndex === -1) {
    return res.status(404).json({ error: "User not found" });
  }

  users[userIndex].role = role;

  res.json({
    id: users[userIndex].id,
    username: users[userIndex].username,
    role: users[userIndex].role
  });
});

// Delete user endpoint
router.delete("/user/:id", (req: Request, res: Response) => {
  const userId = Number(req.params.id);

  if (isNaN(userId)) {
    return res.status(400).json({ error: "Invalid user ID" });
  }

  const userIndex = users.findIndex(u => u.id === userId);

  if (userIndex === -1) {
    return res.status(404).json({ error: "User not found" });
  }

  users.splice(userIndex, 1);

  res.json({ message: "User deleted successfully" });
});
"}

