    // Basic validation
    if (!name || !email) {
      return res.status(400).json({ error: "Name and email are required" });
    }

    const newUser = await mockUserDatabase.create({ name, email, vehicle, preferences });
    res.status(201).json(newUser);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// Update user
router.put("/:id", async (req: Request, res: Response) => {
  try {
    const { name, email, vehicle, preferences } = req.body;

    // Basic validation
    if (!name || !email) {
      return res.status(400).json({ error: "Name and email are required" });
    }

    const updatedUser = await mockUserDatabase.update(req.params.id, { name, email, vehicle, preferences });
    res.json(updatedUser);
