{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./bike-repair.db");

interface PartRequest {
  id: number;
  mechanic_id: number;
  part_type: string;
  status: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS part_requests (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    mechanic_id INTEGER NOT NULL,
    part_type TEXT NOT NULL,
    status TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllPartRequests(): PartRequest[] {
  const stmt = db.prepare("SELECT * FROM part_requests");
  return stmt.all() as unknown as PartRequest[];
}

export function getPartRequestById(id: number): PartRequest | undefined {
  const stmt = db.prepare("SELECT * FROM part_requests WHERE id = ?");
  return stmt.get(id) as unknown as PartRequest | undefined;
}

export function insertPartRequest(
  mechanicId: number,
  partType: string,
  status: string
): number {
  const stmt = db.prepare(
    "INSERT INTO part_requests (mechanic_id, part_type, status) VALUES (?, ?, ?)"
  );
  const result = stmt.run(mechanicId, partType, status);
  return Number(result.lastInsertRowid);
}

export function updatePartRequest(
  id: number,
  mechanicId: number,
  partType: string,
  status: string
): void {
  const stmt = db.prepare(
    "UPDATE part_requests SET mechanic_id = ?, part_type = ?, status = ? WHERE id = ?"
  );
  stmt.run(mechanicId, partType, status, id);
}

export function deletePartRequest(id: number): void {
  const stmt = db.prepare("DELETE FROM part_requests WHERE id = ?");
  stmt.run(id);
}

// Insert sample data if table is empty
if (getAllPartRequests().length === 0) {
  insertPartRequest(1, "Brake Pads", "Pending");
  insertPartRequest(2, "Chain", "In Progress");
  insertPartRequest(3, "Tire", "Completed");
  insertPartRequest(1, "Handlebars", "Pending");
  insertPartRequest(4, "Pedals", "In Progress");
}
