{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to the export endpoint
  if (req.method !== "POST" || req.path !== "/export") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation - in a real system, you'd decode and verify properly
  const [payload, signature] = token.split(".");
  if (!payload || !signature) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  // Create expected signature
  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64url");

  // Use timingSafeEqual to prevent timing attacks
  const signatureBuffer = Buffer.from(signature, "base64url");
  const expectedBuffer = Buffer.from(expectedSignature, "base64url");

  try {
    if (!timingSafeEqual(signatureBuffer, expectedBuffer)) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // Check if the token represents an owner account
  // This is a simplified check - in reality, you'd decode the payload
  // and verify the role/owner status
  const payloadObj = JSON.parse(Buffer.from(payload, "base64url").toString());

  if (payloadObj.role !== "owner") {
    res.status(403).json({ error: "Forbidden: Owner access required" });
    return;
  }

  next();
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import {
  deleteBooking,
  getAllBookings,
  getBookingById,
  insertBooking,
  updateBooking
} from "../db/bookings-table";

export const router = Router();

// Get all bookings
router.get("/", (req: Request, res: Response) => {
  const bookings = getAllBookings();
  res.json(bookings);
});

// Get a booking by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid booking ID" });
  }

  const booking = getBookingById(id);

  if (!booking) {
    return res.status(404).json({ error: "Booking not found" });
  }

  res.json(booking);
});

// Create a new booking
router.post("/", (req: Request, res: Response) => {
  const { guestId, roomId, checkInDate, checkOutDate } = req.body;

  if (!guestId || !roomId || !checkInDate || !checkOutDate) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const newId = insertBooking(guestId, roomId, checkInDate, checkOutDate);

  res.status(201).json({ id: newId, guestId, roomId, checkInDate, checkOutDate });
});

// Update a booking
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { guestId, roomId, checkInDate, checkOutDate } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid booking ID" });
  }

  if (!guestId || !roomId || !checkInDate || !checkOutDate) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const existingBooking = getBookingById(id);

  if (!existingBooking) {
    return res.status(404).json({ error: "Booking not found" });
  }

  updateBooking(id, guestId, roomId, checkInDate, checkOutDate);

  res.json({ id, guestId, roomId, checkInDate, checkOutDate });
});

// Delete a booking
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid booking ID" });
  }

  const existingBooking = getBookingById(id);

  if (!existingBooking) {
    return res.status(404).json({ error: "Booking not found" });
  }

  deleteBooking(id);

  res.json({ message: "Booking deleted successfully" });
});
"}

