{"code":"import { useEffect, useState } from "react";

interface Photo {
  id: number;
  title: string;
  url: string;
  thumbnailUrl: string;
}

interface Album {
  id: number;
  title: string;
  photos: Photo[];
}

export function AlbumDetailPage({ albumId }: { albumId: string }) {
  const [album, setAlbum] = useState<Album | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentPhotoIndex, setCurrentPhotoIndex] = useState(0);

  useEffect(() => {
    const fetchAlbum = async () => {
      try {
        const response = await fetch(`/api/albums/${albumId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch album: ${response.status}`);
        }
        const data = await response.json();
        setAlbum(data);
        setCurrentPhotoIndex(0);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchAlbum();
  }, [albumId]);

  const handleNextPhoto = () => {
    if (album && currentPhotoIndex < album.photos.length - 1) {
      setCurrentPhotoIndex(currentPhotoIndex + 1);
    }
  };

  const handlePrevPhoto = () => {
    if (album && currentPhotoIndex > 0) {
      setCurrentPhotoIndex(currentPhotoIndex - 1);
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (!album) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Album not found</div>;
  }

  const currentPhoto = album.photos[currentPhotoIndex];

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center", marginBottom: "20px" }}>{album.title}</h1>

      <div style={{ textAlign: "center", marginBottom: "20px" }}>
        <img 
          src={currentPhoto.url} 
          alt={currentPhoto.title} 
          style={{ maxWidth: "100%", height: "auto", borderRadius: "8px" }} 
        />
      </div>

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "20px" }}>
        <button 
          onClick={handlePrevPhoto}
          disabled={currentPhotoIndex === 0}
          style={{ 
            padding: "10px 20px", 
            backgroundColor: currentPhotoIndex === 0 ? "#ccc" : "#007bff", 
            color: "white", 
            border: "none", 
            borderRadius: "4px", 
            cursor: currentPhotoIndex === 0 ? "default" : "pointer"
          }}
        >
          Previous
        </button>

        <span style={{ fontSize: "16px" }}>
          {currentPhotoIndex + 1} / {album.photos.length}
        </span>

        <button 
          onClick={handleNextPhoto}
          disabled={currentPhotoIndex === album.photos.length - 1}
          style={{ 
            padding: "10px 20px", 
            backgroundColor: currentPhotoIndex === album.photos.length - 1 ? "#ccc" : "#007bff", 
            color: "white", 
            border: "none", 
            borderRadius: "4px", 
            cursor: currentPhotoIndex === album.photos.length - 1 ? "default" : "pointer"
          }}
        >
          Next
        </button>
      </div>

      <div style={{ display: "flex", flexWrap: "wrap", gap: "10px", justifyContent: "center" }}>
        {album.photos.map((photo, index) => (
          <div 
            key={photo.id}
            style={{ 
              width: "100px", 
              height: "100px", 
              overflow: "hidden", 
              borderRadius: "4px", 
              border: index === currentPhotoIndex ? "2px solid #007bff" : "1px solid #ddd",
              cursor: "pointer"
            }}
            onClick={() => setCurrentPhotoIndex(index)}
          >
            <img 
              src={photo.thumbnailUrl} 
              alt={photo.title} 
              style={{ width: "100%", height: "100%", objectFit: "cover" }} 
            />
          </div>
        ))}
      </div>
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

interface CartItem {
  id: string;
  title: string;
  author: string;
  price: number;
  quantity: number;
}

interface OrderSummary {
  subtotal: number;
  tax: number;
  shipping: number;
  total: number;
}

export function ShoppingCartPage() {
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [orderSummary, setOrderSummary] = useState<OrderSummary | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchCartItems();
  }, []);

  const fetchCartItems = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/cart');
      if (!response.ok) {
        throw new Error('Failed to fetch cart items');
      }
      const items = await response.json();
      setCartItems(items);
      calculateOrderSummary(items);
    } catch (err) {
      setError('Failed to load cart items');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const calculateOrderSummary = (items: CartItem[]) => {
    const subtotal = items.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    const tax = subtotal * 0.08;
    const shipping = subtotal > 0 ? 5.99 : 0;
    const total = subtotal + tax + shipping;

    setOrderSummary({
      subtotal,
      tax,
      shipping,
      total
    });
  };

  const updateQuantity = async (id: string, newQuantity: number) => {
    if (newQuantity <= 0) {
      removeItem(id);
      return;
    }

    try {
      const response = await fetch(`/api/cart/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ quantity: newQuantity })
      });

      if (!response.ok) {
        throw new Error('Failed to update item quantity');
      }

      const updatedItems = cartItems.map(item => 
        item.id === id ? { ...item, quantity: newQuantity } : item
      );
      setCartItems(updatedItems);
      calculateOrderSummary(updatedItems);
    } catch (err) {
      setError('Failed to update item quantity');
      console.error(err);
    }
  };

  const removeItem = async (id: string) => {
    try {
      const response = await fetch(`/api/cart/${id}`, {
        method: 'DELETE'
      });

      if (!response.ok) {
        throw new Error('Failed to remove item');
      }

      const updatedItems = cartItems.filter(item => item.id !== id);
      setCartItems(updatedItems);
      calculateOrderSummary(updatedItems);
    } catch (err) {
      setError('Failed to remove item');
      console.error(err);
    }
  };

  const proceedToCheckout = async () => {
    try {
      const response = await fetch('/api/checkout', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ items: cartItems })
      });

      if (!response.ok) {
        throw new Error('Failed to process checkout');
      }

      // Redirect to checkout page or show success message
      window.location.href = '/checkout';
    } catch (err) {
      setError('Failed to process checkout');
      console.error(err);
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (cartItems.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Your cart is empty</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Shopping Cart</h1>

      <div style={{ marginBottom: '30px' }}>
        {cartItems.map(item => (
          <div key={item.id} style={{ display: 'flex', alignItems: 'center', marginBottom: '15px', padding: '15px', border: '1px solid #ddd', borderRadius: '8px' }}>
            <div style={{ flex: 1 }}>
              <h3>{item.title}</h3>
              <p>by {item.author}</p>
              <p>${item.price.toFixed(2)}</p>
            </div>

            <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
              <button 
                onClick={() => updateQuantity(item.id, item.quantity - 1)}
                style={{ padding: '5px 10px', borderRadius: '4px', border: '1px solid #ccc' }}
              >
                -
              </button>
              <span style={{ minWidth: '30px', textAlign: 'center' }}>{item.quantity}</span>
              <button 
                onClick={() => updateQuantity(item.id, item.quantity + 1)}
                style={{ padding: '5px 10px', borderRadius: '4px', border: '1px solid #ccc' }}
              >
                +
              </button>
              <button 
                onClick={() => removeItem(item.id)}
                style={{ marginLeft: '10px', padding: '5px 10px', backgroundColor: '#ff4d4d', color: 'white', border: 'none', borderRadius: '4px' }}
              >
                Remove
              </button>
            </div>
          </div>
        ))}
      </div>

      {orderSummary && (
        <div style={{ border: '1px solid #ddd', borderRadius: '8px', padding: '20px', marginBottom: '20px' }}>
          <h2>Order Summary</h2>
          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
            <span>Subtotal:</span>
            <span>${orderSummary.subtotal.toFixed(2)}</span>
          </div>
          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
            <span>Tax:</span>
            <span>${orderSummary.tax.toFixed(2)}</span>
          </div>
          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
            <span>Shipping:</span>
            <span>${orderSummary.shipping.toFixed(2)}</span>
          </div>
          <div style={{ display: 'flex', justifyContent: 'space-between', fontWeight: 'bold', fontSize: '1.2em', marginTop: '10px' }}>
            <span>Total:</span>
            <span>${orderSummary.total.toFixed(2)}</span>
          </div>
        </div>
      )}

      <button 
        onClick={proceedToCheckout}
        style={{ 
          width: '100%', 
          padding: '15px', 
          backgroundColor: '#4CAF50', 
          color: 'white', 
          border: 'none', 
          borderRadius: '8px', 
          fontSize: '1.1em', 
          cursor: 'pointer' 
        }}
      >
        Proceed to Checkout
      </button>
    </div>
  );
}
"}

