{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would come from a database module
const mockDatabase = {
  getAllTransactions: async () => [
    { id: 1, description: "Grocery Shopping", amount: 150.75, date: "2023-05-15", type: "expense" },
    { id: 2, description: "Salary", amount: 3000.0, date: "2023-05-01", type: "income" }
  ],
  getTransactionById: async (id: number) => {
    const transactions = await mockDatabase.getAllTransactions();
    return transactions.find(t => t.id === id) || null;
  },
  createTransaction: async (transaction: any) => {
    const transactions = await mockDatabase.getAllTransactions();
    const newId = Math.max(...transactions.map(t => t.id), 0) + 1;
    return { id: newId, ...transaction };
  },
  updateTransaction: async (id: number, updates: any) => {
    const transactions = await mockDatabase.getAllTransactions();
    const index = transactions.findIndex(t => t.id === id);
    if (index === -1) return null;
    transactions[index] = { ...transactions[index], ...updates };
    return transactions[index];
  },
  deleteTransaction: async (id: number) => {
    const transactions = await mockDatabase.getAllTransactions();
    const index = transactions.findIndex(t => t.id === id);
    if (index === -1) return false;
    transactions.splice(index, 1);
    return true;
  }
};

// GET /api/transactions - List all transactions
router.get("/", async (req: Request, res: Response) => {
  try {
    const transactions = await mockDatabase.getAllTransactions();
    res.json(transactions);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// GET /api/transactions/:id - Get a specific transaction by ID
router.get("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid transaction ID" });
    }

    const transaction = await mockDatabase.getTransactionById(id);
    if (!transaction) {
      return res.status(404).json({ error: "Transaction not found" });
    }

    res.json(transaction);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// POST /api/transactions - Create a new transaction
router.post("/", async (req: Request, res: Response) => {
  try {
    const { description, amount, date, type } = req.body;

    // Validate required fields
    if (!description || !amount || !date || !type) {
      return res.status(400).json({ error: "Missing required fields: description, amount, date, type" });
    }

    // Validate amount is a number
    const amountNum = Number(amount);
    if (isNaN(amountNum)) {
      return res.status(400).json({ error: "Amount must be a valid number" });
    }

    // Validate type is either 'income' or 'expense'
    if (type !== "income" && type !== "expense") {
      return res.status(400).json({ error: "Type must be either 'income' or 'expense'" });
    }

    const newTransaction = await mockDatabase.createTransaction({
      description,
      amount: amountNum,
      date,
      type
    });

    res.status(201).json(newTransaction);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// PUT /api/transactions/:id - Update an existing transaction
router.put("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid transaction ID" });
    }

    const { description, amount, date, type } = req.body;

    // Validate amount is a number if provided
    let amountNum: number | undefined;
    if (amount !== undefined) {
      amountNum = Number(amount);
      if (isNaN(amountNum)) {
        return res.status(400).json({ error: "Amount must be a valid number" });
      }
    }

    // Validate type is either 'income' or 'expense' if provided
    if (type !== undefined && type !== "income" && type !== "expense") {
      return res.status(400).json({ error: "Type must be either 'income' or 'expense'" });
    }

    const updates = {
      ...(description !== undefined && { description }),
      ...(amount !== undefined && { amount: amountNum }),
      ...(date !== undefined && { date }),
      ...(type !== undefined && { type })
    };

    const updatedTransaction = await mockDatabase.updateTransaction(id, updates);

    if (!updatedTransaction) {
      return res.status(404).json({ error: "Transaction not found" });
    }

    res.json(updatedTransaction);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// DELETE /api/transactions/:id - Delete a transaction
router.delete("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid transaction ID" });
    }

    const deleted = await mockDatabase.deleteTransaction(id);

    if (!deleted) {
      return res.status(404).json({ error: "Transaction not found" });
    }

    res.json({ message: "Transaction deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});
"}

