{"code":"import { useEffect, useState } from "react";

interface Option {
  id: string;
  text: string;
  voteCount: number;
}

interface Poll {
  id: string;
  question: string;
  options: Option[];
  totalVotes: number;
}

export function PollDetailPage({ pollId }: { pollId: string }) {
  const [poll, setPoll] = useState<Poll | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchPoll = async () => {
      try {
        const response = await fetch(`/api/polls/${pollId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch poll: ${response.status}`);
        }
        const data = await response.json();
        setPoll(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchPoll();
  }, [pollId]);

  const handleVote = async (optionId: string) => {
    try {
      const response = await fetch(`/api/polls/${pollId}/votes`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ optionId }),
      });

      if (!response.ok) {
        throw new Error("Failed to cast vote");
      }

      // Refresh poll data after voting
      const updatedResponse = await fetch(`/api/polls/${pollId}`);
      if (!updatedResponse.ok) {
        throw new Error("Failed to refresh poll data");
      }
      const updatedData = await updatedResponse.json();
      setPoll(updatedData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (!poll) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        Poll not found.
      </div>
    );
  }

  const totalVotes = poll.totalVotes || 0;

  return (
    <div
      style={{
        maxWidth: "600px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>{poll.question}</h1>
      <div style={{ marginBottom: "20px" }}>
        <p style={{ textAlign: "center", color: "#666" }}>
          Total Votes: {totalVotes}
        </p>
      </div>
      <div>
        {poll.options.map((option) => {
          const percentage = totalVotes > 0 ? Math.round((option.voteCount / totalVotes) * 100) : 0;
          return (
            <div key={option.id} style={{ marginBottom: "15px" }}>
              <div style={{ display: "flex", alignItems: "center", marginBottom: "5px" }}>
                <span style={{ width: "40px", textAlign: "right", marginRight: "10px" }}>
                  {percentage}%
                </span>
                <div style={{ flex: 1, height: "20px", backgroundColor: "#e0e0e0", borderRadius: "10px", overflow: "hidden" }}>
                  <div
                    style={{
                      width: `${percentage}%`,
                      height: "100%",
                      backgroundColor: "#007bff",
                      borderRadius: "10px",
                    }}
                  />
                </div>
              </div>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <span>{option.text}</span>
                <button
                  onClick={() => handleVote(option.id)}
                  disabled={totalVotes === 0}
                  style={{
                    backgroundColor: "#007bff",
                    color: "white",
                    border: "none",
                    borderRadius: "5px",
                    padding: "5px 10px",
                    cursor: totalVotes === 0 ? "default" : "pointer",
                  }}
                >
                  Vote
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
"}

