{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock client data storage
let clients = [
  { id: 1, name: "Acme Corp", email: "contact@acmecorp.com", address: "123 Main St" },
  { id: 2, name: "Globex Inc", email: "info@globex.com", address: "456 Oak Ave" }
];

let nextId = 3;

// GET /api/clients - Get all clients
router.get("/", (req: Request, res: Response) => {
  res.json(clients);
});

// GET /api/clients/:id - Get a client by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const client = clients.find(c => c.id === id);

  if (!client) {
    return res.status(404).json({ error: "Client not found" });
  }

  res.json(client);
});

// POST /api/clients - Create a new client
router.post("/", (req: Request, res: Response) => {
  const { name, email, address } = req.body;

  if (!name || !email || !address) {
    return res.status(400).json({ error: "Name, email, and address are required" });
  }

  const newClient = {
    id: nextId++,
    name,
    email,
    address
  };

  clients.push(newClient);
  res.status(201).json(newClient);
});

// PUT /api/clients/:id - Update a client
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const clientIndex = clients.findIndex(c => c.id === id);

  if (clientIndex === -1) {
    return res.status(404).json({ error: "Client not found" });
  }

  const { name, email, address } = req.body;

  if (!name || !email || !address) {
    return res.status(400).json({ error: "Name, email, and address are required" });
  }

  clients[clientIndex] = {
    id,
    name,
    email,
    address
  };

  res.json(clients[clientIndex]);
});

// DELETE /api/clients/:id - Delete a client
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const clientIndex = clients.findIndex(c => c.id === id);

  if (clientIndex === -1) {
    return res.status(404).json({ error: "Client not found" });
  }

  clients.splice(clientIndex, 1);
  res.json({ message: "Client deleted successfully" });
});
