{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface Channel {
  id: number;
  name: string;
  adminUserId: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS channels (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    adminUserId INTEGER NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllChannels(): Channel[] {
  const stmt = db.prepare("SELECT * FROM channels");
  return stmt.all() as unknown as Channel[];
}

export function getChannelById(id: number): Channel | undefined {
  const stmt = db.prepare("SELECT * FROM channels WHERE id = ?");
  return stmt.get(id) as unknown as Channel | undefined;
}

export function insertChannel(name: string, adminUserId: number): number {
  const stmt = db.prepare(
    "INSERT INTO channels (name, adminUserId) VALUES (?, ?)"
  );
  const result = stmt.run(name, adminUserId);
  return Number(result.lastInsertRowid);
}

export function updateChannel(
  id: number,
  name: string,
  adminUserId: number
): boolean {
  const stmt = db.prepare(
    "UPDATE channels SET name = ?, adminUserId = ? WHERE id = ?"
  );
  const result = stmt.run(name, adminUserId, id);
  return result.changes > 0;
}

export function deleteChannel(id: number): boolean {
  const stmt = db.prepare("DELETE FROM channels WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

// Seed data
if (getAllChannels().length === 0) {
  insertChannel("General", 1);
  insertChannel("Random", 2);
  insertChannel("Announcements", 1);
  insertChannel("Support", 3);
  insertChannel("Feedback", 2);
}
"}

