export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockAppointments = [
  { id: "1", patientName: "John Doe", date: "2023-12-01", time: "09:00", status: "scheduled" },
  { id: "2", patientName: "Jane Smith", date: "2023-12-02", time: "10:00", status: "scheduled" }
];

const getAppointments = () => {
  return mockAppointments;
};

const getAppointmentById = (id: string) => {
  return mockAppointments.find(appointment => appointment.id === id);
};

const createAppointment = (appointmentData: Omit<typeof mockAppointments[0], "id">) => {
  const newId = (mockAppointments.length + 1).toString();
  const newAppointment = { ...appointmentData, id: newId };
  mockAppointments.push(newAppointment);
  return newAppointment;
};

const updateAppointment = (id: string, updatedData: Partial<typeof mockAppointments[0]>) => {
  const index = mockAppointments.findIndex(appointment => appointment.id === id);
  if (index === -1) return null;
  mockAppointments[index] = { ...mockAppointments[index], ...updatedData };
  return mockAppointments[index];
};

const cancelAppointment = (id: string) => {
  const index = mockAppointments.findIndex(appointment => appointment.id === id);
  if (index === -1) return false;
  mockAppointments.splice(index, 1);
  return true;
};

const sendNotification = (appointmentId: string) => {
  // In a real app, this would send an actual notification
  console.log(`Sending notification for appointment ${appointmentId}`);
  return true;
};

// List all appointments
router.get("/appointments", (req: Request, res: Response) => {
  try {
    const appointments = getAppointments();
    res.json(appointments);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch appointments" });
  }
});

// Get one appointment by ID
router.get("/appointments/:id", (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    const appointment = getAppointmentById(id);
    if (!appointment) {
      return res.status(404).json({ error: "Appointment not found" });
    }
    res.json(appointment);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch appointment" });
  }
});

// Create a new appointment
router.post("/appointments", (req: Request, res: Response) => {
  try {
    const { patientName, date, time } = req.body;
    if (!patientName || !date || !time) {
      return res.status(400).json({ error: "Patient name, date, and time are required" });
    }
    const newAppointment = createAppointment({ patientName, date, time, status: "scheduled" });
