export const router = Router();

// Mock data structures to simulate database operations
const attendanceRecords = [
  { id: 1, studentId: 101, date: "2023-05-01", status: "present" },
  { id: 2, studentId: 102, date: "2023-05-01", status: "absent" },
  { id: 3, studentId: 103, date: "2023-05-02", status: "late" }
];

let nextId = 4;

// GET /api/attendance - Get all attendance records
router.get("/", (req: Request, res: Response) => {
  res.json(attendanceRecords);
});

// GET /api/attendance/:id - Get a specific attendance record by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const record = attendanceRecords.find(r => r.id === id);

  if (!record) {
    return res.status(404).json({ error: "Attendance record not found" });
  }

  res.json(record);
});

// POST /api/attendance - Create a new attendance record
router.post("/", (req: Request, res: Response) => {
  const { studentId, date, status } = req.body;

  if (!studentId || !date || !status) {
    return res.status(400).json({ error: "Student ID, date, and status are required" });
  }

  const newRecord = {
    id: nextId++,
    studentId,
    date,
    status
  };

  attendanceRecords.push(newRecord);
  res.status(201).json(newRecord);
});

// PUT /api/attendance/:id - Update an existing attendance record
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const recordIndex = attendanceRecords.findIndex(r => r.id === id);

  if (recordIndex === -1) {
    return res.status(404).json({ error: "Attendance record not found" });
  }

  const { studentId, date, status } = req.body;

  // Build updates object with only provided fields
  const updates: Partial<{ studentId: number; date: string; status: string }> = {};

  if (studentId !== undefined) updates.studentId = studentId;
  if (date !== undefined) updates.date = date;
  if (status !== undefined) updates.status = status;

  // Apply updates to the record
  Object.assign(attendanceRecords[recordIndex], updates);

  res.json(attendanceRecords[recordIndex]);
});

// DELETE /api/attendance/:id - Delete an attendance record
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const recordIndex = attendanceRecords.findIndex(r => r.id === id);

  if (recordIndex === -1) {
    return res.status(404).json({ error: "Attendance record not found" });
  }

  attendanceRecords.splice(recordIndex, 1);
  res.json({ message: "Attendance record deleted successfully" });
});

// GET /api/attendance/report - Generate attendance report
router.get("/report", (req: Request, res: Response) => {
  // Simple report generation - count by status
  const report = attendanceRecords.reduce((acc, record) => {
    acc[record.status] = (acc[record.status] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  res.json(report);
});
"}

