{"code":"import { useEffect, useState } from "react";

interface Book {
  id: number;
  title: string;
  author: string;
  isbn: string;
  copies: number;
}

interface Member {
  id: number;
  name: string;
  email: string;
}

interface Loan {
  id: number;
  bookId: number;
  memberId: number;
  checkoutDate: string;
  dueDate: string;
  returnDate?: string;
}

export function LoanManagementPage() {
  const [books, setBooks] = useState<Book[]>([]);
  const [members, setMembers] = useState<Member[]>([]);
  const [loans, setLoans] = useState<Loan[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [newLoan, setNewLoan] = useState({
    bookId: "",
    memberId: ""
  });

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [booksRes, membersRes, loansRes] = await Promise.all([
          fetch("/api/books"),
          fetch("/api/members"),
          fetch("/api/loans")
        ]);

        if (!booksRes.ok || !membersRes.ok || !loansRes.ok) {
          throw new Error("Failed to fetch data");
        }

        const booksData = await booksRes.json();
        const membersData = await membersRes.json();
        const loansData = await loansRes.json();

        setBooks(booksData);
        setMembers(membersData);
        setLoans(loansData);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleCheckout = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!newLoan.bookId || !newLoan.memberId) return;

    try {
      const response = await fetch("/api/loans", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          bookId: Number(newLoan.bookId),
          memberId: Number(newLoan.memberId)
        })
      });

      if (!response.ok) {
        throw new Error("Failed to checkout book");
      }

      // Refresh data
      const [booksRes, membersRes, loansRes] = await Promise.all([
        fetch("/api/books"),
        fetch("/api/members"),
        fetch("/api/loans")
      ]);

      const booksData = await booksRes.json();
      const membersData = await membersRes.json();
      const loansData = await loansRes.json();

      setBooks(booksData);
      setMembers(membersData);
      setLoans(loansData);

      // Reset form
      setNewLoan({ bookId: "", memberId: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleReturn = async (loanId: number) => {
    try {
      const response = await fetch(`/api/loans/${loanId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ returnDate: new Date().toISOString() })
      });

      if (!response.ok) {
        throw new Error("Failed to return book");
      }

      // Refresh data
      const [booksRes, membersRes, loansRes] = await Promise.all([
        fetch("/api/books"),
        fetch("/api/members"),
        fetch("/api/loans")
      ]);

      const booksData = await booksRes.json();
      const membersData = await membersRes.json();
      const loansData = await loansRes.json();

      setBooks(booksData);
      setMembers(membersData);
      setLoans(loansData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Loan Management</h1>

      <div style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2>Check Out Book</h2>
        <form onSubmit={handleCheckout}>
          <div style={{ marginBottom: "15px" }}>
            <label style={{ display: "block", marginBottom: "5px" }}>Book:</label>
            <select
              value={newLoan.bookId}
              onChange={(e) => setNewLoan({...newLoan, bookId: e.target.value})}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            >
              <option value="">Select a book</option>
              {books.map(book => (
                <option key={book.id} value={book.id}>{book.title} by {book.author}</option>
              ))}
            </select>
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label style={{ display: "block", marginBottom: "5px" }}>Member:</label>
            <select
              value={newLoan.memberId}
              onChange={(e) => setNewLoan({...newLoan, memberId: e.target.value})}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            >
              <option value="">Select a member</option>
              {members.map(member => (
                <option key={member.id} value={member.id}>{member.name} ({member.email})</option>
              ))}
            </select>
          </div>

          <button 
            type="submit" 
            style={{ 
              backgroundColor: "#007bff", 
              color: "white", 
              border: "none", 
              padding: "10px 20px", 
              borderRadius: "4px", 
              cursor: "pointer" 
            }}
          >
            Checkout Book
          </button>
        </form>
      </div>

      <div>
        <h2>Active Loans</h2>
        {loans.length === 0 ? (
          <p style={{ textAlign: "center", padding: "20px" }}>No active loans.</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {loans.filter(loan => !loan.returnDate).map(loan => {
              const book = books.find(b => b.id === loan.bookId);
              const member = members.find(m => m.id === loan.memberId);

              return (
                <div 
                  key={loan.id} 
                  style={{ 
                    padding: "15px", 
                    border: "1px solid #ddd", 
                    borderRadius: "8px", 
                    display: "flex", 
                    justifyContent: "space-between", 
                    alignItems: "center" 
                  }}
                >
                  <div>
                    <strong>{book?.title}</strong> by {book?.author}
                    <br />
                    <small>Due: {new Date(loan.dueDate).toLocaleDateString()}</small>
                    <br />
                    <small>Borrowed by: {member?.name}</small>
                  </div>
                  <button 
                    onClick={() => handleReturn(loan.id)}
                    style={{ 
                      backgroundColor: "#28a745", 
                      color: "white", 
                      border: "none", 
                      padding: "8px 16px", 
                      borderRadius: "4px", 
                      cursor: "pointer" 
                    }}
                  >
                    Return
                  </button>
                </div>
              );
            })}
          </div>
        )}
      </div>

      <div style={{ marginTop: "30px" }}>
        <h2>Returned Loans</h2>
        {loans.filter(loan => loan.returnDate).length === 0 ? (
          <p style={{ textAlign: "center", padding: "20px" }}>No returned loans.</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {loans.filter(loan => loan.returnDate).map(loan => {
              const book = books.find(b => b.id === loan.bookId);
              const member = members.find(m => m.id === loan.memberId);

              return (
                <div 
                  key={loan.id} 
                  style={{ 
                    padding: "15px", 
                    border: "1px solid #ddd", 
                    borderRadius: "8px", 
                    display: "flex", 
                    justifyContent: "space-between", 
                    alignItems: "center" 
                  }}
                >
                  <div>
                    <strong>{book?.title}</strong> by {book?.author}
                    <br />
                    <small>Returned: {new Date(loan.returnDate!).toLocaleDateString()}</small>
                    <br />
                    <small>Borrowed by: {member?.name}</small>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}
