{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data to simulate database operations
let payments = [
  { id: "1", studentId: "101", amount: 500, date: "2023-01-15", status: "paid" },
  { id: "2", studentId: "102", amount: 750, date: "2023-02-20", status: "pending" }
];

let nextId = 3;

// GET /payments - List all payments
router.get("/payments", (req: Request, res: Response) => {
  res.json(payments);
});

// GET /payments/:id - Get a specific payment by ID
router.get("/payments/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const payment = payments.find(p => p.id === id);

  if (!payment) {
    return res.status(404).json({ error: "Payment not found" });
  }

  res.json(payment);
});

// POST /payments - Create a new payment
router.post("/payments", (req: Request, res: Response) => {
  const { studentId, amount, date, status } = req.body;

  // Validate required fields
  if (!studentId || !amount || !date || !status) {
    return res.status(400).json({ error: "Missing required fields: studentId, amount, date, status" });
  }

  // Validate amount is a number
  if (isNaN(Number(amount))) {
    return res.status(400).json({ error: "Amount must be a number" });
  }

  const newPayment = {
    id: String(nextId++),
    studentId,
    amount: Number(amount),
    date,
    status
  };

  payments.push(newPayment);
  res.status(201).json(newPayment);
});

// PUT /payments/:id - Update a payment
router.put("/payments/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const paymentIndex = payments.findIndex(p => p.id === id);

  if (paymentIndex === -1) {
    return res.status(404).json({ error: "Payment not found" });
  }

  const { studentId, amount, date, status } = req.body;

  // Validate required fields
  if (!studentId || !amount || !date || !status) {
    return res.status(400).json({ error: "Missing required fields: studentId, amount, date, status" });
  }

  // Validate amount is a number
  if (isNaN(Number(amount))) {
    return res.status(400).json({ error: "Amount must be a number" });
  }

  payments[paymentIndex] = {
    id,
    studentId,
    amount: Number(amount),
    date,
    status
  };

  res.json(payments[paymentIndex]);
});

// DELETE /payments/:id - Delete a payment
router.delete("/payments/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const paymentIndex = payments.findIndex(p => p.id === id);

  if (paymentIndex === -1) {
    return res.status(404).json({ error: "Payment not found" });
  }

  payments.splice(paymentIndex, 1);
  res.json({ message: "Payment deleted successfully" });
});
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const protectedPaths = [
    "/bookings",
    "/bookings/:id",
    "/staff/bookings",
    "/staff/bookings/:id"
  ];

  const isProtectedPath = protectedPaths.some(path => {
    if (path.includes(":")) {
      const pathWithoutParams = path.replace(/:\w+/g, ".*");
      const regex = new RegExp(`^${pathWithoutParams}$`);
      return regex.test(req.path);
    }
    return req.path === path;
  });

  // Skip validation for non-protected paths
  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role based on path
  const userRole = req.headers["x-user-role"] as string | undefined;
  const userId = req.headers["x-user-id"] as string | undefined;

  // If no user info, allow access (let other middleware handle auth)
  if (!userId || !userRole) {
    next();
    return;
  }

  // Define role requirements per path
  const roleRequirements: Record<string, string[]> = {
    "/bookings": ["customer"],
    "/bookings/:id": ["customer"],
    "/staff/bookings": ["staff"],
    "/staff/bookings/:id": ["staff"]
  };

  let requiredRoles: string[] = [];

  // Determine required roles based on path
  if (req.path.startsWith("/staff/bookings")) {
    requiredRoles = roleRequirements["/staff/bookings"];
  } else if (req.path.startsWith("/bookings")) {
    requiredRoles = roleRequirements["/bookings"];
  }

  // If no role requirements defined, allow access
  if (requiredRoles.length === 0) {
    next();
    return;
  }

  // Validate user role
  if (requiredRoles.includes(userRole)) {
    next();
  } else {
    res.status(403).json({ message: "Forbidden: Insufficient permissions" });
  }
}
"}

