{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface Repair {
  id: number;
  bike_id: number;
  part_name: string;
  labour_time: number;
  mechanic_id: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS repairs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    bike_id INTEGER NOT NULL,
    part_name TEXT NOT NULL,
    labour_time REAL NOT NULL,
    mechanic_id INTEGER NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllRepairs(): Repair[] {
  const stmt = db.prepare("SELECT * FROM repairs");
  return stmt.all() as unknown as Repair[];
}

export function getRepairById(id: number): Repair | undefined {
  const stmt = db.prepare("SELECT * FROM repairs WHERE id = ?");
  return stmt.get(id) as unknown as Repair | undefined;
}

export function insertRepair( 
  bikeId: number,
  partName: string,
  labourTime: number,
  mechanicId: number
): number {
  const stmt = db.prepare(
    "INSERT INTO repairs (bike_id, part_name, labour_time, mechanic_id) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(bikeId, partName, labourTime, mechanicId);
  return Number(result.lastInsertRowid);
}

export function updateRepair(
  id: number,
  bikeId: number,
  partName: string,
  labourTime: number,
  mechanicId: number
): number {
  const stmt = db.prepare(
    "UPDATE repairs SET bike_id = ?, part_name = ?, labour_time = ?, mechanic_id = ? WHERE id = ?"
  );
  const result = stmt.run(bikeId, partName, labourTime, mechanicId, id);
  return Number(result.changes);
}

export function deleteRepair(id: number): number {
  const stmt = db.prepare("DELETE FROM repairs WHERE id = ?");
  const result = stmt.run(id);
  return Number(result.changes);
}

// Sample data insertion
if (getAllRepairs().length === 0) {
  insertRepair(1, "Brake Pad", 2.5, 101);
  insertRepair(2, "Chain", 1.0, 102);
  insertRepair(3, "Tire", 0.5, 103);
  insertRepair(4, "Handlebar", 1.5, 101);
  insertRepair(5, "Pedal", 0.75, 102);
}
"}

