{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("blood_bank.db");

interface InventoryItem {
  id: number;
  blood_type: string;
  units: number;
  expiration_date: string;
  storage_location: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS inventory (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    blood_type TEXT NOT NULL,
    units INTEGER NOT NULL,
    expiration_date TEXT NOT NULL,
    storage_location TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllInventory(): InventoryItem[] {
  const stmt = db.prepare(`SELECT * FROM inventory`);
  return stmt.all() as unknown as InventoryItem[];
}

export function getInventoryById(id: number): InventoryItem | undefined {
  const stmt = db.prepare(`SELECT * FROM inventory WHERE id = ?`);
  return stmt.get(id) as unknown as InventoryItem | undefined;
}

export function insertInventory(
  blood_type: string,
  units: number,
  expiration_date: string,
  storage_location: string
): number {
  const stmt = db.prepare(
    `INSERT INTO inventory (blood_type, units, expiration_date, storage_location) VALUES (?, ?, ?, ?)`
  );
  const result = stmt.run(blood_type, units, expiration_date, storage_location);
  return Number(result.lastInsertRowid);
}

export function updateInventory(
  id: number,
  blood_type: string,
  units: number,
  expiration_date: string,
  storage_location: string
): number {
  const stmt = db.prepare(
    `UPDATE inventory SET blood_type = ?, units = ?, expiration_date = ?, storage_location = ? WHERE id = ?`
  );
  const result = stmt.run(blood_type, units, expiration_date, storage_location, id);
  return Number(result.changes);
}

export function deleteInventory(id: number): number {
  const stmt = db.prepare(`DELETE FROM inventory WHERE id = ?`);
  const result = stmt.run(id);
  return Number(result.changes);
}

