  title: string;
  description: string;
  date: string;
  location: string;
}

export function EventDetailPage({ eventId }: { eventId: string }) {
  const [event, setEvent] = useState<Event | null>(null);
  const [photos, setPhotos] = useState<Photo[]>([]);
  const [newPhoto, setNewPhoto] = useState({
    url: "",
    caption: ""
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchEventDetails = async () => {
      try {
        const response = await fetch(`/api/events/${eventId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch event: ${response.status}`);
        }
        const eventData = await response.json();
        setEvent(eventData);

        const photosResponse = await fetch(`/api/events/${eventId}/photos`);
        if (!photosResponse.ok) {
          throw new Error(`Failed to fetch photos: ${photosResponse.status}`);
        }
        const photosData = await photosResponse.json();
        setPhotos(photosData);

        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchEventDetails();
  }, [eventId]);

  const handlePhotoUpload = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPhoto.url || !newPhoto.caption) return;

    try {
      const response = await fetch(`/api/events/${eventId}/photos`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          url: newPhoto.url,
          caption: newPhoto.caption
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to upload photo: ${response.status}`);
      }

      // Refresh photos after upload
      const photosResponse = await fetch(`/api/events/${eventId}/photos`);
      if (photosResponse.ok) {
        const photosData = await photosResponse.json();
        setPhotos(photosData);
      }

      // Reset form
      setNewPhoto({ url: "", caption: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (!event) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Event not found</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>{event.title}</h1>
      <p style={{ textAlign: "center", color: "#666" }}>{event.date} • {event.location}</p>
      <p style={{ textAlign: "center", margin: "20px 0" }}>{event.description}</p>

      <h2 style={{ marginTop: "40px" }}>Photo Gallery</h2>
      {photos.length === 0 ? (
        <p style={{ textAlign: "center", color: "#999" }}>No photos yet. Be the first to share!</p>
      ) : (
        <div style={{ display: "flex", flexWrap: "wrap", gap: "10px", justifyContent: "center" }}>
          {photos.map(photo => (
            <div key={photo.id} style={{ border: "1px solid #ddd", borderRadius: "8px", overflow: "hidden", width: "200px" }}>
              <img src={photo.url} alt={photo.caption} style={{ width: "100%", height: "auto" }} />
              <p style={{ padding: "10px", margin: 0, fontSize: "14px" }}>{photo.caption}</p>
            </div>
          ))}
        </div>
      )}

      <h2 style={{ marginTop: "40px" }}>Upload Photo</h2>
      <form onSubmit={handlePhotoUpload} style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Photo URL"
          value={newPhoto.url}
          onChange={(e) => setNewPhoto({...newPhoto, url: e.target.value})}
          style={{ width: "100%", padding: "10px", boxSizing: "border-box" }}
        />
        <textarea
          placeholder="Caption"
          value={newPhoto.caption}
          onChange={(e) => setNewPhoto({...newPhoto, caption: e.target.value})}
          style={{ width: "100%", padding: "10px", boxSizing: "border-box", minHeight: "80px" }}
        />
        <button type="submit" style={{ padding: "10px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}>
          Upload Photo
        </button>
      </form>
    </div>
  );
}
"}

