export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT secret is set
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  // For demonstration purposes, we'll just check if the request has a body
  // In a real implementation, this would validate the token signature
  if (!req.body || !req.body.token) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Simulate token verification (in reality, this would verify HMAC-SHA256)
  const token = req.body.token;
  const expectedSignature = createHmac("sha256", jwtSecret)
    .update(token.split(".")[0])
    .digest();

  const actualSignature = Buffer.from(token.split(".")[1], "base64");

  try {
    const isValid = timingSafeEqual(expectedSignature, actualSignature);
    if (!isValid) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  next();
}
