  const events = Array.from(trackingEvents.values());
  return res.json(events);
});

// GET /tracking-events/:id - Get a specific tracking event by ID
router.get("/tracking-events/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const event = trackingEvents.get(id);

  if (!event) {
    return res.status(404).json({ error: "Tracking event not found" });
  }

  return res.json(event);
});

// POST /tracking-events - Create a new tracking event
router.post("/tracking-events", (req: Request, res: Response) => {
  const { parcelId, status, location, timestamp } = req.body;

  // Validate required fields
  if (!parcelId || !status || !location || !timestamp) {
    return res.status(400).json({ error: "Missing required fields: parcelId, status, location, timestamp" });
  }

  const id = Date.now().toString();
  const newEvent = {
    id,
    parcelId,
    status,
    location,
    timestamp
  };

  trackingEvents.set(id, newEvent);

  return res.status(201).json(newEvent);
});

// PUT /tracking-events/:id - Update a tracking event
router.put("/tracking-events/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const event = trackingEvents.get(id);

  if (!event) {
    return res.status(404).json({ error: "Tracking event not found" });
  }

  const { status, location, timestamp } = req.body;

  // Update the event
  event.status = status || event.status;
  event.location = location || event.location;
  event.timestamp = timestamp || event.timestamp;

  trackingEvents.set(id, event);

  return res.json(event);
});

// DELETE /tracking-events/:id - Delete a tracking event
router.delete("/tracking-events/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const event = trackingEvents.get(id);

  if (!event) {
    return res.status(404).json({ error: "Tracking event not found" });
  }

  trackingEvents.delete(id);

  return res.json({ message: "Tracking event deleted successfully" });
});
