}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS donations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    donorId INTEGER NOT NULL,
    donationDate TEXT NOT NULL,
    bloodVolume REAL NOT NULL,
    collectionDetails TEXT NOT NULL
  )
`;

