export function getAllDonations(): Donation[] {
  const stmt = db.prepare(`SELECT * FROM donations`);
  return stmt.all() as unknown as Donation[];
}

export function getDonationById(id: number): Donation | undefined {
  const stmt = db.prepare(`SELECT * FROM donations WHERE id = ?`);
  return stmt.get(id) as unknown as Donation | undefined;
}

export function insertDonation(
  donorId: number,
  donationDate: string,
  bloodVolume: number,
  collectionDetails: string
): number {
  const stmt = db.prepare(
    `INSERT INTO donations (donorId, donationDate, bloodVolume, collectionDetails) VALUES (?, ?, ?, ?)`
  );
  const result = stmt.run(donorId, donationDate, bloodVolume, collectionDetails);
  return Number(result.lastInsertRowid);
}

export function updateDonation(
  id: number,
  donorId: number,
  donationDate: string,
  bloodVolume: number,
  collectionDetails: string
): void {
  const stmt = db.prepare(
    `UPDATE donations SET donorId = ?, donationDate = ?, bloodVolume = ?, collectionDetails = ? WHERE id = ?`
  );
  stmt.run(donorId, donationDate, bloodVolume, collectionDetails, id);
}

export function deleteDonation(id: number): void {
