export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockDatabase = {
  customers: [
    { id: "1", name: "John Doe", email: "john@example.com", phone: "123-456-7890", bookingHistory: [] },
    { id: "2", name: "Jane Smith", email: "jane@example.com", phone: "098-765-4321", bookingHistory: [] }
  ],

  getCustomerById(id: string) {
    return this.customers.find(customer => customer.id === id);
  },

  getAllCustomers() {
    return this.customers;
  },

  createCustomer(customerData: any) {
    const newCustomer = {
      id: (this.customers.length + 1).toString(),
      ...customerData,
      bookingHistory: []
    };
    this.customers.push(newCustomer);
    return newCustomer;
  },

  updateCustomer(id: string, updatedData: any) {
    const index = this.customers.findIndex(customer => customer.id === id);
    if (index !== -1) {
      this.customers[index] = { ...this.customers[index], ...updatedData };
      return this.customers[index];
    }
    return null;
  },

  deleteCustomer(id: string) {
    const index = this.customers.findIndex(customer => customer.id === id);
    if (index !== -1) {
      this.customers.splice(index, 1);
      return true;
    }
    return false;
  }
};

// GET /customers - List all customers
