{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  {
    id: 1,
    username: "admin",
    password: "admin123",
    role: "admin"
  },
  {
    id: 2,
    username: "customer",
    password: "customer123",
    role: "customer"
  }
];

// Mock session storage
const sessions = new Map<string, { userId: number; role: string }>();

// User registration endpoint
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role = "customer" } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    username,
    password,
    role
  };

  users.push(newUser);

  return res.status(201).json({
    id: newUser.id,
    username: newUser.username,
    role: newUser.role
  });
});

// User login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Find user
  const user = users.find(u => u.username === username && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate session token
  const token = Math.random().toString(36).substring(2, 15);
  sessions.set(token, { userId: user.id, role: user.role });

  return res.json({ token, role: user.role });
});

// Session validation endpoint
router.get("/validate", (req: Request, res: Response) => {
  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "No token provided" });
  }

  const session = sessions.get(token);
  if (!session) {
    return res.status(401).json({ error: "Invalid token" });
  }

  return res.json({ userId: session.userId, role: session.role });
});
"}

{"code":"import { useEffect, useState } from "react";

interface Book {
  id: number;
  title: string;
  author: string;
  description: string;
  isbn: string;
}

export function BookCatalog() {
  const [books, setBooks] = useState<Book[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [newBook, setNewBook] = useState<Omit<Book, "id">>({ 
    title: "", 
    author: "", 
    description: "", 
    isbn: ""
  });

  useEffect(() => {
    fetchBooks();
  }, []);

  const fetchBooks = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/books-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch books: ${response.status}`);
      }
      const data = await response.json();
      setBooks(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleAddBook = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/books-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newBook),
      });
      if (!response.ok) {
        throw new Error(`Failed to add book: ${response.status}`);
      }
      const createdBook = await response.json();
      setBooks([...books, createdBook]);
      setNewBook({ title: "", author: "", description: "", isbn: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDeleteBook = async (id: number) => {
    try {
      const response = await fetch(`/api/books-api/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`Failed to delete book: ${response.status}`);
      }
      setBooks(books.filter(book => book.id !== id));
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const formStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
    maxWidth: "600px",
    margin: "0 auto 20px",
  };

  const inputStyle: React.CSSProperties = {
    padding: "8px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    fontSize: "16px",
    width: "100%",
    boxSizing: "border-box",
  };

  const buttonStyle: React.CSSProperties = {
    padding: "10px 15px",
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    borderRadius: "4px",
    cursor: "pointer",
    fontSize: "16px",
  };

  const gridStyle: React.CSSProperties = {
    display: "flex",
    flexWrap: "wrap",
    gap: "20px",
    justifyContent: "center",
    maxWidth: "1200px",
    margin: "0 auto",
  };

  const cardStyle: React.CSSProperties = {
    border: "1px solid #ddd",
    borderRadius: "8px",
    padding: "15px",
    width: "250px",
    boxSizing: "border-box",
    backgroundColor: "#f9f9f9",
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  return (
    <div style={{ fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif", padding: "20px" }}>
      <h1 style={{ textAlign: "center" }}>Book Catalog</h1>

      <form onSubmit={handleAddBook} style={formStyle}>
        <input
          type="text"
          placeholder="Title"
          value={newBook.title}
          onChange={(e) => setNewBook({...newBook, title: e.target.value})}
          style={inputStyle}
        />
        <input
          type="text"
          placeholder="Author"
          value={newBook.author}
          onChange={(e) => setNewBook({...newBook, author: e.target.value})}
          style={inputStyle}
        />
        <input
          type="text"
          placeholder="Description"
          value={newBook.description}
          onChange={(e) => setNewBook({...newBook, description: e.target.value})}
          style={inputStyle}
        />
        <input
          type="text"
          placeholder="ISBN"
          value={newBook.isbn}
          onChange={(e) => setNewBook({...newBook, isbn: e.target.value})}
          style={inputStyle}
        />
        <button type="submit" style={buttonStyle}>Add Book</button>
      </form>

      <div style={gridStyle}>
        {books.length === 0 ? (
          <p style={{ textAlign: "center", width: "100%" }}>No books available.</p>
        ) : (
          books.map((book) => (
            <div key={book.id} style={cardStyle}>
              <h3>{book.title}</h3>
              <p><strong>Author:</strong> {book.author}</p>
              <p><strong>Description:</strong> {book.description}</p>
              <p><strong>ISBN:</strong> {book.isbn}</p>
              <button 
                onClick={() => handleDeleteBook(book.id)}
                style={{ ...buttonStyle, backgroundColor: "#dc3545" }}
              >
                Delete
              </button>
            </div>
          ))
        )}
      </div>
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

interface Customer {
  id: number;
  name: string;
  serviceType: string;
  appointmentTime: string;
}

export function CustomerFormPage() {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [formData, setFormData] = useState({
    name: "",
    serviceType: "",
    appointmentTime: ""
  });
  const [editingId, setEditingId] = useState<number | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchCustomers();
  }, []);

  const fetchCustomers = async () => {
    try {
      const response = await fetch("/api/customers");
      if (!response.ok) throw new Error("Failed to fetch customers");
      const data = await response.json();
      setCustomers(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
      setLoading(false);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const url = editingId 
        ? `/api/customers/${editingId}`
        : "/api/customers";

      const method = editingId ? "PUT" : "POST";

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData)
      });

      if (!response.ok) throw new Error("Failed to save customer");

      fetchCustomers();
      resetForm();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleEdit = (customer: Customer) => {
    setFormData({
      name: customer.name,
      serviceType: customer.serviceType,
      appointmentTime: customer.appointmentTime
    });
    setEditingId(customer.id);
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/customers/${id}`, { method: "DELETE" });
      if (!response.ok) throw new Error("Failed to delete customer");
      fetchCustomers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const resetForm = () => {
    setFormData({ name: "", serviceType: "", appointmentTime: "" });
    setEditingId(null);
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  const formStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
    marginBottom: "20px",
    maxWidth: "500px",
    margin: "0 auto",
    padding: "20px",
    border: "1px solid #ccc",
    borderRadius: "8px",
    fontFamily: "system-ui, sans-serif"
  };

  const inputStyle: React.CSSProperties = {
    padding: "8px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    fontSize: "16px"
  };

  const buttonStyle: React.CSSProperties = {
    padding: "10px",
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    borderRadius: "4px",
    cursor: "pointer",
    fontSize: "16px"
  };

  const listStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
    maxWidth: "500px",
    margin: "0 auto",
    fontFamily: "system-ui, sans-serif"
  };

  const itemStyle: React.CSSProperties = {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    padding: "10px",
    border: "1px solid #ccc",
    borderRadius: "4px"
  };

  const buttonGroupStyle: React.CSSProperties = {
    display: "flex",
    gap: "5px"
  };

  return (
    <div style={{ padding: "20px", maxWidth: "600px", margin: "0 auto" }}>
