{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/tmp/tutor-session-scheduler.db"
);

export interface Session {
  id: number;
  tutorId: number;
  studentId: number;
  topic: string;
  timestamp: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    tutorId INTEGER NOT NULL,
    studentId INTEGER NOT NULL,
    topic TEXT NOT NULL,
    timestamp TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllSessions(): Session[] {
  const stmt = db.prepare(`SELECT * FROM sessions`);
  return stmt.all() as unknown as Session[];
}

export function getSessionById(id: number): Session | undefined {
  const stmt = db.prepare(`SELECT * FROM sessions WHERE id = ?`);
  return stmt.get(id) as unknown as Session | undefined;
}

export function insertSession(
  tutorId: number,
  studentId: number,
  topic: string,
  timestamp: string
): number {
  const stmt = db.prepare(
    `INSERT INTO sessions (tutorId, studentId, topic, timestamp) VALUES (?, ?, ?, ?)`
  );
  const result = stmt.run(tutorId, studentId, topic, timestamp);
  return Number(result.lastInsertRowid);
}

export function updateSession(
  id: number,
  tutorId: number,
  studentId: number,
  topic: string,
  timestamp: string
): void {
  const stmt = db.prepare(
    `UPDATE sessions SET tutorId = ?, studentId = ?, topic = ?, timestamp = ? WHERE id = ?`
  );
  stmt.run(tutorId, studentId, topic, timestamp, id);
}

export function deleteSession(id: number): void {
  const stmt = db.prepare(`DELETE FROM sessions WHERE id = ?`);
  stmt.run(id);
}

