  description: string;
  status: 'pass' | 'fail' | 'na';
}

interface Inspection {
  id?: string;
  inspectionDate: string;
  inspectorName: string;
  checklistItems: ChecklistItem[];
  status: 'draft' | 'submitted' | 'approved' | 'rejected';
}

export function InspectionForm() {
  const [inspection, setInspection] = useState<Inspection>({
    inspectionDate: new Date().toISOString().split('T')[0],
    inspectorName: '',
    checklistItems: [],
    status: 'draft'
  });

  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  // Initialize with sample checklist items
  useEffect(() => {
    fetchChecklistItems();
  }, []);

  const fetchChecklistItems = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/template-api/templates');
      if (!response.ok) throw new Error('Failed to fetch templates');

      const templates = await response.json();
      const items = templates.map((template: any) => ({
        id: template.id,
        description: template.description,
        status: 'na' as const
      }));

      setInspection(prev => ({
        ...prev,
        checklistItems: items
      }));
    } catch (err) {
      setError('Failed to load checklist items');
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setInspection(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleItemStatusChange = (itemId: string, status: 'pass' | 'fail' | 'na') => {
    setInspection(prev => ({
      ...prev,
      checklistItems: prev.checklistItems.map(item => 
        item.id === itemId ? { ...item, status } : item
      )
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      setLoading(true);
      const response = await fetch('/api/inspection-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(inspection)
      });

      if (!response.ok) throw new Error('Failed to save inspection');

      // Reset form after successful submission
      setInspection({
        inspectionDate: new Date().toISOString().split('T')[0],
        inspectorName: '',
        checklistItems: inspection.checklistItems.map(item => ({
          ...item,
          status: 'na'
        })),
        status: 'draft'
      });

    } catch (err) {
      setError('Failed to save inspection');
