{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as registrationsRouter } from "../routes/registrations-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply guard to requests targeting the registrations API
  if (!req.path.startsWith("/api/registrations")) {
    next();
    return;
  }

  // Check if user is parent scoped
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify properly
  // For this implementation, we'll just check if it's a valid format
  try {
    const payload = JSON.parse(atob(token.split('.')[1] || ''));

    // Check if the user has parent scope
    if (payload.role !== "parent") {
      res.status(403).json({ error: "Forbidden: Parent access required" });
      return;
    }

    // Verify token signature
    const expectedSignature = createHmac("sha256", secret)
      .update(token.split(".").slice(0, 2).join("."))
      .digest("hex");

    const actualSignature = token.split(".")[2];

    const isEqual = timingSafeEqual(
      Buffer.from(expectedSignature),
      Buffer.from(actualSignature || "")
    );

    if (!isEqual) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    next();
  } catch (err) {
    res.status(401).json({ error: "Invalid token" });
  }
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

// Define role types and their numeric values
const roles = {
  member: 1,
  manager: 2,
  admin: 3,
};

// Type definition for user role
export type UserRole = keyof typeof roles;

// Helper to verify JWT signature
function verifyTokenSignature(token: string, secret: string): boolean {
  const [header, payload, signature] = token.split(".");
  if (!header || !payload || !signature) return false;

  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");
    return timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

// Middleware function
export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST, PUT, DELETE requests
  if (!(req.method === "POST" || req.method === "PUT" || req.method === "DELETE")) {
    next();
    return;
  }

  // Check if JWT secret is set
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  // Extract token from Authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  // Verify token signature
  if (!verifyTokenSignature(token, jwtSecret)) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Decode token (simplified for example)
  const payload = token.split(".")[1];
  if (!payload) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const decodedPayload = Buffer.from(payload, "base64").toString();
  let userData;
  try {
    userData = JSON.parse(decodedPayload);
  } catch {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const userRole: UserRole = userData.role;
  if (!userRole || !(userRole in roles)) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // For this example, we'll assume required role is manager
  const requiredRole: UserRole = "manager";

  // Check role permissions
  if (roles[userRole] < roles[requiredRole]) {
    res.status(403).json({ error: "Forbidden" });
    return;
  }

  next();
}
"}

