{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./coop-grocery.db");

interface ShiftRow {
  member_id: number;
  shift_slot_id: number;
  claimed_at: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS shifts (
    member_id INTEGER NOT NULL,
    shift_slot_id INTEGER NOT NULL,
    claimed_at TEXT NOT NULL,
    PRIMARY KEY (member_id, shift_slot_id)
  )
`;

db.exec(createTableSql);

export function getAllShifts(): ShiftRow[] {
  const stmt = db.prepare(`SELECT * FROM shifts`);
  return stmt.all() as unknown as ShiftRow[];
}

export function getShiftById(memberId: number, shiftSlotId: number): ShiftRow | undefined {
  const stmt = db.prepare(`SELECT * FROM shifts WHERE member_id = ? AND shift_slot_id = ?`);
  return stmt.get(memberId, shiftSlotId) as unknown as ShiftRow | undefined;
}

export function insertShift(memberId: number, shiftSlotId: number, claimedAt: string): number {
  const stmt = db.prepare(
    `INSERT INTO shifts (member_id, shift_slot_id, claimed_at) VALUES (?, ?, ?)`
  );
  const result = stmt.run(memberId, shiftSlotId, claimedAt);
  return Number(result.lastInsertRowid);
}

export function updateShift(memberId: number, shiftSlotId: number, claimedAt: string): number {
  const stmt = db.prepare(
    `UPDATE shifts SET claimed_at = ? WHERE member_id = ? AND shift_slot_id = ?`
  );
  const result = stmt.run(claimedAt, memberId, shiftSlotId);
  return Number(result.changes);
}

export function deleteShift(memberId: number, shiftSlotId: number): number {
  const stmt = db.prepare(`DELETE FROM shifts WHERE member_id = ? AND shift_slot_id = ?`);
  const result = stmt.run(memberId, shiftSlotId);
  return Number(result.changes);
}

