{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./consignments.db");

interface Consignment {
  id: number;
  title: string;
  price: number;
  condition: string;
  consignerId: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS consignments (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    price REAL NOT NULL,
    condition TEXT NOT NULL,
    consignerId INTEGER NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllConsignments(): Consignment[] {
  const stmt = db.prepare("SELECT * FROM consignments");
  return stmt.all() as unknown as Consignment[];
}

export function getConsignmentById(id: number): Consignment | undefined {
  const stmt = db.prepare("SELECT * FROM consignments WHERE id = ?");
  return stmt.get(id) as unknown as Consignment | undefined;
}

export function insertConsignment(
  title: string,
  price: number,
  condition: string,
  consignerId: number
): number {
  const stmt = db.prepare(
    "INSERT INTO consignments (title, price, condition, consignerId) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(title, price, condition, consignerId);
  return Number(result.lastInsertRowid);
}

export function updateConsignment(
  id: number,
  title: string,
  price: number,
  condition: string,
  consignerId: number
): void {
  const stmt = db.prepare(
    "UPDATE consignments SET title = ?, price = ?, condition = ?, consignerId = ? WHERE id = ?"
  );
  stmt.run(title, price, condition, consignerId, id);
}

export function deleteConsignment(id: number): void {
  const stmt = db.prepare("DELETE FROM consignments WHERE id = ?");
  stmt.run(id);
}

// Insert sample data if table is empty
if (getAllConsignments().length === 0) {
  insertConsignment("To Kill a Mockingbird", 12.99, "Good", 1);
  insertConsignment("1984", 15.50, "Very Good", 2);
  insertConsignment("Pride and Prejudice", 10.00, "Fair", 1);
  insertConsignment("The Great Gatsby", 14.25, "Good", 3);
  insertConsignment("Lord of the Flies", 9.99, "Excellent", 2);
}
"}

