{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes
const SECRET = process.env.JWT_SECRET;

// Session data structure
interface Session {
  userId: string;
  createdAt: number;
}

// Helper to check if a session is still valid
function isValidSession(session: Session): boolean {
  return Date.now() - session.createdAt < SESSION_TIMEOUT;
}

// Helper to generate a secure token
function generateToken(userId: string): string {
  const timestamp = Date.now().toString();
  const data = `${userId}.${timestamp}`;
  const signature = createHmac("sha256", SECRET || "").update(data).digest("hex");
  return `${data}.${signature}`;
}

// Helper to verify token signature
function verifyToken(token: string): { userId: string; timestamp: number } | null {
  if (!SECRET) return null;

  const parts = token.split(".");
  if (parts.length !== 3) return null;

  const [userId, timestamp, expectedSignature] = parts;
  const data = `${userId}.${timestamp}`;
  const actualSignature = createHmac("sha256", SECRET).update(data).digest("hex");

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "hex");
    const actualBuffer = Buffer.from(actualSignature, "hex");

    if (timingSafeEqual(expectedBuffer, actualBuffer)) {
      return { userId, timestamp: parseInt(timestamp) };
    }
  } catch {
    return null;
  }

  return null;
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if request has a valid token
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const decoded = verifyToken(token);

  if (!decoded) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // Check if session is still valid
  const session: Session = {
    userId: decoded.userId,
    createdAt: decoded.timestamp
  };

  if (!isValidSession(session)) {
    res.status(401).json({ error: "Session expired" });
    return;
  }

  // Attach user info to request
  (req as any).user = { id: decoded.userId };

  next();
}
"}

