export const db = new DatabaseSync("camp.db");

interface MedicalNote {
  id: number;
  camper_id: number;
  note_text: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS medical_notes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    camper_id INTEGER NOT NULL,
    note_text TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllMedicalNotes(): MedicalNote[] {
  const stmt = db.prepare(`SELECT * FROM medical_notes`);
  return stmt.all() as unknown as MedicalNote[];
}

export function getMedicalNoteById(id: number): MedicalNote | undefined {
  const stmt = db.prepare(`SELECT * FROM medical_notes WHERE id = ?`);
  return stmt.get(id) as unknown as MedicalNote | undefined;
}

export function insertMedicalNote(camperId: number, noteText: string): number {
  const stmt = db.prepare(
    `INSERT INTO medical_notes (camper_id, note_text) VALUES (?, ?)`
  );
  const result = stmt.run(camperId, noteText);
  return Number(result.lastInsertRowid);
}

export function updateMedicalNote(
  id: number,
  camperId: number,
  noteText: string
): void {
  const stmt = db.prepare(
    `UPDATE medical_notes SET camper_id = ?, note_text = ? WHERE id = ?`
  );
  stmt.run(camperId, noteText, id);
}

export function deleteMedicalNote(id: number): void {
  const stmt = db.prepare(`DELETE FROM medical_notes WHERE id = ?`);
  stmt.run(id);
}

