{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;

  if (!jwtSecret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  try {
    // Simple token validation - in a real app, you'd decode and verify JWT signature
    // For this example, we'll just check if it's a valid base64 string
    const decoded = Buffer.from(token, "base64").toString("utf-8");

    // In a real implementation, we would verify the JWT signature here
    // This is a simplified version for demonstration purposes
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(decoded.split(".")[0] + "." + decoded.split(".")[1])
      .digest();

    const actualSignature = Buffer.from(decoded.split(".")[2], "base64");

    if (actualSignature.length !== expectedSignature.length) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    const isValid = timingSafeEqual(expectedSignature, actualSignature);

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}
