{"code":"import { useEffect, useState } from "react";

interface Route {
  id: number;
  name: string;
  stops: string[];
  driver: string;
}

export function RoutesManagement() {
  const [routes, setRoutes] = useState<Route[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [editingId, setEditingId] = useState<number | null>(null);
  const [formData, setFormData] = useState({
    name: "",
    stops: "",
    driver: ""
  });

  // Fetch routes
  useEffect(() => {
    const fetchRoutes = async () => {
      try {
        const response = await fetch("/api/routes");
        if (!response.ok) throw new Error("Failed to fetch routes");
        const data = await response.json();
        setRoutes(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchRoutes();
  }, []);

  // Handle form input changes
  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  // Handle form submission
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/routes", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: formData.name,
          stops: formData.stops.split(",").map(stop => stop.trim()),
          driver: formData.driver
        })
      });

      if (!response.ok) throw new Error("Failed to add route");

      // Refresh routes
      const updatedResponse = await fetch("/api/routes");
      const updatedData = await updatedResponse.json();
      setRoutes(updatedData);

      // Reset form
      setFormData({ name: "", stops: "", driver: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  // Handle update
  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId === null) return;

    try {
      const response = await fetch(`/api/routes/${editingId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: formData.name,
          stops: formData.stops.split(",").map(stop => stop.trim()),
          driver: formData.driver
        })
      });

      if (!response.ok) throw new Error("Failed to update route");

      // Refresh routes
      const updatedResponse = await fetch("/api/routes");
      const updatedData = await updatedResponse.json();
      setRoutes(updatedData);

      // Reset form
      setEditingId(null);
      setFormData({ name: "", stops: "", driver: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  // Handle delete
  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/routes/${id}`, {
        method: "DELETE"
      });

      if (!response.ok) throw new Error("Failed to delete route");

      // Refresh routes
      const updatedResponse = await fetch("/api/routes");
      const updatedData = await updatedResponse.json();
      setRoutes(updatedData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  // Set form data for editing
  const startEditing = (route: Route) => {
    setEditingId(route.id);
    setFormData({
      name: route.name,
      stops: route.stops.join(", "),
      driver: route.driver
    });
  };

  // Cancel editing
  const cancelEditing = () => {
    setEditingId(null);
    setFormData({ name: "", stops: "", driver: "" });
  };

  // Styles
  const containerStyle: React.CSSProperties = {
    maxWidth: "800px",
    margin: "0 auto",
    padding: "20px",
    fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
  };

  const formStyle: React.CSSProperties = {
    marginBottom: "20px",
    display: "flex",
    flexDirection: "column",
    gap: "10px"
  };

  const inputStyle: React.CSSProperties = {
    padding: "10px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    width: "100%",
    boxSizing: "border-box"
  };

  const buttonStyle: React.CSSProperties = {
    padding: "10px 15px",
    borderRadius: "4px",
    border: "none",
    backgroundColor: "#007bff",
    color: "white",
    cursor: "pointer"
  };

  const cancelButtonStyle: React.CSSProperties = {
    ...buttonStyle,
    backgroundColor: "#6c757d"
  };

  const routesContainerStyle: React.CSSProperties = {
    display: "flex",
    flexWrap: "wrap",
    gap: "15px"
  };

  const routeCardStyle: React.CSSProperties = {
    border: "1px solid #ddd",
    borderRadius: "8px",
    padding: "15px",
    width: "100%",
    boxSizing: "border-box",
    backgroundColor: "#f9f9f9"
  };

  const buttonGroupStyle: React.CSSProperties = {
    display: "flex",
    gap: "10px",
    marginTop: "10px"
  };

  if (loading) return <div style={containerStyle}>Loading...</div>;
  if (error) return <div style={containerStyle}>Error: {error}</div>;

  return (
    <div style={containerStyle}>
      <h1>Bus Routes Management</h1>

      <form onSubmit={editingId ? handleUpdate : handleSubmit} style={formStyle}>
        <input
          type="text"
          name="name"
          placeholder="Route Name"
          value={formData.name}
          onChange={handleChange}
          style={inputStyle}
        />
        <textarea
          name="stops"
          placeholder="Stops (comma separated)"
          value={formData.stops}
          onChange={handleChange}
          style={inputStyle}
        />
        <input
          type="text"
          name="driver"
          placeholder="Driver Name"
          value={formData.driver}
          onChange={handleChange}
          style={inputStyle}
        />
        <div>
          <button type="submit" style={buttonStyle}>
            {editingId ? "Update Route" : "Add Route"}
          </button>
          {editingId && (
            <button type="button" onClick={cancelEditing} style={cancelButtonStyle}>
              Cancel
            </button>
          )}
        </div>
      </form>

      <h2>Existing Routes</h2>
      <div style={routesContainerStyle}>
        {routes.length === 0 ? (
          <p>No routes found.</p>
        ) : (
          routes.map(route => (
            <div key={route.id} style={routeCardStyle}>
              <h3>{route.name}</h3>
              <p><strong>Stops:</strong> {route.stops.join(", ")}</p>
              <p><strong>Driver:</strong> {route.driver}</p>
              <div style={buttonGroupStyle}>
                <button onClick={() => startEditing(route)} style={buttonStyle}>Edit</button>
                <button onClick={() => handleDelete(route.id)} style={cancelButtonStyle}>Delete</button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}
"}

