{"code":"import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check deletion requests
  if (req.method !== "DELETE") {
    next();
    return;
  }

  // For this middleware, we assume role checking is handled by a prior middleware
  // If there's no user object, we can't determine role, so we allow the request
  // In a real implementation, you'd want to ensure a prior auth middleware sets req.user
  const userRole = (req as any).user?.role;

  // If user has no role or is not supervisor, reject
  if (!userRole || userRole !== "supervisor") {
    res.status(403).json({ error: "Deletion access denied. Supervisor role required." });
    return;
  }

  // Allow supervisor to proceed
  next();
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    const [header, payload, signature] = parts;
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(signature, "base64url"),
      Buffer.from(expectedSignature, "base64url")
    );

    if (!isValid) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // Decode payload to check expiration
    const decodedPayload = JSON.parse(
      Buffer.from(payload, "base64url").toString("utf-8")
    );

    const currentTime = Date.now();
    const expirationTime = decodedPayload.exp * 1000;

    if (currentTime > expirationTime) {
      res.status(401).json({ error: "Token expired" });
      return;
    }

    // Token is valid, proceed
    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}
"}

