import {
  db,
  deleteCheckout,
  getAllCheckouts,
  getCheckoutById,
  insertCheckout,
  updateCheckout
} from "../db/checkouts-table";

export const router = Router();

// Get all checkouts
router.get("/", (req: Request, res: Response) => {
  const checkouts = getAllCheckouts();
  res.json(checkouts);
});

// Get a checkout by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid checkout ID" });
  }

  const checkout = getCheckoutById(id);

  if (!checkout) {
    return res.status(404).json({ error: "Checkout not found" });
  }

  res.json(checkout);
});

// Create a new checkout
router.post("/", (req: Request, res: Response) => {
  const { memberId, seedPacketId, dueDate } = req.body;

  if (!memberId || !seedPacketId || !dueDate) {
    return res.status(400).json({ error: "Member ID, seed packet ID, and due date are required" });
  }

  const newId = insertCheckout(
    Number(memberId),
    Number(seedPacketId),
    dueDate
  );

  const newCheckout = getCheckoutById(newId);

  if (!newCheckout) {
    return res.status(500).json({ error: "Failed to create checkout" });
  }

  res.status(201).json(newCheckout);
});

// Update a checkout
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { memberId, seedPacketId, dueDate } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid checkout ID" });
  }

  if (!memberId || !seedPacketId || !dueDate) {
    return res.status(400).json({ error: "Member ID, seed packet ID, and due date are required" });
  }

  const updatedRows = updateCheckout(
    id,
    Number(memberId),
    Number(seedPacketId),
    dueDate
  );

  if (updatedRows === 0) {
    return res.status(404).json({ error: "Checkout not found" });
  }

  const updatedCheckout = getCheckoutById(id);

  if (!updatedCheckout) {
    return res.status(500).json({ error: "Failed to retrieve updated checkout" });
  }

  res.json(updatedCheckout);
});

// Delete a checkout
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid checkout ID" });
  }

  const deletedRows = deleteCheckout(id);

  if (deletedRows === 0) {
    return res.status(404).json({ error: "Checkout not found" });
  }

  res.json({ message: "Checkout deleted successfully" });
});
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database - in a real app this would be a proper database
const users: { id: string; username: string; password: string; email: string }[] = [];
let nextId = 1;

// User registration endpoint
router.post("/register", (req: Request, res: Response) => {
  const { username, password, email } = req.body;

  // Validate input
  if (!username || !password || !email) {
    return res.status(400).json({ error: "Username, password, and email are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.email === email);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: nextId.toString(),
    username,
    password,
    email
  };

  users.push(newUser);
  nextId++;

  // Return created user (excluding password)
  res.status(201).json({
    id: newUser.id,
    username: newUser.username,
    email: newUser.email
  });
});

// User login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  // Validate input
  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  // Find user
  const user = users.find(u => u.email === email && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // In a real app, we would generate a JWT token here
  // For now, we'll just return user info
  res.json({
    id: user.id,
    username: user.username,
    email: user.email
  });
});

// Session management endpoint
