  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user (role defaults to member)
  const newUser = {
    id: users.length + 1,
    username,
    password,
    role: "member"
  };

  users.push(newUser);

  return res.status(201).json({
    id: newUser.id,
    username: newUser.username,
    role: newUser.role
  });
});

// User login
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // In a real app, we would generate a JWT token here
  return res.json({
    username: user.username,
    role: user.role
  });
});

// Middleware to check role
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    // For simplicity, assuming role is passed in the request
    // In a real app, this would come from a decoded JWT token
    const userRole = req.headers.role as string;

    if (userRole !== requiredRole) {
      return res.status(403).json({ error: "Access denied" });
    }

    next();
  };
};

// Protected route for admin only
router.get("/admin", requireRole("admin"), (req: Request, res: Response) => {
  return res.json({ message: "Welcome Admin" });
});

// Protected route for members
router.get("/member", requireRole("member"), (req: Request, res: Response) => {
  return res.json({ message: "Welcome Member" });
});
