{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockStudents = [
  { id: 1, name: "Alice Johnson", email: "alice@example.com", grade: "A" },
  { id: 2, name: "Bob Smith", email: "bob@example.com", grade: "B" },
  { id: 3, name: "Charlie Brown", email: "charlie@example.com", grade: "A" }
];

const findStudentById = (id: number) => {
  return mockStudents.find(student => student.id === id);
};

const findStudentIndexById = (id: number) => {
  return mockStudents.findIndex(student => student.id === id);
};

// GET /students - List all students
router.get("/students", (req: Request, res: Response) => {
  res.json(mockStudents);
});

// GET /students/:id - Get a specific student by ID
router.get("/students/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid student ID" });
  }

  const student = findStudentById(id);

  if (!student) {
    return res.status(404).json({ error: "Student not found" });
  }

  res.json(student);
});

// POST /students - Create a new student
router.post("/students", (req: Request, res: Response) => {
  const { name, email, grade } = req.body;

  if (!name || !email || !grade) {
    return res.status(400).json({ error: "Name, email, and grade are required" });
  }

  const newId = Math.max(...mockStudents.map(s => s.id)) + 1;
  const newStudent = { id: newId, name, email, grade };

  mockStudents.push(newStudent);

  res.status(201).json(newStudent);
});

// PUT /students/:id - Update a student
router.put("/students/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { name, email, grade } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid student ID" });
  }

  const index = findStudentIndexById(id);

  if (index === -1) {
    return res.status(404).json({ error: "Student not found" });
  }

  if (!name || !email || !grade) {
    return res.status(400).json({ error: "Name, email, and grade are required" });
  }

  mockStudents[index] = { id, name, email, grade };

  res.json(mockStudents[index]);
});

// DELETE /students/:id - Delete a student
router.delete("/students/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid student ID" });
  }

  const index = findStudentIndexById(id);

  if (index === -1) {
    return res.status(404).json({ error: "Student not found" });
  }

  const deletedStudent = mockStudents.splice(index, 1)[0];

  res.json(deletedStudent);
});

// GET /students/search?name=... - Search students by name
router.get("/students/search", (req: Request, res: Response) => {
  const { name } = req.query;

  if (!name || typeof name !== "string") {
    return res.status(400).json({ error: "Name query parameter is required" });
  }

  const results = mockStudents.filter(student => 
    student.name.toLowerCase().includes(name.toLowerCase())
  );

  res.json(results);
});
"}

