  ],

  getAllMaterials: (): Promise<any[]> => {
    return Promise.resolve(mockDatabase.materials);
  },

  getMaterialById: (id: number): Promise<any | null> => {
    const material = mockDatabase.materials.find(m => m.id === id) || null;
    return Promise.resolve(material);
  },

  createMaterial: (materialData: any): Promise<any> => {
    const newMaterial = {
      id: mockDatabase.materials.length > 0 
        ? Math.max(...mockDatabase.materials.map(m => m.id)) + 1 
        : 1,
      ...materialData
    };
    mockDatabase.materials.push(newMaterial);
    return Promise.resolve(newMaterial);
  },

  updateMaterial: (id: number, materialData: any): Promise<any | null> => {
    const index = mockDatabase.materials.findIndex(m => m.id === id);
    if (index === -1) return Promise.resolve(null);

    mockDatabase.materials[index] = { ...mockDatabase.materials[index], ...materialData };
    return Promise.resolve(mockDatabase.materials[index]);
  },

  deleteMaterial: (id: number): Promise<boolean> => {
    const initialLength = mockDatabase.materials.length;
    mockDatabase.materials = mockDatabase.materials.filter(m => m.id !== id);
    return Promise.resolve(mockDatabase.materials.length < initialLength);
  }
};

// Validation helper
const validateMaterial = (material: any): string | null => {
  if (!material.name || typeof material.name !== 'string') {
    return 'Name is required and must be a string';
  }

  if (typeof material.quantity !== 'number' || material.quantity <= 0) {
    return 'Quantity is required and must be a positive number';
  }

  if (!material.unit || typeof material.unit !== 'string') {
    return 'Unit is required and must be a string';
  }

  if (!material.category || typeof material.category !== 'string') {
    return 'Category is required and must be a string';
  }

  return null;
};

// GET /materials - List all materials
