  try {
    const materials = await mockDatabase.getAllMaterials();
    res.json(materials);
  } catch (error) {
    res.status(500).json({ error: 'Failed to fetch materials' });
  }
});

// GET /materials/:id - Get a specific material by ID
router.get('/materials/:id', async (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid material ID' });
  }

  try {
    const material = await mockDatabase.getMaterialById(id);

    if (!material) {
      return res.status(404).json({ error: 'Material not found' });
    }

    res.json(material);
  } catch (error) {
    res.status(500).json({ error: 'Failed to fetch material' });
  }
});

