  const { name, quantity, unit, category } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid material ID' });
  }

  const validationError = validateMaterial({ name, quantity, unit, category });

  if (validationError) {
    return res.status(400).json({ error: validationError });
  }

  try {
    const updatedMaterial = await mockDatabase.updateMaterial(id, { name, quantity, unit, category });

    if (!updatedMaterial) {
      return res.status(404).json({ error: 'Material not found' });
    }

    res.json(updatedMaterial);
  } catch (error) {
    res.status(500).json({ error: 'Failed to update material' });
  }
});

// DELETE /materials/:id - Delete a material
router.delete('/materials/:id', async (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: 'Invalid material ID' });
  }

  try {
    const deleted = await mockDatabase.deleteMaterial(id);

    if (!deleted) {
      return res.status(404).json({ error: 'Material not found' });
    }

    res.json({ message: 'Material deleted successfully' });
  } catch (error) {
    res.status(500).json({ error: 'Failed to delete material' });
  }
});
