{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./dev.sqlite3");

interface ClientRow {
  id: number;
  name: string;
  address: string;
  payment_terms: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS clients (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    address TEXT NOT NULL,
    payment_terms TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllClients(): ClientRow[] {
  const stmt = db.prepare("SELECT * FROM clients");
  return stmt.all() as unknown as ClientRow[];
}

export function getClientById(id: number): ClientRow | undefined {
  const stmt = db.prepare("SELECT * FROM clients WHERE id = ?");
  return stmt.get(id) as unknown as ClientRow | undefined;
}

export function insertClient(client: Omit<ClientRow, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO clients (name, address, payment_terms) VALUES (?, ?, ?)"
  );
  const result = stmt.run(client.name, client.address, client.payment_terms);
  return Number(result.lastInsertRowid);
}

export function updateClient(
  id: number,
  client: Partial<Omit<ClientRow, "id">>
): number {
  const fields = [];
  const values = [];

  if (client.name !== undefined) {
    fields.push("name = ?");
    values.push(client.name);
  }

  if (client.address !== undefined) {
    fields.push("address = ?");
    values.push(client.address);
  }

  if (client.payment_terms !== undefined) {
    fields.push("payment_terms = ?");
    values.push(client.payment_terms);
  }

  if (fields.length === 0) {
    throw new Error("No fields to update");
  }

  values.push(id);

  const sql = `UPDATE clients SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  const result = stmt.run(...values);
  return Number(result.changes);
}

export function deleteClient(id: number): number {
  const stmt = db.prepare("DELETE FROM clients WHERE id = ?");
  const result = stmt.run(id);
  return Number(result.changes);
}

// Seed data
if (getAllClients().length === 0) {
  insertClient({
    name: "Acme Corporation",
    address: "123 Main St, Anytown, USA",
    payment_terms: "Net 30"
  });

