{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (!(req.method === "POST" && req.path === "/login")) {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;

  if (!jwtSecret) {
    res.status(500).json({ error: "JWT secret not configured" });
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    const [header, payload, signature] = parts;

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // If we get here, the token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Token verification failed" });
  }
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check session timeout for routes that require authentication
  // This middleware should only run on protected routes
  const protectedPaths = ["/dashboard", "/profile", "/billing"];
  const isProtectedRoute = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedRoute) {
    next();
    return;
  }

  // Check if user is authenticated via JWT token in Authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  if (!JWT_SECRET) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    // Verify token signature
    const [header, payload, signature] = parts;
    const expectedSignature = createHmac("sha256", JWT_SECRET)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // Decode payload to check expiration
    const decodedPayload = JSON.parse(
      Buffer.from(payload, "base64url").toString()
    );

    const currentTime = Math.floor(Date.now() / 1000);
    if (decodedPayload.exp < currentTime) {
      res.status(401).json({ error: "Session expired" });
      return;
    }

    // If we get here, the session is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}
"}

{"code":"import { useEffect, useState } from "react";

interface MenuItem {
  id: number;
  name: string;
  description: string;
  price: number;
}

interface Order {
  id: number;
  status: "preparing" | "ready" | "completed";
  items: { menuItemId: number; quantity: number }[];
}

export function CustomerDashboard() {
  const [menuItems, setMenuItems] = useState<MenuItem[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newOrder, setNewOrder] = useState<Record<number, number>>({});

  useEffect(() => {
    async function fetchMenuAndOrders() {
      try {
        const [menuResponse, ordersResponse] = await Promise.all([
          fetch("/api/menu"),
          fetch("/api/orders"),
        ]);

        if (!menuResponse.ok || !ordersResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const [menuData, ordersData] = await Promise.all([
          menuResponse.json(),
          ordersResponse.json(),
        ]);

        setMenuItems(menuData);
        setOrders(ordersData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchMenuAndOrders();
  }, []);

  const handleQuantityChange = (itemId: number, quantity: number) => {
    setNewOrder((prev) => ({
      ...prev,
      [itemId]: quantity,
    }));
  };

  const handleSubmitOrder = async () => {
    const orderItems = Object.entries(newOrder)
      .filter(([_, quantity]) => quantity > 0)
      .map(([itemId, quantity]) => ({
        menuItemId: parseInt(itemId),
        quantity,
      }));

    if (orderItems.length === 0) return;

    try {
      const response = await fetch("/api/orders", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ items: orderItems }),
      });

      if (!response.ok) {
        throw new Error("Failed to place order");
      }

      // Refresh orders after successful submission
      const ordersResponse = await fetch("/api/orders");
      if (ordersResponse.ok) {
        const ordersData = await ordersResponse.json();
        setOrders(ordersData);
      }

      // Reset form
      setNewOrder({});
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div
      style={{
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Food Truck Orders</h1>

      <section style={{ marginBottom: "30px" }}>
        <h2>Menu</h2>
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "15px",
          }}
        >
          {menuItems.length === 0 ? (
            <p>No menu items available.</p>
          ) : (
            menuItems.map((item) => (
              <div
                key={item.id}
                style={{
                  border: "1px solid #ccc",
                  borderRadius: "8px",
                  padding: "15px",
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                }}
              >
                <div>
                  <h3>{item.name}</h3>
                  <p>{item.description}</p>
                  <p>${item.price.toFixed(2)}</p>
                </div>
                <div>
                  <label htmlFor={`quantity-${item.id}`}>Quantity:</label>
                  <input
                    type="number"
                    id={`quantity-${item.id}`}
                    min="0"
                    value={newOrder[item.id] || 0}
                    onChange={(e) =>
                      handleQuantityChange(item.id, parseInt(e.target.value) || 0)
                    }
                    style={{
                      width: "60px",
                      marginLeft: "10px",
                      padding: "5px",
                    }}
                  />
                </div>
              </div>
            ))
          )}
        </div>
      </section>

      <section style={{ marginBottom: "30px" }}>
        <h2>Place Your Order</h2>
        <button
          onClick={handleSubmitOrder}
          style={{
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            borderRadius: "4px",
            padding: "10px 20px",
            cursor: "pointer",
            fontSize: "16px",
          }}
        >
          Submit Order
        </button>
      </section>

      <section>
        <h2>Your Orders</h2>
        {orders.length === 0 ? (
          <p>No orders placed yet.</p>
        ) : (
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: "15px",
            }}
          >
            {orders.map((order) => (
              <div
                key={order.id}
                style={{
                  border: "1px solid #ccc",
                  borderRadius: "8px",
                  padding: "15px",
                }}
              >
                <h3>Order #{order.id}</h3>
                <p>Status: {order.status}</p>
                <h4>Items:</h4>
                <ul>
                  {order.items.map((item) => {
                    const menuItem = menuItems.find(
                      (mi) => mi.id === item.menuItemId
                    );
                    return (
                      <li key={item.menuItemId}>
                        {menuItem?.name} x{item.quantity}
                      </li>
                    );
                  })}
                </ul>
              </div>
            ))}
          </div>
        )}
      </section>
    </div>
  );
}
"}

