{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  const protectedPaths = ["/admin", "/staff"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (!userRole) {
    res.status(401).json({ error: "Unauthorized: Missing role header" });
    return;
  }

  // Validate role
  const validRoles = ["admin", "staff"];
  if (!validRoles.includes(userRole)) {
    res.status(403).json({ error: "Forbidden: Invalid role" });
    return;
  }

  // For admin-only routes
  if (req.path.startsWith("/admin") && userRole !== "admin") {
    res.status(403).json({ error: "Forbidden: Admin access required" });
    return;
  }

  // For staff-only routes
  if (req.path.startsWith("/staff") && userRole !== "staff") {
    res.status(403).json({ error: "Forbidden: Staff access required" });
    return;
  }

  // If we reach here, user has proper access
  next();
}
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockAppointments = [
  { id: "1", customerId: "123", service: "Haircut", date: "2023-10-15", time: "10:00" },
  { id: "2", customerId: "124", service: "Color", date: "2023-10-16", time: "14:00" }
];

const getAppointments = () => {
  return mockAppointments;
};

const getAppointmentById = (id: string) => {
  return mockAppointments.find(appointment => appointment.id === id);
};

const createAppointment = (appointment: any) => {
  const newAppointment = { ...appointment, id: String(mockAppointments.length + 1) };
  mockAppointments.push(newAppointment);
  return newAppointment;
};

const updateAppointment = (id: string, updatedFields: any) => {
  const index = mockAppointments.findIndex(appointment => appointment.id === id);
  if (index !== -1) {
    mockAppointments[index] = { ...mockAppointments[index], ...updatedFields };
    return mockAppointments[index];
  }
  return null;
};

const deleteAppointment = (id: string) => {
  const index = mockAppointments.findIndex(appointment => appointment.id === id);
  if (index !== -1) {
    mockAppointments.splice(index, 1);
    return true;
  }
  return false;
};

// GET /appointments - List all appointments
router.get("/appointments", (req: Request, res: Response) => {
  const appointments = getAppointments();
  res.json(appointments);
});

// GET /appointments/:id - Get one appointment by ID
router.get("/appointments/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const appointment = getAppointmentById(id);
  if (!appointment) {
    return res.status(404).json({ error: "Appointment not found" });
  }
  res.json(appointment);
});

// POST /appointments - Create a new appointment
router.post("/appointments", (req: Request, res: Response) => {
  const { customerId, service, date, time } = req.body;

  if (!customerId || !service || !date || !time) {
    return res.status(400).json({ error: "Missing required fields: customerId, service, date, time" });
  }

  const newAppointment = createAppointment({ customerId, service, date, time });
  res.status(201).json(newAppointment);
});

// PUT /appointments/:id - Update an existing appointment
router.put("/appointments/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const { customerId, service, date, time } = req.body;

  const updatedFields = {} as any;
  if (customerId) updatedFields.customerId = customerId;
  if (service) updatedFields.service = service;
  if (date) updatedFields.date = date;
  if (time) updatedFields.time = time;

  const updatedAppointment = updateAppointment(id, updatedFields);

  if (!updatedAppointment) {
    return res.status(404).json({ error: "Appointment not found" });
  }

  res.json(updatedAppointment);
});

// DELETE /appointments/:id - Cancel an appointment
router.delete("/appointments/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const deleted = deleteAppointment(id);

  if (!deleted) {
    return res.status(404).json({ error: "Appointment not found" });
  }

  res.json({ message: "Appointment cancelled successfully" });
});
"}

