  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid order ID" });
    }

    const order = getOrderById(id);
    if (!order) {
      return res.status(404).json({ error: "Order not found" });
    }

    res.json(order);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch order" });
  }
});

// Create new order
router.post("/", (req: Request, res: Response) => {
  try {
    const { customerId, flavour, size, date } = req.body;

    if (!customerId || !flavour || !size || !date) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const id = insertOrder(customerId, flavour, size, date);
    const newOrder = getOrderById(id);

    if (!newOrder) {
      return res.status(500).json({ error: "Failed to create order" });
    }

    res.status(201).json(newOrder);
  } catch (error) {
    res.status(500).json({ error: "Failed to create order" });
  }
});

// Update existing order
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { customerId, flavour, size, date } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid order ID" });
    }

    if (!customerId || !flavour || !size || !date) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const existingOrder = getOrderById(id);
    if (!existingOrder) {
      return res.status(404).json({ error: "Order not found" });
    }

    updateOrder(id, customerId, flavour, size, date);
    const updatedOrder = getOrderById(id);

    if (!updatedOrder) {
      return res.status(500).json({ error: "Failed to update order" });
    }

    res.json(updatedOrder);
  } catch (error) {
    res.status(500).json({ error: "Failed to update order" });
  }
});

// Delete order (supervisor-only)
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid order ID" });
    }

    const existingOrder = getOrderById(id);
    if (!existingOrder) {
      return res.status(404).json({ error: "Order not found" });
    }

