{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only validate POST, PUT, PATCH requests that contain a body
  if (!['POST', 'PUT', 'PATCH'].includes(req.method)) {
    return next();
  }

  // Skip validation for health check endpoints
  if (req.path === '/health') {
    return next();
  }

  // Validate and sanitize input data
  if (req.body) {
    // Sanitize string fields to prevent XSS and injection attacks
    sanitizeBody(req.body);
  }

  next();
}

function sanitizeBody(obj: any): void {
  if (typeof obj !== 'object' || obj === null) {
    return;
  }

  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      const value = obj[key];

      if (typeof value === 'string') {
        // Remove potentially dangerous characters
        obj[key] = value
          .replace(/<script[^>]*>.*?<\/script>/gi, '')
          .replace(/<iframe[^>]*>.*?<\/iframe>/gi, '')
          .replace(/<object[^>]*>.*?<\/object>/gi, '')
          .replace(/<embed[^>]*>.*?<\/embed>/gi, '')
          .replace(/<applet[^>]*>.*?<\/applet>/gi, '');
      } else if (Array.isArray(value)) {
        value.forEach(item => sanitizeBody(item));
      } else if (typeof value === 'object') {
        sanitizeBody(value);
      }
    }
  }
}
"}

