router.get("/users", authenticate, authorize(["admin"]), (req: Request, res: Response) => {
  res.json(users.map(u => ({ id: u.id, email: u.email, role: u.role })));
});

// Admin-only route to delete a user
router.delete("/users/:id", authenticate, authorize(["admin"]), (req: Request, res: Response) => {
  const userId = req.params.id;
  const userIndex = users.findIndex(u => u.id === userId);

  if (userIndex === -1) {
    return res.status(404).json({ error: "User not found." });
  }

  users.splice(userIndex, 1);
  res.json({ message: "User deleted successfully." });
});
