export function PhotoGallery() {
  const [photos, setPhotos] = useState<Photo[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newPhoto, setNewPhoto] = useState({
    imageUrl: "",
    caption: "",
  });
  const [commentText, setCommentText] = useState("");
  const [selectedPhotoId, setSelectedPhotoId] = useState<string | null>(null);

  useEffect(() => {
    fetchPhotos();
  }, []);

  const fetchPhotos = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/photos-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch photos: ${response.status}`);
      }
      const data = await response.json();
      setPhotos(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleAddPhoto = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/photos-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          imageUrl: newPhoto.imageUrl,
          caption: newPhoto.caption,
          author: "Current User", // In a real app, this would come from auth
        }),
      });
      if (!response.ok) {
        throw new Error(`Failed to add photo: ${response.status}`);
      }
      setNewPhoto({ imageUrl: "", caption: "" });
      fetchPhotos();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDeletePhoto = async (id: string) => {
    try {
      const response = await fetch(`/api/photos-api/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`Failed to delete photo: ${response.status}`);
      }
      fetchPhotos();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleAddComment = async (photoId: string) => {
    if (!commentText.trim()) return;
    try {
      const response = await fetch(`/api/photos-api/${photoId}/comments`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          text: commentText,
          author: "Current User", // In a real app, this would come from auth
        }),
      });
      if (!response.ok) {
        throw new Error(`Failed to add comment: ${response.status}`);
      }
      setCommentText("");
      fetchPhotos();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={styles.container}>
      <h1 style={styles.header}>Family Photo Gallery</h1>

      <form onSubmit={handleAddPhoto} style={styles.form}>
        <input
          type="text"
          placeholder="Image URL"
          value={newPhoto.imageUrl}
          onChange={(e) => setNewPhoto({...newPhoto, imageUrl: e.target.value})}
          style={styles.input}
        />
        <input
          type="text"
          placeholder="Caption"
          value={newPhoto.caption}
          onChange={(e) => setNewPhoto({...newPhoto, caption: e.target.value})}
          style={styles.input}
        />
        <button type="submit" style={styles.button}>Add Photo</button>
      </form>

      {photos.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No photos yet. Be the first to add one!</p>
      ) : (
        <div style={styles.photoGrid}>
          {photos.map((photo) => (
            <div key={photo.id} style={styles.photoCard}>
              <img src={photo.imageUrl} alt={photo.caption} style={styles.photoImage} />
              <p style={styles.caption}>{photo.caption}</p>
              <p style={styles.author}>By {photo.author}</p>
              <button 
                onClick={() => handleDeletePhoto(photo.id)} 
                style={styles.deleteButton}
              >
                Delete
              </button>

              <div style={styles.commentsSection}>
                <h3 style={styles.commentsHeader}>Comments</h3>
                <ul style={styles.commentList}>
                  {photo.comments.map((comment) => (
                    <li key={comment.id} style={styles.commentItem}>
                      <strong>{comment.author}:</strong> {comment.text}
                    </li>
                  ))}
                </ul>
                <div style={styles.addCommentForm}>
                  <input
                    type="text"
                    placeholder="Add a comment..."
                    value={commentText}
                    onChange={(e) => setCommentText(e.target.value)}
                    style={styles.commentInput}
                  />
                  <button 
                    onClick={() => handleAddComment(photo.id)}
                    style={styles.commentButton}
                  >
                    Add Comment
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
