  ],
  getSubscriberById: async (id: string) => {
    const subscribers = await mockDatabase.getAllSubscribers();
    return subscribers.find(sub => sub.id === id) || null;
  },
  createSubscriber: async (email: string, name: string) => {
    const subscribers = await mockDatabase.getAllSubscribers();
    const newId = (subscribers.length + 1).toString();
    return { id: newId, email, name };
  },
  updateSubscriber: async (id: string, email: string, name: string) => {
    const subscribers = await mockDatabase.getAllSubscribers();
    const index = subscribers.findIndex(sub => sub.id === id);
    if (index === -1) return null;
    subscribers[index] = { id, email, name };
    return subscribers[index];
  },
  deleteSubscriber: async (id: string) => {
    const subscribers = await mockDatabase.getAllSubscribers();
    const index = subscribers.findIndex(sub => sub.id === id);
    if (index === -1) return false;
    subscribers.splice(index, 1);
    return true;
  }
};

