interface BoxCustomization {
  id: string;
  memberId: string;
  items: string[];
}

export function BoxCustomizer() {
  const [members, setMembers] = useState<Member[]>([]);
  const [customizations, setCustomizations] = useState<BoxCustomization[]>([]);
  const [selectedMemberId, setSelectedMemberId] = useState<string>("");
  const [items, setItems] = useState<string[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [membersResponse, customizationsResponse] = await Promise.all([
          fetch("/api/membership-api/members"),
          fetch("/api/membership-api/box-customizations"),
        ]);

        if (!membersResponse.ok || !customizationsResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const membersData = await membersResponse.json();
        const customizationsData = await customizationsResponse.json();

        setMembers(membersData);
        setCustomizations(customizationsData);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleMemberChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setSelectedMemberId(e.target.value);
  };

  const handleItemChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const item = e.target.value;
    if (e.target.checked) {
      setItems([...items, item]);
    } else {
      setItems(items.filter(i => i !== item));
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedMemberId) return;

    try {
      const response = await fetch(`/api/membership-api/box-customizations`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          memberId: selectedMemberId,
          items,
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to save customization");
      }

      // Refresh data
      const [membersResponse, customizationsResponse] = await Promise.all([
        fetch("/api/membership-api/members"),
        fetch("/api/membership-api/box-customizations"),
      ]);

      if (!membersResponse.ok || !customizationsResponse.ok) {
        throw new Error("Failed to refresh data");
      }

      const membersData = await membersResponse.json();
      const customizationsData = await customizationsResponse.json();

      setMembers(membersData);
      setCustomizations(customizationsData);
      setItems([]);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={containerStyle}>
      <h1>Box Customizer</h1>
      <p>Select your weekly box items:</p>

      <form onSubmit={handleSubmit} style={formStyle}>
        <div style={inputGroupStyle}>
          <label htmlFor="member">Member:</label>
          <select
            id="member"
            value={selectedMemberId}
            onChange={handleMemberChange}
            style={inputStyle}
          >
            <option value="">Select a member</option>
            {members.map(member => (
              <option key={member.id} value={member.id}>
                {member.name}
              </option>
            ))}
          </select>
        </div>

        <div style={inputGroupStyle}>
          <label>Items:</label>
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {[
              "Organic Apples",
              "Free Range Eggs",
              "Local Honey",
              "Fresh Vegetables",
              "Artisan Bread",
              "Herbal Tea",
            ].map(item => (
              <div key={item} style={{ display: "flex", alignItems: "center" }}>
                <input
                  type="checkbox"
                  id={item}
                  value={item}
                  checked={items.includes(item)}
                  onChange={handleItemChange}
                  style={{ marginRight: "10px" }}
                />
                <label htmlFor={item}>{item}</label>
              </div>
            ))}
          </div>
        </div>

        <button type="submit" style={buttonStyle}>Save Customization</button>
      </form>

      <h2>Saved Customizations</h2>
      {customizations.length === 0 ? (
        <p>No customizations found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {customizations.map(customization => {
            const member = members.find(m => m.id === customization.memberId);
            return (
              <div key={customization.id} style={cardStyle}>
                <strong>{member?.name || "Unknown Member"}</strong>
                <ul>
                  {customization.items.map((item, index) => (
                    <li key={index}>{item}</li>
                  ))}
                </ul>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
