{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to job card related routes
  const jobCardRoutes = /^\/job-cards(\/|$)/i;

  if (!jobCardRoutes.test(req.path)) {
    next();
    return;
  }

  // Check if user has required role for the operation
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (!userRole) {
    res.status(401).json({ error: "Unauthorized: Role not provided" });
    return;
  }

  const allowedRoles: Record<string, string[]> = {
    "GET": ["admin", "mechanic", "manager"],
    "POST": ["admin", "manager"],
    "PUT": ["admin", "manager"],
    "DELETE": ["admin"]
  };

  const method = req.method;
  const allowedRolesForMethod = allowedRoles[method] || [];

  if (!allowedRolesForMethod.includes(userRole)) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  next();
}
"}

{"code":"import { useEffect, useState } from "react";

interface AgingBatch {
  id: number;
  cheeseType: string;
  startDate: string;
  endDate?: string;
  status: 'active' | 'completed' | 'failed';
}

export function BatchLogForm() {
  const [batches, setBatches] = useState<AgingBatch[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    cheeseType: '',
    startDate: '',
    endDate: '',
    status: 'active' as 'active' | 'completed' | 'failed',
  });
  const [editingId, setEditingId] = useState<number | null>(null);

  useEffect(() => {
    fetchBatches();
  }, []);

  const fetchBatches = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/aging-batches-api/');
      if (!response.ok) throw new Error('Failed to fetch batches');
      const data = await response.json();
      setBatches(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const url = editingId 
        ? `/api/aging-batches-api/${editingId}`
        : '/api/aging-batches-api/';

      const method = editingId ? 'PUT' : 'POST';

      const response = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      });

      if (!response.ok) throw new Error('Failed to save batch');

      // Reset form
      setFormData({
        cheeseType: '',
        startDate: '',
        endDate: '',
        status: 'active',
      });
      setEditingId(null);

      // Refresh data
      await fetchBatches();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleEdit = (batch: AgingBatch) => {
    setFormData({
      cheeseType: batch.cheeseType,
      startDate: batch.startDate,
      endDate: batch.endDate || '',
      status: batch.status,
    });
    setEditingId(batch.id);
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/aging-batches-api/${id}`, {
        method: 'DELETE',
      });

      if (!response.ok) throw new Error('Failed to delete batch');

      await fetchBatches();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui' }}>
      <h1 style={{ textAlign: 'center' }}>Cheese Aging Batch Log</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px' }}>Cheese Type:</label>
          <input
            type="text"
            name="cheeseType"
            value={formData.cheeseType}
            onChange={handleChange}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ddd' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px' }}>Start Date:</label>
          <input
            type="date"
            name="startDate"
            value={formData.startDate}
            onChange={handleChange}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ddd' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px' }}>End Date (optional):</label>
          <input
            type="date"
            name="endDate"
