import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to the export endpoint
  if (req.method !== "POST" || req.path !== "/export") {
    next();
    return;
  }

  // Check if the user is authenticated and is the owner
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify the JWT properly
  // For this example, we'll assume the token contains owner information
  try {
    // This is a simplified version - in practice, you'd want proper JWT verification
    const [userId, ownerToken] = token.split(":");

    if (!userId || !ownerToken) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    // Create expected token using the same algorithm
    const expectedToken = createHmac("sha256", secret)
      .update(userId + ":owner")
      .digest("hex");

    // Use timingSafeEqual to prevent timing attacks
    const expectedBuffer = Buffer.from(expectedToken);
    const actualBuffer = Buffer.from(ownerToken);

    if (expectedBuffer.length !== actualBuffer.length ||
        !timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    // If we get here, the user is authorized to export
    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized" });
  }
}
"}

