{"code":"import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply scope checking to GET requests to /members/:id
  if (req.method !== "GET" || !req.path.startsWith("/members/")) {
    next();
    return;
  }

  // Extract user ID from request (assuming it's set by auth middleware)
  const authenticatedUserId = (req as any).user?.id;

  // If no authenticated user, allow request to proceed (let other middleware handle it)
  if (!authenticatedUserId) {
    next();
    return;
  }

  // Extract target member ID from URL path
  const pathParts = req.path.split("/");
  const targetMemberId = pathParts[3];

  // If no target member ID, allow request to proceed
  if (!targetMemberId) {
    next();
    return;
  }

  // Check if the authenticated user is trying to access their own data
  if (authenticatedUserId === targetMemberId) {
    next();
    return;
  }

  // If the authenticated user is not accessing their own data, reject the request
  res.status(403).json({ error: "Forbidden: Access denied" });
}
"}

