{"code":"import { Router, type Request, type Response } from "express";
import {
  getAllBookings,
  getBookingById,
  insertBooking,
  updateBooking,
  deleteBooking
} from "../db/bookings-table";

export const router = Router();

// Get all bookings
router.get("/", (req: Request, res: Response) => {
  const bookings = getAllBookings();
  res.json(bookings);
});

// Get a booking by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid booking ID" });
  }

  const booking = getBookingById(id);

  if (!booking) {
    return res.status(404).json({ error: "Booking not found" });
  }

  res.json(booking);
});

// Create a new booking
router.post("/", (req: Request, res: Response) => {
  const { memberId, slotTime, status } = req.body;

  if (!memberId || !slotTime || !status) {
    return res.status(400).json({ error: "Member ID, slot time, and status are required" });
  }

  const id = insertBooking(memberId, slotTime, status);

  res.status(201).json({ id, memberId, slotTime, status });
});

// Update a booking
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { memberId, slotTime, status } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid booking ID" });
  }

  if (!memberId || !slotTime || !status) {
    return res.status(400).json({ error: "Member ID, slot time, and status are required" });
  }

  const existingBooking = getBookingById(id);

  if (!existingBooking) {
    return res.status(404).json({ error: "Booking not found" });
  }

  updateBooking(id, memberId, slotTime, status);

  res.json({ id, memberId, slotTime, status });
});

// Delete a booking
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid booking ID" });
  }

  const existingBooking = getBookingById(id);

  if (!existingBooking) {
    return res.status(404).json({ error: "Booking not found" });
  }

  deleteBooking(id);

  res.json({ message: "Booking deleted successfully" });
});
"}

{"code":"import { Router, type Request, type Response } from "express";
import { Server, getServerById, getServersByOwner, insertServer } from "../db/servers-table";

export const router = Router();

router.post("/servers", (req: Request, res: Response) => {
  const { name, owner, config } = req.body;
  if (typeof name !== "string" || typeof owner !== "string" || typeof config !== "string") {
    res.status(400).send("Invalid input");
    return;
  }
  insertServer(name, owner, config);
  res.status(201).send("Server created");
});

router.get("/servers/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    res.status(400).send("Invalid server ID");
    return;
  }
  const server = getServerById(id);
  if (!server) {
    res.status(404).send("Server not found");
    return;
  }
  res.json(server);
});

router.get("/servers", (req: Request, res: Response) => {
  const owner = req.query.owner as string;
  if (typeof owner !== "string") {
    res.status(400).send("Invalid owner query");
    return;
  }
  const servers = getServersByOwner(owner);
  res.json(servers);
});
"}

{"code":"import { useEffect, useState } from "react";

interface Patient {
  id: string;
  name: string;
  email: string;
}

interface Service {
  id: string;
  name: string;
  price: number;
}

interface Invoice {
  id: string;
  patientId: string;
  services: string[];
  totalAmount: number;
  status: "paid" | "unpaid";
}

export function InvoiceGenerationPage() {
  const [patients, setPatients] = useState<Patient[]>([]);
  const [services, setServices] = useState<Service[]>([]);
  const [selectedPatient, setSelectedPatient] = useState<string>("");
  const [selectedServices, setSelectedServices] = useState<string[]>([]);
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        // Simulate API calls
        await new Promise(resolve => setTimeout(resolve, 500));

        // Mock data for patients
        const mockPatients: Patient[] = [
          { id: "1", name: "John Doe", email: "john@example.com" },
          { id: "2", name: "Jane Smith", email: "jane@example.com" },
          { id: "3", name: "Bob Johnson", email: "bob@example.com" },
        ];

        // Mock data for services
        const mockServices: Service[] = [
          { id: "1", name: "Consultation", price: 100 },
          { id: "2", name: "Blood Test", price: 50 },
          { id: "3", name: "X-Ray", price: 150 },
          { id: "4", name: "Ultrasound", price: 200 },
        ];

        // Mock data for invoices
        const mockInvoices: Invoice[] = [
          { id: "1", patientId: "1", services: ["1", "2"], totalAmount: 150, status: "paid" },
          { id: "2", patientId: "2", services: ["3"], totalAmount: 150, status: "unpaid" },
        ];

        setPatients(mockPatients);
        setServices(mockServices);
        setInvoices(mockInvoices);
        setLoading(false);
      } catch (err) {
        setError("Failed to load data");
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleServiceChange = (serviceId: string) => {
    if (selectedServices.includes(serviceId)) {
      setSelectedServices(selectedServices.filter(id => id !== serviceId));
    } else {
      setSelectedServices([...selectedServices, serviceId]);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedPatient || selectedServices.length === 0) {
      setError("Please select a patient and at least one service");
      return;
    }

    try {
      // Calculate total amount
      const totalAmount = selectedServices
        .map(id => services.find(s => s.id === id)?.price || 0)
        .reduce((sum, price) => sum + price, 0);

      // Simulate API call to create invoice
      await new Promise(resolve => setTimeout(resolve, 500));

      // Mock success response
      const newInvoice: Invoice = {
        id: `${invoices.length + 1}`,
        patientId: selectedPatient,
        services: selectedServices,
        totalAmount,
        status: "unpaid",
      };

      setInvoices([...invoices, newInvoice]);
      setSelectedPatient("");
      setSelectedServices([]);
      setError(null);
    } catch (err) {
      setError("Failed to create invoice");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Invoice Generation</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <div style={{ marginBottom: "15px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Select Patient:</label>
          <select
            value={selectedPatient}
            onChange={(e) => setSelectedPatient(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          >
            <option value="">-- Choose Patient --</option>
            {patients.map(patient => (
              <option key={patient.id} value={patient.id}>{patient.name}</option>
            ))}
          </select>
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>Select Services:</label>
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {services.map(service => (
              <div key={service.id} style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                <input
                  type="checkbox"
                  id={`service-${service.id}`}
                  checked={selectedServices.includes(service.id)}
                  onChange={() => handleServiceChange(service.id)}
                />
                <label htmlFor={`service-${service.id}`} style={{ cursor: "pointer" }}>
                  {service.name} - ${service.price}
                </label>
              </div>
            ))}
          </div>
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: "#007bff", 
            color: "white", 
            border: "none", 
            padding: "10px 20px", 
            borderRadius: "4px", 
            cursor: "pointer" 
          }}
        >
          Generate Invoice
        </button>
      </form>

      <h2 style={{ textAlign: "center" }}>Recent Invoices</h2>

      {invoices.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>No invoices generated yet.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {invoices.map(invoice => {
            const patient = patients.find(p => p.id === invoice.patientId);
            const serviceNames = invoice.services
              .map(id => services.find(s => s.id === id)?.name || "")
              .filter(name => name !== "");

            return (
              <div 
                key={invoice.id} 
                style={{ 
                  padding: "15px", 
                  border: "1px solid #ccc", 
                  borderRadius: "8px", 
                  display: "flex", 
                  justifyContent: "space-between", 
                  alignItems: "center" 
                }}
              >
                <div>
                  <strong>Patient:</strong> {patient?.name || "Unknown"}<br />
                  <strong>Services:</strong> {serviceNames.join(", ") || "None"}<br />
                  <strong>Total:</strong> ${invoice.totalAmount}
                </div>
                <div>
                  <span style={{ 
                    backgroundColor: invoice.status === "paid" ? "#28a745" : "#ffc107", 
                    color: "white", 
                    padding: "5px 10px", 
                    borderRadius: "4px" 
                  }}>
                    {invoice.status.charAt(0).toUpperCase() + invoice.status.slice(1)}
                  </span>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { useState } from "react";

export function RegistrationForm() {
  // Form state
  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phone: "",
    address: "",
    city: "",
    state: "",
    zipCode: "",
    cardNumber: "",
    expiryDate: "",
    cvv: "",
    cardholderName: ""
  });

  // Validation errors
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Form submission status
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);

  // Handle input changes
  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });

    // Clear error when user starts typing
    if (errors[name]) {
      setErrors({
        ...errors,
        [name]: ""
      });
    }
  };

  // Validate form
  const validateForm = () => {
    const newErrors: Record<string, string> = {};

    if (!formData.firstName.trim()) {
      newErrors.firstName = "First name is required";
    }

    if (!formData.lastName.trim()) {
      newErrors.lastName = "Last name is required";
    }

    if (!formData.email.trim()) {
      newErrors.email = "Email is required";
    } else if (!/^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$/.test(formData.email)) {
      newErrors.email = "Invalid email format";
    }

    if (!formData.phone.trim()) {
      newErrors.phone = "Phone number is required";
    }

    if (!formData.address.trim()) {
      newErrors.address = "Address is required";
    }

    if (!formData.city.trim()) {
      newErrors.city = "City is required";
    }

    if (!formData.state.trim()) {
      newErrors.state = "State is required";
    }

    if (!formData.zipCode.trim()) {
      newErrors.zipCode = "ZIP code is required";
    } else if (!/^\d{5}(?:-\d{4})?$/.test(formData.zipCode)) {
      newErrors.zipCode = "Invalid ZIP code format";
    }

    if (!formData.cardNumber.trim()) {
      newErrors.cardNumber = "Card number is required";
    } else if (!/^[0-9]{16}$/.test(formData.cardNumber.replace(/\s/g, ""))) {
      newErrors.cardNumber = "Invalid card number";
    }

    if (!formData.expiryDate.trim()) {
      newErrors.expiryDate = "Expiry date is required";
    } else if (!/^(0[1-9]|1[0-2])\/?(\d{2})$/.test(formData.expiryDate)) {
      newErrors.expiryDate = "Invalid expiry date format (MM/YY)";
    }

    if (!formData.cvv.trim()) {
      newErrors.cvv = "CVV is required";
    } else if (!/^[0-9]{3,4}$/.test(formData.cvv)) {
      newErrors.cvv = "Invalid CVV";
    }

    if (!formData.cardholderName.trim()) {
      newErrors.cardholderName = "Cardholder name is required";
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  // Handle form submission
  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (validateForm()) {
      setIsSubmitting(true);

      // Simulate API call
      setTimeout(() => {
        setIsSubmitting(false);
        setSubmitSuccess(true);

        // Reset form after successful submission
        setTimeout(() => {
          setFormData({
            firstName: "",
            lastName: "",
            email: "",
            phone: "",
            address: "",
            city: "",
            state: "",
            zipCode: "",
            cardNumber: "",
            expiryDate: "",
            cvv: "",
            cardholderName: ""
          });
          setSubmitSuccess(false);
        }, 3000);
      }, 1000);
    }
  };

  // Input style
  const inputStyle: React.CSSProperties = {
    width: "100%",
    padding: "10px",
    border: "1px solid #ccc",
    borderRadius: "4px",
    fontSize: "16px",
    boxSizing: "border-box"
  };

  // Container style
  const containerStyle: React.CSSProperties = {
    maxWidth: "600px",
    margin: "0 auto",
    padding: "20px",
    fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif"
  };

  // Header style
  const headerStyle: React.CSSProperties = {
    textAlign: "center",
    marginBottom: "30px",
    color: "#333"
  };

  // Section style
  const sectionStyle: React.CSSProperties = {
    marginBottom: "20px",
    padding: "20px",
    backgroundColor: "#f9f9f9",
    borderRadius: "8px"
  };

  // Label style
  const labelStyle: React.CSSProperties = {
    display: "block",
    marginBottom: "5px",
    fontWeight: "bold",
    color: "#333"
  };

  // Error style
  const errorStyle: React.CSSProperties = {
    color: "#d32f2f",
    fontSize: "14px",
    marginTop: "5px"
  };

  // Button style
  const buttonStyle: React.CSSProperties = {
    backgroundColor: "#1976d2",
    color: "white",
    border: "none",
    padding: "12px 20px",
    fontSize: "16px",
    borderRadius: "4px",
    cursor: "pointer",
    width: "100%",
    fontWeight: "bold"
  };

  // Success message style
  const successMessageStyle: React.CSSProperties = {
    backgroundColor: "#4caf50",
    color: "white",
    padding: "15px",
    borderRadius: "4px",
    textAlign: "center",
    marginBottom: "20px"
  };

  return (
    <div style={containerStyle}>
      <h1 style={headerStyle}>Marathon Registration</h1>

      {submitSuccess ? (
        <div style={successMessageStyle}>
          Registration successful! Thank you for signing up.
        </div>
      ) : null}

      <form onSubmit={handleSubmit}>
        {/* Personal Information Section */}
        <div style={sectionStyle}>
          <h2 style={{ margin: "0 0 15px 0", color: "#333" }}>Personal Information</h2>

          <div style={{ marginBottom: "15px" }}>
            <label style={labelStyle}>First Name *</label>
            <input
              type="text"
              name="firstName"
              value={formData.firstName}
              onChange={handleChange}
              style={inputStyle}
            />
            {errors.firstName && <div style={errorStyle}>{errors.firstName}</div>}
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label style={labelStyle}>Last Name *</label>
            <input
              type="text"
              name="lastName"
              value={formData.lastName}
              onChange={handleChange}
              style={inputStyle}
            />
            {errors.lastName && <div style={errorStyle}>{errors.lastName}</div>}
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label style={labelStyle}>Email *</label>
            <input
              type="email"
              name="email"
              value={formData.email}
              onChange={handleChange}
              style={inputStyle}
            />
            {errors.email && <div style={errorStyle}>{errors.email}</div>}
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label style={labelStyle}>Phone *</label>
            <input
              type="tel"
              name="phone"
              value={formData.phone}
              onChange={handleChange}
              style={inputStyle}
            />
            {errors.phone && <div style={errorStyle}>{errors.phone}</div>}
          </div>
        </div>

        {/* Address Section */}
        <div style={sectionStyle}>
          <h2 style={{ margin: "0 0 15px 0", color: "#333" }}>Address</h2>

