{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("internship_tracker.db");

interface StudentRow {
  id: number;
  email: string;
  password_hash: string;
  name: string;
  created_at: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS students (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    email TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    name TEXT NOT NULL,
    created_at TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllStudents(): StudentRow[] {
  const stmt = db.prepare(`SELECT * FROM students`);
  return stmt.all() as unknown as StudentRow[];
}

export function getStudentById(id: number): StudentRow | undefined {
  const stmt = db.prepare(`SELECT * FROM students WHERE id = ?`);
  return stmt.get(id) as unknown as StudentRow | undefined;
}

export function insertStudent(
  email: string,
  passwordHash: string,
  name: string
): number {
  const stmt = db.prepare(
    `INSERT INTO students (email, password_hash, name, created_at) VALUES (?, ?, ?, datetime('now'))`
  );
  const result = stmt.run(email, passwordHash, name);
  return Number(result.lastInsertRowid);
}

export function updateStudent(
  id: number,
  email: string,
  passwordHash: string,
  name: string
): void {
  const stmt = db.prepare(
    `UPDATE students SET email = ?, password_hash = ?, name = ? WHERE id = ?`
  );
  stmt.run(email, passwordHash, name, id);
}

export function deleteStudent(id: number): void {
  const stmt = db.prepare(`DELETE FROM students WHERE id = ?`);
  stmt.run(id);
}

