{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const ADMIN_ROLE = "admin";
const STAFF_ROLE = "staff";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to inventory management routes
  const inventoryPaths = ["/inventory", "/inventory/"];
  const isInventoryRoute = inventoryPaths.some(path => 
    req.path.startsWith(path) || 
    req.path === path
  );

  // Skip validation for non-inventory routes
  if (!isInventoryRoute) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  // For now, we'll allow both admin and staff to access inventory
  // In a real implementation, this would be more restrictive
  if (userRole === ADMIN_ROLE || userRole === STAFF_ROLE) {
    next();
    return;
  }

  // If no valid role is found, deny access
  res.status(403).json({ error: "Access denied: insufficient permissions" });
}
"}

{"code":"import { useEffect, useState } from "react";

interface Movie {
  id: number;
  title: string;
  year: number;
  director: string;
}

export function WatchlistBrowser() {
  const [movies, setMovies] = useState<Movie[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [newMovie, setNewMovie] = useState({
    title: "",
    year: "",
    director: ""
  });

  useEffect(() => {
    fetchMovies();
  }, []);

  const fetchMovies = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/watchlist-api/");
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setMovies(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleAddMovie = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/watchlist-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          title: newMovie.title,
          year: parseInt(newMovie.year),
          director: newMovie.director
        })
      });
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      setNewMovie({ title: "", year: "", director: "" });
      fetchMovies();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDeleteMovie = async (id: number) => {
    try {
      const response = await fetch(`/api/watchlist-api/${id}`, {
        method: "DELETE"
      });
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      fetchMovies();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const movieListStyle: React.CSSProperties = {
    display: "flex",
    flexWrap: "wrap",
    gap: "16px",
    marginBottom: "24px"
  };

  const movieCardStyle: React.CSSProperties = {
    border: "1px solid #ccc",
    borderRadius: "8px",
    padding: "16px",
    width: "250px",
    boxSizing: "border-box"
  };

  const inputStyle: React.CSSProperties = {
    width: "100%",
    padding: "8px",
    marginBottom: "12px",
    borderRadius: "4px",
    border: "1px solid #ddd",
    boxSizing: "border-box"
  };

  const buttonStyle: React.CSSProperties = {
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    borderRadius: "4px",
    padding: "8px 16px",
    cursor: "pointer",
    marginRight: "8px"
  };

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;

  return (
    <div style={{
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      maxWidth: "800px",
      margin: "0 auto",
      padding: "16px"
    }}>
      <h1>My Watchlist</h1>

      {movies.length === 0 ? (
        <p>No movies in your watchlist yet.</p>
      ) : (
        <div style={movieListStyle}>
          {movies.map(movie => (
            <div key={movie.id} style={movieCardStyle}>
              <h3>{movie.title}</h3>
              <p>Year: {movie.year}</p>
              <p>Director: {movie.director}</p>
              <button 
                onClick={() => handleDeleteMovie(movie.id)}
                style={buttonStyle}
              >
                Remove
              </button>
            </div>
          ))}
        </div>
      )}

      <h2>Add New Movie</h2>
      <form onSubmit={handleAddMovie}>
        <input
          type="text"
          placeholder="Title"
          value={newMovie.title}
          onChange={(e) => setNewMovie({...newMovie, title: e.target.value})}
          style={inputStyle}
        />
        <input
          type="text"
          placeholder="Year"
          value={newMovie.year}
          onChange={(e) => setNewMovie({...newMovie, year: e.target.value})}
          style={inputStyle}
        />
        <input
          type="text"
          placeholder="Director"
          value={newMovie.director}
          onChange={(e) => setNewMovie({...newMovie, director: e.target.value})}
          style={inputStyle}
        />
        <button type="submit" style={buttonStyle}>Add to Watchlist</button>
      </form>
    </div>
  );
}
"}

