  date: string;
  topic: string;
}

export function SessionSearch() {
  const [sessions, setSessions] = useState<Session[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [filter, setFilter] = useState<"tutor" | "date" | "topic">("tutor");

  useEffect(() => {
    fetchSessions();
  }, []);

  const fetchSessions = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/sessions-table/`);
      if (!response.ok) {
        throw new Error(`Failed to fetch sessions: ${response.status}`);
      }
      const data = await response.json();
      setSessions(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    fetchSessions();
  };

  const filteredSessions = sessions.filter(session => {
    if (!searchTerm) return true;
    switch (filter) {
      case "tutor":
        return session.tutor.toLowerCase().includes(searchTerm.toLowerCase());
      case "date":
        return session.date.toLowerCase().includes(searchTerm.toLowerCase());
      case "topic":
        return session.topic.toLowerCase().includes(searchTerm.toLowerCase());
      default:
        return true;
    }
  });

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Session Search</h1>

      <form onSubmit={handleSearch} style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc", width: "100%" }}
        />
        <select
          value={filter}
          onChange={(e) => setFilter(e.target.value as "tutor" | "date" | "topic")}
          style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc", width: "100%" }}
