export const router = Router();

// Mock database functions - in a real app these would come from a database module
const mockDatabase = {
  createShift: (shiftData: any) => Promise.resolve({ id: 1, ...shiftData }),
  getShiftById: (id: number) => Promise.resolve({ id: 1, employeeId: 123, date: "2023-05-01", startTime: "08:00", endTime: "16:00" }),
  getAllShifts: () => Promise.resolve([
    { id: 1, employeeId: 123, date: "2023-05-01", startTime: "08:00", endTime: "16:00" },
    { id: 2, employeeId: 456, date: "2023-05-02", startTime: "09:00", endTime: "17:00" }
  ]),
  updateShift: (id: number, shiftData: any) => Promise.resolve({ id, ...shiftData }),
  deleteShift: (id: number) => Promise.resolve(true)
};

// GET /api/shifts - Get all shifts
router.get("/", async (req: Request, res: Response) => {
  try {
    const shifts = await mockDatabase.getAllShifts();
    return res.json(shifts);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch shifts" });
  }
});

// GET /api/shifts/:id - Get a specific shift by ID
router.get("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid shift ID" });
    }

    const shift = await mockDatabase.getShiftById(id);
    if (!shift) {
      return res.status(404).json({ error: "Shift not found" });
    }

    return res.json(shift);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch shift" });
  }
});

// POST /api/shifts - Create a new shift
router.post("/", async (req: Request, res: Response) => {
  try {
    const { employeeId, date, startTime, endTime } = req.body;

    // Basic validation
    if (!employeeId || !date || !startTime || !endTime) {
      return res.status(400).json({ error: "Missing required fields: employeeId, date, startTime, endTime" });
    }

    const newShift = await mockDatabase.createShift({ employeeId, date, startTime, endTime });
    return res.status(201).json(newShift);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create shift" });
  }
});

// PUT /api/shifts/:id - Update an existing shift
router.put("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid shift ID" });
    }

    const { employeeId, date, startTime, endTime } = req.body;

    // Basic validation
    if (!employeeId || !date || !startTime || !endTime) {
      return res.status(400).json({ error: "Missing required fields: employeeId, date, startTime, endTime" });
    }

    const updatedShift = await mockDatabase.updateShift(id, { employeeId, date, startTime, endTime });

    if (!updatedShift) {
      return res.status(404).json({ error: "Shift not found" });
    }

    return res.json(updatedShift);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update shift" });
  }
});

// DELETE /api/shifts/:id - Delete a shift
router.delete("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid shift ID" });
    }

    const deleted = await mockDatabase.deleteShift(id);

    if (!deleted) {
      return res.status(404).json({ error: "Shift not found" });
    }

    return res.json({ message: "Shift deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete shift" });
  }
});
"}

{"code":"import { useEffect, useState } from "react";

interface Booking {
  id: string;
  classTitle: string;
  date: string;
  time: string;
  duration: number;
}

export function UserDashboard() {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchUpcomingBookings();
  }, []);

  const fetchUpcomingBookings = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/user/bookings');
      if (!response.ok) {
        throw new Error('Failed to fetch bookings');
      }
      const data = await response.json();
      setBookings(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleCancelBooking = async (bookingId: string) => {
    try {
      const response = await fetch(`/api/user/bookings/${bookingId}`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        throw new Error('Failed to cancel booking');
      }
      // Refresh the bookings list
      fetchUpcomingBookings();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (bookings.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No upcoming bookings found.</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Your Upcoming Bookings</h1>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        {bookings.map((booking) => (
          <div 
            key={booking.id} 
            style={{ 
              border: '1px solid #ddd', 
              borderRadius: '8px', 
              padding: '15px', 
              display: 'flex', 
              justifyContent: 'space-between', 
              alignItems: 'center'
            }}
          >
            <div>
              <h3 style={{ margin: '0 0 5px 0' }}>{booking.classTitle}</h3>
              <p style={{ margin: '0 0 5px 0' }}>
                {new Date(booking.date).toLocaleDateString()} at {booking.time}
              </p>
              <p style={{ margin: '0 0 5px 0' }}>
                Duration: {booking.duration} minutes
              </p>
            </div>
            <button 
              onClick={() => handleCancelBooking(booking.id)}
              style={{ 
                backgroundColor: '#ff4d4d', 
                color: 'white', 
                border: 'none', 
                borderRadius: '4px', 
                padding: '8px 12px', 
                cursor: 'pointer'
              }}
            >
              Cancel
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}
