{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./documents.db");

interface DocumentRow {
  id: number;
  title: string;
  content: string;
  author: string;
  created_at: string;
  updated_at: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS documents (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    content TEXT NOT NULL,
    author TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllDocuments(): DocumentRow[] {
  const stmt = db.prepare("SELECT * FROM documents ORDER BY created_at DESC");
  return stmt.all() as unknown as DocumentRow[];
}

export function getDocumentById(id: number): DocumentRow | undefined {
  const stmt = db.prepare("SELECT * FROM documents WHERE id = ?");
  return stmt.get(id) as unknown as DocumentRow | undefined;
}

export function insertDocument(
  title: string,
  content: string,
  author: string
): number {
  const stmt = db.prepare(
    "INSERT INTO documents (title, content, author, created_at, updated_at) VALUES (?, ?, ?, datetime('now'), datetime('now'))"
  );
  const result = stmt.run(title, content, author);
  return Number(result.lastInsertRowid);
}

export function updateDocument(
  id: number,
  title: string,
  content: string,
  author: string
): void {
  const stmt = db.prepare(
    "UPDATE documents SET title = ?, content = ?, author = ?, updated_at = datetime('now') WHERE id = ?"
  );
  stmt.run(title, content, author, id);
}

export function deleteDocument(id: number): void {
  const stmt = db.prepare("DELETE FROM documents WHERE id = ?");
  stmt.run(id);
}

// Seed data
if (getAllDocuments().length === 0) {
  insertDocument(
    "Annual Report 2023",
    "This document contains the financial summary and operational highlights for the year 2023.",
    "Finance Department"
  );

  insertDocument(
    "Project Proposal Template",
    "A standard format for submitting new project proposals including budget and timeline details.",
    "Project Management Office"
  );

  insertDocument(
    "Employee Handbook",
    "Comprehensive guide to company policies, benefits, and workplace procedures.",
    "Human Resources"
  );

  insertDocument(
    "Technical Specifications",
    "Detailed technical requirements and specifications for the upcoming software release.",
    "Engineering Team"
  );

  insertDocument(
    "Meeting Minutes - Q1 Planning",
    "Summary of key decisions and action items from the quarterly planning session.",
    "Executive Leadership"
  );
}
"}

