  CREATE TABLE IF NOT EXISTS docents (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    credentials TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllDocents(): Docent[] {
  const stmt = db.prepare("SELECT * FROM docents");
  return stmt.all() as unknown as Docent[];
}

export function getDocentById(id: number): Docent | undefined {
  const stmt = db.prepare("SELECT * FROM docents WHERE id = ?");
  return stmt.get(id) as unknown as Docent | undefined;
}

export function insertDocent(name: string, credentials: string): number {
  const stmt = db.prepare(
    "INSERT INTO docents (name, credentials) VALUES (?, ?)"
  );
  const result = stmt.run(name, credentials);
  return Number(result.lastInsertRowid);
}

export function updateDocent(
  id: number,
  name: string,
  credentials: string
): void {
  const stmt = db.prepare(
    "UPDATE docents SET name = ?, credentials = ? WHERE id = ?"
  );
  stmt.run(name, credentials, id);
}

export function deleteDocent(id: number): void {
  const stmt = db.prepare("DELETE FROM docents WHERE id = ?");
  stmt.run(id);
