{"code":"import { useEffect, useState } from "react";

interface Student {
  id: number;
  name: string;
  email: string;
}

interface Class {
  id: number;
  title: string;
  description: string;
  schedule: string;
}

interface Booking {
  id: number;
  studentId: number;
  classId: number;
  status: "confirmed" | "pending" | "cancelled";
  bookingDate: string;
}

export function BookingManagement() {
  const [students, setStudents] = useState<Student[]>([]);
  const [classes, setClasses] = useState<Class[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Mock data for demonstration
  useEffect(() => {
    const mockStudents: Student[] = [
      { id: 1, name: "Alice Johnson", email: "alice@example.com" },
      { id: 2, name: "Bob Smith", email: "bob@example.com" },
      { id: 3, name: "Charlie Brown", email: "charlie@example.com" },
    ];

    const mockClasses: Class[] = [
      { id: 1, title: "Piano Basics", description: "Learn basic piano skills", schedule: "Mon 6:00 PM" },
      { id: 2, title: "Guitar Fundamentals", description: "Start your guitar journey", schedule: "Tue 7:00 PM" },
      { id: 3, title: "Violin Mastery", description: "Advanced violin techniques", schedule: "Wed 5:00 PM" },
    ];

    const mockBookings: Booking[] = [
      { id: 1, studentId: 1, classId: 1, status: "confirmed", bookingDate: "2023-05-01" },
      { id: 2, studentId: 2, classId: 2, status: "pending", bookingDate: "2023-05-02" },
      { id: 3, studentId: 3, classId: 3, status: "cancelled", bookingDate: "2023-05-03" },
    ];

    setTimeout(() => {
      setStudents(mockStudents);
      setClasses(mockClasses);
      setBookings(mockBookings);
      setLoading(false);
    }, 500);
  }, []);

  const filteredBookings = bookings.filter(booking => {
    const student = students.find(s => s.id === booking.studentId);
    const className = classes.find(c => c.id === booking.classId)?.title || "";

    return (
      student?.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      className.toLowerCase().includes(searchTerm.toLowerCase())
    );
  });

  const handleStatusChange = (bookingId: number, newStatus: "confirmed" | "pending" | "cancelled") => {
    setBookings(prev => 
      prev.map(b => b.id === bookingId ? { ...b, status: newStatus } : b)
    );
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case "confirmed": return "#4caf50";
      case "pending": return "#ff9800";
      case "cancelled": return "#f44336";
      default: return "#9e9e9e";
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Booking Management</h1>

      <div style={{ marginBottom: "20px" }}>
        <input
          type="text"
          placeholder="Search by student or class..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        />
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        {filteredBookings.length === 0 ? (
          <p style={{ textAlign: "center", padding: "20px" }}>No bookings found.</p>
        ) : (
          filteredBookings.map(booking => {
            const student = students.find(s => s.id === booking.studentId);
            const className = classes.find(c => c.id === booking.classId)?.title || "Unknown Class";

            return (
              <div key={booking.id} style={{ border: "1px solid #ddd", borderRadius: "8px", padding: "15px", backgroundColor: "#f9f9f9" }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                  <div>
                    <h3>{student?.name}</h3>
                    <p><strong>Class:</strong> {className}</p>
                    <p><strong>Date:</strong> {booking.bookingDate}</p>
                  </div>
                  <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end" }}>
                    <span style={{ backgroundColor: getStatusColor(booking.status), color: "white", padding: "4px 8px", borderRadius: "4px", fontSize: "14px" }}>
                      {booking.status.charAt(0).toUpperCase() + booking.status.slice(1)}
                    </span>
                    <div style={{ marginTop: "10px", display: "flex", gap: "5px" }}>
                      <button 
                        onClick={() => handleStatusChange(booking.id, "confirmed")}
                        style={{ padding: "4px 8px", backgroundColor: "#4caf50", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
                      >
                        Confirm
                      </button>
                      <button 
                        onClick={() => handleStatusChange(booking.id, "pending")}
                        style={{ padding: "4px 8px", backgroundColor: "#ff9800", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
                      >
                        Pending
                      </button>
                      <button 
                        onClick={() => handleStatusChange(booking.id, "cancelled")}
                        style={{ padding: "4px 8px", backgroundColor: "#f44336", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
                      >
                        Cancel
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

interface Patient {
  id: number;
  name: string;
  phone: string;
  email: string;
}

export function PatientManagement() {
  const [patients, setPatients] = useState<Patient[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Form state
  const [formData, setFormData] = useState({
    name: "",
    phone: "",
    email: ""
  });

  const [editingId, setEditingId] = useState<number | null>(null);
  const [searchTerm, setSearchTerm] = useState("");

  // Fetch patients
  useEffect(() => {
    const fetchPatients = async () => {
      try {
        const response = await fetch('/api/patients');
        if (!response.ok) throw new Error('Failed to fetch patients');
        const data = await response.json();
        setPatients(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
        setLoading(false);
      }
    };

    fetchPatients();
  }, []);

  // Handle form input changes
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  // Handle form submission
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = await fetch('/api/patients', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });

      if (!response.ok) throw new Error('Failed to add patient');

      const newPatient = await response.json();
      setPatients(prev => [...prev, newPatient]);
      setFormData({ name: '', phone: '', email: '' });
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  // Handle update
  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId === null) return;

    try {
      const response = await fetch(`/api/patients/${editingId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });

      if (!response.ok) throw new Error('Failed to update patient');

      const updatedPatient = await response.json();
      setPatients(prev => 
        prev.map(p => p.id === editingId ? updatedPatient : p)
      );
      setEditingId(null);
      setFormData({ name: '', phone: '', email: '' });
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  // Handle delete
  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/patients/${id}`, {
        method: 'DELETE'
      });

      if (!response.ok) throw new Error('Failed to delete patient');

      setPatients(prev => prev.filter(p => p.id !== id));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  // Start editing
  const startEditing = (patient: Patient) => {
    setFormData({ name: patient.name, phone: patient.phone, email: patient.email });
    setEditingId(patient.id);
  };

  // Filter patients based on search term
  const filteredPatients = patients.filter(patient => 
    patient.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    patient.phone.includes(searchTerm)
  );

  // Styles
  const containerStyle: React.CSSProperties = {
    maxWidth: '800px',
    margin: '0 auto',
    padding: '20px',
    fontFamily: 'system-ui, sans-serif'
  };

  const formStyle: React.CSSProperties = {
    display: 'flex',
    flexDirection: 'column',
    gap: '10px',
    marginBottom: '20px',
    padding: '15px',
    border: '1px solid #ccc',
    borderRadius: '5px'
  };

  const inputStyle: React.CSSProperties = {
    padding: '8px',
    borderRadius: '4px',
    border: '1px solid #ddd',
    width: '100%',
    boxSizing: 'border-box'
  };

  const buttonStyle: React.CSSProperties = {
    padding: '8px 12px',
    backgroundColor: '#007bff',
    color: 'white',
    border: 'none',
    borderRadius: '4px',
    cursor: 'pointer'
  };

  const listStyle: React.CSSProperties = {
    display: 'flex',
    flexWrap: 'wrap',
    gap: '10px'
  };

  const cardStyle: React.CSSProperties = {
    border: '1px solid #ddd',
    borderRadius: '5px',
    padding: '15px',
    width: '100%',
    maxWidth: '300px'
  };

  const buttonGroupStyle: React.CSSProperties = {
    display: 'flex',
    gap: '5px',
    marginTop: '10px'
  };

  if (loading) return <div style={containerStyle}>Loading...</div>;
  if (error) return <div style={containerStyle}>Error: {error}</div>;

  return (
    <div style={containerStyle}>
      <h1>Patient Management</h1>

      <form onSubmit={editingId ? handleUpdate : handleSubmit} style={formStyle}>
        <input
          type="text"
          name="name"
          placeholder="Name"
          value={formData.name}
          onChange={handleInputChange}
          style={inputStyle}
        />
        <input
          type="text"
          name="phone"
          placeholder="Phone"
          value={formData.phone}
          onChange={handleInputChange}
          style={inputStyle}
        />
        <input
          type="email"
          name="email"
          placeholder="Email"
          value={formData.email}
          onChange={handleInputChange}
          style={inputStyle}
        />
        <button type="submit" style={buttonStyle}>
          {editingId ? 'Update Patient' : 'Add Patient'}
        </button>
      </form>

      <input
        type="text"
        placeholder="Search by name or phone"
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
        style={inputStyle}
      />

      <div style={listStyle}>
        {filteredPatients.length === 0 ? (
          <p>No patients found.</p>
        ) : (
          filteredPatients.map(patient => (
            <div key={patient.id} style={cardStyle}>
              <h3>{patient.name}</h3>
              <p>Phone: {patient.phone}</p>
              <p>Email: {patient.email}</p>
              <div style={buttonGroupStyle}>
                <button onClick={() => startEditing(patient)} style={buttonStyle}>Edit</button>
