{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface Post {
  id: number;
  created_at: string;
  updated_at: string;
  title: string;
  content: string;
  status: "published" | "draft";
}

const createPostsTable = `
  CREATE TABLE IF NOT EXISTS posts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    title TEXT NOT NULL,
    content TEXT NOT NULL,
    status TEXT NOT NULL CHECK(status IN ('published', 'draft'))
  );
`;

db.exec(createPostsTable);

export const getAllPosts = (): Post[] => {
  const stmt = db.prepare(`SELECT * FROM posts ORDER BY created_at DESC`);
  return stmt.all() as unknown as Post[];
};

export const getPostById = (id: number): Post | undefined => {
  const stmt = db.prepare(`SELECT * FROM posts WHERE id = ?`);
  return stmt.get(id) as unknown as Post | undefined;
};

export const insertPost = (post: Omit<Post, "id" | "created_at" | "updated_at">): number => {
  const stmt = db.prepare(
    `INSERT INTO posts (title, content, status, created_at, updated_at) VALUES (?, ?, ?, ?, ?)`
  );
  const result = stmt.run(post.title, post.content, post.status, new Date().toISOString(), new Date().toISOString());
  return Number(result.lastInsertRowid);
};

export const updatePost = (
  id: number,
  post: Partial<Omit<Post, "id" | "created_at" | "updated_at">>
): boolean => {
  const fields = Object.keys(post);
  if (fields.length === 0) return false;

  const setClause = fields.map(field => `${field} = ?`).join(", ");
  const values = [...Object.values(post), id];

  const stmt = db.prepare(`UPDATE posts SET ${setClause}, updated_at = ? WHERE id = ?`);
  const result = stmt.run(...values, new Date().toISOString());
  return result.changes > 0;
};

export const deletePost = (id: number): boolean => {
  const stmt = db.prepare(`DELETE FROM posts WHERE id = ?`);
  const result = stmt.run(id);
  return result.changes > 0;
};

// Seed data
if (getAllPosts().length === 0) {
  insertPost({
    title: "Getting Started with TypeScript",
    content: "TypeScript is a superset of JavaScript that adds static typing...",
    status: "published"
  });

  insertPost({
    title: "Understanding React Hooks",
    content: "React Hooks allow you to use state and other React features without writing a class...",
    status: "draft"
  });

  insertPost({
    title: "Node.js Best Practices",
    content: "When building Node.js applications, consider performance and security...",
    status: "published"
  });

  insertPost({
    title: "Mastering CSS Grid",
    content: "CSS Grid Layout is a two-dimensional layout system for the web...",
    status: "draft"
  });

  insertPost({
    title: "Building RESTful APIs",
    content: "RESTful APIs are designed around resources and HTTP methods...",
    status: "published"
  });
}
"}

{"code":"import { useEffect, useState } from "react";

interface InventoryItem {
  id: number;
  name: string;
  category: string;
  quantity: number;
  price: number;
}

export function InventoryListPage() {
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [sortConfig, setSortConfig] = useState<{ key: keyof InventoryItem; direction: 'asc' | 'desc' } | null>(null);

  useEffect(() => {
    fetchInventory();
  }, []);

  const fetchInventory = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/inventory');
      if (!response.ok) {
        throw new Error('Failed to fetch inventory');
      }
      const data = await response.json();
      setItems(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/inventory/${id}`, { method: 'DELETE' });
      if (!response.ok) {
        throw new Error('Failed to delete item');
      }
      // Refresh the list after deletion
      fetchInventory();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleSort = (key: keyof InventoryItem) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const sortedItems = [...items];
  if (sortConfig !== null) {
    sortedItems.sort((a, b) => {
      if (a[sortConfig.key] < b[sortConfig.key]) {
        return sortConfig.direction === 'asc' ? -1 : 1;
      }
      if (a[sortConfig.key] > b[sortConfig.key]) {
        return sortConfig.direction === 'asc' ? 1 : -1;
      }
      return 0;
    });
  }

  const filteredItems = sortedItems.filter(item =>
    item.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    item.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Inventory List</h1>

      <div style={{ marginBottom: '20px' }}>
        <input
          type="text"
          placeholder="Search items..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: '100%', padding: '10px', borderRadius: '4px', border: '1px solid #ccc' }}
        />
      </div>

      {filteredItems.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '20px' }}>No items found.</div>
      ) : (
        <div style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ backgroundColor: '#f2f2f2' }}>
                <th style={{ padding: '10px', border: '1px solid #ddd', cursor: 'pointer' }} onClick={() => handleSort('name')}>
                  Name {sortConfig?.key === 'name' && (sortConfig.direction === 'asc' ? '↑' : '↓')}
                </th>
                <th style={{ padding: '10px', border: '1px solid #ddd', cursor: 'pointer' }} onClick={() => handleSort('category')}>
                  Category {sortConfig?.key === 'category' && (sortConfig.direction === 'asc' ? '↑' : '↓')}
                </th>
                <th style={{ padding: '10px', border: '1px solid #ddd', cursor: 'pointer' }} onClick={() => handleSort('quantity')}>
                  Quantity {sortConfig?.key === 'quantity' && (sortConfig.direction === 'asc' ? '↑' : '↓')}
                </th>
                <th style={{ padding: '10px', border: '1px solid #ddd', cursor: 'pointer' }} onClick={() => handleSort('price')}>
                  Price {sortConfig?.key === 'price' && (sortConfig.direction === 'asc' ? '↑' : '↓')}
                </th>
                <th style={{ padding: '10px', border: '1px solid #ddd' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredItems.map(item => (
                <tr key={item.id} style={{ borderBottom: '1px solid #ddd' }}>
                  <td style={{ padding: '10px', border: '1px solid #ddd' }}>{item.name}</td>
                  <td style={{ padding: '10px', border: '1px solid #ddd' }}>{item.category}</td>
                  <td style={{ padding: '10px', border: '1px solid #ddd' }}>{item.quantity}</td>
                  <td style={{ padding: '10px', border: '1px solid #ddd' }}>${item.price.toFixed(2)}</td>
                  <td style={{ padding: '10px', border: '1px solid #ddd' }}>
                    <div style={{ display: 'flex', gap: '5px' }}>
                      <button 
                        style={{ padding: '5px 10px', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
                        onClick={() => window.location.href = `/inventory/${item.id}`}
                      >
                        View
                      </button>
                      <button 
                        style={{ padding: '5px 10px', backgroundColor: '#28a745', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
                        onClick={() => window.location.href = `/inventory/edit/${item.id}`}
                      >
                        Edit
                      </button>
                      <button 
                        style={{ padding: '5px 10px', backgroundColor: '#dc3545', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
                        onClick={() => handleDelete(item.id)}
                      >
                        Delete
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
"}

