{"code":"import { useEffect, useState } from "react";

interface ExamResult {
  id: string;
  studentName: string;
  subject: string;
  score: number;
  grade: string;
}

export function EditExamResultForm() {
  const [examResults, setExamResults] = useState<ExamResult[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<ExamResult>>({});
  const [editingId, setEditingId] = useState<string | null>(null);

  useEffect(() => {
    fetchExamResults();
  }, []);

  const fetchExamResults = async () => {
    try {
      const response = await fetch('/api/exam-results');
      if (!response.ok) {
        throw new Error('Failed to fetch exam results');
      }
      const results = await response.json();
      setExamResults(results);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: name === 'score' ? Number(value) : value
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!editingId) return;

    try {
      const response = await fetch(`/api/exam-results/${editingId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(formData)
      });

      if (!response.ok) {
        throw new Error('Failed to update exam result');
      }

      // Refresh the list
      await fetchExamResults();

      // Reset form
      setFormData({});
      setEditingId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const startEditing = (result: ExamResult) => {
    setFormData(result);
    setEditingId(result.id);
  };

  const cancelEditing = () => {
    setFormData({});
    setEditingId(null);
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Edit Exam Results</h1>

      {editingId && (
        <form onSubmit={handleSubmit} style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
          <div style={{ marginBottom: '15px' }}>
            <label>Student Name:</label>
            <input
              type="text"
              name="studentName"
              value={formData.studentName || ''}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px', marginTop: '5px' }}
            />
          </div>

          <div style={{ marginBottom: '15px' }}>
            <label>Subject:</label>
            <input
              type="text"
              name="subject"
              value={formData.subject || ''}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px', marginTop: '5px' }}
            />
          </div>

          <div style={{ marginBottom: '15px' }}>
            <label>Score:</label>
            <input
              type="number"
              name="score"
              value={formData.score || ''}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px', marginTop: '5px' }}
            />
          </div>

          <div style={{ marginBottom: '15px' }}>
            <label>Grade:</label>
            <select
              name="grade"
              value={formData.grade || ''}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px', marginTop: '5px' }}
            >
              <option value="A+">A+</option>
              <option value="A">A</option>
              <option value="B+">B+</option>
              <option value="B">B</option>
              <option value="C+">C+</option>
              <option value="C">C</option>
              <option value="D+">D+</option>
              <option value="D">D</option>
              <option value="F">F</option>
            </select>
          </div>

          <button type="submit" style={{ backgroundColor: '#4CAF50', color: 'white', padding: '10px 15px', border: 'none', borderRadius: '4px', cursor: 'pointer', marginRight: '10px' }}>
            Save Changes
          </button>
          <button type="button" onClick={cancelEditing} style={{ backgroundColor: '#f44336', color: 'white', padding: '10px 15px', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>
            Cancel
          </button>
        </form>
      )}

      <div>
        {examResults.length === 0 ? (
          <p style={{ textAlign: 'center', padding: '20px' }}>No exam results found.</p>
        ) : (
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ borderBottom: '2px solid #ddd' }}>
                <th style={{ padding: '12px', textAlign: 'left' }}>Student Name</th>
                <th style={{ padding: '12px', textAlign: 'left' }}>Subject</th>
                <th style={{ padding: '12px', textAlign: 'left' }}>Score</th>
                <th style={{ padding: '12px', textAlign: 'left' }}>Grade</th>
                <th style={{ padding: '12px', textAlign: 'left' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {examResults.map((result) => (
                <tr key={result.id} style={{ borderBottom: '1px solid #ddd' }}>
                  <td style={{ padding: '12px' }}>{result.studentName}</td>
                  <td style={{ padding: '12px' }}>{result.subject}</td>
                  <td style={{ padding: '12px' }}>{result.score}</td>
                  <td style={{ padding: '12px' }}>{result.grade}</td>
                  <td style={{ padding: '12px' }}>
                    <button 
                      onClick={() => startEditing(result)}
                      style={{ backgroundColor: '#2196F3', color: 'white', padding: '6px 10px', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
                    >
