  CREATE TABLE IF NOT EXISTS commerce_records (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    type TEXT NOT NULL,
    data TEXT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
  )
`;

db.exec(createTableSql);

export interface CommerceRecord {
  id: number;
  type: string;
  data: string;
  created_at: string;
  updated_at: string;
}

export function getAllRecords(): CommerceRecord[] {
  const stmt = db.prepare(`SELECT * FROM commerce_records`);
  return stmt.all() as unknown as CommerceRecord[];
}

export function getRecordById(id: number): CommerceRecord | undefined {
  const stmt = db.prepare(`SELECT * FROM commerce_records WHERE id = ?`);
  return stmt.get(id) as unknown as CommerceRecord | undefined;
}

export function insertRecord(type: string, data: string): number {
  const stmt = db.prepare(
    `INSERT INTO commerce_records (type, data) VALUES (?, ?)`
  );
  const result = stmt.run(type, data);
  return Number(result.lastInsertRowid);
}

export function updateRecord(id: number, type: string, data: string): boolean {
  const stmt = db.prepare(
    `UPDATE commerce_records SET type = ?, data = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?`
  );
  const result = stmt.run(type, data, id);
  return result.changes > 0;
}

export function deleteRecord(id: number): boolean {
  const stmt = db.prepare(`DELETE FROM commerce_records WHERE id = ?`);
