{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock company data storage
let companies = [
  { id: 1, name: "Tech Corp", contact: "john@techcorp.com", location: "San Francisco" },
  { id: 2, name: "Innovate Inc", contact: "sarah@innovate.com", location: "New York" }
];

