// GET /companies - List all companies
router.get("/companies", (req: Request, res: Response) => {
  res.json(companies);
});

// GET /companies/:id - Get a company by ID
router.get("/companies/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const company = companies.find(c => c.id === id);

  if (!company) {
    return res.status(404).json({ error: "Company not found" });
  }

  res.json(company);
});

// POST /companies - Create a new company
router.post("/companies", (req: Request, res: Response) => {
  const { name, contact, location } = req.body;

  if (!name || !contact || !location) {
    return res.status(400).json({ error: "Name, contact, and location are required" });
  }

  const newCompany = {
    id: nextId++,
    name,
    contact,
    location
  };

  companies.push(newCompany);
  res.status(201).json(newCompany);
});

// PUT /companies/:id - Update a company
router.put("/companies/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { name, contact, location } = req.body;

  const companyIndex = companies.findIndex(c => c.id === id);

  if (companyIndex === -1) {
    return res.status(404).json({ error: "Company not found" });
  }

  if (!name || !contact || !location) {
    return res.status(400).json({ error: "Name, contact, and location are required" });
  }

  companies[companyIndex] = {
    id,
    name,
    contact,
    location
  };

  res.json(companies[companyIndex]);
});

// DELETE /companies/:id - Delete a company
router.delete("/companies/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const companyIndex = companies.findIndex(c => c.id === id);

  if (companyIndex === -1) {
    return res.status(404).json({ error: "Company not found" });
  }

  companies.splice(companyIndex, 1);
  res.json({ message: "Company deleted successfully" });
});
