{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteHarvestEntry,
  getAllHarvestEntries,
  getHarvestEntryById,
  insertHarvestEntry,
  updateHarvestEntry
} from "../db/harvest-entries-table";

export const router = Router();

// Get all harvest entries for the logged-in worker's plot
router.get("/", (req: Request, res: Response) => {
  try {
    const entries = getAllHarvestEntries();
    return res.json(entries);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch harvest entries" });
  }
});

// Get a specific harvest entry by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid entry ID" });
  }

  const entry = getHarvestEntryById(id);

  if (!entry) {
    return res.status(404).json({ error: "Harvest entry not found" });
  }

  return res.json(entry);
});

// Create a new harvest entry
router.post("/", (req: Request, res: Response) => {
  const { plotId, quantity, ownerId } = req.body;

  if (typeof plotId !== "number" || typeof quantity !== "number" || typeof ownerId !== "number") {
    return res.status(400).json({ error: "plotId, quantity, and ownerId must be numbers" });
  }

  try {
    const newId = insertHarvestEntry(plotId, quantity, ownerId);
    const newEntry = getHarvestEntryById(newId);

    if (!newEntry) {
      return res.status(500).json({ error: "Failed to retrieve created harvest entry" });
    }

    return res.status(201).json(newEntry);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create harvest entry" });
  }
});

// Update an existing harvest entry
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { plotId, quantity, ownerId } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid entry ID" });
  }

  if (typeof plotId !== "number" || typeof quantity !== "number" || typeof ownerId !== "number") {
    return res.status(400).json({ error: "plotId, quantity, and ownerId must be numbers" });
  }

  const existingEntry = getHarvestEntryById(id);

  if (!existingEntry) {
    return res.status(404).json({ error: "Harvest entry not found" });
  }

  try {
    updateHarvestEntry(id, plotId, quantity, ownerId);
    const updatedEntry = getHarvestEntryById(id);

    if (!updatedEntry) {
      return res.status(500).json({ error: "Failed to retrieve updated harvest entry" });
    }

    return res.json(updatedEntry);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update harvest entry" });
  }
});

// Delete a harvest entry
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid entry ID" });
  }

  const existingEntry = getHarvestEntryById(id);

  if (!existingEntry) {
    return res.status(404).json({ error: "Harvest entry not found" });
  }

  try {
    deleteHarvestEntry(id);
    return res.json({ message: "Harvest entry deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete harvest entry" });
  }
});
"}

