{"code":"import { useEffect, useState } from "react";

interface ShortUrl {
  id: string;
  originalUrl: string;
  shortCode: string;
  visitCount: number;
}

export function ShortenerWebClient() {
  const [shortUrls, setShortUrls] = useState<ShortUrl[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newUrl, setNewUrl] = useState("");
  const [refreshKey, setRefreshKey] = useState(0);

  useEffect(() => {
    const fetchShortUrls = async () => {
      try {
        const response = await fetch("/api/shortener-api/short-urls");
        if (!response.ok) {
          throw new Error(`Failed to fetch: ${response.status} ${response.statusText}`);
        }
        const data = await response.json();
        setShortUrls(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchShortUrls();
  }, [refreshKey]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUrl.trim()) return;

    try {
      const response = await fetch("/api/shortener-api/short-urls", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ originalUrl: newUrl }),
      });

      if (!response.ok) {
        throw new Error(`Failed to create: ${response.status} ${response.statusText}`);
      }

      setNewUrl("");
      setRefreshKey(prev => prev + 1); // Trigger re-fetch
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/shortener-api/short-urls/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        throw new Error(`Failed to delete: ${response.status} ${response.statusText}`);
      }

      setRefreshKey(prev => prev + 1); // Trigger re-fetch
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleVisit = async (id: string) => {
    try {
      const response = await fetch(`/api/shortener-api/short-urls/${id}/visit`, {
        method: "PUT",
      });

      if (!response.ok) {
        throw new Error(`Failed to update visit count: ${response.status} ${response.statusText}`);
      }

      setRefreshKey(prev => prev + 1); // Trigger re-fetch
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div
      style={{
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
      }}
    >
      <h1 style={{ textAlign: "center" }}>URL Shortener</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px" }}>
        <input
          type="url"
          value={newUrl}
          onChange={(e) => setNewUrl(e.target.value)}
          placeholder="Enter long URL"
          style={{
            width: "100%",
            padding: "10px",
            borderRadius: "4px",
            border: "1px solid #ccc",
            marginBottom: "10px",
          }}
          required
        />
        <button
          type="submit"
          style={{
            backgroundColor: "#007bff",
            color: "white",
            padding: "10px 20px",
            borderRadius: "4px",
            border: "none",
            cursor: "pointer",
          }}
        >
          Create Short Link
        </button>
      </form>

      {shortUrls.length === 0 ? (
        <p style={{ textAlign: "center", color: "#666" }}>No short URLs created yet.</p>
      ) : (
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "15px",
          }}
        >
          {shortUrls.map((url) => (
            <div
              key={url.id}
              style={{
                border: "1px solid #ddd",
                borderRadius: "8px",
                padding: "15px",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                flexWrap: "wrap",
              }}
            >
              <div style={{ flex: 1, minWidth: "200px", marginRight: "10px" }}>
                <div style={{ fontWeight: "bold" }}>
                  {url.shortCode}
                </div>
                <div style={{ fontSize: "0.9em", color: "#555" }}>
                  {url.originalUrl}
                </div>
                <div style={{ fontSize: "0.9em", color: "#555" }}>
                  Visits: {url.visitCount}
                </div>
              </div>
              <div
                style={{
                  display: "flex",
                  gap: "5px",
                  flexWrap: "wrap",
                }}
              >
                <button
                  onClick={() => handleVisit(url.id)}
                  style={{
                    backgroundColor: "#28a745",
                    color: "white",
                    padding: "5px 10px",
                    borderRadius: "4px",
                    border: "none",
                    cursor: "pointer",
                    fontSize: "0.85em",
                  }}
                >
                  Visit
                </button>
                <button
                  onClick={() => handleDelete(url.id)}
                  style={{
                    backgroundColor: "#dc3545",
                    color: "white",
                    padding: "5px 10px",
                    borderRadius: "4px",
                    border: "none",
                    cursor: "pointer",
                    fontSize: "0.85em",
                  }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockDatabase = {
  getAllTransactions: async () => [
    { id: 1, customerId: 1, amount: 100, description: "Initial credit" },
    { id: 2, customerId: 2, amount: 200, description: "Bonus credit" }
  ],
  getTransactionById: async (id: number) => {
    const transactions = await mockDatabase.getAllTransactions();
    return transactions.find(t => t.id === id) || null;
  },
  createTransaction: async (transaction: any) => {
    const newId = Math.max(0, ...(await mockDatabase.getAllTransactions()).map(t => t.id)) + 1;
    return { id: newId, ...transaction };
  },
  updateTransaction: async (id: number, updates: any) => {
    const transactions = await mockDatabase.getAllTransactions();
    const index = transactions.findIndex(t => t.id === id);
    if (index === -1) return null;
    transactions[index] = { ...transactions[index], ...updates };
    return transactions[index];
  },
  deleteTransaction: async (id: number) => {
    const transactions = await mockDatabase.getAllTransactions();
    const index = transactions.findIndex(t => t.id === id);
    if (index === -1) return false;
    transactions.splice(index, 1);
    return true;
  }
};

// List all transactions
router.get("/", async (req: Request, res: Response) => {
  try {
    const transactions = await mockDatabase.getAllTransactions();
    res.json(transactions);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch transactions" });
  }
});

// Get a specific transaction by ID
router.get("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid transaction ID" });
    }
    const transaction = await mockDatabase.getTransactionById(id);
    if (!transaction) {
      return res.status(404).json({ error: "Transaction not found" });
    }
    res.json(transaction);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch transaction" });
  }
});

// Create a new transaction
router.post("/", async (req: Request, res: Response) => {
  try {
    const { customerId, amount, description } = req.body;
    if (!customerId || !amount || !description) {
      return res.status(400).json({ error: "Missing required fields: customerId, amount, description" });
    }
    const newTransaction = await mockDatabase.createTransaction({
      customerId,
      amount,
      description
    });
    res.status(201).json(newTransaction);
  } catch (error) {
    res.status(500).json({ error: "Failed to create transaction" });
  }
});

// Update an existing transaction
router.put("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid transaction ID" });
    }
    const { customerId, amount, description } = req.body;
    const updatedTransaction = await mockDatabase.updateTransaction(id, { customerId, amount, description });
    if (!updatedTransaction) {
      return res.status(404).json({ error: "Transaction not found" });
    }
    res.json(updatedTransaction);
  } catch (error) {
    res.status(500).json({ error: "Failed to update transaction" });
  }
});

// Delete a transaction
router.delete("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid transaction ID" });
    }
    const deleted = await mockDatabase.deleteTransaction(id);
    if (!deleted) {
      return res.status(404).json({ error: "Transaction not found" });
    }
    res.json({ message: "Transaction deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete transaction" });
  }
});
