{"code":"import { useEffect, useState } from "react";

interface Fee {
  id: string;
  studentId: string;
  amount: number;
  status: "paid" | "pending" | "overdue";
  dueDate: string;
  paymentDate?: string;
}

interface FeeFormData {
  studentId: string;
  amount: string;
  dueDate: string;
}

export function FeesManagement() {
  const [fees, setFees] = useState<Fee[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState<FeeFormData>({
    studentId: "",
    amount: "",
    dueDate: "",
  });
  const [showForm, setShowForm] = useState(false);

  useEffect(() => {
    fetchFees();
  }, []);

  const fetchFees = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/fees");
      if (!response.ok) {
        throw new Error(`Failed to fetch fees: ${response.status}`);
      }
      const data = await response.json();
      setFees(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/fees", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...formData,
          amount: Number(formData.amount),
        }),
      });

      if (!response.ok) {
        throw new Error(`Failed to create fee: ${response.status}`);
      }

      // Reset form and reload data
      setFormData({ studentId: "", amount: "", dueDate: "" });
      setShowForm(false);
      fetchFees();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handlePayment = async (feeId: string) => {
    try {
      const response = await fetch(`/api/fees/${feeId}/pay`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: "paid" }),
      });

      if (!response.ok) {
        throw new Error(`Failed to process payment: ${response.status}`);
      }

      fetchFees();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Transport Fee Management</h1>

      <div style={{ marginBottom: "20px", display: "flex", justifyContent: "center" }}>
        <button
          onClick={() => setShowForm(!showForm)}
          style={{
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            borderRadius: "4px",
            padding: "10px 15px",
            cursor: "pointer",
          }}
        >
          {showForm ? "Cancel" : "Add New Fee"}
        </button>
      </div>

      {showForm && (
        <form
          onSubmit={handleSubmit}
          style={{
            backgroundColor: "#f8f9fa",
            padding: "20px",
            borderRadius: "8px",
            marginBottom: "20px",
            border: "1px solid #dee2e6",
          }}
        >
          <div style={{ marginBottom: "15px" }}>
            <label htmlFor="studentId" style={{ display: "block", marginBottom: "5px" }}>
              Student ID
            </label>
            <input
              type="text"
              id="studentId"
              name="studentId"
              value={formData.studentId}
              onChange={handleInputChange}
              required
              style={{
                width: "100%",
                padding: "8px",
                borderRadius: "4px",
                border: "1px solid #ced4da",
              }}
            />
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label htmlFor="amount" style={{ display: "block", marginBottom: "5px" }}>
              Amount ($)
            </label>
            <input
              type="number"
              id="amount"
              name="amount"
              value={formData.amount}
              onChange={handleInputChange}
              required
              min="0"
              step="0.01"
              style={{
                width: "100%",
                padding: "8px",
                borderRadius: "4px",
                border: "1px solid #ced4da",
              }}
            />
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label htmlFor="dueDate" style={{ display: "block", marginBottom: "5px" }}>
              Due Date
            </label>
            <input
              type="date"
              id="dueDate"
              name="dueDate"
              value={formData.dueDate}
              onChange={handleInputChange}
              required
              style={{
                width: "100%",
                padding: "8px",
                borderRadius: "4px",
                border: "1px solid #ced4da",
              }}
            />
          </div>

          <button
            type="submit"
            style={{
              backgroundColor: "#28a745",
              color: "white",
              border: "none",
              borderRadius: "4px",
              padding: "10px 15px",
              cursor: "pointer",
            }}
          >
            Create Fee
          </button>
        </form>
      )}

      <h2>Fees History</h2>
      {fees.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No fees found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {fees.map((fee) => (
            <div
              key={fee.id}
              style={{
                backgroundColor: "#fff",
                border: "1px solid #dee2e6",
                borderRadius: "8px",
                padding: "15px",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                flexWrap: "wrap",
              }}
            >
              <div style={{ flex: 1, minWidth: "200px" }}>
                <strong>Student ID:</strong> {fee.studentId}<br />
                <strong>Amount:</strong> ${fee.amount.toFixed(2)}<br />
                <strong>Status:</strong> {fee.status}<br />
                <strong>Due Date:</strong> {new Date(fee.dueDate).toLocaleDateString()}<br />
                {fee.paymentDate && (
                  <>
                    <strong>Payment Date:</strong> {new Date(fee.paymentDate).toLocaleDateString()}<br />
                  </>
                )}
              </div>
              <div style={{ marginLeft: "10px" }}>
                {fee.status !== "paid" && (
                  <button
                    onClick={() => handlePayment(fee.id)}
                    style={{
                      backgroundColor: "#ffc107",
                      color: "black",
                      border: "none",
                      borderRadius: "4px",
                      padding: "8px 12px",
                      cursor: "pointer",
                    }}
                  >
                    Mark as Paid
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

