{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  // In a real implementation, we would verify the JWT token here
  // For now, we'll just simulate the verification process
  // This is a placeholder implementation

  // Simulate token verification
  const token = req.headers.authorization?.split(" ")[1];
  if (!token) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // Basic token structure validation
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  try {
    // Decode the payload (base64url)
    const payload = Buffer.from(parts[1], "base64").toString("utf-8");
    const payloadObj = JSON.parse(payload);

    // Verify signature
    const signature = parts[2];
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(`${parts[0]}.${parts[1]}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(signature, "base64url"),
      Buffer.from(expectedSignature, "base64url")
    );

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // If we get here, the token is valid
    // In a real implementation, we would set the user in the request object
    // For example: req.user = payloadObj;

    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}
"}

