{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./trivia.db");

interface Room {
  code: string;
  playerCount: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS rooms (
    code TEXT PRIMARY KEY,
    playerCount INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllRooms(): Room[] {
  const stmt = db.prepare("SELECT * FROM rooms");
  return stmt.all() as unknown as Room[];
}

export function getRoomByCode(code: string): Room | undefined {
  const stmt = db.prepare("SELECT * FROM rooms WHERE code = ?");
  return stmt.get(code) as unknown as Room | undefined;
}

export function insertRoom(code: string, playerCount: number): string {
  const stmt = db.prepare("INSERT INTO rooms (code, playerCount) VALUES (?, ?)");
  stmt.run(code, playerCount);
  return code;
}

export function updateRoomPlayerCount(code: string, playerCount: number): boolean {
  const stmt = db.prepare("UPDATE rooms SET playerCount = ? WHERE code = ?");
  const result = stmt.run(playerCount, code);
  return result.changes > 0;
}

export function deleteRoom(code: string): boolean {
  const stmt = db.prepare("DELETE FROM rooms WHERE code = ?");
  const result = stmt.run(code);
  return result.changes > 0;
}

// Seed the table with sample data if empty
if (getAllRooms().length === 0) {
  insertRoom("ABC123", 2);
  insertRoom("XYZ789", 4);
  insertRoom("DEF456", 1);
  insertRoom("GHI789", 3);
  insertRoom("JKL012", 5);
}
"}

