{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check export requests
  if (req.method !== "POST" || req.path !== "/export") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Basic token structure validation
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  const [header, payload, signature] = parts;

  // Verify signature
  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  const signatureBuffer = Buffer.from(signature, "base64url");
  const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

  try {
    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Invalid token signature" });
    return;
  }

  // Decode payload to check ownership
  try {
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());

    if (!decodedPayload.siteId || !decodedPayload.userId) {
      res.status(401).json({ error: "Invalid token payload" });
      return;
    }

    // In a real implementation, we would check if the user owns the site
    // For now, we'll just simulate the check
    const userOwnsSite = true; // This would be replaced with actual DB lookup

    if (!userOwnsSite) {
      res.status(403).json({ error: "Forbidden: User does not own the site" });
      return;
    }

    next();
  } catch (err) {
    res.status(401).json({ error: "Invalid token payload" });
  }
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface Audition {
  actor_id: number;
  show_id: number;
  signup_timestamp: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS auditions (
    actor_id INTEGER NOT NULL,
    show_id INTEGER NOT NULL,
    signup_timestamp INTEGER NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllAuditions(): Audition[] {
  const stmt = db.prepare(`SELECT * FROM auditions;`);
  return stmt.all() as unknown as Audition[];
}

export function getAuditionById(actorId: number, showId: number): Audition | undefined {
  const stmt = db.prepare(`SELECT * FROM auditions WHERE actor_id = ? AND show_id = ?;`);
  return stmt.get(actorId, showId) as unknown as Audition | undefined;
}

export function insertAudition(actorId: number, showId: number, signupTimestamp: number): number {
  const stmt = db.prepare(`INSERT INTO auditions (actor_id, show_id, signup_timestamp) VALUES (?, ?, ?);`);
  const result = stmt.run(actorId, showId, signupTimestamp);
  return Number(result.lastInsertRowid);
}

export function updateAudition(actorId: number, showId: number, signupTimestamp: number): number {
  const stmt = db.prepare(`UPDATE auditions SET signup_timestamp = ? WHERE actor_id = ? AND show_id = ?;`);
  const result = stmt.run(signupTimestamp, actorId, showId);
  return Number(result.changes);
}

export function deleteAudition(actorId: number, showId: number): number {
  const stmt = db.prepare(`DELETE FROM auditions WHERE actor_id = ? AND show_id = ?;`);
  const result = stmt.run(actorId, showId);
  return Number(result.changes);
}

