{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface Thesis {
  id: number;
  studentName: string;
  title: string;
  supervisorId: number;
  startDate: string;
  expectedCompletion: string;
  status: string;
  notes: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS theses (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    studentName TEXT NOT NULL,
    title TEXT NOT NULL,
    supervisorId INTEGER NOT NULL,
    startDate TEXT NOT NULL,
    expectedCompletion TEXT NOT NULL,
    status TEXT NOT NULL,
    notes TEXT
  )
`;

db.exec(createTableSql);

export function getAllTheses(): Thesis[] {
  const stmt = db.prepare("SELECT * FROM theses");
  return stmt.all() as unknown as Thesis[];
}

export function getThesisById(id: number): Thesis | undefined {
  const stmt = db.prepare("SELECT * FROM theses WHERE id = ?");
  return stmt.get(id) as unknown as Thesis | undefined;
}

export function insertThesis(thesis: Omit<Thesis, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO theses (studentName, title, supervisorId, startDate, expectedCompletion, status, notes) VALUES (?, ?, ?, ?, ?, ?, ?)"
  );
  const result = stmt.run(
    thesis.studentName,
    thesis.title,
    thesis.supervisorId,
    thesis.startDate,
    thesis.expectedCompletion,
    thesis.status,
    thesis.notes
  );
  return Number(result.lastInsertRowid);
}

export function updateThesis(id: number, thesis: Partial<Omit<Thesis, "id">>): boolean {
  const fields = [];
  const values = [];

  if (thesis.studentName !== undefined) {
    fields.push("studentName = ?");
    values.push(thesis.studentName);
  }

  if (thesis.title !== undefined) {
    fields.push("title = ?");
    values.push(thesis.title);
  }

  if (thesis.supervisorId !== undefined) {
    fields.push("supervisorId = ?");
    values.push(thesis.supervisorId);
  }

  if (thesis.startDate !== undefined) {
    fields.push("startDate = ?");
    values.push(thesis.startDate);
  }

  if (thesis.expectedCompletion !== undefined) {
    fields.push("expectedCompletion = ?");
    values.push(thesis.expectedCompletion);
  }

  if (thesis.status !== undefined) {
    fields.push("status = ?");
    values.push(thesis.status);
  }

  if (thesis.notes !== undefined) {
    fields.push("notes = ?");
    values.push(thesis.notes);
  }

  if (fields.length === 0) {
    return false;
  }

  values.push(id);

  const sql = `UPDATE theses SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  const result = stmt.run(...values);

  return result.changes > 0;
}

export function deleteThesis(id: number): boolean {
  const stmt = db.prepare("DELETE FROM theses WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

// Insert sample data if table is empty
if (getAllTheses().length === 0) {
  const sampleTheses = [
    {
      studentName: "Alice Johnson",
      title: "Machine Learning Approaches to Natural Language Processing",
      supervisorId: 1,
      startDate: "2023-01-15",
      expectedCompletion: "2024-06-30",
      status: "In Progress",
      notes: "Regular progress meetings scheduled bi-weekly."
    },
    {
      studentName: "Bob Smith",
      title: "Quantum Computing Algorithms for Optimization Problems",
      supervisorId: 2,
      startDate: "2022-09-01",
      expectedCompletion: "2024-03-15",
      status: "Completed",
      notes: "Dissertation submitted and approved."
    },
    {
      studentName: "Carol Williams",
      title: "Sustainable Energy Solutions in Urban Environments",
      supervisorId: 1,
      startDate: "2023-03-10",
      expectedCompletion: "2024-09-30",
      status: "Proposed",
      notes: "Initial proposal accepted. Research phase begins next month."
    }
  ];

  sampleTheses.forEach(thesis => {
    insertThesis(thesis);
  });
}
"}

