{"code":"import { Router, type Request, type Response } from "express";
import { db, deleteEvent, getAllEvents, getEventById, insertEvent, updateEvent } from "../db/events-table";

export const router = Router();

// GET /events - Get all events
router.get("/events", (req: Request, res: Response) => {
  try {
    const events = getAllEvents();
    res.json(events);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch events" });
  }
});

// GET /events/:id - Get event by ID
router.get("/events/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid event ID" });
    }

    const event = getEventById(id);
    if (!event) {
      return res.status(404).json({ error: "Event not found" });
    }

    res.json(event);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch event" });
  }
});

// POST /events - Create a new event
router.post("/events", (req: Request, res: Response) => {
  try {
    const { eventType, userId, timestamp, properties } = req.body;

    if (!eventType || !userId || !timestamp) {
      return res.status(400).json({ error: "eventType, userId, and timestamp are required" });
    }

    const eventId = insertEvent(eventType, userId, timestamp, properties);
    res.status(201).json({ id: eventId, eventType, userId, timestamp, properties });
  } catch (error) {
    res.status(500).json({ error: "Failed to create event" });
  }
});

// PUT /events/:id - Update an existing event
router.put("/events/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid event ID" });
    }

    const { eventType, userId, timestamp, properties } = req.body;

    const updated = updateEvent(id, eventType, userId, timestamp, properties);
    if (!updated) {
      return res.status(404).json({ error: "Event not found" });
    }

    res.json({ message: "Event updated successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to update event" });
  }
});

// DELETE /events/:id - Delete an event
router.delete("/events/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid event ID" });
    }

    const deleted = deleteEvent(id);
    if (!deleted) {
      return res.status(404).json({ error: "Event not found" });
    }

    res.json({ message: "Event deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete event" });
  }
});
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";
import { router as checkoutsApiRouter } from "../routes/checkouts-api";
import { router as supervisorOnlyDeleteGuardRouter } from "../routes/supervisor-only-delete-guard";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check DELETE requests to the checkouts API
  if (req.method !== "DELETE" || !req.path.startsWith("/api/checkouts")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT_SECRET not set" });
    return;
  }

  // Basic token structure validation
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  const [header, payload, signature] = parts;

  // Verify signature
  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  const signatureBuffer = Buffer.from(signature, "base64url");
  const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

  try {
    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Invalid token signature" });
    return;
  }

  // Decode payload to check role
  try {
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());
    if (decodedPayload.role !== "supervisor") {
      res.status(403).json({ error: "Forbidden: Supervisor role required" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Invalid token payload" });
    return;
  }

  next();
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("parking_garage.db");

interface Reservation {
  id: number;
  driver_id: number;
  time_slot: string;
  status: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS reservations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    driver_id INTEGER NOT NULL,
    time_slot TEXT NOT NULL,
    status TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllReservations(): Reservation[] {
  const stmt = db.prepare("SELECT * FROM reservations");
  return stmt.all() as unknown as Reservation[];
}

export function getReservationById(id: number): Reservation | undefined {
  const stmt = db.prepare("SELECT * FROM reservations WHERE id = ?");
  return stmt.get(id) as unknown as Reservation | undefined;
}

export function insertReservation(
  driverId: number,
  timeSlot: string,
  status: string
): number {
  const stmt = db.prepare(
    "INSERT INTO reservations (driver_id, time_slot, status) VALUES (?, ?, ?)"
  );
  const result = stmt.run(driverId, timeSlot, status);
  return Number(result.lastInsertRowid);
}

export function updateReservation(
  id: number,
  driverId: number,
  timeSlot: string,
  status: string
): void {
  const stmt = db.prepare(
    "UPDATE reservations SET driver_id = ?, time_slot = ?, status = ? WHERE id = ?"
  );
  stmt.run(driverId, timeSlot, status, id);
}

export function deleteReservation(id: number): void {
  const stmt = db.prepare("DELETE FROM reservations WHERE id = ?");
  stmt.run(id);
}

// Sample data insertion
if (getAllReservations().length === 0) {
  insertReservation(101, "2023-06-15T09:00:00", "confirmed");
  insertReservation(102, "2023-06-15T10:30:00", "pending");
  insertReservation(103, "2023-06-15T14:15:00", "confirmed");
  insertReservation(104, "2023-06-15T16:45:00", "cancelled");
  insertReservation(105, "2023-06-15T18:00:00", "confirmed");
}
"}

{"code":"import { useEffect, useState } from "react";

interface ServiceRecord {
  id: string;
  applianceId: string;
  date: string;
  description: string;
  technician: string;
}

interface Appliance {
  id: string;
  name: string;
}

export function ApplianceServiceHistoryView() {
  const [serviceRecords, setServiceRecords] = useState<ServiceRecord[]>([]);
  const [appliances, setAppliances] = useState<Appliance[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newService, setNewService] = useState({
    applianceId: '',
    date: '',
    description: '',
    technician: ''
  });

  useEffect(() => {
    fetchServiceRecords();
    fetchAppliances();
  }, []);

  const fetchServiceRecords = async () => {
    try {
      const response = await fetch('/api/maintenance-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch service records: ${response.status}`);
      }
      const data = await response.json();
      setServiceRecords(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
      setLoading(false);
    }
  };

  const fetchAppliances = async () => {
    try {
      const response = await fetch('/api/maintenance-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch appliances: ${response.status}`);
      }
      const data = await response.json();
      setAppliances(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setNewService(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch('/api/maintenance-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newService)
      });

      if (!response.ok) {
        throw new Error(`Failed to create service record: ${response.status}`);
      }

      // Reset form
      setNewService({
        applianceId: '',
        date: '',
        description: '',
        technician: ''
      });

      // Refresh data
      fetchServiceRecords();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Appliance Service History</h1>

      <h2>Add New Service Record</h2>
      <form onSubmit={handleSubmit} style={{ marginBottom: '30px' }}>
        <div style={{ marginBottom: '10px' }}>
          <label>Appliance:
            <select 
              name="applianceId" 
              value={newService.applianceId}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
              required
            >
              <option value="">Select an appliance</option>
              {appliances.map(appliance => (
                <option key={appliance.id} value={appliance.id}>{appliance.name}</option>
              ))}
            </select>
          </label>
        </div>
        <div style={{ marginBottom: '10px' }}>
          <label>Date:
            <input 
              type="date" 
              name="date" 
              value={newService.date}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
              required
            />
          </label>
        </div>
        <div style={{ marginBottom: '10px' }}>
          <label>Description:
            <textarea 
              name="description" 
              value={newService.description}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
              required
            />
          </label>
        </div>
        <div style={{ marginBottom: '10px' }}>
          <label>Technician:
            <input 
              type="text" 
              name="technician" 
              value={newService.technician}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
              required
            />
          </label>
        </div>
        <button 
          type="submit" 
          style={{ 
            backgroundColor: '#007bff', 
            color: 'white', 
            padding: '10px 20px', 
            border: 'none', 
            borderRadius: '4px', 
            cursor: 'pointer' 
          }}
        >
          Add Service Record
        </button>
      </form>

      <h2>Service Records</h2>
      {serviceRecords.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No service records found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {serviceRecords.map(record => (
            <div 
              key={record.id} 
              style={{ 
                border: '1px solid #ddd', 
                borderRadius: '8px', 
                padding: '15px', 
                backgroundColor: '#f9f9f9' 
              }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <div>
                  <h3 style={{ margin: '0 0 10px 0' }}>
                    {appliances.find(a => a.id === record.applianceId)?.name || 'Unknown Appliance'}
                  </h3>
                  <p><strong>Date:</strong> {record.date}</p>
                  <p><strong>Description:</strong> {record.description}</p>
                  <p><strong>Technician:</strong> {record.technician}</p>
                </div>
                <button 
                  onClick={async () => {
                    try {
                      const response = await fetch(`/api/maintenance-api/${record.id}`, {
                        method: 'DELETE'
                      });
                      if (!response.ok) {
                        throw new Error(`Failed to delete service record: ${response.status}`);
                      }
                      fetchServiceRecords();
                    } catch (err) {
                      setError(err instanceof Error ? err.message : 'An unknown error occurred');
                    }
                  }}
                  style={{ 
                    backgroundColor: '#dc3545', 
                    color: 'white', 
                    border: 'none', 
                    padding: '8px 12px', 
                    borderRadius: '4px', 
                    cursor: 'pointer' 
                  }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import { Expense, getExpensesByAccountId, insertExpense } from "../db/expenses-table";

export const router = Router();

router.post("/add", (req: Request, res: Response): void => {
  const { amount, date, category, accountId } = req.body;
  insertExpense(Number(amount), date, category, Number(accountId));
  res.status(201).send({ message: "Expense added successfully" });
});

router.get("/monthly-total", (req: Request, res: Response): void => {
  const accountId = Number(req.query.accountId);
  const expenses = getExpensesByAccountId(accountId);
  const total = expenses.reduce((sum: number, expense: Expense) => sum + expense.amount, 0);
  res.status(200).json({ total });
});
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only enforce role-based access control on specific routes
  const protectedPaths = [
    "/api/projects",
    "/api/projects/:id",
    "/api/profiles",
    "/api/profiles/:id",
    "/api/contracts",
    "/api/contracts/:id"
  ];

  const isProtectedPath = protectedPaths.some(path => {
    if (path.includes(":")) {
      const pathWithoutParams = path.replace(/:\w+/g, ".*");
      const regex = new RegExp(`^${pathWithoutParams}$`);
      return regex.test(req.path);
    }
    return req.path === path;
  });

  // Skip validation for non-protected paths
  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;
  const userId = req.headers["x-user-id"] as string | undefined;

  if (!userId || !userRole) {
    res.status(401).json({ error: "Unauthorized: Missing user information" });
    return;
  }

  // Validate role
  if (userRole !== "client" && userRole !== "freelancer") {
    res.status(403).json({ error: "Forbidden: Invalid user role" });
    return;
  }

  // Allow access for all valid users on these endpoints
  next();
}
"}

