{"code":"import { useEffect, useState } from "react";

interface Expense {
  id: number;
  description: string;
  amount: number;
  status: "pending" | "approved" | "rejected";
}

export function ExpenseForm() {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [description, setDescription] = useState("");
  const [amount, setAmount] = useState("");

  useEffect(() => {
    fetchExpenses();
  }, []);

  const fetchExpenses = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/expenses-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch expenses: ${response.status}`);
      }
      const data = await response.json();
      setExpenses(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!description.trim() || !amount) return;

    try {
      const response = await fetch("/api/expenses-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          description,
          amount: Number(amount),
          status: "pending" as const,
        }),
      });

      if (!response.ok) {
        throw new Error(`Failed to submit expense: ${response.status}`);
      }

      // Reset form
      setDescription("");
      setAmount("");

      // Refresh the list
      await fetchExpenses();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center" }}>{error}</div>;

  return (
    <div style={{ maxWidth: 600, margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Expense Request Form</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="description" style={{ display: "block", marginBottom: "5px" }}>
            Description:
          </label>
          <input
            id="description"
            type="text"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="amount" style={{ display: "block", marginBottom: "5px" }}>
            Amount ($):
          </label>
          <input
            id="amount"
            type="number"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
            min="0"
            step="0.01"
          />
        </div>

        <button
          type="submit"
          style={{
            backgroundColor: "#007bff",
            color: "white",
            padding: "10px 20px",
            border: "none",
            borderRadius: "4px",
            cursor: "pointer",
            fontSize: "16px",
          }}
        >
          Submit Expense
        </button>
      </form>

      <h2 style={{ textAlign: "center" }}>Recent Expenses</h2>
      {expenses.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>No expenses submitted yet.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {expenses.map((expense) => (
            <div
              key={expense.id}
              style={{
                padding: "15px",
                border: "1px solid #ddd",
                borderRadius: "8px",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
              }}
            >
              <div>
                <strong>{expense.description}</strong>
                <br />
                <span>${expense.amount.toFixed(2)}</span>
                <br />
                <span style={{ fontSize: "0.9em", color: "#666" }}>
                  Status: {expense.status}
                </span>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

