  getWorkOrders: () => Promise.resolve([{ id: 1, orderId: "ORD-001", status: "pending" }]),
  getWorkOrderById: (id: number) => Promise.resolve({ id: 1, orderId: "ORD-001", status: "pending" }),
  updateWorkOrder: (id: number, workOrder: any) => Promise.resolve({ id, ...workOrder }),
  deleteWorkOrder: (id: number) => Promise.resolve(true)
};

// GET /api/work-orders - List all work orders
router.get("/", async (req: Request, res: Response) => {
  try {
    const workOrders = await mockDatabase.getWorkOrders();
    res.json(workOrders);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch work orders" });
  }
});

// GET /api/work-orders/:id - Get a specific work order by ID
router.get("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid work order ID" });
    }

    const workOrder = await mockDatabase.getWorkOrderById(id);
    if (!workOrder) {
      return res.status(404).json({ error: "Work order not found" });
    }

    res.json(workOrder);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch work order" });
  }
});

// POST /api/work-orders - Create a new work order
router.post("/", async (req: Request, res: Response) => {
  try {
    const { orderId, status } = req.body;

    if (!orderId || !status) {
      return res.status(400).json({ error: "orderId and status are required" });
    }

    const newWorkOrder = await mockDatabase.createWorkOrder({ orderId, status });
    res.status(201).json(newWorkOrder);
  } catch (error) {
    res.status(500).json({ error: "Failed to create work order" });
  }
});

// PUT /api/work-orders/:id - Update an existing work order
router.put("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid work order ID" });
    }

    const { orderId, status } = req.body;
    if (!orderId || !status) {
      return res.status(400).json({ error: "orderId and status are required" });
    }

    const updatedWorkOrder = await mockDatabase.updateWorkOrder(id, { orderId, status });
    res.json(updatedWorkOrder);
  } catch (error) {
    res.status(500).json({ error: "Failed to update work order" });
  }
});

// DELETE /api/work-orders/:id - Delete a work order
router.delete("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid work order ID" });
    }

    const deleted = await mockDatabase.deleteWorkOrder(id);
    if (!deleted) {
      return res.status(404).json({ error: "Work order not found" });
    }

    res.json({ message: "Work order deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete work order" });
  }
});
"}

