{"code":"import { useEffect, useState } from "react";

interface User {
  id: string;
  name: string;
  email: string;
  bio: string;
  joinDate: string;
}

interface Story {
  id: string;
  title: string;
  wordCount: number;
  createdAt: string;
}

export function UserProfile() {
  const [user, setUser] = useState<User | null>(null);
  const [stories, setStories] = useState<Story[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [editing, setEditing] = useState(false);
  const [editForm, setEditForm] = useState({
    name: "",
    email: "",
    bio: ""
  });

  useEffect(() => {
    const fetchUserData = async () => {
      try {
        const response = await fetch(`/api/user-management-service/users/me`, {
          method: "GET",
          headers: {
            "Content-Type": "application/json"
          }
        });

        if (!response.ok) {
          throw new Error(`Failed to fetch user data: ${response.status}`);
        }

        const userData = await response.json();
        setUser(userData);

        // Fetch stories
        const storiesResponse = await fetch(`/api/user-management-service/users/${userData.id}/stories`, {
          method: "GET",
          headers: {
            "Content-Type": "application/json"
          }
        });

        if (!storiesResponse.ok) {
          throw new Error(`Failed to fetch stories: ${storiesResponse.status}`);
        }

        const storiesData = await storiesResponse.json();
        setStories(storiesData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchUserData();
  }, []);

  const handleEdit = () => {
    if (user) {
      setEditForm({
        name: user.name,
        email: user.email,
        bio: user.bio
      });
      setEditing(true);
    }
  };

  const handleSave = async () => {
    if (!user) return;

    try {
      const response = await fetch(`/api/user-management-service/users/${user.id}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify(editForm)
      });

      if (!response.ok) {
        throw new Error(`Failed to update user: ${response.status}`);
      }

      const updatedUser = await response.json();
      setUser(updatedUser);
      setEditing(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleCancel = () => {
    setEditing(false);
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (!user) {
    return <div style={{ textAlign: "center", padding: "20px" }}>No user data found.</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>User Profile</h1>

      <div style={{ backgroundColor: "#f9f9f9", borderRadius: "8px", padding: "20px", marginBottom: "20px" }}>
        <h2>Personal Information</h2>
        {editing ? (
          <div>
            <div style={{ marginBottom: "10px" }}>
              <label>Name:</label><br />
              <input
                type="text"
                value={editForm.name}
                onChange={(e) => setEditForm({...editForm, name: e.target.value})}
                style={{ width: "100%", padding: "8px", marginTop: "5px" }}
              />
            </div>
            <div style={{ marginBottom: "10px" }}>
              <label>Email:</label><br />
              <input
                type="email"
                value={editForm.email}
                onChange={(e) => setEditForm({...editForm, email: e.target.value})}
                style={{ width: "100%", padding: "8px", marginTop: "5px" }}
              />
            </div>
            <div style={{ marginBottom: "10px" }}>
              <label>Bio:</label><br />
              <textarea
                value={editForm.bio}
                onChange={(e) => setEditForm({...editForm, bio: e.target.value})}
                style={{ width: "100%", padding: "8px", marginTop: "5px", height: "100px" }}
              />
            </div>
            <button onClick={handleSave} style={{ backgroundColor: "#007bff", color: "white", border: "none", padding: "10px 15px", borderRadius: "4px", marginRight: "10px" }}>
              Save
            </button>
            <button onClick={handleCancel} style={{ backgroundColor: "#6c757d", color: "white", border: "none", padding: "10px 15px", borderRadius: "4px" }}>
              Cancel
            </button>
          </div>
        ) : (
          <div>
            <p><strong>Name:</strong> {user.name}</p>
            <p><strong>Email:</strong> {user.email}</p>
            <p><strong>Bio:</strong> {user.bio}</p>
            <p><strong>Member since:</strong> {new Date(user.joinDate).toLocaleDateString()}</p>
            <button onClick={handleEdit} style={{ backgroundColor: "#28a745", color: "white", border: "none", padding: "10px 15px", borderRadius: "4px", marginTop: "10px" }}>
              Edit Profile
            </button>
          </div>
        )}
      </div>

      <div style={{ backgroundColor: "#f9f9f9", borderRadius: "8px", padding: "20px" }}>
        <h2>Writing Statistics</h2>
        <p><strong>Total Stories:</strong> {stories.length}</p>
        <p><strong>Total Words:</strong> {stories.reduce((sum, story) => sum + story.wordCount, 0)}</p>

        <h3 style={{ marginTop: "20px" }}>Your Stories</h3>
        {stories.length === 0 ? (
          <p>No stories yet. Start writing!</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {stories.map((story) => (
              <div key={story.id} style={{ border: "1px solid #ddd", borderRadius: "4px", padding: "10px" }}>
                <h4>{story.title}</h4>
                <p>Words: {story.wordCount}</p>
                <p>Created: {new Date(story.createdAt).toLocaleDateString()}</p>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

interface Recipe {
