  name: string;
  description: string;
  prepTime: number;
  cookTime: number;
  tags: string[];
}

interface Tag {
  id: number;
  name: string;
}

export function RecipeListView() {
  const [recipes, setRecipes] = useState<Recipe[]>([]);
  const [tags, setTags] = useState<Tag[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newRecipe, setNewRecipe] = useState({
    name: "",
    description: "",
    prepTime: "",
    cookTime: "",
    tags: [] as string[],
  });

  useEffect(() => {
    fetchRecipes();
    fetchTags();
  }, []);

  const fetchRecipes = async () => {
    try {
      const response = await fetch("/api/recipes-api/");
      if (!response.ok) throw new Error("Failed to fetch recipes");
      const data = await response.json();
      setRecipes(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const fetchTags = async () => {
    try {
      const response = await fetch("/api/recipes-api/tags");
      if (!response.ok) throw new Error("Failed to fetch tags");
      const data = await response.json();
      setTags(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/recipes-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: newRecipe.name,
          description: newRecipe.description,
          prepTime: parseInt(newRecipe.prepTime),
          cookTime: parseInt(newRecipe.cookTime),
          tags: newRecipe.tags,
        }),
      });

      if (!response.ok) throw new Error("Failed to add recipe");

      // Reset form
      setNewRecipe({
        name: "",
        description: "",
        prepTime: "",
        cookTime: "",
        tags: [],
      });

      // Refresh data
      fetchRecipes();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setNewRecipe({
      ...newRecipe,
      [name]: value,
    });
  };

  const handleTagChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const selectedOptions = Array.from(e.target.selectedOptions, option => option.value);
    setNewRecipe({
      ...newRecipe,
      tags: selectedOptions,
    });
  };

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;

  const styles = {
    container: {
      maxWidth: "800px",
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
    },
    header: {
      textAlign: "center" as const,
      marginBottom: "20px",
    },
    form: {
      display: "flex" as const,
      flexDirection: "column" as const,
      gap: "10px",
    },
    input: {
      width: "100%",
      padding: "8px",
      borderRadius: "4px",
      border: "1px solid #ccc",
      boxSizing: "border-box" as const,
    },
    timeInput: {
      flex: 1,
      padding: "8px",
      borderRadius: "4px",
      border: "1px solid #ccc",
      boxSizing: "border-box" as const,
    },
    button: {
      padding: "10px 16px",
      backgroundColor: "#007bff",
      color: "white",
      border: "none",
      borderRadius: "4px",
      cursor: "pointer",
    },
    recipeList: {
      marginTop: "20px",
    },
    recipeCard: {
      border: "1px solid #ddd",
      borderRadius: "8px",
      padding: "16px",
      marginBottom: "10px",
    },
    noRecipes: {
      textAlign: "center" as const,
      fontStyle: "italic" as const,
      color: "#666",
    },
  };

  return (
    <div style={styles.container}>
      <h1 style={styles.header}>Recipe Box</h1>

      <form onSubmit={handleSubmit} style={styles.form}>
        <input
          type="text"
          name="name"
          placeholder="Recipe Name"
          value={newRecipe.name}
          onChange={handleInputChange}
          style={styles.input}
        />
        <textarea
          name="description"
          placeholder="Description"
          value={newRecipe.description}
          onChange={handleInputChange}
          style={styles.input}
        />
        <div style={{ display: "flex", gap: "10px" }}>
          <input
            type="number"
            name="prepTime"
            placeholder="Prep Time (min)"
            value={newRecipe.prepTime}
            onChange={handleInputChange}
            style={styles.timeInput}
          />
          <input
            type="number"
            name="cookTime"
            placeholder="Cook Time (min)"
            value={newRecipe.cookTime}
            onChange={handleInputChange}
            style={styles.timeInput}
          />
        </div>
        <select
          multiple
          name="tags"
          onChange={handleTagChange}
          style={styles.input}
        >
          {tags.map(tag => (
            <option key={tag.id} value={tag.name}>
              {tag.name}
            </option>
          ))}
        </select>
        <button type="submit" style={styles.button}>Add Recipe</button>
      </form>

      <div style={styles.recipeList}>
        {recipes.length === 0 ? (
          <p style={styles.noRecipes}>No recipes found. Add your first recipe above!</p>
        ) : (
          recipes.map(recipe => (
            <div key={recipe.id} style={styles.recipeCard}>
              <h3>{recipe.name}</h3>
              <p>{recipe.description}</p>
              <p>Prep Time: {recipe.prepTime} min</p>
              <p>Cook Time: {recipe.cookTime} min</p>
              <p>Tags: {recipe.tags.join(", ")}</p>
            </div>
          ))
        )}
      </div>
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user data - in a real app this would come from a database
const mockUsers = [
  { id: "1", username: "admin", password: "admin123", role: "admin" },
  { id: "2", username: "staff", password: "staff123", role: "staff" }
];

// Middleware to check if user is authenticated
const authenticate = (req: Request, res: Response, next: Function) => {
  // In a real app, this would verify JWT or session token
  // For now, we'll simulate authentication with a header
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  // Mock token validation - in reality this would decode and validate a JWT
  const user = mockUsers.find(u => u.id === token);

  if (!user) {
    return res.status(401).json({ error: "Invalid token" });
  }

  // Attach user to request object
  (req as any).user = user;
  next();
};

// Role-based authorization middleware
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: Function) => {
    // Check if user is authenticated
    if (!(req as any).user) {
      return res.status(401).json({ error: "Unauthorized" });
    }

    const userRole = (req as any).user.role;

    if (!roles.includes(userRole)) {
      return res.status(403).json({ error: "Forbidden" });
    }

    next();
  };
};

// POST /login - Authenticate user and return token
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password required" });
  }

  const user = mockUsers.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // In a real app, generate a JWT token here
  // For demo purposes, we'll just return the user ID as a token
  res.json({ token: user.id });
});

// GET /profile - Get authenticated user profile
router.get("/profile", authenticate, (req: Request, res: Response) => {
  if (!(req as any).user) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const user = (req as any).user;

  res.json({
    id: user.id,
    username: user.username,
    role: user.role
  });
});

// GET /admin-only - Admin-only endpoint
router.get("/admin-only", authenticate, authorize(["admin"]), (req: Request, res: Response) => {
  if (!(req as any).user) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const user = (req as any).user;

  res.json({
    message: "Admin access granted",
    user: {
      id: user.id,
      username: user.username,
      role: user.role
    }
  });
});
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  const protectedPaths = ["/bookings", "/patients"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  // Skip validation for non-protected routes
  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  // If no role header, deny access
  if (!userRole) {
    res.status(403).json({ error: "Access denied: role not provided" });
    return;
  }

  // Define role requirements for different paths
  const roleRequirements: Record<string, string[]> = {
    "/bookings": ["admin", "booking-manager"],
    "/patients": ["admin", "doctor", "nurse"]
  };

  // Determine required roles based on path
  let requiredRoles: string[] = [];
  for (const [path, roles] of Object.entries(roleRequirements)) {
    if (req.path.startsWith(path)) {
      requiredRoles = roles;
      break;
    }
  }

  // If no specific requirements found, allow admin access
  if (requiredRoles.length === 0) {
    if (userRole !== "admin") {
      res.status(403).json({ error: "Access denied: insufficient permissions" });
      return;
    }
  } else {
    // Check if user has one of the required roles
    if (!requiredRoles.includes(userRole)) {
      res.status(403).json({ error: "Access denied: insufficient permissions" });
      return;
    }
  }

  // If we reach here, user has proper role
  next();
}
