{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST, PUT, DELETE requests to /problems
  if (!(req.method === "POST" || req.method === "PUT" || req.method === "DELETE") || !req.path.startsWith("/problems")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify the JWT signature
  // For this exercise, we'll just check if it matches a known pattern
  const expectedSignature = createHmac("sha256", secret)
    .update(token.split(".")[0] || "")
    .digest("hex");

  const tokenSignature = token.split(".")[1] || "";

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "hex");
    const actualBuffer = Buffer.from(tokenSignature, "hex");

    if (expectedBuffer.length !== actualBuffer.length || !timingSafeEqual(expectedBuffer, actualBuffer)) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  next();
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to payroll-related routes
  if (!req.path.startsWith("/payroll")) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  // Define role requirements for different payroll endpoints
  const roleRequirements: Record<string, string[]> = {
    "/payroll/salary": ["HR_MANAGER", "PAYROLL_ADMIN"],
    "/payroll/processing": ["PAYROLL_ADMIN"],
    "/payroll/reports": ["HR_MANAGER", "PAYROLL_ADMIN", "FINANCE_MANAGER"],
    "/payroll/employees": ["HR_MANAGER", "PAYROLL_ADMIN"],
  };

  // Get required roles based on endpoint
  let requiredRoles: string[] = [];

  // Check for specific endpoint matches
  for (const [endpoint, roles] of Object.entries(roleRequirements)) {
    if (req.path === endpoint || req.path.startsWith(endpoint + "/")) {
      requiredRoles = roles;
      break;
    }
  }

  // If no specific role requirements defined, allow access
  if (requiredRoles.length === 0) {
    next();
    return;
  }

  // If no role header present, deny access
  if (!userRole) {
    res.status(403).json({ error: "Access denied: Missing role information" });
    return;
  }

  // Check if user has required role
  if (!requiredRoles.includes(userRole)) {
    res.status(403).json({ error: "Access denied: Insufficient permissions" });
    return;
  }

  // User has proper role, proceed
  next();
}
"}

