  timestamp: string;
}

export function CheckInWidget() {
  const [scannedId, setScannedId] = useState<string>("");
  const [checkIns, setCheckIns] = useState<CheckInRecord[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchCheckIns();
  }, []);

  const fetchCheckIns = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/check-in-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setCheckIns(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleScan = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!scannedId.trim()) return;

    try {
      const response = await fetch(`/api/check-in-api/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ memberId: scannedId }),
      });

      if (!response.ok) {
        throw new Error(`Failed to check in: ${response.status} ${response.statusText}`);
      }

      setScannedId("");
      fetchCheckIns();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Dog Park Membership Check-In</h1>

      <form onSubmit={handleScan} style={{ marginBottom: "30px", display: "flex", gap: "10px" }}>
        <input
          type="text"
          value={scannedId}
          onChange={(e) => setScannedId(e.target.value)}
          placeholder="Enter Member ID"
          style={{ flex: 1, padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        />
        <button type="submit" style={{ padding: "10px 20px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}>
          Check In
        </button>
      </form>

      <h2>Recent Check-ins</h2>
      {checkIns.length === 0 ? (
        <p style={{ textAlign: "center", color: "#666" }}>No check-ins yet.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {checkIns.map((record) => (
            <div key={record.id} style={{ padding: "15px", border: "1px solid #ddd", borderRadius: "4px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <strong>Member ID:</strong> {record.memberId}<br />
                <small>{new Date(record.timestamp).toLocaleString()}</small>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

interface User {
  id: string;
  username: string;
  email: string;
  role: string;
}

interface VaultItem {
  id: string;
  title: string;
  username: string;
  password: string;
  url: string;
  notes: string;
}

export function AdminDashboard() {
  const [users, setUsers] = useState<User[]>([]);
  const [vaultItems, setVaultItems] = useState<VaultItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Form states
  const [newUser, setNewUser] = useState({
    username: '',
    email: '',
    role: 'user'
  });

  const [newVaultItem, setNewVaultItem] = useState({
    title: '',
    username: '',
    password: '',
    url: '',
    notes: ''
  });

  useEffect(() => {
    fetchAllData();
  }, []);

  const fetchAllData = async () => {
    try {
      setLoading(true);
      const [usersRes, vaultRes] = await Promise.all([
        fetch('/api/vault-api/'),
        fetch('/api/vault-api/')
      ]);

      if (!usersRes.ok || !vaultRes.ok) {
        throw new Error('Failed to fetch data');
      }

      const usersData = await usersRes.json();
      const vaultData = await vaultRes.json();

      setUsers(usersData);
      setVaultItems(vaultData);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleAddUser = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const res = await fetch('/api/vault-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newUser)
      });

      if (res.ok) {
        setNewUser({ username: '', email: '', role: 'user' });
        fetchAllData();
      } else {
        setError('Failed to add user');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleAddVaultItem = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const res = await fetch('/api/vault-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newVaultItem)
      });

      if (res.ok) {
        setNewVaultItem({ title: '', username: '', password: '', url: '', notes: '' });
        fetchAllData();
      } else {
        setError('Failed to add vault item');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDeleteUser = async (id: string) => {
    try {
      const res = await fetch(`/api/vault-api/${id}`, {
        method: 'DELETE'
      });

      if (res.ok) {
        fetchAllData();
      } else {
        setError('Failed to delete user');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDeleteVaultItem = async (id: string) => {
    try {
      const res = await fetch(`/api/vault-api/${id}`, {
        method: 'DELETE'
      });

      if (res.ok) {
        fetchAllData();
      } else {
        setError('Failed to delete vault item');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;
  }

  return (
    <div style={{
      fontFamily: 'system-ui, sans-serif',
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px'
    }}>
      <h1 style={{ textAlign: 'center' }}>Admin Dashboard</h1>

      <div style={{ marginBottom: '30px' }}>
        <h2>Manage Users</h2>
        <form onSubmit={handleAddUser} style={{ marginBottom: '20px', display: 'flex', flexDirection: 'column', gap: '10px' }}>
          <input
            type="text"
            placeholder="Username"
            value={newUser.username}
            onChange={(e) => setNewUser({...newUser, username: e.target.value})}
            style={{ width: '100%', padding: '8px' }}
          />
          <input
            type="email"
            placeholder="Email"
            value={newUser.email}
            onChange={(e) => setNewUser({...newUser, email: e.target.value})}
            style={{ width: '100%', padding: '8px' }}
          />
          <select
            value={newUser.role}
            onChange={(e) => setNewUser({...newUser, role: e.target.value})}
            style={{ width: '100%', padding: '8px' }}
          >
            <option value="user">User</option>
            <option value="admin">Admin</option>
          </select>
          <button type="submit" style={{ padding: '8px', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px' }}>
            Add User
          </button>
        </form>

        {users.length === 0 ? (
          <p>No users found.</p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
            {users.map(user => (
              <div key={user.id} style={{
                border: '1px solid #ccc',
                borderRadius: '4px',
                padding: '10px',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center'
              }}>
                <div>
                  <strong>{user.username}</strong> ({user.email}) - {user.role}
                </div>
                <button 
                  onClick={() => handleDeleteUser(user.id)}
                  style={{
                    padding: '4px 8px',
                    backgroundColor: '#dc3545',
                    color: 'white',
                    border: 'none',
                    borderRadius: '4px'
                  }}
                >
                  Delete
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      <div style={{ marginBottom: '30px' }}>
        <h2>Manage Vault Items</h2>
        <form onSubmit={handleAddVaultItem} style={{ marginBottom: '20px', display: 'flex', flexDirection: 'column', gap: '10px' }}>
          <input
            type="text"
            placeholder="Title"
            value={newVaultItem.title}
            onChange={(e) => setNewVaultItem({...newVaultItem, title: e.target.value})}
            style={{ width: '100%', padding: '8px' }}
          />
          <input
            type="text"
            placeholder="Username"
            value={newVaultItem.username}
            onChange={(e) => setNewVaultItem({...newVaultItem, username: e.target.value})}
            style={{ width: '100%', padding: '8px' }}
          />
          <input
            type="password"
            placeholder="Password"
            value={newVaultItem.password}
            onChange={(e) => setNewVaultItem({...newVaultItem, password: e.target.value})}
            style={{ width: '100%', padding: '8px' }}
          />
          <input
            type="url"
            placeholder="URL"
            value={newVaultItem.url}
            onChange={(e) => setNewVaultItem({...newVaultItem, url: e.target.value})}
            style={{ width: '100%', padding: '8px' }}
          />
          <textarea
            placeholder="Notes"
            value={newVaultItem.notes}
            onChange={(e) => setNewVaultItem({...newVaultItem, notes: e.target.value})}
            style={{ width: '100%', padding: '8px', height: '60px' }}
          />
          <button type="submit" style={{ padding: '8px', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px' }}>
            Add Vault Item
          </button>
        </form>

        {vaultItems.length === 0 ? (
          <p>No vault items found.</p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
            {vaultItems.map(item => (
              <div key={item.id} style={{
                border: '1px solid #ccc',
                borderRadius: '4px',
                padding: '10px',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center'
              }}>
                <div>
                  <strong>{item.title}</strong><br />
                  <small>{item.username} - {item.url}</small>
                </div>
                <button 
                  onClick={() => handleDeleteVaultItem(item.id)}
                  style={{
                    padding: '4px 8px',
                    backgroundColor: '#dc3545',
                    color: 'white',
                    border: 'none',
                    borderRadius: '4px'
                  }}
                >
                  Delete
                </button>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface DesignFile {
  id: number;
  name: string;
  content: string;
  created_at: string;
  updated_at: string;
}

interface Component {
  id: number;
  design_file_id: number;
  name: string;
  properties: string;
  created_at: string;
  updated_at: string;
}

interface VersionHistory {
  id: number;
  design_file_id: number;
  version_number: number;
  changes: string;
  created_at: string;
}

const createTables = `
  CREATE TABLE IF NOT EXISTS design_files (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    content TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS components (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    design_file_id INTEGER NOT NULL,
    name TEXT NOT NULL,
    properties TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY (design_file_id) REFERENCES design_files (id)
  );

  CREATE TABLE IF NOT EXISTS version_history (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    design_file_id INTEGER NOT NULL,
    version_number INTEGER NOT NULL,
    changes TEXT NOT NULL,
    created_at TEXT NOT NULL,
    FOREIGN KEY (design_file_id) REFERENCES design_files (id)
  );
`;

db.exec(createTables);

export function getAllDesignFiles(): DesignFile[] {
  const stmt = db.prepare(`SELECT * FROM design_files`);
  return stmt.all() as unknown as DesignFile[];
}

export function getDesignFileById(id: number): DesignFile | undefined {
  const stmt = db.prepare(`SELECT * FROM design_files WHERE id = ?`);
  return stmt.get(id) as unknown as DesignFile | undefined;
}

export function insertDesignFile(
  name: string,
  content: string
): number {
  const stmt = db.prepare(
    `INSERT INTO design_files (name, content, created_at, updated_at) VALUES (?, ?, datetime('now'), datetime('now'))`
  );
  const result = stmt.run(name, content);
  return Number(result.lastInsertRowid);
}

export function updateDesignFile(
  id: number,
  name: string,
  content: string
): void {
  const stmt = db.prepare(
    `UPDATE design_files SET name = ?, content = ?, updated_at = datetime('now') WHERE id = ?`
  );
  stmt.run(name, content, id);
}

export function deleteDesignFile(id: number): void {
  const stmt = db.prepare(`DELETE FROM design_files WHERE id = ?`);
  stmt.run(id);
}

// Sample data initialization
if (getAllDesignFiles().length === 0) {
  const fileId1 = insertDesignFile(
    "Homepage Layout",
    "{\"elements\":[{\"type\":\"button\",\"text\":\"Click Me\"}]}",
  );
  const fileId2 = insertDesignFile(
    "Dashboard UI",
    "{\"elements\":[{\"type\":\"card\",\"title\":\"Stats\"}]}",
  );
  const fileId3 = insertDesignFile(
    "Mobile App",
    "{\"elements\":[{\"type\":\"input\",\"placeholder\":\"Enter text\"}]}",
  );

  // Insert some sample components
  const componentStmt = db.prepare(
    `INSERT INTO components (design_file_id, name, properties, created_at, updated_at) VALUES (?, ?, ?, datetime('now'), datetime('now'))`
  );
  componentStmt.run(fileId1, "Header", "{\"color\":\"#333\"}");
  componentStmt.run(fileId1, "Footer", "{\"background\":\"#f0f0f0\"}");
  componentStmt.run(fileId2, "Chart", "{\"type\":\"bar\"}");
  componentStmt.run(fileId3, "Button", "{\"size\":\"large\"}");

  // Insert version history
  const versionStmt = db.prepare(
    `INSERT INTO version_history (design_file_id, version_number, changes, created_at) VALUES (?, ?, ?, datetime('now'))`
  );
  versionStmt.run(fileId1, 1, "Initial layout");
  versionStmt.run(fileId1, 2, "Added footer");
  versionStmt.run(fileId2, 1, "Dashboard structure");
  versionStmt.run(fileId3, 1, "Mobile layout");
}
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data structures to simulate database operations
const interviews = new Map<string, any>();
let nextId = 1;

// Helper function to validate interview data
const validateInterviewData = (data: any): string | null => {
  if (!data.title || typeof data.title !== 'string') {
    return 'Title is required and must be a string';
  }

  if (!data.date || typeof data.date !== 'string') {
    return 'Date is required and must be a string';
  }

  if (!data.startTime || typeof data.startTime !== 'string') {
    return 'Start time is required and must be a string';
  }

  if (!data.endTime || typeof data.endTime !== 'string') {
    return 'End time is required and must be a string';
  }

  // Basic time format validation (HH:MM)
  const timeRegex = /^([0-1]?[0-9]|2[0-3]):[0-5][0-9]$/;
  if (!timeRegex.test(data.startTime)) {
    return 'Start time must be in HH:MM format';
  }

  if (!timeRegex.test(data.endTime)) {
    return 'End time must be in HH:MM format';
  }

  // Ensure end time is after start time
  const [startHours, startMinutes] = data.startTime.split(':').map(Number);
  const [endHours, endMinutes] = data.endTime.split(':').map(Number);

  if (endHours < startHours || (endHours === startHours && endMinutes <= startMinutes)) {
    return 'End time must be after start time';
  }

  return null;
};

// Helper function to check for time conflicts
const hasTimeConflict = (newInterview: any): boolean => {
  const newDate = new Date(newInterview.date);

  for (const [id, existingInterview] of interviews.entries()) {
    if (existingInterview.date === newInterview.date) {
      const existingStart = existingInterview.startTime.split(':').map(Number);
      const existingEnd = existingInterview.endTime.split(':').map(Number);
      const newStart = newInterview.startTime.split(':').map(Number);
      const newEnd = newInterview.endTime.split(':').map(Number);

      // Check if times overlap
      if ((newStart[0] < existingEnd[0] || (newStart[0] === existingEnd[0] && newStart[1] < existingEnd[1])) &&
          (newEnd[0] > existingStart[0] || (newEnd[0] === existingStart[0] && newEnd[1] > existingStart[1]))) {
        return true;
      }
    }
  }

  return false;
};

// GET /interviews - List all interviews
router.get('/', (req: Request, res: Response) => {
  const interviewList = Array.from(interviews.values());
  return res.json(interviewList);
});

// GET /interviews/:id - Get a specific interview by ID
router.get('/:id', (req: Request, res: Response) => {
  const id = req.params.id;
  const interview = interviews.get(id);

  if (!interview) {
    return res.status(404).json({ error: 'Interview not found' });
  }

  return res.json(interview);
});

// POST /interviews - Create a new interview
router.post('/', (req: Request, res: Response) => {
  const { title, date, startTime, endTime } = req.body;

  const validationError = validateInterviewData({ title, date, startTime, endTime });
  if (validationError) {
    return res.status(400).json({ error: validationError });
  }

  // Check for time conflicts
  const newInterview = { id: nextId.toString(), title, date, startTime, endTime };
  if (hasTimeConflict(newInterview)) {
    return res.status(400).json({ error: 'Time conflict detected with existing interview' });
  }

  interviews.set(nextId.toString(), newInterview);
  nextId++;

  return res.status(201).json(newInterview);
});

// PUT /interviews/:id - Update an existing interview
router.put('/:id', (req: Request, res: Response) => {
  const id = req.params.id;
  const { title, date, startTime, endTime } = req.body;

  const existingInterview = interviews.get(id);

  if (!existingInterview) {
    return res.status(404).json({ error: 'Interview not found' });
  }

  const validationError = validateInterviewData({ title, date, startTime, endTime });
  if (validationError) {
    return res.status(400).json({ error: validationError });
  }

  // Check for time conflicts
  const updatedInterview = { ...existingInterview, title, date, startTime, endTime };
  if (hasTimeConflict(updatedInterview)) {
    return res.status(400).json({ error: 'Time conflict detected with existing interview' });
  }

  interviews.set(id, updatedInterview);

  return res.json(updatedInterview);
});

// DELETE /interviews/:id - Delete an interview
router.delete('/:id', (req: Request, res: Response) => {
  const id = req.params.id;

  const interview = interviews.get(id);

  if (!interview) {
    return res.status(404).json({ error: 'Interview not found' });
  }

  interviews.delete(id);

  return res.json({ message: 'Interview deleted successfully' });
});
"}

{"code":"import { useState, useEffect } from "react";

export function TripEntryForm() {
  const [startLocation, setStartLocation] = useState("");
  const [endLocation, setEndLocation] = useState("");
  const [milesDriven, setMilesDriven] = useState("");
  const [purpose, setPurpose] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError("");

    try {
      const response = await fetch("/api/mileage-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          startLocation,
          endLocation,
          milesDriven: Number(milesDriven),
          purpose
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to save trip: ${response.status}`);
      }

      // Reset form after successful submission
      setStartLocation("");
      setEndLocation("");
      setMilesDriven("");
      setPurpose("");
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{
      maxWidth: "600px",
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
    }}>
      <h1 style={{ textAlign: "center" }}>Trip Entry Form</h1>

      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        <div>
          <label htmlFor="startLocation" style={{ display: "block", marginBottom: "5px" }}>
            Start Location
          </label>
          <input
            id="startLocation"
            type="text"
            value={startLocation}
            onChange={(e) => setStartLocation(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <div>
          <label htmlFor="endLocation" style={{ display: "block", marginBottom: "5px" }}>
            End Location
          </label>
          <input
            id="endLocation"
            type="text"
            value={endLocation}
            onChange={(e) => setEndLocation(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <div>
          <label htmlFor="milesDriven" style={{ display: "block", marginBottom: "5px" }}>
            Miles Driven
          </label>
          <input
            id="milesDriven"
            type="number"
            value={milesDriven}
            onChange={(e) => setMilesDriven(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <div>
          <label htmlFor="purpose" style={{ display: "block", marginBottom: "5px" }}>
            Purpose
          </label>
          <input
            id="purpose"
            type="text"
            value={purpose}
            onChange={(e) => setPurpose(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <button
          type="submit"
          disabled={loading}
          style={{
            padding: "10px 15px",
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            borderRadius: "4px",
            cursor: loading ? "not-allowed" : "pointer"
          }}
        >
          {loading ? "Saving..." : "Save Trip"}
        </button>

        {error && (
          <div style={{ color: "red", marginTop: "10px" }}>
            {error}
          </div>
        )}
      </form>
    </div>
  );
