  const newUser = {
    id: users.length + 1,
    username,
    password,
    role
  };
  users.push(newUser);
  return newUser;
};

// Mock login function
const loginUser = (username: string, password: string) => {
  return users.find(user => user.username === username && user.password === password);
};

// Registration endpoint
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role } = req.body;

  if (!username || !password || !role) {
    return res.status(400).json({ error: "Username, password, and role are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.username === username);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Register new user
  const newUser = registerUser(username, password, role);
  return res.status(201).json(newUser);
});

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = loginUser(username, password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  return res.json({ message: "Login successful", user });
});

// Role-based access control middleware
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    // In a real app, this would check JWT token or session
    // For now, we'll simulate with a mock header
    const userRole = req.headers.role as string || "regular";

    if (userRole !== requiredRole) {
      return res.status(403).json({ error: "Access denied" });
    }

    next();
  };
};

// Staff-only route example
router.get("/staff-dashboard", requireRole("staff"), (req: Request, res: Response) => {
  return res.json({ message: "Welcome to the staff dashboard" });
});

// Regular user route example
router.get("/user-dashboard", requireRole("regular"), (req: Request, res: Response) => {
  return res.json({ message: "Welcome to your dashboard" });
});
"}

