{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database - in a real app this would be a proper database
const users: { email: string; password: string }[] = [];

// Registration endpoint
router.post("/register", (req: Request, res: Response) => {
  const { email, password } = req.body;

  // Basic validation
  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.email === email);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  users.push({ email, password });

  // Return success response
  return res.status(201).json({ message: "User registered successfully" });
});

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  // Basic validation
  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  // Find user
  const user = users.find(u => u.email === email && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // In a real app, we would generate a JWT token here
  // For now, we'll just return a success message
  return res.json({ message: "Login successful" });
});

// Session management endpoint
router.get("/session", (req: Request, res: Response) => {
  // In a real app, we would verify the JWT token here
  // For now, we'll just return a success message
  return res.json({ message: "Session valid" });
});
