{"code":"import { useEffect, useState } from "react";

interface Customer {
  id: string;
  name: string;
  email: string;
}

interface BillType {
  id: string;
  name: string;
  description: string;
}

interface PaymentMethod {
  id: string;
  name: string;
}

export function BillPaymentForm() {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [billTypes, setBillTypes] = useState<BillType[]>([]);
  const [paymentMethods, setPaymentMethods] = useState<PaymentMethod[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    customerId: "",
    billTypeId: "",
    amount: "",
    paymentMethodId: ""
  });

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [customersRes, billTypesRes, paymentMethodsRes] = await Promise.all([
          fetch("/api/bill-service/customers"),
          fetch("/api/bill-service/bill-types"),
          fetch("/api/bill-service/mobile-operators")
        ]);

        if (!customersRes.ok || !billTypesRes.ok || !paymentMethodsRes.ok) {
          throw new Error("Failed to fetch data");
        }

        const customersData = await customersRes.json();
        const billTypesData = await billTypesRes.json();
        const paymentMethodsData = await paymentMethodsRes.json();

        setCustomers(customersData);
        setBillTypes(billTypesData);
        setPaymentMethods(paymentMethodsData);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLSelectElement | HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = await fetch("/api/bill-service/transactions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          customerId: formData.customerId,
          billTypeId: formData.billTypeId,
          amount: parseFloat(formData.amount),
          paymentMethodId: formData.paymentMethodId
        })
      });

      if (!response.ok) {
        throw new Error("Failed to process payment");
      }

      // Reset form after successful submission
      setFormData({
        customerId: "",
        billTypeId: "",
        amount: "",
        paymentMethodId: ""
      });

      // Refresh data
      const [customersRes, billTypesRes, paymentMethodsRes] = await Promise.all([
        fetch("/api/bill-service/customers"),
        fetch("/api/bill-service/bill-types"),
        fetch("/api/bill-service/mobile-operators")
      ]);

      if (customersRes.ok && billTypesRes.ok && paymentMethodsRes.ok) {
        const customersData = await customersRes.json();
        const billTypesData = await billTypesRes.json();
        const paymentMethodsData = await paymentMethodsRes.json();

        setCustomers(customersData);
        setBillTypes(billTypesData);
        setPaymentMethods(paymentMethodsData);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px", fontFamily: "system-ui, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Bill Payment Form</h1>
      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        <div>
          <label htmlFor="customerId" style={{ display: "block", marginBottom: "5px" }}>Customer:</label>
          <select
            id="customerId"
            name="customerId"
            value={formData.customerId}
            onChange={handleChange}
            required
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          >
            <option value="">Select Customer</option>
            {customers.map(customer => (
              <option key={customer.id} value={customer.id}>{customer.name}</option>
            ))}
          </select>
        </div>

        <div>
          <label htmlFor="billTypeId" style={{ display: "block", marginBottom: "5px" }}>Bill Type:</label>
          <select
            id="billTypeId"
            name="billTypeId"
            value={formData.billTypeId}
            onChange={handleChange}
            required
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          >
            <option value="">Select Bill Type</option>
            {billTypes.map(type => (
              <option key={type.id} value={type.id}>{type.name}</option>
            ))}
          </select>
        </div>

        <div>
          <label htmlFor="amount" style={{ display: "block", marginBottom: "5px" }}>Amount:</label>
          <input
            type="number"
            id="amount"
            name="amount"
            value={formData.amount}
            onChange={handleChange}
            required
            step="0.01"
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
        </div>

        <div>
          <label htmlFor="paymentMethodId" style={{ display: "block", marginBottom: "5px" }}>Payment Method:</label>
          <select
            id="paymentMethodId"
            name="paymentMethodId"
            value={formData.paymentMethodId}
            onChange={handleChange}
            required
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          >
            <option value="">Select Payment Method</option>
            {paymentMethods.map(method => (
              <option key={method.id} value={method.id}>{method.name}</option>
            ))}
          </select>
        </div>

        <button
          type="submit"
          style={{
            backgroundColor: "#007bff",
            color: "white",
            padding: "10px 15px",
            border: "none",
            borderRadius: "4px",
            cursor: "pointer",
            fontSize: "16px"
          }}
        >
          Process Payment
        </button>
      </form>
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

interface Court {
  id: number;
  name: string;
  location: string;
  pricePerHour: number;
  isAvailable: boolean;
}

export function AdminCourtsManagementPage() {
  const [courts, setCourts] = useState<Court[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchCourts();
  }, []);

  const fetchCourts = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/courts');
      if (!response.ok) {
        throw new Error('Failed to fetch courts');
      }
      const data = await response.json();
      setCourts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleToggleAvailability = async (id: number) => {
    try {
      const court = courts.find(c => c.id === id);
      if (!court) return;

      const response = await fetch(`/api/courts/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...court,
          isAvailable: !court.isAvailable
        })
      });

      if (!response.ok) {
        throw new Error('Failed to update court availability');
      }

      // Refresh the list
      fetchCourts();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDeleteCourt = async (id: number) => {
    try {
      const response = await fetch(`/api/courts/${id}`, {
        method: 'DELETE'
      });

      if (!response.ok) {
        throw new Error('Failed to delete court');
      }

      // Refresh the list
      fetchCourts();
