{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST, PUT, DELETE requests to /parcels/
  if (!(req.method === "POST" || req.method === "PUT" || req.method === "DELETE") || !req.path.startsWith("/parcels/")) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  try {
    const [payload, signature] = token.split(".");
    if (!payload || !signature) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(payload)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // Decode payload (simplified for example)
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());
    const userRole = decodedPayload.role;

    // Check if role has permission
    if (userRole !== "admin" && userRole !== "staff") {
      res.status(403).json({ error: "Insufficient permissions" });
      return;
    }

    next();
  } catch (err) {
    res.status(401).json({ error: "Invalid token" });
  }
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import { 
  getAllTimeEntries,
  getTimeEntryById,
  insertTimeEntry,
  updateTimeEntry,
  deleteTimeEntry
} from "../db/time-entries-table";

export const router = Router();

// Get all time entries
router.get("/", (req: Request, res: Response) => {
  try {
    const timeEntries = getAllTimeEntries();
    res.json(timeEntries);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch time entries" });
  }
});

// Get a specific time entry by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const timeEntry = getTimeEntryById(id);
    if (!timeEntry) {
      return res.status(404).json({ error: "Time entry not found" });
    }

    res.json(timeEntry);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch time entry" });
  }
});

// Create a new time entry
router.post("/", (req: Request, res: Response) => {
  try {
    const { description, hours, rate, budget_id } = req.body;

    if (!description || typeof hours !== "number" || typeof rate !== "number" || typeof budget_id !== "number") {
      return res.status(400).json({ error: "Missing required fields: description, hours, rate, budget_id" });
    }

    const newId = insertTimeEntry(description, hours, rate, budget_id);
    const newEntry = getTimeEntryById(newId);

    if (!newEntry) {
      return res.status(500).json({ error: "Failed to create time entry" });
    }

    res.status(201).json(newEntry);
  } catch (error) {
    res.status(500).json({ error: "Failed to create time entry" });
  }
});

// Update an existing time entry
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const { description, hours, rate, budget_id } = req.body;

    if (!description || typeof hours !== "number" || typeof rate !== "number" || typeof budget_id !== "number") {
      return res.status(400).json({ error: "Missing required fields: description, hours, rate, budget_id" });
    }

    const existingEntry = getTimeEntryById(id);
    if (!existingEntry) {
      return res.status(404).json({ error: "Time entry not found" });
    }

    updateTimeEntry(id, description, hours, rate, budget_id);
    const updatedEntry = getTimeEntryById(id);

    if (!updatedEntry) {
      return res.status(500).json({ error: "Failed to update time entry" });
    }

    res.json(updatedEntry);
  } catch (error) {
    res.status(500).json({ error: "Failed to update time entry" });
  }
});

// Delete a time entry
router.delete("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }

    const existingEntry = getTimeEntryById(id);
    if (!existingEntry) {
      return res.status(404).json({ error: "Time entry not found" });
    }

    deleteTimeEntry(id);
    res.json({ message: "Time entry deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete time entry" });
  }
});
