  const vendor = vendors.find(v => v.id === id);

  if (!vendor) {
    return res.status(404).json({ message: "Vendor not found" });
  }

  res.json(vendor);
});

// Create a new vendor
router.post("/", (req: Request, res: Response) => {
  const { name, serviceType, contactInfo, bookingStatus } = req.body;

  // Validate required fields
  if (!name || !serviceType || !contactInfo || !bookingStatus) {
    return res.status(400).json({ message: "Name, service type, contact info, and booking status are required" });
  }

  const newVendor = {
    id: vendors.length > 0 ? Math.max(...vendors.map(v => v.id)) + 1 : 1,
    name,
    serviceType,
    contactInfo,
    bookingStatus
  };

  vendors.push(newVendor);
  res.status(201).json(newVendor);
});

// Update a vendor
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const vendorIndex = vendors.findIndex(v => v.id === id);

  if (vendorIndex === -1) {
    return res.status(404).json({ message: "Vendor not found" });
  }

  const { name, serviceType, contactInfo, bookingStatus } = req.body;

  // Validate required fields
  if (!name || !serviceType || !contactInfo || !bookingStatus) {
    return res.status(400).json({ message: "Name, service type, contact info, and booking status are required" });
  }

  vendors[vendorIndex] = {
    ...vendors[vendorIndex],
    name,
    serviceType,
    contactInfo,
    bookingStatus
  };

  res.json(vendors[vendorIndex]);
});

// Delete a vendor
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const vendorIndex = vendors.findIndex(v => v.id === id);

  if (vendorIndex === -1) {
    return res.status(404).json({ message: "Vendor not found" });
  }

  vendors.splice(vendorIndex, 1);
  res.json({ message: "Vendor deleted successfully" });
});
