{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function isValidMethod(method: string): boolean {
  return ["GET", "POST", "PUT", "DELETE"].includes(method);
}

function isProtectedPath(path: string): boolean {
  return path.startsWith("/api/attendance") || path.startsWith("/api/students");
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-protected paths or non-allowed methods
  if (!isValidMethod(req.method) || !isProtectedPath(req.path)) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  if (!JWT_SECRET) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    const [header, payload, signature] = parts;

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", JWT_SECRET)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }

    // Decode payload to extract role
    const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());
    const userRole = decodedPayload.role;

    // Check if user has required role
    if (!userRole || !isValidRole(userRole)) {
      res.status(403).json({ error: "Forbidden: Insufficient permissions" });
      return;
    }

    // Attach role to request for downstream middleware/routes
    (req as any).userRole = userRole;
    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

function isValidRole(role: string): boolean {
  return ["admin", "teacher", "staff"].includes(role);
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./food-bank.db");

interface Donation {
  id: number;
  itemName: string;
  quantity: number;
  date: string;
  loggedByUserId: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS donations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    itemName TEXT NOT NULL,
    quantity INTEGER NOT NULL,
    date TEXT NOT NULL,
    loggedByUserId INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllDonations(): Donation[] {
  const stmt = db.prepare("SELECT * FROM donations");
  return stmt.all() as unknown as Donation[];
}

export function getDonationById(id: number): Donation | undefined {
  const stmt = db.prepare("SELECT * FROM donations WHERE id = ?");
  return stmt.get(id) as unknown as Donation | undefined;
}

export function insertDonation(
  itemName: string,
  quantity: number,
  date: string,
  loggedByUserId: number
): number {
  const stmt = db.prepare(
    "INSERT INTO donations (itemName, quantity, date, loggedByUserId) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(itemName, quantity, date, loggedByUserId);
  return Number(result.lastInsertRowid);
}

export function updateDonation(
  id: number,
  itemName: string,
  quantity: number,
  date: string,
  loggedByUserId: number
): number {
  const stmt = db.prepare(
    "UPDATE donations SET itemName = ?, quantity = ?, date = ?, loggedByUserId = ? WHERE id = ?"
  );
  const result = stmt.run(itemName, quantity, date, loggedByUserId, id);
  return Number(result.changes);
}

export function deleteDonation(id: number): number {
  const stmt = db.prepare("DELETE FROM donations WHERE id = ?");
  const result = stmt.run(id);
  return Number(result.changes);
}

// Seed data
