{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes in milliseconds

// In-memory storage for sessions (in production, use Redis or similar)
const sessions = new Map<string, { userId: string; createdAt: number }>();

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Internal server error: JWT_SECRET not set" });
    return;
  }

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Unauthorized: Invalid token format" });
      return;
    }

    const [header, payload, signature] = parts;
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(signature, "base64url"),
      Buffer.from(expectedSignature, "base64url")
    );

    if (!isValid) {
      res.status(401).json({ error: "Unauthorized: Invalid token" });
      return;
    }

    // Decode payload (basic base64url decoding)
    const decodedPayload = JSON.parse(
      Buffer.from(payload, "base64url").toString("utf-8")
    );

    const sessionId = decodedPayload.sessionId;
    const storedSession = sessions.get(sessionId);

    if (!storedSession) {
      res.status(401).json({ error: "Unauthorized: Session not found" });
      return;
    }

    // Check session timeout
    const now = Date.now();
    if (now - storedSession.createdAt > SESSION_TIMEOUT) {
      sessions.delete(sessionId);
      res.status(401).json({ error: "Unauthorized: Session expired" });
      return;
    }

    // Update session timestamp
    sessions.set(sessionId, {
      ...storedSession,
      createdAt: now
    });

    // Attach user info to request
    (req as any).userId = storedSession.userId;
    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes and methods
  const isProtectedRoute = req.method === "POST" && req.path.startsWith("/requests") ||
                          req.method === "PUT" && req.path.startsWith("/inventory") ||
                          req.method === "DELETE" && req.path.startsWith("/inventory") ||
                          req.method === "PUT" && req.path.startsWith("/requests/") ||
                          req.method === "DELETE" && req.path.startsWith("/requests/");

  if (!isProtectedRoute) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT_SECRET not configured" });
    return;
  }

  try {
    // Simple token validation - in a real system, you'd decode and verify the JWT signature
    // For this example, we'll assume the token contains role information
    const payload = JSON.parse(atob(token.split('.')[1]));
    const userRole = payload.role;

    // Check if user has required permissions
    const isApprover = userRole === "approver";
    const isAdmin = userRole === "admin";

    // Allow approvers to approve requests and manage inventory
    if ((req.path.startsWith("/requests/") && req.method === "PUT") || 
        (req.path.startsWith("/inventory/") && (req.method === "PUT" || req.method === "DELETE"))) {
      if (!isApprover && !isAdmin) {
        res.status(403).json({ error: "Forbidden: Insufficient permissions" });
        return;
      }
    }

    // Allow admins to manage everything
    if (isAdmin) {
      next();
      return;
    }

    // Regular users can only submit requests
    if (req.path.startsWith("/requests") && req.method === "POST") {
      if (userRole !== "user") {
        res.status(403).json({ error: "Forbidden: Insufficient permissions" });
        return;
      }
    }

    // If we get here, the user has appropriate permissions
    next();
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}
"}

