export const router = Router();

// Mock book data storage
let books: any[] = [];
let nextId = 1;

// Validation helper
const validateBook = (book: any): string | null => {
  if (!book.title || typeof book.title !== 'string') {
    return 'Title is required and must be a string';
  }
  if (!book.author || typeof book.author !== 'string') {
    return 'Author is required and must be a string';
  }
  if (book.isbn && typeof book.isbn !== 'string') {
    return 'ISBN must be a string';
  }
  if (book.year && typeof book.year !== 'number') {
    return 'Year must be a number';
  }
  return null;
};

// GET /books - List all books
router.get('/', (req: Request, res: Response) => {
  res.json(books);
});

// GET /books/:id - Get a specific book by ID
router.get('/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const book = books.find(b => b.id === id);

  if (!book) {
    return res.status(404).json({ error: 'Book not found' });
  }

  res.json(book);
});

// POST /books - Create a new book
router.post('/', (req: Request, res: Response) => {
  const { title, author, isbn, year } = req.body;

  const validationError = validateBook({ title, author, isbn, year });
  if (validationError) {
    return res.status(400).json({ error: validationError });
  }

  const newBook = {
    id: nextId++,
    title,
    author,
    isbn,
    year
  };

  books.push(newBook);
  res.status(201).json(newBook);
});

// PUT /books/:id - Update a book
router.put('/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const bookIndex = books.findIndex(b => b.id === id);

  if (bookIndex === -1) {
    return res.status(404).json({ error: 'Book not found' });
  }

  const { title, author, isbn, year } = req.body;

  const validationError = validateBook({ title, author, isbn, year });
  if (validationError) {
    return res.status(400).json({ error: validationError });
  }

  const updatedBook = {
    id,
    title,
    author,
    isbn,
    year
  };

  books[bookIndex] = updatedBook;
  res.json(updatedBook);
});

// DELETE /books/:id - Delete a book
router.delete('/:id', (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const bookIndex = books.findIndex(b => b.id === id);

  if (bookIndex === -1) {
    return res.status(404).json({ error: 'Book not found' });
  }

  books.splice(bookIndex, 1);
  res.json({ message: 'Book deleted successfully' });
});
