  },
  {
    id: "2",
    ngoId: "ngo2",
    foodType: "Fruits",
    quantity: 30,
    status: "approved",
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  }
];

const findRequestById = (id: string) => requests.find(request => request.id === id);

const createRequest = (requestData: any) => {
  const newRequest = {
    id: (requests.length + 1).toString(),
    ngoId: requestData.ngoId,
    foodType: requestData.foodType,
    quantity: requestData.quantity,
    status: "pending",
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };
  requests.push(newRequest);
  return newRequest;
};

const updateRequest = (id: string, updateData: any) => {
  const index = requests.findIndex(request => request.id === id);
  if (index === -1) return null;

  const updatedRequest = {
    ...requests[index],
    ...updateData,
    updatedAt: new Date().toISOString()
  };

  requests[index] = updatedRequest;
  return updatedRequest;
};

const deleteRequest = (id: string) => {
  const index = requests.findIndex(request => request.id === id);
  if (index === -1) return false;

  requests.splice(index, 1);
  return true;
};

// GET /requests - List all requests
router.get("/requests", (req: Request, res: Response) => {
  res.json(requests);
});

// GET /requests/:id - Get a specific request by ID
router.get("/requests/:id", (req: Request, res: Response) => {
  const request = findRequestById(req.params.id);
  if (!request) {
    return res.status(404).json({ error: "Request not found" });
  }
  res.json(request);
});

// POST /requests - Create a new request
router.post("/requests", (req: Request, res: Response) => {
  const { ngoId, foodType, quantity } = req.body;

  if (!ngoId || !foodType || !quantity) {
    return res.status(400).json({ error: "Missing required fields: ngoId, foodType, quantity" });
  }

  const newRequest = createRequest({ ngoId, foodType, quantity });
  res.status(201).json(newRequest);
});

// PUT /requests/:id - Update a request
router.put("/requests/:id", (req: Request, res: Response) => {
  const { status } = req.body;

  if (!status) {
    return res.status(400).json({ error: "Missing required field: status" });
  }

  const updatedRequest = updateRequest(req.params.id, { status });

  if (!updatedRequest) {
    return res.status(404).json({ error: "Request not found" });
  }

  res.json(updatedRequest);
});

// DELETE /requests/:id - Delete a request
router.delete("/requests/:id", (req: Request, res: Response) => {
  const deleted = deleteRequest(req.params.id);

  if (!deleted) {
    return res.status(404).json({ error: "Request not found" });
  }

  res.json({ message: "Request deleted successfully" });
});
