{"code":"import { useEffect, useState } from "react";

interface TimeEntry {
  id: string;
  projectId: string;
  description: string;
  startTime: string;
  endTime: string | null;
  duration: number;
}

interface Project {
  id: string;
  name: string;
}

export function TimeEntriesList() {
  const [timeEntries, setTimeEntries] = useState<TimeEntry[]>([]);
  const [projects, setProjects] = useState<Project[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedProject, setSelectedProject] = useState("all");

  useEffect(() => {
    async function fetchTimeEntriesAndProjects() {
      try {
        const [entriesResponse, projectsResponse] = await Promise.all([
          fetch("/api/time-entries-api/"),
          fetch("/api/projects-api/")
        ]);

        if (!entriesResponse.ok || !projectsResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const entriesData = await entriesResponse.json();
        const projectsData = await projectsResponse.json();

        setTimeEntries(entriesData);
        setProjects(projectsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchTimeEntriesAndProjects();
  }, []);

  const filteredEntries = timeEntries.filter(entry => {
    const matchesSearch = entry.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesProject = selectedProject === "all" || entry.projectId === selectedProject;
    return matchesSearch && matchesProject;
  });

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/time-entries-api/${id}`, {
        method: "DELETE"
      });

      if (response.ok) {
        setTimeEntries(timeEntries.filter(entry => entry.id !== id));
      } else {
        throw new Error("Failed to delete entry");
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Time Entries</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search entries..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        />

        <select
          value={selectedProject}
          onChange={(e) => setSelectedProject(e.target.value)}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="all">All Projects</option>
          {projects.map(project => (
            <option key={project.id} value={project.id}>{project.name}</option>
          ))}
        </select>
      </div>

      {filteredEntries.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No time entries found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {filteredEntries.map(entry => {
            const project = projects.find(p => p.id === entry.projectId);
            return (
              <div key={entry.id} style={{ border: "1px solid #ccc", borderRadius: "4px", padding: "10px" }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                  <div>
                    <h3>{project?.name || "Unknown Project"}</h3>
                    <p>{entry.description}</p>
                    <p><strong>Duration:</strong> {entry.duration} seconds</p>
                    <p><strong>Start:</strong> {new Date(entry.startTime).toLocaleString()}</p>
                    {entry.endTime && (
                      <p><strong>End:</strong> {new Date(entry.endTime).toLocaleString()}</p>
                    )}
                  </div>
                  <div style={{ display: "flex", gap: "5px" }}>
                    <button
                      onClick={() => handleDelete(entry.id)}
                      style={{ backgroundColor: "#ff4d4d", color: "white", border: "none", padding: "5px 10px", borderRadius: "4px", cursor: "pointer" }}
                    >
                      Delete
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
"}

