{"code":"import { useEffect, useState } from "react";

interface RepairLog {
  id: number;
  bikeId: number;
  description: string;
  date: string;
}

interface Bike {
  id: number;
  name: string;
}

export function RepairLogForm() {
  const [bikes, setBikes] = useState<Bike[]>([]);
  const [repairLogs, setRepairLogs] = useState<RepairLog[]>([]);
  const [formData, setFormData] = useState({
    bikeId: "",
    description: "",
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [bikesResponse, logsResponse] = await Promise.all([
          fetch("/api/maintenance-records-api/"),
          fetch("/api/maintenance-records-api/"),
        ]);

        if (!bikesResponse.ok || !logsResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const bikesData = await bikesResponse.json();
        const logsData = await logsResponse.json();

        setBikes(bikesData);
        setRepairLogs(logsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = await fetch("/api/maintenance-records-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          bikeId: Number(formData.bikeId),
          description: formData.description,
          date: new Date().toISOString().split("T")[0],
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to submit repair log");
      }

      // Refresh data after successful submission
      const [bikesResponse, logsResponse] = await Promise.all([
        fetch("/api/maintenance-records-api/"),
        fetch("/api/maintenance-records-api/"),
      ]);

      if (!bikesResponse.ok || !logsResponse.ok) {
        throw new Error("Failed to refresh data");
      }

      const bikesData = await bikesResponse.json();
      const logsData = await logsResponse.json();

      setBikes(bikesData);
      setRepairLogs(logsData);

      // Reset form
      setFormData({ bikeId: "", description: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div>Loading...</div>;
