  const recentLogsStyle: React.CSSProperties = {
    marginTop: "30px",
    maxWidth: "600px",
    margin: "0 auto",
    fontFamily: "system-ui, sans-serif",
  };

  const logItemStyle: React.CSSProperties = {
    padding: "10px",
    borderBottom: "1px solid #eee",
