{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes

interface Session {
  userId: string;
  createdAt: number;
}

const activeSessions = new Map<string, Session>();

function getSessionIdFromRequest(req: Request): string | null {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return null;
  }

  const token = authHeader.substring(7);
  return token;
}

function verifyTokenSignature(token: string): boolean {
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return false;
  }

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) {
      return false;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(signatureBuffer, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

function decodeToken(token: string): { userId: string } | null {
  try {
    const payload = token.split(".")[1];
    const decoded = Buffer.from(payload, "base64url").toString("utf-8");
    return JSON.parse(decoded);
  } catch {
    return null;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST /logout requests
  if (req.method !== "POST" || req.path !== "/logout") {
    next();
    return;
  }

  const sessionId = getSessionIdFromRequest(req);
  if (!sessionId) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  if (!verifyTokenSignature(sessionId)) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  const tokenData = decodeToken(sessionId);
  if (!tokenData) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  const session = activeSessions.get(sessionId);
  if (!session) {
    res.status(401).json({ error: "Session not found" });
    return;
  }

  // Check if session has timed out
  if (Date.now() - session.createdAt > SESSION_TIMEOUT) {
    activeSessions.delete(sessionId);
    res.status(401).json({ error: "Session expired" });
    return;
  }

  // Invalidate session on logout
  activeSessions.delete(sessionId);
  res.json({ message: "Logged out successfully" });
}
"}

{"code":"import { useEffect, useState } from "react";

interface Employee {
  id: number;
  name: string;
  position: string;
  salary: number;
}

export function EmployeeManagement() {
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Form state
  const [formData, setFormData] = useState({
    name: "",
    position: "",
    salary: ""
  });

  const [editingId, setEditingId] = useState<number | null>(null);

  // Fetch employees
  useEffect(() => {
    const fetchEmployees = async () => {
      try {
        const response = await fetch("/api/employees");
        if (!response.ok) {
          throw new Error(`Failed to fetch: ${response.status}`);
        }
        const data = await response.json();
        setEmployees(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchEmployees();
  }, []);

  // Handle form input changes
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  // Submit form (add or edit)
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const url = editingId 
        ? `/api/employees/${editingId}`
        : "/api/employees";

      const method = editingId ? "PUT" : "POST";

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...formData,
          salary: Number(formData.salary)
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to save: ${response.status}`);
      }

      // Refresh data
      const fetchEmployees = async () => {
        const response = await fetch("/api/employees");
        if (!response.ok) {
          throw new Error(`Failed to fetch: ${response.status}`);
        }
        const data = await response.json();
        setEmployees(data);
        setLoading(false);
      };

      fetchEmployees();

      // Reset form
      setFormData({ name: "", position: "", salary: "" });
      setEditingId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  // Delete employee
  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/employees/${id}`, { method: "DELETE" });
      if (!response.ok) {
        throw new Error(`Failed to delete: ${response.status}`);
      }

      // Refresh data
      const fetchEmployees = async () => {
        const response = await fetch("/api/employees");
        if (!response.ok) {
          throw new Error(`Failed to fetch: ${response.status}`);
        }
        const data = await response.json();
        setEmployees(data);
        setLoading(false);
      };

      fetchEmployees();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  // Edit employee
  const handleEdit = (employee: Employee) => {
    setFormData({
      name: employee.name,
      position: employee.position,
      salary: employee.salary.toString()
    });
    setEditingId(employee.id);
  };

  // Cancel edit
  const handleCancel = () => {
    setFormData({ name: "", position: "", salary: "" });
    setEditingId(null);
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Employee Management</h1>

      {/* Add/Edit Form */}
      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          <input
            type="text"
            name="name"
            placeholder="Name"
            value={formData.name}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", boxSizing: "border-box" }}
          />
          <input
            type="text"
            name="position"
            placeholder="Position"
            value={formData.position}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", boxSizing: "border-box" }}
          />
          <input
            type="number"
            name="salary"
            placeholder="Salary"
            value={formData.salary}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", boxSizing: "border-box" }}
          />
          <div style={{ display: "flex", gap: "10px" }}>
            <button 
              type="submit" 
              style={{ flex: 1, padding: "10px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
            >
              {editingId ? "Update Employee" : "Add Employee"}
            </button>
            {editingId && (
              <button 
                type="button" 
                onClick={handleCancel}
                style={{ flex: 1, padding: "10px", backgroundColor: "#6c757d", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
              >
                Cancel
              </button>
            )}
          </div>
        </div>
      </form>

      {/* Employee List */}
      <div>
        <h2>Employee Records</h2>
        {employees.length === 0 ? (
          <p style={{ textAlign: "center", padding: "20px" }}>No employees found.</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {employees.map(employee => (
              <div 
                key={employee.id} 
                style={{ 
                  border: "1px solid #ccc", 
                  borderRadius: "8px", 
                  padding: "15px", 
                  display: "flex", 
                  justifyContent: "space-between", 
                  alignItems: "center",
                  flexWrap: "wrap"
                }}
              >
                <div style={{ flex: 1, minWidth: "200px" }}>
                  <strong>{employee.name}</strong><br />
                  {employee.position}<br />
                  Salary: ${employee.salary.toLocaleString()}
                </div>
                <div style={{ display: "flex", gap: "5px", flexShrink: 0 }}>
                  <button 
                    onClick={() => handleEdit(employee)}
                    style={{ padding: "5px 10px", backgroundColor: "#17a2b8", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
                  >
                    Edit
                  </button>
                  <button 
                    onClick={() => handleDelete(employee.id)}
                    style={{ padding: "5px 10px", backgroundColor: "#dc3545", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockStudents = [
  { id: "1", name: "John Doe", email: "john@example.com", balance: 0 },
  { id: "2", name: "Jane Smith", email: "jane@example.com", balance: 0 }
];

const mockPayments = [
  { id: "1", studentId: "1", amount: 500, date: "2023-01-15" },
  { id: "2", studentId: "1", amount: 300, date: "2023-02-15" }
];

// Get all students
router.get("/students", (req: Request, res: Response) => {
  res.json(mockStudents);
});

// Get a student by ID
router.get("/students/:id", (req: Request, res: Response) => {
  const studentId = req.params.id;
  const student = mockStudents.find(s => s.id === studentId);

  if (!student) {
    return res.status(404).json({ error: "Student not found" });
  }

  res.json(student);
});

// Create a new student
router.post("/students", (req: Request, res: Response) => {
  const { name, email } = req.body;

  if (!name || !email) {
    return res.status(400).json({ error: "Name and email are required" });
  }

  const newStudent = {
    id: String(mockStudents.length + 1),
    name,
    email,
    balance: 0
  };

  mockStudents.push(newStudent);
  res.status(201).json(newStudent);
});

// Update a student
router.put("/students/:id", (req: Request, res: Response) => {
  const studentId = req.params.id;
  const { name, email } = req.body;

  const studentIndex = mockStudents.findIndex(s => s.id === studentId);

  if (studentIndex === -1) {
    return res.status(404).json({ error: "Student not found" });
  }

  if (!name || !email) {
    return res.status(400).json({ error: "Name and email are required" });
  }

  mockStudents[studentIndex] = {
    ...mockStudents[studentIndex],
    name,
    email
  };

  res.json(mockStudents[studentIndex]);
});

// Delete a student
router.delete("/students/:id", (req: Request, res: Response) => {
  const studentId = req.params.id;
  const studentIndex = mockStudents.findIndex(s => s.id === studentId);

  if (studentIndex === -1) {
    return res.status(404).json({ error: "Student not found" });
  }

  mockStudents.splice(studentIndex, 1);
  res.json({ message: "Student deleted successfully" });
});

// Get payment history for a student
router.get("/students/:id/payments", (req: Request, res: Response) => {
  const studentId = req.params.id;

  const student = mockStudents.find(s => s.id === studentId);

  if (!student) {
    return res.status(404).json({ error: "Student not found" });
  }

  const payments = mockPayments.filter(p => p.studentId === studentId);
  res.json(payments);
});
"}

{"code":"import { useEffect, useState } from "react";

interface Book {
  id: number;
  title: string;
  author: string;
  isbn: string;
}

interface Checkout {
  id: number;
  bookId: number;
  borrowerName: string;
  checkoutDate: string;
  dueDate: string;
}

export function CheckoutUi() {
  const [books, setBooks] = useState<Book[]>([]);
  const [checkouts, setCheckouts] = useState<Checkout[]>([]);
  const [borrowerName, setBorrowerName] = useState("");
  const [selectedBookId, setSelectedBookId] = useState<number | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchAllData() {
      try {
        setLoading(true);
        const [booksResponse, checkoutsResponse] = await Promise.all([
          fetch("/api/checkouts-api/"),
          fetch("/api/checkouts-api/"),
        ]);

        if (!booksResponse.ok || !checkoutsResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const booksData = await booksResponse.json();
        const checkoutsData = await checkoutsResponse.json();

        setBooks(booksData);
        setCheckouts(checkoutsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchAllData();
  }, []);

  const handleCheckout = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedBookId || !borrowerName.trim()) return;

    try {
      const response = await fetch(`/api/checkouts-api/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          bookId: selectedBookId,
          borrowerName,
          checkoutDate: new Date().toISOString(),
          dueDate: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString(),
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to checkout book");
      }

      // Refresh data
      const [booksResponse, checkoutsResponse] = await Promise.all([
        fetch("/api/checkouts-api/"),
        fetch("/api/checkouts-api/"),
      ]);

      if (booksResponse.ok && checkoutsResponse.ok) {
        const booksData = await booksResponse.json();
        const checkoutsData = await checkoutsResponse.json();

        setBooks(booksData);
        setCheckouts(checkoutsData);
        setBorrowerName("");
        setSelectedBookId(null);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={containerStyle}>
      <h1>Library Checkout</h1>

      <form onSubmit={handleCheckout} style={formStyle}>
        <h2>Checkout a Book</h2>
        <div style={{ marginBottom: "10px" }}>
          <label htmlFor="bookSelect">Select a Book:</label>
          <select
            id="bookSelect"
            value={selectedBookId ?? ""}
            onChange={(e) => setSelectedBookId(Number(e.target.value))}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          >
            <option value="">Choose a book</option>
            {books.map((book) => (
              <option key={book.id} value={book.id}>
                {book.title} by {book.author}
              </option>
            ))}
          </select>
        </div>

        <div style={{ marginBottom: "10px" }}>
          <label htmlFor="borrowerName">Borrower Name:</label>
          <input
            id="borrowerName"
            type="text"
            value={borrowerName}
            onChange={(e) => setBorrowerName(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <button
          type="submit"
          style={{
            backgroundColor: "#007bff",
            color: "white",
            padding: "10px 20px",
            border: "none",
            borderRadius: "4px",
            cursor: "pointer",
            fontSize: "16px",
          }}
        >
          Checkout Book
        </button>
      </form>

      <h2>Available Books</h2>
      {books.length === 0 ? (
        <p>No books available.</p>
      ) : (
        <div style={gridStyle}>
          {books.map((book) => (
            <div key={book.id} style={cardStyle}>
              <h3>{book.title}</h3>
              <p><strong>Author:</strong> {book.author}</p>
              <p><strong>ISBN:</strong> {book.isbn}</p>
            </div>
          ))}
        </div>
      )}

      <h2>Current Checkouts</h2>
      {checkouts.length === 0 ? (
        <p>No current checkouts.</p>
      ) : (
        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr style={{ borderBottom: "1px solid #ddd" }}>
              <th style={{ padding: "8px", textAlign: "left" }}>Book Title</th>
              <th style={{ padding: "8px", textAlign: "left" }}>Borrower</th>
              <th style={{ padding: "8px", textAlign: "left" }}>Checkout Date</th>
              <th style={{ padding: "8px", textAlign: "left" }}>Due Date</th>
              <th style={{ padding: "8px", textAlign: "left" }}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {checkouts.map((checkout) => {
              const book = books.find(b => b.id === checkout.bookId);
              return (
                <tr key={checkout.id} style={{ borderBottom: "1px solid #ddd" }}>
                  <td style={{ padding: "8px" }}>{book?.title || "Unknown Book"}</td>
                  <td style={{ padding: "8px" }}>{checkout.borrowerName}</td>
                  <td style={{ padding: "8px" }}>{new Date(checkout.checkoutDate).toLocaleDateString()}</td>
