{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface SavedArticle {
  id: number;
  userId: number;
  title: string;
  url: string;
  content: string;
  archivedAt: Date;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS saved_articles (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    userId INTEGER NOT NULL,
    title TEXT NOT NULL,
    url TEXT UNIQUE NOT NULL,
    content TEXT NOT NULL,
    archivedAt DATETIME NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllSavedArticles(): SavedArticle[] {
  const stmt = db.prepare(`
    SELECT id, userId, title, url, content, archivedAt 
    FROM saved_articles 
    ORDER BY archivedAt DESC
  `);
  return stmt.all() as unknown as SavedArticle[];
}

export function getSavedArticleById(id: number): SavedArticle | undefined {
  const stmt = db.prepare(`
    SELECT id, userId, title, url, content, archivedAt 
    FROM saved_articles 
    WHERE id = ?
  `);
  return stmt.get(id) as unknown as SavedArticle | undefined;
}

export function insertSavedArticle(
  userId: number,
  title: string,
  url: string,
  content: string
): number {
  const stmt = db.prepare(`
    INSERT INTO saved_articles (userId, title, url, content, archivedAt)
    VALUES (?, ?, ?, ?, datetime('now'))
  `);
  const result = stmt.run(userId, title, url, content);
  return Number(result.lastInsertRowid);
}

export function updateSavedArticle(
  id: number,
  title: string,
  content: string
): number {
  const stmt = db.prepare(`
    UPDATE saved_articles 
    SET title = ?, content = ?
    WHERE id = ?
  `);
  const result = stmt.run(title, content, id);
  return Number(result.changes);
}

export function deleteSavedArticle(id: number): number {
  const stmt = db.prepare(`
    DELETE FROM saved_articles 
    WHERE id = ?
  `);
  const result = stmt.run(id);
  return Number(result.changes);
}

