{"code":"import type { Request, Response, NextFunction } from "express";
import { router as feedingsApiRouter } from "../routes/feedings-api";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check ownership for requests to the feedings API routes
  if (!req.path.startsWith("/api/feedings")) {
    next();
    return;
  }

  // For this example, we'll assume the owner is identified by a fixed ID
  // In a real implementation, this would check the authenticated user
  const ownerID = "owner123";

  // Check if the request has an owner ID in the headers or params
  const requestOwnerID = req.headers["x-owner-id"] as string || req.params.ownerId;

  // If the owner ID doesn't match, reject the request
  if (requestOwnerID !== ownerID) {
    res.status(403).json({ error: "Forbidden: Access denied to this resource." });
    return;
  }

  // If the owner matches, proceed to the next middleware/route handler
  next();
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./equipment.db");

interface EquipmentStock {
  id: number;
  name: string;
  stock_count: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS equipment_stock (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    stock_count INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllEquipment(): EquipmentStock[] {
  const stmt = db.prepare(`SELECT * FROM equipment_stock`);
  return stmt.all() as unknown as EquipmentStock[];
}

export function getEquipmentById(id: number): EquipmentStock | undefined {
  const stmt = db.prepare(`SELECT * FROM equipment_stock WHERE id = ?`);
  return stmt.get(id) as unknown as EquipmentStock | undefined;
}

export function insertEquipment(name: string, stock_count: number): number {
  const stmt = db.prepare(
    `INSERT INTO equipment_stock (name, stock_count) VALUES (?, ?)`
  );
  const result = stmt.run(name, stock_count);
  return Number(result.lastInsertRowid);
}

export function updateEquipment(
  id: number,
  name: string,
  stock_count: number
): void {
  const stmt = db.prepare(
    `UPDATE equipment_stock SET name = ?, stock_count = ? WHERE id = ?`
  );
  stmt.run(name, stock_count, id);
}

export function deleteEquipment(id: number): void {
  const stmt = db.prepare(`DELETE FROM equipment_stock WHERE id = ?`);
  stmt.run(id);
}

// Seed data
if (getAllEquipment().length === 0) {
  insertEquipment("Camera Body", 5);
  insertEquipment("Lens Kit", 12);
  insertEquipment("Tripod", 8);
  insertEquipment("Flash Unit", 15);
  insertEquipment("Microphone", 10);
}
"}

