export const db = new DatabaseSync("./shop.db");

interface Sale {
  id: number;
  timestamp: string;
  items_sold: string;
  total_amount: number;
  payment_method: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS sales (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    timestamp TEXT NOT NULL,
    items_sold TEXT NOT NULL,
    total_amount REAL NOT NULL,
    payment_method TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllSales(): Sale[] {
  const stmt = db.prepare("SELECT * FROM sales;");
  return stmt.all() as unknown as Sale[];
}

export function getSaleById(id: number): Sale | undefined {
  const stmt = db.prepare("SELECT * FROM sales WHERE id = ?;");
  return stmt.get(id) as unknown as Sale | undefined;
}

export function insertSale(
  timestamp: string,
  items_sold: string,
  total_amount: number,
  payment_method: string
): number {
  const stmt = db.prepare(
    "INSERT INTO sales (timestamp, items_sold, total_amount, payment_method) VALUES (?, ?, ?, ?);"
  );
  const result = stmt.run(timestamp, items_sold, total_amount, payment_method);
  return Number(result.lastInsertRowid);
}

export function updateSale(
  id: number,
  timestamp: string,
  items_sold: string,
  total_amount: number,
  payment_method: string
): number {
  const stmt = db.prepare(
    "UPDATE sales SET timestamp = ?, items_sold = ?, total_amount = ?, payment_method = ? WHERE id = ?;"
  );
  const result = stmt.run(timestamp, items_sold, total_amount, payment_method, id);
  return Number(result.changes);
}

export function deleteSale(id: number): number {
  const stmt = db.prepare("DELETE FROM sales WHERE id = ?;");
  const result = stmt.run(id);
  return Number(result.changes);
}

