    id INTEGER PRIMARY KEY AUTOINCREMENT,
    workout_id INTEGER NOT NULL,
    exercise TEXT NOT NULL,
    reps INTEGER NOT NULL
  );
`;

export function getAllWorkouts(): WorkoutRow[] {
  const stmt = db.prepare(`
    SELECT * FROM workouts
  `);
  return stmt.all() as unknown as WorkoutRow[];
}

export function getWorkoutById(id: number): WorkoutRow | undefined {
  const stmt = db.prepare(`
    SELECT * FROM workouts WHERE id = ?
  `);
  return stmt.get(id) as WorkoutRow | undefined;
}

export function insertWorkout(
  trainerId: number,
  clientId: number,
  date: string
): number {
  const stmt = db.prepare(`
    INSERT INTO workouts (trainer_id, client_id, date)
    VALUES (?, ?, ?)
  `);
  const result = stmt.run(trainerId, clientId, date);
  return Number(result.lastInsertRowid);
}

export function updateWorkout(
  id: number,
  trainerId: number,
  clientId: number,
  date: string
): void {
  const stmt = db.prepare(`
    UPDATE workouts
    SET trainer_id = ?, client_id = ?, date = ?
    WHERE id = ?
  `);
  stmt.run(trainerId, clientId, date, id);
}

export function deleteWorkout(id: number): void {
  const stmt = db.prepare(`
    DELETE FROM workouts WHERE id = ?
  `);
  stmt.run(id);
}

export function getWorkoutDetails(workoutId: number): ExerciseDetailRow[] {
  const stmt = db.prepare(`
