export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const protectedPaths = ["/route-logs", "/route-logs/:id"];
  const isProtectedPath = protectedPaths.some(path => 
    path.includes(":id") ? req.path.startsWith(path.replace(":id", "")) : req.path === path
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;
  const requiredRoles = ["driver", "supervisor", "admin"];

  if (!userRole || !requiredRoles.includes(userRole)) {
    res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    return;
  }

  // Allow access for valid roles
  next();
}
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock event data structure
interface Event {
  id: number;
  title: string;
  description: string;
  date: string;
  location: string;
}

// Mock in-memory storage for events
let events: Event[] = [];
let nextId = 1;

// GET /events - Retrieve all events
router.get("/", (req: Request, res: Response) => {
  res.json(events);
});

// GET /events/:id - Retrieve a specific event by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const event = events.find(e => e.id === id);

  if (!event) {
    return res.status(404).json({ error: "Event not found" });
  }

  res.json(event);
});

// POST /events - Create a new event
router.post("/", (req: Request, res: Response) => {
  const { title, description, date, location } = req.body;

  // Validate required fields
  if (!title || !description || !date || !location) {
    return res.status(400).json({ error: "Title, description, date, and location are required" });
  }

  const newEvent: Event = {
    id: nextId++,
    title,
    description,
    date,
    location
  };

  events.push(newEvent);
  res.status(201).json(newEvent);
});

// PUT /events/:id - Update an existing event
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const eventIndex = events.findIndex(e => e.id === id);

  if (eventIndex === -1) {
    return res.status(404).json({ error: "Event not found" });
  }

  const { title, description, date, location } = req.body;

  // Validate required fields
  if (!title || !description || !date || !location) {
    return res.status(400).json({ error: "Title, description, date, and location are required" });
  }

  events[eventIndex] = {
    id,
    title,
    description,
    date,
    location
  };

  res.json(events[eventIndex]);
});

// DELETE /events/:id - Delete an event
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const eventIndex = events.findIndex(e => e.id === id);

  if (eventIndex === -1) {
    return res.status(404).json({ error: "Event not found" });
  }

  events.splice(eventIndex, 1);
  res.json({ message: "Event deleted successfully" });
});
"}

