{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database - in a real app this would be a proper database
const users = [
  { id: 1, username: "admin", password: "password123" },
  { id: 2, username: "user", password: "mypassword" }
];

// Session storage - in a real app this would be a proper session store
const sessions: Record<string, { userId: number; username: string }> = {};

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate a simple session ID
  const sessionId = Math.random().toString(36).substring(2, 15);
  sessions[sessionId] = { userId: user.id, username: user.username };

  res.json({ sessionId, username: user.username });
});

// Logout endpoint
router.post("/logout", (req: Request, res: Response) => {
  const { sessionId } = req.body;

  if (!sessionId) {
    return res.status(400).json({ error: "Session ID is required" });
  }

  if (!sessions[sessionId]) {
    return res.status(401).json({ error: "Invalid session" });
  }

  delete sessions[sessionId];
  res.json({ message: "Logged out successfully" });
});

// Middleware to verify session
const authenticate = (req: Request, res: Response, next: () => void) => {
  const { sessionId } = req.headers;

  if (!sessionId || !sessions[sessionId as string]) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  next();
};

// Protected route example
router.get("/profile", authenticate, (req: Request, res: Response) => {
  const sessionId = req.headers.sessionid as string;
  const session = sessions[sessionId];

  if (!session) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  res.json({ username: session.username });
});
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface Delivery {
  id: number;
  trackingNumber: string;
  recipientName: string;
  address: string;
  status: string;
  estimatedDeliveryDate: string;
  actualDeliveryDate: string | null;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS deliveries (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    trackingNumber TEXT NOT NULL UNIQUE,
    recipientName TEXT NOT NULL,
    address TEXT NOT NULL,
    status TEXT NOT NULL,
    estimatedDeliveryDate TEXT NOT NULL,
    actualDeliveryDate TEXT
  );
`;

db.exec(createTableSql);

export function getAllDeliveries(): Delivery[] {
  const stmt = db.prepare(`SELECT * FROM deliveries ORDER BY id`);
  return stmt.all() as unknown as Delivery[];
}

export function getDeliveryById(id: number): Delivery | undefined {
  const stmt = db.prepare(`SELECT * FROM deliveries WHERE id = ?`);
  return stmt.get(id) as unknown as Delivery | undefined;
}

export function insertDelivery(delivery: Omit<Delivery, "id">): number {
  const stmt = db.prepare(`
    INSERT INTO deliveries (
      trackingNumber,
      recipientName,
      address,
      status,
      estimatedDeliveryDate,
      actualDeliveryDate
    ) VALUES (?, ?, ?, ?, ?, ?)
  `);
  const result = stmt.run(
    delivery.trackingNumber,
    delivery.recipientName,
    delivery.address,
    delivery.status,
    delivery.estimatedDeliveryDate,
    delivery.actualDeliveryDate
  );
  return Number(result.lastInsertRowid);
}

export function updateDelivery(id: number, delivery: Partial<Omit<Delivery, "id">>): boolean {
  const fields = [];
  const values = [];

  if (delivery.trackingNumber !== undefined) {
    fields.push("trackingNumber = ?");
    values.push(delivery.trackingNumber);
  }

  if (delivery.recipientName !== undefined) {
    fields.push("recipientName = ?");
    values.push(delivery.recipientName);
  }

  if (delivery.address !== undefined) {
    fields.push("address = ?");
    values.push(delivery.address);
  }

  if (delivery.status !== undefined) {
    fields.push("status = ?");
    values.push(delivery.status);
  }

  if (delivery.estimatedDeliveryDate !== undefined) {
    fields.push("estimatedDeliveryDate = ?");
    values.push(delivery.estimatedDeliveryDate);
  }

  if (delivery.actualDeliveryDate !== undefined) {
    fields.push("actualDeliveryDate = ?");
    values.push(delivery.actualDeliveryDate);
  }

  if (fields.length === 0) return false;

  values.push(id);

  const sql = `UPDATE deliveries SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);

  return true;
}

export function deleteDelivery(id: number): boolean {
  const stmt = db.prepare(`DELETE FROM deliveries WHERE id = ?`);
  const result = stmt.run(id);
  return result.changes > 0;
}

