{"code":"import { useEffect, useState } from "react";

interface Part {
  id: number;
  name: string;
  quantity: number;
}

interface PartRequest {
  id?: number;
  partId: number;
  quantity: number;
  status: 'pending' | 'approved' | 'rejected';
}

export function PartRequestForm() {
  const [parts, setParts] = useState<Part[]>([]);
  const [requests, setRequests] = useState<PartRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newRequest, setNewRequest] = useState({
    partId: '',
    quantity: ''
  });

  useEffect(() => {
    const fetchData = async () => {
      try {
        const partsResponse = await fetch('/api/parts-api/');
        if (!partsResponse.ok) throw new Error('Failed to fetch parts');
        const partsData = await partsResponse.json();
        setParts(partsData);

        const requestsResponse = await fetch('/api/parts-api/');
        if (!requestsResponse.ok) throw new Error('Failed to fetch requests');
        const requestsData = await requestsResponse.json();
        setRequests(requestsData);

        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!newRequest.partId || !newRequest.quantity) return;

    try {
      const response = await fetch('/api/parts-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          partId: Number(newRequest.partId),
          quantity: Number(newRequest.quantity),
          status: 'pending'
        })
      });

      if (!response.ok) throw new Error('Failed to submit request');

      // Refresh data
      const partsResponse = await fetch('/api/parts-api/');
      if (partsResponse.ok) {
        const partsData = await partsResponse.json();
        setParts(partsData);
      }

      const requestsResponse = await fetch('/api/parts-api/');
      if (requestsResponse.ok) {
        const requestsData = await requestsResponse.json();
        setRequests(requestsData);
      }

      // Reset form
      setNewRequest({ partId: '', quantity: '' });
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Part Request Form</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <h2>Submit New Request</h2>
        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="partId" style={{ display: 'block', marginBottom: '5px' }}>Part:</label>
          <select
            id="partId"
            value={newRequest.partId}
            onChange={(e) => setNewRequest({...newRequest, partId: e.target.value})}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
            required
          >
            <option value="">Select a part</option>
            {parts.map(part => (
              <option key={part.id} value={part.id}>{part.name}</option>
            ))}
          </select>
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="quantity" style={{ display: 'block', marginBottom: '5px' }}>Quantity:</label>
          <input
            type="number"
            id="quantity"
            value={newRequest.quantity}
            onChange={(e) => setNewRequest({...newRequest, quantity: e.target.value})}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
            min="1"
            required
          />
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: '#007bff', 
            color: 'white', 
            border: 'none', 
            padding: '10px 20px', 
            borderRadius: '4px', 
            cursor: 'pointer' 
          }}
        >
          Submit Request
        </button>
      </form>

      <h2>Current Requests</h2>
      {requests.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No requests found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {requests.map(request => {
            const part = parts.find(p => p.id === request.partId);
            return (
              <div 
                key={request.id} 
                style={{ 
                  padding: '15px', 
                  border: '1px solid #ddd', 
                  borderRadius: '8px', 
                  display: 'flex', 
                  justifyContent: 'space-between', 
                  alignItems: 'center' 
                }}
              >
                <div>
                  <strong>{part?.name || 'Unknown Part'}</strong> - Quantity: {request.quantity}
                  <br />
                  Status: <span style={{ textTransform: 'capitalize' }}>{request.status}</span>
                </div>
                <div>
                  <span style={{ marginRight: '10px' }}>
                    {request.status === 'pending' && 'Pending'}
                    {request.status === 'approved' && 'Approved'}
                    {request.status === 'rejected' && 'Rejected'}
                  </span>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
"}

