  getAllReminders: async () => [
    { id: 1, petName: "Buddy", careType: "Vaccination", date: "2023-12-01", notes: "Annual checkup" },
    { id: 2, petName: "Luna", careType: "Grooming", date: "2023-12-05", notes: "Full bath" }
  ],
  getReminderById: async (id: number) => {
    const reminders = await mockDatabase.getAllReminders();
    return reminders.find(r => r.id === id) || null;
  },
  createReminder: async (reminder: any) => {
    const reminders = await mockDatabase.getAllReminders();
    const newId = reminders.length > 0 ? Math.max(...reminders.map(r => r.id)) + 1 : 1;
    return { id: newId, ...reminder };
  },
  updateReminder: async (id: number, updatedFields: any) => {
    const reminders = await mockDatabase.getAllReminders();
    const index = reminders.findIndex(r => r.id === id);
    if (index === -1) return null;
    reminders[index] = { ...reminders[index], ...updatedFields };
    return reminders[index];
  },
  deleteReminder: async (id: number) => {
    const reminders = await mockDatabase.getAllReminders();
    const index = reminders.findIndex(r => r.id === id);
    if (index === -1) return false;
    reminders.splice(index, 1);
    return true;
  }
};

// GET /reminders - List all reminders
router.get("/reminders", async (req: Request, res: Response) => {
  try {
    const reminders = await mockDatabase.getAllReminders();
    res.json(reminders);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reminders" });
  }
});

// GET /reminders/:id - Get a specific reminder by ID
router.get("/reminders/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reminder ID" });
    }

    const reminder = await mockDatabase.getReminderById(id);
    if (!reminder) {
      return res.status(404).json({ error: "Reminder not found" });
    }

    res.json(reminder);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch reminder" });
  }
});

// POST /reminders - Create a new reminder
router.post("/reminders", async (req: Request, res: Response) => {
  try {
    const { petName, careType, date, notes } = req.body;

    if (!petName || !careType || !date) {
      return res.status(400).json({ error: "Missing required fields: petName, careType, date" });
    }

    const newReminder = await mockDatabase.createReminder({
      petName,
      careType,
      date,
      notes: notes || ""
    });

    res.status(201).json(newReminder);
  } catch (error) {
    res.status(500).json({ error: "Failed to create reminder" });
  }
});

// PUT /reminders/:id - Update an existing reminder
router.put("/reminders/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reminder ID" });
    }

    const { petName, careType, date, notes } = req.body;

    const updatedReminder = await mockDatabase.updateReminder(id, {
      petName,
      careType,
      date,
      notes: notes || ""
    });

    if (!updatedReminder) {
      return res.status(404).json({ error: "Reminder not found" });
    }

    res.json(updatedReminder);
  } catch (error) {
    res.status(500).json({ error: "Failed to update reminder" });
  }
});

// DELETE /reminders/:id - Delete a reminder
router.delete("/reminders/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid reminder ID" });
    }

    const deleted = await mockDatabase.deleteReminder(id);

    if (!deleted) {
      return res.status(404).json({ error: "Reminder not found" });
    }

    res.json({ message: "Reminder deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete reminder" });
  }
});
"}

