{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  { id: 1, username: "pharmacist1", password: "pass123", role: "pharmacist" },
  { id: 2, username: "manager1", password: "pass456", role: "manager" },
  { id: 3, username: "admin1", password: "pass789", role: "admin" }
];

// Mock session storage
const sessions = new Map<string, { userId: number; role: string; expiresAt: Date }>();

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate session token
  const token = Math.random().toString(36).substring(2, 15);
  const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000); // 24 hours

  sessions.set(token, {
    userId: user.id,
    role: user.role,
    expiresAt
  });

  return res.status(200).json({
    token,
    user: {
      id: user.id,
      username: user.username,
      role: user.role
    }
  });
});

// Logout endpoint
router.post("/logout", (req: Request, res: Response) => {
  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    return res.status(400).json({ error: "Token is required" });
  }

  if (!sessions.has(token)) {
    return res.status(401).json({ error: "Invalid token" });
  }

  sessions.delete(token);

  return res.status(200).json({ message: "Logged out successfully" });
});

// Middleware to verify session
const authenticate = (req: Request, res: Response, next: () => void) => {
  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "Authorization token required" });
  }

  const session = sessions.get(token);

  if (!session) {
    return res.status(401).json({ error: "Invalid or expired token" });
  }

  // Check if session has expired
  if (new Date() > session.expiresAt) {
    sessions.delete(token);
    return res.status(401).json({ error: "Session expired" });
  }

  // Attach user info to request
  (req as any).user = {
    id: session.userId,
    role: session.role
  };

  next();
};

// Role-based access control middleware
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: () => void) => {
    const userRole = (req as any).user?.role;

    if (!userRole || !roles.includes(userRole)) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }

    next();
  };
};

// Protected route example - get user profile
router.get("/profile", authenticate, (req: Request, res: Response) => {
  const user = (req as any).user;

  const userData = users.find(u => u.id === user.id);

  if (!userData) {
    return res.status(404).json({ error: "User not found" });
  }

  return res.status(200).json({
    id: userData.id,
    username: userData.username,
    role: userData.role
  });
});

// Protected route example - get all users (admin only)
router.get("/users", authenticate, authorize(["admin"]), (req: Request, res: Response) => {
  return res.status(200).json(users);
});
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check authentication for POST /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "JWT secret not configured" });
    return;
  }

  const token = req.headers.authorization?.split(" ")[1];

  if (!token) {
    res.status(401).json({ error: "Authorization token required" });
    return;
  }

  try {
    // Simple verification of token format (base64url encoded)
    const [header, payload, signature] = token.split(".");

    if (!header || !payload || !signature) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(signature, "base64url"),
      Buffer.from(expectedSignature, "base64url")
    );

    if (!isValid) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // If we get here, token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}
"}

