{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./mileage_log.db");

interface MileageEntry {
  id: number;
  trip_id: string;
  date: string;
  miles: number;
  purpose: string;
  tax_year: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS mileage_entries (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    trip_id TEXT NOT NULL,
    date TEXT NOT NULL,
    miles INTEGER NOT NULL,
    purpose TEXT NOT NULL,
    tax_year INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllEntries(): MileageEntry[] {
  const stmt = db.prepare("SELECT * FROM mileage_entries");
  return stmt.all() as unknown as MileageEntry[];
}

export function getEntryById(id: number): MileageEntry | undefined {
  const stmt = db.prepare("SELECT * FROM mileage_entries WHERE id = ?");
  return stmt.get(id) as unknown as MileageEntry | undefined;
}

export function insertEntry(entry: Omit<MileageEntry, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO mileage_entries (trip_id, date, miles, purpose, tax_year) VALUES (?, ?, ?, ?, ?)"
  );
  const result = stmt.run(entry.trip_id, entry.date, entry.miles, entry.purpose, entry.tax_year);
  return Number(result.lastInsertRowid);
}

export function updateEntry(id: number, entry: Partial<Omit<MileageEntry, "id">>): boolean {
  const fields = [];
  const values = [];

  if (entry.trip_id !== undefined) {
    fields.push("trip_id = ?");
    values.push(entry.trip_id);
  }

  if (entry.date !== undefined) {
    fields.push("date = ?");
    values.push(entry.date);
  }

  if (entry.miles !== undefined) {
    fields.push("miles = ?");
    values.push(entry.miles);
  }

  if (entry.purpose !== undefined) {
    fields.push("purpose = ?");
    values.push(entry.purpose);
  }

  if (entry.tax_year !== undefined) {
    fields.push("tax_year = ?");
    values.push(entry.tax_year);
  }

  if (fields.length === 0) return false;

  values.push(id);

  const sql = `UPDATE mileage_entries SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);

  return true;
}

export function deleteEntry(id: number): boolean {
  const stmt = db.prepare("DELETE FROM mileage_entries WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

// Insert sample data if table is empty
if (getAllEntries().length === 0) {
  const sampleEntries = [
