{"code":"import { Router, type Request, type Response } from "express";
import { 
  getAllRepairs,
  getRepairById,
  insertRepair,
  updateRepair,
  deleteRepair
} from "../db/repairs-table";

export const router = Router();

// Get all repairs
router.get("/", (req: Request, res: Response) => {
  try {
    const repairs = getAllRepairs();
    res.json(repairs);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch repairs" });
  }
});

// Get a repair by ID
router.get("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid repair ID" });
    }

    const repair = getRepairById(id);
    if (!repair) {
      return res.status(404).json({ error: "Repair not found" });
    }

    res.json(repair);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch repair" });
  }
});

// Create a new repair
router.post("/", (req: Request, res: Response) => {
  try {
    const { bikeId, partName, labourTime, mechanicId } = req.body;

    if (!bikeId || !partName || !labourTime || !mechanicId) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const newId = insertRepair(bikeId, partName, labourTime, mechanicId);
    const createdRepair = getRepairById(newId);

    if (!createdRepair) {
      return res.status(500).json({ error: "Failed to create repair" });
    }

    res.status(201).json(createdRepair);
  } catch (error) {
    res.status(500).json({ error: "Failed to create repair" });
  }
});

// Update a repair
router.put("/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid repair ID" });
    }

    const { bikeId, partName, labourTime, mechanicId } = req.body;

    if (!bikeId || !partName || !labourTime || !mechanicId) {
      return res.status(400).json({ error: "Missing required fields" });
    }

    const updatedRows = updateRepair(id, bikeId, partName, labourTime, mechanicId);

    if (updatedRows === 0) {
      return res.status(404).json({ error: "Repair not found" });
    }

    const updatedRepair = getRepairById(id);

    if (!updatedRepair) {
      return res.status(500).json({ error: "Failed to update repair" });
    }

    res.json(updatedRepair);
