{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function decodeJwt(token: string): Record<string, unknown> | null {
  try {
    const payload = token.split('.')[1];
    const decoded = Buffer.from(payload, 'base64').toString('utf-8');
    return JSON.parse(decoded);
  } catch {
    return null;
  }
}

function verifySignature(token: string, secret: string): boolean {
  const [header, payload, signature] = token.split('.');

  if (!header || !payload || !signature) {
    return false;
  }

  const expectedSignature = createHmac('sha256', secret)
    .update(`${header}.${payload}`)
    .digest('base64url');

  const actualSignature = signature;

  try {
    return timingSafeEqual(
      Buffer.from(actualSignature, 'base64url'),
      Buffer.from(expectedSignature, 'base64url')
    );
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check authentication for POST requests to /api/journal
  if (!(req.method === 'POST' && req.path === '/api/journal')) {
    next();
    return;
  }

  if (!JWT_SECRET) {
    res.status(500).json({ error: 'Server configuration error' });
    return;
  }

  const authHeader = req.header('Authorization');

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Missing or invalid authorization header' });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  if (!token) {
    res.status(401).json({ error: 'Missing token' });
    return;
  }

  const decoded = decodeJwt(token);

  if (!decoded) {
    res.status(401).json({ error: 'Invalid token format' });
    return;
  }

  if (!verifySignature(token, JWT_SECRET)) {
    res.status(401).json({ error: 'Invalid token signature' });
    return;
  }

  // Token is valid, proceed to next middleware/route handler
  next();
}
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const measurements = [
  { id: 1, customerId: 1, chest: 36, waist: 30, hips: 38, sleeve: 22, length: 32 },
  { id: 2, customerId: 2, chest: 40, waist: 34, hips: 42, sleeve: 24, length: 34 }
];

const findMeasurementById = (id: number) => {
  return measurements.find(m => m.id === id);
};

const createMeasurement = (measurement: any) => {
  const newId = measurements.length > 0 ? Math.max(...measurements.map(m => m.id)) + 1 : 1;
  const newMeasurement = { ...measurement, id: newId };
  measurements.push(newMeasurement);
  return newMeasurement;
};

const updateMeasurement = (id: number, updatedData: any) => {
  const index = measurements.findIndex(m => m.id === id);
  if (index !== -1) {
    measurements[index] = { ...measurements[index], ...updatedData };
    return measurements[index];
  }
  return null;
};

const deleteMeasurement = (id: number) => {
  const index = measurements.findIndex(m => m.id === id);
  if (index !== -1) {
    measurements.splice(index, 1);
    return true;
  }
  return false;
};

// GET /measurements - List all measurements
router.get("/", (req: Request, res: Response) => {
  res.json(measurements);
});

// GET /measurements/:id - Get a specific measurement by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid measurement ID" });
  }

  const measurement = findMeasurementById(id);
  if (!measurement) {
    return res.status(404).json({ error: "Measurement not found" });
  }

  res.json(measurement);
});

// POST /measurements - Create a new measurement
router.post("/", (req: Request, res: Response) => {
  const { customerId, chest, waist, hips, sleeve, length } = req.body;

  // Basic validation
  if (!customerId || !chest || !waist || !hips || !sleeve || !length) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const newMeasurement = createMeasurement({ customerId, chest, waist, hips, sleeve, length });
  res.status(201).json(newMeasurement);
});

// PUT /measurements/:id - Update an existing measurement
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid measurement ID" });
  }

  const { customerId, chest, waist, hips, sleeve, length } = req.body;

  const updatedMeasurement = updateMeasurement(id, { customerId, chest, waist, hips, sleeve, length });

  if (!updatedMeasurement) {
    return res.status(404).json({ error: "Measurement not found" });
  }

  res.json(updatedMeasurement);
});

// DELETE /measurements/:id - Delete a measurement
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid measurement ID" });
  }

  const deleted = deleteMeasurement(id);

  if (!deleted) {
    return res.status(404).json({ error: "Measurement not found" });
  }

  res.json({ message: "Measurement deleted successfully" });
});
