{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockPrescriptions = [
  { id: 1, patientId: "123", medication: "Ibuprofen", dosage: "200mg", frequency: "twice daily", startDate: "2023-01-01", endDate: "2023-01-15" },
  { id: 2, patientId: "123", medication: "Amoxicillin", dosage: "500mg", frequency: "three times daily", startDate: "2023-02-01", endDate: "2023-02-10" },
  { id: 3, patientId: "456", medication: "Lisinopril", dosage: "10mg", frequency: "once daily", startDate: "2023-03-01", endDate: "2023-03-31" }
];

const findPrescriptionById = (id: number) => {
  return mockPrescriptions.find(prescription => prescription.id === id);
};

const createPrescription = (prescriptionData: any) => {
  const newPrescription = {
    id: mockPrescriptions.length + 1,
    ...prescriptionData
  };
  mockPrescriptions.push(newPrescription);
  return newPrescription;
};

const updatePrescription = (id: number, updatedData: any) => {
  const index = mockPrescriptions.findIndex(prescription => prescription.id === id);
  if (index !== -1) {
    mockPrescriptions[index] = { ...mockPrescriptions[index], ...updatedData };
    return mockPrescriptions[index];
  }
  return null;
};

const deletePrescription = (id: number) => {
  const index = mockPrescriptions.findIndex(prescription => prescription.id === id);
  if (index !== -1) {
    mockPrescriptions.splice(index, 1);
    return true;
  }
  return false;
};

// GET /api/prescriptions - List all prescriptions
router.get("/prescriptions", (req: Request, res: Response) => {
  res.json(mockPrescriptions);
});

// GET /api/prescriptions/:id - Get a specific prescription by ID
router.get("/prescriptions/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const prescription = findPrescriptionById(id);

  if (!prescription) {
    return res.status(404).json({ error: "Prescription not found" });
  }

  res.json(prescription);
});

// POST /api/prescriptions - Create a new prescription
router.post("/prescriptions", (req: Request, res: Response) => {
  const { patientId, medication, dosage, frequency, startDate, endDate } = req.body;

  // Basic validation
  if (!patientId || !medication || !dosage || !frequency || !startDate || !endDate) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const newPrescription = createPrescription({
    patientId,
    medication,
    dosage,
    frequency,
    startDate,
    endDate
  });

  res.status(201).json(newPrescription);
});

// PUT /api/prescriptions/:id - Update an existing prescription
router.put("/prescriptions/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { patientId, medication, dosage, frequency, startDate, endDate } = req.body;

  // Basic validation
  if (!patientId || !medication || !dosage || !frequency || !startDate || !endDate) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const updatedPrescription = updatePrescription(id, {
    patientId,
    medication,
    dosage,
    frequency,
    startDate,
    endDate
  });

  if (!updatedPrescription) {
    return res.status(404).json({ error: "Prescription not found" });
  }

  res.json(updatedPrescription);
});

// DELETE /api/prescriptions/:id - Delete a prescription
router.delete("/prescriptions/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const deleted = deletePrescription(id);

  if (!deleted) {
    return res.status(404).json({ error: "Prescription not found" });
  }

  res.json({ message: "Prescription deleted successfully" });
});

// GET /api/prescriptions/search?patientId=123 - Search prescriptions by patient ID
router.get("/prescriptions/search", (req: Request, res: Response) => {
  const patientId = req.query.patientId as string;

  if (!patientId) {
    return res.status(400).json({ error: "Patient ID is required" });
  }

  const filteredPrescriptions = mockPrescriptions.filter(prescription =>
    prescription.patientId === patientId
  );

  res.json(filteredPrescriptions);
});
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;

  if (!jwtSecret) {
    res.status(500).json({ error: "Server configuration error: JWT_SECRET not set" });
    return;
  }

  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  try {
    // Basic token structure validation
    const parts = token.split(".");
    if (parts.length !== 3) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    const [header, payload, signature] = parts;

    // Verify signature using HMAC-SHA256
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token signature" });
      return;
    }

    // If we get here, the token is valid
    next();
  } catch (error) {
    res.status(401).json({ error: "Token verification failed" });
  }
}
"}

