export const router = Router();

// Mock user database
const users = [
  { id: 1, username: "admin", password: "admin123", role: "administrator" },
  { id: 2, username: "staff", password: "staff123", role: "staff" }
];

// Mock authentication middleware
const authenticate = (req: Request, res: Response, next: Function) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  const token = authHeader.substring(7);
  // In a real app, you'd verify the JWT token here
  // For this mock, we'll just check if it matches a known token
  if (token !== "valid-token") {
    return res.status(401).json({ error: "Invalid token" });
  }

  next();
};

// Role-based authorization middleware
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: Function) => {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      return res.status(401).json({ error: "Unauthorized" });
    }

    const token = authHeader.substring(7);
    // In a real app, decode the JWT to get user role
    // For this mock, we'll assume the token corresponds to admin role
    if (token === "valid-token") {
      const userRole = "administrator"; // Mock user role
      if (!roles.includes(userRole)) {
        return res.status(403).json({ error: "Forbidden" });
      }
      next();
    } else {
      return res.status(401).json({ error: "Invalid token" });
    }
  };
};

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // In a real app, generate a JWT token here
  // For this mock, we'll return a mock token
  return res.json({ token: "valid-token", role: user.role });
});

// Get current user info
router.get("/me", authenticate, (req: Request, res: Response) => {
  // In a real app, extract user info from the JWT token
  // For this mock, we'll return a mock user
  return res.json({ username: "admin", role: "administrator" });
});

// Admin-only endpoint example
