{"code":"import { useEffect, useState } from "react";

interface MenuItem {
  id: number;
  date: string;
  mealType: 'breakfast' | 'lunch' | 'dinner';
  foodItems: string[];
}

export function MenuManagement() {
  const [menus, setMenus] = useState<MenuItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Form state
  const [newMenu, setNewMenu] = useState({
    date: '',
    mealType: 'breakfast' as 'breakfast' | 'lunch' | 'dinner',
    foodItems: ''
  });

  // Fetch menus on component mount
  useEffect(() => {
    fetchMenus();
  }, []);

  const fetchMenus = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/menus');
      if (!response.ok) {
        throw new Error('Failed to fetch menus');
      }
      const data = await response.json();
      setMenus(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setNewMenu(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleFoodItemsChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setNewMenu(prev => ({
      ...prev,
      foodItems: e.target.value
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch('/api/menus', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          date: newMenu.date,
          mealType: newMenu.mealType,
          foodItems: newMenu.foodItems.split(',').map(item => item.trim())
        })
      });

      if (!response.ok) {
        throw new Error('Failed to add menu');
      }

      // Reset form and reload data
      setNewMenu({
        date: '',
        mealType: 'breakfast',
        foodItems: ''
      });
      fetchMenus();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Menu Management</h1>

      <div style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <h2>Add New Menu</h2>
        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: '15px' }}>
            <label>Date: </label>
            <input
              type="date"
              name="date"
              value={newMenu.date}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px', marginTop: '5px' }}
              required
            />
          </div>

          <div style={{ marginBottom: '15px' }}>
            <label>Meal Type: </label>
            <select
              name="mealType"
              value={newMenu.mealType}
              onChange={handleInputChange}
              style={{ width: '100%', padding: '8px', marginTop: '5px' }}
            >
              <option value="breakfast">Breakfast</option>
              <option value="lunch">Lunch</option>
              <option value="dinner">Dinner</option>
            </select>
          </div>

          <div style={{ marginBottom: '15px' }}>
            <label>Food Items (comma separated): </label>
            <textarea
              name="foodItems"
              value={newMenu.foodItems}
              onChange={handleFoodItemsChange}
              style={{ width: '100%', padding: '8px', marginTop: '5px', height: '80px' }}
              placeholder="e.g., Oatmeal, Eggs, Toast"
              required
            />
          </div>

          <button 
            type="submit" 
            style={{ 
              backgroundColor: '#007bff', 
              color: 'white', 
              border: 'none', 
              padding: '10px 20px', 
              borderRadius: '4px', 
              cursor: 'pointer' 
            }}
          >
            Add Menu
          </button>
        </form>
      </div>

      <h2>Current Menus</h2>
      {menus.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No menus found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {menus.map(menu => (
            <div 
              key={menu.id} 
              style={{ 
                border: '1px solid #ddd', 
                borderRadius: '8px', 
                padding: '15px', 
                backgroundColor: '#f9f9f9' 
              }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                  <strong>{menu.date}</strong> - {menu.mealType.charAt(0).toUpperCase() + menu.mealType.slice(1)}
                </div>
              </div>
              <div style={{ marginTop: '10px' }}>
                <strong>Food Items:</strong>
                <ul style={{ margin: '5px 0 0 20px' }}>
                  {menu.foodItems.map((item, index) => (
                    <li key={index}>{item}</li>
                  ))}
                </ul>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

