{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockInventoryMovements = [
  {
    id: "1",
    type: "incoming",
    materialId: "mat1",
    quantity: 100,
    timestamp: "2023-05-15T10:00:00Z",
    userId: "user1"
  },
  {
    id: "2",
    type: "outgoing",
    materialId: "mat1",
    quantity: 25,
    timestamp: "2023-05-16T14:30:00Z",
    userId: "user2"
  }
];

const findMovementById = (id: string) => {
  return mockInventoryMovements.find(movement => movement.id === id);
};

const createMovement = (movement: any) => {
  const newMovement = {
    id: `${mockInventoryMovements.length + 1}`,
    ...movement
  };
  mockInventoryMovements.push(newMovement);
  return newMovement;
};

const updateMovement = (id: string, updatedMovement: any) => {
  const index = mockInventoryMovements.findIndex(m => m.id === id);
  if (index !== -1) {
    mockInventoryMovements[index] = { ...mockInventoryMovements[index], ...updatedMovement };
    return mockInventoryMovements[index];
  }
  return null;
};

const deleteMovement = (id: string) => {
  const index = mockInventoryMovements.findIndex(m => m.id === id);
  if (index !== -1) {
    mockInventoryMovements.splice(index, 1);
    return true;
  }
  return false;
};

// GET /inventory-movements - List all inventory movements
router.get("/inventory-movements", (req: Request, res: Response) => {
  res.json(mockInventoryMovements);
});

// GET /inventory-movements/:id - Get a specific inventory movement by ID
router.get("/inventory-movements/:id", (req: Request, res: Response) => {
  const movement = findMovementById(req.params.id);
  if (!movement) {
    return res.status(404).json({ error: "Inventory movement not found" });
  }
  res.json(movement);
});

// POST /inventory-movements - Create a new inventory movement
router.post("/inventory-movements", (req: Request, res: Response) => {
  const { type, materialId, quantity, timestamp, userId } = req.body;

  // Validate required fields
  if (!type || !materialId || !quantity || !timestamp || !userId) {
    return res.status(400).json({ error: "Missing required fields: type, materialId, quantity, timestamp, userId" });
  }

  // Validate type
  if (!["incoming", "outgoing", "adjustment"].includes(type)) {
    return res.status(400).json({ error: "Invalid type. Must be 'incoming', 'outgoing', or 'adjustment'" });
  }

  // Validate quantity
  if (typeof quantity !== "number" || quantity <= 0) {
    return res.status(400).json({ error: "Quantity must be a positive number" });
  }

  // Validate timestamp
  if (isNaN(Date.parse(timestamp))) {
    return res.status(400).json({ error: "Invalid timestamp format" });
  }

  const newMovement = createMovement({
    type,
    materialId,
    quantity,
    timestamp,
    userId
  });

  res.status(201).json(newMovement);
});

// PUT /inventory-movements/:id - Update an existing inventory movement
router.put("/inventory-movements/:id", (req: Request, res: Response) => {
  const { type, materialId, quantity, timestamp, userId } = req.body;

  // Validate required fields
  if (!type || !materialId || !quantity || !timestamp || !userId) {
    return res.status(400).json({ error: "Missing required fields: type, materialId, quantity, timestamp, userId" });
  }

  // Validate type
  if (!["incoming", "outgoing", "adjustment"].includes(type)) {
    return res.status(400).json({ error: "Invalid type. Must be 'incoming', 'outgoing', or 'adjustment'" });
  }

  // Validate quantity
  if (typeof quantity !== "number" || quantity <= 0) {
    return res.status(400).json({ error: "Quantity must be a positive number" });
  }

  // Validate timestamp
  if (isNaN(Date.parse(timestamp))) {
    return res.status(400).json({ error: "Invalid timestamp format" });
  }

  const updatedMovement = updateMovement(req.params.id, {
    type,
    materialId,
    quantity,
    timestamp,
    userId
  });

  if (!updatedMovement) {
    return res.status(404).json({ error: "Inventory movement not found" });
  }

  res.json(updatedMovement);
});

// DELETE /inventory-movements/:id - Delete an inventory movement
router.delete("/inventory-movements/:id", (req: Request, res: Response) => {
  const deleted = deleteMovement(req.params.id);

  if (!deleted) {
    return res.status(404).json({ error: "Inventory movement not found" });
  }

  res.json({ message: "Inventory movement deleted successfully" });
});
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./walks.db");

interface WalkRow {
  id: number;
  ownerId: number;
  walkerId: number;
  date: string;
  status: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS walks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ownerId INTEGER NOT NULL,
    walkerId INTEGER NOT NULL,
    date TEXT NOT NULL,
    status TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllWalks(): WalkRow[] {
  const stmt = db.prepare("SELECT * FROM walks");
  return stmt.all() as unknown as WalkRow[];
}

export function getWalkById(id: number): WalkRow | undefined {
  const stmt = db.prepare("SELECT * FROM walks WHERE id = ?");
  return stmt.get(id) as unknown as WalkRow | undefined;
}

export function insertWalk(ownerId: number, walkerId: number, date: string, status: string): number {
  const stmt = db.prepare(
    "INSERT INTO walks (ownerId, walkerId, date, status) VALUES (?, ?, ?, ?)"
  );
  const result = stmt.run(ownerId, walkerId, date, status);
  return Number(result.lastInsertRowid);
}

export function updateWalk(id: number, ownerId: number, walkerId: number, date: string, status: string): void {
  const stmt = db.prepare(
    "UPDATE walks SET ownerId = ?, walkerId = ?, date = ?, status = ? WHERE id = ?"
  );
  stmt.run(ownerId, walkerId, date, status, id);
}

export function deleteWalk(id: number): void {
  const stmt = db.prepare("DELETE FROM walks WHERE id = ?");
  stmt.run(id);
}

// Insert sample data if table is empty
if (getAllWalks().length === 0) {
  insertWalk(1, 2, "2023-06-15", "scheduled");
  insertWalk(3, 1, "2023-06-16", "completed");
  insertWalk(2, 3, "2023-06-17", "pending");
  insertWalk(4, 2, "2023-06-18", "scheduled");
  insertWalk(5, 1, "2023-06-19", "pending");
}
"}

