{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST, PUT, PATCH, DELETE requests
  if (!['POST', 'PUT', 'PATCH', 'DELETE'].includes(req.method)) {
    next();
    return;
  }

  // Validate and sanitize input data
  if (req.body) {
    sanitizeBody(req.body);
  }

  // Validate query parameters if present
  if (req.query) {
    sanitizeQuery(req.query);
  }

  next();
}

function sanitizeBody(body: any): void {
  if (typeof body === 'object' && body !== null) {
    for (const [key, value] of Object.entries(body)) {
      if (typeof value === 'string') {
        // Basic XSS protection by escaping HTML characters
        body[key] = value
          .replace(/&/g, '&amp;')
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;')
          .replace(/"/g, '&quot;')
          .replace(/'/g, '&#x27;');
      } else if (typeof value === 'object') {
        sanitizeBody(value);
      }
    }
  }
}

function sanitizeQuery(query: Record<string, any>): void {
  for (const [key, value] of Object.entries(query)) {
    if (typeof value === 'string') {
      // Sanitize query parameters
      query[key] = value
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#x27;');
    }
  }
}
"}

