      next();
    } else {
      res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    }
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

// Helper function to extract role from token (simplified for example)
function getUserRoleFromToken(token: string): string | null {
  // In a real implementation, this would decode the JWT and return the role
  // For demo purposes, we'll simulate role extraction
  // This is a placeholder implementation
  return token.includes("admin") ? "admin" : token.includes("staff") ? "staff" : null;
}
