{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./time-tracker.db");

interface ProjectRow {
  id: number;
  name: string;
  description: string;
  client_name: string;
  client_email: string;
  hourly_rate: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    description TEXT,
    client_name TEXT NOT NULL,
    client_email TEXT NOT NULL,
    hourly_rate REAL NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllProjects(): ProjectRow[] {
  const stmt = db.prepare("SELECT * FROM projects");
  return stmt.all() as unknown as ProjectRow[];
}

export function getProjectById(id: number): ProjectRow | undefined {
  const stmt = db.prepare("SELECT * FROM projects WHERE id = ?");
  return stmt.get(id) as unknown as ProjectRow | undefined;
}

export function insertProject(project: Omit<ProjectRow, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO projects (name, description, client_name, client_email, hourly_rate) VALUES (?, ?, ?, ?, ?)"
  );
  const result = stmt.run(
    project.name,
    project.description,
    project.client_name,
    project.client_email,
    project.hourly_rate
  );
  return Number(result.lastInsertRowid);
}

export function updateProject(id: number, project: Partial<Omit<ProjectRow, "id">>): boolean {
  const fields = [];
  const values = [];

  if (project.name !== undefined) {
    fields.push("name = ?");
    values.push(project.name);
  }

  if (project.description !== undefined) {
    fields.push("description = ?");
    values.push(project.description);
  }

  if (project.client_name !== undefined) {
    fields.push("client_name = ?");
    values.push(project.client_name);
  }

  if (project.client_email !== undefined) {
    fields.push("client_email = ?");
    values.push(project.client_email);
  }

  if (project.hourly_rate !== undefined) {
    fields.push("hourly_rate = ?");
    values.push(project.hourly_rate);
  }

  if (fields.length === 0) return false;

  values.push(id);

  const sql = `UPDATE projects SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);

  return true;
}

export function deleteProject(id: number): boolean {
  const stmt = db.prepare("DELETE FROM projects WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

