    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid server ID" });
    }

    const { name, ownerId, config } = req.body;

    if (!name || !ownerId || !config) {
      return res.status(400).json({ error: "Name, owner ID, and config are required" });
    }

    const existingServer = getServerById(id);
    if (!existingServer) {
      return res.status(404).json({ error: "Server not found" });
    }

    updateServer(id, name, ownerId, config);
    const updatedServer = getServerById(id);

    if (!updatedServer) {
      return res.status(500).json({ error: "Failed to retrieve updated server" });
    }

    return res.json(updatedServer);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update server" });
  }
});

// DELETE /servers/:id - Delete a server
router.delete("/servers/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid server ID" });
    }

    const existingServer = getServerById(id);
    if (!existingServer) {
      return res.status(404).json({ error: "Server not found" });
    }

    deleteServer(id);
    return res.json({ message: "Server deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete server" });
  }
});
