{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user data storage
const users = [
  { id: "1", email: "client@example.com", password: "hashed-password-1", role: "client", profile: { name: "John Doe", bio: "Client looking for freelancers" } },
  { id: "2", email: "freelancer@example.com", password: "hashed-password-2", role: "freelancer", profile: { name: "Jane Smith", skills: ["web development", "design"] } }
];

// Helper to find user by email
const findUserByEmail = (email: string) => {
  return users.find(user => user.email === email);
};

// Helper to find user by ID
const findUserById = (id: string) => {
  return users.find(user => user.id === id);
};

// Authentication middleware
const authenticate = (req: Request, res: Response, next: Function) => {
  // In a real app, this would check JWT token or session
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized" });
  }
  next();
};

// Role-based access control middleware
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: Function) => {
    // In a real app, this would extract role from token
    const userRole = "client"; // Mocked for demo purposes
    if (!roles.includes(userRole)) {
      return res.status(403).json({ error: "Forbidden" });
    }
    next();
  };
};

// GET /users - List all users
router.get("/users", (req: Request, res: Response) => {
  res.json(users);
});

// GET /users/:id - Get user by ID
router.get("/users/:id", (req: Request, res: Response) => {
  const user = findUserById(req.params.id);
  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }
  res.json(user);
});

// POST /users/register - Register a new user
router.post("/users/register", (req: Request, res: Response) => {
  const { email, password, role, profile } = req.body;

  if (!email || !password || !role) {
    return res.status(400).json({ error: "Email, password, and role are required" });
  }

  const existingUser = findUserByEmail(email);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  const newUser = {
    id: String(users.length + 1),
    email,
    password,
    role,
    profile: profile || {}
  };

  users.push(newUser);
  res.status(201).json(newUser);
});

// PUT /users/:id - Update user profile
router.put("/users/:id", authenticate, (req: Request, res: Response) => {
  const userIndex = users.findIndex(user => user.id === req.params.id);
  if (userIndex === -1) {
    return res.status(404).json({ error: "User not found" });
  }

  const { profile } = req.body;
  if (!profile) {
    return res.status(400).json({ error: "Profile is required" });
  }

  users[userIndex].profile = { ...users[userIndex].profile, ...profile };
  res.json(users[userIndex]);
});

// DELETE /users/:id - Delete user
router.delete("/users/:id", authenticate, (req: Request, res: Response) => {
  const userIndex = users.findIndex(user => user.id === req.params.id);
  if (userIndex === -1) {
    return res.status(404).json({ error: "User not found" });
  }

  users.splice(userIndex, 1);
  res.json({ message: "User deleted successfully" });
});

// POST /users/login - Login user
router.post("/users/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  const user = findUserByEmail(email);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // In a real app, you'd verify password hash here
  if (user.password !== password) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // In a real app, you'd generate a JWT token here
  res.json({ token: "mock-jwt-token", user: { id: user.id, email: user.email, role: user.role } });
});

// GET /users/profile - Get authenticated user's profile
router.get("/users/profile", authenticate, (req: Request, res: Response) => {
  // In a real app, this would extract user info from token
  const user = findUserById("1"); // Mocked for demo purposes
  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }
  res.json(user.profile);
});
