{"code":"import { useEffect, useState } from "react";

interface DropOffRecord {
  id: number;
  date: string;
  item: string;
  weight: number;
}

export function DropOffList() {
  const [records, setRecords] = useState<DropOffRecord[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const itemsPerPage = 10;

  useEffect(() => {
    fetchDropOffRecords();
  }, [currentPage, searchTerm]);

  const fetchDropOffRecords = async () => {
    try {
      setLoading(true);
      const response = await fetch(
        `/api/drop-offs?page=${currentPage}&limit=${itemsPerPage}&search=${searchTerm}`
      );

      if (!response.ok) {
        throw new Error(`Failed to fetch records: ${response.status}`);
      }

      const data = await response.json();
      setRecords(data.records);
      setTotalPages(data.totalPages);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
    setCurrentPage(1); // Reset to first page when searching
  };

  const handlePageChange = (page: number) => {
    setCurrentPage(page);
  };

  const renderPagination = () => {
    const pages = [];
    for (let i = 1; i <= totalPages; i++) {
      pages.push(
        <button
          key={i}
          onClick={() => handlePageChange(i)}
          style={{
            padding: "8px 12px",
            margin: "0 4px",
            border: "1px solid #ccc",
            borderRadius: "4px",
            backgroundColor: currentPage === i ? "#007bff" : "white",
            color: currentPage === i ? "white" : "black",
            cursor: "pointer"
          }}
        >
          {i}
        </button>
      );
    }

    return (
      <div style={{
        display: "flex",
        justifyContent: "center",
        marginTop: "20px",
        flexWrap: "wrap"
      }}>
        {pages}
      </div>
    );
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{
      maxWidth: "800px",
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
    }}>
      <h1 style={{ textAlign: "center" }}>Drop-off Records</h1>

      <div style={{ marginBottom: "20px" }}>
        <input
          type="text"
          placeholder="Search records..."
          value={searchTerm}
          onChange={handleSearchChange}
          style={{
            width: "100%",
            padding: "10px",
            borderRadius: "4px",
            border: "1px solid #ccc",
            fontSize: "16px"
          }}
        />
      </div>

      {records.length === 0 ? (
        <div style={{ textAlign: "center", padding: "20px" }}>
          No drop-off records found.
        </div>
      ) : (
        <>
          <div style={{
            display: "grid",
            gap: "16px",
            gridTemplateColumns: "repeat(auto-fill, minmax(300px, 1fr))"
          }}>
            {records.map(record => (
              <div
                key={record.id}
                style={{
                  border: "1px solid #ddd",
                  borderRadius: "8px",
                  padding: "16px",
                  boxShadow: "0 2px 4px rgba(0,0,0,0.1)"
                }}
