{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check ownership for POST requests to the export endpoint
  if (req.method !== "POST" || req.path !== "/export") {
    next();
    return;
  }

  // Check if the user is the owner
  const owner = req.headers["x-owner"];
  const expectedOwner = process.env.OWNER_ACCOUNT;

  if (!owner || !expectedOwner) {
    res.status(403).json({ error: "Access denied" });
    return;
  }

  // Simple string comparison (in a real app, this might involve more complex logic)
  if (owner !== expectedOwner) {
    res.status(403).json({ error: "Access denied" });
    return;
  }

  next();
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("timesheets.db");

interface TimesheetEntry {
  id: number;
  associateId: number;
  date: string;
  rate: number;
  description: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS timesheets (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    associateId INTEGER NOT NULL,
    date TEXT NOT NULL,
    rate REAL NOT NULL,
    description TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllTimesheetEntries(): TimesheetEntry[] {
  const stmt = db.prepare(`SELECT * FROM timesheets`);
  return stmt.all() as unknown as TimesheetEntry[];
}

export function getTimesheetEntryById(id: number): TimesheetEntry | undefined {
  const stmt = db.prepare(`SELECT * FROM timesheets WHERE id = ?`);
  return stmt.get(id) as unknown as TimesheetEntry | undefined;
}

export function insertTimesheetEntry(
  associateId: number,
  date: string,
  rate: number,
  description: string
): number {
  const stmt = db.prepare(
    `INSERT INTO timesheets (associateId, date, rate, description) VALUES (?, ?, ?, ?)`
  );
  const result = stmt.run(associateId, date, rate, description);
  return Number(result.lastInsertRowid);
}

export function updateTimesheetEntry(
  id: number,
  associateId: number,
  date: string,
  rate: number,
  description: string
): void {
  const stmt = db.prepare(
    `UPDATE timesheets SET associateId = ?, date = ?, rate = ?, description = ? WHERE id = ?`
  );
  stmt.run(associateId, date, rate, description, id);
}

export function deleteTimesheetEntry(id: number): void {
  const stmt = db.prepare(`DELETE FROM timesheets WHERE id = ?`);
  stmt.run(id);
}

