{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockAppointments = [
  { id: "1", patientId: "p1", doctorId: "d1", date: "2023-10-15", time: "10:00", status: "scheduled" },
  { id: "2", patientId: "p1", doctorId: "d2", date: "2023-10-16", time: "14:00", status: "scheduled" },
];

const getAppointments = () => {
  return mockAppointments;
};

const getAppointmentById = (id: string) => {
  return mockAppointments.find(appointment => appointment.id === id);
};

const createAppointment = (appointment: any) => {
  const newAppointment = {
    id: String(mockAppointments.length + 1),
    ...appointment,
    status: "scheduled"
  };
  mockAppointments.push(newAppointment);
  return newAppointment;
};

const updateAppointment = (id: string, updatedFields: any) => {
  const index = mockAppointments.findIndex(appointment => appointment.id === id);
  if (index === -1) return null;

  mockAppointments[index] = { ...mockAppointments[index], ...updatedFields };
  return mockAppointments[index];
};

const deleteAppointment = (id: string) => {
  const index = mockAppointments.findIndex(appointment => appointment.id === id);
  if (index === -1) return false;

  mockAppointments.splice(index, 1);
  return true;
};

// GET /appointments - List all appointments
router.get("/appointments", (req: Request, res: Response) => {
  try {
    const appointments = getAppointments();
    res.json(appointments);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// GET /appointments/:id - Get one appointment by ID
router.get("/appointments/:id", (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    const appointment = getAppointmentById(id);

    if (!appointment) {
      return res.status(404).json({ error: "Appointment not found" });
    }

    res.json(appointment);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// POST /appointments - Create a new appointment
router.post("/appointments", (req: Request, res: Response) => {
  try {
    const { patientId, doctorId, date, time } = req.body;

    if (!patientId || !doctorId || !date || !time) {
      return res.status(400).json({ error: "Missing required fields: patientId, doctorId, date, time" });
    }

    const newAppointment = createAppointment({ patientId, doctorId, date, time });
    res.status(201).json(newAppointment);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// PUT /appointments/:id - Update an existing appointment
router.put("/appointments/:id", (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    const { date, time } = req.body;

    if (!date || !time) {
      return res.status(400).json({ error: "Missing required fields: date, time" });
    }

    const updatedAppointment = updateAppointment(id, { date, time });

    if (!updatedAppointment) {
      return res.status(404).json({ error: "Appointment not found" });
    }

    res.json(updatedAppointment);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// DELETE /appointments/:id - Delete an appointment
router.delete("/appointments/:id", (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    const deleted = deleteAppointment(id);

    if (!deleted) {
      return res.status(404).json({ error: "Appointment not found" });
    }

    res.json({ message: "Appointment deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});
"}

