{"code":"import { Router, type Request, type Response } from "express";
import { ShortUrlRow, insertShortUrl, getShortUrlByCode, updateVisitAnalytics } from "../db/short-urls-table";

export const router = Router();

router.post("/shorten", (req: Request, res: Response) => {
  const { shortCode, targetUrl } = req.body;
  if (typeof shortCode !== "string" || typeof targetUrl !== "string") {
    res.status(400).send("Invalid input");
    return;
  }
  insertShortUrl(shortCode, targetUrl);
  res.status(201).json({ shortCode, targetUrl });
});

router.get("/:shortCode", (req: Request, res: Response) => {
  const shortCode = req.params.shortCode;
  const shortUrl = getShortUrlByCode(shortCode);
  if (!shortUrl) {
    res.status(404).send("Short URL not found");
    return;
  }
  const visitorCountry = req.headers["cf-ipcountry"] as string || "Unknown";
  updateVisitAnalytics(shortCode, visitorCountry);
  res.redirect(shortUrl.targetUrl);
});
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to the emergency access delegation endpoint
  if (req.method !== "POST" || req.path !== "/emergency-access/delegate") {
    next();
    return;
  }

  // Check if the request has a valid authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT secret not configured" });
    return;
  }

  // Simple token validation - in a real implementation, you'd decode and verify
  // the JWT signature using HMAC-SHA256 with the secret
  try {
    // For demonstration purposes, we'll just check if the token matches a
    // predefined expected token (this is not secure in production)
    const expectedToken = createHmac("sha256", secret)
      .update("valid-emergency-access-token")
      .digest("hex");

    const tokenBuffer = Buffer.from(token);
    const expectedBuffer = Buffer.from(expectedToken);

    if (tokenBuffer.length !== expectedBuffer.length || 
        !timingSafeEqual(tokenBuffer, expectedBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token" });
      return;
    }
  } catch (error) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  next();
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to the export endpoint
  if (req.method !== "POST" || req.path !== "/export") {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Basic token structure validation
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  const [header, payload, signature] = parts;

  // Verify signature using HMAC-SHA256
  const expectedSignature = createHmac("sha256", secret)
    .update(`${header}.${payload}`)
    .digest("base64url");

  const actualSignature = signature;

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(actualSignature, "base64url");

    if (timingSafeEqual(expectedBuffer, actualBuffer)) {
      // Signature is valid, check if owner
      const decodedPayload = JSON.parse(Buffer.from(payload, "base64url").toString());

      if (decodedPayload.role === "owner") {
        next();
      } else {
        res.status(403).json({ error: "Forbidden: Owner access required" });
      }
    } else {
      res.status(401).json({ error: "Invalid token" });
    }
  } catch (err) {
    res.status(401).json({ error: "Invalid token" });
  }
}
"}

