              border: "1px solid #ddd",
              borderRadius: "8px",
              padding: "15px",
              backgroundColor: "#f9f9f9",
            }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <strong>{walk.date}</strong> at {walk.time} ({walk.duration} mins)
                  <br />
                  Status: {walk.status}
                </div>
                <div style={{ display: "flex", gap: "5px" }}>
                  {walk.status === "pending" && (
                    <>
                      <button
                        onClick={() => handleAccept(walk.id)}
                        style={{
                          backgroundColor: "#28a745",
                          color: "white",
                          border: "none",
                          padding: "5px 10px",
                          borderRadius: "4px",
                          cursor: "pointer",
                        }}
                      >
                        Accept
                      </button>
                      <button
                        onClick={() => handleDecline(walk.id)}
                        style={{
                          backgroundColor: "#dc3545",
                          color: "white",
                          border: "none",
                          padding: "5px 10px",
                          borderRadius: "4px",
                          cursor: "pointer",
                        }}
                      >
                        Decline
                      </button>
                    </>
                  )}
                  <button
                    onClick={() => handleDelete(walk.id)}
                    style={{
                      backgroundColor: "#6c757d",
                      color: "white",
                      border: "none",
                      padding: "5px 10px",
                      borderRadius: "4px",
                      cursor: "pointer",
                    }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface InventoryItem {
  id: number;
  name: string;
  quantity: number;
  donor_id: number | null;
  volunteer_id: number | null;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS inventory_items (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    quantity INTEGER NOT NULL,
    donor_id INTEGER,
    volunteer_id INTEGER,
    FOREIGN KEY (donor_id) REFERENCES donors(id),
    FOREIGN KEY (volunteer_id) REFERENCES volunteers(id)
  )
`;

db.exec(createTableSql);

export function getAllInventoryItems(): InventoryItem[] {
  const stmt = db.prepare(`SELECT * FROM inventory_items`);
  return stmt.all() as unknown as InventoryItem[];
}

export function getInventoryItemById(id: number): InventoryItem | undefined {
  const stmt = db.prepare(`SELECT * FROM inventory_items WHERE id = ?`);
  return stmt.get(id) as unknown as InventoryItem | undefined;
}

export function insertInventoryItem(
  name: string,
  quantity: number,
  donorId: number | null,
  volunteerId: number | null
): number {
  const stmt = db.prepare(
    `INSERT INTO inventory_items (name, quantity, donor_id, volunteer_id) VALUES (?, ?, ?, ?)`
  );
  const result = stmt.run(name, quantity, donorId, volunteerId);
  return Number(result.lastInsertRowid);
}

export function updateInventoryItem(
  id: number,
  name: string,
  quantity: number,
  donorId: number | null,
  volunteerId: number | null
): void {
  const stmt = db.prepare(
    `UPDATE inventory_items SET name = ?, quantity = ?, donor_id = ?, volunteer_id = ? WHERE id = ?`
  );
  stmt.run(name, quantity, donorId, volunteerId, id);
}

export function deleteInventoryItem(id: number): void {
  const stmt = db.prepare(`DELETE FROM inventory_items WHERE id = ?`);
  stmt.run(id);
}

// Insert sample data if table is empty
if (getAllInventoryItems().length === 0) {
  insertInventoryItem("Rice - White", 120, 1, null);
  insertInventoryItem("Pasta - Spaghetti", 80, 2, null);
  insertInventoryItem("Canned Tomatoes", 60, null, 1);
  insertInventoryItem("Chicken Breast", 40, 3, 2);
  insertInventoryItem("Milk - Whole", 30, null, 3);
}
