export function MeetingRoomUi() {
  const [sessionData, setSessionData] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newSessionId, setNewSessionId] = useState("");
  const [screenShareActive, setScreenShareActive] = useState(false);
  const [reaction, setReaction] = useState<"like" | "love" | "laugh" | null>(null);
  const [pollQuestion, setPollQuestion] = useState("");
  const [pollOptions, setPollOptions] = useState([""]);
  const [chatMessage, setChatMessage] = useState("");
  const [chatMessages, setChatMessages] = useState<any[]>([]);

  // Fetch session data
  useEffect(() => {
    const fetchSession = async () => {
      try {
        const response = await fetch(`/api/conferencing-server/`);
        if (!response.ok) throw new Error(`Failed to fetch sessions: ${await response.text()}`);
        const data = await response.json();
        setSessionData(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchSession();
  }, []);

  const handleCreateSession = async () => {
    try {
      const response = await fetch(`/api/conferencing-server/create-session`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({}),
      });
      if (!response.ok) throw new Error(`Failed to create session: ${await response.text()}`);
      const data = await response.json();
      setNewSessionId(data.id);
      // Refresh session list
      const refreshResponse = await fetch(`/api/conferencing-server/`);
      if (refreshResponse.ok) {
        const refreshedData = await refreshResponse.json();
        setSessionData(refreshedData);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleJoinSession = async (id: string) => {
    try {
      const response = await fetch(`/api/conferencing-server/session/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "join" }),
      });
      if (!response.ok) throw new Error(`Failed to join session: ${await response.text()}`);
      window.location.href = `/meeting/${id}`;
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleEndSession = async (id: string) => {
    try {
      const response = await fetch(`/api/conferencing-server/session/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) throw new Error(`Failed to end session: ${await response.text()}`);
      // Refresh session list
      const refreshResponse = await fetch(`/api/conferencing-server/`);
      if (refreshResponse.ok) {
        const refreshedData = await refreshResponse.json();
        setSessionData(refreshedData);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const toggleScreenShare = () => {
    setScreenShareActive(!screenShareActive);
  };

  const sendReaction = (type: "like" | "love" | "laugh") => {
    setReaction(type);
    setTimeout(() => setReaction(null), 2000);
  };

  const createPoll = async () => {
    try {
      const response = await fetch(`/api/conferencing-server/session/${sessionData?.[0]?.id}/poll`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ question: pollQuestion, options: pollOptions }),
      });
      if (!response.ok) throw new Error(`Failed to create poll: ${await response.text()}`);
      setPollQuestion("");
      setPollOptions([""]);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const sendMessage = async () => {
    if (!chatMessage.trim()) return;
    try {
      const response = await fetch(`/api/conferencing-server/session/${sessionData?.[0]?.id}/chat`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: chatMessage }),
      });
      if (!response.ok) throw new Error(`Failed to send message: ${await response.text()}`);
      setChatMessage("");
      // In a real app, we'd update chatMessages here
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Meeting Room</h1>

      <div style={{ marginBottom: "20px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <button onClick={handleCreateSession} style={{ padding: "10px 15px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "5px", cursor: "pointer" }}>
          Create New Session
        </button>

        {newSessionId && (
          <div style={{ backgroundColor: "#d4edda", padding: "10px", borderRadius: "5px", color: "#155724" }}>
            Created session ID: {newSessionId}
          </div>
        )}
      </div>

      <div style={{ marginBottom: "20px" }}>
        <h2>Active Sessions</h2>
        {sessionData && sessionData.length > 0 ? (
          <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
            {sessionData.map((session: any) => (
              <div key={session.id} style={{ border: "1px solid #ccc", padding: "10px", borderRadius: "5px", minWidth: "200px" }}>
                <p><strong>ID:</strong> {session.id}</p>
                <p><strong>Status:</strong> {session.status}</p>
                <div style={{ marginTop: "10px", display: "flex", gap: "5px" }}>
