                    style={{ padding: "5px 10px", backgroundColor: "#dc3545", color: "white", border: "none", borderRadius: "3px", cursor: "pointer" }}
                  >
                    End
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p>No active sessions found.</p>
        )}
      </div>

      <div style={{ marginBottom: "20px" }}>
        <h2>Controls</h2>
        <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
          <button 
            onClick={toggleScreenShare}
            style={{ padding: "10px 15px", backgroundColor: screenShareActive ? "#dc3545" : "#007bff", color: "white", border: "none", borderRadius: "5px", cursor: "pointer" }}
          >
            {screenShareActive ? "Stop Sharing" : "Start Sharing Screen"}
          </button>

          <div style={{ display: "flex", gap: "5px" }}>
            <button 
              onClick={() => sendReaction("like")}
              style={{ padding: "5px 10px", backgroundColor: "#17a2b8", color: "white", border: "none", borderRadius: "3px", cursor: "pointer" }}
            >
              👍 Like
            </button>
            <button 
              onClick={() => sendReaction("love")}
              style={{ padding: "5px 10px", backgroundColor: "#17a2b8", color: "white", border: "none", borderRadius: "3px", cursor: "pointer" }}
            >
              ❤️ Love
            </button>
            <button 
              onClick={() => sendReaction("laugh")}
              style={{ padding: "5px 10px", backgroundColor: "#17a2b8", color: "white", border: "none", borderRadius: "3px", cursor: "pointer" }}
            >
              😂 Laugh
            </button>
          </div>
        </div>

        {reaction && (
          <div style={{ marginTop: "10px", padding: "10px", backgroundColor: "#f8f9fa", borderRadius: "5px" }}>
            Sent reaction: {reaction}
          </div>
        )}
      </div>

      <div style={{ marginBottom: "20px" }}>
        <h2>Poll</h2>
        <input 
          type="text" 
          placeholder="Poll question" 
          value={pollQuestion}
          onChange={(e) => setPollQuestion(e.target.value)}
          style={{ width: "100%", padding: "10px", marginBottom: "10px" }}
        />

        <div style={{ marginBottom: "10px" }}>
          {pollOptions.map((option, index) => (
            <input 
              key={index}
              type="text" 
              placeholder={`Option ${index + 1}`}
              value={option}
              onChange={(e) => {
                const newOptions = [...pollOptions];
                newOptions[index] = e.target.value;
                setPollOptions(newOptions);
              }}
              style={{ width: "100%", padding: "10px", marginBottom: "5px" }}
            />
          ))}
          <button 
            onClick={() => setPollOptions([...pollOptions, ""])}
            style={{ padding: "5px 10px", backgroundColor: "#6c757d", color: "white", border: "none", borderRadius: "3px", cursor: "pointer" }}
          >
            Add Option
          </button>
        </div>

        <button 
          onClick={createPoll}
          style={{ padding: "10px 15px", backgroundColor: "#28a745", color: "white", border: "none", borderRadius: "5px", cursor: "pointer" }}
        >
          Create Poll
        </button>
      </div>

      <div>
        <h2>Chat</h2>
        <div style={{ height: "200px", overflowY: "auto", border: "1px solid #ccc", padding: "10px", marginBottom: "10px" }}>
          {chatMessages.length > 0 ? (
            chatMessages.map((msg, i) => (
              <div key={i} style={{ marginBottom: "5px" }}>
                <strong>{msg.user}:</strong> {msg.text}
