          />
          <button 
            onClick={sendMessage}
            style={{ padding: "10px 15px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "5px", cursor: "pointer" }}
          >
            Send
          </button>
        </div>
      </div>
    </div>
  );
}
"}

