{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

// Define role types
export type UserRole = "admin" | "editor" | "viewer";

// Define permission levels
export type Permission = "manage_newsletters" | "manage_subscribers" | "view";

// Define user role permissions
const rolePermissions: Record<UserRole, Permission[]> = {
  admin: ["manage_newsletters", "manage_subscribers", "view"],
  editor: ["manage_newsletters", "view"],
  viewer: ["view"]
};

// Middleware function for role-based access control
export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply RBAC to specific routes and methods
  const protectedPaths = ["/newsletters", "/subscribers"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  // Skip RBAC for non-protected paths
  if (!isProtectedPath) {
    next();
    return;
  }

  // For protected paths, we need to check permissions
  // In a real implementation, this would extract user role from auth token
  // For now, we'll simulate with a mock user role
  const userRole: UserRole = "admin"; // This would normally come from decoded JWT

  // Check if user has required permissions
  const requiredPermissions: Permission[] = [];

  // Determine required permissions based on HTTP method and path
  if (req.path.includes("/newsletters") && req.method === "POST") {
    requiredPermissions.push("manage_newsletters");
  } else if (req.path.includes("/subscribers") && req.method === "POST") {
    requiredPermissions.push("manage_subscribers");
  } else if (req.path.includes("/newsletters") && req.method === "GET") {
    requiredPermissions.push("view");
  } else if (req.path.includes("/subscribers") && req.method === "GET") {
    requiredPermissions.push("view");
  }

  // Check if user has required permissions
  const userPermissions = rolePermissions[userRole] || [];
  const hasPermission = requiredPermissions.every(permission =>
    userPermissions.includes(permission)
  );

  if (hasPermission) {
    next();
  } else {
    res.status(403).json({ message: "Forbidden: Insufficient permissions" });
  }
}
"}

