import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT secret is set
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Mock authentication logic - in a real implementation,
  // this would verify a JWT token signature
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);

  // In a real implementation, we would verify the token signature here
  // For now, we'll just check if it exists and has proper format
  try {
    // This is a simplified mock - a real implementation would decode and verify
    // the JWT using HMAC-SHA256 with the secret
    const payload = JSON.parse(Buffer.from(token.split(".")[1], "base64").toString());

    // Verify the signature (mock implementation)
    const expectedSignature = createHmac("sha256", jwtSecret)
      .update(`${token.split(".")[0]}.${token.split(".")[1]}`)
      .digest("base64");

    const actualSignature = token.split(".")[2];

    // Use timingSafeEqual to prevent timing attacks
    const isValid = timingSafeEqual(
      Buffer.from(expectedSignature, "base64"),
      Buffer.from(actualSignature, "base64")
    );

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    // If token is valid, proceed
    next();
  } catch (error) {
    res.status(401).json({ error: "Invalid token" });
  }
}
