{"code":"import { useEffect, useState } from "react";

interface Topic {
  id: number;
  title: string;
  content: string;
  author: string;
  createdAt: string;
}

interface Post {
  id: number;
  content: string;
  author: string;
  createdAt: string;
}

export function ForumUi() {
  const [topics, setTopics] = useState<Topic[]>([]);
  const [posts, setPosts] = useState<Post[]>([]);
  const [selectedTopicId, setSelectedTopicId] = useState<number | null>(null);
  const [newTopicTitle, setNewTopicTitle] = useState("");
  const [newTopicContent, setNewTopicContent] = useState("");
  const [newPostContent, setNewPostContent] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    fetchTopics();
  }, []);

  const fetchTopics = async () => {
    setLoading(true);
    setError("");
    try {
      const response = await fetch("/api/discussion-api/topics");
      if (!response.ok) throw new Error(await response.text());
      const data = await response.json();
      setTopics(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load topics");
    } finally {
      setLoading(false);
    }
  };

  const fetchPosts = async (topicId: number) => {
    setLoading(true);
    setError("");
    try {
      const response = await fetch(`/api/discussion-api/topics/${topicId}/posts`);
      if (!response.ok) throw new Error(await response.text());
      const data = await response.json();
      setPosts(data);
      setSelectedTopicId(topicId);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load posts");
    } finally {
      setLoading(false);
    }
  };

  const handleCreateTopic = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTopicTitle.trim() || !newTopicContent.trim()) return;

    setLoading(true);
    setError("");
    try {
      const response = await fetch("/api/discussion-api/topics", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          title: newTopicTitle,
          content: newTopicContent,
          author: "CurrentUser"
        })
      });
      if (!response.ok) throw new Error(await response.text());

      setNewTopicTitle("");
      setNewTopicContent("");
      await fetchTopics();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to create topic");
    } finally {
      setLoading(false);
    }
  };

  const handleAddPost = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedTopicId || !newPostContent.trim()) return;

    setLoading(true);
    setError("");
    try {
      const response = await fetch(`/api/discussion-api/topics/${selectedTopicId}/posts`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          content: newPostContent,
          author: "CurrentUser"
        })
      });
      if (!response.ok) throw new Error(await response.text());

      setNewPostContent("");
      await fetchPosts(selectedTopicId);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to add post");
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteTopic = async (topicId: number) => {
    setLoading(true);
    setError("");
    try {
      const response = await fetch(`/api/discussion-api/topics/${topicId}`, {
        method: "DELETE"
      });
      if (!response.ok) throw new Error(await response.text());

      if (selectedTopicId === topicId) {
        setSelectedTopicId(null);
        setPosts([]);
      }
      await fetchTopics();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to delete topic");
    } finally {
      setLoading(false);
    }
  };

  const containerStyle = {
    maxWidth: "800px",
    margin: "0 auto",
    padding: "20px",
    fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
  };

  const cardStyle = {
    border: "1px solid #ddd",
    borderRadius: "8px",
    padding: "16px",
    marginBottom: "16px",
    backgroundColor: "#f9f9f9"
  };

  const inputStyle = {
    width: "100%",
    padding: "10px",
    marginBottom: "10px",
    borderRadius: "4px",
    border: "1px solid #ccc"
  };

  const buttonStyle = {
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    padding: "10px 16px",
    borderRadius: "4px",
    cursor: "pointer",
    marginRight: "8px"
  };

  const secondaryButtonStyle = {
    backgroundColor: "#6c757d",
    color: "white",
    border: "none",
    padding: "10px 16px",
    borderRadius: "4px",
    cursor: "pointer",
    marginRight: "8px"
  };

  const postCardStyle = {
    border: "1px solid #eee",
    borderRadius: "4px",
    padding: "12px",
    marginBottom: "10px",
    backgroundColor: "#fff"
  };

  if (loading && topics.length === 0) {
    return <div style={containerStyle}>Loading...</div>;
  }

  return (
    <div style={containerStyle}>
      <h1>Community Discussion Forum</h1>

      {error && <div style={{ color: "red", marginBottom: "16px" }}>{error}</div>}

      <h2>Create New Topic</h2>
      <form onSubmit={handleCreateTopic} style={cardStyle}>
        <input
          type="text"
          placeholder="Topic Title"
          value={newTopicTitle}
          onChange={(e) => setNewTopicTitle(e.target.value)}
          style={inputStyle}
        />
        <textarea
          placeholder="Content"
          value={newTopicContent}
          onChange={(e) => setNewTopicContent(e.target.value)}
          style={inputStyle}
        />
        <button type="submit" style={buttonStyle} disabled={loading}>Create Topic</button>
      </form>

      <h2>Discussion Topics</h2>
      {topics.length === 0 ? (
        <p>No topics found.</p>
      ) : (
        <div>
          {topics.map((topic) => (
            <div key={topic.id} style={cardStyle}>
              <h3>{topic.title}</h3>
              <p>{topic.content}</p>
              <small>By {topic.author} on {new Date(topic.createdAt).toLocaleString()}</small>
              <div style={{ marginTop: "10px" }}>
                <button 
                  onClick={() => fetchPosts(topic.id)}
                  style={buttonStyle}
                >
                  View Posts
                </button>
                <button 
                  onClick={() => handleDeleteTopic(topic.id)}
                  style={secondaryButtonStyle}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {selectedTopicId !== null && (
        <div>
          <h2>Posts for Topic #{selectedTopicId}</h2>
          <div>
            {posts.length === 0 ? (
              <p>No posts yet.</p>
            ) : (
              posts.map((post) => (
                <div key={post.id} style={postCardStyle}>
                  <p>{post.content}</p>
                  <small>By {post.author} on {new Date(post.createdAt).toLocaleString()}</small>
                </div>
              ))
            )}
          </div>

          <form onSubmit={handleAddPost} style={cardStyle}>
            <textarea
              placeholder="Add a post..."
              value={newPostContent}
              onChange={(e) => setNewPostContent(e.target.value)}
              style={inputStyle}
            />
            <button type="submit" style={buttonStyle} disabled={loading}>Add Post</button>
            <button 
              type="button" 
              onClick={() => setSelectedTopicId(null)}
              style={secondaryButtonStyle}
            >
              Back to Topics
            </button>
          </form>
        </div>
      )}
    </div>
  );
}
"}

