{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes in milliseconds
const ACTIVE_SESSIONS = new Map<string, { expiresAt: number }>();

function getSessionIdFromRequest(req: Request): string | null {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return null;
  }

  const token = authHeader.substring(7);
  return token;
}

function verifyTokenSignature(token: string): boolean {
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return false;
  }

  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) {
      return false;
    }

    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    const actualSignature = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    return timingSafeEqual(actualSignature, expectedSignatureBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const sessionId = getSessionIdFromRequest(req);

  if (!sessionId) {
    res.status(401).json({ error: "Unauthorized: Missing session ID" });
    return;
  }

  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT secret not configured" });
    return;
  }

  if (!verifyTokenSignature(sessionId)) {
    res.status(401).json({ error: "Unauthorized: Invalid session token" });
    return;
  }

  // Check if session exists and is still valid
  const session = ACTIVE_SESSIONS.get(sessionId);
  if (!session || Date.now() > session.expiresAt) {
    ACTIVE_SESSIONS.delete(sessionId);
    res.status(401).json({ error: "Unauthorized: Session expired or invalid" });
    return;
  }

  // Extend session timeout
  session.expiresAt = Date.now() + SESSION_TIMEOUT;

  next();
}
"}

