export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockFeedbackDatabase = {
  getAll: (): Promise<any[]> => Promise.resolve([
    { id: 1, guestName: "John Doe", email: "john@example.com", rating: 5, comment: "Excellent service!" },
    { id: 2, guestName: "Jane Smith", email: "jane@example.com", rating: 4, comment: "Good experience." }
  ]),
  getById: (id: number): Promise<any | null> => Promise.resolve(
    [{ id: 1, guestName: "John Doe", email: "john@example.com", rating: 5, comment: "Excellent service!" },
     { id: 2, guestName: "Jane Smith", email: "jane@example.com", rating: 4, comment: "Good experience." }]
      .find(feedback => feedback.id === id) || null
  ),
  create: (feedback: any): Promise<any> => Promise.resolve({
    id: Date.now(),
    ...feedback
  }),
  update: (id: number, feedback: any): Promise<any | null> => Promise.resolve(
    [{ id: 1, guestName: "John Doe", email: "john@example.com", rating: 5, comment: "Excellent service!" },
     { id: 2, guestName: "Jane Smith", email: "jane@example.com", rating: 4, comment: "Good experience." }]
      .find(feedback => feedback.id === id) ? { id, ...feedback } : null
  ),
  delete: (id: number): Promise<boolean> => Promise.resolve(
    [{ id: 1, guestName: "John Doe", email: "john@example.com", rating: 5, comment: "Excellent service!" },
     { id: 2, guestName: "Jane Smith", email: "jane@example.com", rating: 4, comment: "Good experience." }]
      .some(feedback => feedback.id === id)
  )
};

// Validation helper
const validateFeedback = (feedback: any): string[] => {
  const errors: string[] = [];

  if (!feedback.guestName || feedback.guestName.trim() === '') {
    errors.push('Guest name is required');
  }

  if (!feedback.email || feedback.email.trim() === '') {
    errors.push('Email is required');
  } else if (!/^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$/.test(feedback.email)) {
    errors.push('Invalid email format');
  }

  if (typeof feedback.rating !== 'number' || feedback.rating < 1 || feedback.rating > 5) {
    errors.push('Rating must be a number between 1 and 5');
  }

  if (!feedback.comment || feedback.comment.trim() === '') {
    errors.push('Comment is required');
  }

  return errors;
};

// GET /api/feedback - Get all feedback
router.get('/', async (req: Request, res: Response) => {
  try {
    const feedback = await mockFeedbackDatabase.getAll();
    return res.json(feedback);
  } catch (error) {
    return res.status(500).json({ error: 'Failed to fetch feedback' });
  }
});

// GET /api/feedback/:id - Get feedback by ID
router.get('/:id', async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: 'Invalid ID format' });
    }

    const feedback = await mockFeedbackDatabase.getById(id);

    if (!feedback) {
