{"code":"import { useEffect, useState } from "react";

export function RecordFormPage() {
  const [formData, setFormData] = useState({
    name: "",
    type: "",
    description: "",
    date: "",
  });

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<null | string>(null);
  const [success, setSuccess] = useState<null | string>(null);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setSuccess(null);

    try {
      const response = await fetch("/api/records", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });

      if (!response.ok) {
        throw new Error(`Failed to create record: ${response.status}`);
      }

      setSuccess("Record created successfully!");
      setFormData({ name: "", type: "", description: "", date: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      maxWidth: 600,
      margin: "0 auto",
      padding: 20,
    }}>
      <h1 style={{ textAlign: "center" }}>Add New Record</h1>

      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: 15 }}>
        <div>
          <label htmlFor="name" style={{ display: "block", marginBottom: 5 }}>Name</label>
          <input
            id="name"
            name="name"
            type="text"
            value={formData.name}
            onChange={handleChange}
            required
            style={{ width: "100%", padding: 8, borderRadius: 4, border: "1px solid #ccc" }}
          />
        </div>

        <div>
          <label htmlFor="type" style={{ display: "block", marginBottom: 5 }}>Type</label>
          <select
            id="type"
            name="type"
            value={formData.type}
            onChange={handleChange}
            required
            style={{ width: "100%", padding: 8, borderRadius: 4, border: "1px solid #ccc" }}
          >
            <option value="">Select Type</option>
            <option value="meeting">Meeting</option>
            <option value="resolution">Resolution</option>
            <option value="expense">Expense</option>
            <option value="member">Member</option>
          </select>
        </div>

        <div>
          <label htmlFor="description" style={{ display: "block", marginBottom: 5 }}>Description</label>
          <textarea
            id="description"
            name="description"
            value={formData.description}
            onChange={handleChange}
            required
            style={{ width: "100%", padding: 8, borderRadius: 4, border: "1px solid #ccc", minHeight: 100 }}
          />
        </div>

        <div>
          <label htmlFor="date" style={{ display: "block", marginBottom: 5 }}>Date</label>
          <input
            id="date"
            name="date"
            type="date"
            value={formData.date}
            onChange={handleChange}
            required
            style={{ width: "100%", padding: 8, borderRadius: 4, border: "1px solid #ccc" }}
          />
        </div>

        <button
          type="submit"
          disabled={loading}
          style={{
            padding: 10,
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            borderRadius: 4,
            cursor: loading ? "default" : "pointer",
            fontWeight: "bold",
          }}
        >
          {loading ? "Adding..." : "Add Record"}
        </button>
      </form>

      {error && (
        <div style={{ marginTop: 20, padding: 10, backgroundColor: "#f8d7da", color: "#721c24", borderRadius: 4 }}>
          Error: {error}
        </div>
      )}

      {success && (
        <div style={{ marginTop: 20, padding: 10, backgroundColor: "#d4edda", color: "#155724", borderRadius: 4 }}>
          {success}
        </div>
      )}
    </div>
  );
}
"}

