{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// In-memory storage for shopping list items
let shoppingListItems: { id: number; name: string; purchased: boolean }[] = [];
let nextId = 1;

// GET /shopping-list - Get all shopping list items
router.get("/shopping-list", (req: Request, res: Response) => {
  res.json(shoppingListItems);
});

// GET /shopping-list/:id - Get a specific shopping list item by ID
router.get("/shopping-list/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid item ID" });
  }

  const item = shoppingListItems.find(item => item.id === id);

  if (!item) {
    return res.status(404).json({ error: "Shopping list item not found" });
  }

  res.json(item);
});

// POST /shopping-list - Add a new shopping list item
router.post("/shopping-list", (req: Request, res: Response) => {
  const { name } = req.body;

  if (!name || typeof name !== "string") {
    return res.status(400).json({ error: "Name is required and must be a string" });
  }

  const newItem = {
    id: nextId++,
    name,
    purchased: false
  };

  shoppingListItems.push(newItem);

  res.status(201).json(newItem);
});

// PUT /shopping-list/:id - Mark an item as purchased or unpurchased
router.put("/shopping-list/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { purchased } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid item ID" });
  }

  if (typeof purchased !== "boolean") {
    return res.status(400).json({ error: "Purchased status is required and must be a boolean" });
  }

  const itemIndex = shoppingListItems.findIndex(item => item.id === id);

  if (itemIndex === -1) {
    return res.status(404).json({ error: "Shopping list item not found" });
  }

  shoppingListItems[itemIndex].purchased = purchased;

  res.json(shoppingListItems[itemIndex]);
});

// DELETE /shopping-list/:id - Remove a shopping list item
router.delete("/shopping-list/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid item ID" });
  }

  const itemIndex = shoppingListItems.findIndex(item => item.id === id);

  if (itemIndex === -1) {
    return res.status(404).json({ error: "Shopping list item not found" });
  }

  shoppingListItems.splice(itemIndex, 1);

  res.json({ message: "Item removed successfully" });
});
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  { id: 1, username: "admin", password: "admin123", role: "administrator" },
  { id: 2, username: "employee1", password: "pass456", role: "employee" },
];

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(
    (u) => u.username === username && u.password === password
  );

  if (!user) {
    return res
      .status(401)
      .json({ error: "Invalid username or password" });
  }

  // In a real app, we would generate a JWT token here
  return res.json({
    message: "Login successful",
    user: { id: user.id, username: user.username, role: user.role },
  });
});

// Role-based access control middleware
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: Function) => {
    // In a real app, this would check the JWT token
    const userRole = req.headers.role as string;
    if (!userRole || !roles.includes(userRole)) {
      return res
        .status(403)
        .json({ error: "Access denied: insufficient permissions" });
    }
    next();
  };
};

// Protected route example for administrators
router.get(
  "/admin-dashboard",
  authorize(["administrator"]),
  (req: Request, res: Response) => {
    return res.json({ message: "Welcome to the admin dashboard" });
  }
);

// Protected route example for employees
router.get(
  "/employee-dashboard",
  authorize(["employee", "administrator"]),
  (req: Request, res: Response) => {
    return res.json({ message: "Welcome to your dashboard" });
  }
);
"}

