{"code":"import { useEffect, useState } from "react";

interface Equipment {
  id: number;
  name: string;
  category: string;
  quantity: number;
  available: number;
}

export function EquipmentManagementPage() {
  const [equipments, setEquipments] = useState<Equipment[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [categoryFilter, setCategoryFilter] = useState("");

  // Form state
  const [formData, setFormData] = useState({
    name: "",
    category: "",
    quantity: 1,
    available: 1
  });

  const [editingId, setEditingId] = useState<number | null>(null);

  // Fetch equipment data
  useEffect(() => {
    const fetchEquipments = async () => {
      try {
        const response = await fetch('/api/equipment');
        if (!response.ok) {
          throw new Error('Failed to fetch equipment');
        }
        const data = await response.json();
        setEquipments(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
        setLoading(false);
      }
    };

    fetchEquipments();
  }, []);

  // Filtered equipment based on search and category
  const filteredEquipments = equipments.filter(item => {
    const matchesSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          item.category.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = categoryFilter === "" || item.category === categoryFilter;
    return matchesSearch && matchesCategory;
  });

  // Get unique categories for filter dropdown
  const categories = [...new Set(equipments.map(item => item.category))];

  // Handle form input changes
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: name === 'quantity' || name === 'available' ? Number(value) : value
    }));
  };

  // Handle form submission
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = await fetch('/api/equipment', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });

      if (!response.ok) {
        throw new Error('Failed to add equipment');
      }

      // Refresh data
      const newResponse = await fetch('/api/equipment');
      const newData = await newResponse.json();
      setEquipments(newData);

      // Reset form
      setFormData({ name: "", category: "", quantity: 1, available: 1 });
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  // Handle edit
  const handleEdit = (equipment: Equipment) => {
    setEditingId(equipment.id);
    setFormData({
      name: equipment.name,
      category: equipment.category,
      quantity: equipment.quantity,
      available: equipment.available
    });
  };

  // Handle update
  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId === null) return;

    try {
      const response = await fetch(`/api/equipment/${editingId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });

      if (!response.ok) {
        throw new Error('Failed to update equipment');
      }

      // Refresh data
      const newResponse = await fetch('/api/equipment');
