{"code":"import { useEffect, useState } from "react";

interface CheckInOutRecord {
  id: string;
  petName: string;
  ownerName: string;
  checkInDate: string;
  checkOutDate: string | null;
}

export function CheckInOutForm() {
  const [records, setRecords] = useState<CheckInOutRecord[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    petName: "",
    ownerName: "",
  });
  const [editingId, setEditingId] = useState<string | null>(null);

  const fetchRecords = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/check-in-check-out-api/");
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setRecords(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRecords();
  }, []);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/check-in-check-out-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...formData,
          checkInDate: new Date().toISOString(),
          checkOutDate: null,
        }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      await fetchRecords();
      setFormData({ petName: "", ownerName: "" });
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleCheckOut = async (id: string) => {
    try {
      const response = await fetch(`/api/check-in-check-out-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ checkOutDate: new Date().toISOString() }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      await fetchRecords();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/check-in-check-out-api/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      await fetchRecords();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const formStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
    marginBottom: "20px",
  };

  const inputStyle: React.CSSProperties = {
    padding: "8px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    fontSize: "16px",
    width: "100%",
  };

  const buttonStyle: React.CSSProperties = {
    padding: "8px 16px",
    borderRadius: "4px",
    border: "none",
    backgroundColor: "#007bff",
    color: "white",
    cursor: "pointer",
    fontSize: "16px",
  };

  const tableStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
  };

  const rowStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "5px",
    padding: "10px",
    border: "1px solid #ccc",
    borderRadius: "4px",
  };

  const buttonGroupStyle: React.CSSProperties = {
    display: "flex",
    gap: "5px",
    justifyContent: "flex-end",
  };

  if (loading) return <div>Loading...</div>;

  if (error) return <div>Error: {error}</div>;

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", fontFamily: "system-ui" }}>
      <h1>Pet Check-In/Check-Out</h1>

      <form onSubmit={handleSubmit} style={formStyle}>
        <input
          type="text"
          name="petName"
          placeholder="Pet Name"
          value={formData.petName}
          onChange={handleInputChange}
          style={inputStyle}
        />
        <input
          type="text"
          name="ownerName"
          placeholder="Owner Name"
          value={formData.ownerName}
          onChange={handleInputChange}
          style={inputStyle}
        />
        <button type="submit" style={buttonStyle}>Check In Pet</button>
      </form>

      <div style={tableStyle}>
        {records.length === 0 ? (
          <p>No records found.</p>
        ) : (
          records.map((record) => (
            <div key={record.id} style={rowStyle}>
              <div><strong>Pet:</strong> {record.petName}</div>
              <div><strong>Owner:</strong> {record.ownerName}</div>
              <div><strong>Check In:</strong> {new Date(record.checkInDate).toLocaleString()}</div>
              {record.checkOutDate && (
                <div><strong>Check Out:</strong> {new Date(record.checkOutDate).toLocaleString()}</div>
              )}
              <div style={buttonGroupStyle}>
                {!record.checkOutDate && (
                  <button onClick={() => handleCheckOut(record.id)} style={buttonStyle}>Check Out</button>
                )}
                <button onClick={() => handleDelete(record.id)} style={buttonStyle}>Delete</button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}
"}

