{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const donors = [
  { id: "1", name: "John Doe", email: "john@example.com", bloodType: "A+", lastDonation: "2023-01-15" },
  { id: "2", name: "Jane Smith", email: "jane@example.com", bloodType: "O-", lastDonation: "2023-03-20" }
];

const findDonorById = (id: string) => {
  return donors.find(donor => donor.id === id);
};

const createDonor = (newDonor: any) => {
  const donor = {
    id: `${donors.length + 1}`,
    name: newDonor.name,
    email: newDonor.email,
    bloodType: newDonor.bloodType,
    lastDonation: newDonor.lastDonation
  };
  donors.push(donor);
  return donor;
};

const updateDonor = (id: string, updatedFields: any) => {
  const donorIndex = donors.findIndex(donor => donor.id === id);
  if (donorIndex === -1) return null;

  donors[donorIndex] = {
    ...donors[donorIndex],
    ...updatedFields
  };

  return donors[donorIndex];
};

const deleteDonor = (id: string) => {
  const donorIndex = donors.findIndex(donor => donor.id === id);
  if (donorIndex === -1) return false;

  donors.splice(donorIndex, 1);
  return true;
};

// GET /donors - List all donors
router.get("/donors", (req: Request, res: Response) => {
  res.json(donors);
});

// GET /donors/:id - Get a specific donor by ID
router.get("/donors/:id", (req: Request, res: Response) => {
  const donor = findDonorById(req.params.id);
  if (!donor) {
    return res.status(404).json({ error: "Donor not found" });
  }
  res.json(donor);
});

// POST /donors - Create a new donor
router.post("/donors", (req: Request, res: Response) => {
  const { name, email, bloodType, lastDonation } = req.body;

  // Basic validation
  if (!name || !email || !bloodType) {
    return res.status(400).json({ error: "Name, email, and blood type are required" });
  }

  const newDonor = createDonor({ name, email, bloodType, lastDonation });
  res.status(201).json(newDonor);
});

// PUT /donors/:id - Update a donor
router.put("/donors/:id", (req: Request, res: Response) => {
  const donor = findDonorById(req.params.id);
  if (!donor) {
    return res.status(404).json({ error: "Donor not found" });
  }

  const { name, email, bloodType, lastDonation } = req.body;

  // Basic validation
  if (!name || !email || !bloodType) {
    return res.status(400).json({ error: "Name, email, and blood type are required" });
  }

  const updatedDonor = updateDonor(req.params.id, { name, email, bloodType, lastDonation });
  res.json(updatedDonor);
});

// DELETE /donors/:id - Delete a donor
router.delete("/donors/:id", (req: Request, res: Response) => {
  const deleted = deleteDonor(req.params.id);
  if (!deleted) {
    return res.status(404).json({ error: "Donor not found" });
  }

  res.json({ message: "Donor deleted successfully" });
});
"}

{"code":"import { useEffect, useState } from "react";

interface Booking {
  id: string;
  userId: string;
  startTime: string;
  endTime: string;
  status: string;
}

export function StaffExtensionPanel() {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchBookings();
  }, []);

  const fetchBookings = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/bookings-api/bookings');
      if (!response.ok) {
        throw new Error('Failed to fetch bookings');
      }
      const data = await response.json();
      setBookings(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleExtend = async (bookingId: string, extensionMinutes: number) => {
    try {
      const response = await fetch(`/api/staff-extension-endpoint/extend/${bookingId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ extensionMinutes }),
      });

      if (!response.ok) {
        throw new Error('Failed to extend booking');
      }

      // Refresh the bookings list
      await fetchBookings();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  if (bookings.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No bookings found.</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Staff Extension Panel</h1>
      <p style={{ textAlign: 'center', marginBottom: '20px' }}>Extend booking times for staff members</p>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        {bookings.map(booking => (
          <div key={booking.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px' }}>
            <div style={{ marginBottom: '10px' }}>
              <strong>Booking ID:</strong> {booking.id}
            </div>
            <div style={{ marginBottom: '10px' }}>
              <strong>User ID:</strong> {booking.userId}
            </div>
            <div style={{ marginBottom: '10px' }}>
              <strong>Start Time:</strong> {new Date(booking.startTime).toLocaleString()}
            </div>
            <div style={{ marginBottom: '10px' }}>
              <strong>End Time:</strong> {new Date(booking.endTime).toLocaleString()}
            </div>
            <div style={{ marginBottom: '10px' }}>
              <strong>Status:</strong> {booking.status}
            </div>

            <div style={{ marginTop: '10px' }}>
              <label htmlFor={`extension-${booking.id}`} style={{ display: 'block', marginBottom: '5px' }}>
                Extend by minutes:
              </label>
              <input
                id={`extension-${booking.id}`}
                type="number"
                min="1"
                defaultValue="30"
