{"code":"import { useEffect, useState } from "react";

interface Route {
  id: number;
  name: string;
  description: string;
  setter: string;
  status: 'active' | 'retired';
}

export function RouteLogBoard() {
  const [routes, setRoutes] = useState<Route[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newRoute, setNewRoute] = useState({
    name: '',
    description: '',
    setter: '',
  });

  useEffect(() => {
    fetchRoutes();
  }, []);

  const fetchRoutes = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/routes-api/routes');
      if (!response.ok) {
        throw new Error(`Failed to fetch routes: ${response.status}`);
      }
      const data = await response.json();
      setRoutes(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleCreateRoute = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch('/api/routes-api/routes', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newRoute),
      });
      if (!response.ok) {
        throw new Error(`Failed to create route: ${response.status}`);
      }
      setNewRoute({ name: '', description: '', setter: '' });
      fetchRoutes();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleRetireRoute = async (id: number) => {
    try {
      const response = await fetch(`/api/routes-api/routes/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'retired' }),
      });
      if (!response.ok) {
        throw new Error(`Failed to retire route: ${response.status}`);
      }
      fetchRoutes();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDeleteRoute = async (id: number) => {
    try {
      const response = await fetch(`/api/routes-api/routes/${id}`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        throw new Error(`Failed to delete route: ${response.status}`);
      }
      fetchRoutes();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Route Log Board</h1>

      <div style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <h2>Create New Route</h2>
        <form onSubmit={handleCreateRoute}>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              placeholder="Route Name"
              value={newRoute.name}
              onChange={(e) => setNewRoute({...newRoute, name: e.target.value})}
              style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
              required
            />
          </div>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              placeholder="Description"
              value={newRoute.description}
              onChange={(e) => setNewRoute({...newRoute, description: e.target.value})}
              style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
              required
            />
          </div>
          <div style={{ marginBottom: '10px' }}>
            <input
              type="text"
              placeholder="Setter Name"
              value={newRoute.setter}
              onChange={(e) => setNewRoute({...newRoute, setter: e.target.value})}
              style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
              required
            />
          </div>
          <button type="submit" style={{ padding: '10px 20px', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>
            Add Route
          </button>
        </form>
      </div>

      <h2>Current Routes</h2>
      {routes.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No routes found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {routes.map(route => (
            <div key={route.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                  <h3>{route.name}</h3>
                  <p>{route.description}</p>
                  <p><strong>Setter:</strong> {route.setter}</p>
                  <p><strong>Status:</strong> {route.status}</p>
                </div>
                <div style={{ display: 'flex', gap: '10px' }}>
                  {route.status === 'active' && (
                    <button 
                      onClick={() => handleRetireRoute(route.id)}
                      style={{ padding: '6px 12px', backgroundColor: '#ffc107', color: 'black', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
                    >
                      Retire
                    </button>
                  )}
                  <button 
                    onClick={() => handleDeleteRoute(route.id)}
                    style={{ padding: '6px 12px', backgroundColor: '#dc3545', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply RBAC logic to protected routes
  const protectedPaths = [/^\/pets\/.+$/, /^\/reminders\/.+$/];
  const isProtectedPath = protectedPaths.some(path => path.test(req.path));

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has proper role
  const userRole = req.headers["x-user-role"] as string | undefined;
  const userId = req.headers["x-user-id"] as string | undefined;

  if (!userRole || !userId) {
    res.status(401).json({ error: "Unauthorized: Missing role or user ID" });
    return;
  }

  // Extract petId or reminderId from URL params
  const petId = req.params.petId;
  const reminderId = req.params.reminderId;

  // Validate that the user owns the resource they're trying to access
  if (petId && userRole !== "admin") {
    // For non-admins, ensure petId matches user's pets
    // This is a simplified check - in reality, you'd query the database
    // to verify ownership
    const expectedPetId = `user-${userId}-pet`;
    if (petId !== expectedPetId) {
      res.status(403).json({ error: "Forbidden: Access denied to pet" });
      return;
    }
  }

  if (reminderId && userRole !== "admin") {
    // For non-admins, ensure reminderId matches user's reminders
    const expectedReminderId = `user-${userId}-reminder`;
    if (reminderId !== expectedReminderId) {
      res.status(403).json({ error: "Forbidden: Access denied to reminder" });
      return;
    }
  }

  // If we reach here, the user has proper permissions
  next();
}
"}

