{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check role-based access for specific routes that require it
  const protectedPaths = ["/equipment", "/lending", "/users"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  // Define required roles for different paths
  const pathRoles: Record<string, string[]> = {
    "/equipment": ["admin", "lab-manager"],
    "/lending": ["admin", "lab-manager", "student"],
    "/users": ["admin"]
  };

  const requiredRoles = pathRoles[req.path] || [];

  // If no roles are required, allow access
  if (requiredRoles.length === 0) {
    next();
    return;
  }

  // Validate that userRole exists and is a string
  if (!userRole || typeof userRole !== "string") {
    res.status(403).json({ error: "Access denied: Invalid user role" });
    return;
  }

  // Check if user has required role
  if (requiredRoles.includes(userRole)) {
    next();
  } else {
    res.status(403).json({ error: "Access denied: Insufficient permissions" });
  }
}
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock service data - in a real app this would come from a database
let services = [
  { id: 1, name: "Oil Change", description: "Full oil change with filter replacement", price: 45 },
  { id: 2, name: "Brake Service", description: "Brake pad and rotor inspection and service", price: 65 },
  { id: 3, name: "Tire Replacement", description: "Tire replacement and balancing", price: 80 }
];

let nextId = 4;

// Get all services
router.get("/", (req: Request, res: Response) => {
  res.json(services);
});

// Get a service by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const service = services.find(s => s.id === id);

  if (!service) {
    return res.status(404).json({ error: "Service not found" });
  }

  res.json(service);
});

// Create a new service
router.post("/", (req: Request, res: Response) => {
  const { name, description, price } = req.body;

  // Validate required fields
  if (!name || !description || price === undefined) {
    return res.status(400).json({ error: "Name, description, and price are required" });
  }

  // Validate price is a number
  if (typeof price !== "number" || price < 0) {
    return res.status(400).json({ error: "Price must be a non-negative number" });
  }

  const newService = {
    id: nextId++,
    name,
    description,
    price
  };

  services.push(newService);
  res.status(201).json(newService);
});

// Update a service
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { name, description, price } = req.body;

  const serviceIndex = services.findIndex(s => s.id === id);

  if (serviceIndex === -1) {
    return res.status(404).json({ error: "Service not found" });
  }

  // Validate required fields
  if (!name || !description || price === undefined) {
    return res.status(400).json({ error: "Name, description, and price are required" });
  }

  // Validate price is a number
  if (typeof price !== "number" || price < 0) {
    return res.status(400).json({ error: "Price must be a non-negative number" });
  }

  const updatedService = {
    id,
    name,
    description,
    price
  };

  services[serviceIndex] = updatedService;
  res.json(updatedService);
});

// Delete a service
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const serviceIndex = services.findIndex(s => s.id === id);

  if (serviceIndex === -1) {
    return res.status(404).json({ error: "Service not found" });
  }

  services.splice(serviceIndex, 1);
  res.json({ message: "Service deleted successfully" });
});
"}

