  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    name: "",
    description: "",
    hourlyRate: 0,
  });
  const [editingId, setEditingId] = useState<string | null>(null);

  useEffect(() => {
    fetchProjects();
  }, []);

  const fetchProjects = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/projects-api/");
      if (!response.ok) throw new Error("Failed to fetch projects");
      const data = await response.json();
      setProjects(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId) {
      // Update existing project
      try {
        const response = await fetch(`/api/projects-api/${editingId}`, {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(formData),
        });
        if (!response.ok) throw new Error("Failed to update project");
        fetchProjects();
        setEditingId(null);
        resetForm();
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      }
    } else {
      // Create new project
      try {
        const response = await fetch("/api/projects-api/", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(formData),
        });
        if (!response.ok) throw new Error("Failed to create project");
        fetchProjects();
        resetForm();
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      }
    }
  };

  const handleEdit = (project: Project) => {
    setFormData({
      name: project.name,
      description: project.description,
      hourlyRate: project.hourlyRate,
    });
    setEditingId(project.id);
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/projects-api/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) throw new Error("Failed to delete project");
      fetchProjects();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const resetForm = () => {
    setFormData({
      name: "",
      description: "",
      hourlyRate: 0,
    });
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: name === "hourlyRate" ? Number(value) : value,
    });
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Projects Management</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <div style={{ marginBottom: "15px" }}>
          <input
            type="text"
            name="name"
            placeholder="Project Name"
            value={formData.name}
            onChange={handleChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
            required
          />
        </div>
        <div style={{ marginBottom: "15px" }}>
          <textarea
            name="description"
            placeholder="Description"
            value={formData.description}
            onChange={handleChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd", boxSizing: "border-box" }}
            rows={3}
          />
        </div>
        <div style={{ marginBottom: "15px" }}>
          <input
            type="number"
            name="hourlyRate"
            placeholder="Hourly Rate"
            value={formData.hourlyRate}
            onChange={handleChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
            min="0"
            step="0.01"
            required
          />
        </div>
        <button 
          type="submit" 
          style={{ 
            backgroundColor: "#007bff", 
            color: "white", 
            padding: "10px 20px", 
            border: "none", 
            borderRadius: "4px", 
            cursor: "pointer" 
          }}
        >
          {editingId ? "Update Project" : "Create Project"}
        </button>
        {editingId && (
          <button 
            type="button" 
            onClick={() => {
              setEditingId(null);
              resetForm();
            }}
            style={{ 
              backgroundColor: "#6c757d", 
              color: "white", 
              padding: "10px 20px", 
              border: "none", 
              borderRadius: "4px", 
              cursor: "pointer", 
              marginLeft: "10px" 
            }}
          >
            Cancel
          </button>
        )}
      </form>

      <h2 style={{ textAlign: "center" }}>Your Projects</h2>
      {projects.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No projects found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {projects.map((project) => (
            <div 
              key={project.id} 
              style={{ 
                border: "1px solid #ccc", 
                borderRadius: "8px", 
                padding: "15px", 
                display: "flex", 
                justifyContent: "space-between", 
                alignItems: "center" 
              }}
            >
              <div>
                <h3 style={{ margin: "0 0 5px 0" }}>{project.name}</h3>
                <p style={{ margin: "0 0 5px 0", color: "#666" }}>{project.description}</p>
                <p style={{ margin: "0", color: "#666" }}>
                  Hourly Rate: ${project.hourlyRate.toFixed(2)}
                </p>
              </div>
              <div style={{ display: "flex", gap: "10px" }}>
                <button 
                  onClick={() => handleEdit(project)}
                  style={{ 
                    backgroundColor: "#28a745", 
                    color: "white", 
                    padding: "5px 10px", 
                    border: "none", 
                    borderRadius: "4px", 
                    cursor: "pointer" 
                  }}
                >
                  Edit
                </button>
                <button 
                  onClick={() => handleDelete(project.id)}
                  style={{ 
                    backgroundColor: "#dc3545", 
                    color: "white", 
                    padding: "5px 10px", 
                    border: "none", 
                    borderRadius: "4px", 
                    cursor: "pointer" 
                  }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "./backend/src/db/houseplant-watering.db"
);

export interface WateringEvent {
  id: number;
  plant_id: number;
  timestamp: string;
  operator_id: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS watering_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    plant_id INTEGER NOT NULL,
    timestamp TEXT NOT NULL,
    operator_id INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllWateringEvents(): WateringEvent[] {
  const stmt = db.prepare(
    "SELECT * FROM watering_events ORDER BY timestamp DESC"
  );
  return stmt.all() as unknown as WateringEvent[];
}

export function getWateringEventById(id: number): WateringEvent | undefined {
  const stmt = db.prepare(
    "SELECT * FROM watering_events WHERE id = ?"
  );
  return stmt.get(id) as unknown as WateringEvent | undefined;
}

export function insertWateringEvent(
  plantId: number,
  timestamp: string,
  operatorId: number
): number {
  const stmt = db.prepare(
    "INSERT INTO watering_events (plant_id, timestamp, operator_id) VALUES (?, ?, ?)"
  );
  const result = stmt.run(plantId, timestamp, operatorId);
  return Number(result.lastInsertRowid);
}

export function updateWateringEvent(
  id: number,
  plantId: number,
  timestamp: string,
  operatorId: number
): void {
  const stmt = db.prepare(
    "UPDATE watering_events SET plant_id = ?, timestamp = ?, operator_id = ? WHERE id = ?"
  );
  stmt.run(plantId, timestamp, operatorId, id);
}

export function deleteWateringEvent(id: number): void {
  const stmt = db.prepare("DELETE FROM watering_events WHERE id = ?");
  stmt.run(id);
}

// Sample data insertion
if (getAllWateringEvents().length === 0) {
  insertWateringEvent(1, "2023-05-15T08:30:00Z", 101);
