{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check role-based access for POST, PUT, DELETE requests to booking routes
  const isBookingRequest = req.method === "POST" || req.method === "PUT" || req.method === "DELETE";
  const isBookingPath = req.path.startsWith("/bookings");

  if (!isBookingRequest || !isBookingPath) {
    next();
    return;
  }

  // Check if user has admin role
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // Simple token validation (in a real app, you'd decode and verify properly)
  const [payload, signature] = token.split(".");

  if (!payload || !signature) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  // Create expected signature
  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64url");

  // Verify signature using timingSafeEqual to prevent timing attacks
  const signatureBuffer = Buffer.from(signature, "base64url");
  const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

  try {
    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  // In a real implementation, we would decode the payload to check roles
  // For now, we'll assume valid token means admin access
  next();
}
"}

