{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteReservation,
  getAllReservations,
  getReservationById,
  insertReservation,
  updateReservation
} from "../db/reservations-table";

export const router = Router();

// Get all reservations for the current member
router.get("/", (req: Request, res: Response) => {
  try {
    const reservations = getAllReservations();
    return res.json(reservations);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch reservations" });
  }
});

// Get a specific reservation by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid reservation ID" });
  }

  const reservation = getReservationById(id);

  if (!reservation) {
    return res.status(404).json({ error: "Reservation not found" });
  }

  return res.json(reservation);
});

// Create a new reservation
router.post("/", (req: Request, res: Response) => {
  const { vendorId, stallNumber, weekendDate } = req.body;

  if (!vendorId || !stallNumber || !weekendDate) {
    return res.status(400).json({ error: "Missing required fields: vendorId, stallNumber, weekendDate" });
  }

  try {
    const id = insertReservation(vendorId, stallNumber, weekendDate);
    const newReservation = getReservationById(id);

    if (!newReservation) {
      return res.status(500).json({ error: "Failed to create reservation" });
    }

    return res.status(201).json(newReservation);
  } catch (error) {
    return res.status(500).json({ error: "Failed to create reservation" });
  }
});

// Update an existing reservation
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { vendorId, stallNumber, weekendDate } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid reservation ID" });
  }

  if (!vendorId || !stallNumber || !weekendDate) {
    return res.status(400).json({ error: "Missing required fields: vendorId, stallNumber, weekendDate" });
  }

  const existingReservation = getReservationById(id);

  if (!existingReservation) {
    return res.status(404).json({ error: "Reservation not found" });
  }

  try {
    updateReservation(id, vendorId, stallNumber, weekendDate);
    const updatedReservation = getReservationById(id);

    if (!updatedReservation) {
      return res.status(500).json({ error: "Failed to update reservation" });
    }

    return res.json(updatedReservation);
  } catch (error) {
    return res.status(500).json({ error: "Failed to update reservation" });
  }
});

// Delete a reservation
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid reservation ID" });
  }

  const existingReservation = getReservationById(id);

  if (!existingReservation) {
    return res.status(404).json({ error: "Reservation not found" });
  }

  try {
    deleteReservation(id);
    return res.json({ message: "Reservation deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete reservation" });
  }
});
"}

