export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockAuthors = [
  { id: 1, name: "John Doe", email: "john@example.com" },
  { id: 2, name: "Jane Smith", email: "jane@example.com" }
];

const findAuthorIndex = (id: number) => {
  return mockAuthors.findIndex(author => author.id === id);
};

// GET /authors - List all authors
router.get("/authors", (req: Request, res: Response) => {
  res.json(mockAuthors);
});

// GET /authors/:id - Get one author by ID
router.get("/authors/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const authorIndex = findAuthorIndex(id);

  if (authorIndex === -1) {
    return res.status(404).json({ error: "Author not found" });
  }

  res.json(mockAuthors[authorIndex]);
});

// POST /authors - Create a new author
router.post("/authors", (req: Request, res: Response) => {
  const { name, email } = req.body;

  if (!name || !email) {
    return res.status(400).json({ error: "Name and email are required" });
  }

  const newId = Math.max(...mockAuthors.map(a => a.id)) + 1;
  const newAuthor = { id: newId, name, email };

  mockAuthors.push(newAuthor);

  res.status(201).json(newAuthor);
});

// PUT /authors/:id - Update an existing author
router.put("/authors/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const authorIndex = findAuthorIndex(id);

  if (authorIndex === -1) {
    return res.status(404).json({ error: "Author not found" });
  }

  const { name, email } = req.body;

  if (!name || !email) {
    return res.status(400).json({ error: "Name and email are required" });
  }

  mockAuthors[authorIndex] = { id, name, email };

  res.json(mockAuthors[authorIndex]);
});

// DELETE /authors/:id - Delete an author
router.delete("/authors/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const authorIndex = findAuthorIndex(id);

  if (authorIndex === -1) {
    return res.status(404).json({ error: "Author not found" });
  }

  mockAuthors.splice(authorIndex, 1);

  res.json({ message: "Author deleted successfully" });
});
