  const [error, setError] = useState<string | null>(null);
  const [newRoomCode, setNewRoomCode] = useState("");
  const [joinCode, setJoinCode] = useState("");

  useEffect(() => {
    fetchRooms();
  }, []);

  const fetchRooms = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/trivia-game-engine/rooms");
      if (!response.ok) {
        throw new Error(`Failed to fetch rooms: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setRooms(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleCreateRoom = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newRoomCode.trim()) return;

    try {
      const response = await fetch(`/api/trivia-game-engine/rooms`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ code: newRoomCode }),
      });

      if (!response.ok) {
        throw new Error(`Failed to create room: ${response.status} ${response.statusText}`);
      }

      setNewRoomCode("");
      fetchRooms();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleJoinRoom = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!joinCode.trim()) return;

    try {
      const response = await fetch(`/api/trivia-game-engine/rooms/${joinCode}/player-count`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ playerCount: 1 }),
      });

      if (!response.ok) {
        throw new Error(`Failed to join room: ${response.status} ${response.statusText}`);
      }

      setJoinCode("");
      fetchRooms();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleLeaveRoom = async (code: string) => {
    try {
      const response = await fetch(`/api/trivia-game-engine/rooms/${code}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        throw new Error(`Failed to leave room: ${response.status} ${response.statusText}`);
      }

      fetchRooms();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
