{"code":"import { useEffect, useState } from "react";

interface Notification {
  id: string;
  topic: string;
  content: string;
  timestamp: string;
}

interface Topic {
  name: string;
}

export function NotificationWebUi() {
  const [topics, setTopics] = useState<Topic[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [newTopic, setNewTopic] = useState("");
  const [newMessage, setNewMessage] = useState("");
  const [selectedTopic, setSelectedTopic] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  // Fetch topics and notifications
  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      setError("");
      try {
        const [topicsRes, notificationsRes] = await Promise.all([
          fetch("/api/pub-sub-notification-server/topic/:topic"),
          fetch("/api/pub-sub-notification-server/message/:id"),
        ]);

        if (!topicsRes.ok || !notificationsRes.ok) {
          throw new Error("Failed to fetch data");
        }

        const topicsData = await topicsRes.json();
        const notificationsData = await notificationsRes.json();

        setTopics(topicsData);
        setNotifications(notificationsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handlePublish = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedTopic || !newMessage) return;

    setLoading(true);
    setError("");
    try {
      const res = await fetch(`/api/pub-sub-notification-server/publish/${selectedTopic}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ content: newMessage }),
      });

      if (!res.ok) {
        throw new Error("Failed to publish message");
      }

      // Refresh data
      const [topicsRes, notificationsRes] = await Promise.all([
        fetch("/api/pub-sub-notification-server/topic/:topic"),
        fetch("/api/pub-sub-notification-server/message/:id"),
      ]);

      if (!topicsRes.ok || !notificationsRes.ok) {
        throw new Error("Failed to refresh data");
      }

      const topicsData = await topicsRes.json();
      const notificationsData = await notificationsRes.json();

      setTopics(topicsData);
      setNotifications(notificationsData);
      setNewMessage("");
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    setLoading(true);
    setError("");
    try {
      const res = await fetch(`/api/pub-sub-notification-server/message/${id}`, {
        method: "DELETE",
      });

      if (!res.ok) {
        throw new Error("Failed to delete message");
      }

      // Refresh data
      const notificationsRes = await fetch("/api/pub-sub-notification-server/message/:id");
      if (!notificationsRes.ok) {
        throw new Error("Failed to refresh data");
      }

      const notificationsData = await notificationsRes.json();
      setNotifications(notificationsData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleCreateTopic = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTopic) return;

    setLoading(true);
    setError("");
    try {
      const res = await fetch(`/api/pub-sub-notification-server/publish/${newTopic}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ content: "" }),
      });

      if (!res.ok) {
        throw new Error("Failed to create topic");
      }

      // Refresh data
      const topicsRes = await fetch("/api/pub-sub-notification-server/topic/:topic");
      if (!topicsRes.ok) {
        throw new Error("Failed to refresh data");
      }

      const topicsData = await topicsRes.json();
      setTopics(topicsData);
      setNewTopic("");
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      maxWidth: 800,
      margin: "0 auto",
      padding: "20px",
      display: "flex",
      flexDirection: "column",
      gap: "20px",
    }}>
      <h1>Push Notification Service</h1>

      {error && <div style={{ color: "red" }}>{error}</div>}

      {loading && <div>Loading...</div>}

      <section>
        <h2>Create New Topic</h2>
        <form onSubmit={handleCreateTopic} style={{ display: "flex", gap: "10px" }}>
          <input
            type="text"
            value={newTopic}
            onChange={(e) => setNewTopic(e.target.value)}
            placeholder="Enter topic name"
            style={{ flex: 1, padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
          <button type="submit" style={{ padding: "8px 16px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}>
            Create Topic
          </button>
        </form>
      </section>

      <section>
        <h2>Publish Message</h2>
        <form onSubmit={handlePublish} style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          <select
            value={selectedTopic}
            onChange={(e) => setSelectedTopic(e.target.value)}
            style={{ padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          >
            <option value="">Select a topic</option>
            {topics.map((topic) => (
              <option key={topic.name} value={topic.name}>
                {topic.name}
              </option>
            ))}
          </select>
          <textarea
            value={newMessage}
            onChange={(e) => setNewMessage(e.target.value)}
            placeholder="Enter message content"
            style={{ padding: "8px", borderRadius: "4px", border: "1px solid #ccc", minHeight: "100px" }}
          />
          <button type="submit" style={{ padding: "8px 16px", backgroundColor: "#28a745", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}>
            Publish Message
          </button>
        </form>
      </section>

      <section>
        <h2>Recent Notifications</h2>
        {notifications.length === 0 ? (
          <p>No notifications found.</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {notifications.map((notification) => (
              <div
                key={notification.id}
                style={{
                  border: "1px solid #ccc",
                  borderRadius: "4px",
                  padding: "10px",
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                }}
              >
                <div>
                  <strong>{notification.topic}</strong>
                  <br />
                  {notification.content}
                  <br />
                  <small>{new Date(notification.timestamp).toLocaleString()}</small>
                </div>
                <button
                  onClick={() => handleDelete(notification.id)}
                  style={{
                    padding: "4px 8px",
                    backgroundColor: "#dc3545",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    cursor: "pointer",
                  }}
                >
                  Delete
                </button>
              </div>
            ))}
          </div>
        )}
      </section>
    </div>
  );
}
"}

