const authenticateUser = (req: Request, res: Response, next: Function) => {
  // In a real app, this would verify JWT or session token
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
  }

  // For demo purposes, we'll just proceed
  next();
};

// Role-based authorization middleware
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    // In a real app, this would extract role from token
    const userRole = req.body.role || "assistant"; // mock role extraction

    if (userRole !== requiredRole) {
      return res.status(403).json({ error: "Forbidden: Insufficient permissions" });
    }

    next();
  };
};

// POST /login - Authenticate user and return token
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // In a real app, this would generate a JWT token
  const token = `mock-jwt-token-for-${user.username}`;

  return res.json({
    token,
    user: {
      id: user.id,
      username: user.username,
      role: user.role
    }
  });
});

// GET /profile - Get authenticated user profile
router.get("/profile", authenticateUser, (req: Request, res: Response) => {
  // In a real app, this would decode the token to get user info
  const userId = 1; // mock user ID

  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  return res.json({
    id: user.id,
    username: user.username,
    role: user.role
  });
});

// GET /staff - Get all staff members (requires manager role)
router.get("/staff", authenticateUser, requireRole("manager"), (req: Request, res: Response) => {
  // Return all users except admin (for demo purposes)
  const staffMembers = users.filter(user => user.role !== "manager");

  return res.json(staffMembers);
});

// POST /staff - Create new staff member (requires manager role)
router.post("/staff", authenticateUser, requireRole("manager"), (req: Request, res: Response) => {
  const { username, password, role } = req.body;

  if (!username || !password || !role) {
    return res.status(400).json({ error: "Username, password, and role are required" });
  }

  // Check if username already exists
  const existingUser = users.find(u => u.username === username);

  if (existingUser) {
    return res.status(409).json({ error: "Username already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    username,
    password,
    role
  };

  users.push(newUser);

  return res.status(201).json(newUser);
});
