  uploadedAt: string;
}

const initSql = `
  CREATE TABLE IF NOT EXISTS items (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    description TEXT,
    locationId INTEGER NOT NULL,
    documentId INTEGER,
    FOREIGN KEY (locationId) REFERENCES locations (id),
    FOREIGN KEY (documentId) REFERENCES documents (id)
  );

  CREATE TABLE IF NOT EXISTS locations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    description TEXT
  );

  CREATE TABLE IF NOT EXISTS documents (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    filename TEXT NOT NULL,
    path TEXT NOT NULL,
    uploadedAt TEXT NOT NULL
  );
`;

db.exec(initSql);

export function getAllItems(): Item[] {
  const stmt = db.prepare(`SELECT * FROM items`);
  return stmt.all() as unknown as Item[];
}

export function getItemById(id: number): Item | undefined {
  const stmt = db.prepare(`SELECT * FROM items WHERE id = ?`);
  return stmt.get(id) as unknown as Item | undefined;
}

export function insertItem(item: Omit<Item, "id">): number {
  const stmt = db.prepare(
    `INSERT INTO items (name, description, locationId, documentId) VALUES (?, ?, ?, ?)`
  );
  const result = stmt.run(item.name, item.description, item.locationId, item.documentId);
  return Number(result.lastInsertRowid);
}

export function updateItem(id: number, item: Partial<Omit<Item, "id">>): boolean {
  const fields = [];
  const values = [];

  if (item.name !== undefined) {
    fields.push("name = ?");
    values.push(item.name);
  }
  if (item.description !== undefined) {
    fields.push("description = ?");
    values.push(item.description);
  }
  if (item.locationId !== undefined) {
    fields.push("locationId = ?");
    values.push(item.locationId);
  }
  if (item.documentId !== undefined) {
    fields.push("documentId = ?");
    values.push(item.documentId);
  }

  if (fields.length === 0) return false;

  values.push(id);
  const sql = `UPDATE items SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);
  return true;
}

export function deleteItem(id: number): boolean {
  const stmt = db.prepare(`DELETE FROM items WHERE id = ?`);
  const result = stmt.run(id);
  return result.changes > 0;
}

// Sample data initialization
if (getAllItems().length === 0) {
  const locationIds = [1, 2, 3];
  const documentIds = [1, 2];

