      }
      const data = await response.json();
      setRehearsals(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleCreateRehearsal = async (e: React.FormEvent) => {
    e.preventDefault();
