{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock reservation data storage
let reservations: any[] = [];
let nextId = 1;

// Helper to find reservation by ID
const findReservationIndex = (id: string) => {
  return reservations.findIndex(res => res.id === id);
};

// GET /reservations - List all reservations
router.get("/reservations", (req: Request, res: Response) => {
  res.json(reservations);
});

// GET /reservations/:id - Get a specific reservation by ID
router.get("/reservations/:id", (req: Request, res: Response) => {
  const index = findReservationIndex(req.params.id);
  if (index === -1) {
    return res.status(404).json({ error: "Reservation not found" });
  }
  res.json(reservations[index]);
});

// POST /reservations - Create a new reservation
router.post("/reservations", (req: Request, res: Response) => {
  const { gameId, date, time, playerCount, customerName } = req.body;

  // Basic validation
  if (!gameId || !date || !time || !playerCount || !customerName) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  // Check for conflicts (simplified)
  const existingConflict = reservations.some(res => 
    res.date === date && res.time === time
  );

  if (existingConflict) {
    return res.status(400).json({ error: "Time slot already reserved" });
  }

  const newReservation = {
    id: nextId.toString(),
    gameId,
    date,
    time,
    playerCount,
    customerName,
    createdAt: new Date().toISOString()
  };

  reservations.push(newReservation);
  nextId++;

  res.status(201).json(newReservation);
});

// PUT /reservations/:id - Update a reservation
router.put("/reservations/:id", (req: Request, res: Response) => {
  const index = findReservationIndex(req.params.id);

  if (index === -1) {
    return res.status(404).json({ error: "Reservation not found" });
  }

  const { gameId, date, time, playerCount, customerName } = req.body;

  // Basic validation
  if (!gameId || !date || !time || !playerCount || !customerName) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  // Check for conflicts (simplified)
  const existingConflict = reservations.some(res => 
    res.id !== req.params.id && res.date === date && res.time === time
  );

  if (existingConflict) {
    return res.status(400).json({ error: "Time slot already reserved" });
  }

  reservations[index] = {
    ...reservations[index],
    gameId,
    date,
    time,
    playerCount,
    customerName,
    updatedAt: new Date().toISOString()
  };

  res.json(reservations[index]);
});

// DELETE /reservations/:id - Cancel a reservation
router.delete("/reservations/:id", (req: Request, res: Response) => {
  const index = findReservationIndex(req.params.id);

  if (index === -1) {
    return res.status(404).json({ error: "Reservation not found" });
  }

  reservations.splice(index, 1);

  res.json({ message: "Reservation cancelled successfully" });
});
"}

