      padding: "10px 16px",
      backgroundColor: "#007bff",
      color: "white",
      border: "none",
      borderRadius: "4px",
      cursor: "pointer",
    },
    recipeList: {
      marginTop: "20px",
    },
    recipeCard: {
      border: "1px solid #ddd",
      borderRadius: "8px",
      padding: "16px",
      marginBottom: "10px",
    },
    noRecipes: {
      textAlign: "center" as const,
