{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data structures to simulate database operations
const inventory = [
  { id: 1, name: "Cotton Fabric", quantity: 100, price: 15 },
  { id: 2, name: "Silk Fabric", quantity: 50, price: 30 },
  { id: 3, name: "Wool Yarn", quantity: 75, price: 10 }
];

const bills = [] as any[];

// Helper function to find item by ID
const findItemById = (id: number) => {
  return inventory.find(item => item.id === id);
};

// Create a new bill
router.post("/bills", (req: Request, res: Response) => {
  const { items } = req.body;

  if (!items || !Array.isArray(items)) {
    return res.status(400).json({ error: "Items array is required" });
  }

  let total = 0;
  const updatedInventory = [...inventory];
  const billItems = items.map((item: any) => {
    const inventoryItem = findItemById(item.id);
    if (!inventoryItem) {
      throw new Error(`Item with id ${item.id} not found`);
    }

    if (inventoryItem.quantity < item.quantity) {
      throw new Error(`Not enough ${inventoryItem.name} in stock`);
    }

    const itemTotal = inventoryItem.price * item.quantity;
    total += itemTotal;

    // Update inventory
    const updatedItemIndex = updatedInventory.findIndex(i => i.id === item.id);
    updatedInventory[updatedItemIndex].quantity -= item.quantity;

    return {
      id: item.id,
      name: inventoryItem.name,
      quantity: item.quantity,
      price: inventoryItem.price,
      total: itemTotal
    };
  });

  const newBill = {
    id: bills.length + 1,
    items: billItems,
    total,
    timestamp: new Date().toISOString()
  };

  bills.push(newBill);

  res.status(201).json(newBill);
});

// Get all bills
router.get("/bills", (req: Request, res: Response) => {
  res.json(bills);
});

// Get a specific bill by ID
router.get("/bills/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const bill = bills.find(b => b.id === id);

  if (!bill) {
    return res.status(404).json({ error: "Bill not found" });
  }

  res.json(bill);
});

// Update a bill (not implemented for simplicity)
router.put("/bills/:id", (req: Request, res: Response) => {
  return res.status(405).json({ error: "Method not allowed" });
});

// Delete a bill (not implemented for simplicity)
router.delete("/bills/:id", (req: Request, res: Response) => {
  return res.status(405).json({ error: "Method not allowed" });
});
"}

