{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./seed-library.db");

interface Checkout {
  id: number;
  memberId: number;
  seedPacketId: number;
  dueDate: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS checkouts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    memberId INTEGER NOT NULL,
    seedPacketId INTEGER NOT NULL,
    dueDate TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllCheckouts(): Checkout[] {
  const stmt = db.prepare("SELECT * FROM checkouts");
  return stmt.all() as unknown as Checkout[];
}

export function getCheckoutById(id: number): Checkout | undefined {
  const stmt = db.prepare("SELECT * FROM checkouts WHERE id = ?");
  return stmt.get(id) as unknown as Checkout | undefined;
}

export function insertCheckout(
  memberId: number,
  seedPacketId: number,
  dueDate: string
): number {
  const stmt = db.prepare(
    "INSERT INTO checkouts (memberId, seedPacketId, dueDate) VALUES (?, ?, ?)"
  );
  const result = stmt.run(memberId, seedPacketId, dueDate);
  return Number(result.lastInsertRowid);
}

export function updateCheckout(
  id: number,
  memberId: number,
  seedPacketId: number,
  dueDate: string
): number {
  const stmt = db.prepare(
    "UPDATE checkouts SET memberId = ?, seedPacketId = ?, dueDate = ? WHERE id = ?"
  );
  const result = stmt.run(memberId, seedPacketId, dueDate, id);
  return Number(result.changes);
}

export function deleteCheckout(id: number): number {
  const stmt = db.prepare("DELETE FROM checkouts WHERE id = ?");
  const result = stmt.run(id);
  return Number(result.changes);
}

