  const files = Array.from(storedFiles.entries()).map(([id, file]) => ({
    id,
    name: file.name
  }));

  return res.json(files);
});

// PUT /files/:id - Update a file by ID
router.put("/files/:id", (req: Request, res: Response) => {
  const fileId = req.params.id;

  if (!storedFiles.has(fileId)) {
    return res.status(404).json({ error: "File not found" });
  }

  if (!req.body.name || !req.body.contentType) {
    return res.status(400).json({ error: "Name and contentType are required" });
  }

  const existingFile = storedFiles.get(fileId)!;

  storedFiles.set(fileId, {
    name: req.body.name,
    data: existingFile.data,
    contentType: req.body.contentType
  });

  return res.json({ id: fileId, name: req.body.name });
});

// DELETE /files/:id - Delete a file by ID
router.delete("/files/:id", (req: Request, res: Response) => {
  const fileId = req.params.id;

