{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST, PUT, DELETE, PATCH requests
  if (!['POST', 'PUT', 'DELETE', 'PATCH'].includes(req.method)) {
    next();
    return;
  }

  // Check if JWT_SECRET is set
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  // Get the Authorization header
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  // Verify the token signature
  try {
    const [header, payload, signature] = token.split(".");
    if (!header || !payload || !signature) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    // Create expected signature
    const expectedSignature = createHmac("sha256", secret)
      .update(`${header}.${payload}`)
      .digest("base64url");

    // Use timingSafeEqual to prevent timing attacks
    const signatureBuffer = Buffer.from(signature, "base64url");
    const expectedSignatureBuffer = Buffer.from(expectedSignature, "base64url");

    if (!timingSafeEqual(signatureBuffer, expectedSignatureBuffer)) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    // If we get here, the token is valid
    next();
  } catch (err) {
    res.status(401).json({ error: "Unauthorized" });
  }
}
"}

{"code":"import { useEffect, useState } from "react";

interface Car {
  id: number;
  make: string;
  model: string;
  year: number;
  color: string;
  dailyRate: number;
  availability: boolean;
}

export function CarListPage() {
  const [cars, setCars] = useState<Car[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filter, setFilter] = useState({
    make: "",
    model: "",
    minYear: "",
    maxYear: "",
    minRate: "",
    maxRate: "",
  });

  useEffect(() => {
    fetchCars();
  }, []);

  const fetchCars = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/cars");
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setCars(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFilter({
      ...filter,
      [name]: value,
    });
  };

  const filteredCars = cars.filter(car => {
    const makeMatch = filter.make === "" || car.make.toLowerCase().includes(filter.make.toLowerCase());
    const modelMatch = filter.model === "" || car.model.toLowerCase().includes(filter.model.toLowerCase());
    const yearMatch = 
      (filter.minYear === "" || car.year >= parseInt(filter.minYear)) &&
      (filter.maxYear === "" || car.year <= parseInt(filter.maxYear));
    const rateMatch = 
      (filter.minRate === "" || car.dailyRate >= parseFloat(filter.minRate)) &&
      (filter.maxRate === "" || car.dailyRate <= parseFloat(filter.maxRate));

    return makeMatch && modelMatch && yearMatch && rateMatch;
  });

  const handleBook = async (carId: number) => {
    try {
      const response = await fetch(`/api/cars/${carId}/book`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ carId }),
      });
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      // Refresh the car list after booking
      await fetchCars();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "system-ui, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Available Cars</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          name="make"
          placeholder="Filter by Make"
          value={filter.make}
          onChange={handleFilterChange}
          style={{ width: "100%", padding: "8px" }}
        />
        <input
          type="text"
          name="model"
          placeholder="Filter by Model"
          value={filter.model}
          onChange={handleFilterChange}
          style={{ width: "100%", padding: "8px" }}
        />
        <div style={{ display: "flex", gap: "10px" }}>
          <input
            type="number"
            name="minYear"
            placeholder="Min Year"
            value={filter.minYear}
            onChange={handleFilterChange}
            style={{ width: "100%", padding: "8px" }}
          />
          <input
            type="number"
            name="maxYear"
            placeholder="Max Year"
            value={filter.maxYear}
            onChange={handleFilterChange}
            style={{ width: "100%", padding: "8px" }}
          />
        </div>
        <div style={{ display: "flex", gap: "10px" }}>
          <input
            type="number"
            name="minRate"
            placeholder="Min Rate"
            value={filter.minRate}
            onChange={handleFilterChange}
            style={{ width: "100%", padding: "8px" }}
          />
          <input
            type="number"
            name="maxRate"
            placeholder="Max Rate"
            value={filter.maxRate}
            onChange={handleFilterChange}
            style={{ width: "100%", padding: "8px" }}
          />
        </div>
      </div>

      {filteredCars.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No cars available.</p>
      ) : (
        <div style={{ display: "flex", flexWrap: "wrap", gap: "15px" }}>
          {filteredCars.map(car => (
            <div 
              key={car.id} 
              style={{ 
                border: "1px solid #ccc", 
                borderRadius: "8px", 
                padding: "15px", 
                width: "calc(50% - 15px)", 
                boxSizing: "border-box" 
              }}
            >
              <h3>{car.make} {car.model}</h3>
              <p>Year: {car.year}</p>
              <p>Color: {car.color}</p>
              <p>Daily Rate: ${car.dailyRate}</p>
              <button 
                onClick={() => handleBook(car.id)}
                disabled={!car.availability}
                style={{ 
                  backgroundColor: car.availability ? "#007bff" : "#ccc", 
                  color: "white", 
                  border: "none", 
                  borderRadius: "4px", 
                  padding: "8px 12px", 
                  cursor: car.availability ? "pointer" : "default" 
                }}
              >
                {car.availability ? "Book Now" : "Not Available"}
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

