  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newToolName, setNewToolName] = useState("");

  useEffect(() => {
    fetchCheckouts();
  }, []);

  const fetchCheckouts = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/tool-checkouts-api/');
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setCheckouts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleCheckout = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newToolName.trim()) return;

    try {
      const response = await fetch('/api/tool-checkouts-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ toolName: newToolName }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      setNewToolName("");
      fetchCheckouts();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleReturn = async (id: number) => {
    try {
      const response = await fetch(`/api/tool-checkouts-api/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ returnDate: new Date().toISOString() }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      fetchCheckouts();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/tool-checkouts-api/${id}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      fetchCheckouts();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ maxWidth: 600, margin: '0 auto', padding: 20 }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ maxWidth: 600, margin: '0 auto', padding: 20 }}>
        <p>Error: {error}</p>
      </div>
    );
  }

  return (
    <div style={{ maxWidth: 600, margin: '0 auto', padding: 20, fontFamily: 'system-ui, sans-serif' }}>
      <h1>Tool Checkout</h1>

      <form onSubmit={handleCheckout} style={{ marginBottom: 20 }}>
        <input
          type="text"
          value={newToolName}
          onChange={(e) => setNewToolName(e.target.value)}
          placeholder="Enter tool name"
          style={{ width: '100%', padding: 8, marginBottom: 10, borderRadius: 4, border: '1px solid #ccc' }}
        />
        <button 
          type="submit" 
          style={{ 
            backgroundColor: '#007bff', 
            color: 'white', 
            border: 'none', 
            padding: '8px 16px', 
            borderRadius: 4, 
            cursor: 'pointer' 
          }}
        >
          Checkout Tool
        </button>
      </form>

      {checkouts.length === 0 ? (
        <p>No tool checkouts found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
          {checkouts.map((checkout) => (
            <div 
              key={checkout.id} 
              style={{ 
                border: '1px solid #ccc', 
                borderRadius: 8, 
                padding: 15, 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center', 
                flexWrap: 'wrap'
              }}
            >
              <div>
                <strong>{checkout.toolName}</strong><br />
                Checked out: {new Date(checkout.checkoutDate).toLocaleDateString()}<br />
                {checkout.returnDate ? (
                  <span>Returned: {new Date(checkout.returnDate).toLocaleDateString()}</span>
                ) : (
                  <span style={{ color: 'green' }}>Not returned yet</span>
                )}
              </div>
              <div style={{ display: 'flex', gap: 5, flexWrap: 'wrap' }}>
                {!checkout.returnDate && (
                  <button 
                    onClick={() => handleReturn(checkout.id)}
                    style={{ 
                      backgroundColor: '#28a745', 
                      color: 'white', 
                      border: 'none', 
                      padding: '4px 8px', 
                      borderRadius: 4, 
                      cursor: 'pointer' 
                    }}
                  >
                    Return
                  </button>
                )}
                <button 
                  onClick={() => handleDelete(checkout.id)}
                  style={{ 
                    backgroundColor: '#dc3545', 
                    color: 'white', 
                    border: 'none', 
                    padding: '4px 8px', 
                    borderRadius: 4, 
                    cursor: 'pointer' 
                  }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

