{"code":"import { useEffect, useState } from "react";

interface ExamResult {
  id: number;
  studentName: string;
  subject: string;
  score: number;
  date: string;
}

export function ExamResultsPage() {
  const [results, setResults] = useState<ExamResult[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [filterSubject, setFilterSubject] = useState("");

  useEffect(() => {
    fetchResults();
  }, []);

  const fetchResults = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/exam-results');
      if (!response.ok) {
        throw new Error('Failed to fetch exam results');
      }
      const data = await response.json();
      setResults(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const filteredResults = results.filter(result => {
    const matchesSearch = result.studentName.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          result.subject.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesSubject = filterSubject === '' || result.subject === filterSubject;
    return matchesSearch && matchesSubject;
  });

  const subjects = Array.from(new Set(results.map(r => r.subject)));

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Exam Results</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search by student name or subject..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        />

        <select
          value={filterSubject}
          onChange={(e) => setFilterSubject(e.target.value)}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="">All Subjects</option>
          {subjects.map(subject => (
            <option key={subject} value={subject}>{subject}</option>
          ))}
        </select>
      </div>

      {filteredResults.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No exam results found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {filteredResults.map(result => (
            <div 
              key={result.id} 
              style={{ 
                border: "1px solid #ddd", 
                borderRadius: "8px", 
                padding: "15px", 
                display: "flex", 
                justifyContent: "space-between", 
                alignItems: "center",
                flexWrap: "wrap"
              }}
            >
              <div style={{ flex: "1 1 300px", minWidth: "200px" }}>
                <h3 style={{ margin: "0 0 5px 0" }}>{result.studentName}</h3>
                <p style={{ margin: "0 0 5px 0", color: "#666" }}>{result.subject}</p>
                <p style={{ margin: "0 0 5px 0", color: "#666" }}>{result.date}</p>
              </div>
              <div style={{ flex: "1 1 100px", textAlign: "right" }}>
                <span style={{ fontSize: "18px", fontWeight: "bold" }}>{result.score}%</span>
              </div>
              <div style={{ flex: "1 1 100px", textAlign: "right", paddingLeft: "10px" }}>
                <button 
                  onClick={() => {
                    if (window.confirm(`Are you sure you want to delete ${result.studentName}'s result?`)) {
                      fetch(`/api/exam-results/${result.id}`, { method: "DELETE" })
                        .then(response => {
                          if (response.ok) {
                            fetchResults();
                          } else {
                            throw new Error("Failed to delete result");
                          }
                        })
                        .catch(err => setError(err instanceof Error ? err.message : "An unknown error occurred"));
                    }
                  }}
                  style={{ 
                    backgroundColor: "#dc3545", 
                    color: "white", 
                    border: "none", 
                    padding: "5px 10px", 
                    borderRadius: "4px", 
                    cursor: "pointer",
                    marginLeft: "5px"
                  }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = new Map<string, { email: string; password: string; role: string }>();

// Helper to generate mock JWT token
const generateToken = () => {
  return `token_${Math.random().toString(36).substring(2, 15)}`;
};

// Register route
router.post('/register', (req: Request, res: Response) => {
  const { email, password, role = 'user' } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password are required' });
  }

  if (users.has(email)) {
    return res.status(400).json({ error: 'User already exists' });
  }

  users.set(email, { email, password, role });
  const token = generateToken();

  return res.status(201).json({ token, email, role });
});

// Login route
router.post('/login', (req: Request, res: Response) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password are required' });
  }

  const user = users.get(email);

  if (!user || user.password !== password) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const token = generateToken();
  return res.json({ token, email, role: user.role });
});

// Middleware to verify token (mock)
const authenticate = (req: Request, res: Response, next: Function) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  // Mock verification - in real app, decode and validate JWT
  const user = Array.from(users.entries()).find(([_, u]) => 
    generateToken() === token
  );

  if (!user) {
    return res.status(401).json({ error: 'Invalid token' });
  }

  (req as any).userId = user[0];
  next();
};

// Get user profile
router.get('/profile', authenticate, (req: Request, res: Response) => {
  const userId = (req as any).userId;
  const user = users.get(userId);

  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  return res.json({ email: user.email, role: user.role });
});

// Update user role (admin only)
router.put('/role', authenticate, (req: Request, res: Response) => {
  const userId = (req as any).userId;
  const user = users.get(userId);

  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  if (user.role !== 'admin') {
    return res.status(403).json({ error: 'Admin access required' });
  }

  const { email, role } = req.body;

  if (!email || !role) {
    return res.status(400).json({ error: 'Email and role are required' });
  }

  const targetUser = users.get(email);

  if (!targetUser) {
    return res.status(404).json({ error: 'Target user not found' });
  }

  targetUser.role = role;
  users.set(email, targetUser);

  return res.json({ message: 'Role updated successfully' });
});
"}

