{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only enforce role-based access control on POST requests to visit routes
  if (!(req.method === "POST" && req.path.startsWith("/visits"))) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: "Internal Server Error: JWT_SECRET not configured" });
    return;
  }

  // Simple token validation - in a real app, you'd decode and verify the JWT properly
  // For this implementation, we'll just check if it has a valid structure
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  // Verify the signature using HMAC-SHA256
  const payloadAndSignature = parts[0] + "." + parts[1];
  const expectedSignature = createHmac("sha256", secret)
    .update(payloadAndSignature)
    .digest("base64url");

  try {
    const actualSignature = parts[2];
    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(actualSignature, "base64url");

    if (actualBuffer.length !== expectedBuffer.length || !timingSafeEqual(actualBuffer, expectedBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid token signature" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Token verification failed" });
    return;
  }

  // Check if user has required role
  const userRole = getUserRoleFromToken(token);
  if (!userRole || !hasRequiredRole(userRole)) {
    res.status(403).json({ error: "Forbidden: Insufficient role permissions" });
    return;
  }

  next();
}

function getUserRoleFromToken(token: string): string | null {
  // In a real implementation, this would decode the JWT and extract the role claim
  // For this example, we'll simulate role extraction
  try {
    const payload = token.split(".")[1];
    const decodedPayload = Buffer.from(payload, "base64url").toString("utf-8");
    const payloadObj = JSON.parse(decodedPayload);
    return payloadObj.role || null;
  } catch (err) {
    return null;
  }
}

function hasRequiredRole(role: string): boolean {
  // Define required roles for visit creation
  const requiredRoles = ["sales_rep", "manager", "admin"];
  return requiredRoles.includes(role);
}
"}

