export function getAllQuestions(): QuestionRow[] {
  const stmt = db.prepare("SELECT * FROM questions");
  return stmt.all() as unknown as QuestionRow[];
}

export function getQuestionById(id: number): QuestionRow | undefined {
  const stmt = db.prepare("SELECT * FROM questions WHERE id = ?");
  return stmt.get(id) as unknown as QuestionRow | undefined;
}

export function insertQuestion(questionText: string, correctAnswer: string): number {
  const stmt = db.prepare(
    "INSERT INTO questions (question_text, correct_answer) VALUES (?, ?)"
  );
  const result = stmt.run(questionText, correctAnswer);
  return Number(result.lastInsertRowid);
}

export function updateQuestion(id: number, questionText: string, correctAnswer: string): void {
  const stmt = db.prepare(
    "UPDATE questions SET question_text = ?, correct_answer = ? WHERE id = ?"
  );
  stmt.run(questionText, correctAnswer, id);
}

export function deleteQuestion(id: number): void {
  const stmt = db.prepare("DELETE FROM questions WHERE id = ?");
  stmt.run(id);
}

