  eventType: string,
  userId: number,
  timestamp: string,
  properties?: Record<string, unknown>
): number {
  const propertiesStr = properties ? JSON.stringify(properties) : null;
  const stmt = db.prepare(
    `INSERT INTO events (event_type, user_id, timestamp, properties) VALUES (?, ?, ?, ?)`
  );
  const result = stmt.run(eventType, userId, timestamp, propertiesStr);
  return Number(result.lastInsertRowid);
}

export function updateEvent(
  id: number,
  eventType?: string,
  userId?: number,
  timestamp?: string,
  properties?: Record<string, unknown>
): boolean {
  const updates: string[] = [];
  const params: (string | number | null)[] = [];

  if (eventType !== undefined) {
    updates.push("event_type = ?");
    params.push(eventType);
  }

  if (userId !== undefined) {
    updates.push("user_id = ?");
    params.push(userId);
  }

  if (timestamp !== undefined) {
    updates.push("timestamp = ?");
    params.push(timestamp);
  }

  if (properties !== undefined) {
    updates.push("properties = ?");
    params.push(JSON.stringify(properties));
  }

  if (updates.length === 0) return false;

  params.push(id);

  const sql = `UPDATE events SET ${updates.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  const result = stmt.run(...params);
  return result.changes > 0;
}

