{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to the SSO login endpoint
  if (req.method !== "POST" || req.path !== "/login/sso") {
    next();
    return;
  }

  // Check for SAML or OAuth2 headers
  const samlResponse = req.header("SAMLResponse");
  const oauth2Token = req.header("Authorization");

  // If neither SAML nor OAuth2 headers are present, skip validation
  if (!samlResponse && !oauth2Token) {
    next();
    return;
  }

  // For OAuth2 token validation, we need to verify the signature
  if (oauth2Token) {
    const secret = process.env.JWT_SECRET;
    if (!secret) {
      res.status(500).json({ error: "JWT secret not configured" });
      return;
    }

    // Simple token format check (assuming Bearer token)
    const [prefix, token] = oauth2Token.split(" ");
    if (prefix !== "Bearer" || !token) {
      res.status(401).json({ error: "Invalid token format" });
      return;
    }

    // In a real implementation, we would decode and verify the JWT signature
    // This is a simplified placeholder that just checks the token structure
    try {
      // This is a mock verification - in reality, you'd use a proper JWT library
      // and verify the HMAC-SHA256 signature using the secret
      const expectedSignature = createHmac("sha256", secret)
        .update(token.split(".")[0] + "." + token.split(".")[1])
        .digest("hex");

      // Mock signature comparison (in real code, use timingSafeEqual)
      const actualSignature = token.split(".")[2];

      // For demonstration purposes, we'll assume valid signature
      // In practice, compare with timingSafeEqual to prevent timing attacks
      if (expectedSignature !== actualSignature) {
        res.status(401).json({ error: "Invalid token signature" });
        return;
      }
    } catch (err) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }
  }

  // At this point, either SAML or OAuth2 validation passed
  // Proceed with normal processing
  next();
}
"}

