{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock session storage - in a real app this would be a proper session store
const sessions: Record<string, { userId: string }> = {};

// Mock user database - in a real app this would be a proper database
const users = [
  { id: "1", email: "user@example.com", password: "password123" },
];

// Helper to generate a mock session ID
const generateSessionId = () => Math.random().toString(36).substring(2, 15);

/**
 * POST /login - Authenticate a user and create a session
 */
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  // Find user by email
  const user = users.find(u => u.email === email);

  if (!user || user.password !== password) {
    return res.status(401).json({ error: "Invalid email or password" });
  }

  // Create a session
  const sessionId = generateSessionId();
  sessions[sessionId] = { userId: user.id };

  // Set session cookie
  res.cookie("sessionId", sessionId, { httpOnly: true, secure: false });

  return res.status(200).json({ message: "Login successful" });
});

/**
 * GET /logout - End the current user session
 */
router.get("/logout", (req: Request, res: Response) => {
  const sessionId = req.cookies.sessionId;

  if (sessionId && sessions[sessionId]) {
    delete sessions[sessionId];
  }

  res.clearCookie("sessionId");
  return res.status(200).json({ message: "Logout successful" });
});

/**
 * GET /me - Get the currently authenticated user
 */
router.get("/me", (req: Request, res: Response) => {
  const sessionId = req.cookies.sessionId;

  if (!sessionId || !sessions[sessionId]) {
    return res.status(401).json({ error: "Not authenticated" });
  }

  const userId = sessions[sessionId].userId;
  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  return res.status(200).json({ id: user.id, email: user.email });
});
"}

{"code":"import { useEffect, useState } from "react";

interface Keg {
  id: string;
  beerName: string;
  volume: number;
  status: "available" | "low" | "empty";
}

export function InventoryDashboard() {
  const [kegs, setKegs] = useState<Keg[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newKeg, setNewKeg] = useState({
    beerName: "",
    volume: 0,
  });

  useEffect(() => {
    fetchKegs();
  }, []);

  const fetchKegs = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/inventory-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status}`);
      }
      const data = await response.json();
      setKegs(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleAddKeg = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/inventory-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newKeg),
      });
      if (!response.ok) {
        throw new Error(`Failed to add: ${response.status}`);
      }
      setNewKeg({ beerName: "", volume: 0 });
      fetchKegs();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleFillKeg = async (id: string) => {
    try {
      const response = await fetch(`/api/inventory-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ volume: 100 }),
      });
      if (!response.ok) {
        throw new Error(`Failed to fill: ${response.status}`);
      }
      fetchKegs();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "system-ui, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Brewery Keg Inventory</h1>

      <div style={{ marginBottom: "30px" }}>
        <h2>Add New Keg</h2>
        <form onSubmit={handleAddKeg} style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          <input
            type="text"
            placeholder="Beer Name"
            value={newKeg.beerName}
            onChange={(e) => setNewKeg({ ...newKeg, beerName: e.target.value })}
            style={{ width: "100%", padding: "8px" }}
            required
          />
          <input
            type="number"
            placeholder="Volume (liters)"
            value={newKeg.volume || ""}
            onChange={(e) => setNewKeg({ ...newKeg, volume: Number(e.target.value) })}
            style={{ width: "100%", padding: "8px" }}
            required
          />
          <button type="submit" style={{ padding: "10px", backgroundColor: "#4CAF50", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}>
            Add Keg
          </button>
        </form>
      </div>

      <h2>Keg Inventory</h2>
      {kegs.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No kegs in inventory.</p>
      ) : (
        <div style={{ display: "flex", flexWrap: "wrap", gap: "15px" }}>
          {kegs.map((keg) => (
            <div key={keg.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px", width: "200px", boxSizing: "border-box" }}>
              <h3>{keg.beerName}</h3>
              <p>Volume: {keg.volume}L</p>
              <p>Status: {keg.status}</p>
              <button
                onClick={() => handleFillKeg(keg.id)}
                disabled={keg.status === "available"}
                style={{
                  padding: "8px 12px",
                  backgroundColor: keg.status === "available" ? "#ccc" : "#2196F3",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  cursor: keg.status === "available" ? "default" : "pointer",
                  marginTop: "10px",
                }}
              >
                Fill Keg
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

