  return (
    <div style={containerStyle}>
      <h1>Inventory Management</h1>

      <form onSubmit={editingId ? handleUpdate : handleSubmit} style={formStyle}>
        <h2>{editingId ? 'Edit Product' : 'Add New Product'}</h2>
