{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./studio-equipment.db");

interface EquipmentCheckout {
  id: number;
  equipment_id: number;
  user_id: number;
  checkout_date: string;
  return_date: string | null;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS equipment_checkouts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    equipment_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    checkout_date TEXT NOT NULL,
    return_date TEXT
  )
`;

db.exec(createTableSql);

export function getAllCheckouts(): EquipmentCheckout[] {
  const stmt = db.prepare(`SELECT * FROM equipment_checkouts`);
  return stmt.all() as unknown as EquipmentCheckout[];
}

export function getCheckoutById(id: number): EquipmentCheckout | undefined {
  const stmt = db.prepare(
    `SELECT * FROM equipment_checkouts WHERE id = ?`
  );
  return stmt.get(id) as unknown as EquipmentCheckout | undefined;
}

export function insertCheckout(
  equipmentId: number,
  userId: number,
  checkoutDate: string,
  returnDate: string | null
): number {
  const stmt = db.prepare(
    `INSERT INTO equipment_checkouts (equipment_id, user_id, checkout_date, return_date)
     VALUES (?, ?, ?, ?)`
  );
  const result = stmt.run(equipmentId, userId, checkoutDate, returnDate);
  return Number(result.lastInsertRowid);
}

export function updateCheckout(
  id: number,
  equipmentId: number,
  userId: number,
  checkoutDate: string,
  returnDate: string | null
): void {
  const stmt = db.prepare(
    `UPDATE equipment_checkouts 
     SET equipment_id = ?, user_id = ?, checkout_date = ?, return_date = ?
     WHERE id = ?`
  );
  stmt.run(equipmentId, userId, checkoutDate, returnDate, id);
}

export function deleteCheckout(id: number): void {
  const stmt = db.prepare(`DELETE FROM equipment_checkouts WHERE id = ?`);
  stmt.run(id);
}

// Sample data insertion
if (getAllCheckouts().length === 0) {
