{"code":"import { useEffect, useState } from "react";

interface Teacher {
  id: string;
  name: string;
  email: string;
  specialization: string;
  availability: string[];
}

export function TeacherManagement() {
  const [teachers, setTeachers] = useState<Teacher[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Form state
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [specialization, setSpecialization] = useState("");
  const [availability, setAvailability] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);

  // Fetch teachers
  useEffect(() => {
    const fetchTeachers = async () => {
      try {
        const response = await fetch("/api/teachers");
        if (!response.ok) {
          throw new Error(`Failed to fetch teachers: ${response.status}`);
        }
        const data = await response.json();
        setTeachers(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchTeachers();
  }, []);

  // Handle form submission
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const teacherData = {
      name,
      email,
      specialization,
      availability: availability.split(",").map(day => day.trim()),
    };

    try {
      const response = editingId 
        ? await fetch(`/api/teachers/${editingId}`, {
            method: "PUT",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(teacherData),
          })
        : await fetch("/api/teachers", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(teacherData),
          });

      if (!response.ok) {
        throw new Error(`Failed to ${editingId ? "update" : "create"} teacher: ${response.status}`);
      }

      // Reset form and reload data
      setName("");
      setEmail("");
      setSpecialization("");
      setAvailability("");
      setEditingId(null);

      const responseJson = await response.json();
      const updatedTeachers = editingId 
        ? teachers.map(t => t.id === editingId ? responseJson : t)
        : [...teachers, responseJson];

      setTeachers(updatedTeachers);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  // Handle edit
  const handleEdit = (teacher: Teacher) => {
    setName(teacher.name);
    setEmail(teacher.email);
    setSpecialization(teacher.specialization);
    setAvailability(teacher.availability.join(", "));
    setEditingId(teacher.id);
  };

  // Handle delete
  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/teachers/${id}`, { method: "DELETE" });
      if (!response.ok) {
        throw new Error(`Failed to delete teacher: ${response.status}`);
      }

      setTeachers(teachers.filter(teacher => teacher.id !== id));
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Teacher Management</h1>

      {/* Form */}
      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <div style={{ marginBottom: "15px" }}>
          <input
            type="text"
            placeholder="Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <input
            type="text"
            placeholder="Specialization"
            value={specialization}
            onChange={(e) => setSpecialization(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <input
            type="text"
            placeholder="Availability (comma separated)"
            value={availability}
            onChange={(e) => setAvailability(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
          />
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: "#007bff", 
            color: "white", 
            border: "none", 
            padding: "10px 20px", 
            borderRadius: "4px", 
            cursor: "pointer" 
          }}
        >
          {editingId ? "Update Teacher" : "Add Teacher"}
        </button>
      </form>

      {/* Teachers List */}
      <h2>Teachers</h2>

      {teachers.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No teachers found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {teachers.map((teacher) => (
            <div 
              key={teacher.id} 
              style={{ 
                border: "1px solid #ccc", 
                borderRadius: "8px", 
                padding: "15px", 
                display: "flex", 
                flexDirection: "column", 
                gap: "10px" 
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between" }}>
                <h3>{teacher.name}</h3>
                <div style={{ display: "flex", gap: "10px" }}>
                  <button 
                    onClick={() => handleEdit(teacher)}
                    style={{ 
                      backgroundColor: "#ffc107", 
                      color: "black", 
                      border: "none", 
                      padding: "5px 10px", 
                      borderRadius: "4px", 
                      cursor: "pointer" 
                    }}
                  >
                    Edit
                  </button>
                  <button 
                    onClick={() => handleDelete(teacher.id)}
                    style={{ 
                      backgroundColor: "#dc3545", 
                      color: "white", 
                      border: "none", 
                      padding: "5px 10px", 
                      borderRadius: "4px", 
                      cursor: "pointer" 
                    }}
                  >
                    Delete
                  </button>
                </div>
              </div>

              <p><strong>Email:</strong> {teacher.email}</p>
              <p><strong>Specialization:</strong> {teacher.specialization}</p>
              <p><strong>Availability:</strong> {teacher.availability.join(", ")}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

