{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockJobs = [
  { id: "1", title: "Web Development", description: "Build a responsive website", clientId: "client1", budget: 5000, status: "open" },
  { id: "2", title: "Mobile App Design", description: "Design a mobile app UI", clientId: "client2", budget: 3000, status: "closed" }
];

const mockApplications = [
  { id: "1", jobId: "1", freelancerId: "freelancer1", status: "pending" },
  { id: "2", jobId: "1", freelancerId: "freelancer2", status: "accepted" }
];

// Get all jobs
router.get("/jobs", (req: Request, res: Response) => {
  res.json(mockJobs);
});

// Get a specific job by ID
router.get("/jobs/:id", (req: Request, res: Response) => {
  const job = mockJobs.find(j => j.id === req.params.id);
  if (!job) {
    return res.status(404).json({ error: "Job not found" });
  }
  res.json(job);
});

// Create a new job
router.post("/jobs", (req: Request, res: Response) => {
  const { title, description, clientId, budget } = req.body;

  if (!title || !description || !clientId || !budget) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const newJob = {
    id: String(mockJobs.length + 1),
    title,
    description,
    clientId,
    budget,
    status: "open"
  };

  mockJobs.push(newJob);
  res.status(201).json(newJob);
});

// Update a job
router.put("/jobs/:id", (req: Request, res: Response) => {
  const jobIndex = mockJobs.findIndex(j => j.id === req.params.id);

  if (jobIndex === -1) {
    return res.status(404).json({ error: "Job not found" });
  }

  const { title, description, clientId, budget, status } = req.body;

  mockJobs[jobIndex] = {
    ...mockJobs[jobIndex],
    title: title || mockJobs[jobIndex].title,
    description: description || mockJobs[jobIndex].description,
    clientId: clientId || mockJobs[jobIndex].clientId,
    budget: budget || mockJobs[jobIndex].budget,
    status: status || mockJobs[jobIndex].status
  };

  res.json(mockJobs[jobIndex]);
});

// Delete a job
router.delete("/jobs/:id", (req: Request, res: Response) => {
  const jobIndex = mockJobs.findIndex(j => j.id === req.params.id);

  if (jobIndex === -1) {
    return res.status(404).json({ error: "Job not found" });
  }

  mockJobs.splice(jobIndex, 1);
  res.json({ message: "Job deleted successfully" });
});

// Get all applications for a job
router.get("/jobs/:id/applications", (req: Request, res: Response) => {
  const applications = mockApplications.filter(a => a.jobId === req.params.id);
  res.json(applications);
});

// Apply to a job
router.post("/jobs/:id/applications", (req: Request, res: Response) => {
  const { freelancerId } = req.body;

  if (!freelancerId) {
    return res.status(400).json({ error: "Missing freelancer ID" });
  }

  const newApplication = {
    id: String(mockApplications.length + 1),
    jobId: req.params.id,
    freelancerId,
    status: "pending"
  };

  mockApplications.push(newApplication);
  res.status(201).json(newApplication);
});

// Update application status
router.put("/applications/:id", (req: Request, res: Response) => {
  const applicationIndex = mockApplications.findIndex(a => a.id === req.params.id);

  if (applicationIndex === -1) {
    return res.status(404).json({ error: "Application not found" });
  }

  const { status } = req.body;

  if (!status) {
    return res.status(400).json({ error: "Missing status" });
  }

  mockApplications[applicationIndex] = {
    ...mockApplications[applicationIndex],
    status
  };

  res.json(mockApplications[applicationIndex]);
});
"}

