    },
    {
      id: 2,
      firstName: "Jane",
      lastName: "Smith",
      email: "jane.smith@example.com",
      position: "HR Manager",
      department: "Human Resources",
      salary: 65000,
      startDate: "2023-03-20"
    }
  ],

  getAllEmployees: (): Promise<any[]> => {
    return Promise.resolve(mockDatabase.employees);
  },

  getEmployeeById: (id: number): Promise<any | null> => {
    const employee = mockDatabase.employees.find(emp => emp.id === id);
    return Promise.resolve(employee || null);
  },

  createEmployee: (employeeData: any): Promise<any> => {
    const newEmployee = {
      id: mockDatabase.employees.length > 0 
        ? Math.max(...mockDatabase.employees.map(e => e.id)) + 1 
        : 1,
      ...employeeData
    };
    mockDatabase.employees.push(newEmployee);
    return Promise.resolve(newEmployee);
  },

  updateEmployee: (id: number, employeeData: any): Promise<any | null> => {
    const index = mockDatabase.employees.findIndex(emp => emp.id === id);
    if (index === -1) return Promise.resolve(null);

    mockDatabase.employees[index] = { ...mockDatabase.employees[index], ...employeeData };
    return Promise.resolve(mockDatabase.employees[index]);
  },

  deleteEmployee: (id: number): Promise<boolean> => {
    const initialLength = mockDatabase.employees.length;
    mockDatabase.employees = mockDatabase.employees.filter(emp => emp.id !== id);
    return Promise.resolve(mockDatabase.employees.length < initialLength);
  }
};

// GET /employees - List all employees
router.get("/employees", async (req: Request, res: Response) => {
  try {
    const employees = await mockDatabase.getAllEmployees();
    res.json(employees);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch employees" });
  }
});

// GET /employees/:id - Get one employee by ID
router.get("/employees/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid employee ID" });
    }

    const employee = await mockDatabase.getEmployeeById(id);
    if (!employee) {
      return res.status(404).json({ error: "Employee not found" });
    }

    res.json(employee);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch employee" });
  }
});

// POST /employees - Create a new employee
router.post("/employees", async (req: Request, res: Response) => {
  try {
    const { firstName, lastName, email, position, department, salary, startDate } = req.body;

    // Validate required fields
    if (!firstName || !lastName || !email || !position || !department || !salary || !startDate) {
      return res.status(400).json({ error: "Missing required fields: firstName, lastName, email, position, department, salary, startDate" });
    }

    const employeeData = {
      firstName,
      lastName,
      email,
      position,
