{"code":"import { Router, type Request, type Response } from "express";
import {
  createBooking,
  deleteBooking,
  getAllBookings,
  getBookingById,
  updateBookingStatus
} from "../db/bookings-table";

export const router = Router();

// Get all bookings
router.get("/bookings", (req: Request, res: Response) => {
  try {
    const bookings = getAllBookings();
    return res.json(bookings);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch bookings" });
  }
});

// Get a booking by ID
router.get("/bookings/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    const booking = getBookingById(id);
    if (!booking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    return res.json(booking);
  } catch (error) {
    return res.status(500).json({ error: "Failed to fetch booking" });
  }
});

// Create a new booking
router.post("/bookings", (req: Request, res: Response) => {
  try {
    const { eventTypeId, userName, userEmail, startTime, endTime } = req.body;

    if (!eventTypeId || !userName || !userEmail || !startTime || !endTime) {
      return res.status(400).json({
        error: "Missing required fields: eventTypeId, userName, userEmail, startTime, endTime"
      });
    }

    const id = createBooking(eventTypeId, userName, userEmail, startTime, endTime);
    return res.status(201).json({ id });
  } catch (error) {
    return res.status(500).json({ error: "Failed to create booking" });
  }
});

// Update booking status
router.put("/bookings/:id/status", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { status } = req.body;

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    if (!status || !['confirmed', 'pending', 'cancelled'].includes(status)) {
      return res.status(400).json({
        error: "Invalid status. Must be one of: confirmed, pending, cancelled"
      });
    }

    const booking = getBookingById(id);
    if (!booking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    updateBookingStatus(id, status as "confirmed" | "pending" | "cancelled");
    return res.json({ message: "Booking status updated successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to update booking status" });
  }
});

// Delete a booking
router.delete("/bookings/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    const booking = getBookingById(id);
    if (!booking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    deleteBooking(id);
    return res.json({ message: "Booking deleted successfully" });
  } catch (error) {
    return res.status(500).json({ error: "Failed to delete booking" });
  }
});
"}

