  } catch {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const userRole: UserRole = userData.role;
  if (!userRole || !(userRole in roles)) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // For this example, we'll assume required role is manager
  const requiredRole: UserRole = "manager";

