{"code":"import { useEffect, useState } from "react";

interface Donation {
  id: number;
  donor: string;
  item: string;
  quantity: number;
  date: string;
}

export function InventoryLogForm() {
  const [donations, setDonations] = useState<Donation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    donor: "",
    item: "",
    quantity: 1,
    date: new Date().toISOString().split("T")[0]
  });

  useEffect(() => {
    fetchDonations();
  }, []);

  const fetchDonations = async () => {
    try {
      const response = await fetch("/api/donations-api/");
      if (!response.ok) throw new Error("Failed to fetch donations");
      const data = await response.json();
      setDonations(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
      setLoading(false);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: name === "quantity" ? Number(value) : value
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/donations-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData)
      });
      if (!response.ok) throw new Error("Failed to add donation");
      await fetchDonations();
      setFormData({
        donor: "",
        item: "",
        quantity: 1,
        date: new Date().toISOString().split("T")[0]
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Log New Donation</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="donor" style={{ display: "block", marginBottom: "5px" }}>Donor Name:</label>
          <input
            type="text"
            id="donor"
            name="donor"
            value={formData.donor}
            onChange={handleChange}
            required
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="item" style={{ display: "block", marginBottom: "5px" }}>Item:</label>
          <input
            type="text"
            id="item"
            name="item"
            value={formData.item}
            onChange={handleChange}
            required
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="quantity" style={{ display: "block", marginBottom: "5px" }}>Quantity:</label>
          <input
            type="number"
            id="quantity"
            name="quantity"
            min="1"
            value={formData.quantity}
            onChange={handleChange}
            required
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="date" style={{ display: "block", marginBottom: "5px" }}>Date:</label>
          <input
            type="date"
            id="date"
            name="date"
            value={formData.date}
            onChange={handleChange}
            required
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
          />
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: "#007bff", 
            color: "white", 
            border: "none", 
            padding: "10px 20px", 
            borderRadius: "4px", 
            cursor: "pointer", 
            width: "100%" 
          }}
        >
          Add Donation
        </button>
      </form>

      <h2 style={{ textAlign: "center" }}>Recent Donations</h2>

      {donations.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>No donations logged yet.</p>
