        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {donations.map(donation => (
            <div 
              key={donation.id} 
              style={{ 
                border: "1px solid #ccc", 
                borderRadius: "8px", 
                padding: "15px", 
                display: "flex", 
                justifyContent: "space-between", 
                alignItems: "center" 
              }}
            >
              <div>
                <strong>{donation.donor}</strong> donated {donation.quantity} {donation.item}(s) on {new Date(donation.date).toLocaleDateString()}
