  const [auditTrail, setAuditTrail] = useState<AuditTrailEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  // Load check-ins and audit trail on component mount
  useEffect(() => {
    fetchCheckIns();
    fetchAuditTrail();
  }, []);

  const fetchCheckIns = async () => {
    setLoading(true);
    try {
      const response = await fetch("/api/check-in-api/");
      if (!response.ok) throw new Error("Failed to fetch check-ins");
      const data = await response.json();
      setCheckIns(data);
    } catch (err) {
      setError("Error loading check-ins: " + (err as Error).message);
    } finally {
      setLoading(false);
    }
  };

  const fetchAuditTrail = async () => {
    setLoading(true);
    try {
      const response = await fetch("/api/audit-trail-service/");
      if (!response.ok) throw new Error("Failed to fetch audit trail");
      const data = await response.json();
      setAuditTrail(data);
    } catch (err) {
      setError("Error loading audit trail: " + (err as Error).message);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError("");

    try {
      const response = await fetch("/api/check-in-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ memberId, dogName }),
      });

      if (!response.ok) throw new Error("Failed to check in dog");

      // Refresh data after successful check-in
      await fetchCheckIns();
      await fetchAuditTrail();

      // Reset form
      setMemberId("");
      setDogName("");
    } catch (err) {
      setError("Error checking in dog: " + (err as Error).message);
    } finally {
      setLoading(false);
    }
  };

  const formStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "16px",
    maxWidth: "500px",
    margin: "0 auto",
    padding: "20px",
