{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock complaint data storage
const complaints = [
  {
    id: 1,
    title: "Noise Pollution",
    description: "Loud construction work after 9 PM",
    status: "open",
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  },
  {
    id: 2,
    title: "Garbage Collection",
    description: "Missing garbage pickup this week",
    status: "in_progress",
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  }
];

// Helper to find complaint by ID
const findComplaintIndex = (id: number) => complaints.findIndex(complaint => complaint.id === id);

// GET /complaints - List all complaints
router.get("/complaints", (req: Request, res: Response) => {
  res.json(complaints);
});

// GET /complaints/:id - Get a specific complaint by ID
router.get("/complaints/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const index = findComplaintIndex(id);

  if (index === -1) {
    return res.status(404).json({ error: "Complaint not found" });
  }

  res.json(complaints[index]);
});

// POST /complaints - Create a new complaint
router.post("/complaints", (req: Request, res: Response) => {
  const { title, description } = req.body;

  if (!title || !description) {
    return res.status(400).json({ error: "Title and description are required" });
  }

  const newComplaint = {
    id: complaints.length > 0 ? Math.max(...complaints.map(c => c.id)) + 1 : 1,
    title,
    description,
    status: "open",
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };

  complaints.push(newComplaint);
  res.status(201).json(newComplaint);
});

// PUT /complaints/:id - Update a complaint
router.put("/complaints/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const index = findComplaintIndex(id);

  if (index === -1) {
    return res.status(404).json({ error: "Complaint not found" });
  }

  const { title, description, status } = req.body;

  // Validate status transition
  const currentStatus = complaints[index].status;
  if (status && !isValidStatusTransition(currentStatus, status)) {
    return res.status(400).json({ error: "Invalid status transition" });
  }

  // Update complaint
  complaints[index] = {
    ...complaints[index],
    title: title ?? complaints[index].title,
    description: description ?? complaints[index].description,
    status: status ?? complaints[index].status,
    updatedAt: new Date().toISOString()
  };

  res.json(complaints[index]);
});

// DELETE /complaints/:id - Delete a complaint
router.delete("/complaints/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const index = findComplaintIndex(id);

  if (index === -1) {
    return res.status(404).json({ error: "Complaint not found" });
  }

  complaints.splice(index, 1);
  res.json({ message: "Complaint deleted successfully" });
});

// Helper function to validate status transitions
function isValidStatusTransition(current: string, next: string): boolean {
  const validTransitions: Record<string, string[]> = {
    open: ["in_progress", "resolved"],
    in_progress: ["resolved"],
    resolved: []
  };

  return validTransitions[current]?.includes(next) ?? false;
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const JWT_SECRET = process.env.JWT_SECRET;

function isValidToken(token: string): boolean {
  if (!JWT_SECRET) return false;

  const parts = token.split(".");
  if (parts.length !== 3) return false;

  const [header, payload, signature] = parts;

  // Verify signature
  const expectedSignature = createHmac("sha256", JWT_SECRET)
    .update(`${header}.${payload}`)
    .digest("base64url");

  try {
    const expectedBuffer = Buffer.from(expectedSignature, "base64url");
    const actualBuffer = Buffer.from(signature, "base64url");

    return timingSafeEqual(expectedBuffer, actualBuffer);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only handle POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if token exists in Authorization header
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid token" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  if (!isValidToken(token)) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
    return;
  }

  // Token is valid, proceed to next middleware
  next();
}
"}

