{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "/tmp/garden-planner.db"
);

interface Plant {
  id: number;
  species: string;
  care_requirements: string;
  planting_date: string;
  location: string;
}

const createPlantsTable = () => {
  const sql = `
    CREATE TABLE IF NOT EXISTS plants (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      species TEXT NOT NULL,
      care_requirements TEXT NOT NULL,
      planting_date TEXT NOT NULL,
      location TEXT NOT NULL
    )
  `;
  db.exec(sql);
};

createPlantsTable();

export const getAllPlants = (): Plant[] => {
  const stmt = db.prepare(`SELECT * FROM plants`);
  return stmt.all() as unknown as Plant[];
};

export const getPlantById = (id: number): Plant | undefined => {
  const stmt = db.prepare(`SELECT * FROM plants WHERE id = ?`);
  return stmt.get(id) as unknown as Plant | undefined;
};

export const insertPlant = (
  species: string,
  careRequirements: string,
  plantingDate: string,
  location: string
): number => {
  const stmt = db.prepare(
    `INSERT INTO plants (species, care_requirements, planting_date, location) VALUES (?, ?, ?, ?)`
  );
  const result = stmt.run(species, careRequirements, plantingDate, location);
  return Number(result.lastInsertRowid);
};

export const updatePlant = (
  id: number,
  species: string,
  careRequirements: string,
  plantingDate: string,
  location: string
): number => {
  const stmt = db.prepare(
    `UPDATE plants SET species = ?, care_requirements = ?, planting_date = ?, location = ? WHERE id = ?`
  );
  const result = stmt.run(species, careRequirements, plantingDate, location, id);
  return Number(result.changes);
};

export const deletePlant = (id: number): number => {
  const stmt = db.prepare(`DELETE FROM plants WHERE id = ?`);
  const result = stmt.run(id);
  return Number(result.changes);
};

// Seed data
if (getAllPlants().length === 0) {
  insertPlant(
    "Tomato",
    "Full sun, regular watering",
    "2023-04-15",
    "South garden"
  );
  insertPlant(
    "Basil",
    "Partial shade, well-drained soil",
    "2023-04-20",
    "Herb garden"
  );
  insertPlant(
    "Lavender",
    "Full sun, drought tolerant",
    "2023-05-01",
    "Front yard"
  );
  insertPlant(
    "Pepper",
    "Full sun, consistent moisture",
    "2023-04-10",
    "Back garden"
  );
  insertPlant(
    "Rosemary",
    "Full sun, well-drained soil",
    "2023-05-05",
    "Herb garden"
  );
}
