{"code":"import { Router, type Request, type Response } from "express";
import { db, deleteRepository, getAllRepositories, getRepositoryById, insertRepository, updateRepository } from "../db/repositories-table";

export const router = Router();

// Get all repositories
router.get("/repositories", (req: Request, res: Response) => {
  try {
    const repositories = getAllRepositories();
    res.json(repositories);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch repositories" });
  }
});

// Get a repository by ID
router.get("/repositories/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const repository = getRepositoryById(id);

    if (!repository) {
      return res.status(404).json({ error: "Repository not found" });
    }

    res.json(repository);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch repository" });
  }
});

// Create a new repository
router.post("/repositories", (req: Request, res: Response) => {
  try {
    const { name, description, owner_id } = req.body;

    if (!name || !owner_id) {
      return res.status(400).json({ error: "Name and owner_id are required" });
    }

    const id = insertRepository(name, description || "", owner_id);
    const newRepository = getRepositoryById(id);

    if (!newRepository) {
      return res.status(500).json({ error: "Failed to create repository" });
    }

    res.status(201).json(newRepository);
  } catch (error) {
    res.status(500).json({ error: "Failed to create repository" });
  }
});

// Update a repository
router.put("/repositories/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    const { name, description } = req.body;

    if (!name) {
      return res.status(400).json({ error: "Name is required" });
    }

    const existingRepo = getRepositoryById(id);

    if (!existingRepo) {
      return res.status(404).json({ error: "Repository not found" });
    }

    updateRepository(id, name, description || "");
    const updatedRepo = getRepositoryById(id);

    if (!updatedRepo) {
      return res.status(500).json({ error: "Failed to update repository" });
    }

    res.json(updatedRepo);
  } catch (error) {
    res.status(500).json({ error: "Failed to update repository" });
  }
});

// Delete a repository
router.delete("/repositories/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    const existingRepo = getRepositoryById(id);

    if (!existingRepo) {
      return res.status(404).json({ error: "Repository not found" });
    }

    deleteRepository(id);
    res.json({ message: "Repository deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete repository" });
  }
});
"}

