{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to specific routes
  const protectedPaths = ["/admin", "/staff"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  // Skip validation for non-protected paths
  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has required role
  const userRole = req.headers["x-user-role"] as string | undefined;

  // For /admin path, only admins can access
  if (req.path.startsWith("/admin")) {
    if (userRole !== "admin") {
      res.status(403).json({ error: "Access denied: Admin role required" });
      return;
    }
  }

  // For /staff path, both staff and admin can access
  if (req.path.startsWith("/staff")) {
    if (userRole !== "staff" && userRole !== "admin") {
      res.status(403).json({ error: "Access denied: Staff or Admin role required" });
      return;
    }
  }

  // If we reach here, the user has proper permissions
  next();
}
"}

