  name: string;
  price: number;
}

interface CartItem {
  product: Product;
  quantity: number;
}

export function BillingPage() {
  // State management
  const [products, setProducts] = useState<Product[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [selectedProduct, setSelectedProduct] = useState<number>(0);
  const [quantity, setQuantity] = useState<number>(1);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  // Fetch products from API
  useEffect(() => {
    const fetchProducts = async () => {
      try {
        // Simulate API call
        await new Promise(resolve => setTimeout(resolve, 500));

        // Mock data - in a real app this would be an API call
        const mockProducts: Product[] = [
          { id: 1, name: "Cotton Fabric", price: 15.99 },
          { id: 2, name: "Silk Fabric", price: 25.50 },
          { id: 3, name: "Wool Yarn", price: 8.75 },
          { id: 4, name: "Linen Fabric", price: 12.25 },
          { id: 5, name: "Denim Fabric", price: 18.00 }
        ];

        setProducts(mockProducts);
        setLoading(false);
      } catch (err) {
        setError("Failed to load products");
        setLoading(false);
      }
    };

    fetchProducts();
  }, []);

  // Add item to cart
  const addToCart = () => {
    if (selectedProduct === 0 || quantity <= 0) return;

    const product = products.find(p => p.id === selectedProduct);
    if (!product) return;

    setCart(prevCart => {
      const existingItem = prevCart.find(item => item.product.id === selectedProduct);

      if (existingItem) {
        return prevCart.map(item => 
          item.product.id === selectedProduct 
            ? { ...item, quantity: item.quantity + quantity } 
            : item
        );
      } else {
        return [...prevCart, { product, quantity }];
      }
    });

    // Reset selection
    setSelectedProduct(0);
    setQuantity(1);
  };

  // Remove item from cart
  const removeFromCart = (productId: number) => {
    setCart(prevCart => prevCart.filter(item => item.product.id !== productId));
  };

  // Calculate total amount
  const calculateTotal = (): number => {
    return cart.reduce((total, item) => {
      return total + (item.product.price * item.quantity);
    }, 0);
  };

  // Generate bill
  const generateBill = () => {
    if (cart.length === 0) return;

    alert(`\n--- BILL ---\n${cart.map(item => `${item.product.name}: ${item.quantity} x $${item.product.price.toFixed(2)} = $${(item.product.price * item.quantity).toFixed(2)}`).join('\n')}\n\nTOTAL: $${calculateTotal().toFixed(2)}\n--- END BILL ---`);

    // Clear cart after bill generation
    setCart([]);
  };

  // Render loading state
  if (loading) {
    return (
      <div style={{
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        height: "100vh",
        fontFamily: "system-ui, sans-serif"
      }}>
        <p>Loading...</p>
      </div>
    );
  }

  // Render error state
