{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const donations = [
  { id: 1, foodType: "apples", quantity: 5, status: "available", donor: "John Doe", createdAt: new Date() },
  { id: 2, foodType: "bread", quantity: 10, status: "donated", donor: "Jane Smith", createdAt: new Date() }
];

const findDonationById = (id: number) => {
  return donations.find(donation => donation.id === id);
};

const createDonation = (donationData: Omit<typeof donations[0], "id" | "createdAt">) => {
  const newDonation = {
    id: donations.length > 0 ? Math.max(...donations.map(d => d.id)) + 1 : 1,
    ...donationData,
    createdAt: new Date()
  };
  donations.push(newDonation);
  return newDonation;
};

const updateDonation = (id: number, updateData: Partial<Omit<typeof donations[0], "id" | "createdAt">>) => {
  const index = donations.findIndex(donation => donation.id === id);
  if (index === -1) return null;

  donations[index] = {
    ...donations[index],
    ...updateData
  };

  return donations[index];
};

const deleteDonation = (id: number) => {
  const index = donations.findIndex(donation => donation.id === id);
  if (index === -1) return false;

  donations.splice(index, 1);
  return true;
};

// GET /donations - List all donations
router.get("/", (req: Request, res: Response) => {
  res.json(donations);
});

// GET /donations/:id - Get a specific donation by ID
router.get("/\:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid donation ID" });
  }

  const donation = findDonationById(id);

  if (!donation) {
    return res.status(404).json({ error: "Donation not found" });
  }

  res.json(donation);
});

// POST /donations - Create a new donation
router.post("/", (req: Request, res: Response) => {
  const { foodType, quantity, status, donor } = req.body;

  if (!foodType || !quantity || !status || !donor) {
    return res.status(400).json({ error: "Missing required fields: foodType, quantity, status, donor" });
  }

  const newDonation = createDonation({
    foodType,
    quantity,
    status,
    donor
  });

  res.status(201).json(newDonation);
});

// PUT /donations/:id - Update a donation
router.put("/\:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid donation ID" });
  }

  const { foodType, quantity, status, donor } = req.body;

  const updatedDonation = updateDonation(id, {
    foodType,
    quantity,
    status,
    donor
  });

  if (!updatedDonation) {
    return res.status(404).json({ error: "Donation not found" });
  }

  res.json(updatedDonation);
});

// DELETE /donations/:id - Delete a donation
router.delete("/\:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid donation ID" });
  }

  const deleted = deleteDonation(id);

  if (!deleted) {
    return res.status(404).json({ error: "Donation not found" });
  }

  res.json({ message: "Donation deleted successfully" });
});
"}

