{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface SavedArticle {
  id: number;
  userId: number;
  title: string;
  url: string;
  content: string;
  archivedAt: Date;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS saved_articles (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    userId INTEGER NOT NULL,
    title TEXT NOT NULL,
    url TEXT UNIQUE NOT NULL,
    content TEXT NOT NULL,
    archivedAt DATETIME NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllSavedArticles(): SavedArticle[] {
  const stmt = db.prepare(`
    SELECT id, userId, title, url, content, archivedAt 
    FROM saved_articles 
    ORDER BY archivedAt DESC
  `);
  return stmt.all() as unknown as SavedArticle[];
}

export function getSavedArticleById(id: number): SavedArticle | undefined {
