{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data to simulate database operations
let bookings = [
  {
    id: "1",
    patientName: "John Doe",
    pickupLocation: "123 Main St",
    destination: "City Hospital",
    status: "confirmed",
    bookingTime: new Date().toISOString(),
  },
  {
    id: "2",
    patientName: "Jane Smith",
    pickupLocation: "456 Oak Ave",
    destination: "General Clinic",
    status: "pending",
    bookingTime: new Date().toISOString(),
  },
];

// Get all bookings
router.get("/", (req: Request, res: Response) => {
  res.json(bookings);
});

// Get a booking by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const booking = bookings.find(b => b.id === id);

  if (!booking) {
    return res.status(404).json({ message: "Booking not found" });
  }

  res.json(booking);
});

// Create a new booking
router.post("/", (req: Request, res: Response) => {
  const { patientName, pickupLocation, destination } = req.body;

  if (!patientName || !pickupLocation || !destination) {
    return res.status(400).json({ message: "Patient name, pickup location, and destination are required" });
  }

  const newBooking = {
    id: String(bookings.length + 1),
    patientName,
    pickupLocation,
    destination,
    status: "pending",
    bookingTime: new Date().toISOString(),
  };

  bookings.push(newBooking);

  res.status(201).json(newBooking);
});

// Update a booking status
router.put("/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const { status } = req.body;

  if (!status) {
    return res.status(400).json({ message: "Status is required" });
  }

  const bookingIndex = bookings.findIndex(b => b.id === id);

  if (bookingIndex === -1) {
    return res.status(404).json({ message: "Booking not found" });
  }

  bookings[bookingIndex].status = status;

  res.json(bookings[bookingIndex]);
});

// Delete a booking
router.delete("/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const bookingIndex = bookings.findIndex(b => b.id === id);

  if (bookingIndex === -1) {
    return res.status(404).json({ message: "Booking not found" });
  }

  bookings.splice(bookingIndex, 1);

  res.json({ message: "Booking deleted successfully" });
});
"}

{"code":"import { useEffect, useState } from "react";

interface Reservation {
  id: number;
  vendorName: string;
  stallNumber: number;
  reservationDate: string;
}

export function StallReservationForm() {
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [vendorName, setVendorName] = useState("");
  const [stallNumber, setStallNumber] = useState("");

  const [editingId, setEditingId] = useState<number | null>(null);

  useEffect(() => {
    fetchReservations();
  }, []);

  const fetchReservations = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/reservations-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch reservations: ${response.status}`);
      }
      const data = await response.json();
      setReservations(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!vendorName.trim() || !stallNumber) {
      setError("Please fill in all fields");
      return;
    }

    try {
      const response = await fetch("/api/reservations-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          vendorName,
          stallNumber: Number(stallNumber),
          reservationDate: new Date().toISOString().split('T')[0]
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to create reservation: ${response.status}`);
      }

      // Reset form
      setVendorName("");
      setStallNumber("");

      // Refresh data
      await fetchReservations();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleEdit = (reservation: Reservation) => {
    setEditingId(reservation.id);
    setVendorName(reservation.vendorName);
    setStallNumber(reservation.stallNumber.toString());
  };

  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId === null) return;

    if (!vendorName.trim() || !stallNumber) {
      setError("Please fill in all fields");
      return;
    }

    try {
      const response = await fetch(`/api/reservations-api/${editingId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          vendorName,
          stallNumber: Number(stallNumber),
          reservationDate: new Date().toISOString().split('T')[0]
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to update reservation: ${response.status}`);
      }

      // Reset form
      setEditingId(null);
      setVendorName("");
      setStallNumber("");

      // Refresh data
      await fetchReservations();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/reservations-api/${id}`, {
        method: "DELETE"
      });

      if (!response.ok) {
        throw new Error(`Failed to delete reservation: ${response.status}`);
      }

      // Refresh data
      await fetchReservations();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
