{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockCars = [
  { id: 1, make: "Toyota", model: "Camry", year: 2022, color: "Blue", dailyRate: 50 },
  { id: 2, make: "Honda", model: "Civic", year: 2021, color: "Red", dailyRate: 45 },
  { id: 3, make: "Ford", model: "Focus", year: 2020, color: "Black", dailyRate: 40 }
];

const findCarIndex = (id: number): number => {
  return mockCars.findIndex(car => car.id === id);
};

// Get all cars
router.get("/", (req: Request, res: Response) => {
  res.json(mockCars);
});

// Get a car by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid car ID" });
  }

  const carIndex = findCarIndex(id);

  if (carIndex === -1) {
    return res.status(404).json({ error: "Car not found" });
  }

  res.json(mockCars[carIndex]);
});

// Create a new car
router.post("/", (req: Request, res: Response) => {
  const { make, model, year, color, dailyRate } = req.body;

  if (!make || !model || !year || !color || !dailyRate) {
    return res.status(400).json({ error: "Missing required fields: make, model, year, color, dailyRate" });
  }

  const newCar = {
    id: mockCars.length > 0 ? Math.max(...mockCars.map(c => c.id)) + 1 : 1,
    make,
    model,
    year: Number(year),
    color,
    dailyRate: Number(dailyRate)
  };

  mockCars.push(newCar);

  res.status(201).json(newCar);
});

// Update a car
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid car ID" });
  }

  const carIndex = findCarIndex(id);

  if (carIndex === -1) {
    return res.status(404).json({ error: "Car not found" });
  }

  const { make, model, year, color, dailyRate } = req.body;

  if (!make || !model || !year || !color || !dailyRate) {
    return res.status(400).json({ error: "Missing required fields: make, model, year, color, dailyRate" });
  }

  mockCars[carIndex] = {
    id,
    make,
    model,
    year: Number(year),
    color,
    dailyRate: Number(dailyRate)
  };

  res.json(mockCars[carIndex]);
});

// Delete a car
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid car ID" });
  }

  const carIndex = findCarIndex(id);

  if (carIndex === -1) {
    return res.status(404).json({ error: "Car not found" });
  }

  const deletedCar = mockCars.splice(carIndex, 1)[0];

  res.json(deletedCar);
});
