{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock session handling - in a real app, this would be replaced with actual session management
const sessions: Record<string, { userId: string; role: string }> = {};
const users: Record<string, { email: string; password: string; role: string }> = {
  "member@example.com": { email: "member@example.com", password: "password123", role: "member" },
  "staff@example.com": { email: "staff@example.com", password: "password123", role: "staff" }
};

// Register a new user
router.post("/register", (req: Request, res: Response) => {
  const { email, password, role } = req.body;

  if (!email || !password || !role) {
    return res.status(400).json({ error: "Email, password, and role are required" });
  }

  if (users[email]) {
    return res.status(400).json({ error: "User already exists" });
  }

  users[email] = { email, password, role };
  return res.status(201).json({ message: "User registered successfully" });
});

// Login a user
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  const user = users[email];
  if (!user || user.password !== password) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Create a mock session
  const sessionId = Math.random().toString(36).substring(2, 15);
  sessions[sessionId] = { userId: email, role: user.role };

  return res.json({ sessionId, role: user.role });
});

// Middleware to verify session
const authenticate = (req: Request, res: Response, next: Function) => {
  const sessionId = req.headers.authorization?.split(" ")[1];
  if (!sessionId || !sessions[sessionId]) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  (req as any).session = sessions[sessionId];
  next();
};

// Middleware to verify member role
const requireMember = (req: Request, res: Response, next: Function) => {
  const session = (req as any).session;
  if (!session || session.role !== "member") {
    return res.status(403).json({ error: "Access denied: Member role required" });
  }
  next();
};

// Middleware to verify staff role
const requireStaff = (req: Request, res: Response, next: Function) => {
  const session = (req as any).session;
  if (!session || session.role !== "staff") {
    return res.status(403).json({ error: "Access denied: Staff role required" });
  }
  next();
};

// Get user profile (protected route)
router.get("/profile", authenticate, (req: Request, res: Response) => {
  const session = (req as any).session;
  const user = users[session.userId];

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  return res.json({ email: user.email, role: user.role });
});

// Update user profile (protected route)
router.put("/profile", authenticate, (req: Request, res: Response) => {
  const session = (req as any).session;
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  const user = users[session.userId];
  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  user.email = email;
  user.password = password;

  return res.json({ message: "Profile updated successfully" });
});

// Get all members (staff only)
router.get("/members", authenticate, requireStaff, (req: Request, res: Response) => {
  const members = Object.entries(users)
    .filter(([_, user]) => user.role === "member")
    .map(([email, user]) => ({ email, role: user.role }));

  return res.json(members);
});

// Get all staff (staff only)
router.get("/staff", authenticate, requireStaff, (req: Request, res: Response) => {
  const staff = Object.entries(users)
    .filter(([_, user]) => user.role === "staff")
    .map(([email, user]) => ({ email, role: user.role }));

  return res.json(staff);
});
"}

{"code":"import { useEffect, useState } from "react";

interface Member {
  id: number;
  name: string;
  email: string;
  membershipDate: string;
}

export function MemberListPage() {
  const [members, setMembers] = useState<Member[]>([]);
  const [filteredMembers, setFilteredMembers] = useState<Member[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchMembers();
  }, []);

  const fetchMembers = async () => {
    try {
      const response = await fetch("/api/members");
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setMembers(data);
      setFilteredMembers(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
      setLoading(false);
    }
  };

  useEffect(() => {
    if (searchTerm === "") {
      setFilteredMembers(members);
    } else {
      const filtered = members.filter(member =>
        member.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        member.email.toLowerCase().includes(searchTerm.toLowerCase())
      );
      setFilteredMembers(filtered);
    }
  }, [searchTerm, members]);

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/members/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      // Refresh the list after deletion
