{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const placements = [
  { id: 1, company: "Tech Corp", position: "Software Engineer", salary: 75000, date: "2023-06-15" },
  { id: 2, company: "Data Systems", position: "Data Analyst", salary: 65000, date: "2023-07-20" }
];

const findPlacementIndex = (id: number) => {
  return placements.findIndex(p => p.id === id);
};

// GET /api/placements - List all placements
router.get("/placements", (req: Request, res: Response) => {
  res.json(placements);
});

// GET /api/placements/:id - Get a specific placement by ID
router.get("/placements/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const placement = placements.find(p => p.id === id);

  if (!placement) {
    return res.status(404).json({ error: "Placement not found" });
  }

  res.json(placement);
});

// POST /api/placements - Create a new placement
router.post("/placements", (req: Request, res: Response) => {
  const { company, position, salary, date } = req.body;

  // Validate required fields
  if (!company || !position || !salary || !date) {
    return res.status(400).json({ error: "Company, position, salary, and date are required" });
  }

  const newId = placements.length > 0 ? Math.max(...placements.map(p => p.id)) + 1 : 1;
  const newPlacement = {
    id: newId,
    company,
    position,
    salary: Number(salary),
    date
  };

  placements.push(newPlacement);
  res.status(201).json(newPlacement);
});

// PUT /api/placements/:id - Update a placement
router.put("/placements/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const placementIndex = findPlacementIndex(id);

  if (placementIndex === -1) {
    return res.status(404).json({ error: "Placement not found" });
  }

  const { company, position, salary, date } = req.body;

  // Validate required fields
  if (!company || !position || !salary || !date) {
    return res.status(400).json({ error: "Company, position, salary, and date are required" });
  }

  placements[placementIndex] = {
    id,
    company,
    position,
    salary: Number(salary),
    date
  };

  res.json(placements[placementIndex]);
});

// DELETE /api/placements/:id - Delete a placement
router.delete("/placements/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const placementIndex = findPlacementIndex(id);

  if (placementIndex === -1) {
    return res.status(404).json({ error: "Placement not found" });
  }

  placements.splice(placementIndex, 1);
  res.json({ message: "Placement deleted successfully" });
});
"}

