export const router = Router();

// Mock session data storage
let sessions: any[] = [];
let nextId = 1;

// GET /sessions - List all sessions
router.get("/sessions", (req: Request, res: Response) => {
  res.json(sessions);
});

// GET /sessions/:id - Get a specific session by ID
router.get("/sessions/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const session = sessions.find(s => s.id === id);

  if (!session) {
    return res.status(404).json({ error: "Session not found" });
  }

  res.json(session);
});

// POST /sessions - Create a new session
router.post("/sessions", (req: Request, res: Response) => {
  const { clientId, date, duration, notes } = req.body;

  // Validate required fields
  if (!clientId || !date || !duration) {
    return res.status(400).json({ error: "Client ID, date, and duration are required" });
  }

  const newSession = {
    id: nextId++,
    clientId,
    date,
    duration,
    notes: notes || ""
  };

  sessions.push(newSession);
  res.status(201).json(newSession);
});

// PUT /sessions/:id - Update an existing session
router.put("/sessions/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const sessionIndex = sessions.findIndex(s => s.id === id);

  if (sessionIndex === -1) {
    return res.status(404).json({ error: "Session not found" });
  }

  const { clientId, date, duration, notes } = req.body;

  // Validate required fields
  if (!clientId || !date || !duration) {
    return res.status(400).json({ error: "Client ID, date, and duration are required" });
  }

  sessions[sessionIndex] = {
    id,
    clientId,
    date,
    duration,
    notes: notes || ""
  };

  res.json(sessions[sessionIndex]);
});

// DELETE /sessions/:id - Delete a session
router.delete("/sessions/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const sessionIndex = sessions.findIndex(s => s.id === id);

  if (sessionIndex === -1) {
    return res.status(404).json({ error: "Session not found" });
  }

  sessions.splice(sessionIndex, 1);
  res.json({ message: "Session deleted successfully" });
});
"}

{"code":"import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only protect POST requests to the export endpoint
  if (req.method !== "POST" || req.path !== "/export") {
    next();
    return;
  }

  // Check if the request has an owner role in the session or headers
  // This is a simplified check - in a real implementation, you'd verify a JWT token
  const ownerRole = req.headers["x-owner-role"];

  if (ownerRole === "true") {
    next();
  } else {
    res.status(403).json({ error: "Access denied. Owner privileges required." });
  }
}
"}

