{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockAppointments = [
  { id: "1", patientId: "101", date: "2023-10-15", time: "09:00", service: "Cleaning" },
  { id: "2", patientId: "102", date: "2023-10-15", time: "10:00", service: "Filling" }
];

const getAppointments = () => Promise.resolve(mockAppointments);

const getAppointmentById = (id: string) => {
  const appointment = mockAppointments.find(a => a.id === id);
  return Promise.resolve(appointment || null);
};

const createAppointment = (appointmentData: any) => {
  const newAppointment = {
    id: String(mockAppointments.length + 1),
    ...appointmentData
  };
  mockAppointments.push(newAppointment);
  return Promise.resolve(newAppointment);
};

const updateAppointment = (id: string, updatedData: any) => {
  const index = mockAppointments.findIndex(a => a.id === id);
  if (index === -1) return Promise.resolve(null);

  mockAppointments[index] = { ...mockAppointments[index], ...updatedData };
  return Promise.resolve(mockAppointments[index]);
};

const cancelAppointment = (id: string) => {
  const index = mockAppointments.findIndex(a => a.id === id);
  if (index === -1) return Promise.resolve(false);

  mockAppointments.splice(index, 1);
  return Promise.resolve(true);
};

// Helper to check for time conflicts
const hasConflict = (newDate: string, newTime: string, existing: any[]) => {
  return existing.some(app => app.date === newDate && app.time === newTime);
};

// List all appointments
router.get("/appointments", async (req: Request, res: Response) => {
  try {
    const appointments = await getAppointments();
    res.json(appointments);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch appointments" });
  }
});

// Get appointment by ID
router.get("/appointments/:id", async (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    const appointment = await getAppointmentById(id);

    if (!appointment) {
      return res.status(404).json({ error: "Appointment not found" });
    }

    res.json(appointment);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch appointment" });
  }
});

// Create new appointment
router.post("/appointments", async (req: Request, res: Response) => {
  try {
    const { patientId, date, time, service } = req.body;

    if (!patientId || !date || !time || !service) {
      return res.status(400).json({ error: "Missing required fields: patientId, date, time, service" });
    }

    // Check for time conflicts
    const existingAppointments = await getAppointments();
    if (hasConflict(date, time, existingAppointments)) {
      return res.status(400).json({ error: "Time slot already booked" });
    }

    const newAppointment = await createAppointment({ patientId, date, time, service });
    res.status(201).json(newAppointment);
  } catch (error) {
    res.status(500).json({ error: "Failed to create appointment" });
  }
});

// Update appointment
router.put("/appointments/:id", async (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    const { patientId, date, time, service } = req.body;

    if (!patientId || !date || !time || !service) {
      return res.status(400).json({ error: "Missing required fields: patientId, date, time, service" });
    }

    const existingAppointments = await getAppointments();
    const existingAppointment = await getAppointmentById(id);

    if (!existingAppointment) {
      return res.status(404).json({ error: "Appointment not found" });
    }

    // Check for time conflicts (excluding current appointment)
    const conflictingAppointments = existingAppointments.filter(
      a => a.date === date && a.time === time && a.id !== id
    );

    if (conflictingAppointments.length > 0) {
      return res.status(400).json({ error: "Time slot already booked" });
    }

    const updatedAppointment = await updateAppointment(id, { patientId, date, time, service });

    if (!updatedAppointment) {
      return res.status(404).json({ error: "Appointment not found" });
    }

    res.json(updatedAppointment);
  } catch (error) {
    res.status(500).json({ error: "Failed to update appointment" });
  }
});

// Cancel appointment
router.delete("/appointments/:id", async (req: Request, res: Response) => {
  try {
    const id = req.params.id;
    const result = await cancelAppointment(id);

    if (!result) {
      return res.status(404).json({ error: "Appointment not found" });
    }

    res.json({ message: "Appointment cancelled successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to cancel appointment" });
  }
});
"}

