      width: "100%",
      padding: "10px",
      marginBottom: "10px",
      borderRadius: "4px",
      border: "1px solid #ccc",
      boxSizing: "border-box",
    },
    stockList: {
      display: "flex",
      flexDirection: "column",
      gap: "10px",
    },
    stockItem: {
      border: "1px solid #ddd",
      borderRadius: "8px",
      padding: "15px",
      display: "flex",
      justifyContent: "space-between",
      alignItems: "center",
    },
    stockInfo: {
      flex: "1",
    },
    stockActions: {
      display: "flex",
      gap: "10px",
    },
    deleteButton: {
      backgroundColor: "#ff4d4d",
      color: "white",
      border: "none",
      borderRadius: "4px",
      padding: "8px 12px",
      cursor: "pointer",
    },
    noResults: {
      textAlign: "center",
      padding: "20px",
      fontStyle: "italic",
    },
  };

  if (loading) {
    return (
      <div style={styles.container}>
        <h1 style={styles.header}>Poultry Stock</h1>
        <p>Loading...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div style={styles.container}>
        <h1 style={styles.header}>Poultry Stock</h1>
        <p>Error: {error}</p>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <h1 style={styles.header}>Poultry Stock</h1>
      <div style={styles.searchContainer}>
        <input
          type="text"
          placeholder="Search by species or breed..."
          value={searchTerm}
          onChange={handleSearchChange}
          style={styles.searchInput}
        />
      </div>
      <div style={styles.stockList}>
        {filteredStock.length > 0 ? (
          filteredStock.map((item) => (
            <div key={item.id} style={styles.stockItem}>
              <div style={styles.stockInfo}>
                <strong>{item.species}</strong> - {item.breed} ({item.quantity})
