                </button>
              </div>
            </div>
          ))
        ) : (
          <p style={styles.noResults}>No poultry stock found.</p>
        )}
      </div>
    </div>
  );
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("museum.db");

interface Tour {
  id: number;
  docentId: number;
  tourTime: string;
  curatorId: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS tours (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    docentId INTEGER NOT NULL,
    tourTime TEXT NOT NULL,
    curatorId INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllTours(): Tour[] {
  const stmt = db.prepare("SELECT * FROM tours");
  return stmt.all() as unknown as Tour[];
}

export function getTourById(id: number): Tour | undefined {
  const stmt = db.prepare("SELECT * FROM tours WHERE id = ?");
  return stmt.get(id) as unknown as Tour | undefined;
}

export function insertTour(docentId: number, tourTime: string, curatorId: number): number {
  const stmt = db.prepare(
    "INSERT INTO tours (docentId, tourTime, curatorId) VALUES (?, ?, ?)"
  );
  const result = stmt.run(docentId, tourTime, curatorId);
  return Number(result.lastInsertRowid);
}

export function updateTour(id: number, docentId: number, tourTime: string, curatorId: number): void {
  const stmt = db.prepare(
    "UPDATE tours SET docentId = ?, tourTime = ?, curatorId = ? WHERE id = ?"
  );
  stmt.run(docentId, tourTime, curatorId, id);
}

export function deleteTour(id: number): void {
  const stmt = db.prepare("DELETE FROM tours WHERE id = ?");
  stmt.run(id);
}

// Insert sample data if table is empty
