  insertAsset("Lenovo ThinkPad", "2023-04-05", "Alice Brown");
  insertAsset("Surface Laptop", "2023-05-12", "Charlie Wilson");
}
"}

{"code":"import { FC, useState } from "react";

interface Ingredient {
  id: string;
  name: string;
  quantity: number;
}

interface RecipeFormProps {
  recipeId?: string;
  onSubmit: (recipe: any) => void;
}

export function RecipeForm({ recipeId, onSubmit }: RecipeFormProps) {
  const [name, setName] = useState("");
  const [ingredients, setIngredients] = useState<Ingredient[]>([
    { id: "1", name: "", quantity: 0 },
  ]);
  const [instructions, setInstructions] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const handleAddIngredient = () => {
    setIngredients([
      ...ingredients,
      { id: Date.now().toString(), name: "", quantity: 0 },
    ]);
  };

  const handleRemoveIngredient = (id: string) => {
    if (ingredients.length <= 1) return;
    setIngredients(ingredients.filter(ing => ing.id !== id));
  };

  const handleIngredientChange = (
    id: string,
    field: "name" | "quantity",
    value: string
  ) => {
    setIngredients(
      ingredients.map(ing =>
        ing.id === id ? { ...ing, [field]: field === "name" ? value : Number(value) } : ing
      )
    );
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError("");

    // Simulate API call
    setTimeout(() => {
      try {
        const recipeData = {
          name,
          ingredients: ingredients.filter(ing => ing.name.trim() !== ""),
          instructions,
        };
        onSubmit(recipeData);
        setLoading(false);
      } catch (err) {
        setError("Failed to save recipe");
        setLoading(false);
      }
    }, 500);
  };

  return (
    <div style={{
      maxWidth: "600px",
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
    }}>
      <h1 style={{ textAlign: "center" }}>Recipe Form</h1>

      {error && <div style={{ color: "red", marginBottom: "10px" }}>{error}</div>}

      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        <div>
          <label htmlFor="name" style={{ display: "block", marginBottom: "5px" }}>
            Recipe Name
          </label>
          <input
            id="name"
            type="text"
            value={name}
            onChange={(e) => setName(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            required
          />
        </div>

        <div>
          <label style={{ display: "block", marginBottom: "5px" }}>
            Ingredients
          </label>
          {ingredients.map((ingredient, index) => (
            <div key={ingredient.id} style={{ display: "flex", gap: "10px", marginBottom: "10px" }}>
              <input
                type="text"
                placeholder="Ingredient name"
                value={ingredient.name}
                onChange={(e) => handleIngredientChange(ingredient.id, "name", e.target.value)}
                style={{ flex: 1, padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
                required
              />
              <input
                type="number"
                placeholder="Quantity"
                value={ingredient.quantity}
                onChange={(e) => handleIngredientChange(ingredient.id, "quantity", e.target.value)}
                style={{ width: "100px", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
                required
              />
              <button
                type="button"
                onClick={() => handleRemoveIngredient(ingredient.id)}
                disabled={ingredients.length <= 1}
                style={{
                  padding: "8px 12px",
                  backgroundColor: "#ff4d4d",
                  color: "white",
                  border: "none",
                  borderRadius: "4px",
                  cursor: "pointer",
                }}
              >
                Remove
              </button>
            </div>
          ))}
          <button
            type="button"
            onClick={handleAddIngredient}
            style={{
              padding: "8px 12px",
              backgroundColor: "#4CAF50",
              color: "white",
              border: "none",
              borderRadius: "4px",
              cursor: "pointer",
              marginBottom: "10px",
