{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  // Simulate token verification logic
  const token = req.headers.authorization?.split(" ")[1];
  if (!token) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  // In a real implementation, we would verify the HMAC signature here
  // For now, we'll just simulate a valid token
  const expectedSignature = createHmac("sha256", secret)
    .update(token.split(".")[0] + "." + token.split(".")[1])
    .digest();

  const actualSignature = Buffer.from(token.split(".")[2], "base64");

  try {
    const isValid = timingSafeEqual(expectedSignature, actualSignature);
    if (!isValid) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
  } catch {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  next();
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import { getRoomById } from "../db/rooms-table";
import { getReassignmentById, insertReassignment } from "../db/reassignments-table";

export const router = Router();

router.post("/reassignments", (req: Request, res: Response) => {
  const { supervisorId, sourceHousekeeperId, targetHousekeeperId, roomId } = req.body;

  // Validate input
  if (
    typeof supervisorId !== "number" ||
    typeof sourceHousekeeperId !== "number" ||
    typeof targetHousekeeperId !== "number" ||
    typeof roomId !== "number"
  ) {
    return res.status(400).json({ error: "Invalid input data" });
  }

  // Check if the target housekeeper already has the room assigned
  const room = getRoomById(roomId);
  if (!room) {
    return res.status(404).json({ error: "Room not found" });
  }

  if (room.assigned_housekeeper_id === targetHousekeeperId) {
    return res.status(400).json({ error: "Target housekeeper already has this room assigned" });
  }

  // Proceed with reassignment
  const reassignmentId = insertReassignment(
    supervisorId,
    sourceHousekeeperId,
    targetHousekeeperId,
    roomId
  );

  return res.status(201).json({ id: reassignmentId });
});
"}

