{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data to simulate database operations
let ambulances = [
  { id: 1, status: "available", location: "Hospital A", lastMaintenance: "2023-01-15", nextMaintenance: "2023-07-15" },
  { id: 2, status: "busy", location: "Hospital B", lastMaintenance: "2023-02-20", nextMaintenance: "2023-08-20" },
  { id: 3, status: "maintenance", location: "Garage C", lastMaintenance: "2023-03-10", nextMaintenance: "2023-09-10" }
];

// Get all ambulances
router.get("/", (req: Request, res: Response) => {
  res.json(ambulances);
});

// Get a specific ambulance by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const ambulance = ambulances.find(a => a.id === id);

  if (!ambulance) {
    return res.status(404).json({ error: "Ambulance not found" });
  }

  res.json(ambulance);
});

// Create a new ambulance
router.post("/", (req: Request, res: Response) => {
  const { status, location, lastMaintenance, nextMaintenance } = req.body;

  // Validate required fields
  if (!status || !location || !lastMaintenance || !nextMaintenance) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const newId = ambulances.length > 0 ? Math.max(...ambulances.map(a => a.id)) + 1 : 1;
  const newAmbulance = {
    id: newId,
    status,
    location,
    lastMaintenance,
    nextMaintenance
  };

  ambulances.push(newAmbulance);
  res.status(201).json(newAmbulance);
});

// Update an existing ambulance
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const index = ambulances.findIndex(a => a.id === id);

  if (index === -1) {
    return res.status(404).json({ error: "Ambulance not found" });
  }

  const { status, location, lastMaintenance, nextMaintenance } = req.body;

  // Validate required fields
  if (!status || !location || !lastMaintenance || !nextMaintenance) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  ambulances[index] = {
    id,
    status,
    location,
    lastMaintenance,
    nextMaintenance
  };

  res.json(ambulances[index]);
});

// Delete an ambulance
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const index = ambulances.findIndex(a => a.id === id);

  if (index === -1) {
    return res.status(404).json({ error: "Ambulance not found" });
  }

  ambulances.splice(index, 1);
  res.json({ message: "Ambulance deleted successfully" });
});
"}

