{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./trainer-client.db");

interface Workout {
  id: number;
  trainerId: number;
  clientId: number;
  date: string;
  duration: number;
  notes: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS workouts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    trainerId INTEGER NOT NULL,
    clientId INTEGER NOT NULL,
    date TEXT NOT NULL,
    duration INTEGER NOT NULL,
    notes TEXT
  )
`;

db.exec(createTableSql);

export function getAllWorkouts(): Workout[] {
  const stmt = db.prepare("SELECT * FROM workouts");
  return stmt.all() as unknown as Workout[];
}

export function getWorkoutById(id: number): Workout | undefined {
  const stmt = db.prepare("SELECT * FROM workouts WHERE id = ?");
  return stmt.get(id) as unknown as Workout | undefined;
}

export function insertWorkout(workout: Omit<Workout, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO workouts (trainerId, clientId, date, duration, notes) VALUES (?, ?, ?, ?, ?)"
  );
  const result = stmt.run(workout.trainerId, workout.clientId, workout.date, workout.duration, workout.notes);
  return Number(result.lastInsertRowid);
}

export function updateWorkout(id: number, workout: Partial<Omit<Workout, "id">>): boolean {
  const fields = [];
  const values = [];

  if (workout.trainerId !== undefined) {
    fields.push("trainerId = ?");
    values.push(workout.trainerId);
  }

  if (workout.clientId !== undefined) {
    fields.push("clientId = ?");
    values.push(workout.clientId);
  }

  if (workout.date !== undefined) {
    fields.push("date = ?");
    values.push(workout.date);
  }

  if (workout.duration !== undefined) {
    fields.push("duration = ?");
    values.push(workout.duration);
  }

  if (workout.notes !== undefined) {
    fields.push("notes = ?");
    values.push(workout.notes);
  }

  if (fields.length === 0) return false;

  values.push(id);

  const sql = `UPDATE workouts SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  stmt.run(...values);

  return true;
}

export function deleteWorkout(id: number): boolean {
  const stmt = db.prepare("DELETE FROM workouts WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

// Insert sample data if table is empty
