{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data to simulate database storage
let usageRecords: { id: number; userId: number; kWh: number; date: string }[] = [];
let nextId = 1;

// GET /usage - List all usage records
router.get("/usage", (req: Request, res: Response) => {
  res.json(usageRecords);
});

// GET /usage/:id - Get a specific usage record by ID
router.get("/usage/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const record = usageRecords.find(r => r.id === id);

  if (!record) {
    return res.status(404).json({ error: "Usage record not found" });
  }

  res.json(record);
});

// POST /usage - Create a new usage record
router.post("/usage", (req: Request, res: Response) => {
  const { userId, kWh, date } = req.body;

  if (!userId || !kWh || !date) {
    return res.status(400).json({ error: "Missing required fields: userId, kWh, date" });
  }

  const newRecord = {
    id: nextId++,
    userId: Number(userId),
    kWh: Number(kWh),
    date
  };

  usageRecords.push(newRecord);
  res.status(201).json(newRecord);
});

// PUT /usage/:id - Update an existing usage record
router.put("/usage/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const index = usageRecords.findIndex(r => r.id === id);

  if (index === -1) {
    return res.status(404).json({ error: "Usage record not found" });
  }

  const { userId, kWh, date } = req.body;

  if (!userId || !kWh || !date) {
    return res.status(400).json({ error: "Missing required fields: userId, kWh, date" });
  }

  usageRecords[index] = {
    id,
    userId: Number(userId),
    kWh: Number(kWh),
    date
  };

  res.json(usageRecords[index]);
});

// DELETE /usage/:id - Delete a usage record
router.delete("/usage/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const index = usageRecords.findIndex(r => r.id === id);

  if (index === -1) {
    return res.status(404).json({ error: "Usage record not found" });
  }

  usageRecords.splice(index, 1);
  res.json({ message: "Usage record deleted successfully" });
});
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database - in a real app this would be a proper database
const users = [
  {
    id: 1,
    username: "admin",
    password: "password123",
    role: "staff"
  },
  {
    id: 2,
    username: "placement_officer",
    password: "officer456",
    role: "staff"
  }
];

// Mock session storage
const sessions = new Map<string, { userId: number; role: string }>();

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate a mock session ID
  const sessionId = Math.random().toString(36).substring(2, 15);
  sessions.set(sessionId, { userId: user.id, role: user.role });

  return res.status(200).json({
    sessionId,
    role: user.role
  });
});

// Logout endpoint
router.post("/logout", (req: Request, res: Response) => {
  const sessionId = req.headers["x-session-id"] as string;

  if (!sessionId) {
    return res.status(400).json({ error: "Session ID is required" });
  }

  if (!sessions.has(sessionId)) {
    return res.status(401).json({ error: "Invalid session" });
  }

  sessions.delete(sessionId);
  return res.status(200).json({ message: "Logged out successfully" });
});

// Middleware to verify session
const authenticate = (req: Request, res: Response, next: () => void) => {
  const sessionId = req.headers["x-session-id"] as string;

  if (!sessionId) {
    return res.status(401).json({ error: "Session ID is required" });
  }

  const session = sessions.get(sessionId);

  if (!session) {
    return res.status(401).json({ error: "Invalid session" });
  }

  // Attach user info to request
  (req as any).user = session;
  next();
};

// Get current user info
router.get("/me", authenticate, (req: Request, res: Response) => {
  const user = (req as any).user;
  return res.status(200).json({
    id: user.userId,
    role: user.role
  });
});

// Role-based access control middleware
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: () => void) => {
    const user = (req as any).user;

    if (!user || user.role !== requiredRole) {
      return res.status(403).json({ error: "Access denied" });
    }

    next();
  };
};

// Example protected route for staff
router.get("/dashboard", authenticate, requireRole("staff"), (req: Request, res: Response) => {
  return res.status(200).json({ message: "Welcome to the staff dashboard" });
});
"}

