    res.status(404).send(`Design file with id ${id} not found.`);
  }
});

router.post("/design-files", (req: Request, res: Response): void => {
  const { name, content, version } = req.body;
  insertDesignFile(name, content, version);
  res.status(201).send("Design file created.");
});

router.put("/design-files/:id", (req: Request, res: Response): void => {
