{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockDatabase = {
  players: [
    { id: 1, name: "John Doe", email: "john@example.com", role: "Batsman", matchesPlayed: 10, runsScored: 500 },
    { id: 2, name: "Jane Smith", email: "jane@example.com", role: "Bowler", matchesPlayed: 8, runsScored: 300 },
  ],

  getPlayerById: (id: number) => {
    return mockDatabase.players.find(player => player.id === id);
  },

  getAllPlayers: () => {
    return mockDatabase.players;
  },

  createPlayer: (playerData: Omit<Player, 'id'>) => {
    const newPlayer = {
      id: mockDatabase.players.length > 0 ? Math.max(...mockDatabase.players.map(p => p.id)) + 1 : 1,
      ...playerData
    };
    mockDatabase.players.push(newPlayer);
    return newPlayer;
  },

  updatePlayer: (id: number, updatedData: Partial<Player>) => {
    const playerIndex = mockDatabase.players.findIndex(player => player.id === id);
    if (playerIndex === -1) return null;

    mockDatabase.players[playerIndex] = { ...mockDatabase.players[playerIndex], ...updatedData };
    return mockDatabase.players[playerIndex];
  },

  deletePlayer: (id: number) => {
    const playerIndex = mockDatabase.players.findIndex(player => player.id === id);
    if (playerIndex === -1) return false;

    mockDatabase.players.splice(playerIndex, 1);
    return true;
  }
};

interface Player {
  id: number;
  name: string;
  email: string;
  role: string;
  matchesPlayed: number;
  runsScored: number;
}

// GET /players - List all players
router.get("/players", (req: Request, res: Response) => {
  try {
    const players = mockDatabase.getAllPlayers();
    res.json(players);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// GET /players/:id - Get a specific player by ID
router.get("/players/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid player ID" });
    }

    const player = mockDatabase.getPlayerById(id);
    if (!player) {
      return res.status(404).json({ error: "Player not found" });
    }

    res.json(player);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// POST /players - Create a new player
router.post("/players", (req: Request, res: Response) => {
  try {
    const { name, email, role, matchesPlayed, runsScored } = req.body;

    // Validate required fields
    if (!name || !email || !role) {
      return res.status(400).json({ error: "Name, email, and role are required" });
    }

    // Validate numeric fields if provided
    if (matchesPlayed !== undefined && isNaN(matchesPlayed)) {
      return res.status(400).json({ error: "matchesPlayed must be a number" });
    }

    if (runsScored !== undefined && isNaN(runsScored)) {
      return res.status(400).json({ error: "runsScored must be a number" });
    }

    const newPlayer = mockDatabase.createPlayer({
      name,
      email,
      role,
      matchesPlayed: matchesPlayed || 0,
      runsScored: runsScored || 0
    });

    res.status(201).json(newPlayer);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// PUT /players/:id - Update a player
router.put("/players/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid player ID" });
    }

    const { name, email, role, matchesPlayed, runsScored } = req.body;

    const updatedPlayer = mockDatabase.updatePlayer(id, {
      name,
      email,
      role,
      matchesPlayed,
      runsScored
    });

    if (!updatedPlayer) {
      return res.status(404).json({ error: "Player not found" });
    }

    res.json(updatedPlayer);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// DELETE /players/:id - Delete a player
router.delete("/players/:id", (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid player ID" });
    }

    const deleted = mockDatabase.deletePlayer(id);
    if (!deleted) {
      return res.status(404).json({ error: "Player not found" });
    }

    res.json({ message: "Player deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});
"}

