{"code":"import { useEffect, useState } from "react";

interface MenuItem {
  id: string;
  name: string;
  description: string;
  price: number;
}

interface BoxItem {
  id: string;
  menuItemId: string;
  quantity: number;
}

export function BoxCustomizer() {
  const [menuItems, setMenuItems] = useState<MenuItem[]>([]);
  const [boxItems, setBoxItems] = useState<BoxItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newQuantity, setNewQuantity] = useState<Record<string, number>>({});

  useEffect(() => {
    fetchMenuItems();
    fetchBoxItems();
  }, []);

  const fetchMenuItems = async () => {
    try {
      const response = await fetch("/api/box-customization-api/");
      if (!response.ok) throw new Error("Failed to fetch menu items");
      const data = await response.json();
      setMenuItems(data);
    } catch (err) {
      setError("Error loading menu items");
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchBoxItems = async () => {
    try {
      const response = await fetch("/api/box-customization-api/member");
      if (!response.ok) throw new Error("Failed to fetch box items");
      const data = await response.json();
      setBoxItems(data);
      // Initialize quantities
      const initialQuantities: Record<string, number> = {};
      data.forEach((item: BoxItem) => {
        initialQuantities[item.menuItemId] = item.quantity;
      });
      setNewQuantity(initialQuantities);
    } catch (err) {
      setError("Error loading box items");
      console.error(err);
    }
  };

  const handleQuantityChange = (menuItemId: string, value: string) => {
    const numValue = Number(value);
    if (isNaN(numValue)) return;
    setNewQuantity({
      ...newQuantity,
      [menuItemId]: numValue
    });
  };

  const saveChanges = async () => {
    try {
      const updatedItems = Object.entries(newQuantity)
        .filter(([_, qty]) => qty > 0)
        .map(([menuItemId, quantity]) => ({
          menuItemId,
          quantity
        }));

      const response = await fetch("/api/box-customization-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(updatedItems)
      });

      if (!response.ok) throw new Error("Failed to save changes");

      // Refresh data after successful save
      await fetchMenuItems();
      await fetchBoxItems();
    } catch (err) {
      setError("Error saving changes");
      console.error(err);
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Weekly Box Customization</h1>

      <div style={{ marginBottom: "30px" }}>
        <h2>Menu Items</h2>
        {menuItems.length === 0 ? (
          <p>No menu items available.</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
            {menuItems.map(item => (
              <div key={item.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px" }}>
                <h3>{item.name}</h3>
                <p>{item.description}</p>
                <p>Price: ${item.price.toFixed(2)}</p>
                <label htmlFor={`quantity-${item.id}`} style={{ display: "block", marginTop: "10px" }}>
                  Quantity:
                </label>
                <input
                  id={`quantity-${item.id}`}
                  type="number"
                  min="0"
                  value={newQuantity[item.id] || 0}
                  onChange={(e) => handleQuantityChange(item.id, e.target.value)}
                  style={{ width: "100%", marginTop: "5px" }}
                />
              </div>
            ))}
          </div>
        )}
      </div>

      <div style={{ marginBottom: "30px" }}>
        <h2>Your Box Items</h2>
        {boxItems.length === 0 ? (
          <p>No items in your box yet.</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
            {boxItems.map(item => {
              const menuItem = menuItems.find(m => m.id === item.menuItemId);
              return (
                <div key={item.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px" }}>
                  <h3>{menuItem?.name || "Unknown Item"}</h3>
                  <p>Quantity: {item.quantity}</p>
                </div>
              );
            })}
          </div>
        )}
      </div>

      <button 
        onClick={saveChanges}
        style={{ 
          backgroundColor: "#007bff", 
          color: "white", 
          border: "none", 
          borderRadius: "4px", 
          padding: "10px 20px", 
          fontSize: "16px", 
          cursor: "pointer", 
          width: "100%" 
        }}
      >
        Save Changes
      </button>
    </div>
  );
}
"}

