export const router = Router();

// Mock user database
const users = [
  {
    id: "1",
    username: "john_doe",
    password: "hashed_password_123",
    role: "sales_representative"
  },
  {
    id: "2",
    username: "jane_smith",
    password: "hashed_password_456",
    role: "manager"
  }
];

