{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./help-exchange.db");

interface MessageRow {
  id: number;
  sender_id: number;
  recipient_id: number;
  content: string;
  timestamp: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS messages (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    sender_id INTEGER NOT NULL,
    recipient_id INTEGER NOT NULL,
    content TEXT NOT NULL,
    timestamp TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function insertMessage(
  senderId: number,
  recipientId: number,
  content: string,
  timestamp: string
): number {
  const sql = `INSERT INTO messages (sender_id, recipient_id, content, timestamp)
               VALUES (?, ?, ?, ?)`;
  const result = db.prepare(sql).run(senderId, recipientId, content, timestamp);
  return Number(result.lastInsertRowid);
}

export function getMessageById(id: number): MessageRow | undefined {
  const sql = `SELECT * FROM messages WHERE id = ?`;
  const result = db.prepare(sql).get(id);
  return result as unknown as MessageRow | undefined;
}

export function getAllMessages(): MessageRow[] {
  const sql = `SELECT * FROM messages`;
  const result = db.prepare(sql).all();
  return result as unknown as MessageRow[];
}

export function getMessagesByUserId(userId: number): MessageRow[] {
  const sql = `SELECT * FROM messages 
              WHERE sender_id = ? OR recipient_id = ? 
              ORDER BY timestamp ASC`;
  const result = db.prepare(sql).all(userId, userId);
  return result as unknown as MessageRow[];
}

export function deleteMessageById(id: number): void {
  const sql = `DELETE FROM messages WHERE id = ?`;
  db.prepare(sql).run(id);
}

