  }

  const user = users.find(u => u.username === username && u.password === password);

  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // In a real app, we would generate a JWT token here
  return res.json({
    user: {
      id: user.id,
      username: user.username,
      role: user.role
    },
    token: "mock-jwt-token"
  });
});

// Session management endpoint
router.get("/session", (req: Request, res: Response) => {
  // This would typically verify a JWT token
  const authHeader = req.headers.authorization;

  if (!authHeader) {
    return res.status(401).json({ error: "No authorization header" });
  }

  // Mock verification - in reality this would decode and validate the token
  const token = authHeader.split(" ")[1];
  if (!token || token !== "mock-jwt-token") {
    return res.status(401).json({ error: "Invalid token" });
  }

  // For demo purposes, we'll just return a mock user
  return res.json({
    user: {
      id: 1,
      username: "dr_smith",
      role: "doctor"
    }
  });
});

// Role-based access control middleware
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    const authHeader = req.headers.authorization;
    if (!authHeader) {
      return res.status(401).json({ error: "No authorization header" });
    }

    const token = authHeader.split(" ")[1];
    if (!token || token !== "mock-jwt-token") {
      return res.status(401).json({ error: "Invalid token" });
    }

    // Mock role validation
    const user = users[0]; // Mock user for demo
    if (user.role !== requiredRole) {
      return res.status(403).json({ error: "Insufficient permissions" });
    }

    next();
  };
};

// Example protected route - only doctors can access
router.get("/protected/doctor-only", requireRole("doctor"), (req: Request, res: Response) => {
  return res.json({ message: "Access granted to doctors only" });
});

// Example protected route - only administrators can access
