{"code":"import { useEffect, useState } from "react";

interface Category {
  id: number;
  name: string;
}

interface Submission {
  id: number;
  title: string;
  category: string;
  status: string;
}

export function AuthorSubmissionForm() {
  const [categories, setCategories] = useState<Category[]>([]);
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [title, setTitle] = useState("");
  const [selectedCategory, setSelectedCategory] = useState<number | null>(null);
  const [file, setFile] = useState<File | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchCategories = async () => {
      try {
        const response = await fetch("/api/submissions-api/");
        if (!response.ok) {
          throw new Error(`Failed to fetch categories: ${response.status}`);
        }
        const data = await response.json();
        setCategories(data);
      } catch (err: unknown) {
        if (err instanceof Error) {
          setError("Error loading categories: " + err.message);
        } else {
          setError("Error loading categories: Unknown error");
        }
      } finally {
        setLoading(false);
      }
    };

    const fetchSubmissions = async () => {
      try {
        const response = await fetch("/api/submissions-api/");
        if (!response.ok) {
          throw new Error(`Failed to fetch submissions: ${response.status}`);
        }
        const data = await response.json();
        setSubmissions(data);
      } catch (err: unknown) {
        if (err instanceof Error) {
          setError("Error loading submissions: " + err.message);
        } else {
          setError("Error loading submissions: Unknown error");
        }
      }
    };

    fetchCategories();
    fetchSubmissions();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || selectedCategory === null || !file) {
      setError("Please fill all fields and select a file.");
      return;
    }

    try {
      const formData = new FormData();
      formData.append("title", title);
      formData.append("categoryId", selectedCategory.toString());
      formData.append("manuscript", file);

      const response = await fetch("/api/submissions-api/", {
        method: "POST",
        body: formData,
      });

      if (!response.ok) {
        throw new Error(`Failed to submit manuscript: ${response.status}`);
      }

      // Reset form
      setTitle("");
      setSelectedCategory(null);
      setFile(null);
      setError(null);

      // Refresh submissions
      const submissionsResponse = await fetch("/api/submissions-api/");
      if (submissionsResponse.ok) {
        const submissionsData = await submissionsResponse.json();
        setSubmissions(submissionsData);
      }
    } catch (err: unknown) {
      if (err instanceof Error) {
        setError("Error submitting manuscript: " + err.message);
      } else {
        setError("Error submitting manuscript: Unknown error");
      }
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  const containerStyle: React.CSSProperties = {
    maxWidth: "800px",
    margin: "0 auto",
    padding: "20px",
    fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
  };

  const formStyle: React.CSSProperties = {
    backgroundColor: "#f9f9f9",
    padding: "20px",
    borderRadius: "8px",
    marginBottom: "20px",
  };

  const inputStyle: React.CSSProperties = {
    width: "100%",
    padding: "10px",
    marginBottom: "10px",
    borderRadius: "4px",
    border: "1px solid #ccc",
  };

  const buttonStyle: React.CSSProperties = {
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    padding: "10px 20px",
    borderRadius: "4px",
    cursor: "pointer",
    fontWeight: "bold",
  };

  const submissionListStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
  };

  const submissionCardStyle: React.CSSProperties = {
    border: "1px solid #ddd",
    borderRadius: "4px",
    padding: "15px",
    backgroundColor: "#fff",
  };

  return (
    <div style={containerStyle}>
      <h1>Submit Your Manuscript</h1>

      {error && <div style={{ color: "red", marginBottom: "10px" }}>{error}</div>}

      <form onSubmit={handleSubmit} style={formStyle}>
        <input
          type="text"
          placeholder="Manuscript Title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          style={inputStyle}
        />

        <select
          value={selectedCategory ?? ""}
          onChange={(e) => setSelectedCategory(Number(e.target.value))}
          style={inputStyle}
        >
          <option value="">Select Category</option>
          {categories.map((category) => (
            <option key={category.id} value={category.id}>
              {category.name}
            </option>
          ))}
        </select>

        <input
          type="file"
          accept=".pdf,.doc,.docx"
          onChange={(e) => setFile(e.target.files?.[0] || null)}
          style={inputStyle}
        />

        <button type="submit" style={buttonStyle}>Submit Manuscript</button>
      </form>

      <h2>Your Submissions</h2>

      {submissions.length === 0 ? (
        <p>No submissions yet.</p>
      ) : (
        <div style={submissionListStyle}>
          {submissions.map((submission) => (
            <div key={submission.id} style={submissionCardStyle}>
              <strong>{submission.title}</strong> - {submission.category} - {submission.status}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

