  const actorId = Number(req.params.actorId);
  const showId = Number(req.params.showId);
  const slotId = Number(req.params.slotId);
  const audition = getAudition(actorId, showId, slotId);
  if (audition) {
    res.json(audition);
  } else {
    res.status(404).send("Audition not found");
  }
});

