    if (!paper) {
      return res.status(404).json({ error: "Paper not found" });
    }
    res.json(paper);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// POST /papers - Create a new paper
router.post("/papers", async (req: Request, res: Response) => {
  try {
    const { title, authors, year } = req.body;
    if (!title || !authors || !year) {
      return res.status(400).json({ error: "Title, authors, and year are required" });
    }
    const newPaper = await mockDatabase.create({ title, authors, year });
    res.status(201).json(newPaper);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// PUT /papers/:id - Update a paper
router.put("/papers/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid paper ID" });
    }
    const { title, authors, year } = req.body;
    const updatedPaper = await mockDatabase.update(id, { title, authors, year });
    if (!updatedPaper) {
      return res.status(404).json({ error: "Paper not found" });
    }
    res.json(updatedPaper);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// DELETE /papers/:id - Delete a paper
router.delete("/papers/:id", async (req: Request, res: Response) => {
