{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface BookmarkRow {
  id: number;
  title: string;
  url: string;
  notes: string | null;
}

interface TagRow {
  id: number;
  name: string;
}

interface BookmarkTagRow {
  bookmark_id: number;
  tag_id: number;
}

const initSql = `
  CREATE TABLE IF NOT EXISTS bookmarks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    url TEXT NOT NULL,
    notes TEXT
  );

  CREATE TABLE IF NOT EXISTS tags (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT UNIQUE NOT NULL
  );

  CREATE TABLE IF NOT EXISTS bookmark_tags (
    bookmark_id INTEGER,
    tag_id INTEGER,
    FOREIGN KEY (bookmark_id) REFERENCES bookmarks(id) ON DELETE CASCADE,
    FOREIGN KEY (tag_id) REFERENCES tags(id) ON DELETE CASCADE
  );
`;

db.exec(initSql);

export function getAllBookmarks(): BookmarkRow[] {
  const stmt = db.prepare(`
    SELECT id, title, url, notes
    FROM bookmarks
    ORDER BY id
  `);
  return stmt.all() as unknown as BookmarkRow[];
}

export function getBookmarkById(id: number): BookmarkRow | undefined {
  const stmt = db.prepare(`
    SELECT id, title, url, notes
    FROM bookmarks
    WHERE id = ?
  `);
  const result = stmt.get(id);
  return result as unknown as BookmarkRow | undefined;
}

export function insertBookmark(
  title: string,
  url: string,
  notes: string | null = null
): number {
  const stmt = db.prepare(`
    INSERT INTO bookmarks (title, url, notes)
    VALUES (?, ?, ?)
  `);
  const result = stmt.run(title, url, notes);
  return Number(result.lastInsertRowid);
}

export function updateBookmark(
  id: number,
  title: string,
  url: string,
  notes: string | null = null
): void {
  const stmt = db.prepare(`
    UPDATE bookmarks
    SET title = ?, url = ?, notes = ?
    WHERE id = ?
  `);
  stmt.run(title, url, notes, id);
}

export function deleteBookmark(id: number): void {
  const stmt = db.prepare(`
    DELETE FROM bookmarks
    WHERE id = ?
  `);
  stmt.run(id);
}

export function getTagsForBookmark(bookmarkId: number): TagRow[] {
  const stmt = db.prepare(`
    SELECT t.id, t.name
    FROM tags t
    JOIN bookmark_tags bt ON t.id = bt.tag_id
    WHERE bt.bookmark_id = ?
  `);
  return stmt.all(bookmarkId) as unknown as TagRow[];
}

export function addTagToBookmark(bookmarkId: number, tagName: string): void {
  // First, ensure the tag exists
  const tagStmt = db.prepare(`
    INSERT OR IGNORE INTO tags (name)
    VALUES (?)
  `);
  tagStmt.run(tagName);

  // Then link the tag to the bookmark
  const linkStmt = db.prepare(`
    INSERT OR IGNORE INTO bookmark_tags (bookmark_id, tag_id)
    VALUES (?, (SELECT id FROM tags WHERE name = ?))
  `);
  linkStmt.run(bookmarkId, tagName);
}

// Seed data
const seedBookmarks = [
  {
    title: "TypeScript Documentation",
    url: "https://www.typescriptlang.org/docs/",
    notes: "Official docs for TypeScript"
  },
  {
    title: "Node.js Official Site",
    url: "https://nodejs.org/en/",
    notes: "Node.js runtime documentation"
  },
  {
    title: "GitHub",
    url: "https://github.com/",
    notes: "Code hosting platform"
  }
];

const seedTags = ["documentation", "tooling", "development"];

// Insert seed data if tables are empty
if (getAllBookmarks().length === 0) {
  for (const bookmark of seedBookmarks) {
    const bookmarkId = insertBookmark(bookmark.title, bookmark.url, bookmark.notes);

    // Add some tags to the first bookmark
    if (bookmarkId === 1) {
      for (let i = 0; i < Math.min(seedTags.length, 2); i++) {
        addTagToBookmark(bookmarkId, seedTags[i]);
      }
    }
  }
}
"}

