{"code":"import { useEffect, useState } from "react";

interface Application {
  id: string;
  applicantName: string;
  applicantEmail: string;
  applicationDate: string;
  status: string;
  fields: Record<string, string>;
  statusHistory: StatusChange[];
}

interface StatusChange {
  date: string;
  oldStatus: string;
  newStatus: string;
  changedBy: string;
}

export function ApplicationDetail({ applicationId }: { applicationId: string }) {
  const [application, setApplication] = useState<Application | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newStatus, setNewStatus] = useState("");

  useEffect(() => {
    const fetchApplication = async () => {
      try {
        const response = await fetch(`/api/applications/${applicationId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch application: ${response.status}`);
        }
        const data = await response.json();
        setApplication(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchApplication();
  }, [applicationId]);

  const handleStatusUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!application || !newStatus) return;

    try {
      const response = await fetch(`/api/applications/${applicationId}/status`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status: newStatus }),
      });

      if (!response.ok) {
        throw new Error(`Failed to update status: ${response.status}`);
      }

      // Refresh the application data
      const updatedResponse = await fetch(`/api/applications/${applicationId}`);
      if (!updatedResponse.ok) {
        throw new Error(`Failed to refresh application: ${updatedResponse.status}`);
      }
      const updatedData = await updatedResponse.json();
      setApplication(updatedData);
      setNewStatus("");
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (!application) {
    return <div style={{ textAlign: "center", padding: "20px" }}>No application found</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Application Details</h1>

      <div style={{ marginBottom: "20px", padding: "15px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2>Applicant Information</h2>
        <p><strong>Name:</strong> {application.applicantName}</p>
        <p><strong>Email:</strong> {application.applicantEmail}</p>
        <p><strong>Application Date:</strong> {application.applicationDate}</p>
        <p><strong>Status:</strong> {application.status}</p>
      </div>

      <div style={{ marginBottom: "20px", padding: "15px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2>Submitted Fields</h2>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: "10px" }}>
          {Object.entries(application.fields).map(([key, value]) => (
            <div key={key} style={{ marginBottom: "10px" }}>
              <strong>{key}:</strong>
              <div>{value}</div>
            </div>
          ))}
        </div>
      </div>

      <div style={{ marginBottom: "20px", padding: "15px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2>Status History</h2>
        {application.statusHistory.length > 0 ? (
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr style={{ borderBottom: "1px solid #ccc" }}>
                <th style={{ textAlign: "left", padding: "8px" }}>Date</th>
                <th style={{ textAlign: "left", padding: "8px" }}>Old Status</th>
                <th style={{ textAlign: "left", padding: "8px" }}>New Status</th>
                <th style={{ textAlign: "left", padding: "8px" }}>Changed By</th>
              </tr>
            </thead>
            <tbody>
              {application.statusHistory.map((change, index) => (
                <tr key={index} style={{ borderBottom: "1px solid #eee" }}>
                  <td style={{ padding: "8px" }}>{change.date}</td>
                  <td style={{ padding: "8px" }}>{change.oldStatus}</td>
                  <td style={{ padding: "8px" }}>{change.newStatus}</td>
                  <td style={{ padding: "8px" }}>{change.changedBy}</td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <p>No status changes recorded.</p>
        )}
      </div>

      <div style={{ padding: "15px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2>Update Status</h2>
        <form onSubmit={handleStatusUpdate}>
          <div style={{ marginBottom: "10px" }}>
            <label htmlFor="statusSelect" style={{ display: "block", marginBottom: "5px" }}>
              New Status:
            </label>
            <select
              id="statusSelect"
              value={newStatus}
              onChange={(e) => setNewStatus(e.target.value)}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            >
              <option value="">Select a status</option>
              <option value="pending">Pending</option>
              <option value="approved">Approved</option>
              <option value="rejected">Rejected</option>
              <option value="completed">Completed</option>
            </select>
          </div>
          <button
            type="submit"
            style={{
              backgroundColor: "#007bff",
              color: "white",
              border: "none",
              padding: "10px 20px",
              borderRadius: "4px",
              cursor: "pointer",
              fontSize: "16px"
            }}
          >
            Update Status
          </button>
        </form>
      </div>
    </div>
  );
}
"}

