{"code":"import { useEffect, useState } from "react";

interface Donation {
  id: number;
  donorName: string;
  amount: number;
  donationDate: string;
  status: string;
}

export function DonationList() {
  const [donations, setDonations] = useState<Donation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [sortConfig, setSortConfig] = useState<{ key: keyof Donation; direction: 'asc' | 'desc' } | null>(null);

  useEffect(() => {
    fetchDonations();
  }, []);

  const fetchDonations = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/donations');
      if (!response.ok) {
        throw new Error('Failed to fetch donations');
      }
      const data = await response.json();
      setDonations(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/donations/${id}`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        throw new Error('Failed to delete donation');
      }
      // Refresh the list after deletion
      fetchDonations();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleSort = (key: keyof Donation) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const sortedDonations = [...donations];
  if (sortConfig !== null) {
    sortedDonations.sort((a, b) => {
      if (a[sortConfig.key] < b[sortConfig.key]) {
        return sortConfig.direction === 'asc' ? -1 : 1;
      }
      if (a[sortConfig.key] > b[sortConfig.key]) {
        return sortConfig.direction === 'asc' ? 1 : -1;
      }
      return 0;
    });
  }

  const filteredDonations = sortedDonations.filter(donation =>
    donation.donorName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    donation.status.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Donation List</h1>

      <div style={{ marginBottom: '20px' }}>
        <input
          type="text"
          placeholder="Search by donor name or status..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: '100%', padding: '10px', borderRadius: '4px', border: '1px solid #ccc' }}
        />
      </div>

      {filteredDonations.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No donations found.</p>
      ) : (
        <div style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ backgroundColor: '#f2f2f2' }}>
                <th style={{ padding: '10px', border: '1px solid #ddd', cursor: 'pointer' }} onClick={() => handleSort('donorName')}>
                  Donor Name
                </th>
                <th style={{ padding: '10px', border: '1px solid #ddd', cursor: 'pointer' }} onClick={() => handleSort('amount')}>
                  Amount
                </th>
                <th style={{ padding: '10px', border: '1px solid #ddd', cursor: 'pointer' }} onClick={() => handleSort('donationDate')}>
                  Date
                </th>
                <th style={{ padding: '10px', border: '1px solid #ddd', cursor: 'pointer' }} onClick={() => handleSort('status')}>
                  Status
                </th>
                <th style={{ padding: '10px', border: '1px solid #ddd' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredDonations.map((donation) => (
                <tr key={donation.id}>
                  <td style={{ padding: '10px', border: '1px solid #ddd' }}>{donation.donorName}</td>
                  <td style={{ padding: '10px', border: '1px solid #ddd' }}>${donation.amount.toFixed(2)}</td>
                  <td style={{ padding: '10px', border: '1px solid #ddd' }}>{new Date(donation.donationDate).toLocaleDateString()}</td>
                  <td style={{ padding: '10px', border: '1px solid #ddd' }}>{donation.status}</td>
                  <td style={{ padding: '10px', border: '1px solid #ddd' }}>
                    <button 
                      onClick={() => {
                        // In a real app, this would navigate to an edit page
                        alert(`Edit donation ${donation.id}`);
                      }}
                      style={{ marginRight: '10px', padding: '5px 10px', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
                    >
                      Edit
                    </button>
                    <button 
                      onClick={() => handleDelete(donation.id)}
                      style={{ padding: '5px 10px', backgroundColor: '#dc3545', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface Post {
  id: number;
  created_at: string;
  updated_at: string;
  title: string;
  content: string;
  status: "published" | "draft";
}

const createPostsTable = `
  CREATE TABLE IF NOT EXISTS posts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    title TEXT NOT NULL,
    content TEXT NOT NULL,
    status TEXT NOT NULL CHECK(status IN ('published', 'draft'))
  );
`;

db.exec(createPostsTable);

export const getAllPosts = (): Post[] => {
  const stmt = db.prepare(`SELECT * FROM posts ORDER BY created_at DESC`);
  return stmt.all() as unknown as Post[];
};

export const getPostById = (id: number): Post | undefined => {
  const stmt = db.prepare(`SELECT * FROM posts WHERE id = ?`);
  return stmt.get(id) as unknown as Post | undefined;
};

export const insertPost = (post: Omit<Post, "id" | "created_at" | "updated_at">): number => {
  const stmt = db.prepare(
    `INSERT INTO posts (title, content, status, created_at, updated_at) VALUES (?, ?, ?, ?, ?)`
  );
  const result = stmt.run(post.title, post.content, post.status, new Date().toISOString(), new Date().toISOString());
  return Number(result.lastInsertRowid);
};

export const updatePost = (
  id: number,
  post: Partial<Omit<Post, "id" | "created_at" | "updated_at">>
): boolean => {
  const fields = Object.keys(post);
  if (fields.length === 0) return false;

  const setClause = fields.map(field => `${field} = ?`).join(", ");
  const values = [...Object.values(post), id];

  const stmt = db.prepare(`UPDATE posts SET ${setClause}, updated_at = ? WHERE id = ?`);
  const result = stmt.run(...values, new Date().toISOString());
  return result.changes > 0;
};

export const deletePost = (id: number): boolean => {
  const stmt = db.prepare(`DELETE FROM posts WHERE id = ?`);
  const result = stmt.run(id);
  return result.changes > 0;
};

// Seed data
if (getAllPosts().length === 0) {
  insertPost({
    title: "Getting Started with TypeScript",
    content: "TypeScript is a superset of JavaScript that adds static typing...",
    status: "published"
  });

  insertPost({
    title: "Understanding React Hooks",
    content: "React Hooks allow you to use state and other React features without writing a class...",
    status: "draft"
  });

  insertPost({
    title: "Node.js Best Practices",
    content: "When building Node.js applications, consider performance and security...",
    status: "published"
  });

  insertPost({
    title: "Mastering CSS Grid",
    content: "CSS Grid Layout is a two-dimensional layout system for the web...",
    status: "draft"
  });

  insertPost({
    title: "Building RESTful APIs",
    content: "RESTful APIs are designed around resources and HTTP methods...",
    status: "published"
  });
}
"}

