  );

  if (!user) {
    return res
      .status(401)
      .json({ error: "Invalid username or password" });
  }

  // In a real app, we would generate a JWT token here
  return res.json({
    user: { id: user.id, username: user.username, role: user.role },
    // token: generateToken(user)
  });
});

// Middleware to check if user has staff role
const requireStaffRole = (req: Request, res: Response, next: Function) => {
  // This is a mock implementation - in a real app this would verify a JWT token
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Authorization header missing" });
  }

