{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data to simulate billing records
const billingRecords = [
  { id: "1", customerId: "101", usageKwh: 350, billAmount: 42.5, billingCycle: "2023-06" },
  { id: "2", customerId: "102", usageKwh: 280, billAmount: 33.6, billingCycle: "2023-06" },
];

// Get all billing records
router.get("/", (req: Request, res: Response) => {
  res.json(billingRecords);
});

// Get a specific billing record by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const record = billingRecords.find(r => r.id === id);

  if (!record) {
    return res.status(404).json({ error: "Billing record not found" });
  }

  res.json(record);
});

// Create a new billing record
router.post("/", (req: Request, res: Response) => {
  const { customerId, usageKwh, billAmount, billingCycle } = req.body;

  // Validate required fields
  if (!customerId || !usageKwh || !billAmount || !billingCycle) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  // Calculate new ID
  const newId = (billingRecords.length + 1).toString();

  // Create new record
  const newRecord = {
    id: newId,
    customerId,
    usageKwh: Number(usageKwh),
    billAmount: Number(billAmount),
    billingCycle,
  };

  billingRecords.push(newRecord);

  res.status(201).json(newRecord);
});

// Update a billing record
router.put("/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const { customerId, usageKwh, billAmount, billingCycle } = req.body;

  const index = billingRecords.findIndex(r => r.id === id);

  if (index === -1) {
    return res.status(404).json({ error: "Billing record not found" });
  }

  // Validate required fields
  if (!customerId || !usageKwh || !billAmount || !billingCycle) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  // Update record
  billingRecords[index] = {
    id,
    customerId,
    usageKwh: Number(usageKwh),
    billAmount: Number(billAmount),
    billingCycle,
  };

  res.json(billingRecords[index]);
});

// Delete a billing record
router.delete("/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const index = billingRecords.findIndex(r => r.id === id);

  if (index === -1) {
    return res.status(404).json({ error: "Billing record not found" });
  }

  billingRecords.splice(index, 1);

  res.json({ message: "Billing record deleted successfully" });
});
"}

{"code":"import { useEffect, useState } from "react";

interface Expense {
  id: number;
  description: string;
  amount: number;
  date: string;
}

export function MemberOnlyView() {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [description, setDescription] = useState("");
  const [amount, setAmount] = useState("");
  const [date, setDate] = useState("");

  useEffect(() => {
    fetchExpenses();
  }, []);

  const fetchExpenses = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/expenses-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setExpenses(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const newExpense = {
        description,
        amount: Number(amount),
        date,
      };
      const response = await fetch('/api/expenses-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newExpense),
      });
      if (!response.ok) {
        throw new Error(`Failed to submit: ${response.status} ${response.statusText}`);
      }
      setDescription("");
      setAmount("");
      setDate("");
      await fetchExpenses();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/expenses-api/${id}`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        throw new Error(`Failed to delete: ${response.status} ${response.statusText}`);
      }
      await fetchExpenses();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>My Expenses</h1>

      {expenses.length === 0 ? (
        <p style={{ textAlign: 'center', fontStyle: 'italic' }}>No expenses submitted yet.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {expenses.map(expense => (
            <div key={expense.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <div>
                  <strong>{expense.description}</strong>
                  <br />
                  Amount: ${expense.amount.toFixed(2)}
                  <br />
                  Date: {new Date(expense.date).toLocaleDateString()}
                </div>
                <button 
                  onClick={() => handleDelete(expense.id)}
                  style={{ backgroundColor: '#ff4d4d', color: 'white', border: 'none', borderRadius: '4px', padding: '5px 10px' }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      <h2 style={{ marginTop: '30px', textAlign: 'center' }}>Submit New Expense</h2>
      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
        <input
          type="text"
          placeholder="Description"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          required
        />
        <input
          type="number"
          placeholder="Amount"
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
          style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          required
          step="0.01"
        />
        <input
          type="date"
          value={date}
          onChange={(e) => setDate(e.target.value)}
          style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          required
        />
        <button 
          type="submit" 
          style={{ backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px', padding: '10px', cursor: 'pointer' }}
        >
          Submit Expense
        </button>
      </form>
    </div>
  );
}
"}

