{"code":"import { useEffect, useState } from "react";

export function AdminInterface() {
  const [dnsConfig, setDnsConfig] = useState<any>(null);
  const [dohConfig, setDohConfig] = useState<any>(null);
  const [dotConfig, setDotConfig] = useState<any>(null);
  const [dnscryptConfig, setDnscryptConfig] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [dnsRes, dohRes, dotRes, dnscryptRes] = await Promise.all([
          fetch('/api/dns-filtering-server/dns'),
          fetch('/api/dns-filtering-server/doh'),
          fetch('/api/dns-filtering-server/dot'),
          fetch('/api/dns-filtering-server/dnscrypt')
        ]);

        if (!dnsRes.ok || !dohRes.ok || !dotRes.ok || !dnscryptRes.ok) {
          throw new Error('Failed to fetch data');
        }

        const [dnsData, dohData, dotData, dnscryptData] = await Promise.all([
          dnsRes.json(),
          dohRes.json(),
          dotRes.json(),
          dnscryptRes.json()
        ]);

        setDnsConfig(dnsData);
        setDohConfig(dohData);
        setDotConfig(dotData);
        setDnscryptConfig(dnscryptData);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;

