{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only enforce password security on POST requests to the login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if password is present in request body
  if (!req.body || typeof req.body.password !== "string") {
    res.status(400).json({ error: "Password is required" });
    return;
  }

  const password = req.body.password;

  // Check password strength requirements
  const minLength = 8;
  const hasUpperCase = /[A-Z]/.test(password);
  const hasLowerCase = /[a-z]/.test(password);
  const hasNumbers = /[0-9]/.test(password);
  const hasSpecialChar = /[!@#$%^&*(),.?":{}|<>]/.test(password);

  if (
    password.length < minLength ||
    !hasUpperCase ||
    !hasLowerCase ||
    !hasNumbers ||
    !hasSpecialChar
  ) {
    res.status(400).json({
      error: "Password must be at least 8 characters long and contain uppercase, lowercase, numbers, and special characters",
    });
    return;
  }

  // Hash the password using SHA-256 with a salt
  const salt = "canteen_salt";
  const hashedPassword = createHmac("sha256", salt)
    .update(password)
    .digest("hex");

  // Replace the password with the hashed version in the request body
  req.body.hashedPassword = hashedPassword;

  next();
}
"}

{"code":"import type { Request, Response, NextFunction } from "express";
