import { router as appointmentsRouter } from "../routes/appointments-api";
import { router as exportServiceRouter } from "../routes/export-service";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check ownership for export service routes
  if (!req.path.startsWith("/export")) {
    next();
    return;
  }

  // Check if the user is the owner
  const owner = req.headers["x-owner"];
  if (!owner || typeof owner !== "string") {
    res.status(403).json({ error: "Owner access required" });
    return;
  }

  // In a real implementation, we would verify the owner against a database
  // For now, we'll just check if the owner header matches a known owner
  // This is a simplified example - in practice, you'd have proper authentication logic
  const expectedOwner = process.env.OWNER_ID || "default-owner";

  if (owner !== expectedOwner) {
    res.status(403).json({ error: "Access denied: not the owner" });
    return;
  }

  next();
}
