{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("hotel-housekeeping.db");

interface Room {
  id: number;
  last_cleaned_by: string | null;
  last_cleaned_at: string | null;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS rooms (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    last_cleaned_by TEXT,
    last_cleaned_at TEXT
  )
`;

db.exec(createTableSql);

export function getAllRooms(): Room[] {
  const stmt = db.prepare("SELECT * FROM rooms");
  return stmt.all() as unknown as Room[];
}

export function getRoomById(id: number): Room | undefined {
  const stmt = db.prepare("SELECT * FROM rooms WHERE id = ?");
  return stmt.get(id) as unknown as Room | undefined;
}

export function insertRoom(lastCleanedBy: string | null, lastCleanedAt: string | null): number {
  const stmt = db.prepare(
    "INSERT INTO rooms (last_cleaned_by, last_cleaned_at) VALUES (?, ?)"
  );
  const result = stmt.run(lastCleanedBy, lastCleanedAt);
  return Number(result.lastInsertRowid);
}

export function updateRoom(id: number, lastCleanedBy: string | null, lastCleanedAt: string | null): void {
  const stmt = db.prepare(
    "UPDATE rooms SET last_cleaned_by = ?, last_cleaned_at = ? WHERE id = ?"
  );
  stmt.run(lastCleanedBy, lastCleanedAt, id);
}

export function deleteRoom(id: number): void {
  const stmt = db.prepare("DELETE FROM rooms WHERE id = ?");
  stmt.run(id);
}

// Seed data
if (getAllRooms().length === 0) {
  insertRoom("Alice Smith", "2023-05-15T08:30:00Z");
  insertRoom("Bob Johnson", "2023-05-14T14:15:00Z");
  insertRoom("Carol Williams", "2023-05-16T09:45:00Z");
  insertRoom("David Brown", "2023-05-13T16:20:00Z");
  insertRoom(null, null);
}
