  { id: "2", employeeId: "emp2", startDate: "2023-06-01", endDate: "2023-06-03", status: "pending" }
];

const findLeaveRequestById = (id: string) => {
  return mockLeaveRequests.find(request => request.id === id);
};

const createLeaveRequest = (request: any) => {
  const newRequest = {
    id: String(mockLeaveRequests.length + 1),
    ...request,
    status: request.status || "pending"
  };
  mockLeaveRequests.push(newRequest);
  return newRequest;
};

const updateLeaveRequest = (id: string, updates: any) => {
  const index = mockLeaveRequests.findIndex(request => request.id === id);
  if (index === -1) return null;

  mockLeaveRequests[index] = { ...mockLeaveRequests[index], ...updates };
  return mockLeaveRequests[index];
};

const deleteLeaveRequest = (id: string) => {
  const index = mockLeaveRequests.findIndex(request => request.id === id);
  if (index === -1) return false;

  mockLeaveRequests.splice(index, 1);
  return true;
};

