  // Basic validation
  if (!employeeId || !startDate || !endDate) {
    return res.status(400).json({ error: "employeeId, startDate, and endDate are required" });
  }

  const newLeaveRequest = createLeaveRequest({ employeeId, startDate, endDate, status });

  res.status(201).json(newLeaveRequest);
});

// PUT /leave-requests/:id - Update a leave request
router.put("/leave-requests/:id", (req: Request, res: Response) => {
  const { employeeId, startDate, endDate, status } = req.body;

  const updatedLeaveRequest = updateLeaveRequest(req.params.id, { employeeId, startDate, endDate, status });

  if (!updatedLeaveRequest) {
    return res.status(404).json({ error: "Leave request not found" });
  }

  res.json(updatedLeaveRequest);
});

// DELETE /leave-requests/:id - Delete a leave request
router.delete("/leave-requests/:id", (req: Request, res: Response) => {
  const deleted = deleteLeaveRequest(req.params.id);

  if (!deleted) {
    return res.status(404).json({ error: "Leave request not found" });
  }

  res.json({ message: "Leave request deleted successfully" });
});
