{"code":"import { useEffect, useState } from "react";

export function CollaborativeDocumentEditor() {
  const [documentId, setDocumentId] = useState<string>("");
  const [changes, setChanges] = useState<any[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!documentId) return;

    const fetchChanges = async () => {
      setLoading(true);
      setError(null);

      try {
        const response = await fetch(`/api/encrypted-sync-server/changes/${documentId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch changes: ${response.status} ${response.statusText}`);
        }
        const data = await response.json();
        setChanges(data.changes || []);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchChanges();

    // Poll for updates every 5 seconds
    const intervalId = setInterval(fetchChanges, 5000);

    return () => clearInterval(intervalId);
  }, [documentId]);

  const handleSync = async () => {
    if (!documentId) return;

    setLoading(true);
    setError(null);

    try {
      const response = await fetch(`/api/encrypted-sync-server/sync`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ documentId }),
      });

      if (!response.ok) {
        throw new Error(`Failed to sync: ${response.status} ${response.statusText}`);
      }

      // Refresh changes after sync
      const syncResponse = await fetch(`/api/encrypted-sync-server/changes/${documentId}`);
      if (!syncResponse.ok) {
        throw new Error(`Failed to fetch changes after sync: ${syncResponse.status} ${syncResponse.statusText}`);
      }

      const data = await syncResponse.json();
      setChanges(data.changes || []);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{
      fontFamily: 'system-ui, sans-serif',
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
    }}>
      <h1>Collaborative Document Editor</h1>

      <div style={{ marginBottom: '20px' }}>
        <label htmlFor="documentId" style={{ display: 'block', marginBottom: '5px' }}>
          Document ID:
        </label>
        <input
          id="documentId"
          type="text"
          value={documentId}
          onChange={(e) => setDocumentId(e.target.value)}
          style={{
            width: '100%',
            padding: '8px',
            borderRadius: '4px',
            border: '1px solid #ccc',
          }}
          placeholder="Enter document ID"
        />
      </div>

      <button
        onClick={handleSync}
        disabled={!documentId || loading}
        style={{
          backgroundColor: '#007bff',
          color: 'white',
          border: 'none',
          padding: '10px 16px',
          borderRadius: '4px',
          cursor: documentId && !loading ? 'pointer' : 'default',
          fontSize: '16px',
        }}
      >
        {loading ? 'Syncing...' : 'Sync Changes'}
      </button>

      {error && (
        <div style={{
          marginTop: '20px',
          padding: '10px',
          backgroundColor: '#f8d7da',
          borderColor: '#f5c6cb',
          color: '#721c24',
          borderRadius: '4px',
          border: '1px solid transparent',
        }}>
          Error: {error}
        </div>
      )}

      <h2 style={{ marginTop: '30px' }}>Recent Changes</h2>

      {loading ? (
        <p>Loading...</p>
      ) : changes.length === 0 ? (
        <p>No changes found.</p>
      ) : (
        <div style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '10px',
        }}>
          {changes.map((change, index) => (
            <div key={index} style={{
              padding: '10px',
              border: '1px solid #ddd',
              borderRadius: '4px',
              backgroundColor: '#f9f9f9',
            }}>
              <strong>Change #{index + 1}</strong>: {change.description || 'No description'}
              <br />
              <small>Timestamp: {new Date(change.timestamp).toLocaleString()}</small>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import { middleware } from "../middleware/role-based-login";
import { 
  db,
  deleteStockItem,
  getAllStockItems,
  getStockItemById,
  insertStockItem,
  updateStockItem
} from "../db/stock-items-table";

export const router = Router();

// Get all stock items
router.get("/stock", middleware, (req: Request, res: Response) => {
  try {
    const items = getAllStockItems();
    res.json(items);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch stock items" });
  }
});

// Get a specific stock item by ID
router.get("/stock/:id", middleware, (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID provided" });
    }

    const item = getStockItemById(id);
    if (!item) {
      return res.status(404).json({ error: "Stock item not found" });
    }

    res.json(item);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch stock item" });
  }
});

// Create a new stock item
router.post("/stock", middleware, (req: Request, res: Response) => {
  try {
    const { name, quantity, unit, expiry_date, last_consumed } = req.body;

    if (!name || !quantity || !unit || !expiry_date) {
      return res.status(400).json({ error: "Missing required fields: name, quantity, unit, expiry_date" });
    }

    const id = insertStockItem(name, quantity, unit, expiry_date, last_consumed || null);

    // Fetch the created item to send back
    const newItem = getStockItemById(id);
    if (!newItem) {
      return res.status(500).json({ error: "Failed to retrieve created item" });
    }

    res.status(201).json(newItem);
  } catch (error) {
    res.status(500).json({ error: "Failed to create stock item" });
  }
});

// Update a stock item
router.put("/stock/:id", middleware, (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID provided" });
    }

    const { name, quantity, unit, expiry_date, last_consumed } = req.body;

    if (!name || !quantity || !unit || !expiry_date) {
      return res.status(400).json({ error: "Missing required fields: name, quantity, unit, expiry_date" });
    }

    const existingItem = getStockItemById(id);
    if (!existingItem) {
      return res.status(404).json({ error: "Stock item not found" });
    }

    updateStockItem(id, name, quantity, unit, expiry_date, last_consumed || null);

    // Fetch the updated item to send back
    const updatedItem = getStockItemById(id);
    if (!updatedItem) {
      return res.status(500).json({ error: "Failed to retrieve updated item" });
    }

    res.json(updatedItem);
  } catch (error) {
    res.status(500).json({ error: "Failed to update stock item" });
  }
});

// Delete a stock item
router.delete("/stock/:id", middleware, (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID provided" });
    }

    const existingItem = getStockItemById(id);
    if (!existingItem) {
      return res.status(404).json({ error: "Stock item not found" });
    }

    deleteStockItem(id);

    res.json({ message: "Stock item deleted successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to delete stock item" });
  }
});
"}

{"code":"import { useEffect, useState } from "react";

interface Doctor {
  id: number;
  name: string;
  specialty: string;
}

interface TimeSlot {
  id: number;
  date: string;
  time: string;
  doctorId: number;
}

interface Appointment {
  id: number;
  date: string;
  time: string;
  doctorId: number;
  patientName: string;
}

export function AppointmentBookingView() {
  const [doctors, setDoctors] = useState<Doctor[]>([]);
  const [timeSlots, setTimeSlots] = useState<TimeSlot[]>([]);
  const [selectedDoctorId, setSelectedDoctorId] = useState<number | null>(null);
  const [selectedTimeSlotId, setSelectedTimeSlotId] = useState<number | null>(null);
  const [patientName, setPatientName] = useState<string>("");
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [appointments, setAppointments] = useState<Appointment[]>([]);

  useEffect(() => {
    fetchDoctors();
    fetchAppointments();
  }, []);

  const fetchDoctors = async () => {
    try {
      const response = await fetch('/api/appointments-api/');
      if (!response.ok) throw new Error('Failed to fetch doctors');
      const data = await response.json();
      setDoctors(data);
    } catch (err) {
      setError('Error loading doctors');
    } finally {
      setLoading(false);
    }
  };

  const fetchTimeSlots = async (doctorId: number) => {
    try {
      const response = await fetch(`/api/appointments-api/${doctorId}`);
      if (!response.ok) throw new Error('Failed to fetch time slots');
      const data = await response.json();
      setTimeSlots(data);
    } catch (err) {
      setError('Error loading time slots');
    }
  };

  const fetchAppointments = async () => {
    try {
      const response = await fetch('/api/appointments-api/');
      if (!response.ok) throw new Error('Failed to fetch appointments');
      const data = await response.json();
      setAppointments(data);
    } catch (err) {
      setError('Error loading appointments');
    }
  };

  const handleDoctorSelect = (doctorId: number) => {
    setSelectedDoctorId(doctorId);
    fetchTimeSlots(doctorId);
    setSelectedTimeSlotId(null);
  };

  const handleTimeSlotSelect = (timeSlotId: number) => {
    setSelectedTimeSlotId(timeSlotId);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedDoctorId || !selectedTimeSlotId || !patientName) return;

    try {
      const response = await fetch('/api/appointments-api/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          doctorId: selectedDoctorId,
          timeSlotId: selectedTimeSlotId,
          patientName
        })
      });

      if (!response.ok) throw new Error('Failed to book appointment');

      // Reset form
      setSelectedDoctorId(null);
      setSelectedTimeSlotId(null);
      setPatientName("");
      setTimeSlots([]);
      fetchAppointments();
    } catch (err) {
      setError('Error booking appointment');
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  return (
    <div style={{
      maxWidth: '600px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <h1 style={{ textAlign: 'center' }}>Book an Appointment</h1>

      {error && <p style={{ color: 'red', textAlign: 'center' }}>{error}</p>}

      <form onSubmit={handleSubmit} style={{ marginBottom: '30px' }}>
        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="patientName" style={{ display: 'block', marginBottom: '5px' }}>
            Your Name
