{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./kegs.db");

interface Keg {
  id: number;
  style: string;
  quantity: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS kegs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    style TEXT NOT NULL,
    quantity INTEGER NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllKegs(): Keg[] {
  const stmt = db.prepare("SELECT * FROM kegs");
  return stmt.all() as unknown as Keg[];
}

export function getKegById(id: number): Keg | undefined {
  const stmt = db.prepare("SELECT * FROM kegs WHERE id = ?");
  return stmt.get(id) as unknown as Keg | undefined;
}

export function insertKeg(style: string, quantity: number): number {
  const stmt = db.prepare("INSERT INTO kegs (style, quantity) VALUES (?, ?)");
  const result = stmt.run(style, quantity);
  return Number(result.lastInsertRowid);
}

export function updateKeg(id: number, style: string, quantity: number): void {
  const stmt = db.prepare("UPDATE kegs SET style = ?, quantity = ? WHERE id = ?");
  stmt.run(style, quantity, id);
}

export function deleteKeg(id: number): void {
  const stmt = db.prepare("DELETE FROM kegs WHERE id = ?");
  stmt.run(id);
}

// Seed data
if (getAllKegs().length === 0) {
  insertKeg("IPA", 120);
  insertKeg("Stout", 80);
  insertKeg("Pilsner", 150);
  insertKeg("Wheat Beer", 90);
  insertKeg("Pale Ale", 110);
}
"}

