  const weekDate = req.params.weekDate;
  const { contents } = req.body;

  if (isNaN(memberId)) {
    return res.status(400).json({ error: "Invalid member ID" });
  }

  if (!contents) {
    return res.status(400).json({ error: "Missing required field: contents" });
  }

  try {
    const updatedRows = updateBoxContents(memberId, weekDate, contents);
    if (updatedRows === 0) {
      return res.status(404).json({ error: "Box contents not found" });
    }
    res.json({ message: "Box contents updated successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to update box contents" });
  }
});

