{"code":"import { useEffect, useState } from "react";

interface Booking {
  id: string;
  roomId: string;
  startDate: string;
  endDate: string;
  startTime: string;
  endTime: string;
}

interface Room {
  id: string;
  name: string;
  capacity: number;
}

export function AdminDoubleBookGuard() {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [rooms, setRooms] = useState<Room[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [bookingsResponse, roomsResponse] = await Promise.all([
          fetch('/api/rooms-api/'),
          fetch('/api/rooms-api'),
        ]);

        if (!bookingsResponse.ok || !roomsResponse.ok) {
          throw new Error('Failed to fetch data');
        }

        const bookingsData = await bookingsResponse.json();
        const roomsData = await roomsResponse.json();

        setBookings(bookingsData);
        setRooms(roomsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    const formData = new FormData(e.currentTarget);
    const newBooking = {
      roomId: formData.get('roomId') as string,
      startDate: formData.get('startDate') as string,
      endDate: formData.get('endDate') as string,
      startTime: formData.get('startTime') as string,
      endTime: formData.get('endTime') as string,
    };

    try {
      const response = await fetch('/api/double-booking-guard/bookings', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(newBooking),
      });

      if (!response.ok) {
        throw new Error('Booking failed due to double booking');
      }

      // Refresh data after successful booking
      const [bookingsResponse, roomsResponse] = await Promise.all([
        fetch('/api/rooms-api/'),
        fetch('/api/rooms-api'),
      ]);

      if (bookingsResponse.ok && roomsResponse.ok) {
        const bookingsData = await bookingsResponse.json();
        const roomsData = await roomsResponse.json();

        setBookings(bookingsData);
        setRooms(roomsData);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Admin Double-Book Guard</h1>

      <h2>Current Bookings</h2>
      {bookings.length === 0 ? (
        <p>No bookings found.</p>
      ) : (
        <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '20px' }}>
          <thead>
            <tr style={{ borderBottom: '1px solid #ccc' }}>
              <th style={{ textAlign: 'left', padding: '8px' }}>Room</th>
              <th style={{ textAlign: 'left', padding: '8px' }}>Start Date</th>
              <th style={{ textAlign: 'left', padding: '8px' }}>End Date</th>
              <th style={{ textAlign: 'left', padding: '8px' }}>Start Time</th>
              <th style={{ textAlign: 'left', padding: '8px' }}>End Time</th>
            </tr>
          </thead>
          <tbody>
            {bookings.map(booking => {
              const room = rooms.find(r => r.id === booking.roomId);
              return (
                <tr key={booking.id} style={{ borderBottom: '1px solid #eee' }}>
                  <td style={{ padding: '8px' }}>{room?.name || 'Unknown Room'}</td>
                  <td style={{ padding: '8px' }}>{booking.startDate}</td>
                  <td style={{ padding: '8px' }}>{booking.endDate}</td>
                  <td style={{ padding: '8px' }}>{booking.startTime}</td>
                  <td style={{ padding: '8px' }}>{booking.endTime}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}

      <h2>Create New Booking</h2>
      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
        <div>
          <label htmlFor="roomId">Room:</label>
          <select id="roomId" name="roomId" required style={{ width: '100%', padding: '8px', marginTop: '5px' }}>
            <option value="">Select a room</option>
            {rooms.map(room => (
              <option key={room.id} value={room.id}>{room.name}</option>
            ))}
          </select>
        </div>

        <div>
          <label htmlFor="startDate">Start Date:</label>
          <input 
            type="date" 
            id="startDate" 
            name="startDate" 
            required 
            style={{ width: '100%', padding: '8px', marginTop: '5px' }}
          />
        </div>

        <div>
          <label htmlFor="endDate">End Date:</label>
          <input 
            type="date" 
            id="endDate" 
            name="endDate" 
            required 
            style={{ width: '100%', padding: '8px', marginTop: '5px' }}
          />
        </div>

        <div>
          <label htmlFor="startTime">Start Time:</label>
          <input 
            type="time" 
            id="startTime" 
            name="startTime" 
            required 
            style={{ width: '100%', padding: '8px', marginTop: '5px' }}
          />
        </div>

        <div>
          <label htmlFor="endTime">End Time:</label>
          <input 
            type="time" 
            id="endTime" 
            name="endTime" 
            required 
            style={{ width: '100%', padding: '8px', marginTop: '5px' }}
          />
        </div>

        <button 
          type="submit" 
          style={{ padding: '10px', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
        >
          Create Booking
        </button>
      </form>
    </div>
  );
}
