{"code":"import { useEffect, useState } from "react";

interface FeedingLog {
  id?: number;
  species: string;
  amountFed: number;
  time: string;
}

export function FeedingLogForm() {
  const [feedings, setFeedings] = useState<FeedingLog[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [species, setSpecies] = useState("");
  const [amountFed, setAmountFed] = useState("");
  const [time, setTime] = useState("");

  useEffect(() => {
    fetchFeedings();
  }, []);

  const fetchFeedings = async () => {
    try {
      const response = await fetch('/api/feedings-api/');
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setFeedings(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = await fetch('/api/feedings-api/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          species,
          amountFed: Number(amountFed),
          time,
        }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      // Reset form
      setSpecies("");
      setAmountFed("");
      setTime("");

      // Refresh data
      await fetchFeedings();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) return <div style={{ textAlign: 'center' }}>Loading...</div>;

  if (error) return <div style={{ color: 'red', textAlign: 'center' }}>{error}</div>;

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui' }}>
      <h1>Feeding Log</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: '30px' }}>
