            id="amountFed"
            type="number"
            value={amountFed}
            onChange={(e) => setAmountFed(e.target.value)}
            required
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="time" style={{ display: 'block', marginBottom: '5px' }}>
            Time:
          </label>
          <input
            id="time"
            type="time"
