{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("museum.db");

interface Tour {
  id: number;
  docentId: number;
  exhibitId: number;
  scheduledTime: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS tours (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    docentId INTEGER NOT NULL,
    exhibitId INTEGER NOT NULL,
    scheduledTime TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllTours(): Tour[] {
  const stmt = db.prepare("SELECT * FROM tours");
  return stmt.all() as unknown as Tour[];
}

export function getTourById(id: number): Tour | undefined {
  const stmt = db.prepare("SELECT * FROM tours WHERE id = ?");
  return stmt.get(id) as unknown as Tour | undefined;
}

export function insertTour(tour: Omit<Tour, "id">): number {
  const stmt = db.prepare(
    "INSERT INTO tours (docentId, exhibitId, scheduledTime) VALUES (?, ?, ?)"
  );
  const result = stmt.run(tour.docentId, tour.exhibitId, tour.scheduledTime);
  return Number(result.lastInsertRowid);
}

export function updateTour(id: number, tour: Partial<Tour>): number {
  const fields = [];
  const values = [];

  if (tour.docentId !== undefined) {
    fields.push("docentId = ?");
    values.push(tour.docentId);
  }

  if (tour.exhibitId !== undefined) {
    fields.push("exhibitId = ?");
    values.push(tour.exhibitId);
  }

  if (tour.scheduledTime !== undefined) {
    fields.push("scheduledTime = ?");
    values.push(tour.scheduledTime);
  }

  if (fields.length === 0) {
    throw new Error("No fields to update");
  }

  values.push(id);

  const sql = `UPDATE tours SET ${fields.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  const result = stmt.run(...values);
  return Number(result.changes);
}

export function deleteTour(id: number): number {
  const stmt = db.prepare("DELETE FROM tours WHERE id = ?");
  const result = stmt.run(id);
  return Number(result.changes);
}

// Insert sample data if table is empty
if (getAllTours().length === 0) {
  insertTour({
