{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only apply role-based access control to protected routes
  const protectedPaths = ["/admin", "/instructor", "/student"];
  const isProtectedPath = protectedPaths.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath) {
    next();
    return;
  }

  // Check if user has proper role access
  const userRole = req.headers["x-user-role"] as string | undefined;

  if (!userRole) {
    res.status(401).json({ error: "Unauthorized: Missing role header" });
    return;
  }

  // Define role hierarchy
  const roles = {
    admin: 3,
    instructor: 2,
    student: 1
  };

  // Get required role for path
  let requiredRole: keyof typeof roles = "student";

  if (req.path.startsWith("/admin")) {
    requiredRole = "admin";
  } else if (req.path.startsWith("/instructor")) {
    requiredRole = "instructor";
  }

  // Validate role access
  if (roles[userRole as keyof typeof roles] < roles[requiredRole]) {
    res.status(403).json({ error: "Forbidden: Insufficient role permissions" });
    return;
  }

  next();
}
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real implementation these would connect to a database
const mockTasks = [
  { id: 1, description: "Clean room 101", status: "pending", assignedTo: "John Doe", dueDate: "2023-05-15" },
  { id: 2, description: "Restock supplies", status: "completed", assignedTo: "Jane Smith", dueDate: "2023-05-10" }
];

const findTaskById = (id: number) => {
  return mockTasks.find(task => task.id === id);
};

const createTask = (task: Omit<Task, "id">) => {
  const newTask = {
    id: mockTasks.length > 0 ? Math.max(...mockTasks.map(t => t.id)) + 1 : 1,
    ...task
  };
  mockTasks.push(newTask);
  return newTask;
};

const updateTask = (id: number, updates: Partial<Task>) => {
  const index = mockTasks.findIndex(task => task.id === id);
  if (index === -1) return null;
  mockTasks[index] = { ...mockTasks[index], ...updates };
  return mockTasks[index];
};

const deleteTask = (id: number) => {
  const index = mockTasks.findIndex(task => task.id === id);
  if (index === -1) return false;
  mockTasks.splice(index, 1);
  return true;
};

// Define the Task interface
interface Task {
  id: number;
  description: string;
  status: string;
  assignedTo: string;
  dueDate: string;
}

// GET /tasks - List all tasks
router.get("/tasks", (req: Request, res: Response) => {
  res.json(mockTasks);
});

// GET /tasks/:id - Get a specific task by ID
router.get("/tasks/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid task ID" });
  }

  const task = findTaskById(id);
  if (!task) {
    return res.status(404).json({ error: "Task not found" });
  }

  res.json(task);
});

// POST /tasks - Create a new task
router.post("/tasks", (req: Request, res: Response) => {
  const { description, status, assignedTo, dueDate } = req.body;

  if (!description || !status || !assignedTo || !dueDate) {
    return res.status(400).json({ error: "All fields are required" });
  }

  const newTask = createTask({ description, status, assignedTo, dueDate });
  res.status(201).json(newTask);
});

// PUT /tasks/:id - Update a task
router.put("/tasks/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid task ID" });
  }

  const { description, status, assignedTo, dueDate } = req.body;

  const updatedTask = updateTask(id, { description, status, assignedTo, dueDate });

  if (!updatedTask) {
    return res.status(404).json({ error: "Task not found" });
  }

  res.json(updatedTask);
});

// DELETE /tasks/:id - Delete a task
router.delete("/tasks/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid task ID" });
  }

  const deleted = deleteTask(id);

  if (!deleted) {
    return res.status(404).json({ error: "Task not found" });
  }

  res.json({ message: "Task deleted successfully" });
});
"}

