{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-protected routes
  if (!req.path.startsWith('/api/')) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ error: 'Missing or invalid authorization header' });
    return;
  }

  const token = authHeader.substring(7);
  const secret = process.env.JWT_SECRET;

  if (!secret) {
    res.status(500).json({ error: 'Server configuration error' });
    return;
  }

  // Simple token verification (in a real app, use proper JWT library)
  const [payload, signature] = token.split('.');
  if (!payload || !signature) {
    res.status(401).json({ error: 'Invalid token format' });
    return;
  }

  try {
    const expectedSignature = createHmac('sha256', secret)
      .update(payload)
      .digest('base64url');

    const expectedBuffer = Buffer.from(expectedSignature, 'base64url');
    const actualBuffer = Buffer.from(signature, 'base64url');

    if (actualBuffer.length !== expectedBuffer.length || 
        !timingSafeEqual(actualBuffer, expectedBuffer)) {
      res.status(401).json({ error: 'Invalid token signature' });
      return;
    }

    // Decode payload (simplified for this example)
    const decodedPayload = JSON.parse(Buffer.from(payload, 'base64url').toString());
    const userRole = decodedPayload.role;
    const userId = decodedPayload.userId;

    // Check role-based access control
    if (userRole === 'admin') {
      // Admin has full access
      next();
      return;
    }

    // For non-admin roles, check specific permissions
    if (userRole === 'doctor') {
      // Doctor can only access their own patients
      if (req.path.includes('/patients/') && req.params.patientId) {
        const patientId = req.params.patientId;
        // In a real implementation, we'd check if doctor owns this patient
        // For now, we'll just allow access to the path
        next();
        return;
      }

      // Allow read-only access to own schedule
      if (req.path.includes('/schedule/') && req.method === 'GET') {
        next();
        return;
      }

      // Reject other operations
      res.status(403).json({ error: 'Access denied' });
      return;
    }

    if (userRole === 'nurse') {
      // Nurse can manage all appointments
      if (req.path.includes('/appointments/')) {
        next();
        return;
      }

      // Allow read-only access to schedule
      if (req.path.includes('/schedule/') && req.method === 'GET') {
        next();
        return;
      }

      // Reject other operations
      res.status(403).json({ error: 'Access denied' });
      return;
    }

    // Unauthorized role
    res.status(403).json({ error: 'Access denied' });
  } catch (error) {
    res.status(401).json({ error: 'Invalid token' });
  }
}
"}

