{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface Recipe {
  id: number;
  title: string;
  ingredients: string;
}

interface SearchIndex {
  recipe_id: number;
  ingredient: string;
}

const initSql = `
  CREATE TABLE IF NOT EXISTS recipes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    ingredients TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS search_index (
    recipe_id INTEGER,
    ingredient TEXT,
    FOREIGN KEY (recipe_id) REFERENCES recipes(id)
  );

  CREATE INDEX IF NOT EXISTS idx_ingredient ON search_index(ingredient);
`;

db.exec(initSql);

export function insertRecipe(title: string, ingredients: string): number {
  const sql = `INSERT INTO recipes (title, ingredients) VALUES (?, ?)`;
  const result = db.prepare(sql).run(title, ingredients);
  return Number(result.lastInsertRowid);
}

export function getRecipeById(id: number): Recipe | undefined {
  const sql = `SELECT * FROM recipes WHERE id = ?`;
  const result = db.prepare(sql).get(id);
  return result as unknown as Recipe | undefined;
}

export function getAllRecipes(): Recipe[] {
  const sql = `SELECT * FROM recipes`;
  const result = db.prepare(sql).all();
  return result as unknown as Recipe[];
}

export function createSearchIndex(recipeId: number, ingredients: string): void {
  const ingredientList = ingredients
    .split(",")
    .map((i) => i.trim().toLowerCase())
    .filter((i) => i.length > 0);

  const sql = `INSERT INTO search_index (recipe_id, ingredient) VALUES (?, ?)`;
  const stmt = db.prepare(sql);

  for (const ingredient of ingredientList) {
    stmt.run(recipeId, ingredient);
  }
}

export function searchRecipesByIngredient(ingredient: string): Recipe[] {
  const sql = `
    SELECT r.*
    FROM recipes r
    JOIN search_index si ON r.id = si.recipe_id
    WHERE si.ingredient = ?
  `;
  const result = db.prepare(sql).all(ingredient.toLowerCase());
  return result as unknown as Recipe[];
}

// Seed data
if (getAllRecipes().length === 0) {
  const recipe1Id = insertRecipe(
    "Vegetable Stir Fry",
    "broccoli, bell peppers, carrots, soy sauce"
  );
  createSearchIndex(recipe1Id, "broccoli, bell peppers, carrots, soy sauce");

  const recipe2Id = insertRecipe(
    "Pasta with Vegetables",
    "pasta, zucchini, tomatoes, basil"
  );
  createSearchIndex(recipe2Id, "pasta, zucchini, tomatoes, basil");

  const recipe3Id = insertRecipe(
    "Berry Smoothie",
    "strawberries, blueberries, banana, yogurt"
  );
  createSearchIndex(recipe3Id, "strawberries, blueberries, banana, yogurt");

  const recipe4Id = insertRecipe(
    "Chicken Salad",
    "chicken, lettuce, cucumber, olive oil"
  );
  createSearchIndex(recipe4Id, "chicken, lettuce, cucumber, olive oil");

  const recipe5Id = insertRecipe(
    "Oatmeal with Fruit",
    "oats, apples, cinnamon, milk"
  );
  createSearchIndex(recipe5Id, "oats, apples, cinnamon, milk");
}
"}

