  return id ? { id, hallId: 1, date: "2023-05-15", startTime: "10:00", endTime: "12:00", status: "confirmed" } : null;
};

const mockUpdateBooking = async (id: number, updateData: any) => {
  // Simulate updating a booking
  return { id, ...updateData, status: "updated" };
};

const mockCancelBooking = async (id: number) => {
  // Simulate canceling a booking
  return { id, status: "cancelled" };
};

const mockCheckAvailability = async (hallId: number, date: string, startTime: string, endTime: string) => {
  // Simulate checking availability
  return true; // Assume available for demo purposes
};

// Create a new booking
router.post("/bookings", async (req: Request, res: Response) => {
  try {
    const { hallId, date, startTime, endTime } = req.body;

    if (!hallId || !date || !startTime || !endTime) {
      return res.status(400).json({ error: "Missing required fields: hallId, date, startTime, endTime" });
    }

    const isAvailable = await mockCheckAvailability(hallId, date, startTime, endTime);

    if (!isAvailable) {
      return res.status(400).json({ error: "Hall is not available for the selected time slot" });
    }

    const newBooking = await mockCreateBooking(req.body);

    return res.status(201).json(newBooking);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
});

// Get a booking by ID
router.get("/bookings/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid booking ID" });
    }

    const booking = await mockGetBookingById(id);

    if (!booking) {
      return res.status(404).json({ error: "Booking not found" });
    }

    return res.json(booking);
  } catch (error) {
    return res.status(500).json({ error: "Internal server error" });
  }
