    payDate: "2023-06-15",
    status: "pending"
  }
];

// Get all payroll records
router.get("/", (req: Request, res: Response) => {
  res.json(mockPayrollData);
});

// Get payroll record by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const payrollRecord = mockPayrollData.find(p => p.id === id);

  if (!payrollRecord) {
    return res.status(404).json({ error: "Payroll record not found" });
  }

  res.json(payrollRecord);
});

// Create new payroll record
router.post("/", (req: Request, res: Response) => {
  const { employeeId, grossPay, netPay, taxAmount, payDate, status } = req.body;

  // Validate required fields
  if (!employeeId || !grossPay || !netPay || !taxAmount || !payDate || !status) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  // Create new payroll record
  const newPayrollRecord = {
    id: String(mockPayrollData.length + 1),
    employeeId,
    grossPay: Number(grossPay),
    netPay: Number(netPay),
    taxAmount: Number(taxAmount),
    payDate,
    status
  };

  mockPayrollData.push(newPayrollRecord);

  res.status(201).json(newPayrollRecord);
});

// Update payroll record
router.put("/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const { employeeId, grossPay, netPay, taxAmount, payDate, status } = req.body;

  const index = mockPayrollData.findIndex(p => p.id === id);

  if (index === -1) {
    return res.status(404).json({ error: "Payroll record not found" });
  }

  // Validate required fields
  if (!employeeId || !grossPay || !netPay || !taxAmount || !payDate || !status) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  // Update payroll record
  mockPayrollData[index] = {
    id,
    employeeId,
    grossPay: Number(grossPay),
    netPay: Number(netPay),
    taxAmount: Number(taxAmount),
    payDate,
    status
  };

  res.json(mockPayrollData[index]);
});

// Delete payroll record
router.delete("/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const index = mockPayrollData.findIndex(p => p.id === id);

  if (index === -1) {
    return res.status(404).json({ error: "Payroll record not found" });
  }

  mockPayrollData.splice(index, 1);

  res.json({ message: "Payroll record deleted successfully" });
});
"}

