{"code":"import { useEffect, useState } from "react";

interface Doctor {
  id: number;
  name: string;
  specialty: string;
}

interface TimeSlot {
  id: number;
  date: string;
  time: string;
  doctorId: number;
}

interface Appointment {
  id: number;
  date: string;
  time: string;
  doctorId: number;
}

export function AppointmentBookingView() {
  const [doctors, setDoctors] = useState<Doctor[]>([]);
  const [timeSlots, setTimeSlots] = useState<TimeSlot[]>([]);
  const [selectedDoctorId, setSelectedDoctorId] = useState<number | null>(null);
  const [selectedTimeSlotId, setSelectedTimeSlotId] = useState<number | null>(null);
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [doctorsRes, timeSlotsRes, appointmentsRes] = await Promise.all([
          fetch("/api/appointments-api/"),
          fetch("/api/appointments-api/time-slots"),
          fetch("/api/appointments-api/appointments"),
        ]);

        if (!doctorsRes.ok || !timeSlotsRes.ok || !appointmentsRes.ok) {
          throw new Error("Failed to fetch data");
        }

        const doctorsData = await doctorsRes.json();
        const timeSlotsData = await timeSlotsRes.json();
        const appointmentsData = await appointmentsRes.json();

        setDoctors(doctorsData);
        setTimeSlots(timeSlotsData);
        setAppointments(appointmentsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleBookAppointment = async () => {
    if (!selectedDoctorId || !selectedTimeSlotId) return;

    try {
      const response = await fetch("/api/appointments-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          doctorId: selectedDoctorId,
          timeSlotId: selectedTimeSlotId,
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to book appointment");
      }

      // Refresh data after booking
      const [doctorsRes, timeSlotsRes, appointmentsRes] = await Promise.all([
        fetch("/api/appointments-api/"),
        fetch("/api/appointments-api/time-slots"),
        fetch("/api/appointments-api/appointments"),
      ]);

      if (!doctorsRes.ok || !timeSlotsRes.ok || !appointmentsRes.ok) {
        throw new Error("Failed to refresh data");
      }

      const doctorsData = await doctorsRes.json();
      const timeSlotsData = await timeSlotsRes.json();
      const appointmentsData = await appointmentsRes.json();

      setDoctors(doctorsData);
      setTimeSlots(timeSlotsData);
      setAppointments(appointmentsData);

      // Reset selections
      setSelectedDoctorId(null);
      setSelectedTimeSlotId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  const filteredTimeSlots = timeSlots.filter(
    (slot) => slot.doctorId === selectedDoctorId
  );

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Book an Appointment</h1>

      <div style={{ marginBottom: "20px" }}>
        <label htmlFor="doctorSelect" style={{ display: "block", marginBottom: "5px" }}>
          Select a Doctor:
        </label>
        <select
          id="doctorSelect"
          value={selectedDoctorId || ""}
          onChange={(e) => setSelectedDoctorId(Number(e.target.value))}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="">Choose a doctor</option>
          {doctors.map((doctor) => (
            <option key={doctor.id} value={doctor.id}>
              {doctor.name} - {doctor.specialty}
            </option>
          ))}
        </select>
      </div>

      {selectedDoctorId && (
        <div style={{ marginBottom: "20px" }}>
          <label style={{ display: "block", marginBottom: "5px" }}>
            Select a Time Slot:
          </label>
          <div
            style={{
              display: "flex",
              flexWrap: "wrap",
              gap: "10px",
            }}
          >
            {filteredTimeSlots.length > 0 ? (
              filteredTimeSlots.map((slot) => (
                <button
                  key={slot.id}
                  onClick={() => setSelectedTimeSlotId(slot.id)}
                  style={{
                    padding: "10px 15px",
                    backgroundColor: selectedTimeSlotId === slot.id ? "#007bff" : "#f8f9fa",
                    color: selectedTimeSlotId === slot.id ? "white" : "black",
                    border: "1px solid #007bff",
                    borderRadius: "4px",
                    cursor: "pointer",
                    flex: "1 1 calc(50% - 10px)",
                    minWidth: "120px",
                    textAlign: "center",
                  }}
                >
                  {slot.date} at {slot.time}
                </button>
              ))
            ) : (
              <p>No available time slots for this doctor.</p>
            )}
          </div>
        </div>
      )}

      <button
        onClick={handleBookAppointment}
        disabled={!selectedDoctorId || !selectedTimeSlotId}
        style={{
          width: "100%",
          padding: "12px",
          backgroundColor: selectedDoctorId && selectedTimeSlotId ? "#28a745" : "#6c757d",
          color: "white",
          border: "none",
          borderRadius: "4px",
          cursor: selectedDoctorId && selectedTimeSlotId ? "pointer" : "default",
        }}
      >
        Book Appointment
      </button>

      <h2 style={{ marginTop: "30px", textAlign: "center" }}>Your Appointments</h2>
      {appointments.length > 0 ? (
        <table
          style={{
            width: "100%",
            borderCollapse: "collapse",
            marginTop: "10px",
          }}
        >
          <thead>
            <tr>
              <th style={{ border: "1px solid #ddd", padding: "8px" }}>Date</th>
              <th style={{ border: "1px solid #ddd", padding: "8px" }}>Time</th>
              <th style={{ border: "1px solid #ddd", padding: "8px" }}>Doctor</th>
            </tr>
          </thead>
          <tbody>
            {appointments.map((appointment) => {
              const doctor = doctors.find((doc) => doc.id === appointment.doctorId);
              return (
                <tr key={appointment.id}>
                  <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                    {appointment.date}
                  </td>
                  <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                    {appointment.time}
                  </td>
                  <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                    {doctor ? doctor.name : "Unknown Doctor"}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      ) : (
        <p style={{ textAlign: "center", padding: "20px" }}>No appointments booked yet.</p>
      )}
    </div>
  );
}
"}

{"code":"import { useEffect, useState } from "react";

interface AttendanceRecord {
  id: string;
  singerName: string;
  date: string;
  status: "present" | "absent" | "late";
}

export function AttendanceMarkPanel() {
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newRecord, setNewRecord] = useState({
    singerName: "",
    date: "",
    status: "present" as "present" | "absent" | "late"
  });

  useEffect(() => {
    fetchRecords();
  }, []);

  const fetchRecords = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/attendance-records-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch records: ${response.status}`);
      }
      const data = await response.json();
      setRecords(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setNewRecord(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/attendance-records-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newRecord)
      });
      if (!response.ok) {
        throw new Error(`Failed to create record: ${response.status}`);
      }
      // Reset form
      setNewRecord({
        singerName: "",
        date: "",
        status: "present"
      });
      // Refresh data
      await fetchRecords();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Attendance Mark Panel</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2 style={{ marginTop: "0" }}>Mark New Attendance</h2>
        <div style={{ marginBottom: "10px" }}>
          <label>Singer Name:</label>
          <input
            type="text"
            name="singerName"
            value={newRecord.singerName}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            required
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label>Date:</label>
          <input
            type="date"
            name="date"
            value={newRecord.date}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            required
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <label>Status:</label>
          <select
            name="status"
            value={newRecord.status}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", marginTop: "5px" }}
          >
            <option value="present">Present</option>
            <option value="absent">Absent</option>
            <option value="late">Late</option>
          </select>
        </div>
        <button type="submit" style={{ backgroundColor: "#007bff", color: "white", border: "none", padding: "10px 20px", borderRadius: "4px", cursor: "pointer" }}>
          Mark Attendance
        </button>
      </form>

      <h2>Attendance Records</h2>
      {records.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>No attendance records found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {records.map(record => (
            <div key={record.id} style={{ border: "1px solid #ccc", padding: "15px", borderRadius: "8px" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <strong>{record.singerName}</strong>
                  <br />
                  Date: {record.date}
                  <br />
                  Status: {record.status.charAt(0).toUpperCase() + record.status.slice(1)}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

