{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock data structures to simulate database operations
const requests = new Map<string, any>();
const nextId = 1;

// Helper to generate a unique ID
const generateId = () => {
  return `req_${Date.now()}_${Math.floor(Math.random() * 1000)}`;
};

// GET /certificates - List all certificate requests
router.get("/certificates", (req: Request, res: Response) => {
  const requestList = Array.from(requests.values());
  return res.json(requestList);
});

// GET /certificates/:id - Get a specific certificate request by ID
router.get("/certificates/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const request = requests.get(id);

  if (!request) {
    return res.status(404).json({ error: "Certificate request not found" });
  }

  return res.json(request);
});

// POST /certificates - Create a new certificate request
router.post("/certificates", (req: Request, res: Response) => {
  const { studentName, course, duration } = req.body;

  // Validate required fields
  if (!studentName || !course || !duration) {
    return res.status(400).json({ error: "Missing required fields: studentName, course, duration" });
  }

  const id = generateId();
  const newRequest = {
    id,
    studentName,
    course,
    duration,
    status: "pending",
    createdAt: new Date().toISOString()
  };

  requests.set(id, newRequest);

  return res.status(201).json(newRequest);
});

// PUT /certificates/:id/approve - Approve a certificate request
router.put("/certificates/:id/approve", (req: Request, res: Response) => {
  const id = req.params.id;
  const request = requests.get(id);

  if (!request) {
    return res.status(404).json({ error: "Certificate request not found" });
  }

  request.status = "approved";
  request.approvedAt = new Date().toISOString();

  return res.json(request);
});

// PUT /certificates/:id/reject - Reject a certificate request
router.put("/certificates/:id/reject", (req: Request, res: Response) => {
  const id = req.params.id;
  const request = requests.get(id);

  if (!request) {
    return res.status(404).json({ error: "Certificate request not found" });
  }

  request.status = "rejected";
  request.rejectedAt = new Date().toISOString();

  return res.json(request);
});

// DELETE /certificates/:id - Delete a certificate request
router.delete("/certificates/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const request = requests.get(id);

  if (!request) {
    return res.status(404).json({ error: "Certificate request not found" });
  }

  requests.delete(id);

  return res.json({ message: "Certificate request deleted successfully" });
});
"}

