{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process POST requests to /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT secret is set
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(500).json({ error: "Internal server error" });
    return;
  }

  // For demonstration purposes, we'll just check if the request has a valid token
  // In a real implementation, we would decode and verify the JWT signature
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  const token = authHeader.substring(7);

  // Simple verification - in practice, this would involve HMAC-SHA256 verification
  try {
    // This is a placeholder - actual JWT verification would be more complex
    const expectedToken = createHmac("sha256", jwtSecret).update("valid-token").digest("hex");
    const tokenBuffer = Buffer.from(token, "utf8");
    const expectedBuffer = Buffer.from(expectedToken, "utf8");

    if (tokenBuffer.length !== expectedBuffer.length) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }

    const isValid = timingSafeEqual(tokenBuffer, expectedBuffer);

    if (!isValid) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
  } catch (error) {
    res.status(401).json({ error: "Unauthorized" });
    return;
  }

  next();
}
"}

{"code":"import { useEffect, useState } from "react";

interface GardenPlan {
  id: string;
  name: string;
  description: string;
  createdAt: string;
}

export function GardenPlans() {
  const [plans, setPlans] = useState<GardenPlan[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);

  useEffect(() => {
    fetchPlans();
  }, []);

  const fetchPlans = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/garden-plan-api/");
      if (!response.ok) {
        throw new Error(`Failed to fetch plans: ${response.status}`);
      }
      const data = await response.json();
      setPlans(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;

    try {
      const response = await fetch("/api/garden-plan-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name, description }),
      });

      if (!response.ok) {
        throw new Error(`Failed to create plan: ${response.status}`);
      }

      setName("");
      setDescription("");
      await fetchPlans();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleUpdate = async (id: string, updatedData: Partial<GardenPlan>) => {
    try {
      const response = await fetch(`/api/garden-plan-api/${id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(updatedData),
      });

      if (!response.ok) {
        throw new Error(`Failed to update plan: ${response.status}`);
      }

      setEditingId(null);
      await fetchPlans();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/garden-plan-api/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        throw new Error(`Failed to delete plan: ${response.status}`);
      }

      await fetchPlans();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Garden Plans</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <h2>Create New Plan</h2>
        <div style={{ marginBottom: "10px" }}>
          <input
            type="text"
            placeholder="Plan Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            style={{ width: "100%", padding: "8px", boxSizing: "border-box" }}
            required
          />
        </div>
        <div style={{ marginBottom: "10px" }}>
          <textarea
            placeholder="Description"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            style={{ width: "100%", padding: "8px", boxSizing: "border-box", height: "80px" }}
          />
        </div>
        <button type="submit" style={{ backgroundColor: "#4CAF50", color: "white", padding: "10px 16px", border: "none", borderRadius: "4px", cursor: "pointer" }}>
          Create Plan
        </button>
      </form>

      <h2>Existing Plans</h2>
      {plans.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No garden plans found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {plans.map((plan) => (
            <div key={plan.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px" }}>
              {editingId === plan.id ? (
                <div>
                  <input
                    type="text"
                    defaultValue={plan.name}
                    onChange={(e) => {
                      const newName = e.target.value;
                      handleUpdate(plan.id, { name: newName });
                    }}
                    style={{ width: "100%", marginBottom: "10px", padding: "8px", boxSizing: "border-box" }}
                  />
                  <textarea
                    defaultValue={plan.description}
                    onChange={(e) => {
                      const newDesc = e.target.value;
                      handleUpdate(plan.id, { description: newDesc });
                    }}
                    style={{ width: "100%", marginBottom: "10px", padding: "8px", boxSizing: "border-box", height: "80px" }}
                  />
                  <button 
                    onClick={() => setEditingId(null)}
                    style={{ backgroundColor: "#f44336", color: "white", padding: "8px 12px", border: "none", borderRadius: "4px", cursor: "pointer", marginRight: "10px" }}
                  >
                    Cancel
                  </button>
                </div>
              ) : (
                <>
                  <h3 style={{ margin: "0 0 10px 0" }}>{plan.name}</h3>
                  <p style={{ margin: "0 0 10px 0" }}>{plan.description}</p>
                  <small style={{ color: "#666" }}>
                    Created: {new Date(plan.createdAt).toLocaleDateString()}
                  </small>
                  <div style={{ marginTop: "10px", display: "flex", gap: "10px" }}>
                    <button 
                      onClick={() => setEditingId(plan.id)}
                      style={{ backgroundColor: "#2196F3", color: "white", padding: "8px 12px", border: "none", borderRadius: "4px", cursor: "pointer" }}
                    >
                      Edit
                    </button>
                    <button 
                      onClick={() => handleDelete(plan.id)}
                      style={{ backgroundColor: "#f44336", color: "white", padding: "8px 12px", border: "none", borderRadius: "4px", cursor: "pointer" }}
                    >
                      Delete
                    </button>
                  </div>
                </>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(
  "./community-seed-library.db"
);

export interface HistoryExport {
  id: number;
  requester_email: string;
  export_date: string;
  export_type: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS history_exports (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    requester_email TEXT NOT NULL,
    export_date TEXT NOT NULL,
    export_type TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllHistoryExports(): HistoryExport[] {
  const stmt = db.prepare(
    "SELECT * FROM history_exports ORDER BY export_date DESC"
  );
  return stmt.all() as unknown as HistoryExport[];
}

export function getHistoryExportById(id: number): HistoryExport | undefined {
  const stmt = db.prepare(
    "SELECT * FROM history_exports WHERE id = ?"
  );
  return stmt.get(id) as unknown as HistoryExport | undefined;
}

export function insertHistoryExport(
  requester_email: string,
  export_date: string,
  export_type: string
): number {
  const stmt = db.prepare(
    "INSERT INTO history_exports (requester_email, export_date, export_type) VALUES (?, ?, ?)"
  );
  const result = stmt.run(requester_email, export_date, export_type);
  return Number(result.lastInsertRowid);
}

export function updateHistoryExport(
  id: number,
  requester_email: string,
  export_date: string,
  export_type: string
): number {
  const stmt = db.prepare(
    "UPDATE history_exports SET requester_email = ?, export_date = ?, export_type = ? WHERE id = ?"
  );
  const result = stmt.run(requester_email, export_date, export_type, id);
  return Number(result.changes);
}

export function deleteHistoryExport(id: number): number {
  const stmt = db.prepare("DELETE FROM history_exports WHERE id = ?");
  const result = stmt.run(id);
  return Number(result.changes);
}

