{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only process requests that involve wedding data access
  const isWeddingDataRequest = req.path.startsWith('/api/weddings/') || 
                              req.path.startsWith('/api/vendors/') ||
                              req.path.startsWith('/api/checklists/');

  if (!isWeddingDataRequest) {
    next();
    return;
  }

  // Check if user has proper role
  const userRole = req.headers['x-user-role'] as string | undefined;
  const userId = req.headers['x-user-id'] as string | undefined;

  if (!userRole || !userId) {
    res.status(401).json({ error: 'Unauthorized: Missing role or user ID' });
    return;
  }

  // Validate role permissions
  const allowedRoles = ['admin', 'planner', 'vendor'];
  if (!allowedRoles.includes(userRole)) {
    res.status(403).json({ error: 'Forbidden: Invalid role' });
    return;
  }

  // For vendor-specific endpoints, ensure vendor is authenticated
  if (req.path.startsWith('/api/vendors/') && userRole !== 'vendor') {
    res.status(403).json({ error: 'Forbidden: Vendor access only' });
    return;
  }

  // For planner-specific endpoints, ensure planner is authenticated
  if (req.path.startsWith('/api/checklists/') && userRole !== 'planner') {
    res.status(403).json({ error: 'Forbidden: Planner access only' });
    return;
  }

  // For admin-only endpoints
  if (req.path.startsWith('/api/weddings/') && userRole !== 'admin') {
    res.status(403).json({ error: 'Forbidden: Admin access only' });
    return;
  }

  // If we reach here, user has appropriate permissions
  next();
}
"}

