{"code":"import { useEffect, useState } from "react";

interface Option {
  id: string;
  text: string;
  voteCount: number;
}

interface Poll {
  id: string;
  question: string;
  options: Option[];
  totalVotes: number;
}

export function PollDetailPage({ pollId }: { pollId: string }) {
  const [poll, setPoll] = useState<Poll | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchPoll = async () => {
      try {
        const response = await fetch(`/api/polls/${pollId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch poll: ${response.status}`);
        }
        const data = await response.json();
        setPoll(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchPoll();
  }, [pollId]);

  const handleVote = async (optionId: string) => {
    try {
      const response = await fetch(`/api/polls/${pollId}/votes`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ optionId }),
      });

      if (!response.ok) {
        throw new Error("Failed to cast vote");
      }

      // Refresh poll data after voting
      const updatedResponse = await fetch(`/api/polls/${pollId}`);
      if (!updatedResponse.ok) {
        throw new Error("Failed to refresh poll data");
      }
      const updatedData = await updatedResponse.json();
      setPoll(updatedData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  if (!poll) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        Poll not found.
      </div>
    );
  }

  const totalVotes = poll.totalVotes || 0;

  return (
    <div
      style={{
        maxWidth: "600px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>{poll.question}</h1>
      <div style={{ marginBottom: "20px" }}>
        <p style={{ textAlign: "center", color: "#666" }}>
          Total Votes: {totalVotes}
        </p>
      </div>
      <div>
        {poll.options.map((option) => {
          const percentage = totalVotes > 0 ? Math.round((option.voteCount / totalVotes) * 100) : 0;
          return (
            <div key={option.id} style={{ marginBottom: "15px" }}>
              <div style={{ display: "flex", alignItems: "center", marginBottom: "5px" }}>
                <span style={{ width: "40px", textAlign: "right", marginRight: "10px" }}>
                  {percentage}%
                </span>
                <div style={{ flex: 1, height: "20px", backgroundColor: "#e0e0e0", borderRadius: "10px", overflow: "hidden" }}>
                  <div
                    style={{
                      width: `${percentage}%`,
                      height: "100%",
                      backgroundColor: "#007bff",
                      borderRadius: "10px",
                    }}
                  />
                </div>
              </div>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <span>{option.text}</span>
                <button
                  onClick={() => handleVote(option.id)}
                  disabled={totalVotes === 0}
                  style={{
                    backgroundColor: "#007bff",
                    color: "white",
                    border: "none",
                    borderRadius: "5px",
                    padding: "5px 10px",
                    cursor: totalVotes === 0 ? "default" : "pointer",
                  }}
                >
                  Vote
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock session handling - in a real app, this would be replaced with actual session management
const sessions: Record<string, { userId: string; role: string }> = {};
const users: Record<string, { email: string; password: string; role: string }> = {
  "member@example.com": { email: "member@example.com", password: "password123", role: "member" },
  "staff@example.com": { email: "staff@example.com", password: "password123", role: "staff" }
};

// Register a new user
router.post("/register", (req: Request, res: Response) => {
  const { email, password, role } = req.body;

  if (!email || !password || !role) {
    return res.status(400).json({ error: "Email, password, and role are required" });
  }

  if (users[email]) {
    return res.status(400).json({ error: "User already exists" });
  }

  users[email] = { email, password, role };
  return res.status(201).json({ message: "User registered successfully" });
});

// Login a user
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  const user = users[email];
  if (!user || user.password !== password) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Create a mock session
  const sessionId = Math.random().toString(36).substring(2, 15);
  sessions[sessionId] = { userId: email, role: user.role };

  return res.json({ sessionId, role: user.role });
});

// Middleware to verify session
const authenticate = (req: Request, res: Response, next: Function) => {
  const sessionId = req.headers.authorization?.split(" ")[1];
  if (!sessionId || !sessions[sessionId]) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  (req as any).session = sessions[sessionId];
  next();
};

// Middleware to verify member role
const requireMember = (req: Request, res: Response, next: Function) => {
  const session = (req as any).session;
  if (!session || session.role !== "member") {
    return res.status(403).json({ error: "Access denied: Member role required" });
  }
  next();
};

// Middleware to verify staff role
const requireStaff = (req: Request, res: Response, next: Function) => {
  const session = (req as any).session;
  if (!session || session.role !== "staff") {
    return res.status(403).json({ error: "Access denied: Staff role required" });
  }
  next();
};

// Get user profile (protected route)
router.get("/profile", authenticate, (req: Request, res: Response) => {
  const session = (req as any).session;
  const user = users[session.userId];

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  return res.json({ email: user.email, role: user.role });
});

// Update user profile (protected route)
router.put("/profile", authenticate, (req: Request, res: Response) => {
  const session = (req as any).session;
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  const user = users[session.userId];
  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  user.email = email;
  user.password = password;

  return res.json({ message: "Profile updated successfully" });
});

// Get all members (staff only)
router.get("/members", authenticate, requireStaff, (req: Request, res: Response) => {
  const members = Object.entries(users)
    .filter(([_, user]) => user.role === "member")
    .map(([email, user]) => ({ email, role: user.role }));

  return res.json(members);
});

// Get all staff (staff only)
router.get("/staff", authenticate, requireStaff, (req: Request, res: Response) => {
  const staff = Object.entries(users)
    .filter(([_, user]) => user.role === "staff")
    .map(([email, user]) => ({ email, role: user.role }));

  return res.json(staff);
});
"}

{"code":"import { useEffect, useState } from "react";

interface LoanRecord {
  id: number;
  userId: number;
  equipmentId: number;
  equipmentName: string;
  userName: string;
  loanDate: string;
  returnDate: string | null;
  status: "active" | "returned";
}

export function LendingRecordsPage() {
  const [records, setRecords] = useState<LoanRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [filterStatus, setFilterStatus] = useState<"all" | "active" | "returned">("all");

  useEffect(() => {
    fetchLendingRecords();
  }, []);

  const fetchLendingRecords = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/loans`);
      if (!response.ok) {
        throw new Error(`Failed to fetch records: ${response.status}`);
      }
      const data = await response.json();
      setRecords(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleReturn = async (loanId: number) => {
    try {
      const response = await fetch(`/api/loans/${loanId}/return`, {
        method: "PUT",
      });
      if (!response.ok) {
        throw new Error(`Failed to return item: ${response.status}`);
      }
      // Refresh the records after returning
      await fetchLendingRecords();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const filteredRecords = records.filter(record => {
    const matchesSearch = 
      record.userName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      record.equipmentName.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = filterStatus === "all" || record.status === filterStatus;
    return matchesSearch && matchesStatus;
  });

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Equipment Lending Records</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search by user or equipment..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        />

        <select
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value as "all" | "active" | "returned")}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="all">All Statuses</option>
          <option value="active">Active</option>
          <option value="returned">Returned</option>
        </select>
      </div>

      {filteredRecords.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No lending records found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {filteredRecords.map(record => (
            <div 
              key={record.id} 
              style={{ 
                border: "1px solid #ddd", 
                borderRadius: "8px", 
                padding: "15px", 
                backgroundColor: record.status === "returned" ? "#f0f8f0" : "#fff8f0" 
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <h3>{record.equipmentName}</h3>
                  <p><strong>Borrowed by:</strong> {record.userName}</p>
                  <p><strong>Loan Date:</strong> {new Date(record.loanDate).toLocaleDateString()}</p>
                  {record.returnDate && (
                    <p><strong>Return Date:</strong> {new Date(record.returnDate).toLocaleDateString()}</p>
                  )}
                  <p><strong>Status:</strong> <span style={{ textTransform: "capitalize" }}>{record.status}</span></p>
                </div>

                {record.status === "active" && (
                  <button 
                    onClick={() => handleReturn(record.id)}
                    style={{ 
                      backgroundColor: "#4CAF50", 
                      color: "white", 
                      border: "none", 
                      padding: "8px 16px", 
                      borderRadius: "4px", 
                      cursor: "pointer" 
                    }}
                  >
                    Mark as Returned
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface TemplateRow {
  id: number;
  name: string;
  description: string;
  checklist_items: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS templates (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    description TEXT,
    checklist_items TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllTemplates(): TemplateRow[] {
  const stmt = db.prepare(`SELECT * FROM templates`);
  return stmt.all() as unknown as TemplateRow[];
}

export function getTemplateById(id: number): TemplateRow | undefined {
  const stmt = db.prepare(`SELECT * FROM templates WHERE id = ?`);
  return stmt.get(id) as unknown as TemplateRow | undefined;
}

export function insertTemplate(template: Omit<TemplateRow, "id">): number {
  const stmt = db.prepare(
    `INSERT INTO templates (name, description, checklist_items) VALUES (?, ?, ?)`
  );
  const result = stmt.run(template.name, template.description, template.checklist_items);
  return Number(result.lastInsertRowid);
}

export function updateTemplate(
  id: number,
  template: Partial<Omit<TemplateRow, "id">>
): boolean {
  const updates: string[] = [];
  const values: (string | number)[] = [id];

  if (template.name !== undefined) {
    updates.push("name = ?");
    values.push(template.name);
  }

  if (template.description !== undefined) {
    updates.push("description = ?");
    values.push(template.description);
  }

  if (template.checklist_items !== undefined) {
    updates.push("checklist_items = ?");
    values.push(template.checklist_items);
  }

  if (updates.length === 0) {
    return false;
  }

  const sql = `UPDATE templates SET ${updates.join(", ")} WHERE id = ?`;
  const stmt = db.prepare(sql);
  const result = stmt.run(...values);
  return result.changes > 0;
}

export function deleteTemplate(id: number): boolean {
  const stmt = db.prepare(`DELETE FROM templates WHERE id = ?`);
  const result = stmt.run(id);
  return result.changes > 0;
}

// Sample data initialization
if (getAllTemplates().length === 0) {
  const sampleTemplates = [
    {
      name: "Electrical Safety Check",
      description: "Comprehensive safety inspection for electrical systems",
      checklist_items: "[\"Check circuit breakers\", \"Inspect wiring\", \"Test GFCI outlets\"]"
    },
    {
      name: "Fire Suppression System",
