      checklist_items: "[\"Verify extinguisher pressure\", \"Check hose integrity\", \"Test alarm system\"]"
    },
    {
      name: "Emergency Evacuation Plan",
      description: "Review and validation of evacuation procedures",
      checklist_items: "[\"Confirm exit routes\", \"Verify emergency lighting\", \"Test communication systems\"]"
    }
  ];

  sampleTemplates.forEach(template => {
    insertTemplate(template);
  });
}
