{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database
const users = [
  {
    id: 1,
    email: "admin@example.com",
    password: "hashed-admin-password",
    role: "admin"
  },
  {
    id: 2,
    email: "user@example.com",
    password: "hashed-user-password",
    role: "user"
  }
];

// Mock session store
const sessions = new Map<string, { userId: number; role: string }>();

// Registration endpoint
router.post("/register", (req: Request, res: Response) => {
  const { email, password, role = "user" } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.email === email);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    email,
    password,
    role
  };

  users.push(newUser);

  return res.status(201).json({
    id: newUser.id,
    email: newUser.email,
    role: newUser.role
  });
});

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  // Find user
  const user = users.find(u => u.email === email && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Generate session token
  const token = Math.random().toString(36).substring(2, 15);
  sessions.set(token, { userId: user.id, role: user.role });

  return res.json({ token, role: user.role });
});

// Logout endpoint
router.post("/logout", (req: Request, res: Response) => {
  const token = req.header("Authorization")?.replace("Bearer ", "");

  if (!token) {
    return res.status(400).json({ error: "No token provided" });
  }

  if (!sessions.has(token)) {
    return res.status(401).json({ error: "Invalid token" });
  }

  sessions.delete(token);

  return res.json({ message: "Logged out successfully" });
});

// Middleware to verify session
const authenticate = (req: Request, res: Response, next: Function) => {
  const token = req.header("Authorization")?.replace("Bearer ", "");

  if (!token) {
    return res.status(401).json({ error: "No token provided" });
  }

  const session = sessions.get(token);
  if (!session) {
    return res.status(401).json({ error: "Invalid token" });
  }

  (req as any).user = session;
  next();
};

// Middleware to verify admin role
const requireAdmin = (req: Request, res: Response, next: Function) => {
  const user = (req as any).user;

  if (!user || user.role !== "admin") {
    return res.status(403).json({ error: "Access denied. Admin required." });
  }

  next();
};

// Protected route example
router.get("/profile", authenticate, (req: Request, res: Response) => {
  const user = (req as any).user;
  return res.json({ id: user.userId, role: user.role });
});

// Admin-only route example
router.get("/admin", authenticate, requireAdmin, (req: Request, res: Response) => {
  return res.json({ message: "Welcome, admin!" });
});
"}

