export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only validate POST, PUT, PATCH requests to /requests and /inventory routes
  const isRequestRoute = req.path.startsWith('/requests');
  const isInventoryRoute = req.path.startsWith('/inventory');

  if ((req.method === 'POST' || req.method === 'PUT' || req.method === 'PATCH') && 
      (isRequestRoute || isInventoryRoute)) {
    validateInputData(req);
  }

  next();
}

function validateInputData(req: Request): void {
  // Validate request body for potential injection attacks
  if (req.body) {
    validateObject(req.body);
  }

  // Validate query parameters
  if (req.query) {
    validateObject(req.query);
  }

  // Validate URL parameters
  if (req.params) {
    validateObject(req.params);
  }
}

function validateObject(obj: Record<string, any>): void {
  for (const [key, value] of Object.entries(obj)) {
    if (typeof value === 'string') {
      // Check for common injection patterns
      if (value.includes('\\') || value.includes('\\\"') || value.includes("\\'") || 
          value.includes('<') || value.includes('>') || value.includes('&')) {
        // In a real implementation, we might want to reject these
        // For now, we just log or handle according to requirements
        // This is a simplified validation - in practice, more robust sanitization
        // would be needed based on specific use cases
      }
    } else if (typeof value === 'object' && value !== null) {
      validateObject(value);
    }
  }
}
