  }

  res.json(record);
});

// Create a new billing record
router.post("/", (req: Request, res: Response) => {
  const { sessionId, amount, status, timestamp } = req.body;

  // Validate required fields
  if (!sessionId || !amount || !status || !timestamp) {
    return res.status(400).json({ error: "Missing required fields: sessionId, amount, status, timestamp" });
  }

  // Validate amount is a number
  if (typeof amount !== "number") {
    return res.status(400).json({ error: "Amount must be a number" });
  }

  // Create new record
  const newRecord = {
    id: String(mockBillingRecords.length + 1),
    sessionId,
    amount,
    status,
    timestamp
  };

  mockBillingRecords.push(newRecord);

  res.status(201).json(newRecord);
});

// Update a billing record
router.put("/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const { sessionId, amount, status, timestamp } = req.body;

  const recordIndex = mockBillingRecords.findIndex(r => r.id === id);

  if (recordIndex === -1) {
    return res.status(404).json({ error: "Billing record not found" });
  }

  // Validate required fields
  if (!sessionId || !amount || !status || !timestamp) {
    return res.status(400).json({ error: "Missing required fields: sessionId, amount, status, timestamp" });
  }

  // Validate amount is a number
  if (typeof amount !== "number") {
    return res.status(400).json({ error: "Amount must be a number" });
  }

  // Update record
  const updatedRecord = {
    id,
    sessionId,
    amount,
    status,
    timestamp
  };

  mockBillingRecords[recordIndex] = updatedRecord;

  res.json(updatedRecord);
});

// Delete a billing record
router.delete("/:id", (req: Request, res: Response) => {
  const id = req.params.id;
  const recordIndex = mockBillingRecords.findIndex(r => r.id === id);

  if (recordIndex === -1) {
