{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only check authentication for POST /login endpoint
  if (req.method !== "POST" || req.path !== "/login") {
    next();
    return;
  }

  // Check if JWT_SECRET is set
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  // In a real implementation, we would verify the JWT signature here
  // For now, we'll just simulate a valid token verification
  const token = req.headers.authorization?.split(" ")[1];
  if (!token) {
    res.status(401).json({ error: "Missing token" });
    return;
  }

  // Simulate token verification - in reality, this would verify HMAC-SHA256 signature
  try {
    const expectedSignature = createHmac("sha256", secret)
      .update(token.split(".")[0] + "." + token.split(".")[1])
      .digest();

    const actualSignature = Buffer.from(token.split(".")[2], "base64");

    if (actualSignature.length !== expectedSignature.length) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }

    const isValid = timingSafeEqual(expectedSignature, actualSignature);

    if (!isValid) {
      res.status(401).json({ error: "Invalid token" });
      return;
    }
  } catch (err) {
    res.status(401).json({ error: "Invalid token" });
    return;
  }

  next();
}
"}

{"code":"import { Router, type Request, type Response } from "express";
import {
  db,
  deleteTimesheet,
  getAllTimesheets,
  getTimesheetById,
  insertTimesheet,
  updateTimesheet
} from "../db/timesheets-table";

export const router = Router();

// Get all timesheets for the logged-in user
router.get("/", (req: Request, res: Response) => {
  const userId = Number(req.query.userId);

  if (isNaN(userId)) {
    return res.status(400).json({ error: "Invalid user ID" });
  }

  const timesheets = getAllTimesheets().filter(ts => ts.user_id === userId);

  res.json(timesheets);
});

// Get a specific timesheet by ID
router.get("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid timesheet ID" });
  }

  const timesheet = getTimesheetById(id);

  if (!timesheet) {
    return res.status(404).json({ error: "Timesheet not found" });
  }

  res.json(timesheet);
});

// Create a new timesheet entry
router.post("/", (req: Request, res: Response) => {
  const { userId, date, client, task, hours } = req.body;

  if (!userId || !date || !client || !task || hours === undefined) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const newId = insertTimesheet(userId, date, client, task, hours);

  res.status(201).json({ id: newId });
});

// Update an existing timesheet entry
router.put("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { userId, date, client, task, hours } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid timesheet ID" });
  }

  if (!userId || !date || !client || !task || hours === undefined) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const existingTimesheet = getTimesheetById(id);

  if (!existingTimesheet) {
    return res.status(404).json({ error: "Timesheet not found" });
  }

  updateTimesheet(id, userId, date, client, task, hours);

  res.json({ message: "Timesheet updated successfully" });
});

// Delete a timesheet entry
router.delete("/:id", (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid timesheet ID" });
  }

  const existingTimesheet = getTimesheetById(id);

  if (!existingTimesheet) {
    return res.status(404).json({ error: "Timesheet not found" });
  }

  // Check if the user is a supervisor (this is a placeholder)
  // In a real implementation, we'd check the user's role here
  const isSupervisor = false; // Placeholder logic

  if (!isSupervisor) {
    return res.status(403).json({ error: "Insufficient permissions to delete timesheet" });
  }

  deleteTimesheet(id);

  res.json({ message: "Timesheet deleted successfully" });
});
