{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user data storage
const users = [
  { id: 1, email: "customer@example.com", password: "password123", role: "customer" },
  { id: 2, email: "staff@example.com", password: "password123", role: "staff" },
  { id: 3, email: "admin@example.com", password: "password123", role: "admin" }
];

// User registration
router.post("/register", (req: Request, res: Response) => {
  const { email, password, role } = req.body;

  // Validate input
  if (!email || !password || !role) {
    return res.status(400).json({ error: "Email, password, and role are required" });
  }

  // Check if user already exists
  const existingUser = users.find(user => user.email === email);
  if (existingUser) {
    return res.status(400).json({ error: "User already exists" });
  }

  // Create new user
  const newUser = {
    id: users.length + 1,
    email,
    password,
    role
  };

  users.push(newUser);

  return res.status(201).json(newUser);
});

// User login
router.post("/login", (req: Request, res: Response) => {
  const { email, password } = req.body;

  // Validate input
  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  // Find user
  const user = users.find(u => u.email === email && u.password === password);
  if (!user) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Return user info (excluding password)
  const { password: _, ...userWithoutPassword } = user;
  return res.json(userWithoutPassword);
});

// Role-based access control middleware
const authorize = (roles: string[]) => {
  return (req: Request, res: Response, next: Function) => {
    // In a real app, this would check JWT token or session
    // For now, we'll simulate with a mock header
    const userRole = req.headers.role as string || "customer";

    if (!roles.includes(userRole)) {
      return res.status(403).json({ error: "Access denied" });
    }

    next();
  };
};

// Protected route examples
router.get("/customer", authorize(["customer", "staff", "admin"]), (req: Request, res: Response) => {
  return res.json({ message: "Customer dashboard accessible to all" });
});

router.get("/staff", authorize(["staff", "admin"]), (req: Request, res: Response) => {
  return res.json({ message: "Staff dashboard accessible to staff and admin" });
});

router.get("/admin", authorize(["admin"]), (req: Request, res: Response) => {
  return res.json({ message: "Admin dashboard accessible to admin only" });
});
"}

