{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock in-memory storage for users and sessions
const users = new Map<string, { id: string; username: string; password: string; role: string }>();
const sessions = new Map<string, { userId: string; expiresAt: Date }>();

// Helper to generate mock IDs
const generateId = () => Math.random().toString(36).substring(2, 15);

// Registration endpoint
router.post("/register", (req: Request, res: Response) => {
  const { username, password, role = "user" } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Check if user already exists
  for (const user of users.values()) {
    if (user.username === username) {
      return res.status(400).json({ error: "User already exists" });
    }
  }

  // Create new user
  const newUser = {
    id: generateId(),
    username,
    password,
    role,
  };

  users.set(newUser.id, newUser);

  return res.status(201).json({ id: newUser.id, username: newUser.username, role: newUser.role });
});

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  // Find user by username
  let foundUser;
  for (const user of users.values()) {
    if (user.username === username && user.password === password) {
      foundUser = user;
      break;
    }
  }

  if (!foundUser) {
    return res.status(401).json({ error: "Invalid credentials" });
  }

  // Create session
  const sessionId = generateId();
  const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000); // 24 hours
  sessions.set(sessionId, { userId: foundUser.id, expiresAt });

  // Set session cookie
  res.cookie("sessionId", sessionId, { httpOnly: true, maxAge: 24 * 60 * 60 * 1000 });

  return res.json({ message: "Login successful", role: foundUser.role });
});

// Middleware to verify session
const authenticate = (req: Request, res: Response, next: Function) => {
  const sessionId = req.cookies.sessionId;

  if (!sessionId) {
    return res.status(401).json({ error: "No session found" });
  }

  const session = sessions.get(sessionId);

  if (!session) {
    return res.status(401).json({ error: "Invalid session" });
  }

  // Check if session has expired
  if (new Date() > session.expiresAt) {
    sessions.delete(sessionId);
    return res.status(401).json({ error: "Session expired" });
  }

  // Attach user ID to request
  (req as any).userId = session.userId;
  next();
};

// Get current user info
router.get("/me", authenticate, (req: Request, res: Response) => {
  const userId = (req as any).userId;
  const user = users.get(userId);

  if (!user) {
    return res.status(404).json({ error: "User not found" });
  }

  return res.json({ id: user.id, username: user.username, role: user.role });
});

// Logout endpoint
router.post("/logout", authenticate, (req: Request, res: Response) => {
  const sessionId = req.cookies.sessionId;

  if (sessionId) {
    sessions.delete(sessionId);
  }

  res.clearCookie("sessionId");
  return res.json({ message: "Logged out successfully" });
});
"}

{"code":"import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

const MFA_REQUIRED_PATHS = [
  "/login",
  "/dashboard",
  "/settings",
];

const MFA_REQUIRED_METHODS = ["POST", "PUT", "DELETE"];

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip MFA check for non-protected routes/methods
  const isProtectedPath = MFA_REQUIRED_PATHS.some(path =>
    req.path.startsWith(path)
  );

  if (!isProtectedPath || !MFA_REQUIRED_METHODS.includes(req.method)) {
    next();
    return;
  }

  // Check for MFA token in headers
  const authHeader = req.headers["authorization"];
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7); // Remove 'Bearer '

  // Validate JWT signature
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ error: "Server configuration error" });
    return;
  }

  const [payload, signature] = token.split(".");
  if (!payload || !signature) {
    res.status(401).json({ error: "Invalid token format" });
    return;
  }

  // Recreate signature for verification
  const expectedSignature = createHmac("sha256", secret)
    .update(payload)
    .digest("base64url");

  // Use timingSafeEqual to prevent timing attacks
  const isValid = timingSafeEqual(
    Buffer.from(signature, "base64url"),
    Buffer.from(expectedSignature, "base64url")
  );

  if (!isValid) {
    res.status(401).json({ error: "Invalid token signature" });
    return;
  }

  // Token is valid, proceed
  next();
}
"}

