{"code":"import { useEffect, useState } from "react";

interface Student {
  id: number;
  name: string;
  email: string;
  grade: string;
}

interface AttendanceRecord {
  id: number;
  studentId: number;
  date: string;
  status: 'present' | 'absent' | 'late';
}

export function StudentListPage() {
  const [students, setStudents] = useState<Student[]>([]);
  const [attendanceRecords, setAttendanceRecords] = useState<AttendanceRecord[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [studentsResponse, attendanceResponse] = await Promise.all([
          fetch('/api/students'),
          fetch('/api/attendance')
        ]);

        if (!studentsResponse.ok || !attendanceResponse.ok) {
          throw new Error('Failed to fetch data');
        }

        const studentsData = await studentsResponse.json();
        const attendanceData = await attendanceResponse.json();

        setStudents(studentsData);
        setAttendanceRecords(attendanceData);
      } catch (err) {
        setError('Failed to load student data');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const filteredStudents = students.filter(student =>
    student.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    student.email.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getAttendanceStatus = (studentId: number) => {
    const today = new Date().toISOString().split('T')[0];
    const record = attendanceRecords.find(
      r => r.studentId === studentId && r.date === today
    );
    return record ? record.status : 'unknown';
  };

  const handleMarkAttendance = async (studentId: number, status: 'present' | 'absent' | 'late') => {
    try {
      const today = new Date().toISOString().split('T')[0];
      const response = await fetch('/api/attendance', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          studentId,
          date: today,
          status
        })
      });

      if (!response.ok) {
        throw new Error('Failed to mark attendance');
      }

      // Refresh data
      const [studentsResponse, attendanceResponse] = await Promise.all([
        fetch('/api/students'),
        fetch('/api/attendance')
      ]);

      if (studentsResponse.ok && attendanceResponse.ok) {
        const studentsData = await studentsResponse.json();
        const attendanceData = await attendanceResponse.json();

        setStudents(studentsData);
        setAttendanceRecords(attendanceData);
      }
    } catch (err) {
      setError('Failed to update attendance');
      console.error(err);
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Student Attendance</h1>

      <input
        type="text"
        placeholder="Search students..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
        style={{
          width: '100%',
          padding: '10px',
          marginBottom: '20px',
          borderRadius: '4px',
          border: '1px solid #ccc'
        }}
      />

      {filteredStudents.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No students found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {filteredStudents.map(student => {
            const attendanceStatus = getAttendanceStatus(student.id);
            return (
              <div 
                key={student.id} 
                style={{
                  border: '1px solid #ddd',
                  borderRadius: '8px',
                  padding: '15px',
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                  flexDirection: 'column',
                  gap: '10px'
                }}
              >
                <div style={{ width: '100%' }}>
                  <h3 style={{ margin: '0 0 5px 0' }}>{student.name}</h3>
                  <p style={{ margin: '0 0 5px 0', color: '#666' }}>{student.email}</p>
                  <p style={{ margin: '0 0 5px 0', color: '#666' }}>Grade: {student.grade}</p>
                </div>

                <div style={{ display: 'flex', gap: '10px', width: '100%', justifyContent: 'center' }}>
                  <button 
                    onClick={() => handleMarkAttendance(student.id, 'present')}
                    style={{
                      backgroundColor: attendanceStatus === 'present' ? '#4CAF50' : '#f0f0f0',
                      color: attendanceStatus === 'present' ? 'white' : 'black',
                      border: 'none',
                      padding: '8px 12px',
                      borderRadius: '4px',
                      cursor: 'pointer'
                    }}
                  >
                    Present
                  </button>
                  <button 
                    onClick={() => handleMarkAttendance(student.id, 'absent')}
                    style={{
                      backgroundColor: attendanceStatus === 'absent' ? '#f44336' : '#f0f0f0',
                      color: attendanceStatus === 'absent' ? 'white' : 'black',
                      border: 'none',
                      padding: '8px 12px',
                      borderRadius: '4px',
                      cursor: 'pointer'
                    }}
                  >
                    Absent
                  </button>
                  <button 
                    onClick={() => handleMarkAttendance(student.id, 'late')}
                    style={{
                      backgroundColor: attendanceStatus === 'late' ? '#ff9800' : '#f0f0f0',
                      color: attendanceStatus === 'late' ? 'white' : 'black',
                      border: 'none',
                      padding: '8px 12px',
                      borderRadius: '4px',
                      cursor: 'pointer'
                    }}
                  >
                    Late
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface UserRow {
  id: number;
  role: "driver" | "regular";
  hashed_password: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    role TEXT NOT NULL CHECK(role IN ('driver', 'regular')),
    hashed_password TEXT NOT NULL
  )
`;

db.exec(createTableSql);

export function getAllUsers(): UserRow[] {
  const stmt = db.prepare("SELECT * FROM users");
  return stmt.all() as unknown as UserRow[];
}

export function getUserById(id: number): UserRow | undefined {
  const stmt = db.prepare("SELECT * FROM users WHERE id = ?");
  return stmt.get(id) as unknown as UserRow | undefined;
}

export function insertUser(role: "driver" | "regular", hashedPassword: string): number {
  const stmt = db.prepare(
    "INSERT INTO users (role, hashed_password) VALUES (?, ?)"
  );
  const result = stmt.run(role, hashedPassword);
  return Number(result.lastInsertRowid);
}

export function updateUser(id: number, role: "driver" | "regular", hashedPassword: string): boolean {
  const stmt = db.prepare(
    "UPDATE users SET role = ?, hashed_password = ? WHERE id = ?"
  );
  const result = stmt.run(role, hashedPassword, id);
  return result.changes > 0;
}

export function deleteUser(id: number): boolean {
  const stmt = db.prepare("DELETE FROM users WHERE id = ?");
  const result = stmt.run(id);
  return result.changes > 0;
}

// Seed data
if (getAllUsers().length === 0) {
  insertUser("driver", "$2b$10$example_hash_1");
  insertUser("regular", "$2b$10$example_hash_2");
  insertUser("driver", "$2b$10$example_hash_3");
  insertUser("regular", "$2b$10$example_hash_4");
  insertUser("regular", "$2b$10$example_hash_5");
}
