  { id: "2", roomId: "B202", userId: "user2", startTime: "2023-05-15T14:00:00Z", endTime: "2023-05-15T15:00:00Z" }
];

const findBookingById = (id: string) => {
  return mockBookings.find(booking => booking.id === id);
};

const isRoomAvailable = (roomId: string, startTime: string, endTime: string) => {
  // Simple mock implementation - in reality this would check actual room availability
  return true;
};

const createBooking = (bookingData: any) => {
  const newBooking = {
    id: `${mockBookings.length + 1}`,
    ...bookingData
  };
  mockBookings.push(newBooking);
  return newBooking;
};

const updateBooking = (id: string, updatedData: any) => {
  const index = mockBookings.findIndex(booking => booking.id === id);
  if (index !== -1) {
    mockBookings[index] = { ...mockBookings[index], ...updatedData };
    return mockBookings[index];
  }
  return null;
};

const deleteBooking = (id: string) => {
  const index = mockBookings.findIndex(booking => booking.id === id);
  if (index !== -1) {
    mockBookings.splice(index, 1);
    return true;
  }
  return false;
};

// List all bookings
router.get("/bookings", (req: Request, res: Response) => {
  res.json(mockBookings);
});

// Get a specific booking by ID
router.get("/bookings/:id", (req: Request, res: Response) => {
  const booking = findBookingById(req.params.id);
  if (!booking) {
    return res.status(404).json({ error: "Booking not found" });
  }
  res.json(booking);
});

// Create a new booking
router.post("/bookings", (req: Request, res: Response) => {
  const { roomId, userId, startTime, endTime } = req.body;

  if (!roomId || !userId || !startTime || !endTime) {
    return res.status(400).json({ error: "Missing required fields: roomId, userId, startTime, endTime" });
  }

  if (!isRoomAvailable(roomId, startTime, endTime)) {
    return res.status(400).json({ error: "Room is not available for the selected time period" });
  }

  const newBooking = createBooking({ roomId, userId, startTime, endTime });
  res.status(201).json(newBooking);
});

// Update a booking
router.put("/bookings/:id", (req: Request, res: Response) => {
  const { roomId, userId, startTime, endTime } = req.body;

  if (!roomId || !userId || !startTime || !endTime) {
    return res.status(400).json({ error: "Missing required fields: roomId, userId, startTime, endTime" });
  }

  const updatedBooking = updateBooking(req.params.id, { roomId, userId, startTime, endTime });
  if (!updatedBooking) {
    return res.status(404).json({ error: "Booking not found" });
  }

  res.json(updatedBooking);
});

// Delete a booking
router.delete("/bookings/:id", (req: Request, res: Response) => {
  const deleted = deleteBooking(req.params.id);
  if (!deleted) {
    return res.status(404).json({ error: "Booking not found" });
  }

  res.json({ message: "Booking deleted successfully" });
});
