{"code":"import { useEffect, useState } from "react";

interface Inspection {
  id: string;
  date: string;
  inspector: string;
  status: 'pending' | 'completed' | 'failed';
}

export function InspectionList() {
  const [inspections, setInspections] = useState<Inspection[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [inspector, setInspector] = useState('');
  const [status, setStatus] = useState('');

  useEffect(() => {
    fetchInspections();
  }, []);

  const fetchInspections = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/inspection-api/');
      if (!response.ok) {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }
      const data = await response.json();
      setInspections(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const filteredInspections = inspections.filter(inspection => {
    const matchesDate = (!startDate || inspection.date >= startDate) &&
                        (!endDate || inspection.date <= endDate);
    const matchesInspector = !inspector || inspection.inspector.toLowerCase().includes(inspector.toLowerCase());
    const matchesStatus = !status || inspection.status === status;

    return matchesDate && matchesInspector && matchesStatus;
  });

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
