};

// GET /inventory - List all items
router.get("/", async (req: Request, res: Response) => {
  try {
    const items = await mockDatabase.getAllItems();
    res.json(items);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch items" });
  }
});

// GET /inventory/:id - Get a specific item by ID
router.get("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }
    const item = await mockDatabase.getItemById(id);
    if (!item) {
      return res.status(404).json({ error: "Item not found" });
    }
    res.json(item);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch item" });
  }
});

// POST /inventory - Create a new item
router.post("/", async (req: Request, res: Response) => {
  try {
    const { name, quantity, price } = req.body;
    if (!name || quantity === undefined || price === undefined) {
      return res.status(400).json({ error: "Name, quantity, and price are required" });
    }
    const newItem = await mockDatabase.createItem({
      name,
      quantity: Number(quantity),
      price: Number(price)
    });
    res.status(201).json(newItem);
  } catch (error) {
    res.status(500).json({ error: "Failed to create item" });
  }
});

// PUT /inventory/:id - Update an existing item
router.put("/:id", async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      return res.status(400).json({ error: "Invalid ID format" });
    }
    const { name, quantity, price } = req.body;
    if (!name || quantity === undefined || price === undefined) {
      return res.status(400).json({ error: "Name, quantity, and price are required" });
    }
    const updatedItem = await mockDatabase.updateItem(id, {
      name,
      quantity: Number(quantity),
      price: Number(price)
    });
    if (!updatedItem) {
      return res.status(404).json({ error: "Item not found" });
    }
    res.json(updatedItem);
  } catch (error) {
    res.status(500).json({ error: "Failed to update item" });
  }
});

