{"code":"import { useEffect, useState } from "react";

interface Birthday {
  id: number;
  name: string;
  date: string;
  notes: string;
}

export function EditBirthdayForm({
  birthdayId,
  onSave,
  onCancel
}: {
  birthdayId: number;
  onSave: () => void;
  onCancel: () => void;
}) {
  const [birthday, setBirthday] = useState<Birthday | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchBirthday() {
      try {
        const response = await fetch(`/api/birthdays/${birthdayId}`);
        if (!response.ok) {
          throw new Error(`Failed to fetch birthday: ${response.status}`);
        }
        const data = await response.json();
        setBirthday(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    }

    fetchBirthday();
  }, [birthdayId]);

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  if (!birthday) return <div style={{ textAlign: "center", padding: "20px" }}>Birthday not found</div>;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = await fetch(`/api/birthdays/${birthdayId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(birthday),
      });

      if (!response.ok) {
        throw new Error(`Failed to update birthday: ${response.status}`);
      }

      onSave();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  return (
    <div style={{ maxWidth: "500px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h2 style={{ textAlign: "center" }}>Edit Birthday</h2>

      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        <div>
          <label htmlFor="name" style={{ display: "block", marginBottom: "5px" }}>Name</label>
          <input
            id="name"
            type="text"
            value={birthday.name}
