{"code":"import { useEffect, useState } from "react";

interface Plant {
  id: string;
  species: string;
  careRequirements: string;
  plantingDetails: string;
}

export function PlantRecords() {
  const [plants, setPlants] = useState<Plant[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    species: "",
    careRequirements: "",
    plantingDetails: ""
  });

  const [editingId, setEditingId] = useState<string | null>(null);

  useEffect(() => {
    fetchPlants();
  }, []);

  const fetchPlants = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/plant-api/plants");
      if (!response.ok) {
        throw new Error(`Failed to fetch plants: ${response.status}`);
      }
      const data = await response.json();
      setPlants(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const url = editingId 
        ? `/api/plant-api/plants/${editingId}`
        : "/api/plant-api/plants";

      const method = editingId ? "PUT" : "POST";

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData)
      });

      if (!response.ok) {
        throw new Error(`Failed to save plant: ${response.status}`);
      }

      // Reset form and refresh data
      setFormData({ species: "", careRequirements: "", plantingDetails: "" });
      setEditingId(null);
      await fetchPlants();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleEdit = (plant: Plant) => {
    setFormData({
      species: plant.species,
      careRequirements: plant.careRequirements,
      plantingDetails: plant.plantingDetails
    });
    setEditingId(plant.id);
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/plant-api/plants/${id}`, {
        method: "DELETE"
      });

      if (!response.ok) {
        throw new Error(`Failed to delete plant: ${response.status}`);
      }

      await fetchPlants();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Plant Records</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <div style={{ marginBottom: "15px" }}>
          <input
            type="text"
            name="species"
            placeholder="Species"
            value={formData.species}
            onChange={handleChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <textarea
            name="careRequirements"
            placeholder="Care Requirements"
            value={formData.careRequirements}
            onChange={handleChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd", minHeight: "60px" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <textarea
            name="plantingDetails"
            placeholder="Planting Details"
            value={formData.plantingDetails}
            onChange={handleChange}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd", minHeight: "60px" }}
            required
          />
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: "#4CAF50", 
            color: "white", 
            padding: "10px 20px", 
            border: "none", 
            borderRadius: "4px", 
            cursor: "pointer" 
          }}
        >
          {editingId ? "Update Plant" : "Add Plant"}
        </button>
      </form>

      <div>
        <h2>Plant List</h2>
        {plants.length === 0 ? (
          <p style={{ textAlign: "center", padding: "20px" }}>No plants found.</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {plants.map(plant => (
              <div 
                key={plant.id} 
                style={{ 
                  border: "1px solid #ccc", 
                  borderRadius: "8px", 
                  padding: "15px", 
                  display: "flex", 
                  flexDirection: "column", 
                  gap: "10px" 
                }}
              >
                <div>
                  <strong>Species:</strong> {plant.species}
                </div>
                <div>
                  <strong>Care Requirements:</strong> {plant.careRequirements}
                </div>
                <div>
                  <strong>Planting Details:</strong> {plant.plantingDetails}
                </div>
                <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
                  <button 
                    onClick={() => handleEdit(plant)}
                    style={{ 
                      backgroundColor: "#2196F3", 
                      color: "white", 
                      padding: "5px 10px", 
                      border: "none", 
                      borderRadius: "4px", 
                      cursor: "pointer" 
                    }}
                  >
                    Edit
                  </button>
                  <button 
                    onClick={() => handleDelete(plant.id)}
                    style={{ 
                      backgroundColor: "#f44336", 
                      color: "white", 
                      padding: "5px 10px", 
                      border: "none", 
                      borderRadius: "4px", 
                      cursor: "pointer" 
                    }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
