{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockDatabase = {
  items: [
    { id: 1, name: "Rice", quantity: 100, unit: "kg" },
    { id: 2, name: "Wheat", quantity: 150, unit: "kg" },
    { id: 3, name: "Sugar", quantity: 75, unit: "kg" }
  ],

  getAllItems(): Promise<any[]> {
    return Promise.resolve(this.items);
  },

  getItemById(id: number): Promise<any> {
    const item = this.items.find(i => i.id === id);
    return Promise.resolve(item);
  },

  createItem(itemData: any): Promise<any> {
    const newItem = {
      id: this.items.length + 1,
      ...itemData
    };
    this.items.push(newItem);
    return Promise.resolve(newItem);
  },

  updateItem(id: number, itemData: any): Promise<any> {
    const index = this.items.findIndex(i => i.id === id);
    if (index === -1) return Promise.reject({ status: 404 });

    this.items[index] = { ...this.items[index], ...itemData };
    return Promise.resolve(this.items[index]);
  },

  deleteItem(id: number): Promise<void> {
    const index = this.items.findIndex(i => i.id === id);
    if (index === -1) return Promise.reject({ status: 404 });

    this.items.splice(index, 1);
    return Promise.resolve();
  }
};

// GET /stock - Get all items
router.get("/stock", async (req: Request, res: Response) => {
  try {
    const items = await mockDatabase.getAllItems();
    res.json(items);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// GET /stock/:id - Get item by ID
router.get("/stock/:id", async (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid ID format" });
  }

  try {
    const item = await mockDatabase.getItemById(id);
    if (!item) {
      return res.status(404).json({ error: "Item not found" });
    }
    res.json(item);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// POST /stock - Create new item
router.post("/stock", async (req: Request, res: Response) => {
  const { name, quantity, unit } = req.body;

  if (!name || !quantity || !unit) {
    return res.status(400).json({ error: "Name, quantity, and unit are required" });
  }

  try {
    const newItem = await mockDatabase.createItem({ name, quantity, unit });
    res.status(201).json(newItem);
  } catch (error) {
    res.status(500).json({ error: "Internal server error" });
  }
});

// PUT /stock/:id - Update existing item
router.put("/stock/:id", async (req: Request, res: Response) => {
  const id = Number(req.params.id);
  const { name, quantity, unit } = req.body;

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid ID format" });
  }

  if (!name || !quantity || !unit) {
    return res.status(400).json({ error: "Name, quantity, and unit are required" });
  }

  try {
    const updatedItem = await mockDatabase.updateItem(id, { name, quantity, unit });
    if (!updatedItem) {
      return res.status(404).json({ error: "Item not found" });
    }
    res.json(updatedItem);
  } catch (error) {
    if ((error as any).status === 404) {
      return res.status(404).json({ error: "Item not found" });
    }
    res.status(500).json({ error: "Internal server error" });
  }
});

// DELETE /stock/:id - Delete item
router.delete("/stock/:id", async (req: Request, res: Response) => {
  const id = Number(req.params.id);

  if (isNaN(id)) {
    return res.status(400).json({ error: "Invalid ID format" });
  }

  try {
    await mockDatabase.deleteItem(id);
    res.json({ message: "Item deleted successfully" });
  } catch (error) {
    if ((error as any).status === 404) {
      return res.status(404).json({ error: "Item not found" });
    }
    res.status(500).json({ error: "Internal server error" });
  }
});
"}

{"code":"import { useEffect, useState } from "react";

interface Shift {
  id: string;
  title: string;
  description: string;
  startTime: string;
  endTime: string;
  claimedBy?: string;
}

interface BoardOwnership {
  id: string;
  shiftId: string;
  memberId: string;
}

export function ShiftClaimBoard() {
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [memberId, setMemberId] = useState("");

  useEffect(() => {
    fetchShifts();
  }, []);

  const fetchShifts = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/shifts-api/shifts');
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setShifts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleClaimShift = async (shiftId: string) => {
    if (!memberId.trim()) {
      setError("Please enter your member ID to claim a shift.");
      return;
    }

    try {
      const response = await fetch(`/api/shifts-api/shifts/${shiftId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ claimedBy: memberId }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      // Refresh the shifts list after claiming
      await fetchShifts();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  if (error) {
    return <div>Error: {error}</div>;
  }

  const gridStyle: React.CSSProperties = {
    display: 'flex',
    flexWrap: 'wrap',
    gap: '1rem',
    justifyContent: 'center',
  };

  const cardStyle: React.CSSProperties = {
    border: '1px solid #ccc',
    borderRadius: '8px',
    padding: '1rem',
    width: '300px',
    boxSizing: 'border-box',
    backgroundColor: '#f9f9f9',
  };

  const buttonStyle: React.CSSProperties = {
    backgroundColor: '#4CAF50',
    color: 'white',
    border: 'none',
    padding: '0.5rem 1rem',
    borderRadius: '4px',
    cursor: 'pointer',
    marginTop: '0.5rem',
  };

  const inputStyle: React.CSSProperties = {
    width: '100%',
    padding: '0.5rem',
    marginBottom: '1rem',
    boxSizing: 'border-box',
  };

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', fontFamily: 'system-ui, sans-serif', padding: '1rem' }}>
      <h1>Shift Claim Board</h1>
      <p>Claim an open shift below:</p>

      <input
        type="text"
        placeholder="Enter your Member ID"
        value={memberId}
        onChange={(e) => setMemberId(e.target.value)}
        style={inputStyle}
      />

      {shifts.length === 0 ? (
        <p>No open shifts available.</p>
      ) : (
        <div style={gridStyle}>
          {shifts
            .filter(shift => !shift.claimedBy)
            .map(shift => (
              <div key={shift.id} style={cardStyle}>
                <h3>{shift.title}</h3>
                <p>{shift.description}</p>
                <p><strong>Start:</strong> {new Date(shift.startTime).toLocaleString()}</p>
                <p><strong>End:</strong> {new Date(shift.endTime).toLocaleString()}</p>
                <button onClick={() => handleClaimShift(shift.id)} style={buttonStyle}>Claim Shift</button>
              </div>
            ))}
        </div>
      )}
    </div>
  );
}
"}

