{"code":"import { useEffect, useState } from "react";

interface Application {
  id: number;
  company: string;
  position: string;
  deadline: string;
  status: string;
}

export function ApplicationList() {
  const [applications, setApplications] = useState<Application[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [sortConfig, setSortConfig] = useState<{ key: keyof Application; direction: 'asc' | 'desc' } | null>(null);

  useEffect(() => {
    fetchApplications();
  }, []);

  const fetchApplications = async () => {
    try {
      const response = await fetch('/api/application-api/applications');
      if (!response.ok) {
        throw new Error('Failed to fetch applications');
      }
      const data = await response.json();
      setApplications(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
      setLoading(false);
    }
  };

  const handleSort = (key: keyof Application) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const sortedApplications = [...applications];
  if (sortConfig !== null) {
    sortedApplications.sort((a, b) => {
      if (a[sortConfig.key] < b[sortConfig.key]) {
        return sortConfig.direction === 'asc' ? -1 : 1;
      }
      if (a[sortConfig.key] > b[sortConfig.key]) {
        return sortConfig.direction === 'asc' ? 1 : -1;
      }
      return 0;
    });
  }

  const filteredApplications = sortedApplications.filter(app =>
    app.company.toLowerCase().includes(searchTerm.toLowerCase()) ||
    app.position.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getSortIcon = (key: keyof Application) => {
    if (!sortConfig || sortConfig.key !== key) return ' ↕️';
    return sortConfig.direction === 'asc' ? ' ↑' : ' ↓';
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>My Applications</h1>

      <div style={{ marginBottom: '20px' }}>
        <input
          type="text"
          placeholder="Search companies or positions..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: '100%', padding: '10px', borderRadius: '4px', border: '1px solid #ccc' }}
        />
      </div>

      {filteredApplications.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '20px' }}>No applications found.</div>
      ) : (
        <div style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '20px' }}>
            <thead>
              <tr style={{ backgroundColor: '#f2f2f2' }}>
                <th style={{ padding: '12px', border: '1px solid #ddd', cursor: 'pointer' }} onClick={() => handleSort('company')}>
                  Company {getSortIcon('company')}
                </th>
                <th style={{ padding: '12px', border: '1px solid #ddd', cursor: 'pointer' }} onClick={() => handleSort('position')}>
                  Position {getSortIcon('position')}
                </th>
                <th style={{ padding: '12px', border: '1px solid #ddd', cursor: 'pointer' }} onClick={() => handleSort('deadline')}>
                  Deadline {getSortIcon('deadline')}
                </th>
                <th style={{ padding: '12px', border: '1px solid #ddd', cursor: 'pointer' }} onClick={() => handleSort('status')}>
                  Status {getSortIcon('status')}
                </th>
                <th style={{ padding: '12px', border: '1px solid #ddd' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredApplications.map((app) => (
                <tr key={app.id} style={{ borderBottom: '1px solid #ddd' }}>
                  <td style={{ padding: '12px', border: '1px solid #ddd' }}>{app.company}</td>
                  <td style={{ padding: '12px', border: '1px solid #ddd' }}>{app.position}</td>
                  <td style={{ padding: '12px', border: '1px solid #ddd' }}>{app.deadline}</td>
                  <td style={{ padding: '12px', border: '1px solid #ddd' }}>{app.status}</td>
                  <td style={{ padding: '12px', border: '1px solid #ddd' }}>
                    <button 
                      style={{ padding: '6px 12px', marginRight: '8px', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
                      onClick={async () => {
                        if (window.confirm('Are you sure you want to delete this application?')) {
                          const response = await fetch(`/api/application-api/applications/${app.id}`, { method: 'DELETE' });
                          if (response.ok) {
                            fetchApplications();
                          }
                        }
                      }}
                    >
                      Delete
                    </button>
                    <button 
                      style={{ padding: '6px 12px', backgroundColor: '#28a745', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}
                      onClick={async () => {
                        const newStatus = prompt('Enter new status:', app.status);
                        if (newStatus) {
                          const response = await fetch(`/api/application-api/applications/${app.id}`, {
                            method: 'PUT',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({ ...app, status: newStatus }),
                          });
                          if (response.ok) {
                            fetchApplications();
                          }
                        }
                      }}
                    >
                      Edit
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock database functions - in a real app these would connect to a database
const mockDatabase = {
  participants: [
    { id: 1, name: "Alice Smith", email: "alice@example.com", age: 12 },
    { id: 2, name: "Bob Johnson", email: "bob@example.com", age: 11 }
  ],

  getAllParticipants: (): Promise<any[]> => {
    return Promise.resolve(mockDatabase.participants);
  },

  getParticipantById: (id: number): Promise<any | null> => {
    const participant = mockDatabase.participants.find(p => p.id === id) || null;
    return Promise.resolve(participant);
  },

  createParticipant: (participantData: any): Promise<any> => {
    const newId = Math.max(0, ...mockDatabase.participants.map(p => p.id)) + 1;
    const newParticipant = { ...participantData, id: newId };
    mockDatabase.participants.push(newParticipant);
    return Promise.resolve(newParticipant);
  },

  updateParticipant: (id: number, participantData: any): Promise<any | null> => {
    const index = mockDatabase.participants.findIndex(p => p.id === id);
    if (index === -1) return Promise.resolve(null);

    mockDatabase.participants[index] = { ...mockDatabase.participants[index], ...participantData };
    return Promise.resolve(mockDatabase.participants[index]);
  },

  deleteParticipant: (id: number): Promise<boolean> => {
    const initialLength = mockDatabase.participants.length;
    mockDatabase.participants = mockDatabase.participants.filter(p => p.id !== id);
    return Promise.resolve(mockDatabase.participants.length < initialLength);
  }
};

// Validation helper
const validateParticipant = (data: any): string[] => {
  const errors: string[] = [];

  if (!data.name || typeof data.name !== 'string' || data.name.trim().length === 0) {
    errors.push('Name is required and must be a non-empty string');
  }

  if (!data.email || typeof data.email !== 'string' || !data.email.includes('@')) {
    errors.push('Email is required and must be a valid email address');
  }

  if (typeof data.age !== 'number' || data.age <= 0 || data.age > 100) {
    errors.push('Age is required and must be a positive number between 1 and 100');
  }

  return errors;
};

// GET /participants - List all participants
router.get('/participants', async (req: Request, res: Response) => {
  try {
    const participants = await mockDatabase.getAllParticipants();
    res.json(participants);
  } catch (error) {
    res.status(500).json({ error: 'Failed to fetch participants' });
  }
});

// GET /participants/:id - Get a specific participant by ID
router.get('/participants/:id', async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: 'Invalid participant ID' });
    }

    const participant = await mockDatabase.getParticipantById(id);

    if (!participant) {
      return res.status(404).json({ error: 'Participant not found' });
    }

    res.json(participant);
  } catch (error) {
    res.status(500).json({ error: 'Failed to fetch participant' });
  }
});

// POST /participants - Create a new participant
router.post('/participants', async (req: Request, res: Response) => {
  try {
    const errors = validateParticipant(req.body);

    if (errors.length > 0) {
      return res.status(400).json({ errors });
    }

    const newParticipant = await mockDatabase.createParticipant(req.body);
    res.status(201).json(newParticipant);
  } catch (error) {
    res.status(500).json({ error: 'Failed to create participant' });
  }
});

// PUT /participants/:id - Update a participant
router.put('/participants/:id', async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: 'Invalid participant ID' });
    }

    const errors = validateParticipant(req.body);

    if (errors.length > 0) {
      return res.status(400).json({ errors });
    }

    const updatedParticipant = await mockDatabase.updateParticipant(id, req.body);

    if (!updatedParticipant) {
      return res.status(404).json({ error: 'Participant not found' });
    }

    res.json(updatedParticipant);
  } catch (error) {
    res.status(500).json({ error: 'Failed to update participant' });
  }
});

// DELETE /participants/:id - Delete a participant
router.delete('/participants/:id', async (req: Request, res: Response) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      return res.status(400).json({ error: 'Invalid participant ID' });
