{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./dog-park-members.db");

interface Member {
  id: number;
  name: string;
  membership_status: string;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS members (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    membership_status TEXT NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllMembers(): Member[] {
  const stmt = db.prepare("SELECT * FROM members;");
  return stmt.all() as unknown as Member[];
}

export function getMemberById(id: number): Member | undefined {
  const stmt = db.prepare("SELECT * FROM members WHERE id = ?;");
  return stmt.get(id) as unknown as Member | undefined;
}

export function insertMember(name: string, membershipStatus: string): number {
  const stmt = db.prepare(
    "INSERT INTO members (name, membership_status) VALUES (?, ?);"
  );
  const result = stmt.run(name, membershipStatus);
  return Number(result.lastInsertRowid);
}

export function updateMember(
  id: number,
  name: string,
  membershipStatus: string
): void {
  const stmt = db.prepare(
    "UPDATE members SET name = ?, membership_status = ? WHERE id = ?;"
  );
  stmt.run(name, membershipStatus, id);
}

export function deleteMember(id: number): void {
  const stmt = db.prepare("DELETE FROM members WHERE id = ?;");
  stmt.run(id);
}

// Seed the table with sample data if empty
if (getAllMembers().length === 0) {
  insertMember("Buddy", "Active");
  insertMember("Max", "Active");
  insertMember("Luna", "Inactive");
  insertMember("Charlie", "Active");
  insertMember("Bailey", "Inactive");
}
"}

