export const router = Router();

// Mock database functions - in a real app these would be actual database calls
const mockCustomers = [
  { id: "1", name: "John Doe", email: "john@example.com", phone: "123-456-7890" },
  { id: "2", name: "Jane Smith", email: "jane@example.com", phone: "098-765-4321" }
];

const findCustomerById = (id: string) => {
  return mockCustomers.find(customer => customer.id === id);
};

const createCustomer = (customerData: Omit<typeof mockCustomers[0], "id">) => {
  const newCustomer = {
    id: String(mockCustomers.length + 1),
    ...customerData
  };
  mockCustomers.push(newCustomer);
  return newCustomer;
};

const updateCustomer = (id: string, customerData: Partial<Omit<typeof mockCustomers[0], "id">>) => {
  const index = mockCustomers.findIndex(customer => customer.id === id);
  if (index === -1) return null;

  mockCustomers[index] = { ...mockCustomers[index], ...customerData };
  return mockCustomers[index];
};

const deleteCustomer = (id: string) => {
  const index = mockCustomers.findIndex(customer => customer.id === id);
  if (index === -1) return false;

  mockCustomers.splice(index, 1);
  return true;
};

// List all customers
router.get("/", (req: Request, res: Response) => {
  res.json(mockCustomers);
});

// Get a specific customer by ID
router.get("/:id", (req: Request, res: Response) => {
  const customer = findCustomerById(req.params.id);
  if (!customer) {
    return res.status(404).json({ error: "Customer not found" });
  }
  res.json(customer);
});

// Create a new customer
router.post("/", (req: Request, res: Response) => {
  const { name, email, phone } = req.body;

  if (!name || !email || !phone) {
    return res.status(400).json({ error: "Name, email, and phone are required" });
  }

  const newCustomer = createCustomer({ name, email, phone });
  res.status(201).json(newCustomer);
});

// Update a customer
router.put("/:id", (req: Request, res: Response) => {
  const { name, email, phone } = req.body;

  const updatedCustomer = updateCustomer(req.params.id, { name, email, phone });

  if (!updatedCustomer) {
    return res.status(404).json({ error: "Customer not found" });
  }

  res.json(updatedCustomer);
});

// Delete a customer
router.delete("/:id", (req: Request, res: Response) => {
  const deleted = deleteCustomer(req.params.id);

  if (!deleted) {
    return res.status(404).json({ error: "Customer not found" });
  }

  res.json({ message: "Customer deleted successfully" });
});
