    const { lastCleanedBy, lastCleanedAt } = req.body;

    if (typeof lastCleanedBy !== "string" && lastCleanedBy !== null) {
      return res.status(400).json({ error: "lastCleanedBy must be a string or null" });
    }

    if (typeof lastCleanedAt !== "string" && lastCleanedAt !== null) {
      return res.status(400).json({ error: "lastCleanedAt must be a string or null" });
    }

    const newId = insertRoom(lastCleanedBy, lastCleanedAt);

    return res.status(201).json({ id: newId, lastCleanedBy, lastCleanedAt });
  } catch (error) {
    return res.status(500).json({ error: "Failed to create room" });
  }
});

