    if (typeof lastCleanedBy !== "string" && lastCleanedBy !== null) {
      return res.status(400).json({ error: "lastCleanedBy must be a string or null" });
    }

    if (typeof lastCleanedAt !== "string" && lastCleanedAt !== null) {
      return res.status(400).json({ error: "lastCleanedAt must be a string or null" });
    }

    const existingRoom = getRoomById(id);
    if (!existingRoom) {
      return res.status(404).json({ error: "Room not found" });
    }

    updateRoom(id, lastCleanedBy, lastCleanedAt);

    return res.json({ id, lastCleanedBy, lastCleanedAt });
  } catch (error) {
    return res.status(500).json({ error: "Failed to update room" });
  }
});

