    return next();
  }

  // Check if the user is a maintenance staff member
  const isMaintenanceStaff = req.body.isMaintenanceStaff;
  if (!isMaintenanceStaff) {
    res.status(403).send("Access denied: Only maintenance staff can perform fixes.");
    return;
  }

  // If the user is a maintenance staff member, proceed to the next middleware or route handler
  next();
}
