  const rideId = req.params.id;
  const { status, driverId } = req.body;

  if (!rideId) {
    return res.status(400).json({ error: "Ride ID is required" });
  }

  if (!status && !driverId) {
    return res.status(400).json({ error: "Status or driver ID is required" });
  }

  res.json({ message: `Ride ${rideId} updated` });
});

