              <option value="">Select a service</option>
              {mockServices.map(service => (
                <option key={service.id} value={service.id}>
                  {service.name} - {service.duration} min - ${service.price}
                </option>
              ))}
            </select>
          </div>

          <div style={fieldGroupStyle}>
            <label style={labelStyle}>Stylist</label>
            <select 
              style={selectStyle}
              value={selectedStylist || ""}
              onChange={(e) => setSelectedStylist(Number(e.target.value))}
              required
            >
              <option value="">Select a stylist</option>
              {mockStylists.map(stylist => (
                <option key={stylist.id} value={stylist.id}>
                  {stylist.name}
                </option>
              ))}
            </select>
          </div>

          <div style={fieldGroupStyle}>
            <label style={labelStyle}>Time Slot</label>
            <select 
              style={selectStyle}
              value={selectedTimeSlot || ""}
              onChange={(e) => setSelectedTimeSlot(Number(e.target.value))}
              required
              disabled={!selectedService}
            >
              <option value="">Select a time slot</option>
              {getAvailableTimeSlots().map(slot => (
                <option key={slot.id} value={slot.id}>
                  {new Date(slot.dateTime).toLocaleString()}
                </option>
              ))}
            </select>
          </div>

          <button 
            type="submit" 
            style={isSubmitting ? disabledButtonStyle : buttonStyle}
            disabled={isSubmitting || !selectedService || !selectedStylist || !selectedTimeSlot}
          >
            {isSubmitting ? "Booking..." : "Book Appointment"}
          </button>
        </form>
      )}
    </div>
  );
}
"}

