{"code":"import { useEffect, useState } from "react";

interface Subscriber {
  id: string;
  email: string;
  name: string;
}

export function CampaignComposer() {
  const [subscribers, setSubscribers] = useState<Subscriber[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [newSubscriber, setNewSubscriber] = useState({
    email: "",
    name: ""
  });

  useEffect(() => {
    fetchSubscribers();
  }, []);

  const fetchSubscribers = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/mailing-list-engine/subscribers");
      if (!response.ok) {
        throw new Error(`Failed to fetch subscribers: ${response.status}`);
      }
      const data = await response.json();
      setSubscribers(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleAddSubscriber = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/mailing-list-engine/subscribers", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newSubscriber)
      });
      if (!response.ok) {
        throw new Error(`Failed to add subscriber: ${response.status}`);
      }
      setNewSubscriber({ email: "", name: "" });
      fetchSubscribers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleDeleteSubscriber = async (id: string) => {
    try {
      const response = await fetch(`/api/mailing-list-engine/subscribers/${id}`, {
        method: "DELETE"
      });
      if (!response.ok) {
        throw new Error(`Failed to delete subscriber: ${response.status}`);
      }
      fetchSubscribers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const formStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
    marginBottom: "20px"
  };

  const inputStyle: React.CSSProperties = {
    padding: "8px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    fontSize: "16px"
  };

  const buttonStyle: React.CSSProperties = {
    padding: "8px 16px",
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    borderRadius: "4px",
    cursor: "pointer",
    fontSize: "16px"
  };

  const listContainerStyle: React.CSSProperties = {
    display: "flex",
    flexWrap: "wrap",
    gap: "15px"
  };

  const cardStyle: React.CSSProperties = {
    border: "1px solid #ddd",
    borderRadius: "8px",
    padding: "15px",
    width: "250px",
    boxSizing: "border-box"
  };

  const deleteButtonStyle: React.CSSProperties = {
    padding: "4px 8px",
    backgroundColor: "#dc3545",
    color: "white",
    border: "none",
    borderRadius: "4px",
    cursor: "pointer",
    fontSize: "14px"
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1>Campaign Composer</h1>
      <p>Manage your subscriber list and send newsletters.</p>

      <h2>Add New Subscriber</h2>
      <form onSubmit={handleAddSubscriber} style={formStyle}>
        <input
          type="email"
          placeholder="Email address"
          value={newSubscriber.email}
          onChange={(e) => setNewSubscriber({...newSubscriber, email: e.target.value})}
          style={inputStyle}
          required
        />
        <input
          type="text"
          placeholder="Full name"
          value={newSubscriber.name}
          onChange={(e) => setNewSubscriber({...newSubscriber, name: e.target.value})}
          style={inputStyle}
          required
        />
        <button type="submit" style={buttonStyle}>Add Subscriber</button>
