            <div key={subscriber.id} style={cardStyle}>
              <p><strong>{subscriber.name}</strong></p>
              <p>{subscriber.email}</p>
              <button 
                onClick={() => handleDeleteSubscriber(subscriber.id)}
                style={deleteButtonStyle}
