{"code":"import { useEffect, useState } from "react";

interface Bed {
  id: string;
  date: string;
  isAvailable: boolean;
}

interface Booking {
  id: string;
  bedId: string;
  guestName: string;
  bookingDate: string;
}

export function BookingCalendar() {
  const [beds, setBeds] = useState<Bed[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [guestName, setGuestName] = useState("");

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [bedsResponse, bookingsResponse] = await Promise.all([
          fetch("/api/bookings-api/"),
          fetch("/api/bookings-api/"),
        ]);

        if (!bedsResponse.ok || !bookingsResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const bedsData = await bedsResponse.json();
        const bookingsData = await bookingsResponse.json();

        setBeds(bedsData);
        setBookings(bookingsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleBookBed = async (bedId: string) => {
    if (!guestName.trim()) {
      setError("Please enter your name");
      return;
    }

    try {
      const response = await fetch(`/api/bookings-api/`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          bedId,
          guestName,
          bookingDate: new Date().toISOString().split("T")[0],
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to book bed");
      }

      // Refresh data after successful booking
      const [bedsResponse, bookingsResponse] = await Promise.all([
        fetch("/api/bookings-api/"),
        fetch("/api/bookings-api/"),
      ]);

      if (!bedsResponse.ok || !bookingsResponse.ok) {
        throw new Error("Failed to refresh data");
      }

      const bedsData = await bedsResponse.json();
      const bookingsData = await bookingsResponse.json();

      setBeds(bedsData);
      setBookings(bookingsData);
      setGuestName("");
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Book a Bed</h1>

      <div style={{ marginBottom: "20px" }}>
        <label htmlFor="guestName" style={{ display: "block", marginBottom: "5px" }}>
          Your Name:
        </label>
        <input
          id="guestName"
          type="text"
          value={guestName}
          onChange={(e) => setGuestName(e.target.value)}
          style={{
            width: "100%",
            padding: "8px",
            borderRadius: "4px",
            border: "1px solid #ccc",
          }}
        />
      </div>

      <h2 style={{ textAlign: "center" }}>Available Beds</h2>

      {beds.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>
          No beds available.
        </p>
      ) : (
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            gap: "10px",
            justifyContent: "center",
          }}
        >
          {beds.map((bed) => (
            <div
              key={bed.id}
              style={{
                border: "1px solid #ccc",
                borderRadius: "8px",
                padding: "10px",
                minWidth: "150px",
                textAlign: "center",
                backgroundColor: bed.isAvailable ? "#f0fff0" : "#fff0f0",
              }}
            >
              <p><strong>Date:</strong> {bed.date}</p>
              <p><strong>Status:</strong> {bed.isAvailable ? "Available" : "Booked"}</p>
              {bed.isAvailable && (
                <button
                  onClick={() => handleBookBed(bed.id)}
                  style={{
                    backgroundColor: "#007bff",
                    color: "white",
                    border: "none",
                    borderRadius: "4px",
                    padding: "5px 10px",
                    cursor: "pointer",
                    marginTop: "5px",
                  }}
                >
                  Book Now
                </button>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

