{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync("./community-pool.db");

interface Shift {
  id: number;
  date: string;
  lifeguard_id: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS shifts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    date TEXT NOT NULL,
    lifeguard_id INTEGER NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllShifts(): Shift[] {
  const stmt = db.prepare("SELECT * FROM shifts");
  return stmt.all() as unknown as Shift[];
}

export function getShiftById(id: number): Shift | undefined {
  const stmt = db.prepare("SELECT * FROM shifts WHERE id = ?");
  return stmt.get(id) as unknown as Shift | undefined;
}

export function insertShift(date: string, lifeguard_id: number): number {
  const stmt = db.prepare(
    "INSERT INTO shifts (date, lifeguard_id) VALUES (?, ?)"
  );
  const result = stmt.run(date, lifeguard_id);
  return Number(result.lastInsertRowid);
}

export function updateShift(
  id: number,
  date: string,
  lifeguard_id: number
): void {
  const stmt = db.prepare(
    "UPDATE shifts SET date = ?, lifeguard_id = ? WHERE id = ?"
  );
  stmt.run(date, lifeguard_id, id);
}

export function deleteShift(id: number): void {
  const stmt = db.prepare("DELETE FROM shifts WHERE id = ?");
  stmt.run(id);
}

// Seed data
if (getAllShifts().length === 0) {
  insertShift("2023-06-15", 1);
  insertShift("2023-06-16", 2);
  insertShift("2023-06-17", 3);
  insertShift("2023-06-18", 1);
  insertShift("2023-06-19", 2);
}
"}

