{"code":"import { useEffect, useState } from "react";

interface Tool {
  id: number;
  name: string;
  description: string;
}

interface ToolCheckout {
  memberId: number;
  toolId: number;
  checkoutDate: string;
  returnDate: string | null;
}

export function ToolCheckoutWidget() {
  const [tools, setTools] = useState<Tool[]>([]);
  const [checkouts, setCheckouts] = useState<ToolCheckout[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [memberId, setMemberId] = useState("1"); // Default member ID
  const [toolId, setToolId] = useState("1"); // Default tool ID

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [toolsResponse, checkoutsResponse] = await Promise.all([
          fetch('/api/tool-checkouts-api/'),
          fetch('/api/tool-checkouts-api/'),
        ]);

        if (!toolsResponse.ok || !checkoutsResponse.ok) {
          throw new Error('Failed to fetch data');
        }

        const toolsData = await toolsResponse.json();
        const checkoutsData = await checkoutsResponse.json();

        setTools(toolsData);
        setCheckouts(checkoutsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleCheckout = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch(`/api/tool-checkouts-api/`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ memberId: Number(memberId), toolId: Number(toolId) }),
      });

      if (!response.ok) {
        throw new Error('Failed to checkout tool');
      }

      // Refresh data after successful checkout
      const [toolsResponse, checkoutsResponse] = await Promise.all([
        fetch('/api/tool-checkouts-api/'),
        fetch('/api/tool-checkouts-api/'),
      ]);

      if (!toolsResponse.ok || !checkoutsResponse.ok) {
        throw new Error('Failed to refresh data');
      }

      const toolsData = await toolsResponse.json();
      const checkoutsData = await checkoutsResponse.json();

      setTools(toolsData);
      setCheckouts(checkoutsData);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleReturn = async (memberId: number, toolId: number) => {
    try {
      const response = await fetch(`/api/tool-checkouts-api/${memberId}/${toolId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ returnDate: new Date().toISOString() }),
      });

      if (!response.ok) {
        throw new Error('Failed to return tool');
      }

      // Refresh data after successful return
      const [toolsResponse, checkoutsResponse] = await Promise.all([
        fetch('/api/tool-checkouts-api/'),
        fetch('/api/tool-checkouts-api/'),
      ]);

      if (!toolsResponse.ok || !checkoutsResponse.ok) {
        throw new Error('Failed to refresh data');
      }

      const toolsData = await toolsResponse.json();
      const checkoutsData = await checkoutsResponse.json();

      setTools(toolsData);
      setCheckouts(checkoutsData);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleDelete = async (memberId: number, toolId: number) => {
    try {
      const response = await fetch(`/api/tool-checkouts-api/${memberId}/${toolId}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        throw new Error('Failed to delete checkout');
      }

      // Refresh data after successful deletion
      const [toolsResponse, checkoutsResponse] = await Promise.all([
        fetch('/api/tool-checkouts-api/'),
        fetch('/api/tool-checkouts-api/'),
      ]);

      if (!toolsResponse.ok || !checkoutsResponse.ok) {
        throw new Error('Failed to refresh data');
      }

      const toolsData = await toolsResponse.json();
      const checkoutsData = await checkoutsResponse.json();

      setTools(toolsData);
      setCheckouts(checkoutsData);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Tool Checkout</h1>

      <h2>Available Tools</h2>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
        {tools.length > 0 ? (
          tools.map((tool) => (
            <div key={tool.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '10px', width: '200px' }}>
              <h3>{tool.name}</h3>
              <p>{tool.description}</p>
            </div>
          ))
        ) : (
          <p>No tools available.</p>
        )}
      </div>

      <h2>Checked Out Tools</h2>
      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr>
            <th style={{ border: '1px solid #ccc', padding: '8px' }}>Tool Name</th>
            <th style={{ border: '1px solid #ccc', padding: '8px' }}>Member ID</th>
            <th style={{ border: '1px solid #ccc', padding: '8px' }}>Checkout Date</th>
            <th style={{ border: '1px solid #ccc', padding: '8px' }}>Actions</th>
          </tr>
        </thead>
        <tbody>
          {checkouts.length > 0 ? (
            checkouts.map((checkout) => {
              const tool = tools.find(t => t.id === checkout.toolId);
              return (
                <tr key={`${checkout.memberId}-${checkout.toolId}`}>
                  <td style={{ border: '1px solid #ccc', padding: '8px' }}>{tool?.name || 'Unknown Tool'}</td>
                  <td style={{ border: '1px solid #ccc', padding: '8px' }}>{checkout.memberId}</td>
                  <td style={{ border: '1px solid #ccc', padding: '8px' }}>{new Date(checkout.checkoutDate).toLocaleDateString()}</td>
                  <td style={{ border: '1px solid #ccc', padding: '8px' }}>
                    <button 
                      onClick={() => handleReturn(checkout.memberId, checkout.toolId)}
                      style={{ marginRight: '5px', padding: '4px 8px', backgroundColor: '#4CAF50', color: 'white', border: 'none', borderRadius: '4px' }}
                    >
                      Return
                    </button>
                    <button 
                      onClick={() => handleDelete(checkout.memberId, checkout.toolId)}
                      style={{ padding: '4px 8px', backgroundColor: '#f44336', color: 'white', border: 'none', borderRadius: '4px' }}
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              );
            })
          ) : (
            <tr>
              <td colSpan={4} style={{ border: '1px solid #ccc', padding: '8px', textAlign: 'center' }}>
                No checked out tools.
              </td>
            </tr>
          )}
        </tbody>
      </table>

      <h2>Check Out Tool</h2>
      <form onSubmit={handleCheckout} style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
        <label>
          Member ID:
          <input 
            type="number" 
