{"code":"import { DatabaseSync } from "node:sqlite";

export const db = new DatabaseSync(":memory:");

interface DeviceState {
  id: number;
  deviceId: string;
  state: string;
  timestamp: number;
}

const createTableSql = `
  CREATE TABLE IF NOT EXISTS device_states (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    deviceId TEXT NOT NULL,
    state TEXT NOT NULL,
    timestamp INTEGER NOT NULL
  );
`;

db.exec(createTableSql);

export function getAllDeviceStates(): DeviceState[] {
  const stmt = db.prepare(`SELECT * FROM device_states`);
  return stmt.all() as unknown as DeviceState[];
}

export function getDeviceStateById(id: number): DeviceState | undefined {
  const stmt = db.prepare(`SELECT * FROM device_states WHERE id = ?`);
  return stmt.get(id) as unknown as DeviceState | undefined;
}

export function insertDeviceState(
  deviceId: string,
  state: string,
  timestamp: number
): number {
  const stmt = db.prepare(
    `INSERT INTO device_states (deviceId, state, timestamp) VALUES (?, ?, ?)`
  );
  const result = stmt.run(deviceId, state, timestamp);
  return Number(result.lastInsertRowid);
}

export function updateDeviceState(
  id: number,
  deviceId: string,
  state: string,
  timestamp: number
): void {
  const stmt = db.prepare(
    `UPDATE device_states SET deviceId = ?, state = ?, timestamp = ? WHERE id = ?`
  );
  stmt.run(deviceId, state, timestamp, id);
}

export function deleteDeviceState(id: number): void {
  const stmt = db.prepare(`DELETE FROM device_states WHERE id = ?`);
  stmt.run(id);
}

// Seed the table with sample data
if (getAllDeviceStates().length === 0) {
  insertDeviceState("light-1", "on", Date.now() - 3600000);
