{"code":"import { useEffect, useState } from "react";

interface MachineReport {
  id: number;
  machineId: number;
  description: string;
  reportedAt: string;
}

export function MachineReportForm() {
  const [reports, setReports] = useState<MachineReport[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [machineId, setMachineId] = useState("");
  const [description, setDescription] = useState("");

  useEffect(() => {
    fetchReports();
  }, []);

  const fetchReports = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/machine-reports-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch reports: ${response.status}`);
      }
      const data = await response.json();
      setReports(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = await fetch('/api/machine-reports-api/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          machineId: Number(machineId),
          description,
        }),
      });

      if (!response.ok) {
        throw new Error(`Failed to submit report: ${response.status}`);
      }

      // Reset form
      setMachineId("");
      setDescription("");

      // Refresh reports
      await fetchReports();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Report Broken Machine</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="machineId" style={{ display: 'block', marginBottom: '5px' }}>
            Machine ID:
          </label>
          <input
            id="machineId"
            type="number"
            value={machineId}
            onChange={(e) => setMachineId(e.target.value)}
            required
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label htmlFor="description" style={{ display: 'block', marginBottom: '5px' }}>
            Description:
          </label>
          <textarea
            id="description"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            required
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc', minHeight: '100px' }}
          />
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: '#007bff', 
            color: 'white', 
            border: 'none', 
            padding: '10px 20px', 
            borderRadius: '4px', 
            cursor: 'pointer' 
          }}
        >
          Submit Report
        </button>
      </form>

      <h2 style={{ textAlign: 'center' }}>Recent Reports</h2>

      {reports.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No reports found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
          {reports.map(report => (
            <div 
              key={report.id} 
              style={{ 
                padding: '15px', 
                border: '1px solid #ccc', 
                borderRadius: '8px' 
              }}
            >
              <div><strong>Machine ID:</strong> {report.machineId}</div>
              <div><strong>Description:</strong> {report.description}</div>
              <div><strong>Reported At:</strong> {new Date(report.reportedAt).toLocaleString()}</div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"}

{"code":"import { Router, type Request, type Response } from "express";

export const router = Router();

// Mock user database - in a real app this would be a proper database
const users = [
  { id: 1, username: "admin", password: "admin123", role: "manager" },
  { id: 2, username: "staff1", password: "staff123", role: "employee" },
];

// Login endpoint
router.post("/login", (req: Request, res: Response) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({ error: "Username and password are required" });
  }

  const user = users.find(
    (u) => u.username === username && u.password === password
  );

  if (!user) {
    return res
      .status(401)
      .json({ error: "Invalid username or password" });
  }

  // In a real app, we would generate a JWT token here
  return res.json({
    user: { id: user.id, username: user.username, role: user.role },
    token: "mock-jwt-token",
  });
});

// Session validation endpoint
router.get("/validate", (req: Request, res: Response) => {
  // This is a mock implementation
  // In a real app, this would validate the JWT token
  const authHeader = req.headers.authorization;

  if (!authHeader) {
    return res.status(401).json({ error: "No authorization header" });
  }

  // Mock validation - in reality, decode and verify the token
  const token = authHeader.split(" ")[1];
  if (!token || token !== "mock-jwt-token") {
    return res.status(401).json({ error: "Invalid token" });
  }

  return res.json({ valid: true });
});

// Role-based access control middleware
const requireRole = (requiredRole: string) => {
  return (req: Request, res: Response, next: Function) => {
    const authHeader = req.headers.authorization;
    if (!authHeader) {
      return res.status(401).json({ error: "No authorization header" });
    }

    const token = authHeader.split(" ")[1];
    if (!token || token !== "mock-jwt-token") {
      return res.status(401).json({ error: "Invalid token" });
    }

    // Mock user role check
    const user = users[0]; // Mock current user
    if (user.role !== requiredRole) {
      return res
        .status(403)
        .json({ error: "Insufficient permissions" });
    }

    next();
  };
};

// Example protected route for managers only
router.get(
  "/manager-only",
  requireRole("manager"),
  (req: Request, res: Response) => {
    return res.json({ message: "Manager access granted" });
  }
);
"}
